// Hyperreal Worm's-Eye View of a Capsule Apartment Tower
// p5.js 2.x + p5.brush

let camPos, camR, camD, camF, focal, scX, scY;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#eaece9");

  setupCamera();

  // 1. Overcast sky washes & diffuse atmospheric graphite texture
  drawOvercastSky();

  // 2. Build 3D architectural scene graph (core, 5 capsule stacks, pipes, roof mast)
  let scene = buildTowerScene();

  // 3. Batch watercolor washes (putty, faded mint accent, soffit shadows, porthole voids, rust bleeds)
  renderBatchedWashes(scene);

  // 4. Render core concrete structure, service canyons, pipes, and rooftop steelwork
  renderCoreAndPipes(scene);

  // 5. Render capsule modules with relentless technical pen & graphite precision
  renderAllCapsules(scene);

  // 6. Final atmospheric grain and border framing
  drawFinalTouches();

  noLoop();
}

// ============================================================================
// 3D CAMERA & PERSPECTIVE PROJECTION ENGINE
// ============================================================================

function setupCamera() {
  camPos = [36, -106, -14];
  let target = [-6, -8, 124];

  let dx = target[0] - camPos[0];
  let dy = target[1] - camPos[1];
  let dz = target[2] - camPos[2];
  let flen = Math.hypot(dx, dy, dz);
  camF = [dx / flen, dy / flen, dz / flen];

  // Horizontal right vector in world XY plane
  let r0Len = Math.hypot(camF[1], -camF[0]);
  let R0 = [camF[1] / r0Len, -camF[0] / r0Len, 0];

  // Screen-down vector D0 = R0 x F (so +Z projects upward on screen)
  let D0 = [
    R0[1] * camF[2] - R0[2] * camF[1],
    R0[2] * camF[0] - R0[0] * camF[2],
    R0[0] * camF[1] - R0[1] * camF[0]
  ];

  // Roll camera by -21 degrees so vertical vanishing point sits near upper-left (275, -135)
  let rollRad = (-21 * Math.PI) / 180;
  let c = Math.cos(rollRad);
  let s = Math.sin(rollRad);

  camR = [
    R0[0] * c - D0[0] * s,
    R0[1] * c - D0[1] * s,
    R0[2] * c - D0[2] * s
  ];
  camD = [
    R0[0] * s + D0[0] * c,
    R0[1] * s + D0[1] * c,
    R0[2] * s + D0[2] * c
  ];

  focal = 1380;
  scX = 640;
  scY = 735;
}

function project(x, y, z) {
  let vx = x - camPos[0];
  let vy = y - camPos[1];
  let vz = z - camPos[2];

  let rx = vx * camR[0] + vy * camR[1] + vz * camR[2];
  let ry = vx * camD[0] + vy * camD[1] + vz * camD[2];
  let rz = vx * camF[0] + vy * camF[1] + vz * camF[2];

  if (rz < 5) rz = 5;
  return {
    x: scX + (rx / rz) * focal,
    y: scY + (ry / rz) * focal,
    z: rz
  };
}

// ============================================================================
// 2D CONVEX HULL & CYRUS-BECK CLIPPING ENGINE
// ============================================================================

function computeConvexHull2D(pts) {
  let sorted = pts.slice().sort((a, b) => (a.x !== b.x ? a.x - b.x : a.y - b.y));
  let cross = (o, a, b) => (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);

  let lower = [];
  for (let p of sorted) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) <= 0) {
      lower.pop();
    }
    lower.push(p);
  }
  let upper = [];
  for (let i = sorted.length - 1; i >= 0; i--) {
    let p = sorted[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) <= 0) {
      upper.pop();
    }
    upper.push(p);
  }
  upper.pop();
  lower.pop();
  let hull = lower.concat(upper);
  return buildClipPoly(hull);
}

function buildClipPoly(vertices) {
  let cx = 0, cy = 0;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let v of vertices) {
    cx += v.x;
    cy += v.y;
    if (v.x < minX) minX = v.x;
    if (v.y < minY) minY = v.y;
    if (v.x > maxX) maxX = v.x;
    if (v.y > maxY) maxY = v.y;
  }
  cx /= vertices.length;
  cy /= vertices.length;

  let edges = [];
  let n = vertices.length;
  for (let i = 0; i < n; i++) {
    let v1 = vertices[i];
    let v2 = vertices[(i + 1) % n];
    let ex = v2.x - v1.x;
    let ey = v2.y - v1.y;
    let len = Math.hypot(ex, ey) || 1;
    let nx = -ey / len;
    let ny = ex / len;
    if (nx * (v1.x - cx) + ny * (v1.y - cy) < 0) {
      nx = -nx;
      ny = -ny;
    }
    edges.push({ x1: v1.x, y1: v1.y, nx, ny });
  }
  return { vertices, edges, cx, cy, minX, minY, maxX, maxY };
}

// Returns array of visible sub-segments [x1, y1, x2, y2] lying OUTSIDE convex poly
function clipSegOutsidePoly(seg, poly, margin = -0.35) {
  let x1 = seg[0], y1 = seg[1], x2 = seg[2], y2 = seg[3];
  if (Math.max(x1, x2) < poly.minX || Math.min(x1, x2) > poly.maxX ||
      Math.max(y1, y2) < poly.minY || Math.min(y1, y2) > poly.maxY) {
    return [seg];
  }

  let dx = x2 - x1;
  let dy = y2 - y1;
  let tE = 0.0;
  let tL = 1.0;

  for (let i = 0; i < poly.edges.length; i++) {
    let e = poly.edges[i];
    let num = e.nx * (e.x1 - x1) + e.ny * (e.y1 - y1) + margin;
    let den = e.nx * dx + e.ny * dy;

    if (Math.abs(den) < 1e-9) {
      if (num < 0) return [seg]; // Strictly outside this edge
    } else {
      let t = num / den;
      if (den > 0) {
        if (t < tL) tL = t;
      } else {
        if (t > tE) tE = t;
      }
      if (tE >= tL) return [seg];
    }
  }

  let out = [];
  if (tE > 0.002) {
    out.push([x1, y1, x1 + tE * dx, y1 + tE * dy]);
  }
  if (tL < 0.998) {
    out.push([x1 + tL * dx, y1 + tL * dy, x2, y2]);
  }
  return out;
}

// Returns clipped sub-segment [x1, y1, x2, y2] lying INSIDE convex poly, or null
function clipSegInsidePoly(seg, poly, margin = 0.0) {
  let x1 = seg[0], y1 = seg[1], x2 = seg[2], y2 = seg[3];
  if (Math.max(x1, x2) < poly.minX || Math.min(x1, x2) > poly.maxX ||
      Math.max(y1, y2) < poly.minY || Math.min(y1, y2) > poly.maxY) {
    return null;
  }

  let dx = x2 - x1;
  let dy = y2 - y1;
  let tE = 0.0;
  let tL = 1.0;

  for (let i = 0; i < poly.edges.length; i++) {
    let e = poly.edges[i];
    let num = e.nx * (e.x1 - x1) + e.ny * (e.y1 - y1) + margin;
    let den = e.nx * dx + e.ny * dy;

    if (Math.abs(den) < 1e-9) {
      if (num < 0) return null;
    } else {
      let t = num / den;
      if (den > 0) {
        if (t < tL) tL = t;
      } else {
        if (t > tE) tE = t;
      }
      if (tE >= tL) return null;
    }
  }

  return [x1 + tE * dx, y1 + tE * dy, x1 + tL * dx, y1 + tL * dy];
}

// Clip a 2D segment against an array of occluding boxes and draw surviving parts
function drawClippedSeg2D(x1, y1, x2, y2, occluders, insidePoly = null, insidePoly2 = null) {
  // Quick canvas bounds cull
  if ((x1 < -80 && x2 < -80) || (x1 > 1280 && x2 > 1280) ||
      (y1 < -80 && y2 < -80) || (y1 > 1280 && y2 > 1280)) {
    return;
  }

  let seg = [x1, y1, x2, y2];
  if (insidePoly) {
    seg = clipSegInsidePoly(seg, insidePoly, 0.2);
    if (!seg) return;
  }
  if (insidePoly2) {
    seg = clipSegInsidePoly(seg, insidePoly2, 0.2);
    if (!seg) return;
  }

  let segs = [seg];
  if (occluders && occluders.length > 0) {
    for (let i = 0; i < occluders.length; i++) {
      let occ = occluders[i].hull2D;
      let nextSegs = [];
      for (let j = 0; j < segs.length; j++) {
        let res = clipSegOutsidePoly(segs[j], occ, -0.35);
        for (let k = 0; k < res.length; k++) nextSegs.push(res[k]);
      }
      segs = nextSegs;
      if (segs.length === 0) return;
    }
  }

  for (let i = 0; i < segs.length; i++) {
    let s = segs[i];
    let len = Math.hypot(s[2] - s[0], s[3] - s[1]);
    if (len > 0.7) {
      brush.line(s[0], s[1], s[2], s[3]);
    }
  }
}

function drawLine3D(x1, y1, z1, x2, y2, z2, occluders, insidePoly = null, insidePoly2 = null) {
  let p1 = project(x1, y1, z1);
  let p2 = project(x2, y2, z2);
  drawClippedSeg2D(p1.x, p1.y, p2.x, p2.y, occluders, insidePoly, insidePoly2);
}

// Clip a convex polygon against a single half-plane {x1, y1, nx, ny} keeping points where dot(N, P - P1) >= 0
function clipPolyHalfPlane(pts, edge) {
  if (pts.length === 0) return pts;
  let out = [];
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    let da = (a.x - edge.x1) * edge.nx + (a.y - edge.y1) * edge.ny;
    let db = (b.x - edge.x1) * edge.nx + (b.y - edge.y1) * edge.ny;
    if (da >= -0.5) out.push(a);
    if ((da >= -0.5 && db < -0.5) || (da < -0.5 && db >= -0.5)) {
      let t = da / (da - db);
      out.push({ x: a.x + t * (b.x - a.x), y: a.y + t * (b.y - a.y) });
    }
  }
  return out;
}

// Trim a 2D face polygon against closer occluding boxes for clean watercolor washes
function trimFacePolyAgainstOccluders(pts, occluders) {
  let poly = pts.slice();
  for (let i = 0; i < occluders.length; i++) {
    if (poly.length < 3) break;
    let occ = occluders[i].hull2D;
    // Check AABB overlap
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    let cx = 0, cy = 0;
    for (let p of poly) {
      cx += p.x; cy += p.y;
      if (p.x < minX) minX = p.x;
      if (p.y < minY) minY = p.y;
      if (p.x > maxX) maxX = p.x;
      if (p.y > maxY) maxY = p.y;
    }
    if (maxX < occ.minX || minX > occ.maxX || maxY < occ.minY || minY > occ.maxY) continue;
    cx /= poly.length;
    cy /= poly.length;

    // Find the best separating edge of occ that faces toward poly's centroid
    let bestEdge = null;
    let bestDist = -Infinity;
    for (let e of occ.edges) {
      let d = (cx - e.x1) * e.nx + (cy - e.y1) * e.ny;
      if (d > bestDist) {
        bestDist = d;
        bestEdge = e;
      }
    }
    if (bestEdge && bestDist > -15) {
      poly = clipPolyHalfPlane(poly, bestEdge);
    }
  }
  return poly;
}

// ============================================================================
// SCENE GRAPH BUILDER: CORE, 5 CAPSULE COLUMNS, PIPES & ROOFTOP MAST
// ============================================================================

function isBoxInFront(A, B) {
  if (A.x1 <= B.x0 + 0.05 && camPos[0] <= A.x1) return true;
  if (A.x0 >= B.x1 - 0.05 && camPos[0] >= A.x0) return true;
  if (A.y1 <= B.y0 + 0.05 && camPos[1] <= A.y1) return true;
  if (A.y0 >= B.y1 - 0.05 && camPos[1] >= A.y0) return true;
  if (A.z1 <= B.z0 + 0.05 && camPos[2] <= A.z1) return true;
  if (A.z0 >= B.z1 - 0.05 && camPos[2] >= A.z0) return true;
  return false;
}

function createBox3D(x0, x1, y0, y1, z0, z1, props = {}) {
  let corners3D = [
    [x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0],
    [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]
  ];
  let corners2D = corners3D.map(c => project(c[0], c[1], c[2]));
  let hull2D = computeConvexHull2D(corners2D);

  // Screen size estimate
  let screenW = hull2D.maxX - hull2D.minX;
  let screenH = hull2D.maxY - hull2D.minY;
  let onScreen = !(hull2D.maxX < -60 || hull2D.minX > 1260 || hull2D.maxY < -60 || hull2D.minY > 1260);

  return Object.assign({
    x0, x1, y0, y1, z0, z1,
    corners3D, corners2D, hull2D,
    screenW, screenH, onScreen,
    occluders: []
  }, props);
}

function buildTowerScene() {
  let boxes = [];
  let capsules = [];
  let coreBlocks = [];

  // 1. Central Brutalist Concrete Core Shaft (segmented vertically for clean occlusion)
  let coreZStep = 36;
  for (let z = -24; z < 520; z += coreZStep) {
    let cb = createBox3D(-36, 38, -10, 22, z, z + coreZStep - 0.2, {
      type: "core",
      zLevel: z
    });
    if (cb.onScreen) {
      boxes.push(cb);
      coreBlocks.push(cb);
    }
  }

  // Secondary recessed left core wing
  for (let z = -24; z < 490; z += coreZStep) {
    let cb = createBox3D(-68, -36.2, -4, 24, z, z + coreZStep - 0.2, {
      type: "core",
      zLevel: z
    });
    if (cb.onScreen) {
      boxes.push(cb);
      coreBlocks.push(cb);
    }
  }

  // 2. Five Interlocking Columns of Capsules
  // Columns:
  // Col 0 (C): Center-Left Hero Stack (X: -32..0.5, Y: -45..-11)
  // Col 1 (A): Center-Right Hero Stack (X: 5..37.5, Y: -41..-11) - gap at X: 0.5..5 for vertical pipe canyon!
  // Col 2 (B): Far-Right Wing Stack (X: 40..71, Y: -29..0)
  // Col 3 (D): Left Corner Stack (X: -67..-35.5, Y: -37..-6) - gap at X: -35.5..-32 for left pipe canyon!
  // Col 4 (E): Far-Left Silhouette Stack (X: -98..-69, Y: -20..10)

  let colDefs = [
    { id: 0, x0: -32.0, x1: 0.5,   y0: -44.5, y1: -10.5, zStart: -22, zMax: 515, dz: 24.5, h: 21.6, mainFace: "-Y" },
    { id: 1, x0: 5.0,   x1: 37.5,  y0: -40.5, y1: -10.5, zStart: -11, zMax: 505, dz: 24.5, h: 21.6, mainFace: "-Y" },
    { id: 2, x0: 40.5,  x1: 71.5,  y0: -28.5, y1: -0.5,  zStart: -18, zMax: 465, dz: 24.5, h: 21.6, mainFace: "-Y" },
    { id: 3, x0: -66.5, x1: -35.5, y0: -36.5, y1: -5.5,  zStart: -6,  zMax: 495, dz: 24.5, h: 21.6, mainFace: "mixed" },
    { id: 4, x0: -97.0, x1: -69.0, y0: -19.5, y1: 9.5,   zStart: -14, zMax: 440, dz: 24.5, h: 21.6, mainFace: "+X" }
  ];

  let curtainPool = [
    "none", "none", "parted", "none", "blinds_half",
    "left_drawn", "none", "right_drawn", "none", "blinds_low",
    "parted", "none", "none", "left_drawn"
  ];

  let tonePool = [
    "putty1", "mint1", "putty2", "mint2", "putty1",
    "putty2", "mint1", "putty1", "mint2", "putty1"
  ];

  for (let col of colDefs) {
    let levelIdx = 0;
    for (let z = col.zStart; z < col.zMax; z += col.dz) {
      levelIdx++;

      // Occasional missing capsule slots near upper/side levels (classic Nakagin metabolist rhythm)
      let skipSlot = false;
      if (col.id === 2 && (levelIdx === 7 || levelIdx === 12 || levelIdx === 16)) skipSlot = true;
      if (col.id === 3 && (levelIdx === 10 || levelIdx === 15 || levelIdx === 19)) skipSlot = true;
      if (col.id === 4 && (levelIdx === 5 || levelIdx === 9 || levelIdx === 13 || levelIdx >= 16)) skipSlot = true;
      if (col.id === 1 && (levelIdx === 15 || levelIdx === 19)) skipSlot = true;
      if (col.id === 0 && levelIdx === 18) skipSlot = true;

      if (skipSlot) continue;

      // Subtle cantilevered projection offsets per capsule
      let hash = (col.id * 31 + levelIdx * 17) % 29;
      let yCantilever = ((hash % 5) - 2) * 1.35;
      let xShift = ((hash % 3) - 1) * 0.65;

      let bx0 = col.x0 + xShift;
      let bx1 = col.x1 + xShift;
      let by0 = col.y0 + yCantilever;
      let by1 = col.y1;
      let bz0 = z;
      let bz1 = z + col.h;

      let pFace = col.mainFace;
      if (pFace === "mixed") {
        pFace = (levelIdx % 3 === 1) ? "+X" : "-Y";
      }

      let cType = curtainPool[(col.id * 7 + levelIdx * 5) % curtainPool.length];
      let pTone = tonePool[(col.id * 11 + levelIdx * 3) % tonePool.length];
      let weatherSeed = (col.id * 97 + levelIdx * 53) % 100;

      let cap = createBox3D(bx0, bx1, by0, by1, bz0, bz1, {
        type: "capsule",
        colId: col.id,
        levelIdx,
        portholeFace: pFace,
        curtainType: cType,
        panelTone: pTone,
        weatherSeed
      });

      if (cap.onScreen) {
        boxes.push(cap);
        capsules.push(cap);
      }
    }
  }

  // Compute exact 3D occlusion lists for every box
  for (let i = 0; i < boxes.length; i++) {
    let B = boxes[i];
    let hB = B.hull2D;
    for (let j = 0; j < boxes.length; j++) {
      if (i === j) continue;
      let A = boxes[j];
      let hA = A.hull2D;
      // Check 2D AABB overlap first
      if (hA.maxX < hB.minX || hA.minX > hB.maxX || hA.maxY < hB.minY || hA.minY > hB.maxY) {
        continue;
      }
      if (isBoxInFront(A, B)) {
        B.occluders.push(A);
      }
    }
  }

  return { boxes, capsules, coreBlocks };
}

// ============================================================================
// STAGE 1: PALE OVERCAST SKY & DIFFUSE ATMOSPHERE
// ============================================================================

function drawOvercastSky() {
  brush.noStroke();

  // Soft pale cool-grey overcast cloud layers in upper-right and upper-left sky wedges
  brush.fill("#d7dddb", 48);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.45, 0.15);
  brush.rect(360, -40, 880, 560, "corner");
  brush.rect(-40, -40, 420, 680, "corner");

  brush.fill("#cad2d0", 42);
  brush.fillBleed(0.42, "out");
  brush.rect(520, 40, 720, 360, "corner");
  brush.rect(-20, 60, 290, 420, "corner");

  brush.fill("#dfe4e2", 50);
  brush.fillBleed(0.3, "out");
  brush.rect(680, 340, 560, 440, "corner");

  brush.noFill();

  // Delicate diffuse horizontal/diagonal 2H graphite sky striations
  brush.set("2H", "#b6bec0", 0.28);
  for (let i = 0; i < 95; i++) {
    let y = map(i, 0, 95, 15, 820) + random(-8, 8);
    // Keep mostly in the sky regions (upper right and upper left)
    let xStart = y < 480 ? random(420, 760) : random(720, 960);
    let xEnd = xStart + random(140, 420);
    if (xEnd > 1220) xEnd = 1220;
    let tilt = random(-6, 3);
    brush.line(xStart, y, xEnd, y + tilt);
  }

  for (let i = 0; i < 45; i++) {
    let y = map(i, 0, 45, 15, 720) + random(-6, 6);
    let xStart = random(-10, 80);
    let xEnd = xStart + random(90, 220);
    brush.line(xStart, y, xEnd, y + random(-5, 3));
  }

  // Faint atmospheric stipple in the sky
  brush.set("spray", "#9fa7a9", 0.35);
  for (let i = 0; i < 18; i++) {
    let sx = random(560, 1180);
    let sy = random(30, 580);
    brush.line(sx, sy, sx + random(40, 140), sy + random(-10, 10));
  }
}

// ============================================================================
// STAGE 3: BATCHED WATERCOLOR WASHES (MINT ACCENT, PUTTY, SOFFITS, PORTHOLES)
// ============================================================================

function renderBatchedWashes(scene) {
  let buckets = {
    putty1:   { color: "#cbc8be", opacity: 44, bleed: 0.12, tex: 0.45, border: 0.22, polys: [] },
    putty2:   { color: "#bfbcb2", opacity: 48, bleed: 0.12, tex: 0.48, border: 0.25, polys: [] },
    mint1:    { color: "#aec7bd", opacity: 52, bleed: 0.14, tex: 0.48, border: 0.24, polys: [] },
    mint2:    { color: "#96b4a8", opacity: 56, bleed: 0.15, tex: 0.52, border: 0.26, polys: [] },
    sideGrey: { color: "#a5acab", opacity: 52, bleed: 0.10, tex: 0.45, border: 0.22, polys: [] },
    soffit:   { color: "#80888b", opacity: 64, bleed: 0.10, tex: 0.50, border: 0.28, polys: [] },
    porthole: { color: "#434b4e", opacity: 82, bleed: 0.06, tex: 0.40, border: 0.30, polys: [] },
    curtain:  { color: "#c2c9c6", opacity: 62, bleed: 0.08, tex: 0.35, border: 0.20, polys: [] },
    rust:     { color: "#825b47", opacity: 38, bleed: 0.22, tex: 0.55, border: 0.20, polys: [] }
  };

  for (let cap of scene.capsules) {
    if (cap.screenW < 10 || cap.screenH < 8) continue;

    let { x0, x1, y0, y1, z0, z1 } = cap;

    // 1. Underside Soffit (-Z face at z = z0)
    if (camPos[2] < z0) {
      let pSoffit = [
        project(x0, y0, z0),
        project(x1, y0, z0),
        project(x1, y1, z0),
        project(x0, y1, z0)
      ];
      let trimmed = trimFacePolyAgainstOccluders(pSoffit, cap.occluders);
      if (trimmed.length >= 3) buckets.soffit.polys.push(trimmed);
    }

    // 2. Front Face (-Y face at y = y0)
    if (camPos[1] < y0) {
      let pFront = [
        project(x0, y0, z0),
        project(x1, y0, z0),
        project(x1, y0, z1),
        project(x0, y0, z1)
      ];
      let trimmed = trimFacePolyAgainstOccluders(pFront, cap.occluders);
      if (trimmed.length >= 3) {
        buckets[cap.panelTone].polys.push(trimmed);
      }

      // Sub-panel accent variation on larger capsules
      if (cap.screenW > 55 && (cap.weatherSeed % 3 === 0)) {
        let xm = (x0 + x1) * 0.5;
        let zm = (z0 + z1) * 0.5;
        let subP = [
          project(x0 + 0.8, y0, zm),
          project(xm, y0, zm),
          project(xm, y0, z1 - 0.8),
          project(x0 + 0.8, y0, z1 - 0.8)
        ];
        let trimSub = trimFacePolyAgainstOccluders(subP, cap.occluders);
        if (trimSub.length >= 3) {
          let altBucket = cap.panelTone.startsWith("mint") ? "putty2" : "mint1";
          buckets[altBucket].polys.push(trimSub);
        }
      }
    }

    // 3. Side Face (+X or -X)
    if (camPos[0] > x1) {
      let pSide = [
        project(x1, y0, z0),
        project(x1, y1, z0),
        project(x1, y1, z1),
        project(x1, y0, z1)
      ];
      let trimmed = trimFacePolyAgainstOccluders(pSide, cap.occluders);
      if (trimmed.length >= 3) {
        let bName = cap.portholeFace === "+X" ? cap.panelTone : "sideGrey";
        buckets[bName].polys.push(trimmed);
      }
    } else if (camPos[0] < x0) {
      let pSide = [
        project(x0, y1, z0),
        project(x0, y0, z0),
        project(x0, y0, z1),
        project(x0, y1, z1)
      ];
      let trimmed = trimFacePolyAgainstOccluders(pSide, cap.occluders);
      if (trimmed.length >= 3) {
        buckets.sideGrey.polys.push(trimmed);
      }
    }

    // 4. Porthole dark interior wash & rust bleed stains on larger capsules
    if (cap.screenW > 22) {
      let isFront = cap.portholeFace === "-Y";
      let cx = (x0 + x1) * 0.5;
      let cy = (y0 + y1) * 0.5;
      let cz = (z0 + z1) * 0.5 + 0.4;
      let R = 6.2;

      let ringPts = [];
      let steps = 14;
      for (let s = 0; s < steps; s++) {
        let ang = (s / steps) * Math.PI * 2;
        let ca = Math.cos(ang) * R;
        let sa = Math.sin(ang) * R;
        let pt = isFront
          ? project(cx + ca, y0 + 1.8, cz + sa)
          : project(x1 - 1.8, cy + ca, cz + sa);
        ringPts.push(pt);
      }
      let trimRing = trimFacePolyAgainstOccluders(ringPts, cap.occluders);
      if (trimRing.length >= 4) {
        buckets.porthole.polys.push(trimRing);
      }

      // Subtle rust bleed wash beneath corner bolts on close-up capsules
      if (cap.screenW > 75 && isFront && (cap.weatherSeed % 2 === 0)) {
        let rx = (cap.weatherSeed % 4 === 0) ? x0 + 2.2 : x1 - 2.2;
        let rzTop = z1 - 2.2;
        let rzBot = z1 - 8.5;
        let rustPts = [
          project(rx - 0.7, y0, rzTop),
          project(rx + 0.7, y0, rzTop),
          project(rx + 0.4, y0, rzBot),
          project(rx - 0.4, y0, rzBot)
        ];
        let trimRust = trimFacePolyAgainstOccluders(rustPts, cap.occluders);
        if (trimRust.length >= 3) buckets.rust.polys.push(trimRust);
      }
    }
  }

  // Execute batched watercolor fills
  brush.noStroke();
  let order = ["putty1", "putty2", "mint1", "mint2", "sideGrey", "soffit", "porthole", "rust"];
  for (let key of order) {
    let b = buckets[key];
    if (b.polys.length === 0) continue;
    brush.fill(b.color, b.opacity);
    brush.fillBleed(b.bleed, "in");
    brush.fillTexture(b.tex, b.border);

    for (let poly of b.polys) {
      brush.beginShape(0);
      for (let pt of poly) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();
}

// ============================================================================
// STAGE 4: BRUTALIST CONCRETE CORE, SERVICE CANYONS, PIPES & ROOFTOP MAST
// ============================================================================

function renderCoreAndPipes(scene) {
  // 1. Concrete Core blocks visible in gaps & canyons
  for (let cb of scene.coreBlocks) {
    let { x0, x1, y0, y1, z0, z1 } = cb;

    // Horizontal board-formed concrete lift joints on -Y face of core
    brush.set("2H", "#7c8487", 0.32);
    for (let z = z0; z <= z1; z += 4.5) {
      drawLine3D(x0, y0, z, x1, y0, z, cb.occluders);
    }

    // Vertical shadow hatching in the core face
    brush.set("HB", "#586063", 0.35);
    for (let x = x0 + 2; x < x1; x += 3.0) {
      drawLine3D(x, y0, z0, x, y0, z1, cb.occluders);
    }
  }

  // 2. Vertical galvanized drainage & service conduit pipes in the 2 canyons
  // Canyon 1: X in [0.5, 5.0] at Y = -36.5
  // Canyon 2: X in [-35.5, -32.0] at Y = -33.5
  let pipeSpecs = [
    { x: 1.6,   y: -36.0, zMin: -20, zMax: 515 },
    { x: 2.8,   y: -36.8, zMin: -20, zMax: 515 },
    { x: 3.9,   y: -35.8, zMin: -20, zMax: 515 },
    { x: -34.4, y: -33.0, zMin: -15, zMax: 495 },
    { x: -33.1, y: -33.8, zMin: -15, zMax: 495 }
  ];

  // Segment pipes vertically so we only check relevant occluders
  let pipeStep = 30;
  for (let ps of pipeSpecs) {
    for (let z = ps.zMin; z < ps.zMax; z += pipeStep) {
      let zA = z;
      let zB = Math.min(ps.zMax, z + pipeStep);
      let dummyBox = createBox3D(ps.x - 0.5, ps.x + 0.5, ps.y - 0.5, ps.y + 0.5, zA, zB);
      if (!dummyBox.onScreen) continue;

      let occs = [];
      for (let b of scene.boxes) {
        if (b.type === "core") continue;
        let hA = b.hull2D, hB = dummyBox.hull2D;
        if (hA.maxX < hB.minX || hA.minX > hB.maxX || hA.maxY < hB.minY || hA.minY > hB.maxY) continue;
        if (isBoxInFront(b, dummyBox)) occs.push(b);
      }

      brush.set("rotring", "#2b3134", 0.36);
      drawLine3D(ps.x - 0.28, ps.y, zA, ps.x - 0.28, ps.y, zB, occs);
      brush.set("HB", "#525a5d", 0.30);
      drawLine3D(ps.x + 0.25, ps.y, zA, ps.x + 0.25, ps.y, zB, occs);

      // Horizontal pipe clamps every 12 units
      brush.set("rotring", "#1f2426", 0.42);
      for (let zc = Math.ceil(zA / 12) * 12; zc < zB; zc += 12) {
        drawLine3D(ps.x - 0.65, ps.y - 0.3, zc, ps.x + 0.65, ps.y - 0.3, zc, occs);
        drawLine3D(ps.x - 0.65, ps.y - 0.3, zc + 0.5, ps.x + 0.65, ps.y - 0.3, zc + 0.5, occs);
      }
    }
  }

  // 3. Rooftop Maintenance Davit Crane, Steel Frame & Lightning Mast (Z = 480..590)
  brush.set("rotring", "#3a4144", 0.32);
  let mastOccs = [];
  // Main twin lattice mast at (-12, -18, 490..610)
  drawLine3D(-14, -20, 490, -14, -20, 610, mastOccs);
  drawLine3D(-10, -20, 490, -10, -20, 610, mastOccs);
  drawLine3D(-12, -16, 490, -12, -16, 610, mastOccs);
  for (let zm = 495; zm < 605; zm += 10) {
    drawLine3D(-14, -20, zm, -10, -20, zm + 5, mastOccs);
    drawLine3D(-10, -20, zm + 5, -14, -20, zm + 10, mastOccs);
    drawLine3D(-14, -20, zm, -10, -20, zm, mastOccs);
  }
  // Cantilevered steel maintenance davit arm
  brush.set("rotring", "#2b3134", 0.38);
  drawLine3D(18, -18, 490, 18, -18, 545, mastOccs);
  drawLine3D(20, -18, 490, 20, -18, 545, mastOccs);
  drawLine3D(18, -18, 545, 36, -38, 555, mastOccs);
  drawLine3D(20, -18, 542, 36, -38, 553, mastOccs);
  drawLine3D(19, -18, 525, 30, -31, 549, mastOccs);
}

// ============================================================================
// STAGE 5: HYPERREAL CAPSULE MODULE RENDERING
// ============================================================================

function renderAllCapsules(scene) {
  for (let cap of scene.capsules) {
    let detailScale = Math.max(cap.screenW, cap.screenH);
    if (detailScale < 6) continue;

    // 1. Render Underside Soffit (-Z face)
    if (camPos[2] < cap.z0) {
      renderCapsuleSoffit(cap, detailScale);
    }

    // 2. Render Side Face (+X or -X)
    if (camPos[0] > cap.x1) {
      if (cap.portholeFace === "+X") {
        renderPortholeFacade(cap, "+X", detailScale);
      } else {
        renderSecondarySideFace(cap, "+X", detailScale);
      }
    } else if (camPos[0] < cap.x0) {
      renderSecondarySideFace(cap, "-X", detailScale);
    }

    // 3. Render Front Face (-Y)
    if (camPos[1] < cap.y0) {
      if (cap.portholeFace === "-Y") {
        renderPortholeFacade(cap, "-Y", detailScale);
      } else {
        renderSecondaryFrontFace(cap, detailScale);
      }
    }

    // 4. Crisp architectural outer wireframe edges of the module
    renderModuleWireframe(cap, detailScale);
  }
}

function renderCapsuleSoffit(cap, detailScale) {
  let { x0, x1, y0, y1, z0, occluders } = cap;

  // Primary shadow hatching across the underside soffit (parallel to X)
  let stepY = detailScale > 120 ? 1.1 : detailScale > 55 ? 1.7 : 2.8;
  brush.set("HB", "#484f53", detailScale > 90 ? 0.36 : 0.28);
  for (let y = y0 + 0.8; y < y1 - 0.5; y += stepY) {
    drawLine3D(x0 + 0.4, y, z0, x1 - 0.4, y, z0, occluders);
  }

  // Cross-hatching parallel to Y (deeper shadow toward the core y1 and under drip edge y0)
  if (detailScale > 25) {
    let stepX = detailScale > 120 ? 1.3 : detailScale > 55 ? 2.1 : 3.5;
    brush.set("2B", "#31373a", 0.32);
    for (let x = x0 + 0.8; x < x1 - 0.5; x += stepX) {
      drawLine3D(x, y0 + 0.4, z0, x, y1 - 0.4, z0, occluders);
    }
  }

  // Structural steel soffit channel ribs & inspection hatch
  if (detailScale > 40) {
    brush.set("rotring", "#1f2427", detailScale > 100 ? 0.42 : 0.30);
    let numRibs = 3;
    for (let r = 1; r <= numRibs; r++) {
      let rx = x0 + ((x1 - x0) * r) / (numRibs + 1);
      drawLine3D(rx - 0.45, y0 + 1.0, z0, rx - 0.45, y1 - 1.0, z0, occluders);
      drawLine3D(rx + 0.45, y0 + 1.0, z0, rx + 0.45, y1 - 1.0, z0, occluders);
    }

    // Perimeter drip-groove seam on underside
    drawLine3D(x0 + 1.2, y0 + 1.2, z0, x1 - 1.2, y0 + 1.2, z0, occluders);
    drawLine3D(x1 - 1.2, y0 + 1.2, z0, x1 - 1.2, y1 - 1.2, z0, occluders);
    drawLine3D(x0 + 1.2, y0 + 1.2, z0, x0 + 1.2, y1 - 1.2, z0, occluders);

    // Square soffit service panel
    let hx0 = x0 + 3.2, hx1 = x0 + 8.5;
    let hy0 = y0 + 3.5, hy1 = y0 + 8.8;
    drawLine3D(hx0, hy0, z0, hx1, hy0, z0, occluders);
    drawLine3D(hx1, hy0, z0, hx1, hy1, z0, occluders);
    drawLine3D(hx1, hy1, z0, hx0, hy1, z0, occluders);
    drawLine3D(hx0, hy1, z0, hx0, hy0, z0, occluders);
  }
}

function renderSecondarySideFace(cap, side, detailScale) {
  let { x0, x1, y0, y1, z0, z1, occluders } = cap;
  let sx = side === "+X" ? x1 : x0;
  let zm = (z0 + z1) * 0.5;
  let ym = (y0 + y1) * 0.5;

  // Tonal graphite hatching across side return face
  let zStep = detailScale > 100 ? 1.2 : detailScale > 45 ? 2.0 : 3.4;
  brush.set("HB", "#5b6367", 0.30);
  for (let z = z0 + 0.6; z < z1 - 0.4; z += zStep) {
    drawLine3D(sx, y0 + 0.4, z, sx, y1 - 0.4, z, occluders);
  }

  // Top overhang cast-shadow band
  if (detailScale > 30) {
    brush.set("2B", "#393f42", 0.34);
    for (let z = z1 - 3.2; z < z1 - 0.2; z += 0.9) {
      drawLine3D(sx, y0 + 0.3, z, sx, y1 - 0.3, z, occluders);
    }
  }

  // Welded steel panel seams
  brush.set("rotring", "#252b2e", detailScale > 90 ? 0.38 : 0.28);
  drawLine3D(sx, y0, zm, sx, y1, zm, occluders);
  drawLine3D(sx, ym, z0, sx, ym, z1, occluders);

  // Recessed HVAC ventilation louvre grille on side face
  if (detailScale > 45) {
    let ly0 = y0 + 4.0, ly1 = ym - 2.2;
    let lz0 = zm + 2.0, lz1 = z1 - 2.8;
    drawLine3D(sx, ly0, lz0, sx, ly1, lz0, occluders);
    drawLine3D(sx, ly1, lz0, sx, ly1, lz1, occluders);
    drawLine3D(sx, ly1, lz1, sx, ly0, lz1, occluders);
    drawLine3D(sx, ly0, lz1, sx, ly0, lz0, occluders);

    brush.set("rotring", "#1d2224", 0.32);
    for (let lz = lz0 + 0.7; lz < lz1 - 0.4; lz += 0.85) {
      drawLine3D(sx, ly0 + 0.3, lz, sx, ly1 - 0.3, lz, occluders);
    }
  }

  // Vertical weather streaks & corner bolt rust trails on side face
  if (detailScale > 55) {
    brush.set("2H", "#636b6e", 0.28);
    for (let k = 0; k < 5; k++) {
      let wy = y0 + 2.5 + k * 4.8;
      if (wy < y1 - 1.5) {
        drawLine3D(sx, wy, z1 - 0.5, sx, wy, z0 + 3.0, occluders);
      }
    }
    // Rust bleed from corner bolts
    brush.set("cpencil", "#744f3d", 0.34);
    drawLine3D(sx, y0 + 1.8, z1 - 1.8, sx, y0 + 1.8, z1 - 7.5, occluders);
    drawLine3D(sx, y0 + 1.8, zm - 1.5, sx, y0 + 1.8, zm - 6.5, occluders);
  }
}

function renderSecondaryFrontFace(cap, detailScale) {
  // For Column D modules whose porthole is on the +X face, their -Y face has ribbed concrete/steel panels
  let { x0, x1, y0, z0, z1, occluders } = cap;
  let xm = (x0 + x1) * 0.5;
  let zm = (z0 + z1) * 0.5;

  brush.set("2H", "#727a7e", 0.28);
  let zStep = detailScale > 90 ? 1.5 : 2.6;
  for (let z = z0 + 0.8; z < z1 - 0.6; z += zStep) {
    drawLine3D(x0 + 0.5, y0, z, x1 - 0.5, y0, z, occluders);
  }

  // Panel seams
  brush.set("rotring", "#282e31", 0.35);
  drawLine3D(x0, y0, zm, x1, y0, zm, occluders);
  drawLine3D(xm, y0, z0, xm, y0, z1, occluders);

  // Recessed maintenance door & bolts
  if (detailScale > 40) {
    drawLine3D(x0 + 3.5, y0, z0 + 3.0, xm - 2.0, y0, z0 + 3.0, occluders);
    drawLine3D(xm - 2.0, y0, z0 + 3.0, xm - 2.0, y0, z1 - 3.0, occluders);
    drawLine3D(xm - 2.0, y0, z1 - 3.0, x0 + 3.5, y0, z1 - 3.0, occluders);
    drawLine3D(x0 + 3.5, y0, z1 - 3.0, x0 + 3.5, y0, z0 + 3.0, occluders);
  }
}

// ============================================================================
// PRIMARY PORTHOLE FACADE: SEAMS, PEELING CAULK, RUST, STREAKS & 3D PORTHOLE
// ============================================================================

function renderPortholeFacade(cap, faceType, detailScale) {
  let { x0, x1, y0, y1, z0, z1, occluders } = cap;
  let isFront = faceType === "-Y";

  // Helper to convert local face coordinates (u, v, depth) to 3D world (x, y, z)
  // u: horizontal across face [u0..u1], v: vertical [z0..z1], d: inward depth into module (>= 0)
  let u0 = isFront ? x0 : y0;
  let u1 = isFront ? x1 : y1;
  let uMid = (u0 + u1) * 0.5;
  let vMid = (z0 + z1) * 0.5 + 0.35;

  let to3D = (u, v, d = 0) => {
    if (isFront) return [u, y0 + d, v];
    return [x1 - d, u, v];
  };

  let drawFaceLine = (ua, va, da, ub, vb, db, inside1 = null, inside2 = null) => {
    let pA = to3D(ua, va, da);
    let pB = to3D(ub, vb, db);
    drawLine3D(pA[0], pA[1], pA[2], pB[0], pB[1], pB[2], occluders, inside1, inside2);
  };

  let R_flange = 7.8;
  let R_outer = 6.75;
  let R_inner = 6.0;
  let R_bolts = 7.3;

  // 1. Upper Overhang Shadow Band (cast by the capsule directly above)
  if (detailScale > 22) {
    brush.set("HB", "#586064", 0.30);
    let shadowH = 2.8;
    let sStep = detailScale > 90 ? 0.65 : 1.1;
    for (let v = z1 - shadowH; v < z1 - 0.15; v += sStep) {
      drawFaceLine(u0 + 0.3, v, 0, u1 - 0.3, v, 0);
    }
  }

  // 2. Subtle Graphite Surface Grain & Planar Shading near panel borders
  if (detailScale > 45) {
    brush.set("2H", "#858d90", 0.25);
    let numGrain = detailScale > 110 ? 18 : 9;
    for (let g = 0; g < numGrain; g++) {
      let gu = u0 + 1.2 + ((g * 7.3 + cap.weatherSeed) % (u1 - u0 - 2.4));
      let distU = Math.abs(gu - uMid);
      if (distU > R_flange + 0.6) {
        drawFaceLine(gu, z0 + 1.0, 0, gu, z1 - 1.0, 0);
      }
    }
  }

  // 3. Cruciform Panel Seams & Perimeter Frame Seam
  let pWeight = detailScale > 110 ? 0.40 : detailScale > 55 ? 0.32 : 0.24;
  brush.set("rotring", "#23282b", pWeight);

  // Horizontal seams left & right of porthole bezel
  drawFaceLine(u0, vMid, 0, uMid - R_flange, vMid, 0);
  drawFaceLine(uMid + R_flange, vMid, 0, u1, vMid, 0);

  // Vertical seams above & below porthole bezel
  drawFaceLine(uMid, z0, 0, uMid, vMid - R_flange, 0);
  drawFaceLine(uMid, vMid + R_flange, 0, uMid, z1, 0);

  // Secondary vertical panel divisions near left/right edges
  if (detailScale > 35) {
    let insetU = 1.4;
    let insetV = 1.2;
    drawFaceLine(u0 + insetU, z0 + insetV, 0, u1 - insetU, z0 + insetV, 0);
    drawFaceLine(u0 + insetU, z1 - insetV, 0, u1 - insetU, z1 - insetV, 0);
    drawFaceLine(u0 + insetU, z0 + insetV, 0, u0 + insetU, z1 - insetV, 0);
    drawFaceLine(u1 - insetU, z0 + insetV, 0, u1 - insetU, z1 - insetV, 0);
  }

  // 4. Peeling Caulk along Panel Joints (hyperreal detached curling sealant lines)
  if (detailScale > 50) {
    brush.set("pen", "#33393d", 0.28);
    // Left horizontal joint peeling caulk strand
    let cMidL = (u0 + 1.6 + uMid - R_flange) * 0.5;
    drawFaceLine(u0 + 2.2, vMid - 0.28, 0, cMidL, vMid - 0.65, 0);
    drawFaceLine(cMidL, vMid - 0.65, 0, cMidL + 2.1, vMid - 1.35, -0.2);

    // Right horizontal joint peeling caulk strand
    let cMidR = (uMid + R_flange + u1 - 1.6) * 0.5;
    drawFaceLine(uMid + R_flange + 0.5, vMid + 0.25, 0, cMidR, vMid - 0.45, 0);
    drawFaceLine(cMidR, vMid - 0.45, 0, cMidR + 1.8, vMid - 1.15, -0.15);

    // Lower vertical seam split caulk
    drawFaceLine(uMid + 0.32, vMid - R_flange - 0.3, 0, uMid + 0.75, z0 + 2.2, -0.15);
  }

  // 5. Weather Streaks & Rain Tear-Tracks Beneath Porthole Rim
  if (detailScale > 32) {
    brush.set("2H", "#656d71", 0.27);
    // Twin tear-track water streaks dripping from the left and right lower cheeks of the bezel
    for (let side of [-1, 1]) {
      for (let s = 0; s < 4; s++) {
        let ang = (-90 + side * (32 + s * 9)) * (Math.PI / 180);
        let su = uMid + Math.cos(ang) * R_flange;
        let sv = vMid + Math.sin(ang) * R_flange;
        let streakLen = 3.2 + ((s * 3 + cap.weatherSeed) % 5) * 1.1;
        let svEnd = Math.max(z0 + 0.5, sv - streakLen);
        drawFaceLine(su, sv, 0, su + side * 0.15, svEnd, 0);
      }
    }

    // Center chin drip streaks under porthole
    brush.set("HB", "#51585c", 0.28);
    drawFaceLine(uMid - 0.8, vMid - R_flange, 0, uMid - 0.85, z0 + 0.6, 0);
    drawFaceLine(uMid + 0.7, vMid - R_flange, 0, uMid + 0.75, z0 + 1.2, 0);

    // Drip streaks descending from horizontal panel seam
    for (let k = 0; k < 5; k++) {
      let duL = u0 + 2.5 + k * 1.6;
      if (duL < uMid - R_flange - 0.4) {
        let len = 2.0 + ((k * 7 + cap.weatherSeed) % 4) * 1.3;
        drawFaceLine(duL, vMid, 0, duL, Math.max(z0 + 0.5, vMid - len), 0);
      }
      let duR = uMid + R_flange + 0.8 + k * 1.6;
      if (duR < u1 - 1.8) {
        let len = 2.2 + ((k * 5 + cap.weatherSeed) % 4) * 1.2;
        drawFaceLine(duR, vMid, 0, duR, Math.max(z0 + 0.5, vMid - len), 0);
      }
    }
  }

  // 6. Corner Bolts & Oxidized Rust Bleeding Downward
  if (detailScale > 38) {
    let boltPositions = [
      [u0 + 2.3, z1 - 2.2],
      [u1 - 2.3, z1 - 2.2],
      [u0 + 2.3, z0 + 2.2],
      [u1 - 2.3, z0 + 2.2],
      [u0 + 2.3, vMid + 1.4],
      [u1 - 2.3, vMid + 1.4],
      [u0 + 2.3, vMid - 1.4],
      [u1 - 2.3, vMid - 1.4]
    ];

    for (let bIdx = 0; bIdx < boltPositions.length; bIdx++) {
      let [bu, bv] = boltPositions[bIdx];
      // Bolt socket mark
      brush.set("rotring", "#1d2124", 0.42);
      drawFaceLine(bu - 0.35, bv, 0, bu + 0.35, bv, 0);
      drawFaceLine(bu, bv - 0.35, 0, bu, bv + 0.35, 0);

      // Rust bleed trail dripping downward (-Z)
      if ((bIdx + cap.weatherSeed) % 2 === 0) {
        let rLen = 3.0 + ((bIdx * 13 + cap.weatherSeed) % 6) * 1.15;
        let bvEnd = Math.max(z0 + 0.4, bv - rLen);
        brush.set("cpencil", "#78513d", detailScale > 90 ? 0.38 : 0.28);
        drawFaceLine(bu, bv - 0.2, 0, bu, bvEnd, 0);
        if (detailScale > 75) {
          brush.set("rotring", "#5c3d2e", 0.25);
          drawFaceLine(bu - 0.18, bv - 0.3, 0, bu - 0.1, (bv + bvEnd) * 0.5, 0);
        }
      }
    }
  }

  // ==========================================================================
  // 7. THE 3D RECESSED PORTHOLE WINDOW & CURTAINS
  // ==========================================================================

  let segCount = detailScale > 100 ? 28 : detailScale > 45 ? 20 : 12;

  // Build 2D projected ring polygons at key depths:
  // - Outer flange ring (R = R_flange, depth = -0.22)
  // - Outer aperture rim (R = R_outer, depth = 0.0) -> used as clipping aperture!
  // - Recessed gasket rim (R = R_outer, depth = 3.4)
  // - Inner glass aperture (R = R_inner, depth = 3.5) -> used to clip curtains/glass!
  let flangePts3D = [];
  let outerPts3D = [];
  letouterPts2D = [];
  let deepOuterPts3D = [];
  let innerPts3D = [];
  let innerPts2D = [];

  for (let i = 0; i < segCount; i++) {
    let ang = (i / segCount) * Math.PI * 2;
    let ca = Math.cos(ang);
    let sa = Math.sin(ang);

    flangePts3D.push(to3D(uMid + ca * R_flange, vMid + sa * R_flange, -0.22));

    let pOut3 = to3D(uMid + ca * R_outer, vMid + sa * R_outer, 0.0);
    outerPts3D.push(pOut3);
    letouterPts2D.push(project(pOut3[0], pOut3[1], pOut3[2]));

    deepOuterPts3D.push(to3D(uMid + ca * R_outer, vMid + sa * R_outer, 3.4));

    let pIn3 = to3D(uMid + ca * R_inner, vMid + sa * R_inner, 3.5);
    innerPts3D.push(pIn3);
    innerPts2D.push(project(pIn3[0], pIn3[1], pIn3[2]));
  }

  let outerAperturePoly = buildClipPoly(letouterPts2D);
  let innerGlassPoly = buildClipPoly(innerPts2D);

  // 7A. Cylindrical Tunnel Reveal (between depth = 0.0 and depth = 3.4, clipped inside outerAperturePoly!)
  if (detailScale > 20) {
    // Axial depth hatching along the visible upper/side wall of the cylinder
    let revSteps = detailScale > 90 ? 36 : 20;
    for (let i = 0; i < revSteps; i++) {
      let ang = (i / revSteps) * Math.PI * 2;
      let sa = Math.sin(ang);
      let ca = Math.cos(ang);
      // In worm's-eye view, the upper and side walls of the cylinder (sa > -0.35) are visible
      if (sa > -0.35) {
        let p0 = to3D(uMid + ca * R_outer, vMid + sa * R_outer, 0.0);
        let p1 = to3D(uMid + ca * R_outer, vMid + sa * R_outer, 3.4);
        // Shade left-upper arch darker, right arch slightly lighter with reflected light
        if (ca < -0.1 || sa > 0.55) {
          brush.set("2B", "#2b3033", 0.34);
        } else {
          brush.set("HB", "#4e5659", 0.30);
        }
        drawLine3D(p0[0], p0[1], p0[2], p1[0], p1[1], p1[2], occluders, outerAperturePoly);
      }
    }

    // Circumferential depth rings inside the cylindrical reveal
    brush.set("rotring", "#24292c", 0.30);
    let depthRings = detailScale > 80 ? [0.9, 1.8, 2.6, 3.4] : [1.6, 3.4];
    for (let dRing of depthRings) {
      for (let i = 0; i < segCount; i++) {
        let j = (i + 1) % segCount;
        let a1 = (i / segCount) * Math.PI * 2;
        let a2 = (j / segCount) * Math.PI * 2;
        let pA = to3D(uMid + Math.cos(a1) * R_outer, vMid + Math.sin(a1) * R_outer, dRing);
        let pB = to3D(uMid + Math.cos(a2) * R_outer, vMid + Math.sin(a2) * R_outer, dRing);
        drawLine3D(pA[0], pA[1], pA[2], pB[0], pB[1], pB[2], occluders, outerAperturePoly);
      }
    }
  }

  // 7B. Black Rubber Weather-Gasket Ring at depth = 3.45 (between R_outer and R_inner)
  if (detailScale > 28) {
    brush.set("pen", "#181c1e", detailScale > 90 ? 0.42 : 0.32);
    for (let i = 0; i < segCount; i++) {
      let j = (i + 1) % segCount;
      let pA = innerPts3D[i];
      let pB = innerPts3D[j];
      drawLine3D(pA[0], pA[1], pA[2], pB[0], pB[1], pB[2], occluders, outerAperturePoly);

      // Radial gasket cross-hatch ticks
      let pOut = deepOuterPts3D[i];
      drawLine3D(pOut[0], pOut[1], pOut[2], pA[0], pA[1], pA[2], occluders, outerAperturePoly);
    }

    // Occasional peeling rubber gasket strand hanging inside foreground portholes
    if (detailScale > 85 && (cap.weatherSeed % 3 === 1)) {
      brush.set("rotring", "#161a1c", 0.36);
      let gA = to3D(uMid - 3.2, vMid + 4.8, 3.3);
      let gB = to3D(uMid - 1.5, vMid + 2.9, 3.1);
      let gC = to3D(uMid - 0.6, vMid + 1.8, 2.9);
      drawLine3D(gA[0], gA[1], gA[2], gB[0], gB[1], gB[2], occluders, outerAperturePoly);
      drawLine3D(gB[0], gB[1], gB[2], gC[0], gC[1], gC[2], occluders, outerAperturePoly);
    }
  }

  // 7C. Window Interior: Glass Shading, Specular Sky Reflection, and Precision Curtains / Blinds
  renderPortholeInterior(cap, to3D, uMid, vMid, R_inner, detailScale, outerAperturePoly, innerGlassPoly);

  // 7D. Outer Raised Steel Bezel Ring & 16 Circumferential Fastener Bolts
  brush.set("rotring", "#1c2023", detailScale > 100 ? 0.45 : 0.34);
  for (let i = 0; i < segCount; i++) {
    let j = (i + 1) % segCount;
    // Outer aperture rim (depth = 0)
    let oA = outerPts3D[i];
    let oB = outerPts3D[j];
    drawLine3D(oA[0], oA[1], oA[2], oB[0], oB[1], oB[2], occluders);

    // Raised outer flange ring (depth = -0.22)
    let fA = flangePts3D[i];
    let fB = flangePts3D[j];
    drawLine3D(fA[0], fA[1], fA[2], fB[0], fB[1], fB[2], occluders);
  }

  // 16 Bezel Bolts & Rust Drips from Bottom Bezel Bolts
  if (detailScale > 42) {
    let numBolts = 16;
    for (let b = 0; b < numBolts; b++) {
      let ang = (b / numBolts) * Math.PI * 2;
      let bu = uMid + Math.cos(ang) * R_bolts;
      let bv = vMid + Math.sin(ang) * R_bolts;

      brush.set("rotring", "#181c1e", 0.42);
      drawFaceLine(bu - 0.22, bv, -0.15, bu + 0.22, bv, -0.15);
      drawFaceLine(bu, bv - 0.22, -0.15, bu, bv + 0.22, -0.15);

      // Rust bleed dripping from lower bezel bolts
      if (Math.sin(ang) < -0.45 && ((b + cap.weatherSeed) % 2 === 0)) {
        let dripLen = 1.6 + ((b * 7 + cap.weatherSeed) % 4) * 0.85;
        brush.set("cpencil", "#76503c", 0.34);
        drawFaceLine(bu, bv - 0.2, 0, bu, Math.max(z0 + 0.4, bv - dripLen), 0);
      }
    }
  }
}

function renderPortholeInterior(cap, to3D, uMid, vMid, R, detailScale, outerPoly, innerPoly) {
  let { occluders, curtainType } = cap;
  let dGlass = 3.7;

  let drawClippedGlassLine = (u1, v1, u2, v2) => {
    let p1 = to3D(u1, v1, dGlass);
    let p2 = to3D(u2, v2, dGlass);
    drawLine3D(p1[0], p1[1], p1[2], p2[0], p2[1], p2[2], occluders, outerPoly, innerPoly);
  };

  let step = detailScale > 100 ? 0.55 : detailScale > 50 ? 0.85 : 1.4;

  if (curtainType === "parted") {
    // Two gathered fabric curtains parted in the center with a dark interior gap between them
    let rodV = vMid + R * 0.72;
    brush.set("rotring", "#252b2e", 0.34);
    drawClippedGlassLine(uMid - R, rodV, uMid + R, rodV);

    // Dark interior room void in the center gap & above rod
    brush.set("2B", "#1e2326", 0.38);
    for (let v = vMid - R; v <= vMid + R; v += step) {
      if (v > rodV) {
        drawClippedGlassLine(uMid - R, v, uMid + R, v);
      } else {
        // Center parting width widens toward the bottom tie-backs and narrows at the top rod
        let t = (rodV - v) / (R * 1.65);
        let gapHalf = 0.45 + Math.sin(t * 2.2) * 1.65;
        drawClippedGlassLine(uMid - gapHalf, v, uMid + gapHalf, v);
      }
    }
    // Cross-hatch the central dark gap
    brush.set("rotring", "#191d20", 0.32);
    for (let u = uMid - 1.8; u <= uMid + 1.8; u += step * 0.9) {
      drawClippedGlassLine(u, rodV, u * 0.4 + uMid * 0.6, vMid - R);
    }

    // Left & Right Pleated Curtain Drapes (delicate vertical undulating folds in 2H/HB)
    brush.set("2H", "#6c7477", 0.30);
    for (let side of [-1, 1]) {
      for (let f = 0; f < 7; f++) {
        let uTop = uMid + side * (0.5 + f * 0.78);
        let uMidTie = uMid + side * (1.9 + f * 0.62);
        let uBot = uMid + side * (1.5 + f * 0.72);
        let vTie = vMid - R * 0.18;
        drawClippedGlassLine(uTop, rodV, uMidTie, vTie);
        drawClippedGlassLine(uMidTie, vTie, uBot, vMid - R * 0.78);
      }
      // Tie-back band & bottom stitched hem
      brush.set("rotring", "#333a3d", 0.34);
      let vTie = vMid - R * 0.18;
      drawClippedGlassLine(uMid + side * 1.7, vTie + 0.2, uMid + side * R, vTie - 0.3);
      drawClippedGlassLine(uMid + side * 1.4, vMid - R * 0.78, uMid + side * R, vMid - R * 0.78);
      brush.set("2H", "#6c7477", 0.30);
    }

  } else if (curtainType === "left_drawn" || curtainType === "right_drawn") {
    let dir = curtainType === "left_drawn" ? -1 : 1;
    let rodV = vMid + R * 0.70;
    brush.set("rotring", "#252b2e", 0.34);
    drawClippedGlassLine(uMid - R, rodV, uMid + R, rodV);

    // Dark interior room on the uncovered side
    brush.set("2B", "#1f2427", 0.38);
    let edgeU = uMid + dir * 0.85;
    for (let v = vMid - R; v <= vMid + R; v += step) {
      if (v > rodV) {
        drawClippedGlassLine(uMid - R, v, uMid + R, v);
      } else if (dir === -1) {
        drawClippedGlassLine(edgeU, v, uMid + R, v);
      } else {
        drawClippedGlassLine(uMid - R, v, edgeU, v);
      }
    }
    // Cross-hatch uncovered dark glass
    brush.set("rotring", "#181c1f", 0.30);
    let uStart = dir === -1 ? edgeU : uMid - R;
    let uEnd = dir === -1 ? uMid + R : edgeU;
    for (let u = uStart; u <= uEnd; u += step) {
      drawClippedGlassLine(u, rodV, u + 1.2, vMid - R);
    }

    // Drawn curtain pleats on the covered side
    brush.set("HB", "#5e6669", 0.30);
    let cStart = dir === -1 ? uMid - R + 0.5 : edgeU;
    let cEnd = dir === -1 ? edgeU : uMid + R - 0.5;
    for (let u = cStart; u <= cEnd; u += 0.68) {
      drawClippedGlassLine(u, rodV, u - dir * 0.35, vMid - R * 0.82);
    }
    // Leading curtain edge & bottom hem
    brush.set("rotring", "#2d3336", 0.36);
    drawClippedGlassLine(edgeU, rodV, edgeU - dir * 0.35, vMid - R * 0.82);
    drawClippedGlassLine(cStart, vMid - R * 0.82, cEnd, vMid - R * 0.82);

  } else if (curtainType === "blinds_half" || curtainType === "blinds_low") {
    // Precision horizontal micro-blinds lowered partway down the circular porthole
    let blindBotV = curtainType === "blinds_half" ? vMid - 0.4 : vMid - R * 0.45;

    // Horizontal blind slats above blindBotV
    brush.set("rotring", "#30363a", 0.32);
    let slatStep = Math.max(0.52, step * 0.78);
    for (let v = blindBotV; v <= vMid + R; v += slatStep) {
      drawClippedGlassLine(uMid - R, v, uMid + R, v);
    }
    // Heavy bottom rail of the blinds
    brush.set("rotring", "#1d2225", 0.42);
    drawClippedGlassLine(uMid - R, blindBotV - 0.25, uMid + R, blindBotV - 0.25);

    // Two vertical cord ladders holding the slats
    brush.set("2H", "#7d8588", 0.28);
    drawClippedGlassLine(uMid - 2.6, vMid + R, uMid - 2.6, blindBotV);
    drawClippedGlassLine(uMid + 2.6, vMid + R, uMid + 2.6, blindBotV);

    // Dark interior room void below the blinds
    brush.set("2B", "#1d2225", 0.38);
    for (let v = vMid - R; v < blindBotV - 0.3; v += step * 0.85) {
      drawClippedGlassLine(uMid - R, v, uMid + R, v);
    }
    brush.set("rotring", "#161a1d", 0.32);
    for (let u = uMid - R; u <= uMid + R; u += step * 0.9) {
      drawClippedGlassLine(u, blindBotV - 0.3, u - 1.5, vMid - R);
    }

  } else {
    // Uncurtained dark clinical porthole with diagonal overcast sky reflection band
    brush.set("2B", "#22272a", 0.36);
    for (let v = vMid - R; v <= vMid + R; v += step) {
      drawClippedGlassLine(uMid - R, v, uMid + R, v);
    }
    // Second diagonal cross-hatch pass, leaving a diagonal specular sky highlight band
    brush.set("rotring", "#1a1f22", 0.30);
    for (let d = -R * 1.5; d <= R * 1.5; d += step * 0.95) {
      // Leave a specular reflection gap around d in [0.8, 2.4]
      if (d > 0.8 && d < 2.4) continue;
      drawClippedGlassLine(uMid - R, vMid + d - R * 0.5, uMid + R, vMid + d + R * 0.5);
    }
    // Crisp specular reflection edge lines across the curved glass
    if (detailScale > 40) {
      brush.set("2H", "#9aa2a5", 0.28);
      drawClippedGlassLine(uMid - R, vMid + 1.1 - R * 0.5, uMid + R, vMid + 1.1 + R * 0.5);
      drawClippedGlassLine(uMid - R, vMid + 2.1 - R * 0.5, uMid + R, vMid + 2.1 + R * 0.5);
    }
  }
}

function renderModuleWireframe(cap, detailScale) {
  let { x0, x1, y0, y1, z0, z1, occluders } = cap;
  let w = detailScale > 110 ? 0.52 : detailScale > 55 ? 0.40 : 0.30;
  brush.set("rotring", "#181c1f", w);

  // Front face (-Y) perimeter
  if (camPos[1] < y0) {
    drawLine3D(x0, y0, z0, x1, y0, z0, occluders);
    drawLine3D(x1, y0, z0, x1, y0, z1, occluders);
    drawLine3D(x1, y0, z1, x0, y0, z1, occluders);
    drawLine3D(x0, y0, z1, x0, y0, z0, occluders);
  }

  // Underside (-Z) remaining edges
  if (camPos[2] < z0) {
    drawLine3D(x1, y0, z0, x1, y1, z0, occluders);
    drawLine3D(x1, y1, z0, x0, y1, z0, occluders);
    drawLine3D(x0, y1, z0, x0, y0, z0, occluders);
  }

  // Visible side face (+X or -X) remaining edges
  if (camPos[0] > x1) {
    drawLine3D(x1, y1, z0, x1, y1, z1, occluders);
    drawLine3D(x1, y1, z1, x1, y0, z1, occluders);
  } else if (camPos[0] < x0) {
    drawLine3D(x0, y1, z0, x0, y1, z1, occluders);
    drawLine3D(x0, y1, z1, x0, y0, z1, occluders);
  }
}

// ============================================================================
// STAGE 6: FINAL ATMOSPHERIC GRAIN & ARCHITECTURAL FRAMING
// ============================================================================

function drawFinalTouches() {
  // Subtle concrete spalling / graphite dust on foreground lower capsules
  brush.set("spray", "#5a6265", 0.32);
  for (let i = 0; i < 22; i++) {
    let x = random(180, 1140);
    let y = random(650, 1180);
    brush.line(x, y, x + random(15, 55), y + random(-15, 15));
  }

  // Delicate draughtsman's double hairline border around the sheet
  let m = 22;
  brush.set("rotring", "#3a4043", 0.35);
  brush.line(m, m, width - m, m);
  brush.line(width - m, m, width - m, height - m);
  brush.line(width - m, height - m, m, height - m);
  brush.line(m, height - m, m, m);

  let m2 = 27;
  brush.set("2H", "#7c8487", 0.25);
  brush.line(m2, m2, width - m2, m2);
  brush.line(width - m2, m2, width - m2, height - m2);
  brush.line(width - m2, height - m2, m2, height - m2);
  brush.line(m2, height - m2, m2, m2);
}

