let stones = [];
let ivyVines = [];
let allLeaves = [];
let mossClusters = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1852);
  noiseSeed(1852);

  // Custom brushes for obsessive Pre-Raphaelite detail
  brush.add("fine_cpencil", {
    type: "default",
    weight: 0.32,
    scatter: 0.12,
    sharpness: 0.82,
    grain: 14,
    opacity: 195,
    spacing: 0.12,
    pressure: [0.4, 1.15, 0.3],
    noise: 0.35
  });

  brush.add("needle_pen", {
    type: "default",
    weight: 0.2,
    scatter: 0.04,
    sharpness: 0.95,
    grain: 5,
    opacity: 230,
    spacing: 0.08,
    pressure: [0.5, 1.0, 0.4],
    noise: 0.15
  });

  brush.add("glint_pencil", {
    type: "default",
    weight: 0.38,
    scatter: 0.06,
    sharpness: 0.9,
    grain: 8,
    opacity: 245,
    spacing: 0.1,
    pressure: [0.2, 1.3, 0.2],
    noise: 0.2
  });

  // Custom stream current field that parts around the main boulders and focal crevice
  brush.addField("stream_current", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = (col / field.length) * 1200;
        let y = (row / field[0].length) * 1200;
        let baseAngle = 36 + 18 * Math.sin(x * 0.004 + y * 0.003);
        let n = noise(col * 0.08, row * 0.08) * 32 - 16;
        // Deflect around the focal pebbles near (678, 658)
        let dx = x - 678;
        let dy = y - 658;
        let d = Math.sqrt(dx * dx + dy * dy);
        let deflect = 0;
        if (d < 220) {
          deflect = ((220 - d) / 220) * 28 * Math.sign(dy - dx * 0.6);
        }
        field[col][row] = baseAngle + n + deflect;
      }
    }
    return field;
  });

  buildSceneGeometry();
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Luminous Pre-Raphaelite wet-white ground
  background(PALETTE.ground);
  brush.set("2H", PALETTE.ultraDeep, 0.3);

  // 2. Deep streambed under-glazes (Viridian, Ultramarine, Madder Lake, Gamboge)
  drawUnderpaintingGlazes();

  // 3. Interstitial riverbed sand, gravel, and deep crevice shadows
  drawStreambedGravelAndCrevices();

  // 4. Layered watercolour glazes for all stones (batched for rich bleed & speed)
  drawStoneWatercolorGlazes();

  // 5. Hard coloured pencil sharpening on stones (facets, striations, quartz veins, porphyry grains)
  drawStonePencilDetails();

  // 6. Moss-furred boulders & stones (watercolor glazes + thousands of bryophyte fronds & spore capsules)
  drawMossFurredStones();

  // 7. The Dropped Garnet Ring wedged between Focal Pebble A and Focal Pebble B
  drawGarnetRing(678, 658);

  // 8. Submerged water veil, caustics, and current flow lines
  drawWaterCurrentAndCaustics();

  // 9. Trailing Ivy Tendrils (woody stems, rootlets, and 5-lobed leaves dipping into the current)
  drawIvyVinesAndLeaves();

  // 10. Surface meniscus rings, ripples, and final wet twilight glints
  drawSurfaceMeniscusAndGlints();

  noLoop();
}

// =============================================================================
// SAFE BRUSH / FILL HELPERS
// =============================================================================

function useBrush(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function fillGlazePolygon(pts, col, opacity = 45, bleed = 0.2, tex = 0.55, border = 0.4, curvature = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noFill();
  // Always restore a valid brush so subsequent stroke calls never fail
  brush.set("2H", PALETTE.ultraDeep, 0.25);
}

function washPolygon(pts, col, opacity = 120, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
  brush.noWash();
  brush.set("2H", PALETTE.ultraDeep, 0.25);
}

// =============================================================================
// SCENE GEOMETRY GENERATION
// =============================================================================

function buildSceneGeometry() {
  // Curated Hero Boulders and the Two Focal Pebbles cradling the Garnet Ring at (678, 658)
  const specs = [
    // --- FOCAL PEBBLES AROUND THE GARNET RING (678, 658) ---
    { x: 598, y: 612, rx: 96, ry: 74, rot: 24, type: "focal_left", moss: 0.42, emergent: true, tint: "viridian", quartz: 2 },
    { x: 766, y: 696, rx: 106, ry: 82, rot: -18, type: "focal_right", moss: 0.18, emergent: true, tint: "madder", quartz: 1 },
    { x: 734, y: 534, rx: 84, ry: 68, rot: 12, type: "focal_top", moss: 0.35, emergent: false, tint: "ultramarine", quartz: 1 },
    { x: 596, y: 760, rx: 82, ry: 64, rot: -28, type: "focal_bottom", moss: 0.15, emergent: false, tint: "gamboge", quartz: 1 },

    // --- LARGE MOSS-FURRED BOULDERS & RIVER STONES (Crowding edge-to-edge) ---
    { x: 165, y: 175, rx: 215, ry: 165, rot: -14, type: "mossy_boulder", moss: 0.88, emergent: true, tint: "viridian", quartz: 2 },
    { x: 535, y: 135, rx: 185, ry: 138, rot: 8, type: "mossy_boulder", moss: 0.82, emergent: true, tint: "gamboge", quartz: 1 },
    { x: 965, y: 185, rx: 225, ry: 168, rot: 19, type: "mossy_boulder", moss: 0.85, emergent: true, tint: "viridian", quartz: 2 },
    { x: 115, y: 525, rx: 162, ry: 124, rot: 22, type: "mossy_boulder", moss: 0.78, emergent: true, tint: "viridian", quartz: 1 },
    { x: 382, y: 418, rx: 138, ry: 106, rot: -16, type: "mossy_boulder", moss: 0.68, emergent: true, tint: "ultramarine", quartz: 2 },
    { x: 1045, y: 555, rx: 168, ry: 128, rot: -24, type: "mossy_boulder", moss: 0.75, emergent: true, tint: "viridian", quartz: 1 },
    { x: 865, y: 415, rx: 112, ry: 88, rot: 31, type: "river_cobble", moss: 0.52, emergent: true, tint: "madder", quartz: 1 },
    { x: 355, y: 715, rx: 132, ry: 98, rot: 15, type: "river_cobble", moss: 0.45, emergent: false, tint: "ultramarine", quartz: 2 },
    { x: 175, y: 895, rx: 190, ry: 142, rot: -12, type: "mossy_boulder", moss: 0.62, emergent: true, tint: "viridian", quartz: 2 },
    { x: 515, y: 985, rx: 158, ry: 118, rot: 9, type: "river_cobble", moss: 0.32, emergent: false, tint: "madder", quartz: 1 },
    { x: 935, y: 925, rx: 192, ry: 146, rot: -19, type: "mossy_boulder", moss: 0.64, emergent: true, tint: "viridian", quartz: 2 },
    { x: 755, y: 1095, rx: 148, ry: 112, rot: 14, type: "river_cobble", moss: 0.35, emergent: false, tint: "ultramarine", quartz: 1 },
    { x: 245, y: 1145, rx: 165, ry: 115, rot: -8, type: "river_cobble", moss: 0.48, emergent: false, tint: "gamboge", quartz: 1 },
    { x: 1145, y: 865, rx: 142, ry: 108, rot: 27, type: "mossy_boulder", moss: 0.72, emergent: true, tint: "viridian", quartz: 1 },
    { x: 1155, y: 1135, rx: 155, ry: 120, rot: -15, type: "river_cobble", moss: 0.55, emergent: true, tint: "madder", quartz: 0 },
    { x: -15, y: 1120, rx: 135, ry: 105, rot: 18, type: "mossy_boulder", moss: 0.65, emergent: true, tint: "viridian", quartz: 1 },
    { x: -20, y: 345, rx: 118, ry: 92, rot: -10, type: "mossy_boulder", moss: 0.85, emergent: true, tint: "viridian", quartz: 0 },
    { x: 745, y: 65, rx: 135, ry: 95, rot: -12, type: "mossy_boulder", moss: 0.80, emergent: true, tint: "gamboge", quartz: 1 },
    { x: 1180, y: 355, rx: 125, ry: 95, rot: 15, type: "mossy_boulder", moss: 0.78, emergent: true, tint: "viridian", quartz: 1 }
  ];

  for (let s of specs) {
    stones.push(createStoneObject(s));
  }

  // Pack medium and small pebbles into all remaining gaps across [-60, 1260]
  const tints = ["viridian", "madder", "ultramarine", "gamboge"];
  for (let attempt = 0; attempt < 1800; attempt++) {
    let px = random(-50, 1250);
    let py = random(-50, 1250);

    // Keep the exact ring pocket at (678, 658) clear of random pebbles
    let distToRing = dist(px, py, 678, 658);
    if (distToRing < 46) continue;

    // Determine maximum allowable radius before hitting another stone
    let minGap = 9999;
    for (let st of stones) {
      let dx = px - st.x;
      let dy = py - st.y;
      let c = Math.cos(-st.rot * Math.PI / 180);
      let s = Math.sin(-st.rot * Math.PI / 180);
      let lx = dx * c - dy * s;
      let ly = dx * s + dy * c;
      let eqDist = Math.sqrt(lx * lx + (ly * (st.rx / st.ry)) ** 2) - st.rx * 0.92;
      if (eqDist < minGap) minGap = eqDist;
    }

    let targetR = map(attempt, 0, 1800, 68, 18);
    if (minGap > targetR) {
      let rx = constrain(minGap * random(0.82, 0.98), 18, 76);
      let ry = rx * random(0.68, 0.88);
      let isUpper = py < 450 || px < 260 || px > 960;
      let mossAmt = isUpper ? random(0.25, 0.75) : (random() < 0.35 ? random(0.15, 0.45) : 0);
      stones.push(createStoneObject({
        x: px,
        y: py,
        rx: rx,
        ry: ry,
        rot: random(-60, 60),
        type: rx > 42 ? "river_cobble" : "submerged_pebble",
        moss: mossAmt,
        emergent: rx > 52 && isUpper && random() < 0.45,
        tint: tints[ floor(random(tints.length)) ],
        quartz: random() < 0.35 ? 1 : 0
      }));
    }
    if (stones.length >= 92) break;
  }

  // Sort stones so smaller deep-bed pebbles draw first, larger/focal boulders settle over crevices
  stones.sort((a, b) => {
    let scoreA = (a.type.startsWith("focal") ? 500 : 0) + (a.emergent ? 200 : 0) + a.rx;
    let scoreB = (b.type.startsWith("focal") ? 500 : 0) + (b.emergent ? 200 : 0) + b.rx;
    return scoreA - scoreB;
  });

  // Build Trailing Ivy Vines & 5-Lobed Leaves
  buildIvyGeometry();
}

function createStoneObject(spec) {
  let seed = random(1000);
  let lowPts = [];
  let hiPts = [];
  let rotRad = spec.rot * Math.PI / 180;
  let cosR = Math.cos(rotRad);
  let sinR = Math.sin(rotRad);

  // Facet angles to give stones realistic geological planes
  let fAngle1 = random(Math.PI * 2);
  let fAngle2 = fAngle1 + random(1.4, 2.5);

  function pointAtAngle(ang) {
    let n1 = noise(seed + Math.cos(ang) * 1.3, seed + Math.sin(ang) * 1.3);
    let n2 = noise(seed * 2.1 + Math.cos(ang * 3) * 0.8, seed * 2.1 + Math.sin(ang * 3) * 0.8);
    // Subtle angular flattening for rock cleavage facets
    let flat1 = 1 - 0.09 * Math.exp(-Math.pow( Math.sin((ang - fAngle1) / 2), 2 ) * 12);
    let flat2 = 1 - 0.07 * Math.exp(-Math.pow( Math.sin((ang - fAngle2) / 2), 2 ) * 14);
    let rMod = (0.86 + 0.22 * n1 + 0.08 * n2) * flat1 * flat2;
    let lx = Math.cos(ang) * spec.rx * rMod;
    let ly = Math.sin(ang) * spec.ry * rMod;
    return [
      spec.x + lx * cosR - ly * sinR,
      spec.y + lx * sinR + ly * cosR
    ];
  }

  for (let i = 0; i < 16; i++) {
    lowPts.push(pointAtAngle((i / 16) * Math.PI * 2));
  }
  for (let i = 0; i < 48; i++) {
    hiPts.push(pointAtAngle((i / 48) * Math.PI * 2));
  }

  return {
    ...spec,
    seed,
    fAngle1,
    fAngle2,
    pts: lowPts,
    hiPts: hiPts
  };
}

// Helper to get point on stone at local polar coords (rNorm 0..1, angRad)
function stonePoint(st, rNorm, angRad) {
  let n1 = noise(st.seed + Math.cos(angRad) * 1.3, st.seed + Math.sin(angRad) * 1.3);
  let n2 = noise(st.seed * 2.1 + Math.cos(angRad * 3) * 0.8, st.seed * 2.1 + Math.sin(angRad * 3) * 0.8);
  let flat1 = 1 - 0.09 * Math.exp(-Math.pow(Math.sin((angRad - st.fAngle1) / 2), 2) * 12);
  let flat2 = 1 - 0.07 * Math.exp(-Math.pow(Math.sin((angRad - st.fAngle2) / 2), 2) * 14);
  let rMod = (0.86 + 0.22 * n1 + 0.08 * n2) * flat1 * flat2 * rNorm;

  let rotRad = st.rot * Math.PI / 180;
  let lx = Math.cos(angRad) * st.rx * rMod;
  let ly = Math.sin(angRad) * st.ry * rMod;
  return [
    st.x + lx * Math.cos(rotRad) - ly * Math.sin(rotRad),
    st.y + lx * Math.sin(rotRad) + ly * Math.cos(rotRad)
  ];
}

