  brush.hatch(14, -45, { rand: 0.18 });
  brush.noStroke();
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noHatch();

  // Fine riverbed gravel and quartz grit in the deep pockets (especially near the focal crevice)
  const gritColors = [
    PALETTE.madderMid, PALETTE.ultraDeep, PALETTE.viridianDeep,
