// =============================================================================
// LAYER 4: WATERCOLOUR GLAZES ON STONES
// =============================================================================

function drawStoneWatercolorGlazes() {
  for (let st of stones) {
    // 1. Deep crevice shadow offset to lower-right of stone
    let shadowPts = st.pts.map(p => [p[0] + 6, p[1] + 8]);
    let shadowCol = (st.tint === "madder" || st.tint === "gamboge") ? PALETTE.madderDark : PALETTE.ultraDark;
    fillGlazePolygon(shadowPts, shadowCol, 56, 0.14, 0.5, 0.55, 0.3);

    // 2. Primary luminous mineral glaze across the whole stone
    let baseCol = PALETTE.ultraMid;
    let secondCol = PALETTE.viridianMid;
    if (st.tint === "viridian") {
      baseCol = PALETTE.gambogeLight;
      secondCol = PALETTE.viridianMid;
    } else if (st.tint === "madder") {
      baseCol = PALETTE.gambogeMid;
      secondCol = PALETTE.madderMid;
    } else if (st.tint === "ultramarine") {
      baseCol = PALETTE.viridianLight;
      secondCol = PALETTE.ultraMid;
    } else if (st.tint === "gamboge") {
      baseCol = PALETTE.gambogeLight;
      secondCol = PALETTE.gambogeOlive;
    }

    // First thin glaze (leaves upper-left luminous)
    fillGlazePolygon(st.pts, baseCol, 38, 0.12, 0.55, 0.45, 0.35);

    // Second jewel-tone glaze shifted slightly toward the body/shadow side
    let bodyPts = [];
    for (let i = 0; i < 14; i++) {
      let a = (i / 14) * Math.PI * 2;
      // Pull upper-left inward so the luminous under-glaze shines on the crown
      let crownPull = (Math.cos(a + 2.3) > 0) ? 0.72 : 0.98;
      let pt = stonePoint(st, crownPull, a);
      bodyPts.push(pt);
    }
    fillGlazePolygon(bodyPts, secondCol, 48, 0.15, 0.6, 0.5, 0.35);

    // 3. Third deep twilight shadow glaze on lower-right crescent (for larger stones)
    if (st.rx > 34) {
      let crescPts = [];
      for (let i = 0; i <= 8; i++) {
        let a = -0.35 + (i / 8) * (Math.PI + 0.5);
        crescPts.push(stonePoint(st, 0.98, a));
      }
      for (let i = 6; i >= 1; i--) {
        let a = -0.2 + (i / 7) * (Math.PI + 0.2);
        crescPts.push(stonePoint(st, 0.35, a));
      }
      let deepCol = (st.tint === "viridian") ? PALETTE.ultraDeep : PALETTE.madderDeep;
      fillGlazePolygon(crescPts, deepCol, 52, 0.16, 0.65, 0.5, 0.3);
    }
  }
}

// =============================================================================
// LAYER 5: HARD COLOURED PENCIL SHARPENING ON STONES
// =============================================================================

function drawStonePencilDetails() {
  for (let st of stones) {
    let rotRad = st.rot * Math.PI / 180;

    // 1. 3D Contour-wrapping coloured pencil striations & geological facets
    let numStriations = floor(map(st.rx, 18, 220, 8, 42));
    let darkShade = st.tint === "madder" ? PALETTE.madderDeep :
                    st.tint === "viridian" ? PALETTE.viridianDeep : PALETTE.ultraDeep;
    let midShade = st.tint === "madder" ? PALETTE.madderRose :
                   st.tint === "gamboge" ? PALETTE.gambogeDeep : PALETTE.slateMid;

    for (let i = 0; i < numStriations; i++) {
      let t = map(i, 0, numStriations - 1, -0.82, 0.85);
      // Curve across the stone's dome
      let arcPts = [];
      let steps = 7;
      for (let s = 0; s <= steps; s++) {
        let u = map(s, 0, steps, -0.88, 0.88) * Math.sqrt(Math.max(0.05, 1 - t * t));
        // Arch slightly to show 3D volume
        let domeLift = -0.14 * (1 - u * u - t * t);
        let rNorm = Math.min(0.95, Math.sqrt(u * u + (t + domeLift) ** 2));
        let ang = Math.atan2(t + domeLift, u) - rotRad;
        let p = stonePoint(st, rNorm, ang);
        let pr = (s === 0 || s === steps) ? 0.3 : 0.95;
        arcPts.push([p[0], p[1], pr]);
      }

      if (t > 0.15) {
        // Shadow side striations
        useBrush("fine_cpencil", darkShade, random(0.45, 0.85));
      } else if (t < -0.25) {
        // Lit crown mineral facets
        useBrush("fine_cpencil", st.emergent ? PALETTE.skyBlue : PALETTE.slateLight, random(0.35, 0.65));
      } else {
        // Midtone mineral grain
        useBrush("fine_cpencil", midShade, random(0.35, 0.65));
      }
      brush.spline(arcPts, 0.35);
    }

    // 2. Cross-facet cleavage planes (sharp angular rock planes)
    if (st.rx > 35) {
      let facetLines = floor(st.rx / 6);
      for (let f = 0; f < facetLines; f++) {
        let a1 = st.fAngle1 + random(-0.55, 0.55);
        let r1 = random(0.15, 0.65);
        let r2 = Math.min(0.95, r1 + random(0.2, 0.42));
        let p1 = stonePoint(st, r1, a1);
        let p2 = stonePoint(st, r2, a1 + random(-0.25, 0.25));
        let isLit = Math.cos(a1 + rotRad + 2.2) > 0.2;
        useBrush("2H", isLit ? PALETTE.quartzPale : PALETTE.ultraDark, random(0.25, 0.5));
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // 3. Geological Quartz & Calcite Veins traversing the stone
    for (let q = 0; q < (st.quartz || 0); q++) {
      let startAng = random(-Math.PI, 0);
      let endAng = startAng + Math.PI + random(-0.6, 0.6);
      let veinPts = [];
      let shadowVeinPts = [];
      let vSteps = 9;
      for (let s = 0; s <= vSteps; s++) {
        let frac = s / vSteps;
        let xNorm = lerp(Math.cos(startAng) * 0.92, Math.cos(endAng) * 0.92, frac);
        let yNorm = lerp(Math.sin(startAng) * 0.92, Math.sin(endAng) * 0.92, frac);
        // Add jittery geological fracture jogs
        let jog = (noise(st.seed + q * 10 + s * 0.7) - 0.5) * 0.28;
        xNorm += jog;
        yNorm -= jog * 0.7;
        let rNorm = Math.min(0.95, Math.sqrt(xNorm * xNorm + yNorm * yNorm));
        let ang = Math.atan2(yNorm, xNorm);
        let pt = stonePoint(st, rNorm, ang);
        let pr = 0.5 + 0.8 * Math.sin(frac * Math.PI);
        veinPts.push([pt[0], pt[1], pr]);
        shadowVeinPts.push([pt[0] + 1.5, pt[1] + 1.8, pr * 0.8]);
      }
      useBrush("needle_pen", PALETTE.madderDark, 0.55);
      brush.spline(shadowVeinPts, 0.2);
      useBrush("glint_pencil", PALETTE.quartzPale, random(0.65, 1.05));
      brush.spline(veinPts, 0.2);

      // Secondary branching hair-vein
      if (veinPts.length > 5) {
        let midIdx = 4;
        let bAng = startAng + 1.3;
        let endB = stonePoint(st, 0.9, bAng);
        useBrush("glint_pencil", PALETTE.skyGlint, 0.45);
        brush.line(veinPts[midIdx][0], veinPts[midIdx][1], endB[0], endB[1]);
      }
    }

    // 4. Porphyry / Mineral Speckles & Lichen/Sediment Pores
    let numSpecks = floor(map(st.rx, 18, 220, 12, 95));
    for (let sp = 0; sp < numSpecks; sp++) {
      let rNorm = Math.sqrt(random(0.02, 0.88));
      let ang = random(Math.PI * 2);
      let p = stonePoint(st, rNorm, ang);
      let speckCol = (sp % 4 === 0) ? PALETTE.quartzPale :
                     (sp % 4 === 1) ? PALETTE.madderRose :
                     (sp % 4 === 2) ? PALETTE.ultraDark : PALETTE.gambogeLight;
      useBrush("needle_pen", speckCol, random(0.3, 0.7));
      brush.line(p[0], p[1], p[0] + random(-2.2, 2.2), p[1] + random(-1.8, 1.8));
    }

    // 5. Crisp Crevice Outline on shadowed underside & Wet Sky Glint on upper-left rim
    let underPts = [];
    for (let i = 0; i <= 20; i++) {
      let worldAng = -0.3 + (i / 20) * (Math.PI + 0.5);
      let localAng = worldAng - rotRad;
      let p = stonePoint(st, 0.98, localAng);
      let pr = Math.sin((i / 20) * Math.PI) * 1.2 + 0.2;
      underPts.push([p[0], p[1], pr]);
    }
    useBrush("needle_pen", PALETTE.ultraDark, map(st.rx, 18, 220, 0.45, 1.1));
    brush.spline(underPts, 0.35);

    // Upper-left wet twilight reflection rim
    let rimPts = [];
    for (let i = 0; i <= 14; i++) {
      let worldAng = Math.PI + 0.25 + (i / 14) * (Math.PI * 0.75);
      let localAng = worldAng - rotRad;
      let p = stonePoint(st, 0.91, localAng);
      let pr = Math.sin((i / 14) * Math.PI) * 1.1 + 0.15;
      rimPts.push([p[0], p[1], pr]);
    }
    useBrush("glint_pencil", st.emergent ? PALETTE.skyGlint : PALETTE.skyBlue, map(st.rx, 18, 220, 0.35, 0.85));
    brush.spline(rimPts, 0.4);
  }
}

// =============================================================================
// LAYER 6: MOSS-FURRED STONES (GLAZES + OBSESSIVE BRYOPHYTE FRONDS)
// =============================================================================

function drawMossFurredStones() {
  // Collect moss cushion zones on the stones that have moss coverage
  let mossZones = [];

  for (let st of stones) {
    if (!st.moss || st.moss <= 0.05 || st.rx < 28) continue;

    let rotRad = st.rot * Math.PI / 180;
    // Moss grows thickest on the upper-left and top crown of the stone
    let patchPts = [];
    let steps = 14;
    let spread = map(st.moss, 0.1, 0.9, 0.8, 1.85); // angular spread in radians

    for (let i = 0; i <= steps; i++) {
      let worldAng = -Math.PI * 0.65 - spread + (i / steps) * (spread * 2);
      let localAng = worldAng - rotRad;
      let p = stonePoint(st, 0.96, localAng);
      patchPts.push(p);
    }
    // Irregular lower boundary of the moss cushion creeping over the stone face
    for (let i = steps; i >= 0; i--) {
      let worldAng = -Math.PI * 0.65 - spread + (i / steps) * (spread * 2);
      let localAng = worldAng - rotRad;
      let innerR = map(st.moss, 0.1, 0.9, 0.58, 0.12) + 0.18 * noise(st.seed + i * 0.6);
      let p = stonePoint(st, innerR, localAng);
      patchPts.push(p);
    }

    mossZones.push({ st, patchPts, spread });
  }

  // Pass 1: Jewel-deep watercolor glazes for the moss cushions (Gamboge + Viridian + Ultramarine)
  for (let mz of mossZones) {
    fillGlazePolygon(mz.patchPts, PALETTE.gambogeLight, 44, 0.18, 0.65, 0.45, 0.4);
    fillGlazePolygon(mz.patchPts, PALETTE.viridianMid, 56, 0.22, 0.7, 0.5, 0.4);
    if (mz.st.rx > 70) {
      // Deep emerald-indigo core shadow inside thick moss cushions
      let deepPts = mz.patchPts.map(p => [
        lerp(p[0], mz.st.x, 0.15) + 3,
        lerp(p[1], mz.st.y, 0.15) + 4
      ]);
      fillGlazePolygon(deepPts, PALETTE.viridianDark, 48, 0.15, 0.65, 0.5, 0.35);
    }
  }

  // Pass 2: Thousands of individual feathery moss stems, fronds, and spore capsules
  for (let mz of mossZones) {
    let st = mz.st;
    let rotRad = st.rot * Math.PI / 180;
    let spread = mz.spread;
    let numTufts = floor(map(st.rx * st.moss, 10, 190, 14, 145));

    for (let t = 0; t < numTufts; t++) {
      let worldAng = -Math.PI * 0.65 + random(-spread, spread);
      let localAng = worldAng - rotRad;
      let minR = map(st.moss, 0.1, 0.9, 0.55, 0.08);
      let rNorm = random(minR, 0.96);
      let basePt = stonePoint(st, rNorm, localAng);

      // Lighting based on position on stone crown
      let lightVal = Math.cos(worldAng + Math.PI * 0.65) * (1 - rNorm * 0.35) + random(-0.15, 0.15);

      // Draw a cluster of 3 to 5 individual leafy moss shoots per tuft
      let shoots = floor(random(3, 6));
      for (let s = 0; s < shoots; s++) {
        let sx = basePt[0] + random(-4.5, 4.5);
        let sy = basePt[1] + random(-4.5, 4.5);
        let shootLen = random(5.5, 13.5) * map(st.rx, 28, 220, 0.7, 1.15);
        // Moss shoots arch upward and slightly outward toward the light/current
        let shootAng = -Math.PI * 0.55 + (worldAng + Math.PI * 0.65) * 0.45 + random(-0.45, 0.45);

        let ex = sx + Math.cos(shootAng) * shootLen;
        let ey = sy + Math.sin(shootAng) * shootLen;
        let mx = (sx + ex) * 0.5 + Math.cos(shootAng - 1.2) * (shootLen * 0.18);
        let my = (sy + ey) * 0.5 + Math.sin(shootAng - 1.2) * (shootLen * 0.18);

        // Shadow base of stem
        useBrush("needle_pen", PALETTE.mossShadow, 0.32);
        brush.line(sx, sy, mx, my);

        // Main frond stem colored by twilight light
        let frondCol = PALETTE.viridianMid;
        if (lightVal > 0.55) {
          frondCol = (s === 0) ? PALETTE.mossGold : PALETTE.mossBright;
        } else if (lightVal > 0.2) {
          frondCol = (s % 2 === 0) ? PALETTE.mossBright : PALETTE.mossEmerald;
        } else {
          frondCol = (s % 2 === 0) ? PALETTE.viridianMid : PALETTE.viridianDeep;
        }

        useBrush("fine_cpencil", frondCol, random(0.32, 0.58));
        brush.spline([[sx, sy, 0.8], [mx, my, 0.9], [ex, ey, 0.35]], 0.35);

        // Tiny lateral micro-pinnae (feathery moss leaves along the shoot)
        let barbs = 3;
        for (let b = 1; b <= barbs; b++) {
          let bf = b / (barbs + 0.5);
          let bx = lerp(sx, ex, bf);
          let by = lerp(sy, ey, bf);
          let bLen = (1 - bf * 0.45) * 3.8;
          let side = (b % 2 === 0) ? 0.65 : -0.65;
          useBrush("fine_cpencil", frondCol, 0.28);
          brush.line(bx, by, bx + Math.cos(shootAng + side) * bLen, by + Math.sin(shootAng + side) * bLen);
        }

        // Luminous wet glint on the very tip of emergent moss shoots
        if (lightVal > 0.62 && s === 0 && random() < 0.45) {
          useBrush("glint_pencil", PALETTE.veinPale, 0.32);
          brush.line(mx, my, ex, ey);
        }
      }

      // Delicate Bryophyte Spore Capsules (setae) rising from emergent moss cushions
      if (st.emergent && rNorm > 0.55 && lightVal > 0.3 && random() < 0.14) {
        let setaLen = random(16, 28);
        let setaAng = -Math.PI * 0.5 + random(-0.35, 0.35);
        let cx1 = basePt[0];
        let cy1 = basePt[1];
        let cx2 = cx1 + Math.cos(setaAng) * setaLen * 0.55;
        let cy2 = cy1 + Math.sin(setaAng) * setaLen * 0.55;
        let cx3 = cx1 + Math.cos(setaAng + 0.18) * setaLen;
        let cy3 = cy1 + Math.sin(setaAng + 0.18) * setaLen;

        // Hair-thin madder-amber stalk
        useBrush("needle_pen", PALETTE.madderRose, 0.25);
        brush.spline([[cx1, cy1, 0.7], [cx2, cy2, 0.5], [cx3, cy3, 0.4]], 0.4);

        // Nodding pyriform spore capsule at tip
        useBrush("fine_cpencil", PALETTE.gambogeLight, 0.65);
        brush.line(cx3, cy3, cx3 + 2.8, cy3 + 2.2);
        useBrush("needle_pen", PALETTE.madderDeep, 0.45);
        brush.line(cx3, cy3, cx3 + 1.6, cy3 + 1.2);
      }
    }
  }
}

// =============================================================================
// LAYER 7: THE DROPPED GARNET RING (CAUGHT BETWEEN TWO PEBBLES AT 678, 658)
// =============================================================================

function drawGarnetRing(rx, ry) {
  // The ring is wedged in the deep crevice between Focal Pebble A (598, 612) and Focal Pebble B (766, 696)
  // Hoop center at (rx - 8, ry + 10), tilted at -26 degrees; Gemstone crown at (rx + 10, ry - 8)
  let hoopX = rx - 8;
  let hoopY = ry + 10;
  let tilt = -26 * Math.PI / 180;
  let cosT = Math.cos(tilt);
  let sinT = Math.sin(tilt);
  let outerA = 35;
  let outerB = 21;
  let bandW = 7.2;

  function hoopPt(ang, rOffset = 0, zLift = 0) {
    let lx = Math.cos(ang) * (outerA + rOffset);
    let ly = Math.sin(ang) * (outerB + rOffset);
    return [
      hoopX + lx * cosT - ly * sinT,
      hoopY + lx * sinT + ly * cosT + zLift
    ];
  }

  // 1. Deep pocket shadow & ruby-red refracted caustic glow on the adjacent wet pebble
  let pocketPts = [];
  for (let i = 0; i < 12; i++) {
    let a = (i / 12) * Math.PI * 2;
    pocketPts.push([rx + Math.cos(a) * 46, ry + Math.sin(a) * 36]);
  }
  fillGlazePolygon(pocketPts, PALETTE.ultraDark, 68, 0.18, 0.5, 0.6, 0.35);

  // Refracted scarlet-madder caustic cast onto the lower-right crevice and flank of Pebble B
  let causticPts = [];
  for (let i = 0; i < 10; i++) {
    let a = (i / 10) * Math.PI * 2;
    causticPts.push([rx + 28 + Math.cos(a) * 26, ry + 16 + Math.sin(a) * 18]);
  }
  fillGlazePolygon(causticPts, PALETTE.madderRose, 65, 0.25, 0.4, 0.4, 0.4);
  let hotCausticPts = causticPts.map(p => [lerp(p[0], rx + 24, 0.35), lerp(p[1], ry + 12, 0.35)]);
  fillGlazePolygon(hotCausticPts, PALETTE.garnetFire, 55, 0.2, 0.3, 0.3, 0.4);

  // 2. Back half of the gold hoop (wedged deep into the pebble crevice)
  let backHoopPoly = [];
  for (let i = 0; i <= 14; i++) {
    let a = Math.PI * 0.85 + (i / 14) * Math.PI * 1.1;
    backHoopPoly.push(hoopPt(a, 0));
  }
  for (let i = 14; i >= 0; i--) {
    let a = Math.PI * 0.85 + (i / 14) * Math.PI * 1.1;
    backHoopPoly.push(hoopPt(a, -bandW, 2.5));
  }
  washPolygon(backHoopPoly, PALETTE.goldShadow, 210, 0.25);
  fillGlazePolygon(backHoopPoly, PALETTE.gambogeMid, 65, 0.08, 0.4, 0.6, 0.25);

  // 3. Front/Upper half of the 18k Gold Hoop (catching twilight & water reflections)
  let frontHoopPoly = [];
  for (let i = 0; i <= 16; i++) {
    let a = -Math.PI * 0.15 + (i / 16) * Math.PI * 1.15;
    frontHoopPoly.push(hoopPt(a, 0));
  }
  for (let i = 16; i >= 0; i--) {
    let a = -Math.PI * 0.15 + (i / 16) * Math.PI * 1.15;
    frontHoopPoly.push(hoopPt(a, -bandW, -1.8));
  }
  washPolygon(frontHoopPoly, PALETTE.goldMid, 225, 0.25);
  fillGlazePolygon(frontHoopPoly, PALETTE.gambogeLight, 70, 0.06, 0.35, 0.5, 0.25);

  // Metallic modelling along the gold band with fine coloured pencil & needle pen
  for (let rStep = 0; rStep <= 6; rStep++) {
    let rOff = -bandW * (rStep / 6);
    let bandCurve = [];
    for (let i = 0; i <= 24; i++) {
      let a = (i / 24) * Math.PI * 2;
      let p = hoopPt(a, rOff, (rStep / 6) * (Math.sin(a) > 0 ? -1.5 : 1.5));
      bandCurve.push([p[0], p[1], 0.8]);
    }
    let col = PALETTE.goldMid;
    if (rStep === 0 || rStep === 6) col = PALETTE.goldShadow;
    else if (rStep === 2) col = PALETTE.goldBright;
    else if (rStep === 3) col = PALETTE.skyGlint;
    else if (rStep === 5) col = PALETTE.madderDeep;
    useBrush(rStep === 2 || rStep === 3 ? "glint_pencil" : "needle_pen", col, rStep === 3 ? 0.55 : 0.38);
    brush.spline(bandCurve, 0.35);
  }

  // Specular gold band highlights & antique chased shoulder filigree
  for (let s = 0; s < 14; s++) {
    let a1 = -0.35 + s * 0.14;
    let p1 = hoopPt(a1, -1.5);
    let p2 = hoopPt(a1 + 0.06, -bandW + 1.5);
    let isGlint = (s === 2 || s === 3 || s === 9 || s === 10);
    useBrush(isGlint ? "glint_pencil" : "needle_pen", isGlint ? PALETTE.skyGlint : PALETTE.goldShadow, isGlint ? 0.65 : 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 4. The Faceted Almandine Garnet in a Crown Collet Setting at (rx + 11, ry - 9)
  let gx = rx + 11;
  let gy = ry - 9;
  let gRot = -18 * Math.PI / 180;
  let gCos = Math.cos(gRot);
  let gSin = Math.sin(gRot);
  let gemW = 16.5;
  let gemH = 13.5;

  function gemPt(lx, ly) {
    return [
      gx + lx * gCos - ly * gSin,
      gy + lx * gSin + ly * gCos
    ];
  }

  // Gold bezel cup under the garnet
  let bezelPts = [];
  const octAngles = [0.32, 0.78, 1.18, 2.0, 2.45, 3.46, 3.92, 5.1, 5.95];
  for (let i = 0; i < 8; i++) {
    let a = (i / 8) * Math.PI * 2 + Math.PI / 8;
    bezelPts.push(gemPt(Math.cos(a) * (gemW + 3.2), Math.sin(a) * (gemH + 3.2)));
  }
  washPolygon(bezelPts, PALETTE.goldMid, 235, 0.15);
  useBrush("needle_pen", PALETTE.goldShadow, 0.55);
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    brush.line(bezelPts[i][0], bezelPts[i][1], bezelPts[n][0], bezelPts[n][1]);
  }

  // Outer Girdle Octagon & Inner Table Octagon of the Cushion-Cut Garnet
  let girdle = [];
  let table = [];
  for (let i = 0; i < 8; i++) {
    let a = (i / 8) * Math.PI * 2 + Math.PI / 8;
    // Cushion-cut octagonal proportions
    let cx = Math.sign(Math.cos(a)) * Math.pow(Math.abs(Math.cos(a)), 0.75);
    let cy = Math.sign(Math.sin(a)) * Math.pow(Math.abs(Math.sin(a)), 0.75);
    girdle.push(gemPt(cx * gemW, cy * gemH));
    // Table is shifted slightly upper-left to show 3D crown height
    table.push(gemPt(cx * gemW * 0.54 - 1.2, cy * gemH * 0.54 - 1.0));
  }

  // Deep velvety Madder Lake + Ultramarine core of the Garnet
  washPolygon(girdle, PALETTE.garnetDeep, 245, 0.08);
  fillGlazePolygon(girdle, PALETTE.madderMid, 85, 0.06, 0.35, 0.6, 0.1);

  // Render the 8 Crown Facets around the table with distinct internal fire vs sky reflection
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    let facetQuad = [girdle[i], girdle[n], table[n], table[i]];

    // Determine whether this crown facet faces the lower-right internal gold fire or upper-left twilight sky
    let fCol = PALETTE.garnetDeep;
    let hatchCol = PALETTE.garnetCrimson;
    if (i === 0 || i === 1 || i === 7) {
      // Blazing internal ruby-scarlet refraction on lower-right facets
      fCol = (i === 0) ? PALETTE.garnetFire : PALETTE.garnetCrimson;
      hatchCol = (i === 0) ? PALETTE.garnetPink : PALETTE.garnetFire;
    } else if (i === 3 || i === 4) {
      // Cool twilight sky specular reflection on upper-left crown facets
      fCol = PALETTE.madderRose;
      hatchCol = PALETTE.skyGlint;
    } else {
      // Deep wine-purple shadow facets
      fCol = PALETTE.madderDark;
      hatchCol = PALETTE.madderRose;
    }

    washPolygon(facetQuad, fCol, 210, 0.02);

    // Micro-hatch across the facet with coloured pencil for crystalline brilliance
    for (let h = 1; h <= 5; h++) {
      let hf = h / 6;
      let pA = [lerp(girdle[i][0], table[i][0], hf), lerp(girdle[i][1], table[i][1], hf)];
      let pB = [lerp(girdle[n][0], table[n][0], hf), lerp(girdle[n][1], table[n][1], hf)];
      useBrush("glint_pencil", hatchCol, (i === 0 || i === 4) ? 0.5 : 0.35);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // Central Table Facet: deep mirror crimson with internal pavilion star lines & crisp sky slash
  washPolygon(table, PALETTE.garnetDeep, 230, 0.02);

  // Internal pavilion facets glowing through the table
  let culet = gemPt(2.2, 1.8);
  for (let i = 0; i < 8; i++) {
    let pavCol = (i === 0 || i === 1 || i === 7) ? PALETTE.garnetFire : PALETTE.madderMid;
    useBrush("needle_pen", pavCol, (i === 0 || i === 1) ? 0.55 : 0.32);
    brush.line(culet[0], culet[1], table[i][0], table[i][1]);
  }
  // Glowing ember core near the culet
  useBrush("glint_pencil", PALETTE.garnetFire, 0.75);
  brush.line(culet[0] - 2, culet[1] + 1, table[0][0], table[0][1]);
  useBrush("glint_pencil", PALETTE.garnetPink, 0.55);
  brush.line(culet[0], culet[1], (table[0][0] + table[1][0]) * 0.5, (table[0][1] + table[1][1]) * 0.5);

  // Crisp facet junction ridges across the entire gem
  for (let i = 0; i < 8; i++) {
    let n = (i + 1) % 8;
    useBrush("needle_pen", PALETTE.madderDark, 0.35);
    brush.line(girdle[i][0], girdle[i][1], girdle[n][0], girdle[n][1]);

    let ridgeCol = (i === 3 || i === 4 || i === 5) ? PALETTE.skyGlint :
                   (i === 0 || i === 1) ? PALETTE.garnetPink : PALETTE.madderRose;
    useBrush("needle_pen", ridgeCol, 0.38);
    brush.line(table[i][0], table[i][1], table[n][0], table[n][1]);
    brush.line(girdle[i][0], girdle[i][1], table[i][0], table[i][1]);
  }

  // Diagonal mirror-sharp twilight sky reflection across the upper-left corner of the table
  useBrush("glint_pencil", "#ffffff", 0.75);
  brush.line(table[3][0] + 1, table[3][1] + 1, table[5][0] - 1, table[5][1] + 1);
  useBrush("glint_pencil", PALETTE.skyGlint, 0.55);
  brush.line(table[3][0] + 2.5, table[3][1] + 3, table[5][0] + 1, table[5][1] + 3);

  // 8 Gold Claws gripping the garnet girdle + pinpoint gold glints
  for (let i = 0; i < 8; i++) {
    let clawOuter = bezelPts[i];
    let clawInner = [
      lerp(girdle[i][0], table[i][0], 0.28),
      lerp(girdle[i][1], table[i][1], 0.28)
    ];
    useBrush("needle_pen", PALETTE.goldShadow, 0.8);
    brush.line(clawOuter[0] + 0.8, clawOuter[1] + 0.8, clawInner[0] + 0.8, clawInner[1] + 0.8);
    useBrush("glint_pencil", PALETTE.goldBright, 0.72);
    brush.line(clawOuter[0], clawOuter[1], clawInner[0], clawInner[1]);
    useBrush("glint_pencil", "#ffffff", 0.45);
    brush.line(clawInner[0], clawInner[1], clawInner[0] - 0.8, clawInner[1] - 0.8);
  }
}

// =============================================================================
// LAYER 8: SUBMERGED WATER VEIL, CAUSTICS & CURRENT FLOW LINES
// =============================================================================

function drawWaterCurrentAndCaustics() {
  // 1. Delicate underwater caustic network weaving over the submerged stones
  for (let c = 0; c < 85; c++) {
    let cx = random(40, 1160);
    let cy = random(80, 1160);
    // Avoid drawing underwater caustics on top of the highest emergent corner boulders
    if ((cx < 260 && cy < 260) || (cx > 920 && cy < 260)) continue;

    let cPts = [];
    let ang = 32 * Math.PI / 180 + random(-0.4, 0.4);
    let len = random(28, 75);
    for (let s = 0; s <= 5; s++) {
      let f = s / 5;
      let px = cx + Math.cos(ang) * len * f + Math.sin(f * Math.PI * 2) * 6;
      let py = cy + Math.sin(ang) * len * f - Math.cos(f * Math.PI * 2) * 4;
      cPts.push([px, py, Math.sin(f * Math.PI) * 0.85 + 0.15]);
    }
    let col = (c % 3 === 0) ? PALETTE.viridianLight :
              (c % 3 === 1) ? PALETTE.gambogeLight : PALETTE.skyBlue;
    useBrush("fine_cpencil", col, random(0.28, 0.52));
    brush.spline(cPts, 0.45);
  }

  // 2. Vector-field stream flow filaments parting around stones and trailing past the ring
  brush.field("stream_current");
  for (let i = 0; i < 240; i++) {
    let fx = random(-20, 1180);
    let fy = random(-20, 1180);
    let fLen = random(45, 135);
    let isHighlight = (i % 5 === 0);
    let col = isHighlight ? PALETTE.skyBlue :
              (i % 3 === 0) ? PALETTE.ultraLight : PALETTE.viridianLight;
    useBrush(isHighlight ? "glint_pencil" : "fine_cpencil", col, isHighlight ? random(0.25, 0.45) : random(0.2, 0.38));
    brush.flowLine(fx, fy, fLen, 36);
  }
  brush.noField();
}

// =============================================================================
// LAYER 9: TRAILING IVY TENDRILS (HEDERA HELIX) & 5-LOBED LEAVES
// =============================================================================

function buildIvyGeometry() {
  // 6 sinuous ivy vines entering from the mossy banks and trailing right into the stream current
  const vineDefs = [
    // 1. Main Upper-Left Vine trailing down toward the focal crevice
    {
      spine: [[-30, 55], [95, 135], [225, 225], [345, 335], [445, 455], [525, 555], [568, 612]],
      submergedFrom: 0.72,
      leafScale: 1.05
    },
    // 2. Left Bank Secondary Branch trailing down left side
    {
      spine: [[95, 135], [65, 275], [118, 415], [195, 545], [268, 665], [325, 765]],
      submergedFrom: 0.65,
      leafScale: 0.92
    },
    // 3. Upper-Center Vine dipping into the upper current
    {
      spine: [[445, -25], [495, 110], [585, 235], [675, 345], [755, 438], [818, 505]],
      submergedFrom: 0.68,
      leafScale: 0.95
    },
    // 4. Dense Top-Right Vine trailing down toward the right of the garnet ring
    {
      spine: [[1225, 35], [1065, 145], [935, 275], [885, 425], [895, 575], [855, 715], [812, 815]],
      submergedFrom: 0.70,
      leafScale: 1.08
    },
    // 5. Mid-Right Overhanging Tendril
    {
      spine: [[1230, 445], [1095, 545], [1015, 685], [955, 835], [885, 965]],
      submergedFrom: 0.75,
      leafScale: 0.9
    },
    // 6. Lower-Left Riverbank Vine trailing into the bottom current
    {
      spine: [[-25, 715], [95, 785], [225, 865], [355, 945], [465, 1015]],
      submergedFrom: 0.55,
      leafScale: 0.94
    }
  ];

  for (let vd of vineDefs) {
    // Interpolate smooth stem points
    let stemPts = [];
    let sp = vd.spine;
    for (let i = 0; i < sp.length - 1; i++) {
      let subSteps = 4;
      for (let s = 0; s < subSteps; s++) {
        let f = s / subSteps;
        let x = lerp(sp[i][0], sp[i + 1][0], f) + Math.sin(i * 2 + f * Math.PI) * 6;
        let y = lerp(sp[i][1], sp[i + 1][1], f) + Math.cos(i * 2 + f * Math.PI) * 6;
        stemPts.push([x, y]);
      }
    }
    stemPts.push(sp[sp.length - 1]);

    ivyVines.push({ stemPts, submergedFrom: vd.submergedFrom });

    // Attach alternating 5-lobed Hedera helix leaves along the vine
    let numNodes = sp.length + 2;
    for (let n = 0; n < numNodes; n++) {
      let t = constrain((n + 0.35) / numNodes, 0.04, 0.98);
      let idx = floor(t * (stemPts.length - 1));
      let nextIdx = min(stemPts.length - 1, idx + 1);
      let nodePt = stemPts[idx];
      let tangAng = Math.atan2(stemPts[nextIdx][1] - nodePt[1], stemPts[nextIdx][0] - nodePt[0]);

      // Alternate left and right petioles, plus a terminal leaf at the tip
      let side = (n % 2 === 0) ? 1 : -1;
      let petioleAng = tangAng + side * random(0.65, 1.15);
      if (n === numNodes - 1) petioleAng = tangAng + random(-0.18, 0.18);

      let petioleLen = map(t, 0, 1, 34, 14) * vd.leafScale;
      let leafBaseX = nodePt[0] + Math.cos(petioleAng) * petioleLen;
      let leafBaseY = nodePt[1] + Math.sin(petioleAng) * petioleLen;

      // Leaf blade size tapers toward the trailing tip in the water
      let leafSize = map(t, 0, 1, 56, 24) * vd.leafScale * random(0.88, 1.14);
      let leafAng = petioleAng + side * random(-0.25, 0.15);
      // Current pulls submerged leaves toward ~36 deg
      if (t >= vd.submergedFrom) {
        leafAng = lerp(leafAng, 36 * Math.PI / 180, 0.45);
      }

      allLeaves.push(createIvyLeaf({
        stemPt: nodePt,
        x: leafBaseX,
        y: leafBaseY,
        size: leafSize,
        ang: leafAng,
        submerged: t >= vd.submergedFrom,
        halfSubmerged: Math.abs(t - vd.submergedFrom) < 0.14,
        ageTint: (n === 0 || (n % 4 === 1 && t < 0.5)) ? "madder_bronze" :
                 (t > 0.78) ? "young_gamboge" : "deep_viridian"
      }));

      // Add a smaller companion leaf at the basal nodes for lush edge crowding
      if (t < 0.42 && random() < 0.65) {
        let compAng = tangAng - side * random(0.75, 1.25);
        let compLen = petioleLen * 0.65;
        allLeaves.push(createIvyLeaf({
          stemPt: nodePt,
          x: nodePt[0] + Math.cos(compAng) * compLen,
          y: nodePt[1] + Math.sin(compAng) * compLen,
          size: leafSize * 0.72,
          ang: compAng,
          submerged: false,
          halfSubmerged: false,
          ageTint: random() < 0.4 ? "madder_bronze" : "deep_viridian"
        }));
      }
    }
  }
}

// Authentic 5-lobed Hedera helix leaf generator
function createIvyLeaf(spec) {
  // 5 lobes in local leaf coordinates where (0,0) is the petiole attachment point (sinus)
  // and +X is the direction of the central terminal lobe
  const lobeDirs = [
    { ang: 0, len: 1.0, width: 0.36 },               // Central terminal lobe
    { ang: 0.76, len: 0.76, width: 0.32 },           // Right lateral lobe
    { ang: -0.76, len: 0.76, width: 0.32 },          // Left lateral lobe
    { ang: 1.72, len: 0.46, width: 0.28 },           // Right basal lobe
    { ang: -1.72, len: 0.46, width: 0.28 }           // Left basal lobe
  ];

  let seed = random(1000);
  let cosA = Math.cos(spec.ang);
  let sinA = Math.sin(spec.ang);

  function localToWorld(lx, ly) {
    return [
      spec.x + (lx * cosA - ly * sinA) * spec.size,
      spec.y + (lx * sinA + ly * cosA) * spec.size
    ];
  }

  // Evaluate radius from petiole base at angle theta (-PI to PI)
  function ivyRadiusAt(theta) {
    // Deep cordate sinus at the back (theta near +-PI)
    let backSinus = Math.pow(Math.cos(theta / 2), 0.55);
    let lobeSum = 0.24 * backSinus;
    for (let lb of lobeDirs) {
      let dAng = theta - lb.ang;
      // Wrap angle difference
      while (dAng > Math.PI) dAng -= Math.PI * 2;
      while (dAng < -Math.PI) dAng += Math.PI * 2;
      // Pointed gothic-arch lobe peak
      let peak = Math.exp(-Math.pow(Math.abs(dAng) / lb.width, 1.55));
      lobeSum = Math.max(lobeSum, lb.len * peak * (0.28 + 0.72 * backSinus));
    }
    let waviness = 1 + 0.04 * Math.sin(theta * 6 + seed);
    return lobeSum * waviness;
  }

  let lowPts = [];
  let hiPts = [];
  for (let i = 0; i < 20; i++) {
    let th = -Math.PI + 0.15 + (i / 19) * (Math.PI * 2 - 0.3);
    let r = ivyRadiusAt(th);
    lowPts.push(localToWorld(Math.cos(th) * r, Math.sin(th) * r));
  }
  for (let i = 0; i <= 54; i++) {
    let th = -Math.PI + 0.1 + (i / 54) * (Math.PI * 2 - 0.2);
    let r = ivyRadiusAt(th);
    hiPts.push(localToWorld(Math.cos(th) * r, Math.sin(th) * r));
  }

  return {
    ...spec,
    seed,
    lobeDirs,
    localToWorld,
    ivyRadiusAt,
    pts: lowPts,
    hiPts: hiPts
  };
}

function drawIvyVinesAndLeaves() {
  // 1. Draw woody winding ivy stems and clinging aerial rootlets
  for (let v of ivyVines) {
    let sp = v.stemPts;
    // Shadow beneath stem
    let shadowSpline = sp.map((p, idx) => [p[0] + 4, p[1] + 5, map(idx, 0, sp.length - 1, 1.3, 0.45)]);
    useBrush("2B", PALETTE.ultraDark, 1.15);
    brush.spline(shadowSpline, 0.4);

    // Tiny centipede-like aerial rootlets gripping the mossy stones along the upper vine
    for (let i = 1; i < sp.length - 2; i++) {
      let f = i / sp.length;
      if (f > v.submergedFrom) continue;
      let p = sp[i];
      let tang = Math.atan2(sp[i + 1][1] - p[1], sp[i + 1][0] - p[0]);
      for (let r = -3; r <= 3; r++) {
        if (r === 0) continue;
        let rAng = tang + Math.sign(r) * 1.45 + random(-0.2, 0.2);
        let rLen = random(4, 9.5);
        useBrush("needle_pen", PALETTE.madderDark, 0.35);
        brush.line(p[0], p[1], p[0] + Math.cos(rAng) * rLen, p[1] + Math.sin(rAng) * rLen);
      }
    }

    // Woody stem body (Madder-brown shadow + Gamboge-olive bark highlight)
    let stemSpline = sp.map((p, idx) => [p[0], p[1], map(idx, 0, sp.length - 1, 1.25, 0.4)]);
    useBrush("HB", PALETTE.madderDeep, 1.05);
    brush.spline(stemSpline, 0.4);

    let litSpline = sp.map((p, idx) => [p[0] - 1, p[1] - 1, map(idx, 0, sp.length - 1, 0.85, 0.3)]);
    useBrush("fine_cpencil", PALETTE.gambogeMid, 0.65);
    brush.spline(litSpline, 0.4);
  }

  // Sort leaves so submerged leaves draw first, emergent leaves overlap crisply above
  allLeaves.sort((a, b) => (a.submerged === b.submerged) ? (b.size - a.size) : (a.submerged ? -1 : 1));

  // 2. Leaf Drop Shadows & Layered Watercolour Glazes
  for (let lf of allLeaves) {
    // Petiole stem connecting vine node to leaf sinus
    useBrush("needle_pen", PALETTE.madderDeep, 0.55);
    brush.line(lf.stemPt[0] + 2, lf.stemPt[1] + 3, lf.x + 2, lf.y + 3);
    useBrush("fine_cpencil", lf.submerged ? PALETTE.viridianMid : PALETTE.madderRose, 0.52);
    brush.line(lf.stemPt[0], lf.stemPt[1], lf.x, lf.y);

    // Drop shadow on stone/water below leaf
    let shOff = lf.submerged ? 3.5 : 7.5;
    let shadowPts = lf.pts.map(p => [p[0] + shOff, p[1] + shOff * 1.15]);
    fillGlazePolygon(shadowPts, PALETTE.ultraDark, lf.submerged ? 42 : 58, 0.14, 0.5, 0.5, 0.3);

    // Base and second jewel watercolor glazes on leaf blade
    if (lf.ageTint === "madder_bronze") {
      fillGlazePolygon(lf.pts, PALETTE.gambogeMid, 46, 0.1, 0.55, 0.5, 0.3);
      fillGlazePolygon(lf.pts, PALETTE.madderMid, 48, 0.12, 0.6, 0.5, 0.3);
      fillGlazePolygon(lf.pts, PALETTE.viridianDeep, 44, 0.12, 0.6, 0.5, 0.3);
    } else if (lf.ageTint === "young_gamboge") {
      fillGlazePolygon(lf.pts, PALETTE.gambogeLight, 52, 0.1, 0.55, 0.45, 0.3);
      fillGlazePolygon(lf.pts, PALETTE.viridianLight, 50, 0.12, 0.55, 0.5, 0.3);
    } else {
      fillGlazePolygon(lf.pts, PALETTE.gambogeMid, 38, 0.1, 0.5, 0.45, 0.3);
      fillGlazePolygon(lf.pts, PALETTE.viridianMid, 58, 0.12, 0.6, 0.5, 0.3);
      fillGlazePolygon(lf.pts, lf.submerged ? PALETTE.ultraMid : PALETTE.viridianDeep, 46, 0.12, 0.6, 0.5, 0.3);
    }
  }

  // 3. Hard Coloured Pencil Sharpening on Every Ivy Leaf (Lamina Shading, Margins, and Full Palmate Venation)
  for (let lf of allLeaves) {
    // Subtle coloured pencil shading between the veins to give the leaf blade 3D pillowing
    let bladeShadeCol = lf.submerged ? PALETTE.ultraDeep :
                        (lf.ageTint === "madder_bronze") ? PALETTE.madderDeep : PALETTE.viridianDark;
    for (let lb of lf.lobeDirs) {
      for (let s = 1; s <= 5; s++) {
        let f = s / 6;
        let pCenter = lf.localToWorld(Math.cos(lb.ang) * lb.len * f, Math.sin(lb.ang) * lb.len * f);
        let pLeft = lf.localToWorld(Math.cos(lb.ang - lb.width * 0.65) * lb.len * f * 0.85, Math.sin(lb.ang - lb.width * 0.65) * lb.len * f * 0.85);
        let pRight = lf.localToWorld(Math.cos(lb.ang + lb.width * 0.65) * lb.len * f * 0.85, Math.sin(lb.ang + lb.width * 0.65) * lb.len * f * 0.85);
        useBrush("fine_cpencil", bladeShadeCol, 0.34);
        brush.line(pCenter[0], pCenter[1], pLeft[0], pLeft[1]);
        brush.line(pCenter[0], pCenter[1], pRight[0], pRight[1]);
      }
    }

    // Wet twilight cuticle sheen on emergent leaves
    if (!lf.submerged) {
      let sheenP1 = lf.localToWorld(0.18, -0.22);
      let sheenP2 = lf.localToWorld(0.52, -0.08);
      let sheenP3 = lf.localToWorld(0.35, 0.18);
      useBrush("glint_pencil", PALETTE.skyBlue, 0.42);
      brush.line(sheenP1[0], sheenP1[1], sheenP2[0], sheenP2[1]);
      brush.line(sheenP2[0], sheenP2[1], sheenP3[0], sheenP3[1]);
    }

    // Palmate Primary Veins (5 radiating main veins) + Secondary & Tertiary Reticulate Venation
    for (let lb of lf.lobeDirs) {
      let vSteps = 6;
      let veinPts = [];
      let groovePts = [];
      for (let s = 0; s <= vSteps; s++) {
        let f = (s / vSteps) * 0.94;
        // Slight organic curve along the lobe axis
        let curveOff = Math.sin(f * Math.PI) * 0.025 * Math.sign(lb.ang);
        let lx = Math.cos(lb.ang + curveOff) * lb.len * f;
        let ly = Math.sin(lb.ang + curveOff) * lb.len * f;
        let wp = lf.localToWorld(lx, ly);
        let pr = map(s, 0, vSteps, 1.15, 0.25);
        veinPts.push([wp[0], wp[1], pr]);
        groovePts.push([wp[0] + 1.1, wp[1] + 1.3, pr * 0.85]);

        // Secondary branching lateral veins off each primary vein
        if (s >= 1 && s <= vSteps - 1) {
          for (let side of [-1, 1]) {
            let secAng = lb.ang + side * 0.58;
            let secLen = lb.len * (1 - f * 0.65) * 0.34;
            let sx2 = lx + Math.cos(secAng) * secLen;
            let sy2 = ly + Math.sin(secAng) * secLen;
            let swp = lf.localToWorld(sx2, sy2);

            useBrush("needle_pen", PALETTE.veinDark, 0.24);
            brush.line(wp[0] + 0.8, wp[1] + 0.8, swp[0] + 0.8, swp[1] + 0.8);
            useBrush("fine_cpencil", lf.submerged ? PALETTE.veinMid : PALETTE.veinPale, 0.28);
            brush.line(wp[0], wp[1], swp[0], swp[1]);

            // Tiny tertiary fork near margin
            let tx = sx2 + Math.cos(secAng + side * 0.45) * (secLen * 0.42);
            let ty = sy2 + Math.sin(secAng + side * 0.45) * (secLen * 0.42);
            let twp = lf.localToWorld(tx, ty);
            useBrush("fine_cpencil", PALETTE.veinMid, 0.2);
            brush.line(swp[0], swp[1], twp[0], twp[1]);
          }
        }
      }

      // Draw dark incised groove beside primary vein, then luminous pale cream-green vein ridge
      useBrush("needle_pen", PALETTE.veinDark, 0.36);
      brush.spline(groovePts, 0.25);
      useBrush("glint_pencil", lf.submerged ? PALETTE.veinMid : PALETTE.veinPale, 0.45);
      brush.spline(veinPts, 0.25);
    }

    // Crisp Coloured Pencil Margin around the 5 lobes (lit upper-left edge, dark shadowed lower-right edge)
    let litEdge = [];
    let darkEdge = [];
    for (let i = 0; i < lf.hiPts.length; i++) {
      let p = lf.hiPts[i];
      if (i < lf.hiPts.length * 0.52) {
        litEdge.push([p[0], p[1], 0.65]);
      }
      if (i >= lf.hiPts.length * 0.45) {
        darkEdge.push([p[0], p[1], 0.75]);
      }
    }
    useBrush("needle_pen", PALETTE.ultraDark, 0.42);
    brush.spline(darkEdge, 0.3);
    useBrush("fine_cpencil", lf.submerged ? PALETTE.skyBlue : PALETTE.veinPale, 0.4);
    brush.spline(litEdge, 0.3);
  }
}

// =============================================================================
// LAYER 10: SURFACE MENISCUS RINGS, RIPPLES & WET GLINTS
// =============================================================================

function drawSurfaceMeniscusAndGlints() {
  // 1. Liquid Meniscus Rings around every emergent stone crown where water laps against rock & moss
  for (let st of stones) {
    if (!st.emergent) continue;
    let rotRad = st.rot * Math.PI / 180;

    // Draw 2 concentric meniscus ripple rings hugging the downstream/lower flank of the emergent stone
    for (let ring = 1; ring <= 2; ring++) {
      let rScale = 1.0 + ring * 0.045;
      let mPts = [];
      let shadowMPts = [];
      for (let i = 0; i <= 18; i++) {
        let worldAng = -0.45 + (i / 18) * (Math.PI + 0.9);
        let localAng = worldAng - rotRad;
        let wobble = 1 + 0.02 * Math.sin(i * 2.5 + ring);
        let p = stonePoint(st, rScale * wobble, localAng);
        let pr = Math.sin((i / 18) * Math.PI) * 0.95 + 0.15;
        mPts.push([p[0], p[1], pr]);
        shadowMPts.push([p[0] + 1.5, p[1] + 2.0, pr * 0.8]);
      }
      useBrush("needle_pen", PALETTE.ultraDeep, 0.32);
      brush.spline(shadowMPts, 0.4);
      useBrush("glint_pencil", ring === 1 ? PALETTE.skyGlint : PALETTE.skyBlue, ring === 1 ? 0.48 : 0.32);
      brush.spline(mPts, 0.4);
    }
  }

  // 2. Meniscus Ripples around Ivy Leaves that pierce or trail into the water surface
  for (let lf of allLeaves) {
    if (!lf.submerged && !lf.halfSubmerged) continue;

    // Elliptical wake ripples trailing downstream (angle ~36 deg) from the submerged leaf tip
    let tipPt = lf.localToWorld(0.95, 0);
    for (let w = 1; w <= 2; w++) {
      let wakePts = [];
      for (let i = 0; i <= 10; i++) {
        let a = -1.3 + (i / 10) * 2.6;
        let rx = (12 + w * 9) * Math.cos(a);
        let ry = (7 + w * 5) * Math.sin(a);
        let c = Math.cos(0.62);
        let s = Math.sin(0.62);
        let wx = tipPt[0] + rx * c - ry * s;
        let wy = tipPt[1] + rx * s + ry * c;
        wakePts.push([wx, wy, Math.sin((i / 10) * Math.PI) * 0.85 + 0.15]);
      }
      useBrush("glint_pencil", w === 1 ? PALETTE.skyGlint : PALETTE.skyBlue, w === 1 ? 0.42 : 0.28);
      brush.spline(wakePts, 0.45);
    }
  }

  // 3. Delicate Water Meniscus Line & Surface Tension Glints across the Garnet Ring Setting
  let ringMeniscus = [
    [642, 678, 0.3],
    [658, 668, 0.9],
    [676, 661, 1.1],
    [694, 656, 0.9],
    [712, 659, 0.3]
  ];
  useBrush("needle_pen", PALETTE.ultraDeep, 0.38);
  brush.spline(ringMeniscus.map(p => [p[0], p[1] + 1.8, p[2]]), 0.45);
  useBrush("glint_pencil", "#ffffff", 0.58);
  brush.spline(ringMeniscus, 0.45);

  // Secondary micro-ripple curving past the garnet bezel
  let ringWake = [
    [662, 642, 0.2],
    [682, 634, 0.8],
    [704, 639, 0.9],
    [718, 652, 0.3]
  ];
  useBrush("glint_pencil", PALETTE.skyGlint, 0.42);
  brush.spline(ringWake, 0.45);

  // 4. Obsessive Wet Specular Glints & Dew/Splash Beads across Stones, Moss Tips, and Ivy Leaves
  // Glints on wet emergent stones
  for (let st of stones) {
    let numGlints = st.emergent ? floor(map(st.rx, 25, 220, 4, 18)) : floor(map(st.rx, 18, 120, 1, 5));
    let rotRad = st.rot * Math.PI / 180;
    for (let g = 0; g < numGlints; g++) {
      let worldAng = -Math.PI * 0.78 + random(-0.55, 0.55);
      let localAng = worldAng - rotRad;
      let rNorm = random(0.45, 0.88);
      let p = stonePoint(st, rNorm, localAng);
      let gLen = random(2.5, 6.5);
      let tang = worldAng + Math.PI * 0.5;
      useBrush("glint_pencil", st.emergent ? "#ffffff" : PALETTE.skyGlint, random(0.35, 0.65));
      brush.line(p[0], p[1], p[0] + Math.cos(tang) * gLen, p[1] + Math.sin(tang) * gLen);
    }
  }

  // Tiny water beads sitting on emergent ivy leaves
  for (let lf of allLeaves) {
    if (lf.submerged) continue;
    let drops = floor(random(1, 4));
    for (let d = 0; d < drops; d++) {
      let dp = lf.localToWorld(random(0.15, 0.62), random(-0.25, 0.25));
      // Dark underside of droplet
      useBrush("needle_pen", PALETTE.viridianDark, 0.55);
      brush.line(dp[0] - 1.2, dp[1] + 1.5, dp[0] + 1.8, dp[1] + 1.5);
      // Bright twilight sky pinpoint on top of droplet
      useBrush("glint_pencil", "#ffffff", 0.65);
      brush.line(dp[0] - 0.8, dp[1] - 0.5, dp[0] + 0.8, dp[1] - 0.5);
    }
  }
}

// Hyperreal Close Study of a Dried Riverbed at Dusk (Adire Indigo Resist & Muted Earth)
// Rendered with p5.js v2 + p5.brush in WEBGL

const SEED = 4829;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom spray & mist brushes for wet-in-wet velvety pigment & riverbed silt
  brush.add("fine_mist", {
    type: "spray",
    weight: 0.42,
    scatter: 3.6,
    opacity: 20,
    spacing: 0.35,
    pressure: [0.35, 1.15, 0.35]
  });

  brush.add("wide_mist", {
    type: "spray",
    weight: 0.32,
    scatter: 8.0,
    opacity: 13,
    spacing: 0.48,
    pressure: [0.3, 1.0, 0.3]
  });

  brush.add("grit_stipple", {
    type: "spray",
    weight: 0.6,
    scatter: 1.5,
    opacity: 62,
    spacing: 0.75,
    pressure: [0.7, 1.2, 0.7]
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Reserved pale paper ground: warm desiccated silt / cassava-paste bone tone
  background("#e6dfd1");

  const lightDir = [-0.7071, -0.7071]; // Dusk directional light from top-left

  // -------------------------------------------------------------------------
  // 1. GENERATE VORONOI MUD PLATE NETWORK & CRACK HIERARCHY
  // -------------------------------------------------------------------------
  const margin = 110;
  const bbox = [
    [-margin, -margin],
    [width + margin, -margin],
    [width + margin, height + margin],
    [-margin, height + margin]
  ];

  // Stratified jittered seed points across canvas + bleed margin
  let seeds = [];
  const cols = 9;
  const rows = 9;
  const cellW = (width + margin * 2) / cols;
  const cellH = (height + margin * 2) / rows;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let sx = -margin + (c + random(0.18, 0.82)) * cellW;
      let sy = -margin + (r + random(0.18, 0.82)) * cellH;
      seeds.push([sx, sy]);
    }
  }

  // 2 passes of Lloyd relaxation for natural polygonal mud-plate proportions
  for (let iter = 0; iter < 2; iter++) {
    let nextSeeds = [];
    for (let i = 0; i < seeds.length; i++) {
      let poly = computeCellPoly(i, seeds, bbox, () => 0);
      if (poly.length >= 3) {
        let cent = polyCentroid(poly);
        nextSeeds.push([
          lerp(seeds[i][0], cent[0], 0.48),
          lerp(seeds[i][1], cent[1], 0.48)
        ]);
      } else {
        nextSeeds.push(seeds[i]);
      }
    }
    seeds = nextSeeds;
  }

  // Edge crack-width function: creates primary fracture arteries and standard cracks
  function getCrackHalfWidth(i, j) {
    let a = min(i, j);
    let b = max(i, j);
    let mx = (seeds[a][0] + seeds[b][0]) * 0.5;
    let my = (seeds[a][1] + seeds[b][1]) * 0.5;
    let n = noise(mx * 0.0025 + 10, my * 0.0025 + 20);
    // Diagonal riverbed stress channel has slightly wider primary cracks
    let diagBand = exp(-pow((mx - my * 0.9 - 120) / 380, 2));
    let h = fract(sin(a * 127.1 + b * 311.7) * 43758.5453);
    let baseHalf = map(n, 0, 1, 4.5, 11.5) + diagBand * 3.2 + (h - 0.5) * 2.5;
    return constrain(baseHalf, 4.2, 14.5);
  }

  // Pale cassava-paste / curled rim inset width per edge
  function getRimInset(i, j) {
    let a = min(i, j);
    let b = max(i, j);
    let h = fract(sin(a * 269.5 + b * 183.3) * 19432.21);
    return map(h, 0, 1, 7.5, 15.5);
  }

  // Build primary cells and subdivide selected larger plates along secondary cracks
  let plates = [];
  for (let i = 0; i < seeds.length; i++) {
    let rawCell = computeCellPoly(i, seeds, bbox, () => 0);
    if (rawCell.length < 3) continue;

    let outerBase = computeCellPoly(i, seeds, bbox, (ii, jj) => getCrackHalfWidth(ii, jj));
    if (outerBase.length < 3 || polyArea(outerBase) < 900) continue;

    let innerBase = computeCellPoly(i, seeds, bbox, (ii, jj) => getCrackHalfWidth(ii, jj) + getRimInset(ii, jj));
    let area = polyArea(outerBase);
    let cent = polyCentroid(outerBase);

    // Decide if this primary plate splits into two sibling plates via a secondary crack
    let shouldSplit = (area > 16500 && random() < 0.52) || (area > 23500 && random() < 0.85);

    if (shouldSplit && innerBase.length >= 3) {
      let splitAngle = random(0, 180);
      let nx = cos(splitAngle);
      let ny = sin(splitAngle);
      let secHalfGap = random(2.6, 4.4);
      let secRim = random(6.5, 11.5);

      let outA = clipHalfPlane(outerBase, cent, [nx, ny], -secHalfGap);
      let outB = clipHalfPlane(outerBase, cent, [-nx, -ny], -secHalfGap);

      let inA = clipHalfPlane(innerBase, cent, [nx, ny], -(secHalfGap + secRim));
      let inB = clipHalfPlane(innerBase, cent, [-nx, -ny], -(secHalfGap + secRim));

      if (outA.length >= 3 && polyArea(outA) > 1200) {
        plates.push(buildPlateData(outA, inA, rawCell, true));
      }
      if (outB.length >= 3 && polyArea(outB) > 1200) {
        plates.push(buildPlateData(outB, inB, rawCell, true));
      }
    } else {
      plates.push(buildPlateData(outerBase, innerBase, rawCell, false));
    }
  }

  // -------------------------------------------------------------------------
  // 2. RESERVED PAPER WASHES & MUTED EARTH SUBSTRATE
  // -------------------------------------------------------------------------
  brush.noStroke();
  const earthGroundPalette = ["#d6cab8", "#cbbba4", "#c2ccd0", "#d4c3ac", "#bfb5a4"];
  for (let c = 0; c < earthGroundPalette.length; c++) {
    brush.fill(earthGroundPalette[c], 26);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.52, 0.22);
    for (let k = 0; k < 4; k++) {
      let gx = random(-40, width + 40);
      let gy = random(-40, height + 40);
      let gr = random(180, 360);
      brush.circle(gx, gy, gr, 0.45);
    }
  }
  brush.noFill();

  // Subtle mineral earth & dusk indigo misting over the paper ground
  brush.set("wide_mist", "#9e8e7a", 1.1);
  for (let i = 0; i < 28; i++) {
    let y = map(i, 0, 27, 20, height - 20) + random(-25, 25);
    brush.line(random(-30, 80), y, width + random(-80, 30), y + random(-60, 60));
  }
  brush.set("wide_mist", "#6e8091", 0.95);
  for (let i = 0; i < 20; i++) {
    let x = map(i, 0, 19, 30, width - 30) + random(-30, 30);
    brush.line(x, random(-30, 60), x + random(-70, 70), height + random(-60, 30));
  }

  // -------------------------------------------------------------------------
  // 3. WET-IN-WET WATERCOLOR PASSES ON THE POLYGONAL PLATES
  // -------------------------------------------------------------------------
  brush.noStroke();

  // Pass 3A: Muted Earth & Faded Dusk Indigo Outer Bevel Wash
  // Creates the clay-to-indigo transition just inside the pale cassava-paste rim
  const bevelColors = [
    "#5d554a", // muted raw umber
    "#6b5f50", // warm clay taupe
    "#495866", // dusk slate-earth
    "#334f6b", // faded Prussian dusk
    "#4f5961"  // cool river silt
  ];

  for (let bIdx = 0; bIdx < bevelColors.length; bIdx++) {
    brush.fill(bevelColors[bIdx], 78);
    brush.fillBleed(0.26, "out");
    brush.fillTexture(0.68, 0.62);

    for (let p of plates) {
      if (p.bevelColorIdx !== bIdx) continue;
      for (let lobe of p.bevelLobes) {
        drawBrushPoly(lobe, 0.25);
      }
    }
  }

  // Pass 3B: Saturated Prussian Blue & Deep Indigo Main Plate Fills
  const mainIndigoColors = [
    "#0f2f52", // deep Prussian blue
    "#143b63", // saturated Prussian blue
    "#0c2340", // dark adire indigo
    "#173354", // dusk indigo
    "#102a49", // mineral indigo
    "#1b3f66"  // rich cobalt-Prussian
  ];

  for (let mIdx = 0; mIdx < mainIndigoColors.length; mIdx++) {
    brush.fill(mainIndigoColors[mIdx], 145);
    brush.fillBleed(0.22, "in");
    brush.fillTexture(0.8, 0.82);

    for (let p of plates) {
      if (p.mainColorIdx !== mIdx) continue;
      for (let lobe of p.mainLobes) {
        drawBrushPoly(lobe, 0.28);
      }
    }
  }

  // Pass 3C: Second Wet-in-Wet Indigo Glaze (Offset toward concave bowl center)
  const glazeColors = [
    "#0a1d36",
    "#0d2847",
    "#132238",
    "#08182e"
  ];

  for (let gIdx = 0; gIdx < glazeColors.length; gIdx++) {
    brush.fill(glazeColors[gIdx], 132);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.76, 0.74);

    for (let p of plates) {
      if (p.glazeColorIdx !== gIdx || p.corePoly.length < 3) continue;
      drawBrushPoly(p.corePoly, 0.32);
    }
  }

  // Pass 3D: Mottled Tie-Dye Blooms (Pale Earth/Cerulean Backruns & Blue-Black Pools)
  // 1) Pale tie-dye resist blooms / water backruns inside the plates
  const paleBloomColors = [
    "#9c8e7b", // muted ochre-silt bloom
    "#688299", // pale Prussian backrun
    "#877d6f", // warm clay bloom
    "#7c92a3"  // cool dusk resist eye
  ];

  for (let cIdx = 0; cIdx < paleBloomColors.length; cIdx++) {
    brush.fill(paleBloomColors[cIdx], 76);
    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.86, 0.88);

    for (let p of plates) {
      for (let bl of p.paleBlooms) {
        if (bl.colorIdx !== cIdx) continue;
        brush.circle(bl.x, bl.y, bl.r, 0.42);
      }
    }
  }

  // 2) Saturated Blue-Black & Midnight Indigo Pooled Nuclei
  const darkBloomColors = [
    "#050c18", // blue-black
    "#081324", // midnight indigo
    "#0b1c36", // deep pooled Prussian
    "#121824"  // charcoal-indigo
  ];

  for (let dIdx = 0; dIdx < darkBloomColors.length; dIdx++) {
    brush.fill(darkBloomColors[dIdx], 162);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.78, 0.75);

    for (let p of plates) {
      for (let bl of p.darkBlooms) {
        if (bl.colorIdx !== dIdx) continue;
        brush.circle(bl.x, bl.y, bl.r, 0.38);
      }
    }
  }

  // 3) Subtle Recessed Earth Shadows in the Widest Primary Crack Junctions
  brush.fill("#a89882", 42);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.35);
  for (let p of plates) {
    for (let v of p.rawCell) {
      if (v[0] > -20 && v[0] < width + 20 && v[1] > -20 && v[1] < height + 20 && random() < 0.22) {
        brush.circle(v[0], v[1], random(7, 15), 0.35);
      }
    }
  }

  brush.noFill();

  // -------------------------------------------------------------------------
  // 4. FINE SPRAY MISTING & TIE-DYE TEXTILE BLOOMS
  // -------------------------------------------------------------------------
  for (let p of plates) {
    if (!p.onCanvas) continue;

    // Velvety Prussian blue & blue-black spray mist following the concave plate saucer
    let mistCol = p.mainColorIdx % 2 === 0 ? "#0c2847" : "#061121";
    brush.set("fine_mist", mistCol, random(0.85, 1.25));

    // Curved contour splines across the concave interior
    for (let ring = 0; ring < 2; ring++) {
      let t = ring === 0 ? 0.55 : 0.32;
      let nPts = p.outerRounded.length;
      if (nPts >= 4) {
        let startIdx = floor(random(nPts));
        let splinePts = [];
        for (let k = 0; k < 4; k++) {
          let v = p.outerRounded[(startIdx + k) % nPts];
          let sx = lerp(p.centroid[0], v[0], t) + random(-3, 3);
          let sy = lerp(p.centroid[1], v[1], t) + random(-3, 3);
          splinePts.push([sx, sy, k === 1 || k === 2 ? 1.15 : 0.5]);
        }
        brush.spline(splinePts, 0.55);
      }
    }

    // Muted earth spray mist along the outer bevel where mud meets indigo
    if (random() < 0.75 && p.outerRounded.length >= 3) {
      brush.set("fine_mist", random() < 0.5 ? "#665847" : "#445463", 0.78);
      let idx = floor(random(p.outerRounded.length));
      let v1 = p.outerRounded[idx];
      let v2 = p.outerRounded[(idx + 1) % p.outerRounded.length];
      let bx1 = lerp(v1[0], p.centroid[0], 0.18);
      let by1 = lerp(v1[1], p.centroid[1], 0.18);
      let bx2 = lerp(v2[0], p.centroid[0], 0.18);
      let by2 = lerp(v2[1], p.centroid[1], 0.18);
      brush.line(bx1, by1, bx2, by2);
    }

    // Mottled tie-dye resist rings & radial crinkle lines inside blooms
    for (let bl of p.paleBlooms) {
      // Dark indigo dye ring around pale bloom
      brush.set("fine_mist", "#081b33", 0.75);
      brush.arc(bl.x, bl.y, bl.r * 0.92, random(0, 120), random(200, 350));

      // Delicate pale cassava-resist crinkle whiskers radiating within the bloom
      brush.set("cpencil", "#c7bfb0", 0.38);
      let rays = floor(random(3, 6));
      for (let r = 0; r < rays; r++) {
        let ang = random(360);
        let r1 = bl.r * random(0.15, 0.38);
        let r2 = bl.r * random(0.65, 1.08);
        brush.line(
          bl.x + cos(ang) * r1,
          bl.y + sin(ang) * r1,
          bl.x + cos(ang + random(-12, 12)) * r2,
          bl.y + sin(ang + random(-12, 12)) * r2
        );
      }
    }

    // Deep blue-black spray core in dark blooms
    for (let bl of p.darkBlooms) {
      brush.set("spray", "#040a14", 0.65);
      brush.arc(bl.x, bl.y, bl.r * 0.5, 0, 270);
    }
  }

  // -------------------------------------------------------------------------
  // 5. CURLING MUD PLATE RIMS, 3D UNDERCUT SHADOWS & LAMINATIONS
  // -------------------------------------------------------------------------
  for (let p of plates) {
    if (!p.onCanvas) continue;
    let pts = p.detailedOuter;
    let n = pts.length;
    if (n < 3) continue;

    for (let i = 0; i < n; i++) {
      let p1 = pts[i];
      let p2 = pts[(i + 1) % n];
      let dx = p2[0] - p1[0];
      let dy = p2[1] - p1[1];
      let segLen = sqrt(dx * dx + dy * dy);
      if (segLen < 1.5) continue;

      // Outward normal of the polygon edge (CCW winding -> outward is [dy, -dx] or check vs centroid)
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;
      let nx = dy / segLen;
      let ny = -dx / segLen;
      if (nx * (mx - p.centroid[0]) + ny * (my - p.centroid[1]) < 0) {
        nx = -nx;
        ny = -ny;
      }

      // Alignment with top-left dusk light
      let lightDot = nx * lightDir[0] + ny * lightDir[1];

      if (lightDot < -0.05) {
        // SHADOW-CASTING CURLED EDGE (Overhanging mud lip casts crisp undercut shadow into crack)
        let shadowDepth = map(constrain(-lightDot, 0, 1), 0, 1, 1.2, 4.2);

        // Deep undercut crevice shadow just outside the curled plate rim
        brush.set("2B", "#0c121c", map(-lightDot, 0, 1, 0.65, 1.25));
        brush.line(
          p1[0] + nx * shadowDepth * 0.55,
          p1[1] + ny * shadowDepth * 0.55,
          p2[0] + nx * shadowDepth * 0.55,
          p2[1] + ny * shadowDepth * 0.55
        );

        // Secondary soft earth-umber shadow penumbra on the crack floor
        brush.set("HB", "#2d261f", map(-lightDot, 0, 1, 0.45, 0.85));
        brush.line(
          p1[0] + nx * shadowDepth * 1.15,
          p1[1] + ny * shadowDepth * 1.15,
          p2[0] + nx * shadowDepth * 1.15,
          p2[1] + ny * shadowDepth * 1.15
        );

        // Crisp physical rim edge
        brush.set("2H", "#453c33", 0.5);
        brush.line(p1[0], p1[1], p2[0], p2[1]);

        // Upward-curling inner pale lip catches warm dusk skylight
        brush.set("cpencil", "#f4eee1", 0.85);
        brush.line(
          p1[0] - nx * 2.2,
          p1[1] - ny * 2.2,
          p2[0] - nx * 2.2,
          p2[1] - ny * 2.2
        );

        // Flaky desiccated clay lamination line along the curled pale rim
        if (segLen > 12 && random() < 0.65) {
          brush.set("2H", "#8f806d", 0.38);
          let inset = random(4.0, 7.5);
          brush.line(
            p1[0] - nx * inset,
            p1[1] - ny * inset,
            p2[0] - nx * inset,
            p2[1] - ny * inset
          );
        }
      } else {
        // LIGHT-FACING CURLED EDGE (Outer brink catches bright highlight, inner saucer bevels down)
        // Razor-sharp pale highlight right on the lifted brink of the mud plate
        brush.set("cpencil", "#f7f2e6", map(lightDot, 0, 1, 0.7, 1.35));
        brush.line(
          p1[0] - nx * 0.8,
          p1[1] - ny * 0.8,
          p2[0] - nx * 0.8,
          p2[1] - ny * 0.8
        );

        // Delicate outer edge definition against the crack bed
        brush.set("HB", "#4f453b", 0.52);
        brush.line(p1[0] + nx * 0.6, p1[1] + ny * 0.6, p2[0] + nx * 0.6, p2[1] + ny * 0.6);

        // Inner concave saucer slope shaded with fine earth-graphite contour lines
        if (segLen > 10) {
          brush.set("2H", "#786c5d", 0.42);
          let bevelInset = random(3.5, 6.5);
          brush.line(
            p1[0] - nx * bevelInset,
            p1[1] - ny * bevelInset,
            p2[0] - nx * bevelInset,
            p2[1] - ny * bevelInset
          );
        }
      }
    }

    // Internal partial crack (cassava-resist fissure) pencil detail
    if (p.hasFissure && p.fissureSeg) {
      let fs = p.fissureSeg;
      // Subtle 3D edge along the internal pale fissure
      brush.set("HB", "#2b251f", 0.52);
      brush.line(fs.x1 + fs.nx * fs.halfW, fs.y1 + fs.ny * fs.halfW, fs.x2, fs.y2);
      brush.set("2H", "#6e6254", 0.42);
      brush.line(fs.x1 - fs.nx * fs.halfW, fs.y1 - fs.ny * fs.halfW, fs.x2, fs.y2);
      // Hairline continuation tip into the indigo plate
      brush.set("cpencil", "#dfd6c7", 0.48);
      brush.line(fs.x2, fs.y2, fs.x3, fs.y3);
    }
  }

  // -------------------------------------------------------------------------
  // 6. PENCIL GRIT, RIVER PEBBLES & MICRO-FISSURES IN THE CRACKS
  // -------------------------------------------------------------------------
  let pebbles = [];

  for (let p of plates) {
    if (!p.onCanvas) continue;
    let raw = p.rawCell;
    let out = p.outerBase;
    let m = min(raw.length, out.length);

    for (let i = 0; i < m; i++) {
      let r1 = raw[i];
      let r2 = raw[(i + 1) % m];
      let o1 = out[i];
      let o2 = out[(i + 1) % m];

      let edgeLen = dist(r1[0], r1[1], r2[0], r2[1]);
      let gapW = dist(r1[0], r1[1], o1[0], o1[1]);

      // Fine pencil grit & stipple along the crack floor
      if (edgeLen > 15) {
        brush.set("grit_stipple", random() < 0.6 ? "#3b332b" : "#1c2836", 0.55);
        brush.line(
          lerp(r1[0], o1[0], 0.35),
          lerp(r1[1], o1[1], 0.35),
          lerp(r2[0], o2[0], 0.35),
          lerp(r2[1], o2[1], 0.35)
        );
      }

      // Generate small river pebbles and clay crumbs nestled in the crack trench
      let numPebbles = floor(edgeLen / 26);
      for (let k = 0; k < numPebbles; k++) {
        if (random() < 0.55) {
          let t = random(0.08, 0.92);
          let s = random(0.15, 0.72);
          let px = lerp(lerp(r1[0], r2[0], t), lerp(o1[0], o2[0], t), s) + random(-2, 2);
          let py = lerp(lerp(r1[1], r2[1], t), lerp(o1[1], o2[1], t), s) + random(-2, 2);
          let pr = constrain(gapW * random(0.16, 0.42), 1.4, 5.2);
          if (px > -10 && px < width + 10 && py > -10 && py < height + 10) {
            pebbles.push({
              x: px,
              y: py,
              r: pr,
              tone: floor(random(3))
            });
          }
        }
      }

      // Hairline desiccation micro-cracks & cassava-resist whiskers at polygon corners
      if (random() < 0.58) {
        let vx = o1[0];
        let vy = o1[1];
        let cx = r1[0];
        let cy = r1[1];
        brush.set("2H", "#383028", 0.42);
        let midX = lerp(vx, cx, 0.55) + random(-4, 4);
        let midY = lerp(vy, cy, 0.55) + random(-4, 4);
        brush.line(vx, vy, midX, midY);
        brush.line(midX, midY, cx, cy);

        // Micro-fissure branching partway across the pale curled rim
        if (random() < 0.65) {
          let inX = lerp(vx, p.centroid[0], random(0.08, 0.16)) + random(-3, 3);
          let inY = lerp(vy, p.centroid[1], random(0.08, 0.16)) + random(-3, 3);
          brush.set("2H", "#54493d", 0.36);
          brush.line(vx, vy, inX, inY);
        }
      }
    }
  }

  // Batch-wash the larger pebbles in muted earth & river-slate tones
  brush.noStroke();
  const pebbleWashCols = ["#b8ab97", "#948776", "#7a848c"];
  for (let tIdx = 0; tIdx < 3; tIdx++) {
    brush.fill(pebbleWashCols[tIdx], 92);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.5, 0.4);
    for (let pb of pebbles) {
      if (pb.tone === tIdx && pb.r > 2.4) {
        brush.circle(pb.x, pb.y, pb.r, 0.35);
      }
    }
  }
  brush.noFill();

  // Crisp pencil rendering of every pebble and sand grain in the cracks
  for (let pb of pebbles) {
    // Bottom-right cast shadow of the pebble on the crack bed
    brush.set("2B", "#1a1714", map(pb.r, 1.4, 5.2, 0.38, 0.72));
    brush.arc(pb.x + 0.6, pb.y + 0.6, pb.r, 15, 195);

    // Full graphite contour of the pebble
    brush.set("2H", "#4a4138", 0.36);
    brush.circle(pb.x, pb.y, pb.r * 0.92, 0.32);

    // Top-left dusk highlight on larger pebbles
    if (pb.r > 2.3) {
      brush.set("cpencil", "#f2ece0", 0.52);
      brush.arc(pb.x - 0.4, pb.y - 0.4, pb.r * 0.65, 195, 345);
    }

    // Extra tiny graphite grit specks clustered around the pebble
    if (random() < 0.7) {
      brush.set("HB", "#29231d", 0.42);
      for (let g = 0; g < 2; g++) {
        let ga = random(360);
        let gd = pb.r * random(1.15, 1.9);
        let gx = pb.x + cos(ga) * gd;
        let gy = pb.y + sin(ga) * gd;
        brush.line(gx, gy, gx + random(-1.5, 1.5), gy + random(-1.5, 1.5));
      }
    }
  }

  noLoop();
}

// =============================================================================
// GEOMETRY & P5.BRUSH HELPERS
// =============================================================================

function drawBrushPoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Build complete plate geometry: rounded curled outer lip, pale rim inset,
// optional partial cassava-resist fissure, concave core, and tie-dye blooms.
function buildPlateData(outerBase, innerBase, rawCell, isSecondary) {
  let cent = polyCentroid(outerBase);
  let onCanvas =
    cent[0] > -90 &&
    cent[0] < width + 90 &&
    cent[1] > -90 &&
    cent[1] < height + 90;

  // Chaikin corner-cutting rounds the curled mud corners
  let outerRounded = chaikinCut(outerBase, 0.16);
  let detailedOuter = perturbPolygon(outerRounded, 3, 2.2);

  // Deeper corner cut on inner pigment polygon makes the pale rim widen at corners
  // like curled mud tips and adire cassava-paste junctions
  let bevelPoly = innerBase.length >= 3 ? chaikinCut(innerBase, 0.26) : [];
  let mainInsetPoly = shrinkTowardPoint(bevelPoly, cent, random(0.88, 0.93));

  // Core polygon shifted slightly toward bottom-right (away from top-left light)
  let poolCenter = [cent[0] + random(2, 7), cent[1] + random(2, 7)];
  let corePoly = shrinkTowardPoint(mainInsetPoly, poolCenter, random(0.58, 0.74));

  // Partial intrusion crack (pale cassava-resist fissure cutting partway into plate)
  let bevelLobes = [];
  let mainLobes = [];
  let hasFissure = false;
  let fissureSeg = null;

  if (mainInsetPoly.length >= 4 && polyArea(mainInsetPoly) > 3400 && random() < 0.62) {
    let eIdx = floor(random(outerRounded.length));
    let e1 = outerRounded[eIdx];
    let e2 = outerRounded[(eIdx + 1) % outerRounded.length];
    let emx = (e1[0] + e2[0]) * 0.5;
    let emy = (e1[1] + e2[1]) * 0.5;

    let ax = cent[0] - emx;
    let ay = cent[1] - emy;
    let alen = sqrt(ax * ax + ay * ay);

    if (alen > 18) {
      ax /= alen;
      ay /= alen;
      let nx = -ay;
      let ny = ax;
      let fissHalfW = random(2.6, 4.2);

      // Split the front half of the plate along the fissure, leaving the back half intact
      let stopPt = [
        lerp(emx, cent[0], random(0.75, 1.05)),
        lerp(emy, cent[1], random(0.75, 1.05))
      ];

      let bBack = clipHalfPlane(bevelPoly, stopPt, [-ax, -ay], 1.5);
      let bFront = clipHalfPlane(bevelPoly, stopPt, [ax, ay], 1.5);
      let bLeft = clipHalfPlane(bFront, stopPt, [nx, ny], -fissHalfW);
      let bRight = clipHalfPlane(bFront, stopPt, [-nx, -ny], -fissHalfW);

      let mBack = clipHalfPlane(mainInsetPoly, stopPt, [-ax, -ay], 1.5);
      let mFront = clipHalfPlane(mainInsetPoly, stopPt, [ax, ay], 1.5);
      let mLeft = clipHalfPlane(mFront, stopPt, [nx, ny], -(fissHalfW + 1.2));
      let mRight = clipHalfPlane(mFront, stopPt, [-nx, -ny], -(fissHalfW + 1.2));

      if (bBack.length >= 3) bevelLobes.push(bBack);
      if (bLeft.length >= 3) bevelLobes.push(bLeft);
      if (bRight.length >= 3) bevelLobes.push(bRight);

      if (mBack.length >= 3) mainLobes.push(mBack);
      if (mLeft.length >= 3) mainLobes.push(mLeft);
      if (mRight.length >= 3) mainLobes.push(mRight);

      hasFissure = true;
      fissureSeg = {
        x1: emx,
        y1: emy,
        x2: stopPt[0],
        y2: stopPt[1],
        x3: stopPt[0] + ax * random(10, 22) + nx * random(-6, 6),
        y3: stopPt[1] + ay * random(10, 22) + ny * random(-6, 6),
        nx: nx,
        ny: ny,
        halfW: fissHalfW
      };
    }
  }

  if (!hasFissure) {
    if (bevelPoly.length >= 3) bevelLobes.push(bevelPoly);
    if (mainInsetPoly.length >= 3) mainLobes.push(mainInsetPoly);
  }

  // Generate mottled tie-dye watercolor blooms inside the plate
  let paleBlooms = [];
  let darkBlooms = [];
  let radiusEst = sqrt(polyArea(outerBase) / PI);

  if (onCanvas && mainInsetPoly.length >= 3 && radiusEst > 22) {
    let numPale = floor(random(1, 4));
    for (let k = 0; k < numPale; k++) {
      let v = mainInsetPoly[floor(random(mainInsetPoly.length))];
      let t = random(0.15, 0.52);
      let bx = lerp(cent[0], v[0], t);
      let by = lerp(cent[1], v[1], t);
      let br = radiusEst * random(0.16, 0.34);
      paleBlooms.push({
        x: bx,
        y: by,
        r: br,
        colorIdx: floor(random(4))
      });
    }

    let numDark = floor(random(2, 5));
    for (let k = 0; k < numDark; k++) {
      let v = mainInsetPoly[floor(random(mainInsetPoly.length))];
      let t = random(0.05, 0.48);
      let bx = lerp(cent[0], v[0], t);
      let by = lerp(cent[1], v[1], t);
      let br = radiusEst * random(0.2, 0.42);
      darkBlooms.push({
        x: bx,
        y: by,
        r: br,
        colorIdx: floor(random(4))
      });
    }
  }

  return {
    rawCell,
    outerBase,
    outerRounded,
    detailedOuter,
    bevelLobes,
    mainLobes,
    corePoly,
    centroid: cent,
    onCanvas,
    isSecondary,
    hasFissure,
    fissureSeg,
    bevelColorIdx: floor(random(5)),
    mainColorIdx: floor(random(6)),
    glazeColorIdx: floor(random(4)),
    paleBlooms,
    darkBlooms
  };
}

// Compute Voronoi cell i clipped against all neighbor bisectors with optional inward offset
function computeCellPoly(i, seeds, bbox, offsetFn) {
  let poly = bbox.map((p) => [p[0], p[1]]);
  let pi = seeds[i];

  for (let j = 0; j < seeds.length; j++) {
    if (i === j) continue;
    let pj = seeds[j];
    let dx = pj[0] - pi[0];
    let dy = pj[1] - pi[1];
    let d = sqrt(dx * dx + dy * dy);
    if (d < 0.001 || d > 480) continue;

    let ux = dx / d;
    let uy = dy / d;
    let shift = offsetFn(i, j);
    let midX = (pi[0] + pj[0]) * 0.5 - ux * shift;
    let midY = (pi[1] + pj[1]) * 0.5 - uy * shift;

    poly = clipHalfPlane(poly, [midX, midY], [ux, uy], 0);
    if (poly.length < 3) return [];
  }
  return poly;
}

// Sutherland-Hodgman half-plane clipper: keeps points X where (X - pt) . normal <= bias
function clipHalfPlane(poly, pt, normal, bias = 0) {
  if (!poly || poly.length < 3) return [];
  let out = [];
  let n = poly.length;

  for (let i = 0; i < n; i++) {
    let cur = poly[i];
    let prev = poly[(i + n - 1) % n];
    let dCur = (cur[0] - pt[0]) * normal[0] + (cur[1] - pt[1]) * normal[1] - bias;
    let dPrev = (prev[0] - pt[0]) * normal[0] + (prev[1] - pt[1]) * normal[1] - bias;

    if (dCur <= 0) {
      if (dPrev > 0) {
        let t = dPrev / (dPrev - dCur);
        out.push([
          prev[0] + t * (cur[0] - prev[0]),
          prev[1] + t * (cur[1] - prev[1])
        ]);
      }
      out.push(cur);
    } else if (dPrev <= 0) {
      let t = dPrev / (dPrev - dCur);
      out.push([
        prev[0] + t * (cur[0] - prev[0]),
        prev[1] + t * (cur[1] - prev[1])
      ]);
    }
  }
  return out;
}

function chaikinCut(poly, ratio = 0.2) {
  if (!poly || poly.length < 3) return [];
  let res = [];
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let p0 = poly[i];
    let p1 = poly[(i + 1) % n];
    res.push([
      lerp(p0[0], p1[0], ratio),
      lerp(p0[1], p1[1], ratio)
    ]);
    res.push([
      lerp(p0[0], p1[0], 1 - ratio),
      lerp(p0[1], p1[1], 1 - ratio)
    ]);
  }
  return res;
}

function perturbPolygon(poly, subdivs = 3, amp = 2.0) {
  if (!poly || poly.length < 3) return [];
  let res = [];
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let p0 = poly[i];
    let p1 = poly[(i + 1) % n];
    let dx = p1[0] - p0[0];
    let dy = p1[1] - p0[1];
    let len = sqrt(dx * dx + dy * dy);
    let nx = len > 0.01 ? -dy / len : 0;
    let ny = len > 0.01 ? dx / len : 0;

    res.push([p0[0], p0[1]]);
    if (len > 14) {
      for (let s = 1; s < subdivs; s++) {
        let t = s / subdivs;
        let bx = lerp(p0[0], p1[0], t);
        let by = lerp(p0[1], p1[1], t);
        let nVal = (noise(bx * 0.018 + 50, by * 0.018 + 50) - 0.5) * 2.0;
        res.push([bx + nx * nVal * amp, by + ny * nVal * amp]);
      }
    }
  }
  return res;
}

function shrinkTowardPoint(poly, center, scaleFactor) {
  if (!poly || poly.length < 3) return [];
  return poly.map((v) => [
    lerp(center[0], v[0], scaleFactor),
    lerp(center[1], v[1], scaleFactor)
  ]);
}

function polyCentroid(poly) {
  if (!poly || poly.length === 0) return [0, 0];
  let cx = 0;
  let cy = 0;
  let a = 0;
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let p0 = poly[i];
    let p1 = poly[(i + 1) % n];
    let cross = p0[0] * p1[1] - p1[0] * p0[1];
    a += cross;
    cx += (p0[0] + p1[0]) * cross;
    cy += (p0[1] + p1[1]) * cross;
  }
  if (abs(a) < 1e-5) {
    let sx = 0, sy = 0;
    for (let p of poly) {
      sx += p[0];
      sy += p[1];
    }
    return [sx / n, sy / n];
  }
  a *= 3;
  return [cx / a, cy / a];
}

function polyArea(poly) {
  if (!poly || poly.length < 3) return 0;
  let a = 0;
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let p0 = poly[i];
    let p1 = poly[(i + 1) % n];
    a += p0[0] * p1[1] - p1[0] * p0[1];
  }
  return abs(a) * 0.5;
}

