// ============================================================================
// GEOMETRY GENERATORS & HELPERS
// ============================================================================

function foldShift(x, y) {
  // Subtle physical paper kink across the vertical, horizontal, and corner creases
  let dx = 0;
  let dy = 0;
  let distV = abs(x - FOLD_X);
  if (distV < 28) {
    dy += map(distV, 0, 28, 3.8, 0) * (x < FOLD_X ? -1 : 1);
    dx += map(distV, 0, 28, -2.2, 0);
  }
  let distH = abs(y - FOLD_Y);
  if (distH < 28) {
    dx += map(distH, 0, 28, 3.5, 0) * (y < FOLD_Y ? -1 : 1);
    dy += map(distH, 0, 28, -2.0, 0);
  }
  // Top-left diagonal dog-ear crease: x + y = 350
  let distD = abs((x + y) - 350);
  if (x < 360 && y < 360 && distD < 20) {
    let f = map(distD, 0, 20, 3.0, 0);
    dx += f;
    dy += f;
  }
  return [x + dx, y + dy];
}

function drawPolyShape(pts, curvature = 0.15, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function buildGeometries() {
  // 1. Irregular torn and charred parchment outline filling almost the entire 1200x1200 frame
  paperOutline = [];
  let margin = 30;
  let stepsPerSide = 48;

  // Top edge (left to right)
  for (let i = 0; i <= stepsPerSide; i++) {
    let t = i / stepsPerSide;
    let x = lerp(margin, 1200 - margin, t);
    let y = margin + (noise(x * 0.015, 1.1) - 0.5) * 16;
    // Crease notch at FOLD_X
    if (abs(x - FOLD_X) < 35) y += map(abs(x - FOLD_X), 0, 35, 15, 0);
    // Deep char bite at top-right corner
    if (x > 960) {
      let charT = map(x, 960, 1170, 0, 1);
      y += pow(charT, 1.7) * 85 + (noise(x * 0.06, 9.2) - 0.3) * 28;
    }
    paperOutline.push([x, y]);
  }

  // Right edge (top to bottom)
  for (let i = 1; i <= stepsPerSide; i++) {
    let t = i / stepsPerSide;
    let y = lerp(margin, 1200 - margin, t);
    let x = 1200 - margin + (noise(2.2, y * 0.015) - 0.5) * 16;
    if (y < 240) {
      let charT = map(y, margin, 240, 1, 0);
      x -= pow(charT, 1.6) * 75 + (noise(y * 0.06, 4.4) - 0.3) * 25;
    }
    if (abs(y - FOLD_Y) < 35) x -= map(abs(y - FOLD_Y), 0, 35, 16, 0);
    // Secondary singed notch at lower right
    if ( abs(y - 890) < 65 ) {
      x -= sin(map(y, 825, 955, 0, 180)) * 28;
    }
    paperOutline.push([x, y]);
  }

  // Bottom edge (right to left)
  for (let i = 1; i <= stepsPerSide; i++) {
    let t = i / stepsPerSide;
    let x = lerp(1200 - margin, margin, t);
    let y = 1200 - margin + (noise(x * 0.015, 3.3) - 0.5) * 16;
    if (abs(x - FOLD_X) < 35) y -= map(abs(x - FOLD_X), 0, 35, 15, 0);
    // Deep burnt eat-in at bottom-left
    if (x < 280) {
      let charT = map(x, 30, 280, 1, 0);
      y -= pow(charT, 1.5) * 90 + (noise(x * 0.05, 7.1) - 0.3) * 32;
    }
    paperOutline.push([x, y]);
  }

  // Left edge (bottom to top)
  for (let i = 1; i < stepsPerSide; i++) {
    let t = i / stepsPerSide;
    let y = lerp(1200 - margin, margin, t);
    let x = margin + (noise(4.4, y * 0.015) - 0.5) * 16;
    if (y > 920) {
      let charT = map(y, 920, 1170, 0, 1);
      x += pow(charT, 1.5) * 80 + (noise(y * 0.05, 8.8) - 0.3) * 26;
    }
    if (abs(y - FOLD_Y) < 35) x += map(abs(y - FOLD_Y), 0, 35, 15, 0);
    // Torn notch along upper-left
    if (abs(y - 310) < 40) {
      x += sin(map(y, 270, 350, 0, 180)) * 22;
    }
    paperOutline.push([x, y]);
  }

  // 2. Mainland Western Coastline Polygon (clipped inside neatline [86, 82, 1114, 1118])
  mainlandPoly = [];
  mainlandPoly.push([86, 82]);
  mainlandPoly.push([545, 82]);
  // Sweep down from top edge (545, 82) to left edge (86, 940) with bays and headlands
  let coastAnchors = [
    [545, 82], [510, 145], [560, 210], [470, 265], [390, 235],
    [350, 305], [440, 370], [485, 430], [395, 485], [295, 465],
    [245, 535], [315, 600], [260, 685], [185, 725], [235, 810],
    [165, 885], [86, 935]
  ];
  for (let i = 0; i < coastAnchors.length - 1; i++) {
    let p0 = coastAnchors[i];
    let p1 = coastAnchors[i + 1];
    let segs = 10;
    for (let s = 0; s < segs; s++) {
      let f = s / segs;
      let bx = lerp(p0[0], p1[0], f);
      let by = lerp(p0[1], p1[1], f);
      let n = (noise(bx * 0.025, by * 0.025) - 0.5) * 34 + (noise(bx * 0.08, by * 0.08) - 0.5) * 12;
      let px = constrain(bx + n, 88, 1110);
      let py = constrain(by + n * 0.6, 84, 1114);
      mainlandPoly.push(foldShift(px, py));
    }
  }
  mainlandPoly.push([86, 935]);

  // 3. Large Treasure Island Polygon in the south-east ("Isla de la Sombra")
  // Features a sheltered crescent cove around RED_X (748, 710)
  islandPoly = [];
  let islAnchors = [
    [650, 610], [720, 565], [820, 555], [925, 585], [1005, 650],
    [1035, 745], [1010, 855], [945, 945], [840, 985], [725, 965],
    [645, 905], [615, 815], [675, 775], [735, 785], [785, 750],
    [795, 695], [745, 665], [670, 675]
  ];
  for (let i = 0; i < islAnchors.length; i++) {
    let p0 = islAnchors[i];
    let p1 = islAnchors[(i + 1) % islAnchors.length];
    let segs = 8;
    for (let s = 0; s < segs; s++) {
      let f = s / segs;
      let bx = lerp(p0[0], p1[0], f);
      let by = lerp(p0[1], p1[1], f);
      let n = (noise(bx * 0.03 + 10, by * 0.03 + 10) - 0.5) * 22;
      islandPoly.push(foldShift(bx + n, by + n));
    }
  }

  // 4. Northern headland / island in upper-right quadrant
  northIslePoly = [];
  let nAnchors = [
    [740, 120], [845, 105], [960, 135], [1015, 205],
    [955, 265], [855, 250], [775, 275], [715, 210]
  ];
  for (let i = 0; i < nAnchors.length; i++) {
    let p0 = nAnchors[i];
    let p1 = nAnchors[(i + 1) % nAnchors.length];
    for (let s = 0; s < 6; s++) {
      let f = s / 6;
      let bx = lerp(p0[0], p1[0], f);
      let by = lerp(p0[1], p1[1], f);
      let n = (noise(bx * 0.04 + 25, by * 0.04) - 0.5) * 18;
      northIslePoly.push(foldShift(bx + n, by + n));
    }
  }

  // 5. Smaller rocky skerries & barrier islands
  let skerryDefs = [
    { x: 565, y: 465, rx: 34, ry: 22 },
    { x: 615, y: 525, rx: 22, ry: 15 },
    { x: 485, y: 895, rx: 45, ry: 26 },
    { x: 565, y: 945, rx: 25, ry: 18 },
    { x: 345, y: 1015, rx: 52, ry: 28 },
    { x: 1045, y: 520, rx: 28, ry: 42 }
  ];
  for (let sd of skerryDefs) {
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      let radNoise = 0.75 + noise(cos(a) * 1.5 + sd.x, sin(a) * 1.5 + sd.y) * 0.55;
      let px = sd.x + cos(a) * sd.rx * radNoise;
      let py = sd.y + sin(a) * sd.ry * radNoise;
      pts.push(foldShift(px, py));
    }
    skerryPolys.push(pts);
  }
}

// ============================================================================
// 1. DARK TABLETOP
// ============================================================================

function drawTabletop() {
  background(PAL.tableDark);
  brush.noFill();
  brush.noHatch();
  // Subtle dark wood grain at margins where torn paper exposes the board
  brush.set("2B", PAL.tableGrain, 1.4);
  for (let y = 8; y < 1192; y += 14) {
    if (y > 65 && y < 1130) {
      // Only draw near left & right margins to save strokes
      brush.line(4, y, 95, y + random(-3, 3));
      brush.line(1105, y, 1196, y + random(-3, 3));
    } else {
      brush.line(4, y, 1196, y + random(-4, 4));
    }
  }
}

// ============================================================================
// 2. PARCHMENT DROP SHADOW & BASE WATERCOLOR LAYERS
// ============================================================================

function drawParchmentBase() {
  brush.noStroke();
  brush.noHatch();

  // Multi-pass drop shadow under the paper perimeter so the sheet appears lift-able
  let shadowOffsets = [
    { dx: 12, dy: 14, col: "#050302", op: 155 },
    { dx: 7, dy: 8, col: "#090604", op: 190 }
  ];
  for (let sh of shadowOffsets) {
    brush.wash(sh.col, sh.op);
    brush.beginShape(0.15);
    for (let pt of paperOutline) {
      // Extra curl lift near corners and fold valleys
      let curl = 0;
      if (pt[0] > 950 && pt[1] < 250) curl = 7;
      if (pt[0] < 280 && pt[1] > 920) curl = 8;
      if (abs(pt[0] - FOLD_X) < 40 || abs(pt[1] - FOLD_Y) < 40) curl = 5;
      brush.vertex(pt[0] + sh.dx + curl * 0.6, pt[1] + sh.dy + curl);
    }
    brush.endShape(true);
    brush.noWash();
  }

  // Opaque solid parchment foundation wash so dark tabletop never bleeds through center
  brush.wash(PAL.paperBase, 245);
  drawPolyShape(paperOutline, 0.12, true);
  brush.noWash();

  // Translucent textured watercolor layer over the whole sheet
  brush.fill(PAL.paperWarm, 95);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.85, 0.45);
  drawPolyShape(paperOutline, 0.12, true);
  brush.noFill();
}

// ============================================================================
// 3. AGED WATERCOLOR WASHES, TEA STAINS & FOXING
