function drawBlobWash(cx, cy, rx, ry, col, op, bleed = 0.35, border = 0.55, seedOff = 0) {
  brush.noStroke();
  brush.fill(col, op);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(0.82, border);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 24) {
    let n = 0.65 + noise(cos(a) * 1.3 + seedOff, sin(a) * 1.3 + seedOff) * 0.7;
    let px = constrain(cx + cos(a) * rx * n, 45, 1155);
    let py = constrain(cy + sin(a) * ry * n, 45, 1155);
    brush.vertex(px, py);
  }
  brush.endShape(true);
  brush.noFill();
}

function drawPaperAgingAndStains() {
  // Batch 1: Sepia watercolor clouds
  let sepiaClouds = [
    [240, 210, 220, 180, 55, 1.1],
