function drawKinkedLine(x1, y1, x2, y2, brushName, col, w) {
  brush.set(brushName, col, w);
  let distTotal = dist(x1, y1, x2, y2);
  let steps = max(2, floor(distTotal / 18));
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let [kx, ky] = foldShift(x, y);
    // Slight pressure drop right across fold creases (ink wear)
    let p = 1.0;
    if (abs(x - FOLD_X) < 10 || abs(y - FOLD_Y) < 10) p = 0.35;
    pts.push([kx, ky, p]);
  }
  brush.spline(pts, 0.15);
}

function drawMapCartography() {
  brush.noFill();
  brush.noHatch();

  // --- A. Double-ruled Map Neatline & Degree Border ---
  let nl = { x1: 86, y1: 82, x2: 1114, y2: 1118 };
  let outerNl = { x1: 72, y1: 68, x2: 1128, y2: 1132 };

  // Clip neatline segments away from the heavily charred top-right and bottom-left corners
  drawKinkedLine(nl.x1, nl.y1, 980, nl.y1, "rotring", PAL.inkDark, 1.1);
  drawKinkedLine(outerNl.x1, outerNl.y1, 965, outerNl.y1, "rotring", PAL.inkDark, 1.8);

  drawKinkedLine(nl.x2, 220, nl.x2, nl.y2, "rotring", PAL.inkDark, 1.1);
  drawKinkedLine(outerNl.x2, 235, outerNl.x2, outerNl.y2, "rotring", PAL.inkDark, 1.8);

  drawKinkedLine(245, nl.y2, nl.x2, nl.y2, "rotring", PAL.inkDark, 1.1);
  drawKinkedLine(260, outerNl.y2, outerNl.x2, outerNl.y2, "rotring", PAL.inkDark, 1.8);

  drawKinkedLine(nl.x1, nl.y1, nl.x1, 945, "rotring", PAL.inkDark, 1.1);
  drawKinkedLine(outerNl.x1, outerNl.y1, outerNl.x1, 930, "rotring", PAL.inkDark, 1.8);

  // Alternating shaded degree boxes along neatline
  let tickStep = 64;
  for (let x = nl.x1; x < 950; x += tickStep) {
    let [tx, ty1] = foldShift(x, outerNl.y1);
    let [, ty2] = foldShift(x, nl.y1);
    brush.set("rotring", PAL.inkDark, 0.9);
    brush.line(tx, ty1, tx, ty2);
    if (floor((x - nl.x1) / tickStep) % 2 === 0) {
      for (let sy = ty1 + 3; sy < ty2 - 2; sy += 3.5) {
        brush.line(tx + 2, sy, min(tx + tickStep - 2, 965), sy);
      }
    }
  }
  for (let y = nl.y1; y < 920; y += tickStep) {
    let [tx1, ty] = foldShift(outerNl.x1, y);
    let [tx2, ] = foldShift(nl.x1, y);
    brush.set("rotring", PAL.inkDark, 0.9);
    brush.line(tx1, ty, tx2, ty);
    if (floor((y - nl.y1) / tickStep) % 2 === 1) {
      for (let sx = tx1 + 3; sx < tx2 - 2; sx += 3.5) {
        brush.line(sx, ty + 2, sx, min(ty + tickStep - 2, 930));
      }
    }
  }
  for (let x = 265; x < nl.x2 - 20; x += tickStep) {
    let [tx, ty1] = foldShift(x, nl.y2);
    let [, ty2] = foldShift(x, outerNl.y2);
    brush.set("rotring", PAL.inkDark, 0.9);
    brush.line(tx, ty1, tx, ty2);
    if (floor((x - 265) / tickStep) % 2 === 0) {
      for (let sy = ty1 + 3; sy < ty2 - 2; sy += 3.5) {
        brush.line(tx + 2, sy, min(tx + tickStep - 2, nl.x2), sy);
      }
    }
  }
  for (let y = 240; y < nl.y2 - 20; y += tickStep) {
    let [tx1, ty] = foldShift(nl.x2, y);
    let [tx2, ] = foldShift(outerNl.x2, y);
    brush.set("rotring", PAL.inkDark, 0.9);
    brush.line(tx1, ty, tx2, ty);
    if (floor((y - 240) / tickStep) % 2 === 0) {
      for (let sx = tx1 + 3; sx < tx2 - 2; sx += 3.5) {
        brush.line(sx, ty + 2, sx, min(ty + tickStep - 2, nl.y2));
      }
    }
  }

  // --- B. Portolan Rhumb Line Network & Drawn Compass Roses ---
  let roseNodes = [
    { x: 645, y: 315, r: 58, main: true },
    { x: 255, y: 845, r: 38, main: false }
  ];

  for (let rn of roseNodes) {
    for (let a = 0; a < 360; a += 11.25) {
      let isCardinal = (a % 90 === 0);
      let isHalf = (a % 45 === 0);
      if (!rn.main && !isHalf) continue;
      let col = isCardinal ? PAL.madderWash : (isHalf ? PAL.inkMid : PAL.inkGrid);
      let w = isCardinal ? 0.75 : (isHalf ? 0.55 : 0.38);

      // Ray clip to neatline box [88, 84, 1112, 1116]
      let dx = cos(a);
      let dy = sin(a);
      let tMax = 1600;
      if (dx > 0.001) tMax = min(tMax, (1112 - rn.x) / dx);
      if (dx < -0.001) tMax = min(tMax, (88 - rn.x) / dx);
      if (dy > 0.001) tMax = min(tMax, (1116 - rn.y) / dy);
      if (dy < -0.001) tMax = min(tMax, (84 - rn.y) / dy);

      // Avoid drawing into charred corners
      let ex = rn.x + dx * tMax;
      let ey = rn.y + dy * tMax;
      if (ex > 970 && ey < 230) tMax *= 0.78;
      if (ex < 250 && ey > 940) tMax *= 0.78;

      drawKinkedLine(
        rn.x + dx * (rn.r * 0.35),
        rn.y + dy * (rn.r * 0.35),
        rn.x + dx * tMax,
        rn.y + dy * tMax,
        "rotring", col, w
      );
    }
    drawCartographicRose(rn.x, rn.y, rn.r, rn.main);
  }

  // Latitude & Longitude Graticule lines
  for (let gx = 280; gx <= 960; gx += 220) {
    drawKinkedLine(gx, 84, gx, 1114, "rotring", PAL.inkFaint, 0.5);
  }
  for (let gy = 260; gy <= 960; gy += 220) {
    drawKinkedLine(88, gy, 1110, gy, "rotring", PAL.inkFaint, 0.5);
  }

  // --- C. Coastlines & Concentric Water-lining (Wave Hatching) ---
  drawCoastlineWithWaterlining(mainlandPoly, true);
  drawCoastlineWithWaterlining(islandPoly, false);
  drawCoastlineWithWaterlining(northIslePoly, false);
  for (let sk of skerryPolys) {
    drawCoastlineWithWaterlining(sk, false, 4);
  }

  // --- D. Inland Topography: Mountain Chains, Rivers, Marshes & Stippled Shoals ---
  drawInlandTopography();

  // --- E. Dotted Navigational Route & THE RED X ---
  drawPlottedRouteAndRedX();
}

function drawCartographicRose(cx, cy, r, isMain) {
  let [kx, ky] = foldShift(cx, cy);
  brush.noFill();
  brush.set("rotring", PAL.inkDark, 0.9);
  brush.circle(kx, ky, r, 0.08);
  brush.circle(kx, ky, r * 0.86, 0.08);
  brush.circle(kx, ky, r * 0.22, 0.08);

  let points = isMain ? 16 : 8;
  let step = 360 / points;
  for (let i = 0; i < points; i++) {
    let a = i * step - 90;
    let tipR = (i % 2 === 0) ? r : r * 0.72;
    let baseR = r * 0.22;
    let da = step * 0.38;

    let tx = kx + cos(a) * tipR;
    let ty = ky + sin(a) * tipR;
    let lx = kx + cos(a - da) * baseR;
    let ly = ky + sin(a - da) * baseR;
    let rx = kx + cos(a + da) * baseR;
    let ry = ky + sin(a + da) * baseR;
    let mx = kx + cos(a) * baseR * 0.6;
    let my = ky + sin(a) * baseR * 0.6;

    // Shade the right half of each wind point
    let shadeCol = (i === 0) ? PAL.redDark : PAL.inkDark;
    brush.set("quill", shadeCol, 0.75);
    for (let f = 0.15; f <= 0.9; f += 0.22) {
      brush.line(lerp(mx, tx, f), lerp(my, ty, f), lerp(rx, tx, f), lerp(ry, ty, f));
    }

    // Crisp outline of wind point
    brush.set("rotring", PAL.inkDark, 0.85);
    brush.line(tx, ty, lx, ly);
    brush.line(tx, ty, rx, ry);
  }

  // Ornate North Fleur-de-lis above the main rose
  if (isMain) {
    let ny = ky - r - 14;
    brush.set("quill", PAL.redAccent, 1.1);
    brush.line(kx, ky - r, kx, ny - 14);
    brush.spline([[kx, ny - 14, 1], [kx - 7, ny - 2, 1.2], [kx, ny + 6, 0.8]], 0.5);
    brush.spline([[kx, ny - 14, 1], [kx + 7, ny - 2, 1.2], [kx, ny + 6, 0.8]], 0.5);
    brush.spline([[kx, ny + 2, 1], [kx - 13, ny - 4, 1.1], [kx - 10, ny + 7, 0.7]], 0.6);
    brush.spline([[kx, ny + 2, 1], [kx + 13, ny - 4, 1.1], [kx + 10, ny + 7, 0.7]], 0.6);
  }
}

function drawCoastlineWithWaterlining(poly, isMainland, rings = 7) {
  // Calculate approximate centroid or push direction toward sea
  let cx = 0, cy = 0;
  for (let p of poly) { cx += p[0]; cy += p[1]; }
  cx /= poly.length;
  cy /= poly.length;
  if (isMainland) { cx = 140; cy = 220; }

  // 1. Draw concentric coastal water-lining rings radiating into the sea
  for (let rIdx = 1; rIdx <= rings; rIdx++) {
    let offsetDist = pow(rIdx, 1.28) * 3.8;
    let col = rIdx <= 2 ? PAL.inkDark : (rIdx <= 4 ? PAL.inkMid : PAL.inkFaint);
    let w = map(rIdx, 1, rings, 0.72, 0.35);
    brush.set("rotring", col, w);

    let ringPts = [];
    let startIdx = isMainland ? 2 : 0; // Skip top/left frame borders on mainland
    for (let i = startIdx; i < poly.length; i++) {
      let prev = poly[(i - 1 + poly.length) % poly.length];
      let curr = poly[i];
      let next = poly[(i + 1) % poly.length];

      // Outward normal
      let tx = next[0] - prev[0];
      let ty = next[1] - prev[1];
      let len = hypot(tx, ty) || 1;
      let nx = -ty / len;
      let ny = tx / len;

      // Ensure normal points away from land centroid
      if (nx * (curr[0] - cx) + ny * (curr[1] - cy) < 0) {
        nx = -nx;
        ny = -ny;
      }

      // Smooth out sharp concave corners as rings expand
      let px = curr[0] + nx * offsetDist;
      let py = curr[1] + ny * offsetDist;
      px = constrain(px, 88, 1110);
      py = constrain(py, 84, 1114);
      ringPts.push([px, py, 0.75]);
    }

    if (isMainland) {
      brush.spline(ringPts, 0.35);
    } else {
      ringPts.push(ringPts[0]);
      brush.spline(ringPts, 0.35);
    }
  }

  // 2. Primary bold dip-pen coastline contour
  let mainPts = [];
  let startIdx = isMainland ? 2 : 0;
  for (let i = startIdx; i < poly.length; i++) {
    let pt = poly[i];
    let p = 0.8 + noise(pt[0] * 0.04, pt[1] * 0.04) * 0.7;
    if (abs(pt[0] - FOLD_X) < 10 || abs(pt[1] - FOLD_Y) < 10) p = 0.3;
    mainPts.push([pt[0], pt[1], p]);
  }
  if (!isMainland) mainPts.push(mainPts[0]);
  brush.set("quill", PAL.inkDark, 1.35);
  brush.spline(mainPts, 0.25);

  // 3. Inner coastal cliff/bank hachure ticks along the shoreline
  brush.set("rotring", PAL.inkMid, 0.55);
  for (let i = startIdx + 1; i < poly.length - 1; i += 2) {
    let prev = poly[i - 1];
    let curr = poly[i];
    let next = poly[i + 1];
    let tx = next[0] - prev[0];
    let ty = next[1] - prev[1];
    let len = hypot(tx, ty) || 1;
    let nx = ty / len;
    let ny = -tx / len;
    if (nx * (curr[0] - cx) + ny * (curr[1] - cy) > 0) {
      nx = -nx;
      ny = -ny;
    }
    let hLen = random(4, 9);
    brush.line(curr[0], curr[1], curr[0] + nx * hLen, curr[1] + ny * hLen);
  }
}

function drawMountainChain(pts, scaleW = 22) {
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i];
    let p1 = pts[i + 1];
    let d = dist(p0[0], p0[1], p1[0], p1[1]);
    let steps = max(2, floor(d / 12));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let [mx, my] = foldShift(lerp(p0[0], p1[0], t), lerp(p0[1], p1[1], t));
      let w = scaleW * (0.65 + sin(t * 180) * 0.45) * random(0.85, 1.15);
      let h = w * 0.62;

      // Left sunlit slope
      brush.set("quill", PAL.inkDark, 0.8);
      brush.spline([[mx, my - h, 1.1], [mx - w * 0.5, my - h * 0.3, 0.8], [mx - w, my + 2, 0.4]], 0.3);
      // Right shaded slope with dense hachures
      brush.spline([[mx, my - h, 1.2], [mx + w * 0.5, my - h * 0.3, 1.0], [mx + w, my + 2, 0.5]], 0.3);
      brush.set("rotring", PAL.inkMid, 0.55);
      for (let k = 0.2; k <= 0.85; k += 0.2) {
        let sx = lerp(mx, mx + w, k);
        let sy = lerp(my - h, my + 2, k * 0.5);
        brush.line(sx, sy, sx + 4, my + 3);
      }
    }
  }
}

function drawCalligraphicLabel(x, y, length, scaleH, angleDeg = 0, isBold = false) {
  push();
  let [kx, ky] = foldShift(x, y);
  translate(kx, ky);
  rotate(angleDeg);
  brush.set("quill", isBold ? PAL.inkDark : PAL.inkMid, isBold ? 0.95 : 0.68);

  let cx = 0;
  let pts = [];
  while (cx < length) {
    let step = random(3.5, 6.5);
    let sy = (noise(cx * 0.25 + x, y) - 0.5) * scaleH;
    // Occasional tall ascender or low descender loop
    if (random() < 0.14) sy -= scaleH * 1.35;
    else if (random() < 0.12) sy += scaleH * 1.25;
    pts.push([cx, sy, random(0.5, 1.3)]);
    cx += step;
    if (random() < 0.18 && pts.length > 3) {
      brush.spline(pts, 0.45);
      pts = [];
      cx += random(5, 10);
    }
  }
  if (pts.length > 2) brush.spline(pts, 0.45);
  pop();
}

function drawInlandTopography() {
  // Mainland mountain ranges
  drawMountainChain([[140, 140], [250, 210], [210, 340], [150, 460]], 24);
  drawMountainChain([[280, 130], [365, 190], [315, 290]], 18);
  drawMountainChain([[145, 560], [205, 650], [140, 770]], 20);

  // Treasure Island mountain spine
  drawMountainChain([[720, 615], [845, 625], [935, 710], [895, 845], [760, 895]], 22);
  drawMountainChain([[835, 695], [865, 785]], 16);

  // Northern Isle hills
  drawMountainChain([[785, 165], [885, 175], [935, 215]], 16);

  // Winding Rivers
  brush.set("quill", PAL.inkDark, 0.95);
  let river1 = [[195, 230, 0.4], [245, 275, 0.7], [305, 285, 1.0], [355, 305, 1.4]].map(p => [...foldShift(p[0], p[1]), p[2]]);
  brush.spline(river1, 0.45);
  let river2 = [[165, 515, 0.4], [205, 535, 0.8], [248, 535, 1.3]].map(p => [...foldShift(p[0], p[1]), p[2]]);
  brush.spline(river2, 0.45);
  let river3 = [[855, 735, 0.4], [820, 725, 0.8], [785, 720, 1.3]].map(p => [...foldShift(p[0], p[1]), p[2]]);
  brush.spline(river3, 0.45);

  // Stippled sandbanks & shoals in bays and around RED_X cove
  let shoalCenters = [
    { x: 745, y: 725, rx: 52, ry: 40, count: 160 },
    { x: 430, y: 270, rx: 45, ry: 30, count: 95 },
    { x: 345, y: 495, rx: 48, ry: 32, count: 110 },
    { x: 590, y: 495, rx: 55, ry: 38, count: 120 },
    { x: 525, y: 920, rx: 60, ry: 35, count: 110 }
  ];
  brush.set("rotring", PAL.inkMid, 0.7);
  for (let sh of shoalCenters) {
    for (let i = 0; i < sh.count; i++) {
      let a = random(360);
      let r = sqrt(random()) * 0.95;
      let [sx, sy] = foldShift(sh.x + cos(a) * sh.rx * r, sh.y + sin(a) * sh.ry * r);
      brush.circle(sx, sy, random(0.5, 1.2), 0.2);
    }
    // Dotted shoal boundary
    for (let a = 0; a < 360; a += 12) {
      let [bx, by] = foldShift(sh.x + cos(a) * sh.rx, sh.y + sin(a) * sh.ry);
      brush.circle(bx, by, 0.7, 0.1);
    }
  }

  //Antique cartographic script labels & sea nomenclature
  drawCalligraphicLabel(135, 395, 145, 9, -8, true);
  drawCalligraphicLabel(150, 415, 110, 6, -8, false);
  drawCalligraphicLabel(755, 825, 165, 10, 5, true);
  drawCalligraphicLabel(775, 845, 125, 6, 5, false);
  drawCalligraphicLabel(780, 195, 120, 7, 4, false);
  drawCalligraphicLabel(460, 165, 180, 11, 12, true);
  drawCalligraphicLabel(530, 715, 95, 6, -18, false);
  drawCalligraphicLabel(295, 945, 130, 7, -4, false);

  // Bathymetric depth soundings (tiny dip-pen numerals/Crosses in coastal waters)
  brush.set("rotring", PAL.inkMid, 0.55);
  let soundings = [
    [420, 310], [455, 340], [380, 420], [520, 410], [545, 520],
    [660, 525], [695, 545], [615, 645], [635, 715], [705, 715],
    [715, 745], [685, 745], [585, 835], [440, 855], [385, 915]
  ];
  for (let s of soundings) {
    let [sx, sy] = foldShift(s[0], s[1]);
    brush.line(sx - 2, sy - 3, sx + 2, sy + 3);
    brush.line(sx + 4, sy - 3, sx + 2, sy + 3);
    brush.circle(sx - 5, sy, 1.2, 0.2);
  }
}

function drawPlottedRouteAndRedX() {
  // Winding expedition path from lower-left channel, passing under the brass compass,
  // threading the central islands, and curving into the hidden cove at RED_X (748, 710)
  let routeWaypoints = [
    [165, 1045], [245, 985], [330, 895], [385, 780], [435, 665],
    [490, 555], [545, 485], [635, 480], [705, 515], [685, 605],
    [640, 685], [670, 730], [715, 725], [RED_X.x, RED_X.y]
  ];

  // Interpolate smooth curve through waypoints and draw dashed/dotted dip-pen path
  let densePts = [];
  for (let i = 0; i < routeWaypoints.length - 1; i++) {
    let p0 = routeWaypoints[max(0, i - 1)];
    let p1 = routeWaypoints[i];
    let p2 = routeWaypoints[i + 1];
    let p3 = routeWaypoints[min(routeWaypoints.length - 1, i + 2)];
    for (let s = 0; s < 16; s++) {
      let t = s / 16;
      // Catmull-Rom interpolation
      let t2 = t * t;
      let t3 = t2 * t;
      let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      densePts.push(foldShift(x, y));
    }
  }

  // Draw alternating dash + dot segments along the route
  let accum = 0;
  for (let i = 0; i < densePts.length - 1; i++) {
    let a = densePts[i];
    let b = densePts[i + 1];
    let segLen = dist(a[0], a[1], b[0], b[1]);
    accum += segLen;
    let phase = floor(accum / 9) % 3;
    if (phase === 0) {
      brush.set("quill", PAL.inkDark, 1.35);
      brush.line(a[0], a[1], b[0], b[1]);
    } else if (phase === 1 && i % 2 === 0) {
      brush.set("rotring", PAL.inkDark, 1.1);
      brush.circle(a[0], a[1], 1.1, 0.2);
    }
  }

  // Small navigational cross-ticks and anchor mark at key turning points
  let navTicks = [routeWaypoints[2], routeWaypoints[6], routeWaypoints[8], routeWaypoints[10]];
  brush.set("rotring", PAL.inkDark, 0.85);
  for (let nt of navTicks) {
    let [nx, ny] = foldShift(nt[0], nt[1]);
    brush.circle(nx, ny, 4.5, 0.15);
    brush.line(nx - 6, ny, nx + 6, ny);
    brush.line(nx, ny - 6, nx, ny + 6);
  }

  // ==========================================================================
  // THE RED X (Venetian Red / Madder Accent) at (748, 710)
  // ==========================================================================
  let [rx, ry] = foldShift(RED_X.x, RED_X.y);

  // 1. Subtle crimson watercolor ink-bleed halo into the damp parchment fibers
  drawBlobWash(rx, ry, 28, 25, PAL.redAccent, 52, 0.42, 0.55, 99.1);
  drawBlobWash(rx + 3, ry - 2, 16, 15, PAL.redBright, 65, 0.35, 0.65, 102.4);

  // 2. Dotted crimson ring & callout note around the Red X
  brush.set("quill", PAL.redDark, 0.9);
  for (let a = 0; a < 360; a += 18) {
    let a1 = a + random(-3, 3);
    let a2 = a + 9 + random(-2, 2);
    let rad = 32 + sin(a * 3) * 2;
    brush.line(
      rx + cos(a1) * rad, ry + sin(a1) * rad,
      rx + cos(a2) * rad, ry + sin(a2) * rad
    );
  }

  // 3. Bold hand-drawn dip-pen strokes forming the Red X
  // Stroke 1: Top-left to bottom-right (multi-pass quill with serif splays & ink pooling)
  let xSize = 21;
  let arm1A = [rx - xSize, ry - xSize * 0.92];
  let arm1B = [rx + xSize * 1.05, ry + xSize * 0.98];
  let arm2A = [rx + xSize * 0.95, ry - xSize * 1.02];
  let arm2B = [rx - xSize * 1.02, ry + xSize * 0.95];

  for (let off = -2.2; off <= 2.2; off += 0.85) {
    brush.set("quill", PAL.redAccent, 1.8 - abs(off) * 0.35);
    brush.spline([
      [arm1A[0] + off * 0.6, arm1A[1] - off * 0.5, 1.3],
      [rx + off * 0.4, ry - off * 0.3, 1.6],
      [arm1B[0] + off * 0.7, arm1B[1] - off * 0.5, 1.1]
    ], 0.25);

    brush.spline([
      [arm2A[0] + off * 0.5, arm2A[1] + off * 0.6, 1.3],
      [rx + off * 0.3, ry + off * 0.4, 1.6],
      [arm2B[0] + off * 0.6, arm2B[1] + off * 0.5, 1.1]
    ], 0.25);
  }

  // Vivid crimson core & dark dried-ink center pool
  brush.set("rotring", PAL.redBright, 1.5);
  brush.line(arm1A[0], arm1A[1], arm1B[0], arm1B[1]);
  brush.line(arm2A[0], arm2A[1], arm2B[0], arm2B[1]);

  brush.set("quill", PAL.redDark, 1.4);
  brush.line(arm1A[0] - 2, arm1A[1] + 2, arm1B[0] + 1, arm1B[1] + 1);
  brush.line(arm2A[0] + 2, arm2A[1] + 2, arm2B[0] - 1, arm2B[1] + 1);
  brush.circle(rx, ry, 4.5, 0.3);

  // Tiny ink splatter droplets around the Red X
  let splatters = [
    [-26, -18, 1.8], [24, -22, 1.4], [28, 15, 2.1],
    [-19, 25, 1.5], [12, 27, 1.1], [-29, 4, 1.2]
  ];
  for (let sp of splatters) {
    brush.set("rotring", PAL.redDark, 1.1);
    brush.circle(rx + sp[0], ry + sp[1], sp[2], 0.25);
  }
}

