function drawCreasesAndPinholes() {
  brush.noStroke();
  brush.noHatch();

  // --- A. Vertical Fold Valley (x = FOLD_X = 580) ---
  // Graded watercolor shadow along the right slope of the valley
  brush.fill(PAL.umberWash, 48);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.75, 0.3);
  brush.rect(FOLD_X - 2, 42, 26, 1115, "corner");
  brush.fill(PAL.darkUmber, 35);
  brush.rect(FOLD_X - 1, 42, 11, 1115, "corner");
  brush.noFill();

  // --- B. Horizontal Fold Valley (y = FOLD_Y = 540) ---
  // Graded watercolor shadow along the bottom slope of the valley
  brush.fill(PAL.umberWash, 46);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.75, 0.3);
  brush.rect(42, FOLD_Y - 2, 1115, 24, "corner");
  brush.fill(PAL.darkUmber, 34);
  brush.rect(42, FOLD_Y - 1, 1115, 10, "corner");
  brush.noFill();

  // --- C. Fine Graphite/Charcoal Shading & Cracked Paper-Fiber Highlight Along Creases ---
  // Vertical fold lines
  for (let y = 42; y < 1145; y += 28) {
    let jitter1 = (noise(y * 0.03, 1.5) - 0.5) * 3.5;
    let jitter2 = (noise((y + 28) * 0.03, 1.5) - 0.5) * 3.5;
    // Shadow trough
    brush.set("2B", PAL.darkUmber, 1.15);
    brush.line(FOLD_X + jitter1 + 2, y, FOLD_X + jitter2 + 2, y + 28);
    brush.set("charcoal", PAL.umberWash, 0.8);
    brush.line(FOLD_X + jitter1 + 6, y, FOLD_X + jitter2 + 6, y + 28);

    // Bright worn ridge highlight on left lip of crease
    brush.set("cpencil", PAL.paperLight, 1.35);
    brush.line(FOLD_X + jitter1 - 2.5, y, FOLD_X + jitter2 - 2.5, y + 28);
    brush.set("rotring", PAL.brassSpec, 0.65);
    brush.line(FOLD_X + jitter1 - 1.5, y + 3, FOLD_X + jitter2 - 1.5, y + 24);

    // Tiny lateral stress cracks branching off the fold
    if (random() < 0.45) {
      brush.set("2H", PAL.paperLight, 0.7);
      let side = random() < 0.5 ? -1 : 1;
      brush.line(FOLD_X + jitter1, y + 10, FOLD_X + jitter1 + side * random(8, 22), y + 10 + random(-6, 6));
    }
  }

  // Horizontal fold lines
  for (let x = 42; x < 1145; x += 28) {
    let jitter1 = (noise(x * 0.03, 5.5) - 0.5) * 3.5;
    let jitter2 = (noise((x + 28) * 0.03, 5.5) - 0.5) * 3.5;
    // Shadow trough
    brush.set("2B", PAL.darkUmber, 1.15);
    brush.line(x, FOLD_Y + jitter1 + 2, x + 28, FOLD_Y + jitter2 + 2);
    brush.set("charcoal", PAL.umberWash, 0.8);
    brush.line(x, FOLD_Y + jitter1 + 6, x + 28, FOLD_Y + jitter2 + 6);

    // Bright worn ridge highlight on top lip of crease
    brush.set("cpencil", PAL.paperLight, 1.35);
    brush.line(x, FOLD_Y + jitter1 - 2.5, x + 28, FOLD_Y + jitter2 - 2.5);
    brush.set("rotring", PAL.brassSpec, 0.65);
    brush.line(x + 3, FOLD_Y + jitter1 - 1.5, x + 24, FOLD_Y + jitter2 - 1.5);
  }

  // Central cross-fold wear hole (where the two folds intersect at 580, 540)
  drawBlobWash(FOLD_X, FOLD_Y, 18, 16, PAL.darkUmber, 65, 0.3, 0.6, 55.5);
  brush.set("rotring", PAL.tableDark, 1.6);
  brush.circle(FOLD_X, FOLD_Y, 3.2, 0.4);
  brush.set("cpencil", PAL.paperLight, 1.1);
  brush.arc(FOLD_X, FOLD_Y, 4.8, -30, 110);

  // Diagonal corner dog-ear crease from (36, 314) to (316, 34)
  for (let t = 0; t < 1; t += 0.08) {
    let x1 = lerp(36, 316, t);
    let y1 = lerp(314, 34, t);
    let x2 = lerp(36, 316, t + 0.08);
    let y2 = lerp(314, 34, t + 0.08);
    brush.set("charcoal", PAL.umberWash, 1.2);
    brush.line(x1 + 3, y1 + 3, x2 + 3, y2 + 3);
    brush.set("2B", PAL.darkUmber, 0.9);
    brush.line(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
    brush.set("cpencil", PAL.paperLight, 1.25);
    brush.line(x1 - 2, y1 - 2, x2 - 2, y2 - 2);
  }

  // Secondary lower-right crease from (960, 1158) to (1158, 920)
  for (let t = 0; t < 1; t += 0.1) {
    let x1 = lerp(960, 1158, t);
    let y1 = lerp(1158, 920, t);
    let x2 = lerp(960, 1158, t + 0.1);
    let y2 = lerp(1158, 920, t + 0.1);
    brush.set("charcoal", PAL.umberWash, 1.0);
    brush.line(x1 - 3, y1 - 3, x2 - 3, y2 - 3);
    brush.set("cpencil", PAL.paperLight, 1.15);
    brush.line(x1 + 2, y1 + 2, x2 + 2, y2 + 2);
  }

  // --- D. Trompe-l'oeil Pinholes (Corner Tack Holes & Divider Pricks on Map) ---
  let pinholes = [
    { x: 64, y: 62, r: 3.4, rust: true },
    { x: 935, y: 58, r: 3.2, rust: true },
    { x: 1138, y: 245, r: 3.0, rust: true },
    { x: 1136, y: 1138, r: 3.5, rust: true },
    { x: 275, y: 1142, r: 3.2, rust: true },
    { x: 58, y: 915, r: 3.2, rust: true },
    // Divider pricks at map nodes
    { x: 645, y: 315, r: 2.2, rust: false },
    { x: 255, y: 845, r: 2.0, rust: false },
    { x: 545, y: 485, r: 2.1, rust: false },
    { x: RED_X.x, y: RED_X.y, r: 2.4, rust: false }
  ];

  for (let ph of pinholes) {
    let [px, py] = foldShift(ph.x, ph.y);
    if (ph.rust) {
      drawBlobWash(px, py, 14, 13, PAL.umberWash, 55, 0.35, 0.65, px * 0.1);
    }
    // Raised paper burr rim catching top-left light on its bottom-right lip
    brush.set("cpencil", PAL.brassSpec, 1.3);
    brush.arc(px, py, ph.r + 1.6, -25, 115);
    // Tiny shadow on top-left lip
    brush.set("rotring", PAL.darkUmber, 1.0);
    brush.arc(px, py, ph.r + 1.0, 145, 295);
    // Pitch-black hole center exposing table underneath
    brush.noStroke();
    brush.wash(PAL.tableDark, 250);
    brush.circle(px, py, ph.r, 0.2);
    brush.noWash();
  }
}

function drawCharredMargins() {
  // Singed, toasted umber & charcoal smudge along the irregular paper perimeter
  let n = paperOutline.length;

  // 1. Toasted golden-brown & raw umber heat halo just inside the burnt edges
  for (let i = 0; i < n; i += 2) {
    let p0 = paperOutline[i];
    let p1 = paperOutline[(i + 2) % n];

    // Vector pointing inward toward canvas center (600, 600)
    let vx = 600 - p0[0];
    let vy = 600 - p0[1];
    let vLen = hypot(vx, vy) || 1;
    vx /= vLen;
    vy /= vLen;

    // Determine char intensity (heaviest at top-right, bottom-left, and fold notches)
    let isHeavyChar = (p0[0] > 940 && p0[1] < 260) ||
                      (p0[0] < 290 && p0[1] > 910) ||
                      (abs(p0[0] - FOLD_X) < 40) ||
                      (abs(p0[1] - FOLD_Y) < 40) ||
                      (p0[0] > 1100 && abs(p0[1] - 890) < 65);

    let smudgeDepth = isHeavyChar ? random(22, 46) : random(8, 18);

    // Soft soot smudge inward
    brush.set("soot_smudge", PAL.umberWash, isHeavyChar ? 1.5 : 0.85);
    brush.line(
      p0[0] + vx * 4, p0[1] + vy * 4,
      p0[0] + vx * smudgeDepth, p0[1] + vy * smudgeDepth
    );

    if (isHeavyChar) {
      brush.set("soot_smudge", PAL.bistre, 1.3);
      brush.line(
        p0[0] + vx * 2, p0[1] + vy * 2,
        p0[0] + vx * (smudgeDepth * 0.55), p0[1] + vy * (smudgeDepth * 0.55)
      );
    }

    // Charcoal smudge right along the scorched margin
    brush.set("charcoal", isHeavyChar ? PAL.charcoal : PAL.bistre, isHeavyChar ? 1.8 : 1.1);
    brush.line(p0[0], p0[1], p1[0], p1[1]);

    // Crisp charred black rim & brittle ash cracks
    brush.set("2B", PAL.charcoal, isHeavyChar ? 1.5 : 0.9);
    brush.line(p0[0] + vx * 1.5, p0[1] + vy * 1.5, p1[0] + vx * 1.5, p1[1] + vy * 1.5);

    if (isHeavyChar && random() < 0.5) {
      brush.set("quill", PAL.charcoal, 0.85);
      let crackLen = random(10, 26);
      brush.line(
        p0[0], p0[1],
        p0[0] + vx * crackLen + random(-6, 6),
        p0[1] + vy * crackLen + random(-6, 6)
      );
    }

    // Paper thickness edge highlight on top- and left-facing torn edges
    if (!isHeavyChar && (p0[0] < 80 || p0[1] < 80)) {
      brush.set("cpencil", PAL.paperLight, 1.1);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Loose charcoal dust & ash flecks near the heavily charred corners
  let charZones = [
    { x: 1055, y: 125, r: 95 },
    { x: 135, y: 1065, r: 105 },
    { x: 1135, y: 890, r: 50 }
  ];
  for (let cz of charZones) {
    for (let i = 0; i < 65; i++) {
      let a = random(360);
      let d = random(cz.r);
      let ax = cz.x + cos(a) * d;
      let ay = cz.y + sin(a) * d;
      brush.set("charcoal", random() < 0.6 ? PAL.charcoal : PAL.bistre, random(0.5, 1.4));
      brush.circle(ax, ay, random(0.6, 2.2), 0.4);
    }
  }
}

