function drawBrassCompass() {
  let cx = COMPASS.x;
  let cy = COMPASS.y;
  let R = COMPASS.r;

  // --- A. Real Soft Cast Shadow Across the Drawn Sea (Light from Top-Left -135 deg) ---
  brush.noStroke();
  brush.noHatch();

  let shadowLayers = [
    { dx: 48, dy: 54, r: R + 16, col: PAL.umberWash, op: 42, bleed: 0.48 },
    { dx: 34, dy: 38, r: R + 8, col: PAL.darkUmber, op: 58, bleed: 0.38 },
    { dx: 20, dy: 23, r: R + 2, col: PAL.bistre, op: 72, bleed: 0.25 },
    { dx: 9, dy: 11, r: R - 2, col: PAL.charcoal, op: 88, bleed: 0.12 }
  ];

  for (let sl of shadowLayers) {
    brush.fill(sl.col, sl.op);
    brush.fillBleed(sl.bleed, "out");
    brush.fillTexture(0.75, 0.35);
    brush.circle(cx + sl.dx, cy + sl.dy, sl.r, 0.06);
    brush.noFill();
  }

  // Soft charcoal penumbra hatching in the cast shadow so drawn sea remains subtly visible beneath
  for (let a = -35; a <= 125; a += 4) {
    let rIn = R - 5;
    let rOut = R + 48 * pow(cos(a - 45), 1.4);
    if (rOut > rIn + 4) {
      brush.set("soot_smudge", PAL.bistre, 0.9);
      brush.line(
        cx + cos(a) * rIn + 8, cy + sin(a) * rIn + 10,
        cx + cos(a) * rOut + 22, cy + sin(a) * rOut + 25
      );
    }
  }

  // --- B. Top-Left Brass Suspension Bow (Ring) & Knurled Crown ---
  let stemAngle = -132;
  let ux = cos(stemAngle);
  let uy = sin(stemAngle);
  let px = -uy;
  let py = ux;

  let crownX = cx + ux * (R + 18);
  let crownY = cy + uy * (R + 18);
  let ringX = cx + ux * (R + 46);
  let ringY = cy + uy * (R + 46);
  let ringR = 36;

  // Cast shadow of the ring and crown onto the parchment
  brush.set("soot_smudge", PAL.bistre, 1.8);
  brush.circle(ringX + 14, ringY + 16, ringR, 0.08);
  brush.set("charcoal", PAL.charcoal, 2.2);
  brush.circle(ringX + 9, ringY + 11, ringR, 0.06);
  brush.noStroke();
  brush.wash(PAL.bistre, 110);
  brush.circle(crownX + 10, crownY + 12, 22, 0.1);
  brush.noWash();

  // Brass suspension ring (thick torus rendered with concentric metallic strokes)
  for (let dr = -6.5; dr <= 6.5; dr += 1.3) {
    let col = abs(dr) < 2.0 ? PAL.brassBright : (dr < 0 ? PAL.brassMid : PAL.brassDark);
    brush.set("cpencil", col, 1.4);
    brush.circle(ringX, ringY, ringR + dr, 0.04);
  }
  // Specular highlights on ring catching top-left window light
  brush.set("rotring", PAL.brassSpec, 1.5);
  brush.arc(ringX, ringY, ringR - 2, -175, -80);
  brush.arc(ringX, ringY, ringR + 2, 10, 75);
  brush.set("rotring", PAL.brassDark, 1.1);
  brush.circle(ringX, ringY, ringR + 7, 0.04);
  brush.circle(ringX, ringY, ringR - 7, 0.04);

  // Brass Stem & Knurled Crown
  let stemPts = [
    [cx + ux * (R - 2) - px * 15, cy + uy * (R - 2) - py * 15],
    [cx + ux * (R + 28) - px * 21, cy + uy * (R + 28) - py * 21],
    [cx + ux * (R + 28) + px * 21, cy + uy * (R + 28) + py * 21],
    [cx + ux * (R - 2) + px * 15, cy + uy * (R - 2) + py * 15]
  ];
  brush.noStroke();
  brush.wash(PAL.brassUmber, 245);
  drawPolyShape(stemPts, 0.08, true);
  brush.noWash();

  // Knurled ridges across the crown
  for (let s = -18; s <= 18; s += 3.5) {
    let col = s < -4 ? PAL.brassBright : (s < 6 ? PAL.brassGold : PAL.brassDark);
    brush.set("rotring", col, 1.15);
    brush.line(
      cx + ux * R + px * s, cy + uy * R + py * s,
      cx + ux * (R + 27) + px * (s * 1.12), cy + uy * (R + 27) + py * (s * 1.12)
    );
  }
  brush.set("rotring", PAL.brassSpec, 1.4);
  brush.line(
    cx + ux * (R + 2) - px * 10, cy + uy * (R + 2) - py * 10,
    cx + ux * (R + 26) - px * 12, cy + uy * (R + 26) - py * 12
  );

  // --- C. Stepped Antique Brass Casing (Bezel) ---
  brush.noStroke();
  brush.wash(PAL.brassDark, 255);
  brush.circle(cx, cy, R, 0.02);
  brush.noWash();

  let dialR = R - 26;

  // Radial anisotropic metallic reflections around the 26px brass bezel
  for (let a = 0; a < 360; a += 1.5) {
    // Realistic cylindrical/toroidal metallic specular lobes
    let l1 = exp(-pow(angleDiff(a, -135) / 28, 2)); // Primary window light (top-left)
    let l2 = exp(-pow(angleDiff(a, 42) / 35, 2)) * 0.78; // Secondary rim reflex (bottom-right)
    let l3 = exp(-pow(angleDiff(a, -38) / 22, 2)) * 0.45; // Side sheen
    let dark1 = exp(-pow(angleDiff(a, -75) / 30, 2));
    let dark2 = exp(-pow(angleDiff(a, 130) / 38, 2));

    let lum = constrain(0.35 + l1 * 0.75 + l2 + l3 - dark1 * 0.35 - dark2 * 0.3, 0, 1);
    let col = PAL.brassUmber;
    if (lum > 0.86) col = PAL.brassSpec;
    else if (lum > 0.68) col = PAL.brassBright;
    else if (lum > 0.48) col = PAL.brassGold;
    else if (lum > 0.28) col = PAL.brassMid;
    else col = PAL.brassDark;

    brush.set("cpencil", col, 1.35);
    brush.line(
      cx + cos(a) * (dialR + 1), cy + sin(a) * (dialR + 1),
      cx + cos(a) * (R - 1), cy + sin(a) * (R - 1)
    );
  }

  // Concentric machined brass bezel grooves & stepped bevels
  let bezelSteps = [
    { r: R, col: PAL.brassDark, w: 1.6 },
    { r: R - 3, col: PAL.brassGold, w: 1.1 },
    { r: R - 8, col: PAL.brassDark, w: 1.3 },
    { r: R - 11, col: PAL.brassMid, w: 1.0 },
    { r: R - 18, col: PAL.brassDark, w: 1.5 },
    { r: dialR + 2, col: PAL.brassGold, w: 1.1 },
    { r: dialR, col: PAL.charcoal, w: 1.6 }
  ];
  for (let bs of bezelSteps) {
    brush.set("rotring", bs.col, bs.w);
    brush.circle(cx, cy, bs.r, 0.02);
  }

  // Razor-sharp specular highlight arcs along the stepped brass bevels
  brush.set("rotring", PAL.brassSpec, 1.8);
  brush.arc(cx, cy, R - 2, -168, -98);
  brush.arc(cx, cy, R - 10, -162, -104);
  brush.arc(cx, cy, dialR + 3, -155, -110);
  brush.set("rotring", PAL.brassBright, 1.3);
  brush.arc(cx, cy, R - 9, 18, 72);
  brush.arc(cx, cy, dialR + 2, 12, 78);

  // Subtle verdigris & tarnish specks in the bezel grooves
  for (let i = 0; i < 28; i++) {
    let a = random(360);
    let gr = random() < 0.5 ? R - 8 : R - 18;
    brush.set("2B", random() < 0.45 ? PAL.verdigris : PAL.brassDark, random(0.6, 1.3));
    brush.circle(cx + cos(a) * gr, cy + sin(a) * gr, random(0.8, 2.2), 0.3);
  }

  // --- D. Recessed Compass Dial Face & Markings ---
  brush.noStroke();
  brush.wash(PAL.dialFace, 252);
  brush.circle(cx, cy, dialR, 0.01);
  brush.noWash();

  // Warm aged patina inside the dial face
  brush.fill(PAL.paperWarm, 55);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.65, 0.35);
  brush.circle(cx, cy, dialR - 2, 0.02);
  brush.noFill();

  // Inner crescent shadow cast by the raised brass rim onto the top-left of the dial face
  for (let s = 1; s <= 16; s += 2) {
    let col = s < 7 ? PAL.bistre : PAL.dialShadow;
    brush.set("charcoal", col, map(s, 1, 16, 1.8, 0.6));
    brush.arc(cx + s * 0.55, cy + s * 0.6, dialR - s * 0.45, 132, 318);
  }

  // Precision degree track & minute rings on the dial
  brush.set("rotring", PAL.inkDark, 0.85);
  brush.circle(cx, cy, dialR - 5, 0.01);
  brush.circle(cx, cy, dialR - 15, 0.01);
  brush.circle(cx, cy, dialR - 24, 0.01);

  for (let a = 0; a < 360; a += 2) {
    let isTen = (a % 10 === 0);
    let isThirty = (a % 30 === 0);
    let rOuter = dialR - 5;
    let rInner = isThirty ? dialR - 23 : (isTen ? dialR - 15 : dialR - 11);
    brush.set("rotring", PAL.inkDark, isThirty ? 0.9 : (isTen ? 0.65 : 0.4));
    brush.line(
      cx + cos(a) * rInner, cy + sin(a) * rInner,
      cx + cos(a) * rOuter, cy + sin(a) * rOuter
    );
  }

  // Engraved 8-point compass rose star on the dial face
  let starR = dialR - 28;
  for (let i = 0; i < 8; i++) {
    let a = i * 45 - 90;
    let tipR = (i % 2 === 0) ? starR : starR * 0.68;
    let baseR = 18;
    let tx = cx + cos(a) * tipR;
    let ty = cy + sin(a) * tipR;
    let lx = cx + cos(a - 20) * baseR;
    let ly = cy + sin(a - 20) * baseR;
    let rx = cx + cos(a + 20) * baseR;
    let ry = cy + sin(a + 20) * baseR;

    // Fill right half of star point with dense ink lines
    brush.set("rotring", i === 0 ? PAL.redDark : PAL.inkDark, 0.7);
    for (let f = 0.15; f <= 0.9; f += 0.2) {
      brush.line(
        lerp(cx, tx, f), lerp(cy, ty, f),
        lerp(rx, tx, f), lerp(ry, ty, f)
      );
    }
    brush.set("rotring", PAL.inkDark, 0.8);
    brush.line(tx, ty, lx, ly);
    brush.line(tx, ty, rx, ry);
  }

  // Cardinal Letters (N, E, S, W)
  drawDialCardinalLetters(cx, cy, dialR - 36);

  // --- E. Compass Needle & Shadow on Dial ---
  let needleAngle = -68; // Pointing NNW
  let nLen = dialR - 16;
  let nx = cos(needleAngle);
  let ny = sin(needleAngle);
  let npx = -ny;
  let npy = nx;

  // 1. Sharp shadow of the floating needle cast onto the dial face below (offset +7, +8)
  let sdx = 7, sdy = 8;
  brush.set("charcoal", PAL.dialShadow, 1.9);
  brush.line(cx - nx * nLen + sdx, cy - ny * nLen + sdy, cx + nx * nLen + sdx, cy + ny * nLen + sdy);
  brush.set("rotring", PAL.bistre, 1.3);
  brush.line(cx - nx * nLen + sdx, cy - ny * nLen + sdy, cx + nx * nLen + sdx, cy + ny * nLen + sdy);
  brush.circle(cx + sdx, cy + sdy, 11, 0.08);

  // 2. South Half of Needle (Blued Steel)
  let southTip = [cx - nx * nLen, cy - ny * nLen];
  let southMidL = [cx - nx * (nLen * 0.42) - npx * 7.5, cy - ny * (nLen * 0.42) - npy * 7.5];
  let southMidR = [cx - nx * (nLen * 0.42) + npx * 7.5, cy - ny * (nLen * 0.42) + npy * 7.5];
  brush.noStroke();
  brush.wash(PAL.steelDark, 250);
  drawPolyShape([[cx, cy], southMidL, southTip, southMidR], 0.04, true);
  brush.noWash();
  brush.set("rotring", PAL.steelMid, 1.1);
  brush.line(cx, cy, southTip[0], southTip[1]);
  brush.line(southMidL[0], southMidL[1], southTip[0], southTip[1]);

  // 3. North Half of Needle (Venetian Red Accent Tip + Blued Base)
  let northTip = [cx + nx * nLen, cy + ny * nLen];
  let northMidL = [cx + nx * (nLen * 0.48) - npx * 8.0, cy + ny * (nLen * 0.48) - npy * 8.0];
  let northMidR = [cx + nx * (nLen * 0.48) + npx * 8.0, cy + ny * (nLen * 0.48) + npy * 8.0];
  brush.noStroke();
  brush.wash(PAL.redAccent, 250);
  drawPolyShape([[cx, cy], northMidL, northTip, northMidR], 0.04, true);
  brush.noWash();

  // Bright crimson facet on sunlit side & dark madder facet on shadow side
  brush.set("rotring", PAL.redBright, 1.35);
  brush.line(cx, cy, northTip[0], northTip[1]);
  brush.line(northMidL[0], northMidL[1], northTip[0], northTip[1]);
  brush.set("rotring", PAL.redDark, 1.2);
  brush.line(northMidR[0], northMidR[1], northTip[0], northTip[1]);

  // 4. Central Brass Pivot Cap & Screw Slot
  brush.noStroke();
  brush.wash(PAL.brassDark, 255);
  brush.circle(cx, cy, 13, 0.03);
  brush.wash(PAL.brassGold, 250);
  brush.circle(cx - 1, cy - 1, 10, 0.03);
  brush.noWash();
  brush.set("rotring", PAL.brassSpec, 1.5);
  brush.arc(cx, cy, 8, -170, -60);
  brush.set("rotring", PAL.charcoal, 1.2);
  brush.line(cx - 5, cy - 3, cx + 5, cy + 3);

  // --- F. Convex Glass Dome Mirroring a Mullioned Studio Window ---
  drawCompassGlassWindowReflection(cx, cy, dialR);
}

function angleDiff(a, b) {
  let d = (a - b + 540) % 360 - 180;
  return d;
}

function drawDialCardinalLetters(cx, cy, r) {
  brush.set("rotring", PAL.redDark, 1.25);
  // N (top)
  let nx = cx, ny = cy - r;
  brush.line(nx - 5, ny + 6, nx - 5, ny - 6);
  brush.line(nx - 5, ny - 6, nx + 5, ny + 6);
  brush.line(nx + 5, ny + 6, nx + 5, ny - 6);

  brush.set("rotring", PAL.inkDark, 1.1);
  // E (right)
  let ex = cx + r, ey = cy;
  brush.line(ex - 4, ey - 6, ex - 4, ey + 6);
  brush.line(ex - 4, ey - 6, ex + 4, ey - 6);
  brush.line(ex - 4, ey, ex + 2, ey);
  brush.line(ex - 4, ey + 6, ex + 4, ey + 6);

  // S (bottom)
  let sx = cx, sy = cy + r;
  brush.spline([[sx + 4, sy - 5, 1], [sx - 4, sy - 3, 1], [sx + 4, sy + 3, 1], [sx - 4, sy + 5, 1]], 0.5);

  // W (left)
  let wx = cx - r, wy = cy;
  brush.line(wx - 6, wy - 5, wx - 3, wy + 5);
  brush.line(wx - 3, wy + 5, wx, wy - 2);
  brush.line(wx, wy - 2, wx + 3, wy + 5);
  brush.line(wx + 3, wy + 5, wx + 6, wy - 5);
}

function domePanePoint(cx, cy, u, v) {
  // Maps normalized window grid (u in [0,1] along arc, v in [0,1] radial) onto spherical glass dome
  let angle = lerp(-166, -86, u);
  let rad = lerp(42, 114, v) * (1 - 0.12 * sin(u * 180));
  return [cx + cos(angle) * rad, cy + sin(angle) * rad];
}

function drawCompassGlassWindowReflection(cx, cy, dialR) {
  // 2 columns x 3 rows of curved window panes warped by the convex glass dome
  let uSplits = [
    [0.0, 0.45],
    [0.53, 1.0]
  ];
  let vSplits = [
    [0.0, 0.29],
    [0.36, 0.65],
    [0.72, 1.0]
  ];

  brush.noStroke();
  brush.noHatch();

  for (let ui = 0; ui < uSplits.length; ui++) {
    for (let vi = 0; vi < vSplits.length; vi++) {
      let u0 = uSplits[ui][0], u1 = uSplits[ui][1];
      let v0 = vSplits[vi][0], v1 = vSplits[vi][1];

      let poly = [];
      for (let s = 0; s <= 6; s++) poly.push(domePanePoint(cx, cy, lerp(u0, u1, s / 6), v1));
      for (let s = 0; s <= 4; s++) poly.push(domePanePoint(cx, cy, u1, lerp(v1, v0, s / 4)));
      for (let s = 0; s <= 6; s++) poly.push(domePanePoint(cx, cy, lerp(u1, u0, s / 6), v0));
      for (let s = 0; s <= 4; s++) poly.push(domePanePoint(cx, cy, u0, lerp(v0, v1, s / 4)));

      // Luminous sky reflection wash inside each pane (brightest toward outer top-left rim)
      let op = map(vi, 0, 2, 42, 82) + (ui === 0 ? 15 : 0);
      brush.wash(PAL.windowSky, op);
      drawPolyShape(poly, 0.15, true);
      brush.noWash();

      // Soft dry-pencil diagonal glass sheen across each reflected window pane
      brush.set("cpencil", PAL.brassSpec, 1.15);
      for (let f = 0.15; f <= 0.85; f += 0.22) {
        let pA = domePanePoint(cx, cy, lerp(u0, u1, f), v0 + 0.03);
        let pB = domePanePoint(cx, cy, lerp(u0, u1, min(1, f + 0.12)), v1 - 0.03);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Crisp specular edge highlight along the outer curve of the top panes
      if (vi === 2) {
        let arcPts = [];
        for (let s = 0; s <= 8; s++) {
          let pt = domePanePoint(cx, cy, lerp(u0, u1, s / 8), v1 - 0.02);
          arcPts.push([pt[0], pt[1], 1.2]);
        }
        brush.set("rotring", PAL.brassSpec, 1.5);
        brush.spline(arcPts, 0.35);
      }
    }
  }

  // Secondary bottom-right curved caustic rim reflex on the glass dome
  for (let rOff = 8; rOff <= 16; rOff += 2.5) {
    brush.set("cpencil", PAL.windowSky, map(rOff, 8, 16, 1.3, 0.6));
    brush.arc(cx, cy, dialR - rOff, 14, 76);
  }
  brush.set("rotring", PAL.brassSpec, 1.1);
  brush.arc(cx, cy, dialR - 6, 22, 66);

  // Fine micro-scratches on the convex glass surface catching the window light
  brush.set("2H", PAL.brassSpec, 0.65);
  brush.line(cx - 58, cy - 62, cx - 24, cy - 48);
  brush.line(cx - 42, cy - 78, cx - 15, cy - 71);
  brush.line(cx + 35, cy + 52, cx + 62, cy + 34);
}

// ============================================================================
// 7. TROMPE-L'OEIL OBJECT 2: STUB OF BEESWAX CANDLE
// ============================================================================

function drawBeeswaxCandle() {
  let wx = CANDLE.x;
  let wy = CANDLE.y;
  let R = CANDLE.r;

  // --- A. Long Soft Cast Shadow Across the Map (Taller object = longer shadow) ---
  brush.noStroke();
  brush.noHatch();

  let waxShadows = [
    { dx: 72, dy: 80, rx: R + 24, ry: R + 16, col: PAL.umberWash, op: 44, bleed: 0.48 },
    { dx: 52, dy: 58, rx: R + 14, ry: R + 10, col: PAL.darkUmber, op: 58, bleed: 0.38 },
    { dx: 32, dy: 36, rx: R + 6, ry: R + 4, col: PAL.bistre, op: 75, bleed: 0.25 },
    { dx: 14, dy: 16, rx: R, ry: R, col: PAL.charcoal, op: 95, bleed: 0.12 }
  ];

  for (let ws of waxShadows) {
    drawBlobWash(wx + ws.dx, wy + ws.dy, ws.rx, ws.ry, ws.col, ws.op, ws.bleed, 0.35, ws.dx);
  }

  // Soft charcoal hatching along the candle shadow
  for (let a = -25; a <= 115; a += 5) {
    let rIn = R - 8;
    let rOut = R + 78 * pow(cos(a - 45), 1.5);
    if (rOut > rIn + 6) {
      brush.set("soot_smudge", PAL.bistre, 0.95);
      brush.line(
        wx + cos(a) * rIn + 10, wy + sin(a) * rIn + 12,
        wx + cos(a) * rOut + 28, wy + sin(a) * rOut + 32
      );
    }
  }

  // --- B. Spilled & Cooled Beeswax Drips Pooled onto the Parchment ---
  let waxDrips = [
    { a: -145, dist: R + 14, r: 22 },
    { a: -95, dist: R + 18, r: 26 },
    { a: -65, dist: R + 32, r: 16 },
    { a: -15, dist: R + 15, r: 24 },
    { a: 35, dist: R + 22, r: 28 },
    { a: 62, dist: R + 38, r: 17 },
    { a: 118, dist: R + 16, r: 25 },
    { a: 165, dist: R + 20, r: 21 }
  ];

  for (let wd of waxDrips) {
    let dx = wx + cos(wd.a) * wd.dist;
    let dy = wy + sin(wd.a) * wd.dist;

    // Tiny shadow under each wax drip lobe
    brush.noStroke();
    brush.wash(PAL.bistre, 105);
    brush.circle(dx + 4, dy + 4.5, wd.r, 0.18);

    // Translucent warm beeswax lobe
    brush.wash(PAL.waxMid, 210);
    brush.circle(dx, dy, wd.r, 0.18);
    brush.wash(PAL.waxWarm, 185);
    brush.circle(dx - 2, dy - 2, wd.r * 0.78, 0.15);
    brush.noWash();

    // Glossy edge highlight on top-left of drip
    brush.set("cpencil", PAL.waxLight, 1.3);
    brush.arc(dx, dy, wd.r - 2, -175, -65);
    brush.set("rotring", PAL.waxSpec, 1.1);
    brush.arc(dx, dy, wd.r - 3, -155, -95);
    brush.set("rotring", PAL.waxDark, 0.85);
    brush.arc(dx, dy, wd.r, 15, 135);
  }

  // --- C. Cylindrical Candle Stub Body & Organic Melted Rim ---
  let outerPts = [];
  let rimPts = [];
  for (let a = 0; a < 360; a += 10) {
    let n1 = 0.9 + noise(cos(a) * 1.6 + 12, sin(a) * 1.6 + 12) * 0.24;
    let n2 = 0.86 + noise(cos(a) * 1.8 + 44, sin(a) * 1.8 + 44) * 0.25;
    // Slight perspective offset: top crater is shifted (-4, -4) toward top-left camera/light
    outerPts.push([wx + cos(a) * R * n1, wy + sin(a) * R * n1]);
    rimPts.push([wx - 4 + cos(a) * (R - 14) * n2, wy - 4 + sin(a) * (R - 14) * n2]);
  }

  // Base beeswax body fill
  brush.noStroke();
  brush.wash(PAL.waxMid, 250);
  drawPolyShape(outerPts, 0.25, true);
  brush.noWash();

  // Radial shading around the vertical wax wall between outerPts and rimPts
  for (let i = 0; i < outerPts.length; i++) {
    let a = i * 10;
    let pOut = outerPts[i];
    let pIn = rimPts[i];
    let isSunlit = (a >= 165 || a <= -35);
    let col = isSunlit ? PAL.waxWarm : PAL.waxDark;
    brush.set("cpencil", col, 1.6);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }

  // Top recessed wax crater (cup)
  brush.noStroke();
  brush.wash(PAL.waxWarm, 248);
  drawPolyShape(rimPts, 0.25, true);
  brush.noWash();

  // Translucent warm honey-cream glow on the raised wax rim
  brush.fill(PAL.waxLight, 135);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.7, 0.35);
  drawPolyShape(rimPts, 0.25, true);
  brush.noFill();

  // Concave bowl shading inside the melted wax cup (shadow on top-left inner wall, glow on bottom-right inner wall)
  let cupX = wx - 4;
  let cupY = wy - 4;
  let cupR = R - 18;

  for (let r = cupR; r >= 10; r -= 3.5) {
    // Inner top-left slope shaded inside the crater
    let colTL = r > cupR * 0.55 ? PAL.waxMid : PAL.waxDark;
    brush.set("cpencil", colTL, 1.45);
    brush.arc(cupX, cupY, r, 145, 315);

    // Inner bottom-right slope catching subsurface honey-amber light
    let colBR = r > cupR * 0.45 ? PAL.waxLight : PAL.waxWarm;
    brush.set("cpencil", colBR, 1.45);
    brush.arc(cupX, cupY, r, -45, 145);
  }

  // Deep amber molten pool around the base of the wick
  drawBlobWash(cupX, cupY, 24, 22, PAL.waxDark, 95, 0.3, 0.5, 88.2);

  // Raised wax lip highlights around the crater rim
  let rimSpline = [];
  for (let i = 0; i <= rimPts.length; i++) {
    let pt = rimPts[i % rimPts.length];
    let a = (i * 10) % 360;
    let p = (a > 170 || a < 290) ? 1.4 : 0.6;
    rimSpline.push([pt[0], pt[1], p]);
  }
  brush.set("cpencil", PAL.waxLight, 1.5);
  brush.spline(rimSpline, 0.35);
  brush.set("rotring", PAL.waxSpec, 1.35);
  brush.arc(cupX, cupY, cupR + 3, 185, 290);
  brush.arc(cupX, cupY, cupR + 2, 10, 80);

  // Solidified rivulets dripping over the rim
  let rivuletAngles = [-145, -95, -15, 35, 118];
  for (let ra of rivuletAngles) {
    let rx1 = cupX + cos(ra) * (cupR + 2);
    let ry1 = cupY + sin(ra) * (cupR + 2);
    let rx2 = wx + cos(ra) * (R + 8);
    let ry2 = wy + sin(ra) * (R + 8);
    brush.set("cpencil", PAL.waxLight, 1.6);
    brush.line(rx1, ry1, rx2, ry2);
    brush.set("rotring", PAL.waxSpec, 1.0);
    brush.line(rx1 - 1, ry1 - 1, rx2 - 1, ry2 - 1);
  }

  // --- D. Charred Twisted Cotton Wick & Snuffed Ember ---
  // Wick shadow inside the wax bowl
  brush.set("charcoal", PAL.waxDark, 1.8);
  brush.spline([
    [cupX + 2, cupY + 2, 1.2],
    [cupX - 6, cupY - 4, 1.1],
    [cupX - 14, cupY - 1, 0.9]
  ], 0.4);

  // Wicked braided base (wax-soaked cream/umber) transitioning to charred black tip
  brush.set("2B", PAL.paperLight, 2.2);
  brush.line(cupX, cupY, cupX - 5, cupY - 5);
  brush.set("charcoal", PAL.charcoal, 2.1);
  brush.spline([
    [cupX - 3, cupY - 3, 1.1],
    [cupX - 11, cupY - 10, 1.4],
    [cupX - 19, cupY - 7, 1.6]
  ], 0.45);

  // Tiny glowing red-orange ember at the very tip of the snuffed wick
  brush.set("rotring", PAL.redAccent, 1.8);
  brush.circle(cupX - 19, cupY - 7, 2.4, 0.2);
  brush.set("rotring", PAL.redBright, 1.3);
  brush.circle(cupX - 19.5, cupY - 7.5, 1.2, 0.1);

  // Subtle soot specks in the wax pool around the wick
  for (let i = 0; i < 14; i++) {
    let sa = random(360);
    let sd = random(4, 18);
    brush.set("2B", PAL.charcoal, random(0.5, 1.1));
    brush.circle(cupX + cos(sa) * sd, cupY + sin(sa) * sd, random(0.5, 1.3), 0.3);
  }
}

// Hyperreal Eroded Limestone Stele with Half-Dissolved Glyph Registers & Lichen Rosettes
// Raking dawn light from the left; charcoal mass recesses, burnished graphite planes,
