let heightMap;
let erosionMap;
let lichenMap;     // >0 for sage, <0 for sienna (magnitude = density)
let shadowMap;
let illumMap;

let slabLeftEdge = [];
let slabRightEdge = [];
let slabTopEdge = [];
let glyphSegments = [];
let lichenColonies = [];
let majorCracks = [];
let karstPits = [];
let spallBasins = [];

