    scatter: 3.2,
    opacity: 32,
    spacing: 0.65,
    pressure: [0.8, 1.0, 0.7],
    rotate: "random",
    noise: 0.8
  });

  buildMonumentData();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#131413");

  // 1. Deep museum/moorland dawn void surrounding the frontal slab
  renderDarkSurround();

  // 2. Base mineral watercolor washes on the limestone stele
  renderSlabBaseWashes();

  // 3. Charcoal massing for deep recesses, spall basins & right shadow flank
  renderCharcoalRecessMasses();

  // 4. Burnished graphite pencil layers across sunlit & raking-lit stone planes
  renderBurnishedGraphitePlanes();

  // 5. Sedimentary strata, tooth-chisel dressing & point-chisel scars
  renderChiselToolingAndStrata();

  // 6. Architectural crown panel, 12-rayed solar rosette & register rules
  renderCrownAndRegisterRules();

  // 7. Half-dissolved carved glyph registers in raking left light
  renderGlyphRegisters();

  // 8. Karst dissolution pits, fossil cavities & major structural fractures
  renderPitsAndFractures();

  // 9. Raw sienna & sage green watercolour washes for lichen rosettes
  renderLichenWatercolourWashes();

  // 10. Tactile crustose/foliose lichen lobes, apothecia & cast micro-shadows
  renderLichenTactileDetails();

  // 11. Final cold limestone grit, left arris raking highlights & plinth anchor
  renderFinalSurfaceGritAndArris();

  noLoop();
}

// ============================================================================
// STEP 0: MATHEMATICAL HEIGHTFIELD, EROSION, GLYPHS & RAKING SHADOW ENGINE
// ============================================================================

function fbm(x, y, octaves = 4) {
  let val = 0;
  let amp = 0.5;
  let freq = 1.0;
  for (let i = 0; i < octaves; i++) {
    val += amp * noise(x * freq, y * freq);
    freq *= 2.07;
    amp *= 0.48;
  }
  return val;
}

function buildMonumentData() {
  heightMap = new Float32Array(GRID_W * GRID_H);
  erosionMap = new Float32Array(GRID_W * GRID_H);
  lichenMap = new Float32Array(GRID_W * GRID_H);
  shadowMap = new Float32Array(GRID_W * GRID_H);
  illumMap = new Float32Array(GRID_W * GRID_H);

  // 1. Define slab outer silhouette edges (in 1200x1200 coords)
  for (let y = 0; y <= 1200; y++) {
    let nL = fbm(0.4, y * 0.008, 4) * 18 - 9;
    let nR = fbm(8.4, y * 0.008, 4) * 20 - 10;

    // Deep frost-spalled notches on left edge
    let notch1 = Math.exp(-Math.pow((y - 315) / 22, 2)) * 11;
    let notch2 = Math.exp(-Math.pow((y - 632) / 28, 2)) * 16;
    let notch3 = Math.exp(-Math.pow((y - 930) / 18, 2)) * 9;

    // Right edge erosion & upper-right ancient diagonal break
    let breakR = 0;
    if (y < 215) {
      let t = (215 - y) / 170;
      breakR = Math.pow(Math.max(0, t), 1.45) * 155 + fbm(y * 0.04, 2.1, 3) * 14;
    }
    let chipR = Math.exp(-Math.pow((y - 590) / 34, 2)) * 14;

    // Plinth widening at bottom (y > 1148)
    let plinthOffset = y > 1148 ? 42 + fbm(y * 0.05, 1.1, 2) * 8 : 0;

    slabLeftEdge[y] = 278 + nL + notch1 + notch2 + notch3 - plinthOffset;
    slabRightEdge[y] = 922 + nR - breakR - chipR + plinthOffset;
  }

  for (let x = 0; x <= 1200; x++) {
    let arch = Math.pow((x - 585) / 320, 2) * 24;
    let nT = fbm(x * 0.012, 0.7, 4) * 16;
    let dip = Math.exp(-Math.pow((x - 515) / 35, 2)) * 12;
    let cornerBreak = x > 730 ? Math.pow((x - 730) / 190, 1.55) * 155 : 0;
    slabTopEdge[x] = 44 + arch + nT + dip + cornerBreak;
  }

  // 2. Define Spall Basins (delaminated patches where stone surface flaked off)
  spallBasins = [
    { x: 715, y: 405, rx: 95, ry: 58, depth: 0.42, seed: 11 },
    { x: 445, y: 725, rx: 88, ry: 48, depth: 0.38, seed: 23 },
    { x: 645, y: 925, rx: 110, ry: 54, depth: 0.36, seed: 37 },
    { x: 355, y: 495, rx: 62, ry: 44, depth: 0.32, seed: 51 },
    { x: 810, y: 745, rx: 75, ry: 68, depth: 0.45, seed: 67 },
    { x: 525, y: 285, rx: 58, ry: 35, depth: 0.28, seed: 83 }
  ];

  // 3. Define Lichen Colonies (type: +1 = grey-green sage, -1 = raw sienna orange)
  lichenColonies = [
    // Prominent colonies over glyph registers & moisture fissures
    { x: 425, y: 632, r: 66, type: 1, seed: 101 },   // Large sage rosette on Crack 1
    { x: 472, y: 618, r: 34, type: -1, seed: 102 },  // Raw sienna cluster beside it
    { x: 382, y: 392, r: 58, type: 1, seed: 103 },   // Sage rosette on Reg 2 left
    { x: 428, y: 422, r: 28, type: -1, seed: 104 },  // Raw sienna satellite
    { x: 688, y: 608, r: 54, type: -1, seed: 105 },  // Raw sienna rosette on Crack 1 right
    { x: 735, y: 585, r: 46, type: 1, seed: 106 },   // Sage partner
    { x: 538, y: 172, r: 44, type: 1, seed: 107 },   // Lower-left of crown solar rosette
    { x: 568, y: 192, r: 25, type: -1, seed: 108 },  // Orange accent on cornice
    { x: 748, y: 502, r: 50, type: 1, seed: 109 },   // Reg 3 right sage colony
    { x: 520, y: 518, r: 32, type: -1, seed: 110 },  // Reg 3 center raw sienna
    { x: 635, y: 842, r: 62, type: 1, seed: 111 },   // Reg 6 large sage rosette
    { x: 590, y: 868, r: 30, type: -1, seed: 112 },  // Reg 6 raw sienna satellite
    { x: 368, y: 942, r: 48, type: 1, seed: 113 },   // Reg 7 left sage colony
    { x: 488, y: 822, r: 26, type: -1, seed: 114 },  // Raw sienna near fossil cavity
    { x: 795, y: 320, r: 38, type: 1, seed: 115 },   // Upper right sage
    { x: 342, y: 765, r: 33, type: -1, seed: 116 }   // Left margin raw sienna
  ];

  // 4. Populate base heightfield and erosion map
  for (let gy = 0; gy < GRID_H; gy++) {
    let y = gy * CELL;
    let xL = slabLeftEdge[y];
    let xR = slabRightEdge[y];

    for (let gx = 0; gx < GRID_W; gx++) {
      let x = gx * CELL;
      let idx = gy * GRID_W + gx;
      let yT = slabTopEdge[x];

      if (x < xL || x > xR || y < yT || y > 1192) {
        heightMap[idx] = 0.0;
        erosionMap[idx] = 1.0;
        continue;
      }

      // Distance from edges for 3D stone bevels/chamfers
      let dLeft = x - xL;
      let dRight = xR - x;
      let dTop = y - yT;

      let bevelL = Math.min(1.0, dLeft / (22 + fbm(0.2, y * 0.03, 2) * 14));
      let bevelR = Math.min(1.0, dRight / (34 + fbm(5.2, y * 0.03, 2) * 18));
      let bevelT = Math.min(1.0, dTop / (28 + fbm(x * 0.03, 0.2, 2) * 16));
      let edgeProfile = Math.pow(bevelL * bevelR * bevelT, 0.55);

      // Macro limestone undulation + faint sedimentary bedding planes
      let macroWave = fbm(x * 0.0028, y * 0.0022, 4) * 0.26;
      let strata = Math.sin(y * 0.045 + x * 0.006 + fbm(x * 0.01, y * 0.01, 2) * 3.5) * 0.018;
      let microGrain = (noise(x * 0.09, y * 0.09) - 0.5) * 0.028;

      // Subtle convexity on left-center, slight hollowing on right
      let camber = Math.sin(((x - xL) / (xR - xL)) * 180) * 0.12;

      let h = 0.55 + edgeProfile * (0.35 + macroWave + camber + strata + microGrain);

      // Sunken tympanum panel in the crown (y = 82..210, x = 338..855)
      if (y > 82 && y < 210 && x > 338 && x < 855 && dTop > 26 && dRight > 28) {
        let bx = Math.min(x - 338, 855 - x);
        let by = Math.min(y - 82, 210 - y);
        let bEdge = Math.min(1.0, Math.min(bx, by) / 10.0);
        h -= 0.085 * bEdge;
      }

      // Erosion field: combines spall basins + high-frequency weathering
      let ero = fbm(x * 0.0055 + 12.3, y * 0.0055 + 4.7, 4) * 0.65;
      if (dLeft < 40) ero += (40 - dLeft) / 55;
      if (dRight < 55) ero += (55 - dRight) / 60;
      if (dTop < 45) ero += (45 - dTop) / 45;
      if (y > 980) ero += (y - 980) / 260;

      for (let b of spallBasins) {
        let dx = (x - b.x) / b.rx;
        let dy = (y - b.y) / b.ry;
        let dist = Math.sqrt(dx * dx + dy * dy);
        let warp = (fbm(x * 0.025 + b.seed, y * 0.025, 3) - 0.5) * 0.42;
        let eff = dist + warp;
        if (eff < 1.0) {
          // Stepped delamination lip
          let step = eff < 0.82 ? 1.0 : (1.0 - eff) / 0.18;
          h -= b.depth * 0.18 * step;
          ero += 0.65 * step;
        }
      }

      // Lichen height & coverage contribution
      let lichVal = 0;
      for (let col of lichenColonies) {
        let dx = x - col.x;
        let dy = y - col.y;
        let d = Math.sqrt(dx * dx + dy * dy);
        if (d < col.r * 1.35) {
          let ang = Math.atan2(dy, dx);
          // Scalloped radiating lobes
          let lobe = Math.sin(ang * 14 + col.seed) * 0.12 +
                     Math.cos(ang * 23 - col.seed * 2) * 0.08 +
                     (fbm(x * 0.04 + col.seed, y * 0.04, 3) - 0.5) * 0.35;
          let normD = d / (col.r * (0.85 + lobe));
          if (normD < 1.0) {
            // Raised lobed margin & warty areolate interior
            let ring = Math.sin(normD * 18) * 0.25 + 0.75;
            let strength = Math.pow(1.0 - normD, 0.45) * ring;
            h += 0.032 * strength;
            ero += 0.55 * strength;
            if (Math.abs(strength) > Math.abs(lichVal)) {
              lichVal = col.type * strength;
            }
          }
        }
      }

      heightMap[idx] = h;
      erosionMap[idx] = constrain(ero, 0, 1.35);
      lichenMap[idx] = lichVal;
    }
  }

  // 5. Generate Major Cracks & Carve into Heightfield
  buildMajorCracks();

  // 6. Generate Epigraphic Glyph Registers & Crown Solar Rosette
  buildCrownAndGlyphs();

  // 7. Generate Karst Dissolution Pits & Fossil Impressions
  buildKarstPits();

  // 8. Compute Raking Left Light Illumination & Self-Shadowing
  computeLightingAndShadows();
}

function carveGrooveInGrid(x1, y1, x2, y2, halfWidth, depth, respectErosion = true) {
  let dist = Math.hypot(x2 - x1, y2 - y1);
  let steps = Math.max(2, Math.ceil(dist / 1.5));
  let rGrid = Math.ceil(halfWidth / CELL) + 1;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let cx = x1 + (x2 - x1) * t;
    let cy = y1 + (y2 - y1) * t;
    let gx0 = Math.floor(cx / CELL);
    let gy0 = Math.floor(cy / CELL);

    for (let dy = -rGrid; dy <= rGrid; dy++) {
      let gy = gy0 + dy;
      if (gy < 1 || gy >= GRID_H - 1) continue;
      for (let dx = -rGrid; dx <= rGrid; dx++) {
        let gx = gx0 + dx;
        if (gx < 1 || gx >= GRID_W - 1) continue;
        let px = gx * CELL;
        let py = gy * CELL;
        let d = Math.hypot(px - cx, py - cy);
        if (d < halfWidth) {
          let idx = gy * GRID_W + gx;
          if (heightMap[idx] <= 0.05) continue;
          let ero = erosionMap[idx];
          let effDepth = depth;
          if (respectErosion) {
            effDepth *= Math.max(0.06, 1.0 - ero * 0.78);
          }
          // V-cut profile
          let vCut = 1.0 - d / halfWidth;
          heightMap[idx] -= effDepth * vCut;
        }
      }
    }
  }
}

function buildMajorCracks() {
  // 4 major structural fractures across the monument
  let crackDefs = [
    // Crack 1: Deep trans-slab fracture from left notch (282, 632) to right (915, 588)
    {
      pts: [
        [280, 632], [355, 642], [435, 635], [520, 648],
        [610, 628], [705, 612], [815, 604], [916, 588]
      ],
      width: 7.5, depth: 0.18
    },
    // Crack 2: Upper-right shear crack through solar rosette into Reg 2
    {
      pts: [
        [775, 108], [712, 138], [648, 168], [612, 235],
        [595, 315], [568, 392], [552, 468]
      ],
      width: 6.2, depth: 0.15
    },
    // Crack 2B: Branch from Crack 2
    {
      pts: [
        [598, 305], [648, 342], [715, 378], [785, 425]
      ],
      width: 4.5, depth: 0.11
    },
    // Crack 3: Basal vertical frost fissure
    {
      pts: [
        [462, 1152], [455, 1075], [472, 995], [468, 912], [492, 835]
      ],
      width: 5.8, depth: 0.14
    },
    // Crack 4: Left upper fissure
    {
      pts: [
        [282, 315], [348, 328], [412, 312], [465, 338]
      ],
      width: 4.8, depth: 0.12
    }
  ];

  for (let cd of crackDefs) {
    let detailed = [];
    for (let i = 0; i < cd.pts.length - 1; i++) {
      let p1 = cd.pts[i];
      let p2 = cd.pts[i + 1];
      let segs = 12;
      for (let s = 0; s < segs; s++) {
        let t = s / segs;
        let x = lerp(p1[0], p2[0], t);
        let y = lerp(p1[1], p2[1], t);
        let jitter = (fbm(x * 0.035, y * 0.035, 3) - 0.5) * 14 * Math.sin(t * 180);
        let jx = (noise(x * 0.08, y * 0.08) - 0.5) * 6;
        detailed.push([x + jx, y + jitter]);
      }
    }
    detailed.push(cd.pts[cd.pts.length - 1]);
    majorCracks.push({ pts: detailed, width: cd.width, depth: cd.depth });

    for (let i = 0; i < detailed.length - 1; i++) {
      let a = detailed[i];
      let b = detailed[i + 1];
      carveGrooveInGrid(a[0], a[1], b[0], b[1], cd.width, cd.depth, false);
    }
  }
}

function buildCrownAndGlyphs() {
  // 1. Crown Solar Rosette at (595, 145), radius 52
  let cx = 595, cy = 145;
  let outerR = 52, innerR = 15;
  let ringSegs = 36;
  for (let i = 0; i < ringSegs; i++) {
    let a1 = (i / ringSegs) * 360;
    let a2 = ((i + 1) / ringSegs) * 360;
    carveGrooveInGrid(
      cx + cos(a1) * outerR, cy + sin(a1) * outerR,
      cx + cos(a2) * outerR, cy + sin(a2) * outerR,
      4.5, 0.075, true
    );
    carveGrooveInGrid(
      cx + cos(a1) * innerR, cy + sin(a1) * innerR,
      cx + cos(a2) * innerR, cy + sin(a2) * innerR,
      3.8, 0.065, true
    );
  }
  // 12 radiating petals
  for (let p = 0; p < 12; p++) {
    let ang = p * 30;
    carveGrooveInGrid(
      cx + cos(ang) * (innerR + 2), cy + sin(ang) * (innerR + 2),
      cx + cos(ang) * (outerR - 3), cy + sin(ang) * (outerR - 3),
      4.0, 0.07, true
    );
  }

  // Flanking pilaster flutes in crown
  for (let px of [358, 376, 394, 802, 820, 838]) {
    carveGrooveInGrid(px, 92, px, 200, 4.2, 0.065, true);
