  // 2. Register Horizontal Dividing Rules
  let regYs = [222, 232, 346, 354, 458, 466, 570, 578, 682, 690, 794, 802, 906, 914, 1016, 1024];
  for (let ry of regYs) {
    let xStart = slabLeftEdge[ry] + 32;
