    // 2: Trident / Shin-Musnad
    [[0.15, 0.15, 0.15, 0.65], [0.5, 0.12, 0.5, 0.9], [0.85, 0.15, 0.85, 0.65], [0.15, 0.65, 0.85, 0.65]],
    // 3: Lozenge / Solar Eye
    [[0.5, 0.12, 0.88, 0.5], [0.88, 0.5, 0.5, 0.88], [0.5, 0.88, 0.12, 0.5], [0.12, 0.5, 0.5, 0.12], [0.5, 0.35, 0.5, 0.65]],
    // 4: Het (ladder / sanctuary gate)
    [[0.18, 0.1, 0.18, 0.9], [0.82, 0.1, 0.82, 0.9], [0.18, 0.25, 0.82, 0.25], [0.18, 0.52, 0.82, 0.52], [0.18, 0.78, 0.82, 0.78]],
    // 5: Qof (bisected circle on pillar)
    [[0.5, 0.1, 0.5, 0.92], [0.5, 0.12, 0.85, 0.34], [0.85, 0.34, 0.5, 0.56], [0.5, 0.56, 0.15, 0.34], [0.15, 0.34, 0.5, 0.12]],
    // 6: Mem (zig-zag water crest + stem)
    [[0.82, 0.12, 0.82, 0.9], [0.12, 0.28, 0.35, 0.12], [0.35, 0.12, 0.58, 0.32], [0.58, 0.32, 0.82, 0.12], [0.82, 0.12, 0.82, 0.45]],
    // 7: Dalet / Triangle standard
    [[0.22, 0.12, 0.22, 0.88], [0.22, 0.12, 0.86, 0.42], [0.86, 0.42, 0.22, 0.68]],
    // 8: Stepped Altar / Throne glyph
    [[0.15, 0.88, 0.85, 0.88], [0.15, 0.88, 0.15, 0.48], [0.85, 0.88, 0.85, 0.48], [0.32, 0.48, 0.32, 0.14], [0.68, 0.48, 0.68, 0.14], [0.15, 0.48, 0.85, 0.48], [0.32, 0.14, 0.68, 0.14]],
    // 9: Archaic Taw / Crossed standard
    [[0.5, 0.1, 0.5, 0.9], [0.15, 0.32, 0.85, 0.32], [0.25, 0.18, 0.15, 0.32], [0.75, 0.18, 0.85, 0.32]],
    // 10: Forked Waw / Y-standard
    [[0.5, 0.45, 0.5, 0.9], [0.18, 0.12, 0.5, 0.45], [0.82, 0.12, 0.5, 0.45], [0.3, 0.88, 0.7, 0.88]],
    // 11: Zayin / Double bar sceptre
