    // 14: Open Sanctuary / He
    [[0.82, 0.1, 0.82, 0.9], [0.16, 0.14, 0.82, 0.14], [0.24, 0.48, 0.82, 0.48], [0.16, 0.14, 0.16, 0.72]],
    // 15: Word Divider (two vertical wedges)
    [[0.5, 0.22, 0.5, 0.42], [0.5, 0.58, 0.5, 0.78]]
