  for (let rIdx = 0; rIdx < registerBands.length; rIdx++) {
    let band = registerBands[rIdx];
    let gh = band.yBot - band.yTop;
    let curX = 328;
    let endX = 872;
    let glyphCounter = 0;

    while (curX + band.gw < endX) {
      let isDivider = (glyphCounter > 0 && glyphCounter % 4 === 3 && random() < 0.75);
      let tIdx = isDivider ? 15 : floor(random(0, 15));
      let w = isDivider ? band.gw * 0.45 : band.gw * random(0.88, 1.08);
      let tmpl = templates[tIdx];

      for (let seg of tmpl) {
        let x1 = curX + seg[0] * w;
        let y1 = band.yTop + seg[1] * gh;
