      }

      curX += w + band.gap * random(0.85, 1.2);
      glyphCounter++;
    }
  }
}

function buildKarstPits() {
  // Generate 420 karst dissolution pits and fossil cavities across the slab
  for (let i = 0; i < 420; i++) {
    let py = random(65, 1140);
    let xL = slabLeftEdge[floor(py)] + 16;
    let xR = slabRightEdge[floor(py)] - 16;
    if (xR <= xL + 20) continue;
    let px = random(xL, xR);
    if (py < slabTopEdge[floor(px)] + 14) continue;

    // Cluster pits near eroded zones and cracks
    let gx = floor(px / CELL);
    let gy = floor(py / CELL);
    let ero = erosionMap[gy * GRID_W + gx];
    if (random() > 0.28 + ero * 0.65) continue;

    let r = random() < 0.08 ? random(8, 19) : random(2.2, 7.5);
    let depth = map(r, 2, 19, 0.045, 0.16);
    karstPits.push({ x: px, y: py, r, depth });

    // Carve pit into heightfield
    let rGrid = Math.ceil(r / CELL) + 1;
    for (let dy = -rGrid; dy <= rGrid; dy++) {
      let cy = gy + dy;
      if (cy < 1 || cy >= GRID_H - 1) continue;
      for (let dx = -rGrid; dx <= rGrid; dx++) {
        let cx = gx + dx;
        if (cx < 1 || cx >= GRID_W - 1) continue;
        let d = Math.hypot(cx * CELL - px, cy * CELL - py);
        if (d < r) {
          let norm = d / r;
          let bowl = Math.cos(norm * 90);
          heightMap[cy * GRID_W + cx] -= depth * bowl;
        }
      }
    }
  }
}

function computeLightingAndShadows() {
  // Raking dawn light from the left ( slightly elevated from top-left )
  const shadowSlope = 0.0145; // Low grazing angle

  for (let gy = 1; gy < GRID_H - 1; gy++) {
    let runShadowH = 0.0;
    for (let gx = 1; gx < GRID_W - 1; gx++) {
      let idx = gy * GRID_W + gx;
      let h = heightMap[idx];

      if (h <= 0.01) {
        shadowMap[idx] = 1.0;
        illumMap[idx] = 0.0;
        runShadowH = Math.max(0, runShadowH - shadowSlope * 2.5);
        continue;
      }

      // Check self-shadowing from features to the left
      let prevRow = Math.max(0, gy - (gx % 4 === 0 ? 1 : 0));
      let prevShadow = shadowMap[prevRow * GRID_W + (gx - 1)];
      runShadowH = Math.max(h, runShadowH - shadowSlope);

      let inShadow = (runShadowH > h + 0.003) ? Math.min(1.0, (runShadowH - h) * 18.0) : 0.0;

      // Global right-side falloff across the monument
      let y = gy * CELL;
      let x = gx * CELL;
      let xL = slabLeftEdge[y];
      let xR = slabRightEdge[y];
      let normX = constrain((x - xL) / Math.max(1, xR - xL), 0, 1);
      let globalFalloff = Math.pow(normX, 1.65) * 0.58;

      // Surface normal illumination: dH/dx > 0 means facing left (toward light!)
      let dhdx = (heightMap[idx + 1] - heightMap[idx - 1]) * 0.5;
      let dhdy = (heightMap[idx + GRID_W] - heightMap[idx - GRID_W]) * 0.5;

      //Wait: if surface slopes UP as x increases (dhdx > 0), its normal points LEFT (-x), toward the light!
      let normalLight = dhdx * 16.5 + dhdy * 3.8;

      let rawIllum = 0.76 - globalFalloff + normalLight - inShadow * 0.48;
      illumMap[idx] = constrain(rawIllum, 0.02, 1.0);
      shadowMap[idx] = constrain(inShadow + globalFalloff * 0.65, 0.0, 1.0);
    }
  }
}

// ============================================================================
// HELPER FOR DRAWING POLYGONS SAFELY WITH P5.BRUSH
// ============================================================================

function drawBrushShape(pts, curvature = 0.15, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// ============================================================================
// STEP 1: DARK MONUMENT SURROUND
// ============================================================================

function renderDarkSurround() {
  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.6, 0.35);

  // Left and right dark void panels
  brush.fill("#161817", 210);
  drawBrushShape([[0, 0], [310, 0], [310, 1200], [0, 1200]], 0);
  drawBrushShape([[890, 0], [1200, 0], [1200, 1200], [890, 1200]], 0);

  // Subtle cold dawn glow behind upper-left edge so the stone silhouette is crisp
  brush.fill("#282a27", 95);
  drawBrushShape([[160, 20], [305, 20], [305, 720], [140, 620]], 0.2);

  brush.noFill();

  // Dense vertical charcoal hatching in the background margins
  brush.hatchStyle("charcoal", "#0e0f0e", 1.15);
  brush.hatch(10, 88, { rand: 0.08 });
  drawBrushShape([[0, 0], [292, 0], [285, 1200], [0, 1200]], 0);
  drawBrushShape([[908, 0], [1200, 0], [1200, 1200], [912, 1200]], 0);
  brush.noHatch();
}

// ============================================================================
// STEP 2: LIMESTONE SLAB BASE MINERAL WASHES
// ============================================================================

function renderSlabBaseWashes() {
  brush.noStroke();

  // Solid mineral undertone wash across the whole slab silhouette
  let slabPoly = [];
  for (let x = 285; x <= 915; x += 35) {
    slabPoly.push([x, slabTopEdge[x]]);
  }
  for (let y = 60; y <= 1190; y += 40) {
    slabPoly.push([slabRightEdge[y], y]);
  }
  for (let x = 940; x >= 250; x -= 45) {
    slabPoly.push([x, 1192]);
  }
  for (let y = 1190; y >= 60; y -= 40) {
    slabPoly.push([slabLeftEdge[y], y]);
  }

  brush.wash("#8f897c", 235);
  drawBrushShape(slabPoly, 0.08);
  brush.noWash();

  // Layered watercolor mineral washes batched by tone (left sunlit to right shadow)
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.78, 0.45);

  // 1. Bright dawn-lit left stone zone
  brush.fill("#d8d1c3", 135);
  for (let band = 0; band < 5; band++) {
    let y1 = 55 + band * 215;
    let y2 = y1 + 235;
    let xL1 = slabLeftEdge[y1] + 6;
    let xL2 = slabLeftEdge[min(1190, y2)] + 6;
    drawBrushShape([
      [xL1, y1],
      [xL1 + 240 + random(-25, 25), y1 + 15],
      [xL2 + 210 + random(-25, 25), y2],
      [xL2, y2]
    ], 0.25);
  }

  // 2. Warm-cool weathered putty mid-left patches
  brush.fill("#bcb5a6", 115);
  for (let i = 0; i < 9; i++) {
    let cx = random(340, 660);
    let cy = random(90, 1060);
    let rx = random(85, 160);
    let ry = random(65, 140);
    let pts = [];
    for (let a = 0; a < 360; a += 45) {
      let rMod = 0.8 + noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a)) * 0.4;
      pts.push([cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod]);
    }
    drawBrushShape(pts, 0.3);
  }

  // 3. Cold limestone shadow washes on right half & spalled zones
  brush.fill("#59554d", 140);
  for (let band = 0; band < 5; band++) {
    let y1 = 60 + band * 220;
    let y2 = y1 + 240;
    let xR1 = slabRightEdge[y1];
    let xR2 = slabRightEdge[min(1190, y2)];
    drawBrushShape([
      [xR1 - 260 + random(-30, 30), y1],
      [xR1, y1],
      [xR2, y2],
      [xR2 - 280 + random(-30, 30), y2]
    ], 0.2);
  }

  // 4. Deep damp/shadow stain along right margin, upper-right fracture & plinth base
  brush.fill("#34322d", 165);
  for (let band = 0; band < 6; band++) {
    let y1 = 50 + band * 190;
    let y2 = y1 + 205;
    let xR1 = slabRightEdge[y1];
    let xR2 = slabRightEdge[min(1190, y2)];
    drawBrushShape([
      [xR1 - 115 + random(-18, 18), y1],
      [xR1, y1],
      [xR2, y2],
      [xR2 - 135 + random(-18, 18), y2]
    ], 0.18);
  }
  // Rising damp at bottom socle & plinth
  drawBrushShape([
    [slabLeftEdge[1030], 1035],
    [slabRightEdge[1030], 1020],
    [slabRightEdge[1190], 1192],
    [slabLeftEdge[1190], 1192]
  ], 0.1);

  brush.noFill();
}

// ============================================================================
// STEP 3: CHARCOAL MASSING FOR DEEP RECESSES & SPALL BASINS
// ============================================================================

function renderCharcoalRecessMasses() {
  brush.noStroke();

  // 1. Spall basins: render their recessed left shadow zones with dry charcoal mass
  for (let b of spallBasins) {
    let ptsOuter = [];
    let ptsInner = [];
    for (let a = 0; a < 360; a += 30) {
      let warp = 0.78 + fbm(b.x * 0.02 + cos(a), b.y * 0.02 + sin(a), 3) * 0.42;
      // Shift shadow mass toward left side of the recessed basin (raking left light)
      let sx = b.x - b.rx * 0.18 + cos(a) * b.rx * 0.78 * warp;
      let sy = b.y + sin(a) * b.ry * 0.85 * warp;
      ptsOuter.push([sx, sy]);
      if (a >= 110 && a <= 265) {
        ptsInner.push([
          b.x + cos(a) * b.rx * 0.92 * warp,
          b.y + sin(a) * b.ry * 0.92 * warp
        ]);
      }
    }

    brush.mass("charcoal", "#423f39", {
      precision: 0.45,
      strength: 0.55,
      gradient: 0.65,
      outline: false
    });
    drawBrushShape(ptsOuter, 0.25);
    brush.noMass();

    // Deepest left-edge trough of the spall basin
    if (ptsInner.length >= 3) {
      ptsInner.push([b.x - b.rx * 0.35, b.y]);
      brush.mass("charcoal", "#252320", {
        precision: 0.35,
        strength: 0.8,
        gradient: 0.5,
        outline: false
      });
      drawBrushShape(ptsInner, 0.2);
      brush.noMass();
    }
  }

  // 2. Right-hand chamfer & ancient upper-right break shadow masses
  for (let s = 0; s < 8; s++) {
    let y1 = 48 + s * 140;
    let y2 = min(1188, y1 + 150);
    let xR1 = slabRightEdge[y1];
    let xR2 = slabRightEdge[y2];
    let w1 = s === 0 ? 115 : random(55, 88);
    let w2 = random(55, 92);

    brush.mass("charcoal", "#282623", {
      precision: 0.4,
      strength: 0.75,
      gradient: 0.7,
      outline: false
    });
    drawBrushShape([
      [xR1 - w1, y1],
      [xR1, y1],
      [xR2, y2],
      [xR2 - w2, y2]
    ], 0.15);
    brush.noMass();
  }

  // 3. Deep plinth base charcoal mass
  brush.mass("charcoal", "#1c1b19", {
    precision: 0.35,
    strength: 0.9,
    gradient: 0.4,
    outline: false
  });
  drawBrushShape([
    [slabLeftEdge[1152], 1150],
    [slabRightEdge[1152], 1150],
    [slabRightEdge[1190], 1192],
    [slabLeftEdge[1190], 1192]
  ], 0.08);
  brush.noMass();
}

// ============================================================================
// STEP 4: BURNISHED GRAPHITE PENCIL FOR SUNLIT PLANES & RAKING RELIEF
// ============================================================================

function renderBurnishedGraphitePlanes() {
  // Sample the heightfield illumination map to lay down thousands of directional
  // burnished graphite strokes ("2H", "HB", "burnisher") on lit planes and
  // gritty "2B" / "charcoal" strokes in raking grazing zones.

  let lightStrokes1 = []; // Brightest dawn mineral burnish (#ede8dc)
  let lightStrokes2 = []; // Sunlit graphite sheen (#dad4c6)
  let midLightStrokes = []; // Cool silver-graphite (#b5ae9f)
  let midDarkStrokes = [];  // Grazing graphite tooth (#6b665c)
  let shadowStrokes = [];   // Deep raking shadow (#33302b)
  let abyssStrokes = [];    // Core charcoal recess (#1d1c19)

  for (let gy = 14; gy < GRID_H - 12; gy += 3) {
    let y = gy * CELL;
    for (let gx = 68; gx < GRID_W - 60; gx += 3) {
      let idx = gy * GRID_W + gx;
      if (heightMap[idx] <= 0.05) continue;

      let x = gx * CELL + random(-2.2, 2.2);
      let py = y + random(-2.2, 2.2);
      let illum = illumMap[idx];
      let shad = shadowMap[idx];

      // Local tooling angle: slight diagonal chisel dressing (~28 deg or ~152 deg)
      let baseAng = (gy > 505) ? 85 + random(-12, 12) : 26 + (noise(gx * 0.04, gy * 0.04) - 0.5) * 28;
      let len = random(11, 24);

      if (illum > 0.78 && shad < 0.12) {
        lightStrokes1.push({ x, y: py, ang: baseAng, len: len * 0.9 });
      } else if (illum > 0.64 && shad < 0.25) {
        lightStrokes2.push({ x, y: py, ang: baseAng, len });
      } else if (illum > 0.48) {
        midLightStrokes.push({ x, y: py, ang: baseAng, len });
      } else if (illum > 0.34) {
        midDarkStrokes.push({ x, y: py, ang: baseAng + 45, len: len * 0.85 });
      } else if (illum > 0.20) {
        shadowStrokes.push({ x, y: py, ang: baseAng - 35, len: len * 0.9 });
      } else {
        abyssStrokes.push({ x, y: py, ang: 82 + random(-15, 15), len: len * 0.95 });
      }
    }
  }

  // Draw batched graphite & charcoal strokes from dark to light so burnished highlights gleam on top
  drawStrokeBatch(abyssStrokes, "charcoal", "#1c1b18", 0.95);
  drawStrokeBatch(shadowStrokes, "2B", "#34312c", 0.82);
  drawStrokeBatch(midDarkStrokes, "2B", "#5e5a50", 0.72);
  drawStrokeBatch(midLightStrokes, "HB", "#aba496", 0.68);
  drawStrokeBatch(lightStrokes2, "burnisher", "#dcd6c8", 1.05);
  drawStrokeBatch(lightStrokes1, "2H", "#efeae0", 0.78);

  // Additional tight cross-burnishing pass on the strongly raking-lit left third of the slab
  brush.set("burnisher", "#e8e2d5", 0.95);
  for (let i = 0; i < 950; i++) {
    let py = random(62, 1080);
    let xL = slabLeftEdge[floor(py)] + 10;
    let px = xL + Math.pow(random(), 1.6) * 240;
    let gx = floor(px / CELL);
    let gy = floor(py / CELL);
    if (gx < 0 || gx >= GRID_W || gy < 0 || gy >= GRID_H) continue;
    let idx = gy * GRID_W + gx;
    if (heightMap[idx] > 0.5 && illumMap[idx] > 0.62 && Math.abs(lichenMap[idx]) < 0.2) {
      let ang = -22 + random(-8, 8);
      let l = random(14, 30);
      brush.line(px - cos(ang) * l * 0.5, py - sin(ang) * l * 0.5, px + cos(ang) * l * 0.5, py + sin(ang) * l * 0.5);
    }
  }
}

function drawStrokeBatch(list, brushName, col, weight) {
  brush.set(brushName, col, weight);
  for (let i = 0; i < list.length; i++) {
    let s = list[i];
    let dx = cos(s.ang) * s.len * 0.5;
    let dy = sin(s.ang) * s.len * 0.5;
    brush.line(s.x - dx, s.y - dy, s.x + dx, s.y + dy);
  }
}

// ============================================================================
// STEP 5: SEDIMENTARY STRATA & CHISEL SCARS (TOOTH CHISEL & POINT CHISEL)
// ============================================================================

function renderChiselToolingAndStrata() {
  // 1. Faint sedimentary bedding striae across the limestone
  for (let y = 85; y < 1140; y += random(22, 42)) {
    let xL = slabLeftEdge[floor(y)] + 14;
    let xR = slabRightEdge[floor(y)] - 18;
    let curX = xL;
    while (curX < xR - 30) {
      let segLen = random(28, 75);
      let nx = min(xR, curX + segLen);
      let ny = y + (fbm(curX * 0.008, y * 0.01, 2) - 0.5) * 10;
      let gx = floor(curX / CELL);
      let gy = floor(y / CELL);
      let ill = illumMap[gy * GRID_W + gx];

      if (random() < 0.68) {
        // Dark fine bedding hairline
        brush.set("2B", ill > 0.5 ? "#5c584e" : "#2c2a25", 0.45);
        brush.line(curX, y, nx, ny);
        // Raking lower lip highlight where light catches the stratum step
        if (ill > 0.48) {
          brush.set("2H", "#e3ddd0", 0.38);
          brush.line(curX + 1, y + 1.4, nx + 1, ny + 1.4);
        }
      }
      curX = nx + random(15, 55);
    }
  }

  // 2. Tooth-chisel (drove) parallel tracks & point-chisel gouges
  // Each chisel scar is a tiny recessed gouge: dark left notch + bright right bevel!
  let scarDark = [];
  let scarLight = [];

  for (let i = 0; i < 1650; i++) {
    let py = random(58, 1150);
    let xL = slabLeftEdge[floor(py)] + 12;
    let xR = slabRightEdge[floor(py)] - 14;
    if (xR <= xL + 20) continue;
    let px = random(xL, xR);
    if (py < slabTopEdge[floor(px)] + 12) continue;

    let gx = floor(px / CELL);
    let gy = floor(py / CELL);
    let idx = gy * GRID_W + gx;
    if (Math.abs(lichenMap[idx]) > 0.35) continue;

    let isSocle = py > 1018;
    let ang = isSocle ? random(55, 82) : (random() < 0.7 ? random(58, 76) : random(105, 125));
    let len = isSocle ? random(6, 15) : random(4, 11);

    let dx = cos(ang) * len * 0.5;
    let dy = sin(ang) * len * 0.5;

    scarDark.push([px - dx, py - dy, px + dx, py + dy]);
    if (illumMap[idx] > 0.36) {
      // Right-hand sunlit edge of the chisel strike
      scarLight.push([px - dx + 1.5, py - dy + 0.4, px + dx + 1.5, py + dy + 0.4]);
    }
  }

  brush.set("chisel_edge", "#2b2924", 0.65);
  for (let s of scarDark) {
    brush.line(s[0], s[1], s[2], s[3]);
  }

  brush.set("2H", "#ebe5d8", 0.52);
  for (let s of scarLight) {
    brush.line(s[0], s[1], s[2], s[3]);
  }
}

// ============================================================================
// STEP 6: ARCHITECTURAL CROWN PANEL, SOLAR ROSETTE & REGISTER RULES
// ============================================================================

function renderCrownAndRegisterRules() {
  // 1. Sunken Tympanum Frame (x = 338..855, y = 82..210)
  // Left vertical reveal of the sunken panel is in deep raking shadow!
  brush.set("charcoal", "#1c1b18", 1.35);
  brush.line(338, 84, 338, 210);
  brush.set("2B", "#33302b", 0.95);
  brush.line(341, 84, 341, 210);
  // Top reveal shadow
  brush.line(338, 83, 760, 83);

  // Right vertical reveal of the sunken panel faces the left light -> bright highlight!
  brush.set("2H", "#efeae0", 0.95);
  brush.line(854, 155, 854, 210);
  // Bottom lip catches subtle grazing light
  brush.set("2H", "#dfd9cb", 0.75);
  brush.line(340, 211, 854, 211);
  brush.set("2B", "#3c3933", 0.65);
  brush.line(340, 208, 854, 208);

  // Flanking pilaster flutes
  for (let px of [358, 376, 394, 802, 820, 838]) {
    let topY = max(92, slabTopEdge[px] + 18);
    if (topY < 198) {
      drawCarvedVGroove(px, topY, px, 198, 4.2, true);
    }
  }

  // 2. The 12-Rayed Solar Rosette at (595, 145)
  let cx = 595, cy = 145;
  for (let r of [52, 36, 15]) {
    let segs = 36;
    for (let i = 0; i < segs; i++) {
      let a1 = (i / segs) * 360;
      let a2 = ((i + 1) / segs) * 360;
      let x1 = cx + cos(a1) * r;
      let y1 = cy + sin(a1) * r;
      let x2 = cx + cos(a2) * r;
      let y2 = cy + sin(a2) * r;
      drawCarvedVGroove(x1, y1, x2, y2, r === 52 ? 4.5 : 3.4, true);
    }
  }

  for (let p = 0; p < 12; p++) {
    let ang = p * 30;
    let x1 = cx + cos(ang) * 16;
    let y1 = cy + sin(ang) * 16;
    let x2 = cx + cos(ang) * 50;
    let y2 = cy + sin(ang) * 50;
    drawCarvedVGroove(x1, y1, x2, y2, 3.8, true);

    // Carved petal boss between rays: left edge lit, right edge shaded
    let midA = ang + 15;
    let bx = cx + cos(midA) * 34;
    let by = cy + sin(midA) * 34;
    let gx = floor(bx / CELL);
    let gy = floor(by / CELL);
    if (erosionMap[gy * GRID_W + gx] < 0.75) {
      brush.set("2H", "#ebe5d8", 0.72);
      brush.arc(bx - 1.5, by, 6, 120, 250);
      brush.set("2B", "#33302b", 0.68);
      brush.arc(bx + 1.5, by, 6, -60, 65);
    }
  }

  // Central umbilical boss of solar rosette
  brush.set("2H", "#f0ebe1", 0.9);
  brush.arc(cx - 2, cy, 10, 110, 260);
  brush.set("charcoal", "#24221e", 0.9);
  brush.arc(cx + 2, cy, 10, -70, 70);

  // 3. Horizontal Register Rule-Lines & Cornice Dentils
  let regYs = [222, 232, 346, 354, 458, 466, 570, 578, 682, 690, 794, 802, 906, 914, 1016, 1024];
  for (let ry of regYs) {
    let xStart = slabLeftEdge[ry] + 28;
    let xEnd = slabRightEdge[ry] - 28;
    drawCarvedVGroove(xStart, ry, xEnd, ry, 3.4, true);
  }

  // Eroded dentil blocks along the main cornice band (y = 222..232)
  for (let dx = 335; dx < 855; dx += 18) {
    let gx = floor(dx / CELL);
    let gy = floor(227 / CELL);
    if (erosionMap[gy * GRID_W + gx] < 0.65) {
      // Left edge of dentil catches raking light; right edge casts shadow into notch
      brush.set("2H", "#ece6d9", 0.7);
      brush.line(dx, 223, dx, 231);
      brush.set("charcoal", "#24221e", 0.85);
      brush.line(dx + 10, 223, dx + 10, 231);
    }
  }
}

// ============================================================================
// STEP 7: HALF-DISSOLVED CARVED GLYPH REGISTERS
// ============================================================================

function renderGlyphRegisters() {
  for (let seg of glyphSegments) {
    drawCarvedVGroove(seg.x1, seg.y1, seg.x2, seg.y2, seg.halfW, true);
  }
}

// Renders an authentic V-cut chisel groove under low left raking light,
// dissolving organically where erosionMap or lichenMap is high.
function drawCarvedVGroove(x1, y1, x2, y2, halfW, respectErosion = true) {
  let len = Math.hypot(x2 - x1, y2 - y1);
  if (len < 1) return;

  let stepSize = 5.5;
  let steps = Math.max(1, Math.ceil(len / stepSize));

  // Offset direction for raking light from left (-x, slightly -y):
  // Left/upper slope of V-cut is in shadow; right/lower slope catches the light!
  let dx = (x2 - x1) / len;
  let dy = (y2 - y1) / len;
  // Normal pointing roughly right/down
  let nx = Math.abs(dy) * 0.88 + 0.35;
  let ny = Math.abs(dx) * 0.55 + 0.15;

  for (let i = 0; i < steps; i++) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    let sx1 = lerp(x1, x2, t1);
    let sy1 = lerp(y1, y2, t1);
    let sx2 = lerp(x1, x2, t2);
    let sy2 = lerp(y1, y2, t2);

    let mx = (sx1 + sx2) * 0.5;
    let my = (sy1 + sy2) * 0.5;
    let gx = constrain(floor(mx / CELL), 0, GRID_W - 1);
    let gy = constrain(floor(my / CELL), 0, GRID_H - 1);
    let idx = gy * GRID_W + gx;

    if (heightMap[idx] <= 0.08) continue;

    let ero = respectErosion ? erosionMap[idx] : 0.15;
    let lich = Math.abs(lichenMap[idx]);
    let ill = illumMap[idx];

    // Completely dissolved under heavy spalling or thick lichen center
    if (ero > 0.92 || lich > 0.58) {
      if (random() < 0.25) {
        // Faint ghost pit of dissolved chisel trench
        brush.set("2B", "#49463e", 0.48);
        brush.line(mx - 1, my - 1, mx + 1, my + 1);
      }
      continue;
    }

    let w = halfW * (1.0 - ero * 0.35);

    if (ero < 0.48) {
      // Crisp or moderately weathered V-cut:
      // 1. Left/upper inner slope in deep charcoal/graphite shadow
      brush.set("charcoal", ill > 0.35 ? "#23211d" : "#181715", 0.72 * (w / 3.8));
      brush.line(sx1 - nx * w * 0.42, sy1 - ny * w * 0.42, sx2 - nx * w * 0.42, sy2 - ny * w * 0.42);

      // 2. Center V-trough line
      brush.set("chisel_edge", "#151412", 0.65);
      brush.line(sx1, sy1, sx2, sy2);

      // 3. Right/lower inner bevel facing the raking dawn light!
      if (ill > 0.28) {
        let hiCol = ill > 0.62 ? "#f0ebe0" : (ill > 0.45 ? "#dad4c6" : "#a39d90");
        brush.set("2H", hiCol, 0.68 * (w / 3.8));
        brush.line(sx1 + nx * w * 0.48, sy1 + ny * w * 0.48, sx2 + nx * w * 0.48, sy2 + ny * w * 0.48);
      }
    } else {
      // Half-dissolved, eroded V-cut: broken, pitted edges
      let j1 = random(-1.6, 1.6);
      let j2 = random(-1.6, 1.6);
      brush.set("2B", "#3b3832", 0.62);
      brush.line(sx1 - nx * w * 0.35 + j1, sy1 - ny * w * 0.35, sx2 - nx * w * 0.35 + j2, sy2 - ny * w * 0.35);

      if (ill > 0.38 && random() < 0.75) {
        brush.set("HB", "#c9c3b5", 0.55);
        brush.line(sx1 + nx * w * 0.52, sy1 + ny * w * 0.52 + j1, sx2 + nx * w * 0.52, sy2 + ny * w * 0.52 + j2);
      }
    }
  }
}

// ============================================================================
// STEP 8: KARST DISSOLUTION PITS, FOSSILS & MAJOR STRUCTURAL FRACTURES
// ============================================================================

function renderPitsAndFractures() {
  // 1. Karst Pits & Fossil Cavities
  // Every pit has a dark charcoal left cavity and a bright burnished right crescent rim!
  for (let p of karstPits) {
    let gx = constrain(floor(p.x / CELL), 0, GRID_W - 1);
    let gy = constrain(floor(p.y / CELL), 0, GRID_H - 1);
    let idx = gy * GRID_W + gx;
    if (heightMap[idx] <= 0.08 || Math.abs(lichenMap[idx]) > 0.55) continue;

    let ill = illumMap[idx];
    let r = p.r;

    if (r > 6.5) {
      // Larger dissolution pit or fossil impression: fill left cavity with charcoal
      brush.noStroke();
      brush.fill("#201e1b", 185);
      brush.fillBleed(0.08, "in");
      brush.circle(p.x - r * 0.18, p.y, r * 0.78, 0.35);
      brush.noFill();

      // Deep left inner rim shadow
      brush.set("charcoal", "#141311", 0.88);
      brush.arc(p.x, p.y, r, 105, 265);

      // Sunlit right inner wall & lip
      if (ill > 0.28) {
        brush.set("2H", ill > 0.58 ? "#f0ebe1" : "#d4cec0", 0.82);
        brush.arc(p.x + 1.2, p.y, r * 0.95, -75, 80);
      }

      // If very large, add radial fossil striae inside
      if (r > 12) {
        brush.set("chisel_edge", "#38352f", 0.48);
        for (let a = 0; a < 360; a += 36) {
          brush.line(p.x + cos(a) * r * 0.25, p.y + sin(a) * r * 0.25, p.x + cos(a) * r * 0.85, p.y + sin(a) * r * 0.85);
        }
      }
    } else {
      // Small sharp karst pore (2..6.5px)
      brush.set("charcoal", "#191816", 0.65);
      brush.line(p.x - r * 0.5, p.y - r * 0.4, p.x - r * 0.2, p.y + r * 0.5);
      if (ill > 0.34) {
        brush.set("2H", ill > 0.6 ? "#ede8dc" : "#c8c2b4", 0.55);
        brush.line(p.x + r * 0.45, p.y - r * 0.4, p.x + r * 0.45, p.y + r * 0.45);
      }
    }
  }

  // 2. Major Structural Fractures
  for (let cr of majorCracks) {
    let pts = cr.pts;
    let w = cr.width;

    // Wide spalled shadow zone along the crack
    for (let i = 0; i < pts.length - 1; i++) {
      let a = pts[i];
      let b = pts[i + 1];
      let mx = (a[0] + b[0]) * 0.5;
      let my = (a[1] + b[1]) * 0.5;
      let gx = constrain(floor(mx / CELL), 0, GRID_W - 1);
      let gy = constrain(floor(my / CELL), 0, GRID_H - 1);
      if (heightMap[gy * GRID_W + gx] <= 0.05) continue;

      let ill = illumMap[gy * GRID_W + gx];

      // Upper/left spalled shadow lip
      brush.set("charcoal", "#24221e", 1.15 * (w / 6.0));
      brush.line(a[0] - 2.2, a[1] - 1.8, b[0] - 2.2, b[1] - 1.8);

      // Abyssal core fissure
      brush.set("chisel_edge", "#0f0e0d", 1.1 * (w / 6.0));
      brush.line(a[0], a[1], b[0], b[1]);

      // Lower/right chipped lip catching sharp raking dawn light!
      if (ill > 0.24) {
        let col = ill > 0.58 ? "#f2ede3" : "#d4cec0";
        brush.set("2H", col, 0.88 * (w / 6.0));
        brush.line(a[0] + 2.6, a[1] + 2.2, b[0] + 2.6, b[1] + 2.2);
      }

      // Micro-branching hairline fractures
      if (i % 5 === 2 && random() < 0.65) {
        let brAng = random(-65, 65);
        let brLen = random(14, 34);
        let bx = b[0] + cos(brAng) * brLen;
        let by = b[1] + sin(brAng) * brLen;
        brush.set("chisel_edge", "#211f1c", 0.55);
        brush.line(b[0], b[1], bx, by);
        brush.set("2H", "#dfd9cc", 0.42);
        brush.line(b[0] + 1.2, b[1] + 1.0, bx + 1.2, by + 1.0);
      }
    }
  }
}

// ============================================================================
// STEP 9: WATERCOLOUR WASHES FOR LICHEN ROSETTES (SAGE & RAW SIENNA)
// ============================================================================

function renderLichenWatercolourWashes() {
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.78, 0.58);

  let sageOuterPolys = [];
  let sageInnerPolys = [];
  let siennaOuterPolys = [];
  let siennaInnerPolys = [];

  for (let col of lichenColonies) {
    let outerPts = [];
    let innerPts = [];
    let steps = 28;

    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      let radA = (i / steps) * TWO_PI;
      let lobe = Math.sin(radA * 14 + col.seed) * 0.14 +
                 Math.cos(radA * 23 - col.seed * 2) * 0.09 +
                 (fbm(col.x * 0.03 + cos(ang), col.y * 0.03 + sin(ang), 3) - 0.5) * 0.32;
      let rOut = col.r * (0.86 + lobe);
      let rIn = col.r * 0.52 * (0.85 + lobe * 0.6);

      outerPts.push([col.x + cos(ang) * rOut, col.y + sin(ang) * rOut]);
      innerPts.push([col.x + cos(ang) * rIn, col.y + sin(ang) * rIn]);
    }

    if (col.type > 0) {
      sageOuterPolys.push(outerPts);
      sageInnerPolys.push(innerPts);
    } else {
      siennaOuterPolys.push(outerPts);
      siennaInnerPolys.push(innerPts);
    }

    // Small satellite thalli along nearby glyph grooves
    for (let s = 0; s < 4; s++) {
      let sa = random(360);
      let sd = col.r * random(0.95, 1.45);
      let sx = col.x + cos(sa) * sd;
      let sy = col.y + sin(sa) * sd;
      let sr = random(6, 15);
      let sPts = [];
      for (let k = 0; k < 10; k++) {
        let ka = k * 36;
        let kr = sr * random(0.75, 1.25);
        sPts.push([sx + cos(ka) * kr, sy + sin(ka) * kr]);
      }
      if (col.type > 0) sageOuterPolys.push(sPts);
      else siennaOuterPolys.push(sPts);
    }
  }

  // Batch 1: Grey-green sage watercolor outer thallus washes
  brush.fill("#7b856f", 145);
  for (let p of sageOuterPolys) drawBrushShape(p, 0.25);

  // Batch 2: Deeper olive-sage inner crust washes
  brush.fill("#56614b", 160);
  for (let p of sageInnerPolys) drawBrushShape(p, 0.25);

  // Batch 3: Raw sienna / ochre-orange watercolor outer washes
  brush.fill("#b87330", 155);
  for (let p of siennaOuterPolys) drawBrushShape(p, 0.25);

  // Batch 4: Deep burnt sienna inner apothecia zone washes
  brush.fill("#8c4b19", 170);
  for (let p of siennaInnerPolys) drawBrushShape(p, 0.25);

  brush.noFill();
}

// ============================================================================
// STEP 10: TACTILE LICHEN ROSETTE LOBES, APOTHECIA & MICRO-SHADOWS
// ============================================================================

function renderLichenTactileDetails() {
  for (let col of lichenColonies) {
    let isSage = col.type > 0;
    let litRimCol = isSage ? "#c2cbb6" : "#e3a65f";
    let midLobeCol = isSage ? "#8d9780" : "#c47e38";
    let darkCenterCol = isSage ? "#3b4234" : "#5e3110";

    // 1. Radiating foliose lobes around the perimeter
    // Lichen rosettes are RAISED: left lobes catch bright dawn light, right lobes cast crisp shadows!
    let lobeCount = floor(col.r * 0.85);
    for (let i = 0; i < lobeCount; i++) {
      let ang = (i / lobeCount) * 360 + random(-4, 4);
      let radA = ang * (PI / 180);
      let lobeMod = Math.sin(radA * 14 + col.seed) * 0.14 +
                    Math.cos(radA * 23 - col.seed * 2) * 0.09 +
                    (fbm(col.x * 0.03 + cos(ang), col.y * 0.03 + sin(ang), 3) - 0.5) * 0.32;
      let rEdge = col.r * (0.86 + lobeMod);
      let lx = col.x + cos(ang) * rEdge;
      let ly = col.y + sin(ang) * rEdge;

      let gx = constrain(floor(lx / CELL), 0, GRID_W - 1);
      let gy = constrain(floor(ly / CELL), 0, GRID_H - 1);
      if (heightMap[gy * GRID_W + gx] <= 0.08) continue;

      let lobeR = random(3.2, 6.8);

      // Cast shadow on the right side of each lobe onto the limestone
      brush.set("charcoal", "#1c1b18", 0.72);
      brush.arc(lx + 1.6, ly + 0.5, lobeR, -75, 85);

      // Midtone body of the lobe
      brush.set("cpencil", midLobeCol, 0.85);
      brush.arc(lx, ly, lobeR * 0.85, 0, 360);

      // Pruinose sunlit left rim of the lobe
      brush.set("2H", litRimCol, 0.68);
      brush.arc(lx - 1.0, ly - 0.3, lobeR * 0.9, 105, 255);
    }

    // 2. Crustose areolate interior & saucer-like apothecia fruiting discs
    let apotheciaCount = floor(col.r * 0.55);
    for (let j = 0; j < apotheciaCount; j++) {
      let d = random(0.05, 0.68) * col.r;
      let a = random(360);
      let ax = col.x + cos(a) * d;
      let ay = col.y + sin(a) * d;
      let ar = random(1.8, 4.2);

      // Dark spore disc center
      brush.set("charcoal", darkCenterCol, 0.78);
      brush.circle(ax, ay, ar * 0.65, 0.25);

      // Raised thalline rim around apothecium (bright on right of inner cup, bright on left of outer rim)
      brush.set("2H", litRimCol, 0.52);
      brush.arc(ax - 0.6, ay, ar, 110, 250);
    }

    // 3. Tiny lichen granules colonizing adjacent glyph grooves
    brush.set("cpencil", midLobeCol, 0.62);
    for (let g = 0; g < 18; g++) {
      let ga = random(360);
      let gd = col.r * random(0.8, 1.38);
      let gx = col.x + cos(ga) * gd;
      let gy = col.y + sin(ga) * gd;
      brush.line(gx - 1.2, gy, gx + 1.2, gy + 0.8);
    }
  }
}

// ============================================================================
// STEP 11: FINAL COLD TACTILE GRIT, LEFT ARRIS HIGHLIGHTS & PLINTH ANCHOR
// ============================================================================

function renderFinalSurfaceGritAndArris() {
  // 1. Cold tactile limestone grit (spray passes across lit and shadow zones)
  brush.set("stone_grit", "#e8e3d6", 0.95);
  for (let i = 0; i < 65; i++) {
    let y1 = random(55, 1120);
    let x1 = slabLeftEdge[floor(y1)] + random(12, 340);
    brush.line(x1, y1, x1 + random(-18, 18), y1 + random(25, 65));
  }

  brush.set("stone_grit", "#262420", 1.05);
  for (let i = 0; i < 75; i++) {
    let y1 = random(55, 1160);
    let x1 = random(360, slabRightEdge[floor(y1)] - 10);
    brush.line(x1, y1, x1 + random(-20, 20), y1 + random(25, 70));
  }

  // 2. Razor-sharp raking dawn light along the broken/chipped LEFT ARRIS of the monument
  for (let y = 52; y < 1146; y += 4) {
    let xL = slabLeftEdge[y];
    let xLNext = slabLeftEdge[y + 4];
    if (y < slabTopEdge[floor(xL)] + 4) continue;

    // Bright outer dawn rim
    brush.set("2H", "#f5f0e6", 1.05);
    brush.line(xL + 2, y, xLNext + 2, y + 4);

    // Chipped bevel facet width (~14..22px)
    let bevelW = 14 + noise(y * 0.04, 1.5) * 12;
    brush.set("burnisher", "#e3ddd0", 0.95);
    brush.line(xL + bevelW * 0.5, y, xLNext + bevelW * 0.5, y + 4);

    // Inner arris ridge where the left chamfer meets the front face
    if (random() < 0.78) {
      brush.set("2H", "#faf6ed", 0.72);
      brush.line(xL + bevelW, y, xLNext + bevelW, y + 4);
      // Tiny shadow notch right behind the jagged arris
      brush.set("2B", "#4a473f", 0.55);
      brush.line(xL + bevelW + 2.2, y, xLNext + bevelW + 2.2, y + 4);
    }
  }

  // 3. Top pedimental crown edge & upper-right sheared cleavage planes
  for (let x = 290; x < 905; x += 6) {
    let yT = slabTopEdge[x];
    let yTNext = slabTopEdge[x + 6];
    if (x < 735) {
      // Sunlit top-left weathered crown rim
      brush.set("2H", x < 580 ? "#efeae0" : "#b8b2a4", 0.85);
      brush.line(x, yT + 2, x + 6, yTNext + 2);
      brush.set("2B", "#302e29", 0.68);
      brush.line(x, yT + 14 + noise(x * 0.05) * 8, x + 6, yTNext + 14 + noise((x + 6) * 0.05) * 8);
    } else {
      // Upper-right ancient diagonal break: stepped dark cleavage planes
      brush.set("charcoal", "#1a1917", 1.25);
      brush.line(x, yT, x + 6, yTNext);
      brush.set("2B", "#47443d", 0.75);
      brush.line(x - 12, yT + 18, x - 6, yTNext + 18);
    }
  }

  // 4. Right edge deep charcoal contour & plinth horizontal masonry joint
  for (let y = 58; y < 1185; y += 6) {
    let xR = slabRightEdge[y];
    let xRNext = slabRightEdge[y + 6];
    brush.set("charcoal", "#121210", 1.35);
    brush.line(xR, y, xRNext, y + 6);
  }

  // Deep horizontal bedding joint where the slab rests on its plinth block (y = 1150)
  let pLeft = slabLeftEdge[1150];
  let pRight = slabRightEdge[1150];
  brush.set("charcoal", "#0f0f0e", 1.6);
  brush.line(pLeft, 1150, pRight, 1150);
  brush.set("2H", "#c7c1b4", 0.65);
  brush.line(pLeft - 32, 1152.5, pLeft + 260, 1152.5);
}

