// Geometric Path Builder for crisp automotive curves
class Path {
  constructor() {
    this.points = [];
  }
  M(x, y) {
    this.points.push([x, y]);
    return this;
  }
  L(x, y) {
    this.points.push([x, y]);
    return this;
  }
  Q(cx, cy, x, y, steps = 16) {
    const start = this.points.length ? this.points[this.points.length - 1] : [cx, cy];
    const [x0, y0] = start;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const mt = 1 - t;
      this.points.push([
        mt * mt * x0 + 2 * mt * t * cx + t * t * x,
        mt * mt * y0 + 2 * mt * t * cy + t * t * y
      ]);
    }
    return this;
  }
  C(c1x, c1y, c2x, c2y, x, y, steps = 22) {
    const start = this.points.length ? this.points[this.points.length - 1] : [c1x, c1y];
    const [x0, y0] = start;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const mt = 1 - t;
      this.points.push([
        mt * mt * mt * x0 + 3 * mt * mt * t * c1x + 3 * mt * t * t * c2x + t * t * t * x,
        mt * mt * mt * y0 + 3 * mt * mt * t * c1y + 3 * mt * t * t * c2y + t * t * t * y
      ]);
    }
    return this;
  }
  A(cx, cy, rx, ry, startDeg, endDeg, rotDeg = 0, steps = 28) {
    const rot = (rotDeg * Math.PI) / 180;
    const cr = Math.cos(rot);
    const sr = Math.sin(rot);
    for (let i = 0; i <= steps; i++) {
      const a = ((startDeg + ((endDeg - startDeg) * i) / steps) * Math.PI) / 180;
      const lx = Math.cos(a) * rx;
      const ly = Math.sin(a) * ry;
      this.points.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
    }
    return this;
  }
  pts(minDist = 1.5) {
    const out = [];
    for (let i = 0; i < this.points.length; i++) {
      const p = this.points[i];
      if (!out.length || Math.hypot(p[0] - out[out.length - 1][0], p[1] - out[out.length - 1][1]) >= minDist) {
        out.push([p[0], p[1]]);
      }
    }
    if (out.length > 2 && Math.hypot(out[0][0] - out[out.length - 1][0], out[0][1] - out[out.length - 1][1]) < minDist) {
      out.pop();
    }
    return out;
  }
}

function ellipsePts(cx, cy, rx, ry, rotDeg = 0, steps = 36) {
  return new Path().A(cx, cy, rx, ry, 0, 360, rotDeg, steps).pts();
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1964);
  noiseSeed(1964);

  // Custom even-weight technical pen for animation cel ink contours
  brush.add("cel_ink", {
    type: "default",
    weight: 0.72,
    scatter: 0.01,
    sharpness: 0.94,
    grain: 0.05,
    opacity: 250,
    spacing: 0.22,
    pressure: [1.0, 1.0, 1.0],
    noise: 0.02
  });

  // Custom flat felt-tip Copic marker for opaque cel fills
  brush.add("cel_marker", {
    type: "marker",
    weight: 2.2,
    scatter: 0.01,
    opacity: 52,
    spacing: 0.35,
    pressure: [1.0, 1.0, 1.0],
    markerTip: false,
    rotate: "natural",
    noise: 0.0
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // Always ensure a default brush is active before any operation
  brush.set("2B", PAL.wcDoveDark, 1);

  // =========================================================================
  // REGISTER 1: HAZY WATERCOLOR BACKGROUND (SHOPFRONTS, AWNINGS & COBBLED LANE)
  // =========================================================================
  drawWatercolorBackground();

  // Reset all soft/field/watercolor states before entering the animation cel register
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // =========================================================================
  // REGISTER 2: HYPERREAL HARD-EDGED CEL VESPA (MARKER FILLS & EVEN INK LINE)
  // =========================================================================
  drawCelVespa();

  noLoop();
}

// ===========================================================================
// WATERCOLOR HELPERS (REGISTER 1)
// ===========================================================================
function wcBlob(pts, col, opacity = 85, bleed = 0.38, tex = 0.55, border = 0.28) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0.25);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function wcRect(x, y, w, h, col, opacity = 85, bleed = 0.35, tex = 0.5, border = 0.25) {
  const j = 4;
  const pts = [
    [x + random(-j, j), y + random(-j, j)],
    [x + w * 0.5, y + random(-j, j)],
    [x + w + random(-j, j), y + random(-j, j)],
    [x + w + random(-j, j), y + h * 0.5],
    [x + w + random(-j, j), y + h + random(-j, j)],
    [x + w * 0.5, y + h + random(-j, j)],
    [x + random(-j, j), y + h + random(-j, j)],
    [x + random(-j, j), y + h * 0.5]
  ];
  wcBlob(pts, col, opacity, bleed, tex, border);
}

