  wcRect(-20, 680, 1240, 540, PAL.wcMist, 95, 0.45, 0.55, 0.2);
  wcBlob([[-20, 685], [1220, 695], [1220, 960], [-20, 920]], PAL.wcCobbleWarm, 78, 0.45, 0.6, 0.25);
