    [PAL.wcCobbleGrey]: [],
    [PAL.wcCobbleWarm]: [],
    [PAL.wcCobbleOchre]: [],
    [PAL.wcCobbleDark]: []
  };
  const cobbleColors = Object.keys(cobbleBatches);

  for (let row = 0; row < 16; row++) {
    const t = row / 15;
    const y = 700 + Math.pow(t, 1.38) * 485;
    const stoneH = 7 + t * 20;
    const stoneW = 16 + t * 44;
    const cols = Math.floor(1240 / (stoneW * 1.28));
    for (let col = 0; col < cols; col++) {
      // Skip some stones randomly so the wash breathes like true watercolor
      if (random() < 0.34) continue;
      const x = -10 + col * (stoneW * 1.28) + (row % 2) * (stoneW * 0.6) + random(-4, 4);
      const arch = Math.sin((col / cols) * Math.PI * 3.5) * (4 + t * 10);
      const sy = y + arch + random(-2, 2);
      const w = stoneW * random(0.75, 1.08);
      const h = stoneH * random(0.68, 0.96);
      const cKey = cobbleColors[Math.floor(random(cobbleColors.length))];
      cobbleBatches[cKey].push([
        [x, sy + h * 0.2],
        [x + w * 0.5, sy],
        [x + w, sy + h * 0.25],
        [x + w * 0.88, sy + h],
        [x + w * 0.15, sy + h * 0.95]
      ]);
    }
  }

  for (const cKey of cobbleColors) {
    const list = cobbleBatches[cKey];
    for (let i = 0; i < list.length; i++) {
      wcBlob(list[i], cKey, 58, 0.26, 0.45, 0.3);
