  }

  // 8. Fugitive Graphite & Wet Watercolor Brush Accents in Background (No Hard Ink!)
  brush.set("2B", PAL.wcDoveDark, 0.48);
  // Subtle architectural plumb lines and shutter slats
  for (const [sx, sy, sw, sh] of shutters) {
    brush.line(sx, sy, sx, sy + sh);
    brush.line(sx + sw, sy, sx + sw, sy + sh);
    for (let ly = sy + 16; ly < sy + sh - 12; ly += 13) {
