  }
  // Shopfront molding and curb line in soft pencil
  brush.line(375, 120, 375, 690);
  brush.line(415, 295, 1120, 295);
  brush.line(390, 415, 1155, 415);
  brush.line(0, 692, 415, 682);
  brush.line(415, 698, 1200, 712);

  // Loose curved cobblestone arcs in soft graphite
  brush.set("charcoal", PAL.wcCobbleDark, 0.38);
  for (let r = 0; r < 11; r++) {
    const ty = 735 + r * r * 3.8;
