// ===========================================================================
// ANIMATION CEL HELPERS (REGISTER 2: OPAQUE MARKER FILLS + EVEN INK CONTOURS)
// ===========================================================================
function celFill(pts, col, opacity = 250, markerAngle = null, markerSpacing = 11) {
  if (!pts || pts.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noFill();
  const poly = new brush.Polygon(pts);
  poly.wash(col, opacity);

  if (markerAngle !== null) {
    brush.hatchStyle("cel_marker", col, 1.0);
    poly.hatch(markerSpacing, markerAngle, { rand: 0.01 });
    brush.noHatch();
  }
}

function inkOutline(pts, weight = 1.0, closed = true, col = PAL.ink) {
  if (!pts || pts.length < 2) return;
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("cel_ink", col, weight);
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  if (closed) {
    brush.line(pts[pts.length - 1][0], pts[pts.length - 1][1], pts[0][0], pts[0][1]);
  }
}

function celPart(pts, col, weight = 1.0, markerAngle = null, opacity = 252) {
  celFill(pts, col, opacity, markerAngle);
  if (weight > 0) {
    inkOutline(pts, weight, true, PAL.ink);
  }
}

function inkLine(x1, y1, x2, y2, weight = 1.0, col = PAL.ink) {
  brush.noField();
  brush.set("cel_ink", col, weight);
  brush.line(x1, y1, x2, y2);
}

