function draw() {
  translate(-width / 2, -height / 2);

  // 1. Plain Newsprint Grey Ground
  background(PAL.newsprint);
  renderNewsprintGround();

  // 2. Generate all 3D anatomical pen strokes (cross-contours, dermatoglyphs, nails, creases, tendons)
  let allStrokes3D = [];
  generateWristAndForearmStrokes(allStrokes3D);
  generatePalmVaultStrokes(allStrokes3D);
  generatePalmarCreaseStrokes(allStrokes3D);
  generateFingerStrokes(allStrokes3D);
  generateSilhouetteAndOcclusionContours(allStrokes3D);

  // 3. Project 3D strokes into Left-Eye (Cyan) and Right-Eye (Scarlet) plates & compute ink density maps
  let projected = projectAndRasterizeStereo(allStrokes3D);

  // 4. Subtle tonal print undertones (Cyan fringe, Scarlet fringe, Violet-Black overlap core)
  renderStereoscopicUndertones();

  // 5. Execute the three printmaking passes: Cyan Plate, Scarlet Plate, and Dark Violet-Black Overlap Plate
  renderPlateBatches(projected);

  // 6. Final optical stipple & razor-sharp subungual / crease accents
  renderOpticalStippleAndAccents();

  noLoop();
}

