// ============================================================================
// 2. 3D SURFACE EVALUATION & Z-BUFFER CONSTRUCTION
// ============================================================================

function evalPrimitive(p, x, y) {
  if (p.type === "ellipsoid" || p.type === "palm_bowl") {
    let dx = x - p.cx;
    let dy = y - p.cy;
    let ca = cos(-p.ang);
    let sa = sin(-p.ang);
    let ux = (dx * ca - dy * sa) / p.rx;
    let uy = (dx * sa + dy * ca) / p.ry;
    let r2 = ux * ux + uy * uy;
    if (r2 >= 1.0) return null;

    let h = sqrt(1.0 - r2);
    let z = p.cz + p.rz * h;

    // Local normal in rotated space
    let lnx = ux;
    let lny = uy;
    let lnz = h;

    // If palm_bowl, carve a realistic central palmar hollow
    if (p.type === "palm_bowl") {
      let hx = (x - 596) / 118;
      let hy = (y - 642) / 115;
      let hr2 = hx * hx + hy * hy;
      if (hr2 < 1.0) {
        let dip = (1.0 - hr2) * (1.0 - hr2);
        z -= 0.085 * dip;
        lnx -= hx * 0.45 * (1.0 - hr2);
        lny -= hy * 0.45 * (1.0 - hr2);
      }
    }

    // Rotate normal back to screen space
    let ca2 = cos(p.ang);
    let sa2 = sin(p.ang);
    let nx = lnx * ca2 - lny * sa2;
    let ny = lnx * sa2 + lny * ca2;
    let nz = lnz;
    let invL = 1.0 / sqrt(nx * nx + ny * ny + nz * nz + 1e-6);
    return { z, nx: nx * invL, ny: ny * invL, nz: nz * invL, h };
  }

  if (p.type === "capsule") {
    let vx = p.x2 - p.x1;
    let vy = p.y2 - p.y1;
    let wx = x - p.x1;
    let wy = y - p.y1;
    let len2 = vx * vx + vy * vy;
    let t = constrain((wx * vx + wy * vy) / len2, 0.0, 1.0);
    let px = p.x1 + t * vx;
    let py = p.y1 + t * vy;
    let r = lerp(p.r1, p.r2, t);
    let cz = lerp(p.z1, p.z2, t);

    let dx = x - px;
    let dy = y - py;
    let d2 = (dx * dx + dy * dy) / (r * r);
    if (d2 >= 1.0) return null;

    let h = sqrt(1.0 - d2);
    let z = cz + p.rz * h;

    // Add anatomical flexor tendon cords on forearm/wrist
    if (p.id === "forearm") {
      let u = (dx / r);
      let tendon1 = exp(-pow((u + 0.14) / 0.11, 2));
      let tendon2 = exp(-pow((u - 0.16) / 0.10, 2));
      let tendonGroove = exp(-pow((u - 0.01) / 0.08, 2));
      z += (tendon1 * 0.022 + tendon2 * 0.018 - tendonGroove * 0.014) * (1.0 - t * 0.3);
    }

    let nx = dx / r;
    let ny = dy / r;
    let nz = h;
    let invL = 1.0 / sqrt(nx * nx + ny * ny + nz * nz + 1e-6);
    return { z, nx: nx * invL, ny: ny * invL, nz: nz * invL, h, t };
  }
  return null;
}

function build3DBuffers() {
  const N = GW * GH;
  zBuf = new Float32Array(N);
  partBuf = new Int16Array(N);
  nxBuf = new Float32Array(N);
  nyBuf = new Float32Array(N);
  nzBuf = new Float32Array(N);
  lightBuf = new Float32Array(N);
  creaseBuf = new Float32Array(N);
  partBuf.fill(-1);

  // Primary raking top-left-front light + dramatic contrast
  const lx = -0.34, ly = -0.46, lz = 0.82;

  for (let gy = 0; gy < GH; gy++) {
    let y = (gy + 0.5) * GSCALE;
    for (let gx = 0; gx < GW; gx++) {
      let x = (gx + 0.5) * GSCALE;
      let idx = gy * GW + gx;

      let bestZ = 0.0;
      let bestP = -1;
      let bnx = 0, bny = 0, bnz = 1;

      // Smoothly blend palm/wrist primitives, but allow closer finger segments to sharply occlude
      let palmZ = 0.0;
      let pnx = 0, pny = 0, pnz = 0, pWeight = 0;

      for (let i = 0; i < primitives.length; i++) {
        let p = primitives[i];
        let res = evalPrimitive(p, x, y);
        if (!res) continue;

        if (p.group === "palm" || p.group === "wrist") {
          if (res.z > palmZ) palmZ = res.z;
          let w = pow(res.h, 1.5);
          pnx += res.nx * w;
          pny += res.ny * w;
          pnz += res.nz * w;
          pWeight += w;
          if (res.z > bestZ) {
            bestZ = res.z;
            bestP = i;
          }
        } else {
          // Finger segments: sharp occlusion hierarchy
          if (res.z > bestZ) {
            bestZ = res.z;
            bestP = i;
            bnx = res.nx;
            bny = res.ny;
            bnz = res.nz;
          }
        }
      }

      if (bestP >= 0) {
        if (primitives[bestP].group === "palm" || primitives[bestP].group === "wrist") {
          let inv = 1.0 / sqrt(pnx * pnx + pny * pny + pnz * pnz + 1e-6);
          bnx = pnx * inv;
          bny = pny * inv;
          bnz = pnz * inv;
          bestZ = palmZ;
        }

        zBuf[idx] = bestZ;
        partBuf[idx] = bestP;
        nxBuf[idx] = bnx;
        nyBuf[idx] = bny;
        nzBuf[idx] = bnz;

        // Compute Lambertian + Specular + Rim chiaroscuro illumination
        let ndotl = bnx * lx + bny * ly + bnz * lz;
        let diffuse = constrain(ndotl * 0.65 + 0.35, 0.0, 1.0);
        let spec = pow(constrain(ndotl, 0.0, 1.0), 9.0) * 0.32;
        // Core shadow darkening near grazing angles, with subtle reflected bounce on extreme rim
        let rim = pow(1.0 - constrain(bnz, 0.0, 1.0), 2.5);
        let coreShadow = exp(-pow((ndotl + 0.15) / 0.28, 2)) * 0.25;
        let illum = constrain(diffuse + spec - coreShadow + rim * 0.08, 0.02, 1.0);
        lightBuf[idx] = illum;
      }
    }
  }

  // Imprint palm creases and finger flexion creases into the lighting & Z buffers
  imprintCreasesIntoBuffers();

  // Build per-eye Z-buffers for exact stereoscopic occlusion
  zBufC = new Float32Array(N);
  zBufS = new Float32Array(N);
  for (let gy = 0; gy < GH; gy++) {
    let y = (gy + 0.5) * GSCALE;
    for (let gx = 0; gx < GW; gx++) {
      let idx = gy * GW + gx;
      let z = zBuf[idx];
      if (z <= 0) continue;
      let x = (gx + 0.5) * GSCALE;
      let d = getStereoDelta(x, y, z);

      // Cyan shift (-d.dx, -d.dy)
      let gxc = round((x - d.dx) / GSCALE);
      let gyc = round((y - d.dy) / GSCALE);
      if (gxc >= 0 && gxc < GW && gyc >= 0 && gyc < GH) {
        let ic = gyc * GW + gxc;
        if (z > zBufC[ic]) zBufC[ic] = z;
      }

      // Scarlet shift (+d.dx, +d.dy)
      let gxs = round((x + d.dx) / GSCALE);
      let gys = round((y + d.dy) / GSCALE);
      if (gxs >= 0 && gxs < GW && gys >= 0 && gys < GH) {
        let is = gys * GW + gxs;
        if (z > zBufS[is]) zBufS[is] = z;
      }
    }
  }
}

function imprintCreasesIntoBuffers() {
  // Carve palmar creases into lightBuf and creaseBuf so cross-contours react to creases!
  for (let c of palmCreases) {
    let dense = sampleSplinePoints(c.pts, 140);
    for (let i = 0; i < dense.length; i++) {
      let px = dense[i][0];
      let py = dense[i][1];
      let gx0 = floor(px / GSCALE);
      let gy0 = floor(py / GSCALE);
      let rad = 5;
      for (let dy = -rad; dy <= rad; dy++) {
        for (let dx = -rad; dx <= rad; dx++) {
          let gx = gx0 + dx;
          let gy = gy0 + dy;
          if (gx < 0 || gx >= GW || gy < 0 || gy >= GH) continue;
          let idx = gy * GW + gx;
          if (zBuf[idx] <= 0) continue;
          // Only carve into palm/wrist (not into closer overhanging fingers!)
          let pGroup = primitives[partBuf[idx]].group;
          if (pGroup !== "palm" && pGroup !== "wrist") continue;

          let dist = sqrt(dx * dx + dy * dy) * GSCALE;
          if (dist < 8.5) {
            let v = exp(-pow(dist / 3.8, 2)) * c.weight;
            creaseBuf[idx] = max(creaseBuf[idx], v);
            lightBuf[idx] = max(0.02, lightBuf[idx] - v * 0.42);
          }
        }
      }
    }
  }
}

// ============================================================================
// 3. STEREOSCOPIC DISPARITY & PROJECTION ENGINE
// ============================================================================

function getStereoDelta(x, y, z) {
  // Wrist (z ~ 0.04) nearly converges (~1.6px each way = 3.2px total)
  // Fingertips (z ~ 0.95-1.0) offset widely (~26px each way = 52px total)
  let zp = pow(constrain(z, 0.0, 1.05), 1.48);
  let dx = 1.4 + 25.2 * zp + 0.011 * (x - 590) * zp;
  let dy = 0.4 + 5.8 * zp + 0.009 * (y - 620) * zp;
  return { dx, dy };
}

function querySurface(x, y) {
  let gx = constrain(floor(x / GSCALE), 0, GW - 1);
  let gy = constrain(floor(y / GSCALE), 0, GH - 1);
  let idx = gy * GW + gx;
  return {
    z: zBuf[idx],
    part: partBuf[idx],
    nx: nxBuf[idx],
    ny: nyBuf[idx],
    nz: nzBuf[idx],
    light: lightBuf[idx],
    crease: creaseBuf[idx]
  };
}

// ============================================================================
// 4. HYPERREALIST ANATOMICAL PEN HATCHING GENERATORS
// ============================================================================

// Helper: push a 3D polyline [[x, y, z, pressure], ...] with brush metadata
function addStroke3D(list, pts, brushName, weight, curvature = 0.35, role = "hatch") {
  // Split into clean contiguous visible segments with point spacing >= 2.8px
  let current = [];
  for (let i = 0; i < pts.length; i++) {
    let pt = pts[i];
    if (!pt || !pt. visible) {
      if (current.length >= 2) flushSegment(list, current, brushName, weight, curvature, role);
      current = [];
      continue;
    }
    if (current.length === 0) {
      current.push(pt);
    } else {
      let prev = current[current.length - 1];
      let d = dist(prev.x, prev.y, pt.x, pt.y);
      if (d >= 2.8) {
        current.push(pt);
      } else if (i === pts.length - 1 && d >= 1.2) {
        current.push(pt);
      }
    }
  }
  if (current.length >= 2) {
    flushSegment(list, current, brushName, weight, curvature, role);
  }
}

function flushSegment(list, seg, brushName, weight, curvature, role) {
  // Subdivide long segments into manageable chunks so per-segment overlap coloring is super sharp!
  const maxChunk = 11;
  if (seg.length <= maxChunk) {
    list.push({ pts: seg, brushName, weight, curvature, role });
  } else {
    for (let i = 0; i < seg.length - 1; i += maxChunk - 1) {
      let sub = seg.slice(i, min(seg.length, i + maxChunk));
      if (sub.length >= 2) {
        list.push({ pts: sub, brushName, weight, curvature, role });
      }
    }
  }
}

// --- A. WRIST & FOREARM CROSS-CONTOUR ENGRAVING ---
function generateWristAndForearmStrokes(out) {
  // 1. Primary cross-contour arcs wrapping over the wrist & flexor tendons
  const numRows = 44;
  for (let r = 0; r < numRows; r++) {
    let v = r / (numRows - 1);
    let yBase = lerp(862, 1175, v);
    let xCenter = lerp(608, 642, v);
    let halfW = lerp(106, 120, v);

    let pts = [];
    let steps = 26;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -0.96, 0.96);
      let x = xCenter + u * halfW;
      // Cylindrical wrap + slight upward buckle over the two central flexor tendons
      let arch = -sqrt(max(0, 1.0 - u * u)) * 22 * (1.0 - v * 0.35);
      let tendonBuckle = -4.5 * (exp(-pow((u + 0.14) / 0.12, 2)) + exp(-pow((u - 0.16) / 0.11, 2)));
      let y = yBase + arch + tendonBuckle;

      let surf = querySurface(x, y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "wrist";
      let shade = 1.0 - surf.light;
      // Skip brightest highlight strips on alternative rows for engraving halftone
      if (shade < 0.26 && r % 2 === 1) vis = false;

      let pr = constrain(map(shade, 0.15, 0.85, 0.22, 1.25), 0.2, 1.35);
      pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, "burin", 0.44, 0.35, "hatch");
  }

  // 2. Longitudinal tendon striation & shadow cross-hatching along forearm
  const numCols = 32;
  for (let c = 0; c < numCols; c++) {
    let u = map(c, 0, numCols - 1, -0.92, 0.92);
    // Concentrate lines in the tendon channels and ulnar/radial shadow borders
    let inChannel = abs(u - 0.01) < 0.12 || abs(u + 0.34) < 0.14 || u > 0.32 || u < -0.52;
    if (!inChannel && c % 2 === 1) continue;

    let pts = [];
    let steps = 28;
    for (let s = 0; s <= steps; s++) {
      let v = s / steps;
      let y = lerp(868, 1172, v);
      let xCenter = lerp(608, 642, v);
      let halfW = lerp(105, 119, v);
      let x = xCenter + u * halfW + sin(v * 180 + c * 25) * 2.5;

      let surf = querySurface(x, y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "wrist";
      let shade = 1.0 - surf.light;
      if (shade < 0.36) vis = false;

      let pr = constrain(map(shade, 0.32, 0.88, 0.25, 1.15), 0.2, 1.2);
      pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, "needle", 0.38, 0.25, "hatch");
  }
}

// --- B. PALM VAULT, THENAR, HYPOTHENAR, & METACARPAL MOUNTS ---
function generatePalmVaultStrokes(out) {
  // 1. Sweeping Muscular Cross-Contours on the Thenar Eminence (Thumb Mound)
  const thenarLines = 52;
  for (let i = 0; i < thenarLines; i++) {
    let t = i / (thenarLines - 1);
    let ang = lerp(-155, 25, t);
    let pts = [];
    let steps = 24;
    for (let s = 0; s <= steps; s++) {
      let rFrac = map(s, 0, steps, 0.08, 1.08);
      // Curved muscular fibers radiating from carpus/life-line over the thenar belly
      let curveBend = sin(rFrac * 150) * 14;
      let a = ang + curveBend * 0.4;
      let ux = cos(a) * rFrac * 132;
      let uy = sin(a) * rFrac * 172;
      let ca = cos(-24), sa = sin(-24);
      let x = 465 + (ux * ca - uy * sa);
      let y = 725 + (ux * sa + uy * ca);

      let surf = querySurface(x, y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "palm";
      let shade = 1.0 - surf.light;
      // Leave crisp highlight on the upper-left ridge of the Thenar mound
      if (shade < 0.22 && i % 2 === 0) vis = false;
      if (shade < 0.14) vis = false;

      let pr = constrain(map(shade, 0.15, 0.85, 0.20, 1.25), 0.18, 1.3);
      pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, "burin", 0.42, 0.4, "hatch");
  }

  // 2. Transverse Bowl Contours across the Central Palmar Hollow & Hypothenar Eminence
  const palmRows = 68;
  for (let r = 0; r < palmRows; r++) {
    let v = r / (palmRows - 1);
    let yBase = lerp(465, 875, v);
    let pts = [];
    let steps = 42;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -1.0, 1.0);
      let x = 602 + u * 238;
      // Dip down into the central palmar basin and rise over the hypothenar mound
      let bowlDip = exp(-pow((x - 595) / 115, 2)) * 28 * sin(v * 180);
      let y = yBase + bowlDip + sin(u * 160) * 8;

      let surf = querySurface(x, y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "palm";
      let shade = 1.0 - surf.light;
      if (shade < 0.24 && r % 2 === 1) vis = false;
      if (shade < 0.15) vis = false;

      let pr = constrain(map(shade, 0.15, 0.85, 0.22, 1.28), 0.2, 1.35);
      pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, "burin", 0.44, 0.35, "hatch");
  }

  // 3. Secondary & Tertiary Diamond Engraving Cross-Hatching in the Deep Palmar Hollow & Ulnar Shadow
  const hatchAngles = [36, -42];
  for (let hIdx = 0; hIdx < hatchAngles.length; hIdx++) {
    let ang = hatchAngles[hIdx];
    let ca = cos(ang), sa = sin(ang);
    let numLines = hIdx === 0 ? 58 : 44;
    let minShade = hIdx === 0 ? 0.36 : 0.50;

    for (let i = 0; i < numLines; i++) {
      let offset = map(i, 0, numLines - 1, -240, 240);
      let pts = [];
      let steps = 36;
      for (let s = 0; s <= steps; s++) {
        let along = map(s, 0, steps, -230, 230);
        let x = 605 + along * ca - offset * sa;
        let y = 665 + along * sa + offset * ca;

        let surf = querySurface(x, y);
        let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "palm";
        let shade = 1.0 - surf.light;
        if (shade < minShade) vis = false;

        let pr = constrain(map(shade, minShade, 0.92, 0.22, 1.2), 0.2, 1.25);
        pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
      }
      addStroke3D(out, pts, "needle", 0.38, 0.25, "hatch");
    }
  }

  // 4. Concentric Cushion Contours on the Four Distal Metacarpal Mounts & Webs
  const mountCenters = [
    { cx: 474, cy: 505, rx: 68, ry: 62, ang: -18 },
    { cx: 585, cy: 476, rx: 70, ry: 60, ang: -2 },
    { cx: 696, cy: 498, rx: 66, ry: 60, ang: 16 },
    { cx: 790, cy: 564, rx: 60, ry: 56, ang: 30 }
  ];
  for (let m of mountCenters) {
    let rings = 14;
    for (let r = 2; r <= rings; r++) {
      let rf = r / rings;
      let pts = [];
      let steps = 24;
      for (let s = 0; s <= steps; s++) {
        let a = map(s, 0, steps, -10, 195);
        let ux = cos(a) * m.rx * rf;
        let uy = sin(a) * m.ry * rf * 0.85;
        let ca = cos(m.ang), sa = sin(m.ang);
        let x = m.cx + ux * ca - uy * sa;
        let y = m.cy + ux * sa + uy * ca;

        let surf = querySurface(x, y);
        let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "palm";
        let shade = 1.0 - surf.light;
        if (shade < 0.22 && r % 2 === 0) vis = false;

        let pr = constrain(map(shade, 0.16, 0.85, 0.22, 1.15), 0.2, 1.2);
        pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
      }
      addStroke3D(out, pts, "needle", 0.36, 0.35, "hatch");
    }
  }
}

// --- C. RAZOR-SHARP PALMAR CREASES & MICRO-WRINKLE NETWORKS ---
function generatePalmarCreaseStrokes(out) {
  for (let c of palmCreases) {
    let dense = sampleSplinePoints(c.pts, 48);

    // 1. Primary deep fissure line
    let mainPts = [];
    // 2. Parallel secondary bevel fold line (offset by 3.8px)
    let foldPts = [];

    for (let i = 0; i < dense.length; i++) {
      let x = dense[i][0];
      let y = dense[i][1];
      let surf = querySurface(x, y);
      let pGroup = surf.part >= 0 ? primitives[surf.part].group : "";
      let vis = surf.z > 0.01 && (pGroup === "palm" || pGroup === "wrist");

      let t = i / (dense.length - 1);
      let taper = sin(t * 180);
      let pr = c.weight * (0.45 + 0.75 * taper);
      mainPts.push({ x, y, z: surf.z + 0.008, pr, shade: 0.92, visible: vis });

      // Normal vector to crease
      let i0 = max(0, i - 1), i1 = min(dense.length - 1, i + 1);
      let tx = dense[i1][0] - dense[i0][0];
      let ty = dense[i1][1] - dense[i0][1];
      let tl = sqrt(tx * tx + ty * ty + 1e-6);
      let nx = (-ty / tl) * c.featherDir;
      let ny = (tx / tl) * c.featherDir;

      let fx = x + nx * 4.2;
      let fy = y + ny * 4.2;
      let fSurf = querySurface(fx, fy);
      let fGroup = fSurf.part >= 0 ? primitives[fSurf.part].group : "";
      let fVis = fSurf.z > 0.01 && (fGroup === "palm" || fGroup === "wrist");
      foldPts.push({ x: fx, y: fy, z: fSurf.z + 0.005, pr: pr * 0.58, shade: 0.75, visible: fVis });
    }

    addStroke3D(out, mainPts, "crease_knife", 0.65 * c.weight, 0.35, "crease");
    addStroke3D(out, foldPts, "burin", 0.42 * c.weight, 0.35, "crease");

    // 3. Feathering tributary hachures & crow's-foot skin tension ticks along the crease
    let featherDense = sampleSplinePoints(c.pts, c.featherCount);
    for (let i = 1; i < featherDense.length - 1; i++) {
      let x = featherDense[i][0];
      let y = featherDense[i][1];
      let tx = featherDense[i + 1][0] - featherDense[i - 1][0];
      let ty = featherDense[i + 1][1] - featherDense[i - 1][1];
      let tl = sqrt(tx * tx + ty * ty + 1e-6);
      tx /= tl; ty /= tl;
      let nx = -ty * c.featherDir;
      let ny = tx * c.featherDir;

      // Short diagonal feathering tick diving into the crease canyon
      let tickLen = random(9, 24) * c.weight;
      let slant = random(-0.45, 0.45);
      let dx = nx + tx * slant;
      let dy = ny + ty * slant;

      let tickPts = [];
      for (let s = 0; s <= 4; s++) {
        let f = s / 4;
        let px = x + dx * tickLen * f;
        let py = y + dy * tickLen * f;
        let surf = querySurface(px, py);
        let pGroup = surf.part >= 0 ? primitives[surf.part].group : "";
        let vis = surf.z > 0.01 && (pGroup === "palm" || pGroup === "wrist");
        let pr = (1.0 - f * 0.8) * 0.95 * c.weight;
        tickPts.push({ x: px, y: py, z: surf.z + 0.004, pr, shade: 0.82, visible: vis });
      }
      addStroke3D(out, tickPts, "needle", 0.42, 0.2, "crease");
    }
  }

  // 4. Fine Epidermal Flexure Criss-Cross Lines across the Central Palmar Aponeurosis
  for (let i = 0; i < 95; i++) {
    let cx = random(435, 775);
    let cy = random(510, 845);
    let surf0 = querySurface(cx, cy);
    if (surf0.z <= 0.01 || surf0.part < 0 || primitives[surf0.part].group !== "palm") continue;

    let ang = random([-52, -22, 18, 48, 75]) + random(-8, 8);
    let len = random(14, 36);
    let ca = cos(ang), sa = sin(ang);
    let pts = [];
    for (let s = -2; s <= 2; s++) {
      let px = cx + ca * (s * len * 0.25);
      let py = cy + sa * (s * len * 0.25);
      let surf = querySurface(px, py);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === "palm";
      let pr = (1.0 - abs(s) * 0.35) * (1.1 - surf.light * 0.6);
      pts.push({ x: px, y: py, z: surf.z, pr, shade: 1.0 - surf.light, visible: vis });
    }
    addStroke3D(out, pts, "needle", 0.34, 0.2, "hatch");
  }
}

// --- D. ENORMOUSLY FORESHORTENED FINGERS, FINGERNAILS, & DERMATOGLYPHS ---
function generateFingerStrokes(out) {
  for (let f of fingers) {
    let fGroup = "finger_" + f.index;

    // 1. Proximal & Middle Phalanges: Cylindrical Perspective Cross-Contours
    for (let sIdx = 0; sIdx < 2; sIdx++) {
      let seg = f.segments[sIdx];
      let numRings = 24;
      for (let r = 0; r < numRings; r++) {
        let t = r / (numRings - 1);
        let cx = lerp(seg.x1, seg.x2, t);
        let cy = lerp(seg.y1, seg.y2, t);
        let rad = lerp(seg.r1, seg.r2, t);

        let vx = seg.x2 - seg.x1;
        let vy = seg.y2 - seg.y1;
        let vLen = sqrt(vx * vx + vy * vy + 1e-6);
        let ux = vx / vLen, uy = vy / vLen;
        let nx = -uy, ny = ux;

        let pts = [];
        let steps = 22;
        for (let k = 0; k <= steps; k++) {
          let u = map(k, 0, steps, -0.98, 0.98);
          // Perspective U-curve wrapping around the underside of the foreshortened cylinder
          let bellyDrop = sqrt(max(0, 1.0 - u * u)) * rad * 0.48;
          let x = cx + nx * (u * rad) - ux * bellyDrop;
          let y = cy + ny * (u * rad) - uy * bellyDrop;

          let surf = querySurface(x, y);
          // Strict occlusion check: only draw if THIS segment (or same finger non-tip) is visible!
          let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === seg.id;
          let shade = 1.0 - surf.light;
          if (shade < 0.22 && r % 2 === 1) vis = false;

          let pr = constrain(map(shade, 0.15, 0.88, 0.24, 1.32), 0.2, 1.35);
          pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
        }
        addStroke3D(out, pts, "burin", 0.44, 0.4, "hatch");
      }

      // Secondary oblique cross-hatching on the shadowed lower belly & side of each phalanx
      let numDiag = 22;
      for (let d = 0; d < numDiag; d++) {
        let u0 = map(d, 0, numDiag - 1, -0.92, 0.92);
        let pts = [];
        let steps = 16;
        for (let k = 0; k <= steps; k++) {
          let t = k / steps;
          let u = constrain(u0 + (t - 0.5) * 0.65, -0.96, 0.96);
          let cx = lerp(seg.x1, seg.x2, t);
          let cy = lerp(seg.y1, seg.y2, t);
          let rad = lerp(seg.r1, seg.r2, t);

          let vx = seg.x2 - seg.x1, vy = seg.y2 - seg.y1;
          let vLen = sqrt(vx * vx + vy * vy + 1e-6);
          let ux = vx / vLen, uy = vy / vLen;
          let nx = -uy, ny = ux;

          let x = cx + nx * (u * rad);
          let y = cy + ny * (u * rad);
          let surf = querySurface(x, y);
          let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === seg.id;
          let shade = 1.0 - surf.light;
          if (shade < 0.36) vis = false;

          let pr = constrain(map(shade, 0.32, 0.90, 0.25, 1.2), 0.2, 1.25);
          pts.push({ x, y, z: surf.z, pr, shade, visible: vis });
        }
        addStroke3D(out, pts, "needle", 0.38, 0.3, "hatch");
      }
    }

    // 2. Interphalangeal Joint Flexion Creases (MCP, PIP double-crease, DIP saddle crease)
    for (let cr of f.creases) {
      let ca = cos(cr.ang), sa = sin(cr.ang);
      let passes = cr.double ? [-3.5, 3.5] : [0];
      for (let off of passes) {
        let pts = [];
        let steps = 20;
        for (let k = 0; k <= steps; k++) {
          let a = map(k, 0, steps, 90 - cr.span * 0.5, 90 + cr.span * 0.5);
          let lx = cos(a - 90) * cr.r * 0.95;
          let ly = sin(a - 90) * cr.r * 0.34 + off;
          let x = cr.cx + lx * ca - ly * sa;
          let y = cr.cy + lx * sa + ly * ca;

          let surf = querySurface(x, y);
          let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === fGroup;
          let t = k / steps;
          let pr = sin(t * 180) * 1.35;
          pts.push({ x, y, z: surf.z + 0.008, pr, shade: 0.92, visible: vis });
        }
        addStroke3D(out, pts, "crease_knife", 0.62, 0.4, "crease");
      }

      // Short longitudinal joint fold ticks crossing into the flexion crease
      for (let k = 0; k < 14; k++) {
        let u = map(k, 0, 13, -0.78, 0.78);
        let lx = u * cr.r;
        let lyBase = (1.0 - u * u) * cr.r * 0.28;
        let tickPts = [];
        for (let s = -2; s <= 2; s++) {
          let ly = lyBase + s * 4.2;
          let x = cr.cx + lx * ca - ly * sa;
          let y = cr.cy + lx * sa + ly * ca;
          let surf = querySurface(x, y);
          let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].group === fGroup;
          let pr = (1.0 - abs(s) * 0.3) * 0.85;
          tickPts.push({ x, y, z: surf.z + 0.005, pr, shade: 0.80, visible: vis });
        }
        addStroke3D(out, tickPts, "needle", 0.38, 0.2, "crease");
      }
    }

    // 3. ENORMOUS DISTAL PHALANX (FINGERTIP): Foreshortened Fingernail, Hyponychium, & Dermatoglyph Whorls
    let tip = f.segments[2];
    generateFingertipDetail(out, tip, f.ang);
  }
}

function generateFingertipDetail(out, tip, ang) {
  let ca = cos(ang), sa = sin(ang);
  let rx = tip.rx, ry = tip.ry;

  // Helper to convert fingertip local (u, v) in [-1, 1]^2 to world (x, y)
  function toWorld(u, v) {
    let lx = u * rx;
    let ly = v * ry;
    return {
      x: tip.cx + lx * ca - ly * sa,
      y: tip.cy + lx * sa + ly * ca
    };
  }

  // --- 3A. FORESHORTENED FINGERNAIL VISOR (Top arch of fingertip: v in [-0.94, -0.44]) ---
  // 1. Cuticle / Eponychium upper arch & Free Nail Edge lower arch
  const nailContours = [
    { vBase: -0.91, arch: 0.34, uMax: 0.72, weight: 0.58, brush: "burin", shade: 0.82 }, // Eponychium fold
    { vBase: -0.87, arch: 0.33, uMax: 0.70, weight: 0.38, brush: "needle", shade: 0.70 }, // Cuticle inner rim
    { vBase: -0.68, arch: 0.28, uMax: 0.46, weight: 0.34, brush: "needle", shade: 0.45 }, // Lunula crescent
    { vBase: -0.48, arch: 0.26, uMax: 0.78, weight: 0.68, brush: "crease_knife", shade: 0.92 }, // Free nail edge
    { vBase: -0.43, arch: 0.25, uMax: 0.76, weight: 0.55, brush: "burin", shade: 0.90 }  // Hyponychium rim
  ];

  for (let nc of nailContours) {
    let pts = [];
    let steps = 22;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -nc.uMax, nc.uMax);
      let v = nc.vBase + nc.arch * (u * u);
      let w = toWorld(u, v);
      let surf = querySurface(w.x, w.y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === tip.id;
      let pr = (0.5 + 0.6 * (1.0 - abs(u))) * (nc.weight / 0.5);
      pts.push({ x: w.x, y: w.y, z: tip.cz + 0.015, pr, shade: nc.shade, visible: vis });
    }
    addStroke3D(out, pts, nc.brush, nc.weight, 0.4, "crease");
  }

  // 2. Longitudinal keratin striations across the curved nail plate (skipping specular highlight band)
  let nailStriations = 26;
  for (let i = 0; i < nailStriations; i++) {
    let u = map(i, 0, nailStriations - 1, -0.70, 0.70);
    let vTop = -0.88 + 0.33 * (u * u);
    let vBot = -0.48 + 0.26 * (u * u);
    let pts = [];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let f = s / steps;
      let v = lerp(vTop, vBot, f);
      let w = toWorld(u * (1.0 + f * 0.06), v);
      let surf = querySurface(w.x, w.y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === tip.id;
      // Bright specular highlight band across the crown of the nail around u in [-0.38, 0.08], f in [0.3, 0.7]
      if (u > -0.38 && u < 0.08 && f > 0.28 && f < 0.72) vis = false;
      let pr = (0.35 + 0.65 * abs(u)) * 0.85;
      pts.push({ x: w.x, y: w.y, z: tip.cz + 0.012, pr, shade: 0.55 + 0.35 * abs(u), visible: vis });
    }
    addStroke3D(out, pts, "needle", 0.34, 0.25, "hatch");
  }

  // 3. Deep Subungual Shadow (Hyponychium crevice directly beneath the overhanging nail edge)
  for (let row = 0; row < 5; row++) {
    let rf = row / 4;
    let pts = [];
    let steps = 24;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -0.78, 0.78);
      let vTop = -0.48 + 0.26 * (u * u);
      let vBot = -0.35 + 0.24 * (u * u);
      let v = lerp(vTop, vBot, rf);
      let w = toWorld(u, v);
      let surf = querySurface(w.x, w.y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === tip.id;
      let pr = (1.0 - abs(u) * 0.4) * 1.25;
      pts.push({ x: w.x, y: w.y, z: tip.cz + 0.014, pr, shade: 0.95, visible: vis });
    }
    addStroke3D(out, pts, "burin", 0.48, 0.35, "crease");
  }

  // --- 3B. APICAL PULP (FINGER PAD): Concentric Dermatoglyph Whorls & Loops ---
  // Center of the fingerprint whorl sits at (u = 0, v = 0.16)
  const numWhorls = 34;
  for (let wIdx = 1; wIdx <= numWhorls; wIdx++) {
    let wf = wIdx / numWhorls; // 0.03 -> 1.0
    let pts = [];
    let steps = 36;
    for (let s = 0; s <= steps; s++) {
      // Trace elliptical whorl loop around (0, 0.16), clipped by the subungual groove above and DIP crease below
      let theta = map(s, 0, steps, -205, 155);
      let u = cos(theta) * wf * 0.96;
      let v = 0.16 + sin(theta) * wf * 0.78;
      // Arch upper ridges slightly to hug the subungual contour
      if (v < 0) v -= 0.08 * (1.0 - u * u) * wf;

      // Clip against the hyponychium boundary at top and fingertip rim
      let vHypo = -0.35 + 0.24 * (u * u);
      if (v < vHypo || u * u + v * v > 0.96) {
        pts.push({ visible: false });
        continue;
      }

      let w = toWorld(u, v);
      let surf = querySurface(w.x, w.y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === tip.id;
      let shade = 1.0 - surf.light;

      // Specular skin highlight on upper-left dome of finger pad: break every second ridge cleanly
      if (shade < 0.20 && wIdx % 2 === 0) vis = false;
      if (shade < 0.12) vis = false;

      let pr = constrain(map(shade, 0.12, 0.85, 0.20, 1.25), 0.18, 1.30);
      pts.push({ x: w.x, y: w.y, z: surf.z + 0.004, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, wIdx % 3 === 0 ? "burin" : "needle", 0.39, 0.4, "hatch");
  }

  // --- 3C. Secondary Shadow Cross-Hatching on Lower/Right Belly of Fingertip Pad ---
  for (let d = 0; d < 24; d++) {
    let v0 = map(d, 0, 23, -0.25, 0.88);
    let pts = [];
    let steps = 18;
    for (let s = 0; s <= steps; s++) {
      let u = map(s, 0, steps, -0.88, 0.92);
      let v = v0 + 0.22 * (u * u) + u * 0.18;
      if (u * u + v * v > 0.95) {
        pts.push({ visible: false });
        continue;
      }
      let w = toWorld(u, v);
      let surf = querySurface(w.x, w.y);
      let vis = surf.z > 0.01 && surf.part >= 0 && primitives[surf.part].id === tip.id;
      let shade = 1.0 - surf.light;
      if (shade < 0.42) vis = false;

      let pr = constrain(map(shade, 0.40, 0.92, 0.25, 1.22), 0.22, 1.25);
      pts.push({ x: w.x, y: w.y, z: surf.z + 0.005, pr, shade, visible: vis });
    }
    addStroke3D(out, pts, "burin", 0.42, 0.35, "hatch");
  }
}

// --- E. EXPRESSIVE OUTER SILHOUETTE & PHALANX OCCLUSION CONTOURS ---
function generateSilhouetteAndOcclusionContours(out) {
  // Trace exact boundary contours around every fingertip, phalanx, web, palm edge, and wrist
  for (let i = 0; i < primitives.length; i++) {
    let p = primitives[i];
    if (p.type === "ellipsoid" || p.type === "palm_bowl") {
      if (p.id === "palm_core") continue;
      let steps = 64;
      for (let pass = 0; pass < 2; pass++) {
        let rScale = pass === 0 ? 0.97 : 0.93;
        let pts = [];
        for (let s = 0; s <= steps; s++) {
          let a = map(s, 0, steps, 0, 360);
          let ux = cos(a) * p.rx * rScale;
          let uy = sin(a) * p.ry * rScale;
          let ca = cos(p.ang), sa = sin(p.ang);
          let x = p.cx + ux * ca - uy * sa;
          let y = p.cy + ux * sa + uy * ca;

          let surf = querySurface(x, y);
          // Check if this point is near an exterior silhouette or an occlusion jump
          let isVis = surf.z > 0.01 && (surf.part === i || (p.isTip && abs(surf.z - p.cz) < 0.22));
          if (isVis && !p.isTip) {
            // Only keep outer boundary of palm/mounts where adjacent to background or deep crease
            let nOut = querySurface(x + cos(a + p.ang) * 7, y + sin(a + p.ang) * 7);
            if (nOut.z > 0.01 && abs(nOut.z - surf.z) < 0.06) isVis = false;
          }

          let shade = 1.0 - surf.light;
          let pr = constrain(0.45 + shade * 0.95, 0.35, 1.4);
          pts.push({ x, y, z: max(surf.z, p.cz), pr, shade: max(0.75, shade), visible: isVis });
        }
        addStroke3D(out, pts, pass === 0 ? "crease_knife" : "burin", pass === 0 ? 0.62 : 0.42, 0.35, "contour");
      }
    }

    if (p.type === "capsule") {
      // Left and right lateral scalloped contours of each phalanx and forearm
      let vx = p.x2 - p.x1, vy = p.y2 - p.y1;
      let vLen = sqrt(vx * vx + vy * vy + 1e-6);
      let nx = -vy / vLen, ny = vx / vLen;

      for (let side of [-1, 1]) {
        for (let pass = 0; pass < 2; pass++) {
          let rMult = pass === 0 ? 0.96 : 0.91;
          let pts = [];
          let steps = 24;
          for (let s = 0; s <= steps; s++) {
            let t = s / steps;
            let cx = lerp(p.x1, p.x2, t);
            let cy = lerp(p.y1, p.y2, t);
            let r = lerp(p.r1, p.r2, t) * rMult;
            let x = cx + nx * side * r;
            let y = cy + ny * side * r;

            let surf = querySurface(x, y);
            let isVis = surf.z > 0.01 && surf.part === i;
            let shade = 1.0 - surf.light;
            let pr = constrain(0.45 + shade * 0.9, 0.35, 1.35);
            pts.push({ x, y, z: surf.z, pr, shade: max(0.72, shade), visible: isVis });
          }
          addStroke3D(out, pts, pass === 0 ? "crease_knife" : "burin", pass === 0 ? 0.58 : 0.40, 0.3, "contour");
        }
      }
    }
  }
}

// ============================================================================
// 5. STEREOSCOPIC PROJECTION & SUBTRACTIVE OVERLAP RASTERIZER
// ============================================================================

function projectAndRasterizeStereo(strokes3D) {
  const N = GW * GH;
  cyanInkMap = new Float32Array(N);
  scarletInkMap = new Float32Array(N);

  // Seed ink maps with continuous 3D shadow density of each shifted eye projection
  for (let gy = 0; gy < GH; gy++) {
    let y = (gy + 0.5) * GSCALE;
    for (let gx = 0; gx < GW; gx++) {
      let idx = gy * GW + gx;
      let z = zBuf[idx];
      if (z <= 0) continue;
      let x = (gx + 0.5) * GSCALE;
      let shade = 1.0 - lightBuf[idx];
      let d = getStereoDelta(x, y, z);

      let gxc = round((x - d.dx) / GSCALE);
      let gyc = round((y - d.dy) / GSCALE);
      if (gxc >= 0 && gxc < GW && gyc >= 0 && gyc < GH) {
        let ic = gyc * GW + gxc;
        cyanInkMap[ic] = max(cyanInkMap[ic], shade * 0.65);
      }

      let gxs = round((x + d.dx) / GSCALE);
      let gys = round((y + d.dy) / GSCALE);
      if (gxs >= 0 && gxs < GW && gys >= 0 && gys < GH) {
        let is = gys * GW + gxs;
        scarletInkMap[is] = max(scarletInkMap[is], shade * 0.65);
      }
    }
  }

  let cyanStrokes = [];
  let scarletStrokes = [];

  for (let st of strokes3D) {
    let cPts = [];
    let sPts = [];
    let sumShade = 0;

    for (let pt of st.pts) {
      let d = getStereoDelta(pt.x, pt.y, pt.z);
      let cx = pt.x - d.dx;
      let cy = pt.y - d.dy;
      let sx = pt.x + d.dx;
      let sy = pt.y + d.dy;

      cPts.push([cx, cy, pt.pr]);
      sPts.push([sx, sy, pt.pr]);
      sumShade += pt.shade;

      // Stamp stroke ink into cyanInkMap and scarletInkMap (2px radius)
      stampInk(cyanInkMap, cx, cy, st.weight * pt.pr * 0.85);
      stampInk(scarletInkMap, sx, sy, st.weight * pt.pr * 0.85);
    }

    let avgShade = sumShade / st.pts.length;
    cyanStrokes.push({ pts: cPts, brushName: st.brushName, weight: st.weight, curvature: st.curvature, shade: avgShade, role: st.role });
    scarletStrokes.push({ pts: sPts, brushName: st.brushName, weight: st.weight, curvature: st.curvature, shade: avgShade, role: st.role });
  }

  // Classify overlapping segments to build the Dark Violet-Black Overlap Plate
  let overlapStrokes = [];

  for (let cs of cyanStrokes) {
    let otherInk = sampleInkAlongPath(scarletInkMap, cs.pts);
    cs.overlap = otherInk;
    if (otherInk > 0.36) {
      overlapStrokes.push({
        pts: cs.pts,
        brushName: cs.brushName,
        weight: cs.weight * map(otherInk, 0.36, 1.0, 0.78, 1.08),
        curvature: cs.curvature,
        density: otherInk,
        role: cs.role
      });
    }
  }

  for (let ss of scarletStrokes) {
    let otherInk = sampleInkAlongPath(cyanInkMap, ss.pts);
    ss.overlap = otherInk;
    if (otherInk > 0.36) {
      overlapStrokes.push({
        pts: ss.pts,
        brushName: ss.brushName,
        weight: ss.weight * map(otherInk, 0.36, 1.0, 0.78, 1.08),
        curvature: ss.curvature,
        density: otherInk,
        role: ss.role
      });
    }
  }

  return { cyanStrokes, scarletStrokes, overlapStrokes };
}

function stampInk(grid, x, y, val) {
  let gx0 = round(x / GSCALE);
  let gy0 = round(y / GSCALE);
  for (let dy = -1; dy <= 1; dy++) {
    let gy = gy0 + dy;
    if (gy < 0 || gy >= GH) continue;
    for (let dx = -1; dx <= 1; dx++) {
      let gx = gx0 + dx;
      if (gx < 0 || gx >= GW) continue;
      let w = (dx === 0 && dy === 0) ? 1.0 : 0.6;
      let idx = gy * GW + gx;
      grid[idx] = min(1.2, grid[idx] + val * w);
    }
  }
}

function sampleInkAlongPath(grid, pts) {
  let sum = 0;
  let maxV = 0;
  for (let i = 0; i < pts.length; i++) {
    let gx = constrain(round(pts[i][0] / GSCALE), 0, GW - 1);
    let gy = constrain(round(pts[i][1] / GSCALE), 0, GH - 1);
    let v = grid[gy * GW + gx];
    sum += v;
    if (v > maxV) maxV = v;
  }
  return (sum / pts.length) * 0.65 + maxV * 0.35;
}

