function renderStereoscopicUndertones() {
  brush.noStroke();

  // 1. Subtle Cyan plate tonal wash on fingertips, palm hollow, and wrist
  brush.wash(PAL.cyanMid, 16);
  for (let f of fingers) {
    let tip = f.segments[2];
    let d = getStereoDelta(tip.cx, tip.cy, tip.cz);
    brush.circle(tip.cx - d.dx, tip.cy - d.dy, (tip.rx + tip.ry) * 0.46, 0.12);
  }
  let dp = getStereoDelta(602, 655, 0.35);
  brush.circle(602 - dp.dx, 655 - dp.dy, 195, 0.18);

  // 2. Subtle Scarlet plate tonal wash on fingertips, palm hollow, and wrist
  brush.wash(PAL.scarletMid, 16);
  for (let f of fingers) {
    let tip = f.segments[2];
    let d = getStereoDelta(tip.cx, tip.cy, tip.cz);
    brush.circle(tip.cx + d.dx, tip.cy + d.dy, (tip.rx + tip.ry) * 0.46, 0.12);
  }
  brush.circle(602 + dp.dx, 655 + dp.dy, 195, 0.18);

  // 3. Dark Violet-Black core overlap wash in the deep palmar concavity & under overhanging fingertips
  brush.wash(PAL.overlapDark, 24);
  brush.circle(598, 648, 145, 0.20);
  for (let f of fingers) {
    let s1 = f.segments[1];
    brush.circle((s1.x1 + s1.x2) * 0.5, (s1.y1 + s1.y2) * 0.5, s1.r2 * 0.72, 0.15);
  }
  brush.noWash();
}

function renderPlateBatches(projected) {
  // --- PASS 1: CYAN PLATE ---
  drawStrokeBatch(projected.cyanStrokes, (st) => {
    if (st.role === "crease" || st.role === "contour" || st.shade > 0.68) return PAL.cyanDark;
    if (st.shade > 0.38) return PAL.cyanMid;
    return PAL.cyanLight;
  });

  // --- PASS 2: SCARLET PLATE ---
  drawStrokeBatch(projected.scarletStrokes, (st) => {
    if (st.role === "crease" || st.role === "contour" || st.shade > 0.68) return PAL.scarletDark;
    if (st.shade > 0.38) return PAL.scarletMid;
    return PAL.scarletLight;
  });

  // --- PASS 3: DARK VIOLET-BLACK OVERLAP PLATE ---
  drawStrokeBatch(projected.overlapStrokes, (st) => {
    if (st.role === "crease" || st.role === "contour" || st.density > 0.72) return PAL.overlapDeep;
    if (st.density > 0.52) return PAL.overlapDark;
    return PAL.overlapMid;
  });
}

function drawStrokeBatch(strokes, colorFn) {
  // Group strokes by (brushName + color + quantized weight) for optimal p5.brush state switching
  let buckets = new Map();

  for (let st of strokes) {
    let col = colorFn(st);
    let wQuant = round(st.weight * 20) / 20;
    let key = st.brushName + "|" + col + "|" + wQuant;
    if (!buckets.has(key)) {
      buckets.set(key, { brushName: st.brushName, col, weight: wQuant, list: [] });
    }
    buckets.get(key).list.push(st);
  }

  for (let b of buckets.values()) {
    brush.set(b.brushName, b.col, b.weight);
    for (let st of b.list) {
      drawSafePolyline(st.pts, st.curvature);
    }
  }
}

function drawSafePolyline(pts, curvature) {
  if (!pts || pts.length < 2) return;
  if (pts.length === 2) {
    let p0 = pts[0], p1 = pts[1];
    if (dist(p0[0], p0[1], p1[0], p1[1]) >= 1.2) {
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
    return;
  }
  brush.spline(pts, curvature);
}

