function renderOpticalStippleAndAccents() {
  // High-resolution skin pore stippling across the fingertips, knuckles, and palmar creases
  let cyanDots = [];
  let scarletDots = [];
  let overlapDots = [];

  for (let i = 0; i < 1100; i++) {
    let x = random(140, 1060);
    let y = random(90, 1140);
    let surf = querySurface(x, y);
    if (surf.z <= 0.01) continue;

    let shade = 1.0 - surf.light;
    if (random() > shade * 1.15 + surf.crease * 0.6) continue;

    let d = getStereoDelta(x, y, surf.z);
    let cx = x - d.dx, cy = y - d.dy;
    let sx = x + d.dx, sy = y + d.dy;

    let gxc = constrain(round(cx / GSCALE), 0, GW - 1);
    let gyc = constrain(round(cy / GSCALE), 0, GH - 1);
    let cOverlap = scarletInkMap[gyc * GW + gxc];

    let gxs = constrain(round(sx / GSCALE), 0, GW - 1);
    let gys = constrain(round(sy / GSCALE), 0, GH - 1);
    let sOverlap = cyanInkMap[gys * GW + gxs];

    let a = random(360);
    let len = random(2.2, 5.2);

    if (cOverlap > 0.45) {
      overlapDots.push([cx, cy, a, len]);
    } else {
      cyanDots.push([cx, cy, a, len]);
    }

    if (sOverlap > 0.45) {
      overlapDots.push([sx, sy, a, len]);
    } else {
      scarletDots.push([sx, sy, a, len]);
    }
  }

  brush.set("needle", PAL.cyanMid, 0.36);
  for (let d of cyanDots) {
    brush.line(d[0], d[1], d[0] + cos(d[2]) * d[3], d[1] + sin(d[2]) * d[3]);
  }

  brush.set("needle", PAL.scarletMid, 0.36);
  for (let d of scarletDots) {
    brush.line(d[0], d[1], d[0] + cos(d[2]) * d[3], d[1] + sin(d[2]) * d[3]);
  }

  brush.set("needle", PAL.overlapDeep, 0.40);
  for (let d of overlapDots) {
    brush.line(d[0], d[1], d[0] + cos(d[2]) * d[3], d[1] + sin(d[2]) * d[3]);
  }
}

// ============================================================================
// UTILITY: CATMULL-ROM INTERPOLATION FOR CREASE SPLINES
// ============================================================================

function sampleSplinePoints(ctrlPts, numSamples) {
  let out = [];
  let n = ctrlPts.length;
  if (n < 2) return ctrlPts;

  for (let i = 0; i < numSamples; i++) {
    let tGlobal = (i / (numSamples - 1)) * (n - 1);
    let seg = min(floor(tGlobal), n - 2);
    let t = tGlobal - seg;

    let p0 = ctrlPts[max(0, seg - 1)];
    let p1 = ctrlPts[seg];
    let p2 = ctrlPts[min(n - 1, seg + 1)];
    let p3 = ctrlPts[min(n - 1, seg + 2)];

    let t2 = t * t;
    let t3 = t2 * t;

    let x = 0.5 * (
      (2 * p1[0]) +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
    );
    let y = 0.5 * (
      (2 * p1[1]) +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
    );
    out.push([x, y]);
  }
  return out;
}

// Hyperrealist Singing Wren & Magma Bioacoustic Spectrogram
// p5.js 2.x + p5.brush

const MAGMA_STOPS = [
  { t: 0.00, c: [12, 9, 26] },     // Deepest void indigo
  { t: 0.14, c: [26, 17, 48] },    // Midnight indigo
  { t: 0.28, c: [53, 19, 74] },    // Deep violet-aubergine
  { t: 0.42, c: [90, 23, 88] },    // Royal plum
  { t: 0.56, c: [138, 32, 82] },   // Dark magenta-crimson
  { t: 0.70, c: [188, 49, 64] },   // Rich crimson
  { t: 0.82, c: [230, 85, 45] },   // Molten vermilion-orange
  { t: 0.91, c: [250, 150, 42] },  // Molten amber-gold
  { t: 0.96, c: [253, 216, 78] },  // Incandescent yellow
  { t: 1.00, c: [255, 251, 215] }  // Luminous white-gold core
];

function magmaHex(val, earthyShift = 0) {
  let v = constrain(val, 0, 1);
  for (let i = 0; i < MAGMA_STOPS.length - 1; i++) {
    let s0 = MAGMA_STOPS[i];
    let s1 = MAGMA_STOPS[i + 1];
    if (v >= s0.t && v <= s1.t) {
      let f = (v - s0.t) / (s1.t - s0.t);
      let r = lerp(s0.c[0], s1.c[0], f);
      let g = lerp(s0.c[1], s1.c[1], f);
      let b = lerp(s0.c[2], s1.c[2], f);
      if (earthyShift > 0) {
        r = lerp(r, 110, earthyShift * 0.25);
        g = lerp(g, 85, earthyShift * 0.25);
        b = lerp(b, 65, earthyShift * 0.25);
      }
      return (
        "#" +
        int(constrain(r, 0, 255)).toString(16).padStart(2, "0") +
        int(constrain(g, 0, 255)).toString(16).padStart(2, "0") +
        int(constrain(b, 0, 255)).toString(16).padStart(2, "0")
      );
    }
  }
  return "#fffbd7";
}

// Bioacoustic spectrogram model of Troglodytes troglodytes song
// x in [280, 1130], y in [140, 910]
function getSpectrogramEnergy(x, y) {
  if (x < 260 || x > 1140 || y < 130 || y > 925) return 0;

  // Envelope expanding horizontally from the wren's open beak (395, 448)
  let beakDistX = x - 375;
  let spreadY = beakDistX < 0 ? 95 : min(390, 85 + beakDistX * 1.45);
  let centerEnvY = lerp(448, 520, constrain(beakDistX / 260, 0, 1));
  let vertEnv = exp(-pow((y - centerEnvY) / spreadY, 2.4));
  let leftFade = constrain(map(x, 270, 390, 0, 1), 0, 1);
  let rightFade = constrain(map(x, 1085, 1135, 1, 0), 0, 1);
  let baseEnv = leftFade * rightFade * vertEnv;

  // Ambient horizontal frequency bands (formant floor)
  let n1 = noise(x * 0.004, y * 0.018);
  let bandFloor =
    0.16 * exp(-pow((y - 650) / 160, 2)) +
    0.14 * exp(-pow((y - 460) / 140, 2)) +
    0.10 * exp(-pow((y - 290) / 110, 2));
  let energy = (0.08 + n1 * 0.14 + bandFloor) * baseEnv;

  // 1. Introductory Staccato Broadband Clicks & Beak Burst (x: 392..472)
  if (x >= 385 && x <= 485) {
    let clicks = [408, 434, 460];
    for (let i = 0; i < clicks.length; i++) {
      let cx = clicks[i];
      let dx = abs(x - cx);
      if (dx < 18) {
        let spikeY = exp(-pow((y - (445 - i * 18)) / (165 + i * 25), 2));
        let eClick = exp(-pow(dx / 4.2, 1.8)) * spikeY * 0.92;
        energy = max(energy, eClick);
      }
    }
    // Initial rising whistle out of beak
    let u = constrain((x - 392) / 76, 0, 1);
    let ySweep = 452 - 115 * pow(u, 0.85);
    let eSweep = exp(-pow((y - ySweep) / 18, 2)) * sin(u * 180) * 0.95;
    energy = max(energy, eSweep);
  }

  // 2. Syllable Group A: Three Rising Harmonic Sweeps (x: 475..628)
  if (x >= 470 && x <= 635) {
    let starts = [480, 528, 576];
    for (let s = 0; s < 3; s++) {
      let u = (x - starts[s]) / 44;
      if (u >= -0.1 && u <= 1.1) {
        let uc = constrain(u, 0, 1);
        let envS = sin(uc * 180);
        // Fundamental F0
        let yf0 = 695 - s * 14 - 210 * pow(uc, 0.72);
        // 2nd Harmonic 2F0
        let yf1 = 495 - s * 12 - 175 * pow(uc, 0.72);
        // 3rd Harmonic 3F0
        let yf2 = 335 - s * 10 - 135 * pow(uc, 0.72);
        // Sub-band
        let yfSub = 790 - 95 * uc;

        let e0 = exp(-pow((y - yf0) / 19, 2)) * envS * 0.98;
        let e1 = exp(-pow((y - yf1) / 15, 2)) * envS * 0.88;
        let e2 = exp(-pow((y - yf2) / 12, 2)) * envS * 0.72;
        let eSub = exp(-pow((y - yfSub) / 22, 2)) * envS * 0.52;
        energy = max(energy, e0, e1, e2, eSub);
      }
    }
  }

  // 3. Syllable Group B: Vertical Transient Spikes & Down-Slurred Polyphony (x: 628..748)
  if (x >= 622 && x <= 755) {
    let spikes = [
      { x: 636, yTop: 195, yBot: 825, coreY: 430 },
      { x: 668, yTop: 175, yBot: 845, coreY: 390 },
      { x: 702, yTop: 205, yBot: 810, coreY: 470 },
      { x: 734, yTop: 185, yBot: 830, coreY: 410 }
    ];
    for (let sp of spikes) {
      let dx = abs(x - sp.x);
      if (dx < 22 && y >= sp.yTop && y <= sp.yBot) {
        let vSpan = sin(map(y, sp.yTop, sp.yBot, 0, 180));
        let coreBoost = 0.65 + 0.35 * exp(-pow((y - sp.coreY) / 120, 2));
        let eSpike = exp(-pow(dx / 4.8, 1.65)) * pow(vSpan, 0.55) * coreBoost * 0.99;
        energy = max(energy, eSpike);
      }
    }
    // Down-slurred formant bridges between spikes
    let u = constrain((x - 636) / 100, 0, 1);
    let yBridge1 = 365 + 95 * u + 22 * sin(u * 540);
    let yBridge2 = 545 + 110 * u + 18 * cos(u * 540);
    let eB1 = exp(-pow((y - yBridge1) / 20, 2)) * 0.84;
    let eB2 = exp(-pow((y - yBridge2) / 24, 2)) * 0.78;
    energy = max(energy, eB1, eB2);
  }

  // 4. Syllable Group C: Rapid Syllabic Trill — 10 Chevron FM Sweeps (x: 748..958)
  if (x >= 742 && x <= 964) {
    let period = 20.5;
    let relX = x - 750;
    let idx = floor(relX / period);
    let phase = (relX - idx * period) / period; // 0..1
    if (idx >= 0 && idx < 10) {
      // Sawtooth/chevron rapid up-down sweep
      let tri = phase < 0.68 ? phase / 0.68 : (1 - phase) / 0.32;
      let envT = sin(constrain(phase, 0, 1) * 180);
      let yTrill0 = 655 - 245 * tri;
      let yTrill1 = 415 - 175 * tri;
      let yCarrier = 745 - 35 * sin(relX * 2.5);

      let eT0 = exp(-pow((y - yTrill0) / 18, 2)) * (0.75 + 0.25 * envT);
      let eT1 = exp(-pow((y - yTrill1) / 14, 2)) * (0.68 + 0.24 * envT);
      let eCar = exp(-pow((y - yCarrier) / 22, 2)) * 0.62;
      energy = max(energy, eT0, eT1, eCar);
    }
  }

  // 5. Syllable Group D: Sustained Vibrato Stack & Soaring Final Flare (x: 958..1118)
  if (x >= 952 && x <= 1125) {
    if (x <= 1052) {
      let u = (x - 958) / 90;
      let vib = sin((x - 958) * 14) * 11;
      let harms = [685, 525, 370, 240];
      let weights = [0.85, 0.96, 0.88, 0.68];
      for (let h = 0; h < harms.length; h++) {
        let yh = harms[h] - u * 28 + vib * (1 + h * 0.2);
        let eh = exp(-pow((y - yh) / (19 - h * 2), 2)) * weights[h];
        energy = max(energy, eh);
      }
    }
    // Final soaring sweep & dual chirp spikes (x: 1038..1108)
    if (x >= 1035) {
      let u = constrain((x - 1040) / 58, 0, 1);
      let yRise0 = 510 - 305 * pow(u, 1.25);
      let yRise1 = 670 - 280 * pow(u, 1.15);
      let fadeOut = constrain(map(x, 1085, 1118, 1, 0), 0, 1);
      let eR0 = exp(-pow((y - yRise0) / 17, 2)) * fadeOut * 0.98;
      let eR1 = exp(-pow((y - yRise1) / 19, 2)) * fadeOut * 0.88;
      energy = max(energy, eR0, eR1);

      let endSpikes = [1064, 1088];
      for (let sx of endSpikes) {
        let dx = abs(x - sx);
        if (dx < 16 && y > 175 && y < 790) {
          let vEnv = sin(map(y, 175, 790, 0, 180));
          let eSp = exp(-pow(dx / 4.2, 1.7)) * vEnv * 0.94;
          energy = max(energy, eSp);
        }
      }
    }
  }

  return constrain(energy, 0, 1);
}

// Helper for watercolor polygon fills
function fillPoly(pts, col, opacity, bleed = 0.15, tex = 0.45, border = 0.35, curv = 0.15) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Helper for opaque wash polygons (crucial for layering over dark grounds)
function washPoly(pts, col, opacity) {
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(73194);
  noiseSeed(73194);

  // Constraint #2: Call brush.scaleBrushes(3) in setup
  brush.scaleBrushes(3);

  // Fine custom brushes for feather barbules and high-precision spectrogram filaments
  brush.add("fineBarb", {
    type: "default",
    weight: 0.22,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 8,
    opacity: 195,
    spacing: 0.12,
    pressure: [0.3, 1.0, 0.15],
    noise: 0.25
  });

  brush.add("dataNeedle", {
    type: "default",
    weight: 0.28,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 5,
    opacity: 220,
    spacing: 0.1,
    pressure: [0.2, 1.1, 0.2],
    noise: 0.15
  });

  brush.add("magmaGlow", {
    type: "spray",
    weight: 2.2,
    scatter: 1.8,
    opacity: 55,
    spacing: 0.6,
    pressure: [0.5, 1.0, 0.5],
    noise: 0.4
  });

  // Custom vector field for the horizontal spectrogram flow
  brush.addField("songFlow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let wx = nx * 1200;
        let wy = ny * 1200;
        // Radiate slightly from the beak (395, 448) then level out horizontally
        let dx = max(40, wx - 350);
        let dy = (wy - 470) * exp(-dx / 240);
        let baseAngle = atan2(dy * 0.25, dx);
        let wave = sin(nx * 720 + ny * 180) * 5.5 + (noise(nx * 4.5, ny * 6.0) - 0.5) * 11;
        field[col][row] = baseAngle + wave;
      }
    }
    return field;
  });
}

function draw() {
