  background("#f1eadf");

  // Warm muted earth paper washes (batched by color for performance)
  fillPoly(
    [[35, 45], [1165, 45], [1165, 1155], [35, 1155]],
    "#eadfce", 42, 0.22, 0.45, 0.2, 0.05
  );
  fillPoly(
    [[50, 320], [520, 280], [540, 1020], [50, 1050]],
    "#dfd0ba", 55, 0.35, 0.55, 0.3, 0.2
  );
  fillPoly(
    [[60, 680], [560, 660], [520, 1080], [60, 1090]],
    "#cbb89d", 48, 0.38, 0.6, 0.35, 0.2
  );

  // Subtle parchment foxing and grain around margins
  brush.noField();
  brush.set("spray", "#b8a489", 0.7);
  for (let i = 0; i < 65; i++) {
    let px = random(60, 1140);
    let py = random(60, 1140);
    if (px < 360 || py < 160 || py > 920) {
      brush.line(px, py, px + random(-25, 25), py + random(-12, 12));
    }
  }

  // =========================================================================
  // 2. SPECTROGRAM BASE CHAMBER — DEEP INDIGO TO MAGMA WATERCOLOUR WASHES
  // =========================================================================
  drawSpectrogramWashes();

  // =========================================================================
  // 3. SCIENTIFIC AXES, CALIBRATION GRID & OSCILLOGRAM WAVEFORM
  // =========================================================================
  drawScientificGridAndWaveform();

  // =========================================================================
  // 4. FLOW-FIELD SPECTROGRAM HATCHING, RISING SWEEPS & CHIRP SPIKES
  // =========================================================================
  drawSpectrogramFlowField();
  drawSpectrogramPeakFeatures();

  // =========================================================================
  // 5. GNARLED HAWTHORN PERCH WITH BARK FISSURES, LICHEN & MOSS
  // =========================================================================
  drawPerchBranch();

  // =========================================================================
  // 6. THE SINGING WREN — HYPERREAL WATERCOLOUR & PENCIL/INK ANATOMY
  // =========================================================================
  drawWrenUnderpainting();
  drawWrenTail();
  drawWrenBodyAndMantle();
  drawWrenWing();
  drawWrenThroatAndBreast();
  drawWrenHeadAndCrown();
  drawWrenOpenBeakAndTongue();
  drawWrenEye();
  drawWrenLegsAndFeet();

  // =========================================================================
  // 7. FOREGROUND ACOUSTIC SHOCKWAVES & LUMINOUS FILAMENTS AT THE BEAK
  // =========================================================================
  drawBeakAcousticCoupling();

  noLoop();
}

