function drawScientificGridAndWaveform() {
  brush.noField();

  // Outer scientific plate border in muted sepia ink
  brush.set("rotring", "#8c7b67", 0.35);
  brush.line(62, 68, 1138, 68);
  brush.line(62, 1132, 1138, 1132);
  brush.line(62, 68, 62, 1132);
  brush.line(1138, 68, 1138, 1132);

  // Inner hair-line corner registration marks
  brush.set("rotring", "#6e5d4b", 0.45);
  let corners = [[76, 82, 1, 1], [1124, 82, -1, 1], [76, 1118, 1, -1], [1124, 1118, -1, -1]];
  for (let c of corners) {
    brush.line(c[0], c[1], c[0] + c[2] * 24, c[1]);
    brush.line(c[0], c[1], c[0], c[1] + c[3] * 24);
  }

  // Spectrogram framing axes (x: 375..1125, y: 150..905)
  brush.set("rotring", "#7a6855", 0.4);
  brush.line(370, 150, 1125, 150);
  brush.line(370, 905, 1125, 905);
  brush.line(1125, 150, 1125, 905);

  // Horizontal Frequency Grid Lines (1 kHz to 11 kHz)
  // Subtle dotted/dashed lines across the spectrogram
  for (let khz = 1; khz <= 11; khz++) {
    let y = map(khz, 0.5, 11.5, 905, 150);
    // Right axis calibration ticks
    brush.set("rotring", "#5c4b3b", 0.5);
    brush.line(1125, y, 1134, y);
    if (khz % 2 === 0) {
      brush.line(1125, y, 1138, y);
      // Subtle internal grid dashes across the dark field
      for (let gx = 395; gx < 1115; gx += 28) {
        let e = getSpectrogramEnergy(gx, y);
        let gridCol = e > 0.5 ? "#fff3b8" : "#5e4b70";
        brush.set("rotring", gridCol, 0.22);
        brush.line(gx, y, gx + 8, y);
      }
    }
  }

  // Vertical Time Axis Ticks (top y = 150 and bottom y = 905)
  for (let tx = 400; tx <= 1120; tx += 20) {
    let isMajor = (tx - 400) % 100 === 0;
    let tickLen = isMajor ? 11 : 5;
    brush.set("rotring", "#6b5a48", isMajor ? 0.5 : 0.32);
    brush.line(tx, 150, tx, 150 - tickLen);
    brush.line(tx, 905, tx, 905 + tickLen);

    if (isMajor) {
      for (let gy = 165; gy < 895; gy += 32) {
        brush.set("rotring", "#4b3b5c", 0.2);
        brush.line(tx, gy, tx, gy + 7);
      }
    }
  }

  // Lower Bioacoustic Oscillogram / Amplitude Envelope Strip (yCenter = 995)
  let oscY = 995;
  brush.set("rotring", "#8c7a66", 0.32);
  brush.line(370, oscY, 1125, oscY);
  brush.line(370, oscY - 52, 1125, oscY - 52);
  brush.line(370, oscY + 52, 1125, oscY + 52);

  // Render high-resolution amplitude bars synchronized with spectrogram energy above
  for (let x = 385; x <= 1120; x += 2.2) {
    // Integrate column energy
    let colMax = 0;
    let colSum = 0;
    for (let sy = 200; sy <= 820; sy += 35) {
      let e = getSpectrogramEnergy(x, sy);
      colMax = max(colMax, e);
      colSum += e;
    }
    let amp = constrain((colMax * 0.65 + (colSum / 18) * 0.6) * random(0.82, 1.15), 0.02, 1.0);
    let h = amp * 48;
    let barCol = amp > 0.72 ? magmaHex(0.68) : amp > 0.45 ? magmaHex(0.45) : "#4a3b4e";
    brush.set("rotring", barCol, amp > 0.65 ? 0.42 : 0.28);
    brush.line(x, oscY - h, x, oscY + h * 0.88);
  }

  // Scientific annotation callout lines above spectrogram (syllable bracket markers)
  let brackets = [
    [395, 468],
    [480, 624],
    [632, 742],
    [750, 954],
    [960, 1108]
  ];
  brush.set("rotring", "#6e5d4c", 0.38);
  for (let b of brackets) {
    brush.line(b[0], 124, b[1], 124);
    brush.line(b[0], 124, b[0], 133);
    brush.line(b[1], 124, b[1], 133);
  }
}

function drawSpectrogramFlowField() {
  brush.field("songFlow");

  // Multi-pass flow-field hatching streaking rightward in bands of magma colour
  // Pass 1: Deep Indigo, Violet & Aubergine background flow (low-to-mid energy)
  for (let i = 0; i < 1550; i++) {
    let x = random(275, 1110);
    let y = random(150, 900);
    let e = getSpectrogramEnergy(x, y);
    if (e < 0.03) continue;

    // Bias pass 1 toward deep indigo to crimson
    let colVal = constrain(e * 0.85 + random(-0.06, 0.06), 0.02, 0.78);
    let col = magmaHex(colVal);
    let len = map(e, 0, 1, 22, 68) * random(0.7, 1.3);
    let w = map(e, 0, 1, 0.45, 0.95);

    let bType = e < 0.28 ? "charcoal" : "cpencil";
    brush.set(bType, col, w);
    brush.flowLine(x, y, len, random(-4, 4));
  }

  // Pass 2: Dense Horizontal Hatching Bands (Crimson -> Vermilion -> Molten Gold)
  for (let i = 0; i < 1650; i++) {
    let x = random(355, 1115);
    let y = random(165, 865);
    let e = getSpectrogramEnergy(x, y);
    if (e < 0.24) continue;

    let colVal = constrain(pow(e, 0.85) + random(-0.04, 0.05), 0.22, 0.98);
    let col = magmaHex(colVal);
    let len = map(e, 0.24, 1, 18, 54) * random(0.75, 1.25);
    let w = map(e, 0.24, 1, 0.35, 0.78);

    let bType = e > 0.75 ? "dataNeedle" : "cpencil";
    brush.set(bType, col, w);
    brush.flowLine(x, y, len, random(-2, 2));
  }

  brush.noField();
}

function drawSpectrogramPeakFeatures() {
  brush.noField();

  // 1. Introductory Clicks & Rising Beak Sweep (x: 392..472)
  let introClicks = [408, 434, 460];
  for (let i = 0; i < introClicks.length; i++) {
    drawChirpSpike(introClicks[i], 280 - i * 15, 650 + i * 15, 445 - i * 18, 0.85);
  }
  drawRisingSweepRibbon(392, 452, 468, 337, 0.85, 18, true);

  // 2. Syllable Group A: Three Rising Harmonic Sweeps (x: 480..624)
  let starts = [480, 528, 576];
  for (let s = 0; s < 3; s++) {
    let x0 = starts[s];
    let x1 = x0 + 44;
    // Fundamental F0
    drawRisingSweepRibbon(x0, 695 - s * 14, x1, 485 - s * 14, 0.72, 20, true);
    // 2nd Harmonic 2F0
    drawRisingSweepRibbon(x0, 495 - s * 12, x1, 320 - s * 12, 0.72, 15, true);
    // 3rd Harmonic 3F0
    drawRisingSweepRibbon(x0, 335 - s * 10, x1, 200 - s * 10, 0.72, 11, false);
  }

  // 3. Syllable Group B: Dramatic Vertical Chirp Spikes & Down-Slurs (x: 636..734)
  let mainSpikes = [
    { x: 636, yTop: 185, yBot: 830, coreY: 430 },
    { x: 668, yTop: 168, yBot: 850, coreY: 390 },
    { x: 702, yTop: 195, yBot: 815, coreY: 470 },
    { x: 734, yTop: 178, yBot: 835, coreY: 410 }
  ];
  for (let sp of mainSpikes) {
    drawChirpSpike(sp.x, sp.yTop, sp.yBot, sp.coreY, 1.0);
  }

  // Down-slurred formant bridges across Syllable B
  for (let layer = 0; layer < 24; layer++) {
    let pts1 = [];
    let pts2 = [];
    let yOff = random(-10, 10);
    for (let x = 634; x <= 740; x += 6) {
      let u = (x - 636) / 100;
      let y1 = 365 + 95 * u + 22 * sin(u * 540) + yOff;
      let y2 = 545 + 110 * u + 18 * cos(u * 540) + yOff * 1.1;
      pts1.push([x, y1]);
      pts2.push([x, y2]);
    }
    let col = magmaHex(map(abs(yOff), 0, 10, 0.96, 0.62));
    brush.set("dataNeedle", col, map(abs(yOff), 0, 10, 0.75, 0.35));
    brush.spline(pts1, 0.4);
    brush.spline(pts2, 0.4);
  }

  // 4. Syllable Group C: Rapid Syllabic Trill — 10 Chevron FM Sweeps (x: 750..955)
  let period = 20.5;
  for (let idx = 0; idx < 10; idx++) {
    let xStart = 750 + idx * period;
    let xPeak = xStart + period * 0.68;
    let xEnd = xStart + period;

    // Wash molten yellow-orange core along each trill tooth
    washPoly(
      [
        [xStart - 2, 655],
        [xPeak, 405],
        [xEnd + 1, 645],
        [xPeak, 435]
      ],
      magmaHex(0.88),
      140
    );

    // Fine hatched & spline filaments for F0 and 2F0 chevrons
    for (let s = 0; s < 16; s++) {
      let dy = random(-11, 11);
      let cVal = map(abs(dy), 0, 11, 0.99, 0.58);
      brush.set("dataNeedle", magmaHex(cVal), map(abs(dy), 0, 11, 0.72, 0.32));
      brush.spline(
        [
          [xStart, 655 + dy],
          [(xStart + xPeak) * 0.5, 530 + dy * 0.8],
          [xPeak, 410 + dy * 0.6],
          [xEnd, 648 + dy]
        ],
        0.35
      );
      // Upper harmonic chevron
      brush.set("dataNeedle", magmaHex(cVal * 0.92), 0.38);
      brush.spline(
        [
          [xStart, 415 + dy * 0.7],
          [xPeak, 240 + dy * 0.5],
          [xEnd, 410 + dy * 0.7]
        ],
        0.35
      );
    }

    // Bright vertical inflection flare at the top & bottom of each trill tooth
    brush.set("dataNeedle", "#fffbd6", 0.65);
    brush.line(xPeak, 392, xPeak, 432);
    brush.line(xPeak, 228, xPeak, 256);
  }

  // 5. Syllable Group D: Vibrato Harmonic Stack & Final Rising Flare (x: 958..1110)
  let harms = [685, 525, 370, 240];
  for (let h = 0; h < harms.length; h++) {
    for (let k = 0; k < 18; k++) {
      let dy = random(-12, 12);
      let pts = [];
      for (let x = 956; x <= 1052; x += 5) {
        let u = (x - 958) / 90;
        let vib = sin((x - 958) * 14) * 11 * (1 + h * 0.2);
        pts.push([x, harms[h] - u * 28 + vib + dy]);
      }
      let cVal = map(abs(dy), 0, 12, 0.97 - h * 0.05, 0.52);
      brush.set("dataNeedle", magmaHex(cVal), map(abs(dy), 0, 12, 0.75, 0.32));
      brush.spline(pts, 0.45);
    }
  }

  // Final soaring sweeps & terminal spikes
  drawRisingSweepRibbon(1040, 510, 1098, 205, 1.25, 17, true);
  drawRisingSweepRibbon(1040, 670, 1098, 390, 1.15, 18, true);
  drawChirpSpike(1064, 175, 785, 360, 0.92);
  drawChirpSpike(1088, 185, 760, 310, 0.88);

  // Luminous magma spray embers and high-frequency data stipple
  for (let i = 0; i < 160; i++) {
    let sx = random(385, 1110);
    let sy = random(175, 845);
    let e = getSpectrogramEnergy(sx, sy);
    if (e > 0.62) {
      brush.set("magmaGlow", magmaHex(constrain(e + 0.1, 0, 1)), random(0.4, 0.9));
      brush.line(sx, sy, sx + random(8, 24), sy + random(-5, 5));
    }
  }
}

function drawRisingSweepRibbon(x0, y0, x1, y1, powerExp, halfWidth, brightCore) {
  // Opaque wash under-core for molten luminance against dark indigo
  let corePts = [];
  for (let step = 0; step <= 8; step++) {
    let u = step / 8;
    let x = lerp(x0, x1, u);
    let y = lerp(y0, y1, pow(u, powerExp));
    corePts.push([x, y - halfWidth * 0.45]);
  }
  for (let step = 8; step >= 0; step--) {
    let u = step / 8;
    let x = lerp(x0, x1, u);
    let y = lerp(y0, y1, pow(u, powerExp));
    corePts.push([x, y + halfWidth * 0.45]);
  }
  washPoly(corePts, magmaHex(brightCore ? 0.86 : 0.68), brightCore ? 160 : 110);

  // Layered spline filaments from outer crimson halo to inner incandescent yellow core
  let layers = 26;
  for (let i = 0; i < layers; i++) {
    let norm = (i / (layers - 1)) * 2 - 1; // -1..1
    let offset = norm * halfWidth;
    let distFromCenter = abs(norm);
    let cVal = brightCore
      ? map(distFromCenter, 0, 1, 0.99, 0.48)
      : map(distFromCenter, 0, 1, 0.85, 0.38);

    let pts = [];
    for (let step = 0; step <= 10; step++) {
      let u = step / 10;
      let x = lerp(x0, x1, u);
      let taper = sin(u * 180);
      let y = lerp(y0, y1, pow(u, powerExp)) + offset * (0.35 + 0.65 * taper);
      pts.push([x, y]);
    }
    brush.set(
      distFromCenter < 0.35 ? "dataNeedle" : "cpencil",
      magmaHex(cVal),
      map(distFromCenter, 0, 1, 0.82, 0.32)
    );
    brush.spline(pts, 0.4);
  }
}

function drawChirpSpike(cx, yTop, yBot, yCore, intensity) {
  // Vertical crimson-to-molten-yellow flare wash
  let w = 11 * intensity;
  washPoly(
    [
      [cx - w, yCore],
      [cx, yTop],
      [cx + w, yCore],
      [cx, yBot]
    ],
    magmaHex(0.76 * intensity),
    145
  );
  washPoly(
    [
      [cx - w * 0.45, yCore],
      [cx, lerp(yCore, yTop, 0.72)],
      [cx + w * 0.45, yCore],
      [cx, lerp(yCore, yBot, 0.72)]
    ],
    magmaHex(0.95 * intensity),
    185
  );

  // Vertical and tightly cross-hatched transient strokes
  for (let i = 0; i < 38; i++) {
    let dx = randomGaussian(0, 4.2 * intensity);
    let distNorm = constrain(abs(dx) / (12 * intensity), 0, 1);
    let spanTop = lerp(yTop, yCore - 40, pow(distNorm, 0.7));
    let spanBot = lerp(yBot, yCore + 40, pow(distNorm, 0.7));
    let cVal = map(distNorm, 0, 1, 0.99, 0.38) * intensity;

    brush.set(
      distNorm < 0.3 ? "dataNeedle" : "cpencil",
      magmaHex(cVal),
      map(distNorm, 0, 1, 0.75, 0.28)
    );
    brush.line(cx + dx, spanTop + random(-12, 12), cx + dx, spanBot + random(-12, 12));
  }

  // Horizontal harmonic side-lobes along the spike
  for (let y = yTop + 25; y < yBot - 25; y += 9) {
    let vFactor = exp(-pow((y - yCore) / 145, 2));
    let hw = (4 + 18 * vFactor) * intensity * random(0.6, 1.3);
    let cVal = constrain(0.45 + 0.54 * vFactor, 0.35, 0.99);
    brush.set("dataNeedle", magmaHex(cVal), 0.36 + 0.35 * vFactor);
    brush.line(cx - hw, y, cx + hw, y);
  }
}

