function drawPerchBranch() {
  brush.noField();

  // Main diagonal branch geometry from bottom-left (40, 935) up-right to (485, 715)
  let branchMain = [
    [35, 905], [120, 855], [215, 802], [295, 768], [385, 736], [468, 708],
    [485, 716], [440, 742], [365, 778], [285, 818], [190, 875], [95, 945], [35, 965]
  ];
  washPoly(branchMain, "#59483b", 235);
  fillPoly(branchMain, "#4a3b2f", 160, 0.18, 0.65, 0.45, 0.12);

  // Upper illuminated bark ridge (warm ochre-taupe & grey-brown)
  let branchTop = [
    [35, 905], [120, 855], [215, 802], [295, 768], [385, 736], [468, 708],
    [445, 724], [360, 754], [275, 790], [185, 838], [90, 895], [35, 925]
  ];
  washPoly(branchTop, "#8c7762", 180);

  // Lower deep shadow underside of branch
  let branchShadow = [
    [45, 940], [165, 862], [275, 804], [385, 758], [465, 720],
    [440, 742], [365, 778], [285, 818], [190, 875], [95, 945], [35, 965]
  ];
