  // Secondary side twig fork at (355, 765) -> (455, 810) and broken stub at (165, 830)
  let twigRight = [
    [340, 772], [395, 785], [448, 804], [468, 815],
    [452, 822], [392, 800], [330, 784]
  ];
  washPoly(twigRight, "#4f3e32", 220);

  let stubLeft = [
    [155, 838], [132, 795], [142, 786], [174, 826]
  ];
  washPoly(stubLeft, "#5e4c3e", 220);

  // Longitudinal bark fissures and rough wood grain lines
  for (let i = 0; i < 190; i++) {
    let t = random(0.02, 0.96);
    let bx = lerp(45, 465, t);
    let by = lerp(930, 718, t) + random(-8, 8) * sin(t * 180);
    let offset = random(-22, 22) * (1 - t * 0.55);
    let isShadow = offset > 2;
    let col = isShadow
      ? random(["#241a14", "#36281f", "#47362b"])
      : random(["#6e5b4b", "#8a7562", "#a6927d", "#4f3f32"]);

    brush.set(random(["2B", "HB", "fineBarb"]), col, random(0.35, 0.85));
    let segLen = random(18, 52);
    let ang = -26.5 + random(-6, 6);
    brush.line(
      bx,
      by + offset,
      bx + cos(ang) * segLen,
      by + offset + sin(ang) * segLen
    );
