  // Crustose lichen patches (muted sage, pale olive, ochre-cream)
  let lichenSpots = [
    { x: 115, y: 882, r: 18 },
    { x: 195, y: 832, r: 22 },
    { x: 242, y: 806, r: 15 },
    { x: 345, y: 762, r: 16 },
    { x: 398, y: 740, r: 12 },
    { x: 405, y: 796, r: 11 }
  ];
  for (let ls of lichenSpots) {
    let pts = [];
    for (let a = 0; a < 360; a += 36) {
      let rad = ls.r * random(0.55, 1.15);
      pts.push([ls.x + cos(a) * rad, ls.y + sin(a) * rad * 0.58]);
    }
    washPoly(pts, random(["#9ea685", "#b4baa0", "#c4bf9c"]), 185);
    // Fine stippled thallus lobes and dark apothecia cups
    for (let k = 0; k < 18; k++) {
