function drawWrenTail() {
  // Cocked tail composed of 6 overlapping rectrices with transverse dark umber barring
  let tailFeathers = [
    { bx: 140, by: 632, tx: 82, ty: 484, w: 16 },
    { bx: 148, by: 626, tx: 92, ty: 468, w: 17 },
    { bx: 155, by: 620, tx: 104, ty: 456, w: 18 },
    { bx: 162, by: 616, tx: 116, ty: 452, w: 17 },
    { bx: 168, by: 618, tx: 128, ty: 464, w: 15 }
  ];

  for (let f = 0; f < tailFeathers.length; f++) {
    let tf = tailFeathers[f];
    let ang = atan2(tf.ty - tf.by, tf.tx - tf.bx);
    let perp = ang + 90;
    let len = dist(tf.bx, tf.by, tf.tx, tf.ty);

    // Individual feather vane barbs along length
    for (let s = 0; s <= 1; s += 0.018) {
      let cx = lerp(tf.bx, tf.tx, s);
      let cy = lerp(tf.by, tf.ty, s);
      let curW = tf.w * sin(constrain(s * 1.15, 0.15, 1) * 140);

      // Transverse dark barring pattern (9 bars along the tail)
      let barWave = sin(s * 180 * 9.5 + f * 12);
      let isDarkBar = barWave > 0.15;
      let col = isDarkBar
        ? random(["#26170f", "#382216", "#1f120b"])
        : s > 0.92
        ? "#d9be9c" // Pale buff tip
        : random(["#874e2c", "#9e6039", "#734022", "#b07148"]);

      brush.set("fineBarb", col, isDarkBar ? 0.55 : 0.45);
      // Left and right barbs angling up from shaft
      let barbAngL = ang - 24;
      let barbAngR = ang + 24;
      brush.line(cx, cy, cx + cos(barbAngL) * curW * 0.65, cy + sin(barbAngL) * curW * 0.65);
      brush.line(cx, cy, cx + cos(barbAngR) * curW * 0.55, cy + sin(barbAngR) * curW * 0.55);
    }

    // Crisp central feather shaft (rachis)
    brush.set("fineBarb", "#3b2315", 0.5);
    brush.line(tf.bx, tf.by, tf.tx, tf.ty);
    brush.set("fineBarb", "#b8845a", 0.25);
    brush.line(tf.bx + 0.6, tf.by, tf.tx + 0.6, tf.ty);
  }

  // Undertail coverts & rump feathers overlapping base of tail (barred buff and sepia)
  for (let i = 0; i < 65; i++) {
    let rx = random(132, 185);
    let ry = random(600, 668);
    let ang = random(-135, -75);
    let col = i % 3 === 0 ? "#2b1a10" : i % 3 === 1 ? "#dfc6a4" : "#8c5735";
    brush.set("fineBarb", col, 0.48);
    brush.line(rx, ry, rx + cos(ang) * random(9, 18), ry + sin(ang) * random(9, 18));
  }
}

function drawWrenBodyAndMantle() {
  // 1. Mantle & Scapular contour feathers (rich warm chestnut-umber with subtle dark barring)
  for (let row = 0; row < 11; row++) {
    let tRow = row / 10;
    let yBase = lerp(488, 610, tRow);
    let xLeft = lerp(242, 152, tRow);
    let xRight = lerp(288, 225, tRow);

    for (let colIdx = 0; colIdx < 9; colIdx++) {
      let fx = lerp(xLeft, xRight, colIdx / 8) + random(-4, 4);
      let fy = yBase + random(-4, 4);
      let fAng = lerp(142, 158, tRow) + random(-8, 8);
      let fLen = random(16, 26);

      // Draw miniature fan of barbs for each contour feather
      for (let b = -5; b <= 5; b++) {
        let ba = fAng + b * 4.5;
        // Basal shadow, warm chestnut middle, dark subterminal bar, warm rufous tip
        brush.set("fineBarb", random(["#5c331b", "#754325", "#8c5330", "#472714"]), 0.48);
        brush.line(fx, fy, fx + cos(ba) * fLen, fy + sin(ba) * fLen);

        if (abs(b) <= 3) {
          let barDist = fLen * 0.68;
          brush.set("fineBarb", "#26150c", 0.52);
          brush.line(
            fx + cos(ba) * (barDist - 3),
            fy + sin(ba) * (barDist - 3),
            fx + cos(ba) * (barDist + 2),
            fy + sin(ba) * (barDist + 2)
          );
        }
      }
    }
  }

  // 2. Downy Flanks & Lower Belly (warm clay-buff with characteristic dark flank barring)
  for (let r = 0; r < 12; r++) {
    let tr = r / 11;
    let fyBase = lerp(625, 725, tr);
    let fxStart = lerp(165, 205, tr);
    let fxEnd = lerp(322, 295, tr);

    for (let c = 0; c < 14; c++) {
      let tc = c / 13;
      let fx = lerp(fxStart, fxEnd, tc) + random(-4, 4);
      let fy = fyBase + sin(tc * 180) * 10 + random(-3, 3);
      let ang = lerp(128, 62, tc) + random(-10, 10);
      let fLen = random(14, 24);

      let isBar = (r + c) % 3 === 0 && tc < 0.72;
      let baseCol = isBar
        ? random(["#382315", "#4d311e"])
        : tc > 0.65
        ? random(["#dcc29e", "#c9a87e", "#e8d3b5"])
        : random(["#b38659", "#9c6f44", "#c79d71"]);

      for (let b = -3; b <= 3; b++) {
        let ba = ang + b * 5;
        brush.set("fineBarb", baseCol, 0.45);
        brush.line(fx, fy, fx + cos(ba) * fLen, fy + sin(ba) * fLen);
      }
    }
  }
}

function drawWrenWing() {
  // Folded wing anatomy (x: 168..308, y: 542..702)
  let wingPts = [
    [285, 542], [306, 568], [295, 615], [255, 665],
    [172, 698], [168, 678], [198, 615], [242, 558]
  ];
  washPoly(wingPts, "#663a20", 230);
  fillPoly(wingPts, "#4f2c17", 150, 0.16, 0.5, 0.35, 0.15);

  // 1. Primaries & Secondaries (extending down-left to wingtip at 172, 696)
  // Barred with alternating dark sepia-umber and warm rufous-ochre
  let numPrimaries = 8;
  for (let p = 0; p < numPrimaries; p++) {
    let tp = p / (numPrimaries - 1);
    let x0 = lerp(248, 282, tp);
    let y0 = lerp(608, 618, tp);
    let x1 = lerp(170, 232, tp);
    let y1 = lerp(696, 672, tp);
    let ang = atan2(y1 - y0, x1 - x0);

    for (let s = 0; s <= 1; s += 0.025) {
      let cx = lerp(x0, x1, s);
      let cy = lerp(y0, y1, s);
      let isDark = sin(s * 180 * 7.5 + p * 22) > 0.05;
      let col = isDark
        ? random(["#21130b", "#331e12"])
        : s > 0.92
        ? "#d9be9b"
        : random(["#8f5530", "#ab6c42", "#c4865a"]);

      brush.set("fineBarb", col, 0.52);
      brush.line(cx, cy, cx + cos(ang - 28) * 10, cy + sin(ang - 28) * 10);
      brush.line(cx, cy, cx + cos(ang + 22) * 6, cy + sin(ang + 22) * 6);
    }
    // Primary shaft
    brush.set("fineBarb", "#2b190f", 0.55);
    brush.line(x0, y0, x1, y1);
    brush.set("fineBarb", "#cfa379", 0.25);
    brush.line(x0, y0 + 0.6, x1, y1 + 0.6);
  }

  // 2. Greater Coverts & Median Coverts (with characteristic buff-white pearl tips!)
  let covertRows = [
    { y0: 590, y1: 604, x0: 215, x1: 288, count: 7, len: 22 }, // Greater coverts
    { y0: 568, y1: 582, x0: 232, x1: 296, count: 7, len: 18 }, // Median coverts
    { y0: 548, y1: 562, x0: 248, x1: 302, count: 8, len: 14 }  // Lesser coverts
  ];

  for (let r = 0; r < covertRows.length; r++) {
    let cr = covertRows[r];
    for (let i = 0; i < cr.count; i++) {
      let ti = i / (cr.count - 1);
      let fx = lerp(cr.x0, cr.x1, ti);
      let fy = lerp(cr.y0, cr.y1, ti);
      let ang = 136 + ti * 12;

      // Dark umber & warm chestnut feather body
      for (let b = -4; b <= 4; b++) {
        let ba = ang + b * 4.5;
        let col = abs(b) < 2 ? "#361f12" : "#784526";
        brush.set("fineBarb", col, 0.5);
        brush.line(fx, fy, fx + cos(ba) * cr.len, fy + sin(ba) * cr.len);
      }

      // Pearl-buff triangular tip on greater & median coverts (forming the two wing bars)
      if (r < 2) {
        let tipX = fx + cos(ang) * (cr.len * 0.85);
        let tipY = fy + sin(ang) * (cr.len * 0.85);
        for (let tb = -2; tb <= 2; tb++) {
          let tba = ang + tb * 5;
          brush.set("fineBarb", "#f2e2c9", 0.55);
          brush.line(tipX, tipY, tipX + cos(tba) * 5.5, tipY + sin(tba) * 5.5);
        }
      }
    }
  }
}

function drawWrenThroatAndBreast() {
  // Puffed throat & breast feathers (x: 282..370, y: 470..665)
  // Feathers are erected and separated by the inflated vocal air sac, catching warm magma light
  for (let row = 0; row < 18; row++) {
    let tr = row / 17;
    let fyBase = lerp(474, 658, tr);
    let xInner = lerp(296, 275, sin(tr * 160));
    let xOuter = lerp(338, 368, sin(tr * 155)); // Dramatic convex throat puff!

    let colsInRow = 10;
    for (let c = 0; c < colsInRow; c++) {
      let tc = c / (colsInRow - 1);
      let fx = lerp(xInner, xOuter, tc) + random(-2.5, 2.5);
      let fy = fyBase + random(-2.5, 2.5);

      // Feathers near the outer profile splay outward (-15 deg to +45 deg)
      let ang = lerp(82, 18 - (1 - tr) * 28, pow(tc, 0.85)) + random(-6, 6);
      let fLen = lerp(13, 19, tc) * random(0.85, 1.15);

      // Dark grey-sepia feather root shadow (visible between puffed feathers)
      if (tc > 0.25 && random() < 0.65) {
        brush.set("fineBarb", "#594638", 0.45);
        brush.line(fx, fy, fx + cos(ang) * (fLen * 0.45), fy + sin(ang) * (fLen * 0.45));
      }

      // Main feather barbs: warm cream/buff transitioning to glowing golden-amber at outer edge
      for (let b = -3; b <= 3; b++) {
        let ba = ang + b * 4.2;
        let midCol =
          tc > 0.78
            ? random(["#f7d89c", "#fce8be", "#f2b86b"])
            : tc > 0.42
            ? random(["#efe0c6", "#e3cdb0", "#f7ecd8"])
            : random(["#cfb38e", "#bfa07a", "#dcc4a4"]);

        brush.set("fineBarb", midCol, 0.46);
        brush.line(
          fx + cos(ba) * (fLen * 0.25),
          fy + sin(ba) * (fLen * 0.25),
          fx + cos(ba) * fLen,
          fy + sin(ba) * fLen
        );

        // Luminous golden-white & coral-amber tip highlights on outermost puffed throat plumes
        if (tc > 0.72 && abs(b) <= 2) {
          let tipCol = random() < 0.65 ? "#fff7dc" : "#fa9e3e";
          brush.set("fineBarb", tipCol, 0.48);
          brush.line(
            fx + cos(ba) * (fLen * 0.72),
            fy + sin(ba) * (fLen * 0.72),
            fx + cos(ba) * (fLen * 1.15),
            fy + sin(ba) * (fLen * 1.15)
          );
        }
      }

      // Subtle speckling/barring on lower breast
      if (tr > 0.55 && tc < 0.7 && (row + c) % 4 === 0) {
        brush.set("fineBarb", "#6e4e35", 0.42);
        brush.line(
          fx + cos(ang) * (fLen * 0.6),
          fy + sin(ang) * (fLen * 0.6),
          fx + cos(ang + 45) * (fLen * 0.55),
          fy + sin(ang + 45) * (fLen * 0.55)
        );
      }
    }
  }
}

function drawWrenHeadAndCrown() {
