    let ang = lerp(192, 132, t) + random(-8, 8);
    let fLen = lerp(9, 16, t);

    let col = random(["#3d2213", "#54311c", "#6b4025", "#2b170c", "#825132"]);
    brush.set("fineBarb", col, 0.48);
    brush.line(cx, cy, cx + cos(ang) * fLen, cy + sin(ang) * fLen);
  }

  // 2. Supercilium (Iconic pale buff-cream eyebrow stripe arching above the eye)
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let sx = lerp(334, 254, t) + random(-2, 2);
    let sy = lerp(431, 462, pow(t, 1.25)) - sin(t * 180) * 11 + random(-3, 3);
