  // 3. Dark Eye-Stripe (post-ocular stripe) & Mottled Auriculars (Cheek patch)
  for (let i = 0; i < 140; i++) {
    let ax = random(262, 332);
    let ay = random(448, 492);
    if (dist(ax, ay, 304, 454) < 14) continue; // Keep clear of eye center

    let ang = map(ax, 332, 262, 165, 135) + random(-10, 10);
