  // 4. Malar stripe & Chin feathers right below lower mandible
  for (let i = 0; i < 55; i++) {
    let mx = random(302, 338);
    let my = random(464, 486);
    let ang = random(115, 155);
    let col = random(["#f2e2c6", "#d9be98", "#6e472b", "#faf0dc"]);
    brush.set("fineBarb", col, 0.44);
    brush.line(mx, my, mx + cos(ang) * random(6, 11), my + sin(ang) * random(6, 11));
