function drawWrenEye() {
  let ex = 304;
  let ey = 454;
  let r = 12.2;

  // 1. Dark orbital shadow socket
  let orbPts = [];
  for (let a = 0; a < 360; a += 20) {
    orbPts.push([ex + cos(a) * (r + 3.5), ey + sin(a) * (r + 3.0)]);
  }
  washPoly(orbPts, "#1f130c", 245);

  // 2. Deep chestnut outer iris ring
  let irisPts = [];
  for (let a = 0; a < 360; a += 18) {
    irisPts.push([ex + cos(a) * r, ey + sin(a) * r]);
  }
  washPoly(irisPts, "#422210", 252);

  // Radial iris striations in warm chestnut & raw umber
  for (let a = 0; a < 360; a += 8) {
    let col = (a > -45 && a < 90) ? "#6e3b1e" : "#291408";
    brush.set("fineBarb", col, 0.42);
    brush.line(
      ex + cos(a) * (r * 0.45),
      ey + sin(a) * (r * 0.45),
      ex + cos(a) * (r * 0.96),
      ey + sin(a) * (r * 0.96)
    );
  }

  // 3. Obsidian-black pupil
  let pupilPts = [];
  for (let a = 0; a < 360; a += 20) {
    pupilPts.push([ex + cos(a) * (r * 0.58), ey + sin(a) * (r * 0.58)]);
  }
  washPoly(pupilPts, "#0d0806", 255);

  // 4. Delicate pale-buff orbital ring of tiny eyelid feathers
  for (let a = 0; a < 360; a += 11) {
    let rad = r + 1.8;
    let fx = ex + cos(a) * rad;
    let fy = ey + sin(a) * (rad * 0.95);
    let col = sin(a) < 0 ? "#ebd8ba" : "#c7a882";
    brush.set("fineBarb", col, 0.52);
    brush.line(fx, fy, fx + cos(a) * 3.2, fy + sin(a) * 3.2);
  }

  // 5. Razor-sharp corneal specular catchlights!
  // Primary upper-right catchlight reflecting the luminous spectrogram
  washPoly(
    [[ex + 2.5, ey - 6.8], [ex + 7.2, ey - 5.2], [ex + 6.5, ey - 1.8], [ex + 2.0, ey - 3.2]],
    "#fffdf5",
    255
  );
  brush.set("dataNeedle", "#ffffff", 0.75);
  brush.line(ex + 3.2, ey - 5.5, ex + 6.2, ey - 3.5);

  // Secondary warm golden reflection crescent along lower-right rim
  brush.set("fineBarb", "#f7b952", 0.5);
  brush.arc(ex, ey, r * 0.82, 15, 75);

  // Soft sky reflection along upper-left cornea
  brush.set("fineBarb", "#c8d2d9", 0.42);
  brush.arc(ex, ey, r * 0.84, 195, 245);
}

