// Hyperrealistic Daguerreotype: Two Small Children's Hands Clasped in a Lap of Dark Velvet
// Rendered with p5.js 2.x and p5.brush in WEBGL mode

const CX = 600;
const CY = 600;
const OVAL_RX = 442;
const OVAL_RY = 512;

// Light direction for 3D mercury-silver relief modeling (normalized)
const LIGHT = { x: -0.32, y: -0.54, z: 0.78 };

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
