}

function draw() {
  translate(-width / 2, -height / 2);
  background("#08090d");
  brush.noField();

  // 1. Base Daguerreotype Plate & Velvet Lap Washes
  renderPlateBaseAndVelvetWashes();

  // 2. Deep Velvet Lap Drapery Folds & Grazing Silver Nap
  renderVelvetDrapery();

  // 3. Delicate Pleated Linen & Lace Cuffs at the Wrists
  renderWristCuffs();

  // 4. Ghostly Long-Exposure Double of the Right Hand (Motion Blur in Mercury)
  renderGhostHandExposure(28, -26, 0.88);
  renderGhostHandExposure(14, -13, 0.45);

  // 5. The Clasped Hands (Anatomical 3D Relief, Creases, and Fingernails)
  renderClaspedHands();

  // 6. Daguerreotype Plate Surface Physics (Buffing Marks, Mercury Frost, Archival Dust)
  renderPlateSurfaceArtifacts();

  // 7. Soft Charcoal Oval Vignette & Iridescent Blue-Violet Tarnish Halos
  renderVignetteAndTarnishHalo();

  // 8. Embossed Antique Brass Mat (Preserver / Passe-Partout) & Bevel
  renderBrassMatFrame();

  noLoop();
}

// ============================================================================
// GEOMETRY & LIGHTING HELPERS
// ============================================================================

function ovalNormDist(x, y, cx = CX, cy = CY, rx = OVAL_RX, ry = OVAL_RY) {
  let dx = (x - cx) / rx;
  let dy = (y - cy) / ry;
  return Math.sqrt(dx * dx + dy * dy);
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let st = constrain(t, 0, 0.999999) * n;
  let i = Math.floor(st);
  let f = st - i;

  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];

  let f2 = f * f;
  let f3 = f2 * f;

  let x = 0.5 * (
    (2 * p1.x) +
    (-p0.x + p2.x) * f +
    (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * f2 +
    (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * f3
  );
  let y = 0.5 * (
    (2 * p1.y) +
    (-p0.y + p2.y) * f +
    (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * f2 +
    (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * f3
  );
  let r = 0.5 * (
    (2 * p1.r) +
    (-p0.r + p2.r) * f +
    (2 * p0.r - 5 * p1.r + 4 * p2.r - p3.r) * f2 +
    (-p0.r + 3 * p1.r - 3 * p2.r + p3.r) * f3
  );

  // Tangent
  let tx = 0.5 * (
    (-p0.x + p2.x) +
    2 * (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * f +
    3 * (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * f2
  );
  let ty = 0.5 * (
    (-p0.y + p2.y) +
    2 * (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * f +
    3 * (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * f2
  );
  let len = Math.sqrt(tx * tx + ty * ty) || 1;
  tx /= len;
  ty /= len;

  // Normal pointing "upward" relative to screen (ensure ny <= 0 when horizontal)
  let nx = -ty;
  let ny = tx;
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }

  return { x, y, r, tx, ty, nx, ny };
}

// Maps a 0..1 luminance value to the Daguerreotype pewter-mercury palette
function mercuryColor(lum, warmth = 0) {
  lum = constrain(lum, 0, 1);
  // High-contrast metallic S-curve
  let s = lum < 0.5
    ? 2.0 * lum * lum
    : 1.0 - 2.0 * (1.0 - lum) * (1.0 - lum);

  const stops = [
    [10, 12, 18],     // 0.0: Abyssal mirror black
    [22, 27, 38],     // 0.16: Deep gunmetal shadow
    [40, 48, 63],     // 0.33: Dark slate pewter
    [68, 79, 98],     // 0.50: Mid cool pewter
    [108, 122, 144],  // 0.66: Silvery pewter
    [162, 177, 198],  // 0.82: Bright silver
    [216, 228, 242],  // 0.92: Frosted mercury
    [247, 251, 255]   // 1.00: Pure specular mercury highlight
  ];

  let idx = s * (stops.length - 1);
  let i0 = Math.floor(idx);
  let i1 = Math.min(stops.length - 1, i0 + 1);
  let f = idx - i0;

  let r = lerp(stops[i0][0], stops[i1][0], f) + warmth * 14;
  let g = lerp(stops[i0][1], stops[i1][1], f) + warmth * 6;
  let b = lerp(stops[i0][2], stops[i1][2], f) - warmth * 10;

  return color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
}

function drawOvalRingShape(cx, cy, rx, ry, steps = 40, jitter = 0) {
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let jr = jitter ? (noise(i * 0.3, rx * 0.01) - 0.5) * jitter : 0;
    let x = cx + (rx + jr) * cos(ang);
    let y = cy + (ry + jr) * sin(ang);
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

// ============================================================================
// 1. PLATE BASE & DARK VELVET WASHES
// ============================================================================

function renderPlateBaseAndVelvetWashes() {
  brush.noStroke();

  // Deep obsidian-pewter base wash inside the oval
  brush.wash("#0b0e15", 240);
  drawOvalRingShape(CX, CY, OVAL_RX * 1.02, OVAL_RY * 1.02, 48, 0);
  brush.noWash();

  // Soft atmospheric silver-pewter glow behind the hands (upper-central plate)
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.25);

  // Batch 1: Deep indigo-slate ambient glow in upper lap
  brush.fill("#1d2434", 85);
  drawOvalRingShape(CX - 20, CY - 70, 330, 350, 36, 12);
  drawOvalRingShape(CX, CY - 20, 270, 260, 32, 10);

  // Batch 2: Luminous pewter halo right around the clasped hands
  brush.fill("#2f394d", 65);
  drawOvalRingShape(CX - 10, CY - 15, 225, 165, 32, 8);

  // Batch 3: Deep velvet shadow sink below the hands in the lap
  brush.fill("#07090e", 130);
  drawOvalRingShape(CX + 10, CY + 190, 340, 230, 36, 15);
  drawOvalRingShape(CX - 30, CY + 240, 280, 175, 32, 12);

  brush.noFill();
}

// ============================================================================
// 2. DARK VELVET LAP DRAPERY FOLDS & GRAZING SILVER NAP
// ============================================================================

function renderVelvetDrapery() {
  // Define major velvet folds radiating down the child's skirt/lap
  const folds = [
    // Left lap folds
    { x0: 360, y0: 210, cx: 290, cy: 520, x1: 240, y1: 890, w: 46, lum: 0.34 },
    { x0: 435, y0: 190, cx: 385, cy: 480, x1: 315, y1: 960, w: 54, lum: 0.42 },
    { x0: 505, y0: 200, cx: 475, cy: 520, x1: 415, y1: 1020, w: 62, lum: 0.48 },
    // Central deep lap folds (compressed beneath the clasped hands)
    { x0: 575, y0: 205, cx: 560, cy: 450, x1: 525, y1: 1050, w: 58, lum: 0.38 },
    { x0: 645, y0: 210, cx: 645, cy: 460, x1: 635, y1: 1055, w: 64, lum: 0.46 },
    // Right lap folds
    { x0: 715, y0: 205, cx: 735, cy: 510, x1: 750, y1: 1025, w: 56, lum: 0.44 },
    { x0: 785, y0: 220, cx: 825, cy: 530, x1: 855, y1: 965, w: 50, lum: 0.36 },
    { x0: 850, y0: 260, cx: 900, cy: 560, x1: 935, y1: 880, w: 42, lum: 0.28 }
  ];

  // Draw deep velvet troughs and shimmering grazing ridges
  for (let f of folds) {
    let steps = 28;
    // Across-fold profile: left trough, sharp silver-pewter grazing ridge, right slope
    for (let s = -6; s <= 6; s++) {
      let u = s / 6; // -1..1 across the fold
      let ridge = Math.exp(-Math.pow((u + 0.18) * 3.2, 2)); // Grazing highlight offset
      let trough = Math.exp(-Math.pow((u - 0.45) * 2.4, 2));

      let pts = [];
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let bx = (1 - t) * (1 - t) * f.x0 + 2 * (1 - t) * t * f.cx + t * t * f.x1;
        let by = (1 - t) * (1 - t) * f.y0 + 2 * (1 - t) * t * f.cy + t * t * f.y1;

        // Slight inward gather under the hands (y ~ 550..680)
        let handPull = Math.exp(-Math.pow((by - 610) / 120, 2));
        let spread = f.w * (0.65 + 0.6 * t - 0.22 * handPull);

        let px = bx + u * spread + (noise(bx * 0.01, by * 0.01) - 0.5) * 14;
        let py = by;

        if (ovalNormDist(px, py) < 0.92) {
          let p = 0.4 + 0.6 * sin(t * 180) * (1 - 0.3 * handPull);
          pts.push([px, py, p]);
        }
      }

      if (pts.length > 3) {
        if (ridge > 0.45) {
          // Grazing velvet nap highlight
          let col = mercuryColor(f.lum * ridge * 0.95);
          brush.set("charcoal", col, 0.55 + ridge * 0.45);
          brush.spline(pts, 0.45);

          if (ridge > 0.78) {
            brush.set("2H", mercuryColor(f.lum * 1.15), 0.32);
            brush.spline(pts, 0.45);
          }
        } else if (trough > 0.4) {
          // Deep abyssal velvet trough
          brush.set("smudge", "#07090e", 0.95);
          brush.spline(pts, 0.4);
        } else {
          brush.set("charcoal", "#121621", 0.65);
          brush.spline(pts, 0.4);
        }
      }
    }
  }

  // Horizontal/catenary lap compression folds directly beneath the clasped hands
  for (let k = 0; k < 18; k++) {
    let yBase = map(k, 0, 17, 655, 895);
    let span = map(k, 0, 17, 210, 330);
    let sag = map(k, 0, 17, 38, 65);
    let isCrest = (k % 3 === 1);

    let pts = [];
    for (let i = 0; i <= 20; i++) {
      let u = map(i, 0, 20, -1, 1);
      let x = CX + u * span;
      let y = yBase + (1 - u * u) * sag + sin(u * 180 + k * 25) * 6;
      if (ovalNormDist(x, y) < 0.88) {
        pts.push([x, y, 0.3 + 0.7 * (1 - u * u)]);
      }
    }
    if (pts.length > 3) {
      if (isCrest) {
        brush.set("charcoal", mercuryColor(0.32 + 0.12 * sin(k * 37)), 0.55);
        brush.spline(pts, 0.5);
        brush.set("silverpoint", mercuryColor(0.52), 0.25);
        brush.spline(pts, 0.5);
      } else {
        brush.set("smudge", "#080a10", 0.85);
        brush.spline(pts, 0.5);
      }
    }
  }

  // Fine velvet nap cross-hatching in deep shadow zones
  for (let i = 0; i < 220; i++) {
    let ang = random(360);
    let rad = sqrt(random(0.15, 0.82));
    let x = CX + cos(ang) * rad * OVAL_RX;
    let y = CY + sin(ang) * rad * OVAL_RY;
    // Skip central hand zone
    if (dist(x, y, CX, 585) < 185) continue;

    let len = random(24, 65);
    let dir = 82 + (x - CX) * 0.04 + random(-8, 8);
    let lum = (y > 620 ? 0.14 : 0.10) * (1 - rad * 0.6);
    brush.set("2B", mercuryColor(lum + random(-0.04, 0.06)), random(0.3, 0.6));
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }
}

// ============================================================================
// 3. PLEATED LINEN & LACE CUFFS AT THE WRISTS
// ============================================================================

function renderWristCuffs() {
  // Left sleeve velvet edge & delicate pleated linen cuff
  drawLaceCuff(332, 488, 25, 76, 1.0, false);

  // Ghost cuff trace on the right wrist (from long exposure movement)
  drawLaceCuff(888 + 26, 482 - 24, 154, 74, 0.36, true);

  // Primary Right sleeve velvet edge & pleated linen cuff
  drawLaceCuff(882, 486, 155, 74, 0.92, false);
}

function drawLaceCuff(cx, cy, armAngle, radius, intensity, isGhost) {
  // Perpendicular axis along the cuff opening
  let px = -sin(armAngle);
  let py = cos(armAngle);
  // Direction toward the hand
  let ax = cos(armAngle);
  let ay = sin(armAngle);

  // Dark sleeve opening shadow behind the cuff
  if (!isGhost) {
    let shadowPts = [];
    for (let i = -8; i <= 8; i++) {
      let u = i / 8;
      let curve = (1 - u * u) * 18;
      shadowPts.push([
        cx + px * u * (radius * 1.12) - ax * (22 - curve),
        cy + py * u * (radius * 1.12) - ay * (22 - curve),
        1 - Math.abs(u) * 0.5
      ]);
    }
    brush.set("smudge", "#06080c", 1.2);
    brush.spline(shadowPts, 0.45);
  }

  // Pleated linen folds & scalloped lace edge
  let pleats = 11;
  for (let i = 0; i < pleats; i++) {
    let u = map(i, 0, pleats - 1, -0.95, 0.95);
    let arch = (1 - u * u) * 14;
    let bx = cx + px * (u * radius) + ax * arch;
    let by = cy + py * (u * radius) + ay * arch;

    // Upper pleats catch more skylight
    let lightFactor = constrain(0.75 - u * (armAngle < 90 ? 0.35 : -0.35), 0.25, 0.98) * intensity;

    // Pleat ridge lines
    for (let s = -2; s <= 2; s++) {
      let su = s * 3.2;
      let pLum = lightFactor * (1 - Math.abs(s) * 0.22);
      let x0 = bx + px * su - ax * 28;
      let y0 = by + py * su - ay * 28;
      let x1 = bx + px * (su * 0.8) + ax * 14;
      let y1 = by + py * (su * 0.8) + ay * 14;

      brush.set(isGhost ? "2H" : "HB", mercuryColor(pLum), isGhost ? 0.22 : 0.38);
      brush.line(x0, y0, x1, y1);
    }

    // Scalloped lace rim at the wrist edge
    let scallopPts = [];
    for (let k = 0; k <= 6; k++) {
      let ku = map(k, 0, 6, -1, 1);
      let sx = bx + px * ku * (radius / pleats) + ax * (14 + (1 - ku * ku) * 8);
      let sy = by + py * ku * (radius / pleats) + ay * (14 + (1 - ku * ku) * 8);
      scallopPts.push([sx, sy, 0.5 + 0.5 * (1 - ku * ku)]);
    }
    brush.set("silverpoint", mercuryColor(min(0.96, lightFactor * 1.18)), isGhost ? 0.18 : 0.32);
    brush.spline(scallopPts, 0.5);

    // Tiny lace eyelet hole in the center of each scallop
    if (!isGhost) {
      brush.set("silverpoint", "#121620", 0.35);
      let ex = bx + ax * 14;
      let ey = by + ay * 14;
      brush.circle(ex, ey, 2.2, 0.2);
    }
  }
}

