function renderGhostHandExposure(dx, dy, ghostStrength) {
  let rightGhost = getRightHandAnatomy(dx, dy);

  // Subtle silvery mercury mist wash where the ghost hand rested during exposure
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.45, 0.2);
  brush.fill("#4b576e", Math.round(32 * ghostStrength));

  // Ghost dorsum wash
  brush.beginShape(0.4);
  brush.vertex(rightGhost.wristAndDorsum.cuffCenter.x, rightGhost.wristAndDorsum.cuffCenter.y - 48);
  brush.vertex(rightGhost.wristAndDorsum.wristCenter.x - 10, rightGhost.wristAndDorsum.wristCenter.y - 52);
  brush.vertex(620 + dx, 462 + dy);
  brush.vertex(490 + dx, 515 + dy);
  brush.vertex(505 + dx, 570 + dy);
  brush.vertex(715 + dx, 655 + dy);
  brush.vertex(rightGhost.wristAndDorsum.cuffCenter.x + 25, rightGhost.wristAndDorsum.cuffCenter.y + 45);
  brush.endShape(true);
  brush.noFill();

  // Render ghost dorsum and upper fingers in ethereal silver-vapor strokes
  renderHandDorsum(rightGhost.wristAndDorsum, "right", true, ghostStrength);

  for (let fg of rightGhost.lowerFingers) {
    renderFinger3D(fg, true, ghostStrength * 0.75);
  }
  for (let fg of rightGhost.upperFingers) {
    renderFinger3D(fg, true, ghostStrength);
  }
}

// ============================================================================
// 5. PRIMARY CLASPED HANDS (PAINTER'S ORDER WITH CAST SHADOWS & MICRO-DETAIL)
// ============================================================================

function renderClaspedHands() {
  let leftHand = getLeftHandAnatomy();
  let rightHand = getRightHandAnatomy(0, 0);

  // --- LAYER 5A: Right Hand's Lower Fingers (tucked underneath on lower-right) ---
  for (let fg of rightHand.lowerFingers) {
    renderFinger3D(fg, false, 0.78);
  }

  // Soft cast shadow from Left Hand's lower fingers onto Right Hand's lower fingers & velvet
  drawContactShadowCurve([
    [468, 675], [538, 702], [608, 712], [685, 682], [728, 638]
  ], 18, 0.95);

  // --- LAYER 5B: Left Hand Wrist & Dorsum (Back of Hand) ---
  renderHandDorsum(leftHand.wristAndDorsum, "left", false, 0.96);

  // --- LAYER 5C: Left Hand Fingers (Little -> Ring -> Middle -> Index -> Thumb) ---
  for (let i = 0; i < leftHand.fingers.length; i++) {
    let fg = leftHand.fingers[i];
    // Cast shadow onto the finger below it
    if (i > 0 && i < 4) {
      let prev = leftHand.fingers[i - 1];
      drawInterdigitalShadow(fg, prev);
    }
    renderFinger3D(fg, false, 0.98);
  }

  // --- LAYER 5D: Cast Shadow of Right Hand's Clasping Fingers onto Left Hand ---
  drawContactShadowCurve([
    [486, 535], [545, 572], [618, 574], [692, 582], [735, 595]
  ], 16, 0.92);
  drawContactShadowCurve([
    [568, 492], [625, 488], [685, 492], [745, 512]
  ], 12, 0.80);

  // --- LAYER 5E: Right Hand Wrist & Upper Dorsum ---
  renderHandDorsum(rightHand.wristAndDorsum, "right", false, 0.96);

  // --- LAYER 5F: Right Hand Upper Clasping Fingers (Middle -> Index -> Thumb) ---
  for (let i = 0; i < rightHand.upperFingers.length; i++) {
    let fg = rightHand.upperFingers[i];
    if (i > 0) {
      let prev = rightHand.upperFingers[i - 1];
      drawInterdigitalShadow(fg, prev);
    }
    renderFinger3D(fg, false, 1.0);
  }
}

function drawContactShadowCurve(pts, widthPx, strength) {
  for (let s = 0; s < 5; s++) {
    let offset = (s - 2) * (widthPx * 0.22);
    let curve = pts.map(p => [p[0], p[1] + offset, 0.6 + 0.4 * (1 - Math.abs(s - 2) / 2.5)]);
    brush.set(s === 2 ? "charcoal" : "smudge", "#07090e", (1.1 - Math.abs(s - 2) * 0.22) * strength);
    brush.spline(curve, 0.45);
  }
}

function drawInterdigitalShadow(upperFinger, lowerFinger) {
  let cleftPts = [];
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    let uP = evalCatmullRom(upperFinger.pts, t);
    let lP = evalCatmullRom(lowerFinger.pts, t);
    let mx = lerp(uP.x - uP.nx * uP.r * 0.85, lP.x + lP.nx * lP.r * 0.85, 0.5);
    let my = lerp(uP.y - uP.ny * uP.r * 0.85, lP.y + lP.ny * lP.r * 0.85, 0.5);
    cleftPts.push([mx, my, 0.4 + 0.6 * sin(t * 180)]);
  }
  brush.set("smudge", "#080b11", 0.78);
  brush.spline(cleftPts, 0.45);
  brush.set("2B", "#0d1119", 0.48);
  brush.spline(cleftPts, 0.45);
}

// ============================================================================
// HAND DORSUM (BACK OF HAND, WRIST CREASES, CHILDHOOD KNUCKLE DIMPLES)
// ============================================================================

function renderHandDorsum(dorsum, side, isGhost, exposureScale) {
  let c0 = dorsum.cuffCenter;
  let w0 = dorsum.wristCenter;
  let mcps = dorsum.mcps;

  // Compute bounding quad / surface grid for the back of the hand
  // Top border: cuff top -> wrist top -> Index MCP
  // Bottom border: cuff bottom -> wrist bottom -> Little MCP
  let isLeft = (side === "left");
  let topCuff = { x: c0.x + (isLeft ? 20 : -20), y: c0.y - 54 };
  let botCuff = { x: c0.x - (isLeft ? 22 : -22), y: c0.y + 58 };
  let topWrist = { x: w0.x + (isLeft ? 16 : -16), y: w0.y - 48 };
  let botWrist = { x: w0.x - (isLeft ? 18 : -18), y: w0.y + 56 };
  let topKnuckle = { x: mcps[0].x, y: mcps[0].y - 18 };
  let botKnuckle = { x: mcps[3].x, y: mcps[3].y + 16 };

  // 1. Base opaque wash for solid primary hands (blocks dark velvet underneath)
  if (!isGhost) {
    brush.noStroke();
    brush.wash("#232a38", 235);
    brush.beginShape(0.35);
    brush.vertex(topCuff.x, topCuff.y);
    brush.vertex(topWrist.x, topWrist.y);
    brush.vertex(topKnuckle.x, topKnuckle.y);
    for (let m of mcps) brush.vertex(m.x + (isLeft ? 14 : -14), m.y);
    brush.vertex(botKnuckle.x, botKnuckle.y);
    brush.vertex(botWrist.x, botWrist.y);
    brush.vertex(botCuff.x, botCuff.y);
    brush.endShape(true);
    brush.noWash();

    // Soft mercury highlight wash on upper half of the back of the hand
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.45, 0.2);
    brush.fill("#687791", 95);
    brush.beginShape(0.4);
    brush.vertex(lerp(topCuff.x, botCuff.x, 0.12), lerp(topCuff.y, botCuff.y, 0.12));
    brush.vertex(lerp(topWrist.x, botWrist.x, 0.10), lerp(topWrist.y, botWrist.y, 0.10));
    brush.vertex(mcps[0].x, mcps[0].y - 8);
    brush.vertex(mcps[1].x, mcps[1].y);
    brush.vertex(lerp(topWrist.x, botWrist.x, 0.58), lerp(topWrist.y, botWrist.y, 0.58));
    brush.vertex(lerp(topCuff.x, botCuff.x, 0.52), lerp(topCuff.y, botCuff.y, 0.52));
    brush.endShape(true);
    brush.noFill();
  }

  // 2. Cross-contour 3D silverpoint & graphite strokes across the back of the hand
  let uSteps = isGhost ? 22 : 52;
  let vSteps = 14;

  for (let iu = 0; iu <= uSteps; iu++) {
    let u = iu / uSteps; // 0 = cuff, 0.42 = wrist, 1.0 = MCP knuckle arch

    // Interpolate top and bottom rails along u
    let topPt, botPt;
    if (u < 0.42) {
      let f = u / 0.42;
      topPt = { x: lerp(topCuff.x, topWrist.x, f), y: lerp(topCuff.y, topWrist.y, f) };
      botPt = { x: lerp(botCuff.x, botWrist.x, f), y: lerp(botCuff.y, botWrist.y, f) };
    } else {
      let f = (u - 0.42) / 0.58;
      topPt = { x: lerp(topWrist.x, topKnuckle.x, f), y: lerp(topWrist.y, topKnuckle.y, f) };
      botPt = { x: lerp(botWrist.x, botKnuckle.x, f), y: lerp(botWrist.y, botKnuckle.y, f) };
    }

    let crossPts = [];
    for (let iv = 0; iv <= vSteps; iv++) {
      let v = iv / vSteps; // 0 = top edge, 1 = bottom edge
      let vn = v * 2 - 1;  // -1..1

      // Arch the cross-contour slightly to reflect the 3D fullness of a child's hand
      let archOut = (1 - vn * vn) * (isLeft ? 14 : -14) * sin(u * 180);
      let x = lerp(topPt.x, botPt.x, v) + archOut;
      let y = lerp(topPt.y, botPt.y, v) - (1 - vn * vn) * 6;

      crossPts.push({ x, y, vn });
    }

    // Draw segmented strokes along the cross-contour with 3D normal lighting
    for (let s = 0; s < vSteps; s += 2) {
      let pA = crossPts[s];
      let pB = crossPts[Math.min(vSteps, s + 2)];
      let vm = (pA.vn + pB.vn) * 0.5;

      // 3D normal of the plush child dorsum
      let nx = (isLeft ? 0.15 : -0.15) + (u - 0.55) * (isLeft ? 0.35 : -0.35);
      let ny = vm * 0.82;
      let nz = Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny));

      // Childhood wrist crease indentation around u = 0.42
      let wristCrease = Math.exp(-Math.pow((u - 0.42) / 0.045, 2)) * Math.sin((u - 0.42) * 90);
      ny += wristCrease * 0.25;

      let ndotl = Math.max(0, nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z);
      // Specular mercury sheen on the upper dorsum swell (u ~ 0.65, vm ~ -0.35)
      let spec = Math.pow(ndotl, 7) * 0.42;
      // Subtle reflected light at bottom edge (vm > 0.7)
      let refl = vm > 0.65 ? (vm - 0.65) * 0.45 : 0;

      let lum = constrain((0.12 + ndotl * 0.68 + spec + refl) * exposureScale, 0.06, 0.98);

      if (isGhost && (lum < 0.28 || random() < 0.35)) continue;

      let bName = lum > 0.72 ? "silverpoint" : (lum > 0.38 ? "2H" : "HB");
      let w = isGhost ? 0.22 : map(lum, 0, 1, 0.45, 0.28);
      brush.set(bName, mercuryColor(lum), w);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // 3. Longitudinal skin grain & tendon/metacarpal modeling
  let longStrands = isGhost ? 14 : 34;
  for (let j = 0; j < longStrands; j++) {
    let v = map(j, 0, longStrands - 1, 0.06, 0.94);
    let vn = v * 2 - 1;
    let pts = [];
    for (let k = 0; k <= 12; k++) {
      let u = k / 12;
      let topPt = u < 0.42
        ? { x: lerp(topCuff.x, topWrist.x, u / 0.42), y: lerp(topCuff.y, topWrist.y, u / 0.42) }
        : { x: lerp(topWrist.x, topKnuckle.x, (u - 0.42) / 0.58), y: lerp(topWrist.y, topKnuckle.y, (u - 0.42) / 0.58) };
      let botPt = u < 0.42
        ? { x: lerp(botCuff.x, botWrist.x, u / 0.42), y: lerp(botCuff.y, botWrist.y, u / 0.42) }
        : { x: lerp(botWrist.x, botKnuckle.x, (u - 0.42) / 0.58), y: lerp(botWrist.y, botKnuckle.y, (u - 0.42) / 0.58) };

      let x = lerp(topPt.x, botPt.x, v) + (1 - vn * vn) * (isLeft ? 12 : -12) * sin(u * 180);
      let y = lerp(topPt.y, botPt.y, v);
      pts.push([x, y, 0.35 + 0.65 * sin(u * 180)]);
    }
    let lum = constrain((0.52 - vn * 0.34) * exposureScale, 0.08, 0.94);
    brush.set(lum > 0.65 ? "silverpoint" : "2H", mercuryColor(lum), isGhost ? 0.18 : 0.28);
    brush.spline(pts, 0.45);
  }

  // 4. Soft wrist skin creases
  for (let wc = -1; wc <= 1; wc++) {
    let wPts = [];
    for (let i = 0; i <= 8; i++) {
      let v = map(i, 0, 8, 0.12, 0.88);
      let x = lerp(topWrist.x, botWrist.x, v) + wc * 6 + sin(v * 180) * (isLeft ? 6 : -6);
      let y = lerp(topWrist.y, botWrist.y, v) + wc * 3;
      wPts.push([x, y, 0.3 + 0.7 * sin(v * 180)]);
    }
    brush.set("silverpoint", mercuryColor((wc === 0 ? 0.22 : 0.68) * exposureScale), isGhost ? 0.18 : 0.28);
    brush.spline(wPts, 0.5);
  }

  // 5. Childhood Dimpled MCP Knuckles (soft dimple hollows & radial skin folds)
  for (let i = 0; i < mcps.length; i++) {
    let m = mcps[i];
    let dimpleX = m.x - (isLeft ? 8 : -8);
    let dimpleY = m.y;
    let baseLum = map(i, 0, 3, 0.78, 0.36) * exposureScale;

    // Upper crescent catchlight of the knuckle dimple
    brush.set("silverpoint", mercuryColor(min(0.96, baseLum * 1.22)), isGhost ? 0.20 : 0.32);
    brush.arc(dimpleX, dimpleY, 8.5, isLeft ? 125 : 295, isLeft ? 245 : 65);

    // Soft shadow crescent inside the dimple hollow
    brush.set("2H", mercuryColor(baseLum * 0.48), isGhost ? 0.20 : 0.34);
    brush.arc(dimpleX, dimpleY, 6.0, isLeft ? 305 : 115, isLeft ? 65 : 245);

    // Fine micro-wrinkles across the MCP joint
    for (let k = -2; k <= 2; k++) {
      let cy = dimpleY + k * 2.8;
      let cx = dimpleX + (1 - (k * k) / 6) * (isLeft ? 3.5 : -3.5);
      let cLum = (k % 2 === 0 ? baseLum * 0.52 : min(0.95, baseLum * 1.18));
      brush.set("silverpoint", mercuryColor(cLum), isGhost ? 0.16 : 0.24);
      brush.line(cx - 2, cy - 5, cx + 2, cy + 5);
    }
  }
}

// ============================================================================
// 3D FINGER RENDERER (PHALANGES, KNUCKLE CREASES, FINGERNAILS)
// ============================================================================

function renderFinger3D(finger, isGhost, exposureScale) {
  let pts = finger.pts;

  // 1. Sample centerline spine
  let spineSteps = 44;
  let spine = [];
  for (let i = 0; i <= spineSteps; i++) {
    let t = i / spineSteps;
    let s = evalCatmullRom(pts, t);

    // Anatomical radius modulation: plump phalanges, slight narrowing at PIP/DIP joints, rounded tip
    let pipPinch = 1.0 - 0.06 * Math.exp(-Math.pow((t - finger.pipT) / 0.07, 2));
    let dipPinch = 1.0 - 0.05 * Math.exp(-Math.pow((t - finger.dipT) / 0.06, 2));
    let phalanxPlump = 1.0 + 0.05 * Math.sin(t * Math.PI * 3);
    let tipRound = t > 0.84 ? Math.sqrt(Math.max(0.02, 1.0 - Math.pow((t - 0.84) / 0.165, 2))) : 1.0;

    s.r = s.r * pipPinch * dipPinch * phalanxPlump * (0.32 + 0.68 * tipRound);
    s.t = t;
    spine.push(s);
  }

  // 2. Opaque base wash for solid fingers (prevents dark background bleed-through)
  if (!isGhost) {
    brush.noStroke();
    brush.wash("#222938", 242);
    brush.beginShape(0.25);
    for (let i = 0; i <= spineSteps; i += 2) {
      let s = spine[i];
      brush.vertex(s.x + s.nx * s.r * 0.96, s.y + s.ny * s.r * 0.96);
    }
    for (let i = spineSteps; i >= 0; i -= 2) {
      let s = spine[i];
      brush.vertex(s.x - s.nx * s.r * 0.96, s.y - s.ny * s.r * 0.96);
    }
    brush.endShape(true);
    brush.noWash();

    // Luminous silver wash along upper-dorsal ridge of the finger
    brush.fillBleed(0.15, "in");
    brush.fillTexture(0.35, 0.15);
    brush.fill(mercuryColor(0.68 * exposureScale), 95);
    brush.beginShape(0.3);
    for (let i = 2; i <= spineSteps - 2; i += 3) {
      let s = spine[i];
      brush.vertex(s.x + s.nx * s.r * 0.82, s.y + s.ny * s.r * 0.82);
    }
    for (let i = spineSteps - 2; i >= 2; i -= 3) {
      let s = spine[i];
      brush.vertex(s.x - s.nx * s.r * 0.08, s.y - s.ny * s.r * 0.08);
    }
    brush.endShape(true);
    brush.noFill();
  }

  // 3. Cross-Contour Cylindrical Silverpoint & Graphite Modeling
  let ringStep = isGhost ? 2 : 1;
  for (let i = 1; i < spineSteps; i += ringStep) {
    let s = spine[i];
    let t = s.t;

    // Cross-sectional rings wrapping around the 3D cylinder of the finger
    let uSlices = 10;
    for (let k = 0; k < uSlices; k++) {
      let u0 = map(k, 0, uSlices, -0.95, 0.95);
      let u1 = map(k + 1, 0, uSlices, -0.95, 0.95);
      let um = (u0 + u1) * 0.5; // -1 = top edge (nx, ny), +1 = bottom edge (-nx, -ny)

      // Compute 3D surface normal on the finger cylinder
      let nz = Math.sqrt(Math.max(0.04, 1.0 - um * um));
      // Longitudinal slope near fingertip or knuckle swell
      let longSlope = t > 0.82 ? (t - 0.82) * 2.2 : 0;
      let nx3 = -s.nx * um + s.tx * longSlope;
      let ny3 = -s.ny * um + s.ty * longSlope;
      let nLen = Math.sqrt(nx3 * nx3 + ny3 * ny3 + nz * nz) || 1;
      nx3 /= nLen;
      ny3 /= nLen;
      let nz3 = nz / nLen;

      // Skylight diffuse + metallic mercury specular + bottom reflected bounce
      let ndotl = Math.max(0, nx3 * LIGHT.x + ny3 * LIGHT.y + nz3 * LIGHT.z);
      let spec = Math.pow(ndotl, 8) * 0.46;
      // Core shadow trough around um = +0.52, reflected silver bounce around um = +0.86
      let coreDip = Math.exp(-Math.pow((um - 0.52) / 0.25, 2)) * 0.16;
      let reflBounce = um > 0.68 ? (um - 0.68) * 0.42 : 0;

      let lum = constrain((0.14 + ndotl * 0.68 + spec - coreDip + reflBounce) * exposureScale, 0.05, 0.99);

      if (isGhost && (lum < 0.30 || (i + k) % 2 === 1)) continue;

      // Slight perspective curve along the cross-section
      let curveOffset = Math.sqrt(Math.max(0, 1 - um * um)) * s.r * 0.18 * (finger.nailDir);
      let x0 = s.x - s.nx * (u0 * s.r) + s.tx * curveOffset;
      let y0 = s.y - s.ny * (u0 * s.r) + s.ty * curveOffset;
      let x1 = s.x - s.nx * (u1 * s.r) + s.tx * curveOffset;
      let y1 = s.y - s.ny * (u1 * s.r) + s.ty * curveOffset;

      let bName = lum > 0.74 ? "silverpoint" : (lum > 0.40 ? "2H" : "HB");
      let weight = isGhost ? 0.20 : map(lum, 0, 1, 0.42, 0.26);
      brush.set(bName, mercuryColor(lum), weight);
      brush.line(x0, y0, x1, y1);
    }
  }

  // 4. Longitudinal Contour & Specular Ridge Strokes along the Finger
  let bands = [-0.96, -0.78, -0.52, -0.32, -0.12, 0.15, 0.48, 0.76, 0.95];
  for (let u of bands) {
    let bandPts = [];
    for (let i = 0; i <= spineSteps; i += 2) {
      let s = spine[i];
      let bx = s.x - s.nx * (u * s.r);
      let by = s.y - s.ny * (u * s.r);
      bandPts.push([bx, by, 0.35 + 0.65 * sin(s.t * 180)]);
    }

    // Determine band tone
    let lum;
    if (u < -0.85) {
      // Crisp upper edge catchlight
      lum = 0.84 * exposureScale;
    } else if (u < -0.25) {
      // Bright mercury specular ridge
      lum = 0.94 * exposureScale;
    } else if (u < 0.25) {
      // Mid pewter transition
      lum = 0.56 * exposureScale;
    } else if (u < 0.65) {
      // Dark gunmetal core shadow
      lum = 0.16 * exposureScale;
    } else if (u < 0.88) {
      // Silvery reflected light on underside
      lum = 0.38 * exposureScale;
    } else {
      // Crisp lower occlusion contour
      lum = 0.08 * exposureScale;
    }

    if (isGhost && lum < 0.35) continue;

    let bName = (u < -0.25 || u > 0.88) ? "silverpoint" : "2H";
    let w = isGhost ? 0.22 : (u > 0.88 ? 0.38 : 0.28);
    brush.set(bName, mercuryColor(lum), w);
    brush.spline(bandPts, 0.45);
  }

  // 5. Mercury Crystal Stipple along the Specular Ridge (for primary hands)
  if (!isGhost && exposureScale > 0.85) {
    for (let i = 4; i < spineSteps - 4; i += 2) {
      let s = spine[i];
      let sx = s.x + s.nx * (s.r * random(0.25, 0.55));
      let sy = s.y + s.ny * (s.r * random(0.25, 0.55));
      brush.set("mercury_stipple", "#f2f7fd", 0.32);
      brush.line(sx, sy, sx + s.tx * 3, sy + s.ty * 3);
    }
  }

  // 6. Exact Knuckle Creases (PIP and DIP Joint Elliptical Skin Folds)
  renderJointCreases(spine, finger.pipT, 4, finger.nailDir, isGhost, exposureScale, 1.0);
  renderJointCreases(spine, finger.dipT, 3, finger.nailDir, isGhost, exposureScale, 0.82);

  // 7. Exact Fingernail (Nail Plate, Lunula, Cuticle, Lateral Folds, Free Edge)
  if (finger.hasNail) {
    renderFingernail(spine, finger, isGhost, exposureScale);
  }
}

// ============================================================================
// EXACT KNUCKLE CREASES (PIP & DIP JOINTS)
// ============================================================================

function renderJointCreases(spine, jointT, numFolds, dirSign, isGhost, exposureScale, scaleFactor) {
  let idx = Math.round(jointT * (spine.length - 1));
  let centerS = spine[constrain(idx, 2, spine.length - 3)];

  // At each finger joint, render concentric elliptical transverse skin folds:
  // Deep shadow crease lines alternating with plump, mercury-lit skin ridges
  for (let f = -numFolds; f <= numFolds; f++) {
    let offsetAlong = f * 2.1 * scaleFactor;
    let foldWidth = (1.0 - Math.pow(f / (numFolds + 1.2), 2)) * 0.78;

    // Curve of the skin fold across the dorsal surface of the joint
    let troughPts = [];
    let highlightPts = [];

    for (let k = 0; k <= 8; k++) {
      let u = map(k, 0, 8, -foldWidth, foldWidth * 0.75); // Skewed toward dorsal/upper side
      // Elliptical bow of the crease
      let bow = (1.0 - Math.pow(u / foldWidth, 2)) * (f * 1.35 + dirSign * 1.8);

      let px = centerS.x + centerS.tx * (offsetAlong + bow) - centerS.nx * (u * centerS.r);
      let py = centerS.y + centerS.ty * (offsetAlong + bow) - centerS.ny * (u * centerS.r);

      let press = 0.25 + 0.75 * (1.0 - Math.pow(u / foldWidth, 2));
      troughPts.push([px, py, press]);
      highlightPts.push([
        px + centerS.tx * 1.1 - centerS.nx * 0.5,
        py + centerS.ty * 1.1 - centerS.ny * 0.5,
        press
      ]);
    }

    // Dark crease trough
    let troughLum = (Math.abs(f) <= 1 ? 0.14 : 0.26) * exposureScale;
    if (!isGhost || Math.abs(f) <= 1) {
      brush.set("silverpoint", mercuryColor(troughLum), isGhost ? 0.18 : (Math.abs(f) === 0 ? 0.34 : 0.24));
      brush.spline(troughPts, 0.5);
    }

    // Bright silvery mercury catchlight on the lip of each crease fold
    let crestLum = min(0.98, (Math.abs(f) <= 1 ? 0.92 : 0.78) * exposureScale);
    brush.set("silverpoint", mercuryColor(crestLum), isGhost ? 0.20 : 0.26);
    brush.spline(highlightPts, 0.5);
  }
}

// ============================================================================
// EXACT FINGERNAILS (KERATIN PLATE, LUNULA, CUTICLE, FREE EDGE)
// ============================================================================

function renderFingernail(spine, finger, isGhost, exposureScale) {
  // Nail spans from t = 0.79 (cuticle base) to t = 0.97 (distal free edge)
  let iStart = Math.floor(0.79 * (spine.length - 1));
  let iEnd = Math.floor(0.97 * (spine.length - 1));

  // Dorsal position on the fingertip: shifted slightly toward upper side (u in [-0.78, +0.18])
  let uTop = -0.78;
  let uBot = finger.isThumb ? -0.05 : 0.18;

  // Helper to get point on nail coordinate (nt in 0..1 along length, nu in 0..1 top-to-bottom)
  const nailPt = (nt, nu) => {
    let sIdx = lerp(iStart, iEnd, nt);
    let i0 = Math.floor(sIdx);
    let i1 = Math.min(spine.length - 1, i0 + 1);
    let f = sIdx - i0;
    let s = {
      x: lerp(spine[i0].x, spine[i1].x, f),
      y: lerp(spine[i0].y, spine[i1].y, f),
      r: lerp(spine[i0].r, spine[i1].r, f),
      tx: spine[i0].tx,
      ty: spine[i0].ty,
      nx: spine[i0].nx,
      ny: spine[i0].ny
    };

    // Rounded cuticle base at nt -> 0 and curved distal edge at nt -> 1
    let widthTaper = Math.sin(constrain(nt, 0.05, 0.95) * Math.PI * 0.85 + 0.22);
    let uMid = (uTop + uBot) * 0.5;
    let uHalf = ((uBot - uTop) * 0.5) * (0.68 + 0.32 * widthTaper);
    let u = uMid + (nu * 2 - 1) * uHalf;

    // Slight cylindrical arch of the nail plate
    let arch = (1 - Math.pow(nu * 2 - 1, 2)) * 2.2 * finger.nailDir;
    return {
      x: s.x - s.nx * (u * s.r) + s.tx * arch,
      y: s.y - s.ny * (u * s.r) + s.ty * arch
    };
  };

  // 1. Longitudinal Keratin Sheen & Metallic Shading across the Nail Plate
  let strips = isGhost ? 5 : 9;
  for (let k = 0; k <= strips; k++) {
    let nu = k / strips;
    let p0 = nailPt(0.04, nu);
    let pMid = nailPt(0.52, nu);
    let p1 = nailPt(0.96, nu);

    // High-gloss metallic specular band at nu ~ 0.32
    let specBand = Math.exp(-Math.pow((nu - 0.32) / 0.20, 2));
    let nLum = constrain((0.46 + 0.52 * specBand - 0.22 * nu) * exposureScale, 0.18, 0.99);

    brush.set("silverpoint", mercuryColor(nLum), isGhost ? 0.20 : 0.28);
    brush.spline([
      [p0.x, p0.y, 0.5],
      [pMid.x, pMid.y, 1.0],
      [p1.x, p1.y, 0.6]
    ], 0.4);
  }

  // 2. Pale Frosty Lunula (Half-Moon at the Base of the Nail, nt = 0.04..0.28)
  for (let l = 0; l < 3; l++) {
    let lnt = 0.12 + l * 0.06;
    let lPts = [];
    for (let m = 0; m <= 6; m++) {
      let nu = map(m, 0, 6, 0.15, 0.85);
      let curveNt = lnt * (1 - Math.pow((nu - 0.5) * 1.8, 2));
      let p = nailPt(max(0.03, curveNt), nu);
      lPts.push([p.x, p.y, 0.5 + 0.5 * (1 - Math.abs(nu - 0.5) * 2)]);
    }
    brush.set("silverpoint", mercuryColor(min(0.98, 0.88 * exposureScale)), isGhost ? 0.18 : 0.26);
    brush.spline(lPts, 0.5);
  }

  // 3. Proximal Nail Fold & Cuticle Rim (Dark micro-crevice + bright cuticle lip)
  let cutShadow = [];
  let cutHighlight = [];
  for (let m = 0; m <= 6; m++) {
    let nu = m / 6;
    let bow = (1 - Math.pow(nu * 2 - 1, 2)) * 0.08;
    let pS = nailPt(0.10 - bow, nu);
    let pH = nailPt(0.02 - bow, nu);
    cutShadow.push([pS.x, pS.y, 0.6]);
    cutHighlight.push([pH.x, pH.y, 0.6]);
  }
  brush.set("silverpoint", mercuryColor(0.14 * exposureScale), isGhost ? 0.18 : 0.30);
  brush.spline(cutShadow, 0.5);
  brush.set("silverpoint", mercuryColor(min(0.97, 0.86 * exposureScale)), isGhost ? 0.18 : 0.25);
  brush.spline(cutHighlight, 0.5);

  // 4. Lateral Nail Folds (Top and Bottom skin borders framing the nail)
  let topFold = [nailPt(0.08, 0.0), nailPt(0.5, 0.0), nailPt(0.92, 0.0)].map(p => [p.x, p.y, 0.7]);
  let botFold = [nailPt(0.08, 1.0), nailPt(0.5, 1.0), nailPt(0.92, 1.0)].map(p => [p.x, p.y, 0.7]);
  brush.set("silverpoint", mercuryColor(0.16 * exposureScale), isGhost ? 0.18 : 0.30);
  brush.spline(topFold, 0.4);
  brush.spline(botFold, 0.4);

  // 5. Distal Free Edge of the Fingernail (Bright silver-white crescent + dark under-nail line)
  let freeEdge = [];
  let underNail = [];
  for (let m = 0; m <= 6; m++) {
    let nu = m / 6;
    let bow = (1 - Math.pow(nu * 2 - 1, 2)) * 0.07;
    let pE = nailPt(0.91 + bow, nu);
    let pU = nailPt(0.98 + bow, nu);
    freeEdge.push([pE.x, pE.y, 0.8]);
    underNail.push([pU.x, pU.y, 0.7]);
  }
  brush.set("silverpoint", mercuryColor(min(0.99, 0.94 * exposureScale)), isGhost ? 0.22 : 0.32);
  brush.spline(freeEdge, 0.5);
  brush.set("silverpoint", mercuryColor(0.10 * exposureScale), isGhost ? 0.18 : 0.32);
  brush.spline(underNail, 0.5);
}

// ============================================================================
// 6. DAGUERREOTYPE PLATE SURFACE ARTIFACTS (BUFFING LINES & ARCHIVAL PATINA)
// ============================================================================

function renderPlateSurfaceArtifacts() {
  // 1. Fine horizontal silver-plate buffing marks (from polishing the silvered copper plate)
  for (let i = 0; i < 160; i++) {
    let y = random(CY - OVAL_RY * 0.92, CY + OVAL_RY * 0.92);
    let dy = (y - CY) / OVAL_RY;
    let maxRx = Math.sqrt(Math.max(0, 1 - dy * dy)) * OVAL_RX * 0.92;
    if (maxRx < 40) continue;

    let x0 = CX + random(-maxRx, maxRx * 0.4);
    let len = random(45, 220);
    let x1 = min(CX + maxRx, x0 + len);
    let slope = random(-1.8, 1.8); // Almost horizontal buffing strokes

    let isBrightScratch = random() < 0.45;
    let col = isBrightScratch ? color(195, 210, 228, 38) : color(16, 20, 28, 45);
    brush.set("silverpoint", col, random(0.14, 0.24));
    brush.line(x0, y, x1, y + slope);
  }

  // 2. Diagonal metallic sheen reflection across the polished silver plate
  for (let i = 0; i < 45; i++) {
    let offset = random(-280, 280);
    let x0 = CX - 260 + offset * 0.5;
    let y0 = CY - 320 + offset * 0.3;
    let x1 = x0 + random(80, 180);
    let y1 = y0 + (x1 - x0) * 0.85;
    if (ovalNormDist(x0, y0) < 0.82 && ovalNormDist(x1, y1) < 0.82) {
      brush.set("silverpoint", color(210, 224, 240, 28), 0.18);
      brush.line(x0, y0, x1, y1);
    }
  }

  // 3. Tiny archival oxidation spots & mercury dust specks near the vignette
  for (let i = 0; i < 75; i++) {
    let ang = random(360);
    let rad = random(0.55, 0.95);
    let x = CX + cos(ang) * rad * OVAL_RX;
    let y = CY + sin(ang) * rad * OVAL_RY;
    if (random() < 0.5) {
      brush.set("silverpoint", "#07090e", random(0.25, 0.45));
      brush.circle(x, y, random(1.0, 2.8), 0.3);
    } else {
      brush.set("mercury_stipple", "#c8d6e8", random(0.22, 0.38));
      brush.line(x, y, x + 2, y + 2);
    }
  }
}

// ============================================================================
// 7. CHARCOAL VIGNETTE & IRIDESCENT BLUE-VIOLET TARNISH HALOS
// ============================================================================

function renderVignetteAndTarnishHalo() {
  // Daguerreotype chemical tarnish halo sequence from inner vignette to brass mat edge:
  // r = 0.74..0.85: Soft charcoal smudging vignette
  // r = 0.84..0.93: Deep iridescent Prussian blue & cobalt-violet tarnish halo
  // r = 0.92..0.97: Smoky violet-indigo & peacock slate oxidation
  // r = 0.96..1.00: Warm amber-bronze edge tarnish right against the brass mat

  const haloBands = [
    { rMin: 0.73, rMax: 0.83, col: "#0b0e16", bName: "smudge", w: 1.15, count: 44 },
    { rMin: 0.80, rMax: 0.89, col: "#17233d", bName: "smudge", w: 1.05, count: 48 },
    { rMin: 0.84, rMax: 0.93, col: "#253966", bName: "charcoal", w: 0.85, count: 55 },
    { rMin: 0.86, rMax: 0.95, col: "#3c3264", bName: "smudge", w: 0.95, count: 52 },
    { rMin: 0.88, rMax: 0.96, col: "#4c5f8a", bName: "charcoal", w: 0.65, count: 45 },
    { rMin: 0.91, rMax: 0.97, col: "#2d2246", bName: "charcoal", w: 0.80, count: 45 },
    { rMin: 0.94, rMax: 0.99, col: "#573d22", bName: "smudge", w: 0.90, count: 42 },
    { rMin: 0.97, rMax: 1.005, col: "#1c140c", bName: "charcoal", w: 0.95, count: 48 }
  ];

  for (let band of haloBands) {
    for (let i = 0; i < band.count; i++) {
      let rNorm = random(band.rMin, band.rMax);
      let startAng = random(360);
      let arcSpan = random(22, 52);

      let pts = [];
      let steps = 8;
      for (let s = 0; s <= steps; s++) {
        let a = startAng + (s / steps) * arcSpan;
        let wobble = (noise(a * 0.05, rNorm * 4) - 0.5) * 0.025;
        let rx = (rNorm + wobble) * OVAL_RX;
        let ry = (rNorm + wobble) * OVAL_RY;
        pts.push([
          CX + cos(a) * rx,
          CY + sin(a) * ry,
          0.3 + 0.7 * sin((s / steps) * 180)
        ]);
      }
      brush.set(band.bName, band.col, band.w * random(0.8, 1.2));
      brush.spline(pts, 0.5);
    }
  }

  // Delicate metallic silver-blue iridescent shimmer streaks inside the tarnish halo
  for (let i = 0; i < 65; i++) {
    let rNorm = random(0.85, 0.95);
    let startAng = random(360);
    let arcSpan = random(12, 28);
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      let a = startAng + (s / 5) * arcSpan;
      pts.push([
        CX + cos(a) * rNorm * OVAL_RX,
        CY + sin(a) * rNorm * OVAL_RY,
        0.4 + 0.6 * sin((s / 5) * 180)
      ]);
    }
    let shimmerCol = random() < 0.5 ? "#6982b0" : "#7868a3";
    brush.set("2H", shimmerCol, 0.35);
    brush.spline(pts, 0.5);
  }
}

// ============================================================================
// 8. EMBOSSED ANTIQUE BRASS MAT (PASSE-PARTOUT) & BEVELED APERTURE
// ============================================================================

function renderBrassMatFrame() {
  // 1. Solid opaque brass mat surround outside the oval aperture (drawn in 4 overlapping quadrants)
  brush.noStroke();
  brush.wash("#221a0d", 255);

  const outerPad = 650;
  for (let q = 0; q < 4; q++) {
    let aStart = q * 90;
    let aEnd = (q + 1) * 90;
    brush.beginShape(0);
    // Inner oval edge
    for (let a = aStart; a <= aEnd; a += 3) {
      brush.vertex(CX + cos(a) * OVAL_RX * 1.002, CY + sin(a) * OVAL_RY * 1.002);
    }
    // Outer canvas boundary
    for (let a = aEnd; a >= aStart; a -= 15) {
      brush.vertex(CX + cos(a) * outerPad * 1.45, CY + sin(a) * outerPad * 1.45);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 2. Engine-Turned / Stamped Antique Brass Texture on the Outer Mat
  for (let ring = 0; ring < 38; ring++) {
    let rNorm = map(ring, 0, 37, 1.055, 1.62);
    let rx = rNorm * OVAL_RX;
    let ry = rNorm * OVAL_RY;

    let segs = 72;
    for (let s = 0; s < segs; s++) {
      let a0 = (s / segs) * 360;
      let a1 = ((s + 0.85) / segs) * 360;
      let x0 = CX + cos(a0) * rx;
      let y0 = CY + sin(a0) * ry;
      let x1 = CX + cos(a1) * rx;
      let y1 = CY + sin(a1) * ry;

      if (x0 < -10 || x0 > 1210 || y0 < -10 || y0 > 1210) continue;

      // Directional metallic sheen on the brass mat (brighter at upper-left & lower-right)
      let sheen = Math.pow(Math.max(0, cos(a0 - 135)), 2) * 0.65 +
                  Math.pow(Math.max(0, cos(a0 - 315)), 2) * 0.45;
      // Dark vignette toward the extreme corners of the canvas
      let cornerFade = constrain(map(rNorm, 1.15, 1.55, 1.0, 0.15), 0.1, 1.0);
      // Embossed guilloche wave pattern
      let wave = 0.5 + 0.5 * sin(a0 * 24 + ring * 35);

      let bVal = (0.18 + 0.55 * sheen + 0.22 * wave) * cornerFade;
      let col = brassColor(bVal);

      brush.set(bVal > 0.55 ? "2H" : "charcoal", col, map(bVal, 0, 1, 0.85, 0.42));
      brush.line(x0, y0, x1, y1);
    }
  }

  // 3. Repoussé Decorative Beaded Ring & Recessed Groove around the Aperture (r = 1.042..1.058)
  drawBrassOvalContour(1.042, "#140e06", "charcoal", 0.95);
  drawBrassOvalContour(1.056, "#140e06", "charcoal", 0.85);

  let beadCount = 160;
  for (let i = 0; i < beadCount; i++) {
    let ang = (i / beadCount) * 360;
    let bx = CX + cos(ang) * OVAL_RX * 1.049;
    let by = CY + sin(ang) * OVAL_RY * 1.049;
    let sheen = 0.35 + 0.65 * Math.pow(Math.max(0, cos(ang - 135)), 2) +
                0.45 * Math.pow(Math.max(0, cos(ang - 315)), 2);

    brush.set("silverpoint", brassColor(min(0.98, sheen * 1.15)), 0.36);
    brush.circle(bx, by, 2.8, 0.15);
  }

  // 4. The 3D Inner Beveled Gilt Rim of the Brass Mat (r = 1.000..1.040)
  let bevelRings = 14;
  for (let b = 0; b <= bevelRings; b++) {
    let f = b / bevelRings;
    let rNorm = lerp(1.001, 1.040, f);
    let segs = 90;

    for (let s = 0; s < segs; s++) {
      let a0 = (s / segs) * 360;
      let a1 = ((s + 1) / segs) * 360;
      let x0 = CX + cos(a0) * OVAL_RX * rNorm;
      let y0 = CY + sin(a0) * OVAL_RY * rNorm;
      let x1 = CX + cos(a1) * OVAL_RX * rNorm;
      let y1 = CY + sin(a1) * OVAL_RY * rNorm;

      // Bevel faces inward: catches direct skylight on bottom-right arc (a ~ -60..110)
      // and warm reflected sheen on upper-left arc
      let bevelLight = Math.pow(Math.max(0, cos(a0 - 35)), 2) * 0.85 +
                       Math.pow(Math.max(0, cos(a0 - 215)), 2) * 0.45;
      let profile = sin(f * 180); // Rounded bevel cross-section
      let bLum = constrain(0.15 + bevelLight * (0.45 + 0.55 * profile), 0.08, 0.99);

      brush.set(bLum > 0.7 ? "silverpoint" : "2H", brassColor(bLum), 0.38);
      brush.line(x0, y0, x1, y1);
    }
  }

  // 5. Crisp Inner Shadow Cast by the Brass Mat onto the Silver Daguerreotype Plate
  // (Upper-left inner edge casts a deep shadow onto the plate; lower-right inner edge has a razor-sharp gilt rim)
  for (let s = 0; s < 90; s++) {
    let a0 = (s / 90) * 360;
    let a1 = ((s + 1) / 90) * 360;
    let x0 = CX + cos(a0) * OVAL_RX * 0.997;
    let y0 = CY + sin(a0) * OVAL_RY * 0.997;
    let x1 = CX + cos(a1) * OVAL_RX * 0.997;
    let y1 = CY + sin(a1) * OVAL_RY * 0.997;

    let isShadowSide = cos(a0 - 220) > -0.2;
    if (isShadowSide) {
      brush.set("charcoal", "#050609", 0.92);
      brush.line(x0, y0, x1, y1);
    } else {
      brush.set("silverpoint", brassColor(0.95), 0.35);
      brush.line(x0, y0, x1, y1);
    }
  }

  // 6. Outer Dark Leather/Velvet Case Corner Shadow
  for (let c = 0; c < 4; c++) {
    let cx = (c % 2 === 0) ? 0 : 1200;
    let cy = (c < 2) ? 0 : 1200;
    for (let k = 0; k < 28; k++) {
      let rad = random(40, 260);
      let aStart = c === 0 ? 0 : (c === 1 ? 90 : (c === 2 ? 270 : 180));
      let a0 = aStart + random(5, 45);
      let a1 = a0 + random(25, 40);
      brush.set("smudge", "#090705", random(0.8, 1.3));
      brush.line(
        cx + cos(a0) * rad, cy + sin(a0) * rad,
        cx + cos(a1) * rad, cy + sin(a1) * rad
      );
    }
  }
}

function drawBrassOvalContour(rNorm, col, bName, weight) {
  let pts = [];
  for (let i = 0; i <= 72; i++) {
    let a = (i / 72) * 360;
    pts.push([
      CX + cos(a) * OVAL_RX * rNorm,
      CY + sin(a) * OVAL_RY * rNorm,
      0.7
    ]);
  }
  brush.set(bName, col, weight);
  brush.spline(pts, 0.5);
}

function brassColor(lum) {
  lum = constrain(lum, 0, 1);
  const stops = [
    [18, 13, 6],      // 0.0: Deep oxidized umber-black
    [44, 32, 15],     // 0.25: Dark tarnished bronze
    [82, 62, 26],     // 0.50: Antique brass midtone
    [138, 108, 48],   // 0.72: Warm burnished brass
    [198, 162, 82],   // 0.88: Bright gilt gold
    [244, 222, 156]   // 1.00: Specular brass highlight
  ];
  let idx = lum * (stops.length - 1);
  let i0 = Math.floor(idx);
  let i1 = Math.min(stops.length - 1, i0 + 1);
  let f = idx - i0;
  return color(
    lerp(stops[i0][0], stops[i1][0], f),
    lerp(stops[i0][1], stops[i1][1], f),
    lerp(stops[i0][2], stops[i1][2], f)
  );
}

const HORIZON_Y = 936;
const SUN_X = 648;

// Sky color stops from zenith (0.0) to horizon (1.0) — muted earth & atmospheric tones
const SKY_STOPS = [
  { pos: 0.00, col: [30, 43, 56] },    // Deep zenith steel-slate
  { pos: 0.16, col: [43, 59, 74] },    // Cold steel blue
  { pos: 0.32, col: [62, 78, 92] },    // Weathered slate blue
  { pos: 0.48, col: [87, 94, 103] },   // Muted storm pewter-slate
  { pos: 0.62, col: [118, 105, 107] }, // Dusty lavender-taupe
  { pos: 0.74, col: [152, 117, 109] }, // Muted earth rose
  { pos: 0.84, col: [182, 134, 108] }, // Faded terracotta-rose
  { pos: 0.92, col: [208, 155, 111] }, // Muted apricot-ochre
  { pos: 0.97, col: [222, 170, 118] }, // Warm horizon apricot
  { pos: 1.00, col: [192, 140, 102] }  // Dense marine-layer amber-umber rim
];

function lerpRGB(c1, c2, t) {
  t = constrain(t, 0, 1);
  return [
    c1[0] + (c2[0] - c1[0]) * t,
    c1[1] + (c2[1] - c1[1]) * t,
    c1[2] + (c2[2] - c1[2]) * t
  ];
}

function rgbToHex(rgb) {
  const r = constrain(Math.round(rgb[0]), 0, 255).toString(16).padStart(2, "0");
  const g = constrain(Math.round(rgb[1]), 0, 255).toString(16).padStart(2, "0");
  const b = constrain(Math.round(rgb[2]), 0, 255).toString(16).padStart(2, "0");
  return `#${r}${g}${b}`;
}

function sampleSkyRGB(x, y) {
  let yn = constrain(y / HORIZON_Y, 0, 1);
  let base = SKY_STOPS[SKY_STOPS.length - 1].col;
  for (let i = 0; i < SKY_STOPS.length - 1; i++) {
    if (yn >= SKY_STOPS[i].pos && yn <= SKY_STOPS[i + 1].pos) {
      let localT = (yn - SKY_STOPS[i].pos) / (SKY_STOPS[i + 1].pos - SKY_STOPS[i].pos);
      localT = localT * localT * (3 - 2 * localT);
      base = lerpRGB(SKY_STOPS[i].col, SKY_STOPS[i + 1].col, localT);
      break;
    }
  }

  // Subtle solar azimuth glow near the vanished sun
  let dx = (x - SUN_X) / 410.0;
  let dy = (HORIZON_Y - y) / 145.0;
  let solarGlow = Math.exp(-(dx * dx * 1.15 + dy * dy * 1.65));
  if (solarGlow > 0.01) {
    let warmGlow = [244, 211, 152];
    base = lerpRGB(base, warmGlow, solarGlow * 0.42);
  }

  // Slight atmospheric extinction cooling toward far lateral edges near horizon
  let edgeDist = Math.abs(x - SUN_X) / 650.0;
  if (yn > 0.7 && edgeDist > 0.45) {
    let coolEdge = [132, 108, 104];
    let edgeFactor = constrain((edgeDist - 0.45) * 0.55 * ((yn - 0.7) / 0.3), 0, 0.28);
    base = lerpRGB(base, coolEdge, edgeFactor);
  }

  return base;
}

function evaluateWave(x, y) {
  let u = constrain((y - HORIZON_Y) / (1200 - HORIZON_Y), 0.0005, 1.0);
  // Projective distance z and world horizontal coordinate X
  let z = 1.0 / (u + 0.016);
  let X = ((x - 600) / (u + 0.055)) * 0.0032;

  // Multi-harmonic ocean swell and capillary wave field
  let n1 = noise(X * 0.65 + 11.3, z * 0.11 + 4.7) * 5.8;
  let n2 = noise(X * 1.55 + 43.1, z * 0.28 + 9.2) * 4.6;
  let n3 = noise(X * 3.80 + 87.5, z * 0.75 + 2.1) * 5.2;

  let p1 = z * 4.4 + n1;
  let p2 = z * 11.2 + X * 1.9 + n2;
  let p3 = z * 25.0 - X * 3.4 + n3;

  let ridge = Math.sin(p1) * 0.52 + Math.sin(p2) * 0.31 + Math.sin(p3) * 0.17;
  let slope = Math.cos(p1) * 0.52 + Math.cos(p2) * 0.31 + Math.cos(p3) * 0.17;
  let micro = (noise(X * 9.5 + 130, z * 2.4 + 17) - 0.5) * 0.48;

  return {
    u,
    z,
    ridge,
    slope: slope + micro
  };
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Custom aerosol spray for soft meteorological sky gradients
  brush.add("atmos_spray", {
    type: "spray",
    weight: 26,
    scatter: 3.9,
    opacity: 15,
    spacing: 0.35,
    pressure: [0.5, 1.0, 0.5],
    rotate: "random"
  });

  // Soft dry-pigment veil for seamless horizon and stratus blending
  brush.add("pastel_veil", {
    type: "default",
    weight: 16,
    scatter: 0.55,
    sharpness: 0.07,
    grain: 8,
    opacity: 15,
    spacing: 0.28,
    pressure: [0.35, 1.0, 0.35],
    noise: 0.25
  });

  // Tapered engraving pen for foreground/midground horizontal water ticks
  brush.add("sea_pen", {
    type: "default",
    weight: 0.72,
    scatter: 0.03,
    sharpness: 0.84,
    grain: 3,
    opacity: 170,
    spacing: 0.35,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.2
  });

  // Ultra-fine meteorological needle for horizon distance & green flash details
  brush.add("micro_pen", {
    type: "default",
    weight: 0.38,
    scatter: 0.015,
    sharpness: 0.92,
    grain: 2,
    opacity: 190,
    spacing: 0.38,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.12
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#1e2b38");
  brush.noField();

  // =========================================================================
  // 1. SKY FOUNDATION: OPTICAL WASH GRADIENT (ZENITH STEEL TO HORIZON APRICOT)
  // =========================================================================
  brush.noStroke();
  brush.noHatch();
  const skyBands = 96;
  const bandStep = HORIZON_Y / skyBands;
  for (let i = 0; i <= skyBands; i++) {
    let y = i * bandStep;
    let rgb = sampleSkyRGB(600, y);
    brush.wash(rgbToHex(rgb), 115);
    brush.rect(-20, y - 4, 1240, bandStep + 10, "corner");
  }

  // Localized solar horizon cushion where the sun has just dipped below the rim
  for (let r = 12; r >= 1; r--) {
    let t = r / 12;
    let w = 110 + t * 560;
    let h = 18 + t * 145;
    let yCenter = HORIZON_Y - h * 0.28;
    let rgb = sampleSkyRGB(SUN_X, yCenter);
    let warmShift = lerpRGB(rgb, [246, 214, 154], (1 - t) * 0.55);
    brush.wash(rgbToHex(warmShift), 24);
    brush.rect(SUN_X - w / 2, yCenter - h / 2, w, h, "corner");
  }
  brush.noWash();

  // =========================================================================
  // 2. SOFT SPRAY & PASTEL VEIL GRADIENTS ACROSS THE VAST SKY
  // =========================================================================
  // Pass A: Velvety horizontal pastel-veil sweeps to fuse the atmospheric strata
  for (let i = 0; i < 210; i++) {
    let yn = Math.pow(random(), 0.88);
    let y = yn * (HORIZON_Y - 4);
    let sampleY = constrain(y + random(-42, 42), 0, HORIZON_Y);
    let xMid = random(150, 1050);
    let col = rgbToHex(sampleSkyRGB(xMid, sampleY));
    let wt = map(yn, 0, 1, 1.35, 0.55) * random(0.75, 1.25);

    brush.set("pastel_veil", col, wt);
    let x1 = random(-60, 120);
    let x2 = random(1080, 1260);
    brush.line(x1, y, x2, y + random(-1.5, 1.5));
  }

  // Pass B: Fine aerosol spray stipple fading apricot -> rose -> steel blue
  for (let i = 0; i < 360; i++) {
    let yn = random();
    let y = yn * (HORIZON_Y - 2);
    // Sample slightly displaced altitude to interleave grain between color zones
    let spread = map(yn, 0, 1, 65, 28);
    let sampleY = constrain(y + random(-spread, spread), 0, HORIZON_Y);
    let xSpanStart = random(-50, 350);
    let xSpanEnd = random(850, 1250);
    let col = rgbToHex(sampleSkyRGB((xSpanStart + xSpanEnd) * 0.5, sampleY));

    let brushName = random() < 0.72 ? "atmos_spray" : "spray";
    let wt = brushName === "atmos_spray"
      ? map(yn, 0, 1, 1.15, 0.48) * random(0.8, 1.2)
      : map(yn, 0, 1, 0.55, 0.28) * random(0.8, 1.2);

    brush.set(brushName, col, wt);
    brush.line(xSpanStart, y, xSpanEnd, y + random(-1.2, 1.2));
  }

  // =========================================================================
  // 3. DISTANT HORIZON INVERSION FILAMENTS (EDGE-ON MARINE STRATUS)
  // =========================================================================
  for (let i = 0; i < 68; i++) {
    let v = Math.pow(random(), 1.9); // Concentrated near the low horizon
    let y = HORIZON_Y - 3 - v * 175;
    let len = map(v, 0, 1, 90, 420) * random(0.5, 1.4);
    let cx = random(60, 1140);
    let x1 = cx - len * 0.5;
    let x2 = cx + len * 0.5;

    let skyHere = sampleSkyRGB(cx, y);
    let sunDist = Math.abs(cx - SUN_X) / 500.0;

    // Upper cool shadow edge of distant stratus filament
    let shadowRGB = lerpRGB(skyHere, [92, 86, 94], 0.36);
    brush.set("pastel_veil", rgbToHex(shadowRGB), map(v, 0, 1, 0.14, 0.34));
    brush.line(x1, y, x2, y);

    // Faint warm apricot-copper underside lit from below the horizon
    if (v < 0.55 && random() < 0.65) {
      let rimWarmth = constrain(1.0 - sunDist * 0.85, 0.2, 1.0);
      let litRGB = lerpRGB(skyHere, [232, 174, 120], 0.45 * rimWarmth);
      brush.set("2H", rgbToHex(litRGB), map(v, 0, 1, 0.18, 0.32));
      brush.line(x1 + len * 0.08, y + 0.9, x2 - len * 0.08, y + 0.9);
    }
  }

  // =========================================================================
  // 4. SEA UNDERPAINTING: DEEP SLATE, PEWTER & SUBTLE COPPER GLOW
  // =========================================================================
  brush.noStroke();
  const seaBands = 56;
  const seaHeight = 1200 - HORIZON_Y;
  const seaStep = seaHeight / seaBands;

  for (let i = 0; i < seaBands; i++) {
    let u = i / (seaBands - 1);
    let y = HORIZON_Y + i * seaStep;

    // Distant horizon water is cool slate-pewter; foreground deepens to dark iron-slate
    let farSea = [44, 57, 66];
    let midSea = [35, 46, 54];
    let nearSea = [22, 31, 38];
    let seaRGB = u < 0.4
      ? lerpRGB(farSea, midSea, u / 0.4)
      : lerpRGB(midSea, nearSea, (u - 0.4) / 0.6);

    brush.wash(rgbToHex(seaRGB), 155);
    brush.rect(-20, y, 1240, seaStep + 4, "corner");

    // Subtle warm earth-copper sub-surface reflection along the sun's azimuth
    let reflWidth = 140 + u * 420;
    let copperGlow = lerpRGB(seaRGB, [96, 74, 64], 0.32 * (1 - u * 0.45));
    brush.wash(rgbToHex(copperGlow), 42);
    brush.rect(SUN_X - reflWidth * 0.5, y, reflWidth, seaStep + 3, "corner");
  }
  brush.noWash();

  // Soft volumetric swell under-modulations across the water
  for (let i = 0; i < 85; i++) {
    let u = Math.pow(random(), 1.15);
    let y = HORIZON_Y + 2 + u * (seaHeight - 4);
    let wv = evaluateWave(600, y);
    let swellCol = wv.slope > 0
      ? rgbToHex(lerpRGB([54, 66, 74], [84, 92, 96], u * 0.5))
      : rgbToHex(lerpRGB([24, 33, 40], [16, 23, 29], u * 0.7));
    brush.set("pastel_veil", swellCol, map(u, 0, 1, 0.16, 0.55));
    let xStart = random(-30, 200);
    let xEnd = random(1000, 1230);
    brush.line(xStart, y, xEnd, y);
  }

  // Fine continuous horizontal hatch base to give microscopic engraved water grain
  brush.noStroke();
  brush.hatchStyle("2H", "#394750", 0.32);
  brush.hatch(2.2, 0, { rand: 0.015 });
  brush.rect(0, HORIZON_Y + 1, 1200, seaHeight - 1, "corner");
  brush.noHatch();

  // =========================================================================
  // 5. THE RAZOR-FLAT HORIZON & THE EMERALD GREEN FLASH SLIVER
  // =========================================================================
  // Crisp distant ocean rim across the entire 1200px frame
  for (let x = 0; x < 1200; x += 24) {
    let distFromSun = Math.abs(x + 12 - SUN_X);
    let rimCol = distFromSun < 55
      ? "#4b524f"
      : (distFromSun < 180 ? "#344149" : "#26333c");
    brush.set("micro_pen", rimCol, 0.36);
    brush.line(x, HORIZON_Y, x + 25, HORIZON_Y);
  }

  // Tightly concentrated atmospheric refraction bloom around the vanishing sun
  brush.set("pastel_veil", "#f2cb8b", 0.28);
  brush.line(SUN_X - 38, HORIZON_Y - 1.5, SUN_X + 38, HORIZON_Y - 1.5);
  brush.set("atmos_spray", "#f7dca6", 0.26);
  brush.line(SUN_X - 28, HORIZON_Y - 2.0, SUN_X + 28, HORIZON_Y - 2.0);

  // Sub-millimeter golden-amber solar limb right at the water interface
  brush.set("micro_pen", "#f5ce78", 0.42);
  brush.line(SUN_X - 14, HORIZON_Y - 0.4, SUN_X + 14, HORIZON_Y - 0.4);
  brush.set("micro_pen", "#ffeaa8", 0.34);
  brush.line(SUN_X - 9, HORIZON_Y - 0.7, SUN_X + 9, HORIZON_Y - 0.7);

  // THE GREEN FLASH: minuscule, intensely saturated emerald sliver flaring above the sea
  // 1. Subtle viridian-emerald atmospheric dispersion aureole
  brush.set("pastel_veil", "#048c55", 0.22);
  brush.line(SUN_X - 16, HORIZON_Y - 2.4, SUN_X + 16, HORIZON_Y - 2.4);
  brush.set("spray", "#00b86b", 0.18);
  brush.line(SUN_X - 13, HORIZON_Y - 2.6, SUN_X + 13, HORIZON_Y - 2.6);

  // 2. Outer saturated emerald mirage spindle
  brush.set("micro_pen", "#00a85a", 0.48);
  brush.line(SUN_X - 11.5, HORIZON_Y - 1.8, SUN_X + 11.5, HORIZON_Y - 1.8);
  brush.set("micro_pen", "#00d46a", 0.46);
  brush.line(SUN_X - 10.0, HORIZON_Y - 2.3, SUN_X + 10.0, HORIZON_Y - 2.3);
  brush.set("rotring", "#05eb78", 0.42);
  brush.line(SUN_X - 8.5, HORIZON_Y - 2.8, SUN_X + 8.5, HORIZON_Y - 2.8);

  // 3. Detached mock-mirage emerald beads at the lateral tips of the sliver
  brush.set("micro_pen", "#14f584", 0.36);
  brush.line(SUN_X - 13.8, HORIZON_Y - 2.1, SUN_X - 12.0, HORIZON_Y - 2.1);
  brush.line(SUN_X + 12.0, HORIZON_Y - 2.1, SUN_X + 13.8, HORIZON_Y - 2.1);

  // 4. Incandescent emerald-chartreuse core (minuscule high-luminance heart)
  brush.set("micro_pen", "#52ffaa", 0.42);
  brush.line(SUN_X - 6.0, HORIZON_Y - 2.4, SUN_X + 6.0, HORIZON_Y - 2.4);
  brush.set("micro_pen", "#b8ffdc", 0.35);
  brush.line(SUN_X - 3.6, HORIZON_Y - 2.5, SUN_X + 3.6, HORIZON_Y - 2.5);
  brush.set("micro_pen", "#ecfff6", 0.28);
  brush.line(SUN_X - 1.6, HORIZON_Y - 2.5, SUN_X + 1.6, HORIZON_Y - 2.5);

  // =========================================================================
  // 6. THOUSANDS OF HORIZONTAL PEN TICKS IN SLATE, PEWTER & FAINT COPPER
  // =========================================================================
  const SLATE_DARKS = ["#141d24", "#1b262f", "#222f3a", "#2a3843", "#31404c"];
  const PEWTER_MIDS = ["#3d4b55", "#4a5862", "#576670", "#65737c", "#748189"];
  const PEWTER_LIGHTS = ["#818d94", "#8f9a9f", "#9da7ab", "#acb4b6", "#bac0c0"];
  const COPPER_TINTS = ["#7c645a", "#8e6f5e", "#a27b63", "#b6896a", "#c99973", "#dab084"];

  // Perspective scanline stepping from HORIZON_Y + 0.8 down to 1200
  let yCursor = HORIZON_Y + 0.8;
  while (yCursor < 1200) {
    let u = constrain((yCursor - HORIZON_Y) / seaHeight, 0.001, 1.0);
    // Perspective vertical density: ultra-tight at horizon, gradually opening toward bottom
    let dy = 0.52 + 1.55 * Math.pow(u, 0.88);

    // Number of ticks along this horizontal line
    let numTicks = Math.floor(map(Math.pow(u, 0.5), 0, 1, 28, 20) * random(0.88, 1.12));
    let cellWidth = 1200 / numTicks;

    for (let j = 0; j < numTicks; j++) {
      let xCenter = (j + random(0.08, 0.92)) * cellWidth;
      let yTick = yCursor + random(-dy * 0.35, dy * 0.35);
      if (yTick <= HORIZON_Y + 0.3 || yTick >= 1200) continue;

      let wv = evaluateWave(xCenter, yTick);
      let baseLen = map(Math.pow(u, 0.72), 0, 1, 3.2, 27.0);
      let tickLen = baseLen * random(0.55, 1.45) * (0.85 + 0.35 * Math.abs(wv.ridge));

      // Perspective stroke weight and pen choice
      let bName = "sea_pen";
      let wt = map(Math.pow(u, 0.68), 0, 1, 0.28, 0.88) * random(0.82, 1.18);
      if (u < 0.16) {
        bName = random() < 0.75 ? "micro_pen" : "rotring";
        wt = map(u, 0, 0.16, 0.24, 0.42);
      } else if (random() < 0.22) {
        bName = "rotring";
        wt *= 0.65;
      } else if (random() < 0.15) {
        bName = "2H";
        wt *= 0.75;
      }

      // Azimuthal proximity to the vanished sun's reflection corridor
      let coneSigma = 48 + u * 235 + u * u * 130;
      let dxSun = xCenter - SUN_X;
      let sunProx = Math.exp(-(dxSun * dxSun) / (coneSigma * coneSigma));

      let colHex;
      if (wv.slope < -0.16) {
        // Wave trough / forward shadow face -> deep slate & iron
        let idx = constrain(Math.floor(map(wv.slope, -0.85, -0.16, 0, SLATE_DARKS.length)), 0, SLATE_DARKS.length - 1);
        colHex = SLATE_DARKS[idx];
        wt *= 1.08;
      } else if (wv.slope < 0.20) {
        // Neutral water facet -> slate and muted pewter
        if (random() < sunProx * 0.28) {
          colHex = COPPER_TINTS[Math.floor(random(0, 3))];
        } else {
          let idx = constrain(Math.floor(map(wv.slope, -0.16, 0.20, 0, PEWTER_MIDS.length)), 0, PEWTER_MIDS.length - 1);
          colHex = PEWTER_MIDS[idx];
        }
      } else {
        // Back-tilted wave crest reflecting sky -> bright pewter or faint coppery reflection
        let copperChance = sunProx * 0.68 + (1 - u * 0.5) * 0.11;
        if (random() < copperChance) {
          let cIdx = constrain(
            Math.floor(map(wv.slope + sunProx * 0.35, 0.2, 1.1, 1, COPPER_TINTS.length)),
            0,
            COPPER_TINTS.length - 1
          );
          colHex = COPPER_TINTS[cIdx];
          tickLen *= 0.85;
        } else {
          let pIdx = constrain(
            Math.floor(map(wv.slope, 0.20, 0.85, 0, PEWTER_LIGHTS.length)),
            0,
            PEWTER_LIGHTS.length - 1
          );
          colHex = PEWTER_LIGHTS[pIdx];
        }
      }

      let x1 = xCenter - tickLen * 0.5;
      let x2 = xCenter + tickLen * 0.5;
      let tilt = random(-0.22, 0.22) * u;

      brush.set(bName, colHex, wt);
      brush.line(x1, yTick, x2, yTick + tilt);
    }

    yCursor += dy;
  }

  // =========================================================================
  // 7. SPECULAR COPPERY CREST GLINTS & SUB-HORIZON EMERALD WHISPERS
  // =========================================================================
  // Delicate coppery & burnished pewter highlights along the solar reflection column
  for (let i = 0; i < 420; i++) {
    let u = Math.pow(random(), 1.35);
    let y = HORIZON_Y + 1.2 + u * (seaHeight - 6);
    let spread = 26 + u * 210 + (random() < 0.22 ? u * 260 : 0);
    let x = SUN_X + randomGaussian() * spread * 0.55;
    if (x < 10 || x > 1190) continue;

    let wv = evaluateWave(x, y);
    if (wv.slope < 0.08 && random() < 0.75) continue;

    let len = map(Math.pow(u, 0.7), 0, 1, 2.5, 16.0) * random(0.6, 1.3);
    let isNearFlash = u < 0.095 && Math.abs(x - SUN_X) < 16 + u * 95;

    let glintCol;
    if (isNearFlash && random() < 0.42) {
      // Faint emerald-verdigris water glint directly under the green flash
      const EMERALD_REFL = ["#1e7355", "#2d916b", "#4cb086", "#78cfa8"];
      glintCol = EMERALD_REFL[Math.floor(random(EMERALD_REFL.length))];
    } else if (random() < 0.74) {
      // Warm coppery & burnished bronze wavelet reflections
      const BRIGHT_COPPER = ["#9c7663", "#b4866b", "#ca9975", "#ddb084", "#ecc696"];
      glintCol = BRIGHT_COPPER[Math.floor(random(BRIGHT_COPPER.length))];
    } else {
      // Crisp silver-pewter sky glints
      glintCol = random() < 0.5 ? "#b5bcbd" : "#cad0d0";
    }

    let bName = u < 0.25 ? "micro_pen" : "sea_pen";
    let wt = map(u, 0, 1, 0.25, 0.58) * random(0.8, 1.15);
    brush.set(bName, glintCol, wt);
    brush.line(x - len * 0.5, y, x + len * 0.5, y);
  }

  noLoop();
}

