function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0.15, closed = true) {
  if (!pts || pts.length < 2) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// 3D to 2D helper around a local base origin (bx, by)
function proj(bx, by, dx, dy, z = 0) {
  return [bx + dx, by + dy * TILT - z];
}

// Scalloped radius function for the 16-lobed Chippendale silver salver rim
function salverRadiusScale(angleDeg, lobes = 16) {
  let a = ((angleDeg % 360) + 360) % 360;
  let sector = 360 / lobes;
  let local = (a % sector) / sector; // 0..1
  // Smooth arch with subtle double-cusp shoulder at the ends
  let arch = sin(local * 180);
  let cusp = pow(sin(local * 180), 0.55) * 0.052;
  let bead = -pow(cos((local - 0.5) * 180), 4) * 0.012;
  return 0.955 + cusp + bead + 0.012 * sin(angleDeg * 3);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(20260418);
  noiseSeed(20260418);

  // Custom Velvet Chalk Mass Brush for soft confectionery blending
  brush.add("velvet_chalk", {
    type: "default",
