  });

  // Custom Fondant Glaze Brush for smooth, luminous satin transitions
  brush.add("fondant_glaze", {
    type: "marker",
    weight: 6,
    scatter: 0.12,
    opacity: 34,
    spacing: 0.2,
    pressure: [0.6, 1.15, 0.5],
    markerTip: false,
