function draw() {
  translate(-width / 2, -height / 2);
  background("#232f42");

  // 1. Atmospheric Silk Damask Table Surface
  drawTableclothBackground();

  // 2. Ornate Silver Salver (Cast Shadow, Basin, Reflections, Chippendale Rim)
  drawSilverSalver();

  // 3. Cut-Paper Lace Doily (Embossed Center, Geometric Eyelets, Picot Scallops)
  drawPaperLaceDoily();

  // 4. Define the Asymmetric C-Scroll of Petits Fours & Confectionery Elements
  const items = buildConfectioneryComposition();

  // 5. Render Multi-Layered Cast Shadows & Pastel Color Bounces on the Doily
  drawAllCastShadows(items);

  // 6. Render Lower Scattered Crumbs & Sugar Dust Underneath & Around Confections
  drawOrnamentalCrumbsAndSugar(false);

  // 7. Render All Petits Fours, Sugared Violets & Standalone Scrolls (Sorted Back-to-Front)
  items.sort((a, b) => a.sortY - b.sortY);
  for (let item of items) {
    if (item.kind === "petit_four") {
      drawPetitFour(item);
    } else if (item.kind === "cut_petit_four") {
      drawCutPetitFour(item);
    } else if (item.kind === "standalone_scroll") {
      drawStandaloneButtercreamScroll(item);
    } else if (item.kind === "violet_cluster") {
      drawSugarVioletCluster(item);
    }
  }

  // 8. Foreground Ornamental Crumbs, Fallen Petals, Silver Dragees & Crisp Pencil Cuts
  drawOrnamentalCrumbsAndSugar(true);
  drawFinalSpecularAndPencilPolish();

  resetBrush();
  noLoop();
}

// ============================================================================
// STAGE 1: ATMOSPHERIC TABLECLOTH SURFACE
// ============================================================================
function drawTableclothBackground() {
  resetBrush();

  // Rich deep Wedgewood-slate & plum-indigo watercolor washes
  const corners = [
    { x: 180, y: 160, r: 380, col: "#3d516b", op: 95 },
    { x: 1020, y: 180, r: 420, col: "#243247", op: 110 },
    { x: 160, y: 1020, r: 440, col: "#1b2536", op: 130 },
    { x: 1040, y: 1040, r: 480, col: "#141c29", op: 150 },
    { x: 350, y: 320, r: 460, col: "#526885", op: 70 }
  ];

  for (let c of corners) {
    resetBrush();
    brush.fill(c.col, c.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.55, 0.3);
    brush.circle(c.x, c.y, c.r, 0.35);
  }

  // Fine woven linen damask cross-hatching in the exposed corners
  resetBrush();
  brush.set("2H", "#161f2e", 0.45);
  for (let i = 0; i < 140; i++) {
    let x = random(0, 1200);
    let y = random(0, 1200);
    // Only draw outside the inner tray area to save render budget
    let dx = (x - TRAY_X) / 480;
    let dy = (y - TRAY_Y) / (480 * TILT);
    if (dx * dx + dy * dy > 0.85) {
      let len = random(45, 110);
      brush.set("2H", i % 2 === 0 ? "#182232" : "#4f6682", 0.38);
      brush.line(x - len / 2, y - len * 0.15, x + len / 2, y + len * 0.15);
      brush.line(x - len * 0.15, y - len / 2, x + len * 0.15, y + len / 2);
    }
  }

  // Subtle damask floral scroll hints in top-left and bottom-left corners
  resetBrush();
  brush.set("cpencil", "#5a7291", 0.55);
  for (let a = 0; a < 300; a += 18) {
    let r = 45 + a * 0.22;
    let x1 = 115 + cos(a) * r;
    let y1 = 110 + sin(a) * r * TILT;
    let x2 = 115 + cos(a + 14) * (r + 3);
    let y2 = 110 + sin(a + 14) * (r + 3) * TILT;
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// STAGE 2: THE SILVER SALVER (GADROONED CHIPPENDALE PIE-CRUST RIM & BASIN)
// ============================================================================
function drawSilverSalver() {
  const rxOut = 548;
  const ryOut = rxOut * TILT;
  const rxMid = 482;
  const ryMid = rxMid * TILT;
  const rxBasin = 446;
  const ryBasin = rxBasin * TILT;

  // 2.1 Deep Cast Shadow of the Salver onto the Tablecloth (shifted bottom-right)
  for (let pass = 0; pass < 4; pass++) {
    let offX = 16 + pass * 9;
    let offY = 20 + pass * 10;
    let pts = [];
    for (let a = 0; a < 360; a += 5) {
      let s = salverRadiusScale(a) * (1.0 + pass * 0.012);
      pts.push([
        TRAY_X + offX + cos(a) * rxOut * s,
        TRAY_Y + offY + sin(a) * ryOut * s
      ]);
    }
    resetBrush();
    brush.wash(pass < 2 ? "#0d131d" : "#162030", 115 - pass * 22);
    drawPoly(pts, 0.2, true);
  }

  // Soft charcoal feathering along the shadow edge
  resetBrush();
  for (let a = -25; a <= 165; a += 3) {
    let s = salverRadiusScale(a);
    let sx = TRAY_X + 26 + cos(a) * rxOut * s;
    let sy = TRAY_Y + 30 + sin(a) * ryOut * s;
    brush.set("charcoal", "#0b1018", 1.3);
    brush.line(sx, sy, sx + cos(a) * 18, sy + sin(a) * 15);
  }

  // 2.2 Outer Silver Rim Base Fill
  let outerPts = [];
  for (let a = 0; a < 360; a += 3) {
    let s = salverRadiusScale(a);
    outerPts.push([
      TRAY_X + cos(a) * rxOut * s,
      TRAY_Y + sin(a) * ryOut * s
    ]);
  }
  resetBrush();
  brush.wash("#7c91a8", 245);
  drawPoly(outerPts, 0.15, true);

  // 2.3 High-Contrast Metallic Specular Wedges around the Scalloped Rim
  // Silver reflects alternating bands of dark slate, bright gleam, and warm pastel bounce
  for (let a = 0; a < 360; a += 2) {
    let s1 = salverRadiusScale(a);
    let s2 = salverRadiusScale(a + 2.2);
    let rIn = 0.805;

    // Metallic reflection wave function
    let wave = sin(a * 4 + 35) * 0.5 + cos(a * 2 - 50) * 0.5;
    let lightBias = cos(a + 130); // Upper-left main light source
    let val = wave * 0.65 + lightBias * 0.55;

    let col = PALETTE.silverMid;
    let weight = 1.6;
    if (val > 0.62) {
      col = PALETTE.silverWhite;
      weight = 2.0;
    } else if (val > 0.25) {
      col = PALETTE.silverGleam;
      weight = 1.7;
    } else if (val > -0.15) {
      col = PALETTE.silverBright;
    } else if (val > -0.5) {
      col = PALETTE.silverSlate;
    } else {
      col = PALETTE.silverDark;
      weight = 1.8;
    }

    // Add warm confectionery bounce reflections on the rim
    if (a > 120 && a < 260 && abs(sin(a * 7)) > 0.72) {
      col = a < 190 ? "#f2cadc" : "#d8ebd9";
    } else if ((a < 60 || a > 300) && abs(cos(a * 6)) > 0.75) {
      col = "#e6d8f7";
    }

    let xOut = TRAY_X + cos(a) * rxOut * s1;
    let yOut = TRAY_Y + sin(a) * ryOut * s1;
    let xIn = TRAY_X + cos(a) * rxOut * s1 * rIn;
    let yIn = TRAY_Y + sin(a) * ryOut * s1 * rIn;

    resetBrush();
    brush.set("fondant_glaze", col, weight);
    brush.line(xIn, yIn, xOut, yOut);

    // Crisp radial chasing / burnishing lines in 2H pencil
    if (a % 4 === 0) {
      brush.set("2H", val > 0.2 ? "#ffffff" : "#1d2736", 0.5);
      brush.line(
        TRAY_X + cos(a + 0.5) * rxOut * s2 * (rIn + 0.02),
        TRAY_Y + sin(a + 0.5) * ryOut * s2 * (rIn + 0.02),
        xOut,
        yOut
      );
    }
  }

  // 2.4 Recessed Silver Basin (Mirror-Polished Center)
  let basinPts = [];
  for (let a = 0; a < 360; a += 5) {
    basinPts.push([
      TRAY_X + cos(a) * rxBasin,
      TRAY_Y + sin(a) * ryBasin
    ]);
  }
  resetBrush();
  brush.wash("#3e4f63", 235);
  drawPoly(basinPts, 0.2, true);

  // Diagonal mirror-sheen streaks across the visible silver basin
  for (let i = -380; i <= 380; i += 9) {
    let t = i / 380;
    let halfChord = sqrt(max(0, 1 - t * t)) * rxBasin * 0.96;
    let cx = TRAY_X + i * 0.45;
    let cy = TRAY_Y + i * 0.65 * TILT;

    let sheen = sin(t * 540 + 40) + cos(t * 260 - 20) * 0.6;
    let sCol = sheen > 0.7 ? "#eef6ff" : sheen > 0.1 ? "#8ea4bd" : sheen > -0.45 ? "#4a5d73" : "#222e3d";
    resetBrush();
    brush.set("velvet_chalk", sCol, 1.4);
    brush.line(
      cx - halfChord * 0.7,
      cy - halfChord * 0.45 * TILT,
      cx + halfChord * 0.7,
      cy + halfChord * 0.45 * TILT
    );
  }

  // 2.5 Gadrooned & Molded Concentric Rim Contours (Chippendale Pie-Crust Edge)
  const rimRings = [
    { scale: 1.0, colHi: "#ffffff", colDark: "#121a24", w: 1.1 },
    { scale: 0.984, colHi: "#1b2533", colDark: "#e3eef8", w: 0.85 },
    { scale: 0.966, colHi: "#ffffff", colDark: "#2d3c4f", w: 0.95 },
    { scale: 0.946, colHi: "#37485e", colDark: "#cfddev", w: 0.65 },
    { scale: 0.848, colHi: "#141d29", colDark: "#ffffff", w: 1.0 },
    { scale: 0.832, colHi: "#ffffff", colDark: "#1e2938", w: 0.85 }
  ];

  for (let ring of rimRings) {
    for (let a = 0; a < 360; a += 4) {
      let sA = ring.scale > 0.9 ? salverRadiusScale(a) * ring.scale : ring.scale * 0.97;
      let sB = ring.scale > 0.9 ? salverRadiusScale(a + 4) * ring.scale : ring.scale * 0.97;
      let x1 = TRAY_X + cos(a) * rxOut * sA;
      let y1 = TRAY_Y + sin(a) * ryOut * sA;
      let x2 = TRAY_X + cos(a + 4) * rxOut * sB;
      let y2 = TRAY_Y + sin(a + 4) * ryOut * sB;

      let lit = cos(a + 135) + sin(a * 8) * 0.35;
      let strokeCol = lit > 0.15 ? ring.colHi : ring.colDark === "#cfddev" ? "#c8d8e8" : ring.colDark;
      resetBrush();
      brush.set("2H", strokeCol, ring.w);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Engraved Rococo C-scroll cartouches at each of the 16 scallop cusps
  for (let k = 0; k < 16; k++) {
    let cuspA = k * 22.5;
    let midA = cuspA + 11.25;
    let sCusp = salverRadiusScale(cuspA) * 0.93;
    let cx = TRAY_X + cos(cuspA) * rxOut * sCusp;
    let cy = TRAY_Y + sin(cuspA) * ryOut * sCusp;

    // Tiny raised silver shell / cartouche at each cusp
    resetBrush();
    brush.set("2H", "#161f2b", 0.75);
    brush.circle(cx, cy, 6.5, 0.15);
    brush.set("2H", "#ffffff", 0.9);
    brush.arc(cx - 1.5, cy - 1.5, 6, cuspA - 90, cuspA + 90);

    // Finely chased inner swag on the silver cavetto border
    let sx1 = TRAY_X + cos(cuspA + 3) * rxMid * 0.95;
    let sy1 = TRAY_Y + sin(cuspA + 3) * ryMid * 0.95;
    let sxm = TRAY_X + cos(midA) * rxMid * 0.92;
    let sym = TRAY_Y + sin(midA) * ryMid * 0.92;
    let sx2 = TRAY_X + cos(cuspA + 19.5) * rxMid * 0.95;
    let sy2 = TRAY_Y + sin(cuspA + 19.5) * ryMid * 0.95;

    brush.set("2H", "#2a384b", 0.5);
    brush.spline([[sx1, sy1], [sxm, sym], [sx2, sy2]], 0.5);
    brush.set("2H", "#ffffff", 0.5);
    brush.spline([[sx1 - 1, sy1 - 1], [sxm - 1, sym - 1], [sx2 - 1, sy2 - 1]], 0.5);
  }
}

// ============================================================================
// STAGE 3: THE CUT-PAPER LACE DOILY (DENTELLE DE PAPIER)
// ============================================================================
function drawPaperLaceDoily() {
  const rxDoily = 412;
  const ryDoily = rxDoily * TILT;
  const scallops = 72;

  // 3.1 Crisp Cast Shadow of the Doily's Ruffled Picot Edge onto the Silver Basin
  let shadowPts = [];
  for (let i = 0; i < scallops * 4; i++) {
    let a = (i / (scallops * 4)) * 360;
    let wave = abs(sin(a * (scallops / 2))) * 0.028;
    let r = 0.975 + wave;
    shadowPts.push([
      TRAY_X + 4.5 + cos(a) * rxDoily * r,
      TRAY_Y + 5.5 + sin(a) * ryDoily * r
    ]);
  }
  resetBrush();
  brush.wash("#1b2533", 165);
  drawPoly(shadowPts, 0.1, true);

  // 3.2 Warm Cream-White Paper Base of the Doily
  let basePts = [];
  for (let i = 0; i < scallops * 4; i++) {
    let a = (i / (scallops * 4)) * 360;
    let wave = abs(sin(a * (scallops / 2))) * 0.028;
    let r = 0.975 + wave;
    basePts.push([
      TRAY_X + cos(a) * rxDoily * r,
      TRAY_Y + sin(a) * ryDoily * r
    ]);
  }
  resetBrush();
  brush.wash(PALETTE.doilyCream, 250);
  drawPoly(basePts, 0.1, true);

  // Chalky paper texture over the doily
  let innerPaperPts = [];
  for (let a = 0; a < 360; a += 8) {
    innerPaperPts.push([
      TRAY_X + cos(a) * rxDoily * 0.92,
      TRAY_Y + sin(a) * ryDoily * 0.92
    ]);
  }
  resetBrush();
  brush.mass("pastel", PALETTE.doilyWhite, {
    precision: 0.85,
    strength: 0.55,
    gradient: 0.2,
    outline: false
  });
  drawPoly(innerPaperPts, 0.2, true);
  resetBrush();

  // 3.3 Die-Cut Lace Perforation Rings (Revealing Dark Gleaming Silver Beneath!)
  // Ring A: Outer Picot Eyelets (72 teardrop/oval cutouts at r = 0.945)
  for (let i = 0; i < scallops; i++) {
    let a = (i + 0.5) * (360 / scallops);
    let ex = TRAY_X + cos(a) * rxDoily * 0.945;
    let ey = TRAY_Y + sin(a) * ryDoily * 0.945;

    // Silver showing through the hole
    let silverTone = sin(a * 4 + 30) > 0.2 ? "#697e96" : "#273445";
    resetBrush();
    brush.set("marker", silverTone, 1.15);
    brush.line(ex - cos(a) * 3.5, ey - sin(a) * 3.5 * TILT, ex + cos(a) * 3.5, ey + sin(a) * 3.5 * TILT);

    // Paper thickness micro-shadow (top-left) & highlight (bottom-right)
    brush.set("2H", PALETTE.doilyDeep, 0.45);
    brush.arc(ex, ey, 4.5, 130, 310);
    brush.set("2H", "#ffffff", 0.55);
    brush.arc(ex, ey, 4.5, -50, 130);
  }

  // Ring B: Diamond Latticework Cutouts (72 diamonds at r = 0.885 & r = 0.835)
  const latticeRadii = [0.89, 0.84, 0.785];
  for (let rIdx = 0; rIdx < latticeRadii.length; rIdx++) {
    let rNorm = latticeRadii[rIdx];
    let count = 72;
    for (let i = 0; i < count; i++) {
      let a = (i + (rIdx % 2) * 0.5) * (360 / count);
      let nextA = a + 360 / count;

      let cx = TRAY_X + cos(a) * rxDoily * rNorm;
      let cy = TRAY_Y + sin(a) * ryDoily * rNorm;

      // Underlying silver tone
      let sVal = sin(a * 3 - 20) + cos(a * 5);
      let holeCol = sVal > 0.6 ? "#8aa0b8" : sVal > -0.3 ? "#43556b" : "#1f2a38";

      let radSpan = 6.5 - rIdx * 0.8;
      let tanSpan = 5.5 - rIdx * 0.6;
      let tx = -sin(a) * tanSpan;
      let ty = cos(a) * tanSpan * TILT;
      let rx = cos(a) * radSpan;
      let ry = sin(a) * radSpan * TILT;

      let dPts = [
        [cx + rx, cy + ry],
        [cx + tx, cy + ty],
        [cx - rx, cy - ry],
        [cx - tx, cy - ty]
      ];

      resetBrush();
      brush.wash(holeCol, 225);
      drawPoly(dPts, 0.05, true);

      // Crisp die-cut paper edge
      resetBrush();
      brush.set("2H", PALETTE.doilyDeep, 0.42);
      brush.line(dPts[2][0], dPts[2][1], dPts[3][0], dPts[3][1]);
      brush.line(dPts[3][0], dPts[3][1], dPts[0][0], dPts[0][1]);
      brush.set("2H", "#ffffff", 0.55);
      brush.line(dPts[0][0], dPts[0][1], dPts[1][0], dPts[1][1]);
      brush.line(dPts[1][0], dPts[1][1], dPts[2][0], dPts[2][1]);
    }
  }

  // Ring C: Inner Floral Medallion & Wheel Cutouts at r = 0.725
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let mx = TRAY_X + cos(a) * rxDoily * 0.725;
    let my = TRAY_Y + sin(a) * ryDoily * 0.725;

    // 4-petal rosette cutout in the lace
    for (let p = 0; p < 4; p++) {
      let pa = a + p * 90 + 45;
      let px = mx + cos(pa) * 6.5;
      let py = my + sin(pa) * 6.5 * TILT;
      resetBrush();
      brush.set("marker", "#314054", 0.95);
      brush.line(mx, my, px, py);
      brush.set("2H", "#ffffff", 0.48);
      brush.arc(px, py, 3.8, -45, 135);
    }
    resetBrush();
    brush.set("2H", PALETTE.doilyShadow, 0.5);
    brush.circle(mx, my, 10.5, 0.1);
    brush.set("2H", "#ffffff", 0.65);
    brush.arc(mx, my, 11.2, -50, 140);
  }

  // Ring D: Fine Pin-Prick Eyelet Band at r = 0.655
  for (let i = 0; i < 108; i++) {
    let a = i * (360 / 108);
    let px = TRAY_X + cos(a) * rxDoily * 0.655;
    let py = TRAY_Y + sin(a) * ryDoily * 0.655;
    resetBrush();
    brush.set("rotring", "#2b384a", 0.85);
    brush.line(px, py, px + 0.8, py + 0.8);
    brush.set("2H", "#ffffff", 0.5);
    brush.line(px + 1.2, py + 1.2, px + 2.4, py + 2.0);
  }

  // 3.4 Embossed Paper Relief Lines in the Solid Center of the Doily (Visible in the C-Scroll Hollow)
  const embossRings = [0.63, 0.615, 0.48, 0.465, 0.28];
  for (let er of embossRings) {
    for (let a = 0; a < 360; a += 6) {
      let x1 = TRAY_X + cos(a) * rxDoily * er;
      let y1 = TRAY_Y + sin(a) * ryDoily * er;
      let x2 = TRAY_X + cos(a + 5) * rxDoily * er;
      let y2 = TRAY_Y + sin(a + 5) * ryDoily * er;
      resetBrush();
      brush.set("2H", PALETTE.doilyShadow, 0.42);
      brush.line(x1, y1, x2, y2);
      brush.set("2H", "#ffffff", 0.6);
      brush.line(x1 + 1.2, y1 + 1.2, x2 + 1.2, y2 + 1.2);
    }
  }

  // Delicate embossed floral garlands in the exposed center-right hollow of the doily
  for (let i = 0; i < 24; i++) {
    let a1 = i * 15;
    let aMid = a1 + 7.5;
    let a2 = a1 + 15;
    let sx1 = TRAY_X + cos(a1) * rxDoily * 0.58;
    let sy1 = TRAY_Y + sin(a1) * ryDoily * 0.58;
    let sxm = TRAY_X + cos(aMid) * rxDoily * 0.52;
    let sym = TRAY_Y + sin(aMid) * ryDoily * 0.52;
    let sx2 = TRAY_X + cos(a2) * rxDoily * 0.58;
    let sy2 = TRAY_Y + sin(a2) * ryDoily * 0.58;

    resetBrush();
    brush.set("2H", "#cbc2d6", 0.45);
    brush.spline([[sx1, sy1], [sxm, sym], [sx2, sy2]], 0.55);
    brush.set("2H", "#ffffff", 0.65);
    brush.spline([[sx1 + 1.3, sy1 + 1.3], [sxm + 1.3, sym + 1.3], [sx2 + 1.3, sy2 + 1.3]], 0.55);
  }

  // 3.5 Outer Ruffled Picot Scallop Rim Pencil Cut
  for (let i = 0; i < scallops * 3; i++) {
    let a1 = (i / (scallops * 3)) * 360;
    let a2 = ((i + 1) / (scallops * 3)) * 360;
    let r1 = 0.975 + abs(sin(a1 * (scallops / 2))) * 0.028;
    let r2 = 0.975 + abs(sin(a2 * (scallops / 2))) * 0.028;
    let x1 = TRAY_X + cos(a1) * rxDoily * r1;
    let y1 = TRAY_Y + sin(a1) * ryDoily * r1;
    let x2 = TRAY_X + cos(a2) * rxDoily * r2;
    let y2 = TRAY_Y + sin(a2) * ryDoily * r2;

    resetBrush();
    brush.set("2H", "#736982", 0.5);
    brush.line(x1 + 1.2, y1 + 1.5, x2 + 1.2, y2 + 1.5);
    brush.set("2H", "#ffffff", 0.75);
    brush.line(x1, y1, x2, y2);
  }
}

