// ============================================================================
// STAGE 5: MULTI-LAYERED CAST SHADOWS & SUBSURFACE BOUNCE ON THE DOILY
// ============================================================================
function drawAllCastShadows(items) {
  for (let item of items) {
    if (item.kind === "petit_four" || item.kind === "cut_petit_four") {
      let bx = item.bx;
      let by = item.by;
      let rx = item.rx;
      let ry = item.ry * TILT;

      // Soft outer penumbra
      resetBrush();
      brush.fill("#9c90ab", 75);
      brush.fillBleed(0.4, "out");
      brush.circle(bx + 26, by + 20, rx * 1.08, 0.25);

      // Pastel subsurface color bounce in the shadow
      resetBrush();
      brush.fill(item.glaze.shadow, 52);
      brush.fillBleed(0.35, "out");
      brush.circle(bx + 20, by + 16, rx * 0.95, 0.22);

      // Tight dark ambient occlusion directly under the base
      let aoPts = [];
      for (let a = 0; a < 360; a += 15) {
        aoPts.push([
          bx + 8 + cos(a) * rx * 0.92,
          by + 7 + sin(a) * ry * 0.92
        ]);
      }
      resetBrush();
      brush.wash("#352a40", 155);
      drawPoly(aoPts, 0.2, true);
    } else if (item.kind === "violet_cluster" && item.onDoily) {
      resetBrush();
      brush.wash("#533d6b", 125);
      brush.circle(item.bx + 7, item.by + 6, 16 * item.scale, 0.25);
    } else if (item.kind === "standalone_scroll") {
      resetBrush();
      brush.wash("#756885", 110);
      brush.circle(item.bx + 8, item.by + 7, 18, 0.3);
    }
  }
}

// ============================================================================
// STAGE 6: RENDERING PETITS FOURS (CUBE, DIAMOND, CYLINDER, BOMBE)
// ============================================================================
function drawPetitFour(pf) {
  const { bx, by, shape, glaze, rx, ry, h, rot, topStyle, swagStyle, cup } = pf;

  // Optional fluted paper or gold-foil petit-four cup at the base
  if (cup) {
    drawFlutedPaperCup(bx, by, rx * 1.08, ry * 1.08);
  } else {
    // Toasted golden sponge / frangipane crumb base peeking under the fondant
    drawSpongeBaseRim(bx, by, rx, ry, shape, rot);
  }

  // Render the 3D Chalky Pastel Body + Glossy Fondant Glaze
  if (shape === "cube" || shape === "diamond") {
    drawPolygonalPetitFourBody(pf);
  } else if (shape === "cylinder") {
    drawCylindricalPetitFourBody(pf);
  } else if (shape === "bombe") {
    drawBombePetitFourBody(pf);
  }

  // Render Piped Buttercream Side Swags / Collars
  drawPetitFourSidePiping(pf);

  // Render Top Crown (Buttercream Scrolls, Star-Tip Rosettes, Sugared Violets, Gold Leaf)
  drawPetitFourTopCrown(pf);
}

function drawFlutedPaperCup(bx, by, rx, ry) {
  const flutes = 28;
  // Back rim unnecessary, draw visible front flutes from angle -15 to 195
  for (let i = 0; i < flutes; i++) {
    let a1 = -15 + (i / flutes) * 210;
    let a2 = -15 + ((i + 1) / flutes) * 210;
    let am = (a1 + a2) * 0.5;

    let b1 = proj(bx, by, cos(a1) * rx * 0.92, sin(a1) * ry * 0.92, 0);
    let b2 = proj(bx, by, cos(a2) * rx * 0.92, sin(a2) * ry * 0.92, 0);
    let t1 = proj(bx, by, cos(a1) * rx * 1.07, sin(a1) * ry * 1.07, 18);
    let tm = proj(bx, by, cos(am) * rx * 1.12, sin(am) * ry * 1.12, 21);
    let t2 = proj(bx, by, cos(a2) * rx * 1.07, sin(a2) * ry * 1.07, 18);

    let lit = cos(am - 135);
    let col = lit > 0.2 ? "#fffdf7" : lit > -0.3 ? "#e8decb" : "#b8ab96";

    resetBrush();
    brush.wash(col, 235);
    drawPoly([b1, t1, tm, t2, b2], 0.05, true);

    // Crisp pencil-cut pleat crease
    resetBrush();
    brush.set("2H", i % 2 === 0 ? "#857765" : "#ffffff", 0.55);
    brush.line(b1[0], b1[1], t1[0], t1[1]);
    brush.set("2H", "#ffffff", 0.65);
    brush.line(t1[0], t1[1], tm[0], tm[1]);
  }
}

function drawSpongeBaseRim(bx, by, rx, ry, shape, rot) {
  for (let a = -10; a <= 190; a += 8) {
    let rScale = (shape === "cube" || shape === "diamond") ? 0.95 : 0.98;
    let p = proj(bx, by, cos(a) * rx * rScale, sin(a) * ry * rScale, random(1, 5));
    resetBrush();
    brush.set("cpencil", random() > 0.4 ? PALETTE.spongeMid : PALETTE.spongeDark, 0.95);
    brush.circle(p[0], p[1], random(1.8, 3.8), 0.35);
  }
}

// ============================================================================
// POLYGONAL PETIT FOUR (CUBE & DIAMOND LOZENGE WITH POURED FONDANT DRIPS)
// ============================================================================
function drawPolygonalPetitFourBody(pf) {
  const { bx, by, shape, glaze, rx, ry, h, rot } = pf;

  // Define 4 corner angles in tray plane
  let baseAngles = shape === "diamond"
    ? [rot, rot + 74, rot + 180, rot + 254]
    : [rot, rot + 90, rot + 180, rot + 270];

  let rCorner = shape === "diamond" ? rx * 1.14 : rx * 1.08;

  // Compute bottom & top corner 3D points
  let corners = baseAngles.map((ang) => {
    let a = ((ang % 360) + 360) % 360;
    return {
      ang: a,
      dx: cos(a) * rCorner,
      dy: sin(a) * rCorner,
      bot: proj(bx, by, cos(a) * rCorner, sin(a) * rCorner, 2),
      top: proj(bx, by, cos(a) * rCorner * 0.94, sin(a) * rCorner * 0.94, h)
    };
  });

  // Identify front-facing edges (where average y in screen space faces viewer)
  let faces = [];
  for (let i = 0; i < 4; i++) {
    let c1 = corners[i];
    let c2 = corners[(i + 1) % 4];
    // Outward normal angle
    let midDx = (c1.dx + c2.dx) * 0.5;
    let midDy = (c1.dy + c2.dy) * 0.5;
    let normAng = atan2(midDy, midDx);
    // Visible if normal points generally downward-left or downward-right (sin(normAng) > -0.25)
    if (sin(normAng) > -0.2) {
      faces.push({ c1, c2, normAng, midY: (c1.bot[1] + c2.bot[1]) * 0.5 });
    }
  }
  faces.sort((a, b) => a.midY - b.midY);

  // Render each visible vertical side face with velvety chalk mass + poured fondant drips
  for (let f of faces) {
    let { c1, c2, normAng } = f;
    // Light comes from upper-left (-135 deg). Left-facing sides are brighter than right-facing sides.
    let isLeftFace = cos(normAng) < 0;
    let faceCol = isLeftFace ? glaze.mid : glaze.shadow;
    let deepCol = isLeftFace ? glaze.vivid : glaze.deep;

    // Build polygon with organic poured-fondant drips along the bottom edge
    let sidePts = [];
    // Top edge (slightly arched from poured fondant tension)
    for (let t = 0; t <= 1; t += 0.2) {
      let tx = lerp(c1.top[0], c2.top[0], t);
      let ty = lerp(c1.top[1], c2.top[1], t) - sin(t * 180) * 2.5;
      sidePts.push([tx, ty]);
    }
    // Right vertical edge
    sidePts.push([c2.bot[0], c2.bot[1] - 2]);
    // Bottom wavy fondant drip curtain (from c2.bot back to c1.bot)
    let steps = 10;
    for (let s = 1; s <= steps; s++) {
      let t = s / steps;
      let bxEdge = lerp(c2.bot[0], c1.bot[0], t);
      let byEdge = lerp(c2.bot[1], c1.bot[1], t);
      let drip = sin(t * 540 + bx * 0.5) * 2.8 + (s % 3 === 0 ? 2.2 : 0);
      sidePts.push([bxEdge, byEdge + drip]);
    }

    // 1. Opaque base wash
    resetBrush();
    brush.wash(faceCol, 245);
    drawPoly(sidePts, 0.12, true);

    // 2. Velvety chalk mass for soft pastel richness
    resetBrush();
    brush.mass("pastel", isLeftFace ? glaze.light : glaze.vivid, {
      precision: 0.78,
      strength: 0.65,
      gradient: 0.45,
      outline: false
    });
    drawPoly(sidePts, 0.12, true);

    // 3. Saturated core shadow gradient & warm doily reflected bounce at bottom edge
    for (let v = 0; v <= 1; v += 0.08) {
      let pA = [
        lerp(c1.top[0], c1.bot[0], v),
        lerp(c1.top[1], c1.bot[1], v)
      ];
      let pB = [
        lerp(c2.top[0], c2.bot[0], v),
        lerp(c2.top[1], c2.bot[1], v)
      ];
      let strokeCol = v < 0.25 ? glaze.light : v < 0.78 ? deepCol : glaze.bounce;
      resetBrush();
      brush.set("velvet_chalk", strokeCol, 1.25);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    // 4. Fine colored pencil vertical hatching for velvety surface grain
    resetBrush();
    brush.set("cpencil", glaze.pencil, 0.48);
    for (let u = 0.08; u < 0.95; u += 0.09) {
      let topP = [lerp(c1.top[0], c2.top[0], u), lerp(c1.top[1], c2.top[1], u)];
      let botP = [lerp(c1.bot[0], c2.bot[0], u), lerp(c1.bot[1], c2.bot[1], u)];
      brush.line(topP[0], topP[1] + 4, botP[0], botP[1] - 3);
    }

    // 5. Crisp 2H pencil cutting the bottom fondant drip edge
    resetBrush();
    brush.set("2H", glaze.deep, 0.65);
    let dripLine = sidePts.slice(6);
    brush.spline(dripLine, 0.4);
  }

  // Render Top Face (Softly Domed Poured Fondant Crown)
  let topPts = [];
  for (let i = 0; i < 4; i++) {
    let cA = corners[i].top;
    let cB = corners[(i + 1) % 4].top;
    for (let t = 0.1; t <= 0.9; t += 0.2) {
      let px = lerp(cA[0], cB[0], t);
      let py = lerp(cA[1], cB[1], t);
      // Slight outward & upward pillow dome
      let centerTop = proj(bx, by, 0, 0, h + 5);
      px = lerp(px, centerTop[0], -0.05);
      py = lerp(py, centerTop[1], 0.08) - sin(t * 180) * 2.2;
      topPts.push([px, py]);
    }
  }

  // 1. Base wash of vivid pastel
  resetBrush();
  brush.wash(glaze.mid, 248);
  drawPoly(topPts, 0.25, true);

  // 2. Velvety pastel mass on top face
  resetBrush();
  brush.mass("pastel", glaze.light, {
    precision: 0.82,
    strength: 0.72,
    gradient: 0.5,
    outline: false
  });
  drawPoly(topPts, 0.25, true);

  // 3. Soft chalky blending from upper-left highlight to lower-right vivid saturation
  let topCenter = proj(bx, by, 0, 0, h + 4);
  for (let r = 0.85; r >= 0.15; r -= 0.14) {
    let ringCol = r > 0.55 ? glaze.mid : r > 0.3 ? glaze.light : glaze.hi;
    let shiftX = - (1 - r) * 10;
    let shiftY = - (1 - r) * 8;
    let subPts = topPts.map((pt) => [
      lerp(topCenter[0] + shiftX, pt[0], r),
      lerp(topCenter[1] + shiftY, pt[1], r)
    ]);
    resetBrush();
    brush.fill(ringCol, 85);
    brush.fillBleed(0.2, "in");
    drawPoly(subPts, 0.25, true);
  }

  // 4. Glossy Fondant Specular Reflection along the Rounded Upper-Left Bevel & Crown!
  // Find the corner closest to top-left and trace the wet specular highlight ribbon
  let ulPt = proj(bx, by, -rx * 0.62, -ry * 0.62, h + 3);
  let urPt = proj(bx, by, rx * 0.25, -ry * 0.72, h + 3);
  let dlPt = proj(bx, by, -rx * 0.72, ry * 0.25, h + 2);
  let frontCorner = corners.reduce((a, b) => (a.top[1] > b.top[1] ? a : b)).top;

  resetBrush();
  brush.set("fondant_glaze", glaze.hi, 2.2);
  brush.spline([dlPt, ulPt, urPt], 0.5);
  brush.set("pastel", "#ffffff", 1.5);
  brush.spline([dlPt, ulPt, urPt], 0.5);

  // Front bevel specular ridge catching studio window light
  let midFrontL = [lerp(dlPt[0], frontCorner[0], 0.5), lerp(dlPt[1], frontCorner[1], 0.5) - 2];
  brush.set("fondant_glaze", glaze.hi, 1.8);
  brush.spline([dlPt, midFrontL, [frontCorner[0] + 6, frontCorner[1] - 1]], 0.45);
  brush.set("2H", "#ffffff", 0.95);
  brush.spline([dlPt, midFrontL, [frontCorner[0] + 6, frontCorner[1] - 1]], 0.45);

  // Fine pencil cutting the glossy reflection window edge
  brush.set("2H", glaze.vivid, 0.52);
  brush.spline([
    [dlPt[0] + 3, dlPt[1] + 2],
    [ulPt[0] + 3, ulPt[1] + 3],
    [urPt[0] + 2, urPt[1] + 3]
  ], 0.5);
}

// ============================================================================
// CYLINDRICAL PETIT FOUR (ROUND LAYERED CAKE WITH DOMED FONDANT CAP)
// ============================================================================
function drawCylindricalPetitFourBody(pf) {
  const { bx, by, glaze, rx, ry, h } = pf;

  // Build cylinder silhouette
  let cylPts = [];
  // Top elliptical arch (back half)
  for (let a = 180; a <= 360; a += 10) {
    cylPts.push(proj(bx, by, cos(a) * rx * 0.96, sin(a) * ry * 0.96, h + sin(a - 180) * 3));
  }
  // Right vertical wall down to base
  cylPts.push(proj(bx, by, rx, 0, 4));
  // Bottom wavy fondant drip edge (front half)
  for (let a = 0; a <= 180; a += 8) {
    let drip = sin(a * 7 + bx) * 2.4 + (a % 24 === 0 ? 2.0 : 0);
    let p = proj(bx, by, cos(a) * rx, sin(a) * ry, 2 - drip);
    cylPts.push(p);
  }
  // Left vertical wall up
  cylPts.push(proj(bx, by, -rx, 0, h * 0.8));

  // 1. Base wash
  resetBrush();
  brush.wash(glaze.mid, 248);
  drawPoly(cylPts, 0.15, true);

  // 2. Vertical cylinder shading strips (from left highlight -> vivid mid -> right core shadow -> right rim bounce)
  for (let a = 180; a >= 0; a -= 4) {
    let normX = -cos(a); // -1 at right (0 deg), +1 at left (180 deg)
    let col;
    if (normX > 0.65) col = glaze.light;
    else if (normX > 0.35) col = glaze.hi; // Specular vertical band on front-left!
    else if (normX > -0.1) col = glaze.mid;
    else if (normX > -0.55) col = glaze.vivid;
    else if (normX > -0.85) col = glaze.shadow;
    else col = glaze.bounce; // Reflected light from white lace doily on far right edge

    let pTop = proj(bx, by, cos(a) * rx * 0.97, sin(a) * ry * 0.97, h - 2);
    let pBot = proj(bx, by, cos(a) * rx, sin(a) * ry, 3);

    resetBrush();
    brush.set("velvet_chalk", col, 1.5);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);

    // Fine pencil vertical modeling strokes
    if (a % 12 === 0) {
      brush.set("cpencil", normX > 0.2 ? glaze.light : glaze.pencil, 0.45);
      brush.line(pTop[0], pTop[1] + 3, pBot[0], pBot[1] - 3);
    }
  }

  // 3. Domed Top Cap of the Cylinder
  let topCapPts = [];
  for (let a = 0; a < 360; a += 10) {
    topCapPts.push(proj(bx, by, cos(a) * rx * 0.96, sin(a) * ry * 0.96, h + 2));
  }
  resetBrush();
  brush.wash(glaze.light, 240);
  drawPoly(topCapPts, 0.2, true);

  resetBrush();
  brush.mass("pastel", glaze.mid, {
    precision: 0.82,
    strength: 0.68,
    gradient: 0.55,
    outline: false
  });
  drawPoly(topCapPts, 0.2, true);

  // Soft highlight dome on upper-left of top cap
  let hiCenter = proj(bx, by, -rx * 0.26, -ry * 0.24, h + 5);
  resetBrush();
  brush.fill(glaze.hi, 145);
  brush.fillBleed(0.25, "out");
  brush.circle(hiCenter[0], hiCenter[1], rx * 0.52, 0.2);

  // 4. Glossy Fondant Crescent Reflection on the Rounded Upper-Left Crown
  let arcPts = [];
  for (let a = 115; a <= 255; a += 12) {
    arcPts.push(proj(bx, by, cos(a) * rx * 0.86, sin(a) * ry * 0.86, h + 3));
  }
  resetBrush();
  brush.set("fondant_glaze", "#ffffff", 2.1);
  brush.spline(arcPts, 0.5);
  brush.set("2H", "#ffffff", 0.95);
  brush.spline(arcPts, 0.5);
  brush.set("2H", glaze.vivid, 0.5);
  brush.spline(arcPts.map((p) => [p[0] + 2.5, p[1] + 2.0]), 0.5);

  // Crisp 2H pencil cutting the outer cylinder contour
  resetBrush();
  brush.set("2H", glaze.pencil, 0.58);
  let pLTop = proj(bx, by, -rx * 0.98, 0, h - 3);
  let pLBot = proj(bx, by, -rx, 0, 3);
  let pRTop = proj(bx, by, rx * 0.98, 0, h - 3);
  let pRBot = proj(bx, by, rx, 0, 3);
  brush.line(pLTop[0], pLTop[1], pLBot[0], pLBot[1]);
  brush.line(pRTop[0], pRTop[1], pRBot[0], pRBot[1]);
}

// ============================================================================
// DOMED BOMBE PETIT FOUR (HEMISPHERICAL GLAZED PATISSERIE DOME)
// ============================================================================
function drawBombePetitFourBody(pf) {
  const { bx, by, glaze, rx, ry, h } = pf;

  // Crisp golden sablé biscuit base disk
  for (let a = -15; a <= 195; a += 6) {
    let p1 = proj(bx, by, cos(a) * rx * 1.04, sin(a) * ry * 1.04, 0);
    let p2 = proj(bx, by, cos(a) * rx * 1.04, sin(a) * ry * 1.04, 7);
    let col = cos(a - 135) > 0 ? PALETTE.spongeLight : PALETTE.spongeDark;
    resetBrush();
    brush.set("cpencil", col, 1.2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Build hemispherical dome silhouette
  let domePts = [];
  for (let a = 0; a <= 180; a += 8) {
    domePts.push(proj(bx, by, cos(a) * rx, sin(a) * ry, 6));
  }
  for (let elev = 10; elev <= 170; elev += 10) {
    let rad = cos(elev) * rx;
    let z = 6 + sin(elev) * (h - 4);
    domePts.push(proj(bx, by, rad, -sin(elev) * ry * 0.22, z));
  }

  // 1. Base wash
  resetBrush();
  brush.wash(glaze.mid, 248);
  drawPoly(domePts, 0.25, true);

  // 2. Concentric spherical shading rings shifted toward upper-left light source
  for (let t = 0.95; t >= 0.08; t -= 0.07) {
    let col;
    if (t > 0.82) col = glaze.shadow;
    else if (t > 0.62) col = glaze.vivid;
    else if (t > 0.42) col = glaze.mid;
    else if (t > 0.22) col = glaze.light;
    else col = glaze.hi;

    let ringPts = [];
    let shiftX = -(1 - t) * rx * 0.36;
    let shiftY = -(1 - t) * ry * 0.28;
    let zLift = 6 + sqrt(max(0, 1 - t * t)) * (h - 5);

    for (let a = 0; a < 360; a += 15) {
      ringPts.push(
        proj(
          bx + shiftX,
          by + shiftY,
          cos(a) * rx * t,
          sin(a) * ry * t * 0.85,
          zLift * (0.65 + 0.35 * (1 - t))
        )
      );
    }
    resetBrush();
    brush.set("velvet_chalk", col, 1.65);
    brush.spline(ringPts, 0.45);
  }

  // Reflected doily bounce along bottom-right curve of the dome
  let bouncePts = [];
  for (let a = -10; a <= 95; a += 10) {
    bouncePts.push(proj(bx, by, cos(a) * rx * 0.94, sin(a) * ry * 0.94, 12));
  }
  resetBrush();
  brush.set("velvet_chalk", glaze.bounce, 1.5);
  brush.spline(bouncePts, 0.45);

  // 3. Mirror-Gloss Window Reflection on Upper-Left Crown of the Bombe!
  let winPts1 = [];
  let winPts2 = [];
  for (let a = 155; a <= 235; a += 14) {
    winPts1.push(proj(bx, by, cos(a) * rx * 0.58, sin(a) * ry * 0.58, h * 0.76));
    winPts2.push(proj(bx, by, cos(a) * rx * 0.42, sin(a) * ry * 0.42, h * 0.86));
  }
  resetBrush();
  brush.set("fondant_glaze", "#ffffff", 2.4);
  brush.spline(winPts1, 0.5);
  brush.set("pastel", "#ffffff", 1.7);
  brush.spline(winPts2, 0.5);

  // Crisp 2H pencil cutting the reflection boundary and dome contour
  brush.set("2H", "#ffffff", 0.95);
  brush.spline(winPts1, 0.5);
  brush.set("2H", glaze.pencil, 0.55);
  let rimContour = [];
  for (let a = -5; a <= 185; a += 10) {
    rimContour.push(proj(bx, by, cos(a) * rx, sin(a) * ry, 6));
  }
  brush.spline(rimContour, 0.4);
}

// ============================================================================
// PIPED BUTTERCREAM SIDE SWAGS & LAMBETH COLLARS
// ============================================================================
function drawPetitFourSidePiping(pf) {
  const { bx, by, shape, glaze, rx, ry, h, swagStyle } = pf;

  // Pipe delicate catenary swags and pearl collars around the front-facing perimeter
  const swagsCount = 3;
  const startAng = -10;
  const totalSpan = 200;
  const spanPerSwag = totalSpan / swagsCount;

  if (swagStyle === "pearl_collar") {
    // Ruffled shell-piped collar around the base of bombe tartlets
    for (let a = -12; a <= 192; a += 9) {
      let rScale = 1.03;
      let p = proj(bx, by, cos(a) * rx * rScale, sin(a) * ry * rScale, 8);
      drawButtercreamShellBead(p[0], p[1], 5.2, a);
    }
    return;
  }

  // Hanging Lambeth-style catenary swags on the vertical sides
  for (let s = 0; s < swagsCount; s++) {
    let a1 = startAng + s * spanPerSwag;
    let a2 = a1 + spanPerSwag;
    let steps = 9;

    // Primary Catenary Swag
    let swagPts = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = lerp(a1, a2, t);
      let rScale = (shape === "cube" || shape === "diamond") ? 0.98 : 1.02;
      let drop = sin(t * 180) * 16;
      let zPos = h * 0.72 - drop;
      let p = proj(bx, by, cos(a) * rx * rScale, sin(a) * ry * rScale, zPos);
      swagPts.push(p);
    }

    // Cast shadow of the piped swag onto the fondant wall
    resetBrush();
    brush.set("2H", glaze.deep, 0.9);
    brush.spline(swagPts.map((p) => [p[0] + 1.5, p[1] + 2.8]), 0.45);

    // Cream body of the swag
    brush.set("pastel", PALETTE.butterMid, 1.45);
    brush.spline(swagPts.map((p) => [p[0], p[1] + 1.0]), 0.45);
    brush.set("pastel", PALETTE.butterLight, 1.35);
    brush.spline(swagPts, 0.45);

    // Individual star-tip ridges & pencil cuts along the swag
    for (let i = 0; i <= steps; i++) {
      let p = swagPts[i];
      resetBrush();
      brush.set("2H", PALETTE.butterShadow, 0.55);
      brush.arc(p[0], p[1], 3.2, 10, 170);
      brush.set("2H", "#ffffff", 0.75);
      brush.arc(p[0], p[1] - 0.6, 3.0, 190, 350);
    }

    // Optional double drop-string swag underneath
    if (swagStyle === "double") {
      let lowPts = [];
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let a = lerp(a1 + 4, a2 - 4, t);
        let rScale = (shape === "cube" || shape === "diamond") ? 0.99 : 1.03;
        let drop = sin(t * 180) * 21;
        let zPos = h * 0.64 - drop;
        lowPts.push(proj(bx, by, cos(a) * rx * rScale, sin(a) * ry * rScale, zPos));
      }
      resetBrush();
      brush.set("2H", glaze.deep, 0.65);
      brush.spline(lowPts.map((p) => [p[0] + 1.2, p[1] + 2.2]), 0.5);
      brush.set("cpencil", PALETTE.butterLight, 0.95);
      brush.spline(lowPts, 0.5);
      brush.set("2H", "#ffffff", 0.65);
      brush.spline(lowPts.map((p) => [p[0], p[1] - 0.8]), 0.5);
    }

    // Tiny piped rosette / silver dragee knot where swags meet
    let knotP = proj(bx, by, cos(a1) * rx * 1.01, sin(a1) * ry * 1.01, h * 0.72);
    drawSilverDragee(knotP[0], knotP[1], 2.8);
  }
}

function drawButtercreamShellBead(x, y, rad, ang) {
  resetBrush();
  brush.set("2H", PALETTE.butterDeep, 0.65);
  brush.circle(x + 1.2, y + 1.8, rad, 0.15);

  brush.set("pastel", PALETTE.butterMid, 1.2);
  brush.circle(x, y, rad * 0.85, 0.15);

  brush.set("pastel", PALETTE.butterHi, 1.0);
  brush.circle(x - 0.8, y - 0.8, rad * 0.6, 0.1);

  // Pencil-cut flute lines
  brush.set("2H", PALETTE.butterShadow, 0.45);
  brush.arc(x, y, rad, 20, 160);
  brush.set("2H", "#ffffff", 0.65);
  brush.arc(x, y, rad * 0.9, 200, 340);
}

// ============================================================================
// TOP CROWN DECORATIONS (ROSETTES, SCROLL LATTICE, SUGARED VIOLETS, GOLD LEAF)
// ============================================================================
function drawPetitFourTopCrown(pf) {
  const { bx, by, glaze, rx, ry, h, topStyle } = pf;
  let topC = proj(bx, by, 0, 0, h + 4);

  // 1. Piped C-scroll or pearl border framing the top edge
  const borderScrolls = 8;
  for (let i = 0; i < borderScrolls; i++) {
    let a1 = i * (360 / borderScrolls);
    let a2 = a1 + 360 / borderScrolls;
    let am = (a1 + a2) * 0.5;
    let p1 = proj(bx, by, cos(a1) * rx * 0.78, sin(a1) * ry * 0.78, h + 4);
    let pm = proj(bx, by, cos(am) * rx * 0.86, sin(am) * ry * 0.86, h + 6);
    let p2 = proj(bx, by, cos(a2) * rx * 0.74, sin(a2) * ry * 0.74, h + 4);

    // Shadow on fondant
    resetBrush();
    brush.set("2H", glaze.deep, 0.7);
    brush.spline([[p1[0] + 1.5, p1[1] + 2], [pm[0] + 1.5, pm[1] + 2], [p2[0] + 1.5, p2[1] + 2]], 0.5);

    // Piped buttercream C-scroll
    brush.set("pastel", PALETTE.butterMid, 1.35);
    brush.spline([p1, pm, p2], 0.5);
    brush.set("pastel", PALETTE.butterHi, 1.05);
    brush.spline([[p1[0], p1[1] - 1], [pm[0], pm[1] - 1], [p2[0], p2[1] - 1]], 0.5);

    // Fine pencil ridge cut
    brush.set("2H", PALETTE.butterShadow, 0.5);
    brush.spline([[p1[0], p1[1] + 0.8], [pm[0], pm[1] + 0.8], [p2[0], p2[1] + 0.8]], 0.5);
  }

  // 2. Central Crown Variation
  if (topStyle === "rosette_crown") {
    // Candied angelica emerald leaves peeking out from under the rosette
    drawCandiedAngelicaLeaf(topC[0] - 10, topC[1] - 4, -145, 16);
    drawCandiedAngelicaLeaf(topC[0] + 12, topC[1] + 5, 25, 15);
    // Lush architectural star-tip Chantilly rosette
    let rosetteTint = glaze.name === "gold" ? "pink" : "ivory";
    drawPipedButtercreamRosette(topC[0], topC[1] - 2, 22, rosetteTint);
    // Topped with a single sugared violet petal or 24k gold leaf & silver dragee
    drawGoldLeafFlake(topC[0] - 5, topC[1] - 8, 7);
    drawSilverDragee(topC[0] + 2, topC[1] - 6, 3.5);
  } else if (topStyle === "violet_trio") {
    // Bed of piped buttercream + 2 candied angelica leaves + 2 sugared violets
    drawPipedButtercreamRosette(topC[0], topC[1], 18, "ivory");
    drawCandiedAngelicaLeaf(topC[0] - 14, topC[1] + 4, 155, 17);
    drawCandiedAngelicaLeaf(topC[0] + 14, topC[1] - 6, -30, 16);
    drawSugaredViolet(topC[0] - 9, topC[1] - 4, 14, -20);
    drawSugaredViolet(topC[0] + 9, topC[1] + 2, 13.5, 35);
    drawGoldLeafFlake(topC[0], topC[1] - 9, 6);
  } else if (topStyle === "violet_rosette") {
    // Tinted buttercream rosette crowned with a prized sugared violet
    let rTint = glaze.name === "pistachio" ? "pink" : "ivory";
    drawPipedButtercreamRosette(topC[0], topC[1] - 1, 21, rTint);
    drawCandiedAngelicaLeaf(topC[0] + 13, topC[1] - 5, -25, 15);
    drawSugaredViolet(topC[0] - 2, topC[1] - 7, 15, 12);
    drawSilverDragee(topC[0] + 8, topC[1] + 2, 3.0);
  } else if (topStyle === "scroll_lattice") {
    // Diagonal royal-icing lattice with S-scrolls, sugared violet & gold leaf
    for (let k = -1; k <= 1; k++) {
      let offset = k * 11;
      let l1 = proj(bx, by, -rx * 0.55, offset, h + 5);
      let l2 = proj(bx, by, rx * 0.55, offset, h + 5);
      let c1 = proj(bx, by, offset, -ry * 0.55, h + 5);
      let c2 = proj(bx, by, offset, ry * 0.55, h + 5);

      resetBrush();
      brush.set("2H", glaze.deep, 0.55);
      brush.line(l1[0] + 1, l1[1] + 1.5, l2[0] + 1, l2[1] + 1.5);
      brush.line(c1[0] + 1, c1[1] + 1.5, c2[0] + 1, c2[1] + 1.5);

      brush.set("cpencil", "#ffffff", 0.95);
      brush.line(l1[0], l1[1], l2[0], l2[1]);
      brush.line(c1[0], c1[1], c2[0], c2[1]);
    }
    drawCandiedAngelicaLeaf(topC[0] - 12, topC[1] - 5, -135, 15);
    drawSugaredViolet(topC[0] + 2, topC[1] - 3, 14.5, -15);
    drawGoldLeafFlake(topC[0] - 7, topC[1] + 4, 6.5);
  }
}

// ============================================================================
// ARCHITECTURAL PIPED BUTTERCREAM ROSETTE (STAR-TIP SWIRL WITH PENCIL CUTS)
// ============================================================================
function drawPipedButtercreamRosette(cx, cy, radius, tint = "ivory") {
  let cHi = "#ffffff";
  let cLight = tint === "pink" ? "#ffe3ee" : tint === "pistachio" ? "#e3ffea" : PALETTE.butterLight;
  let cMid = tint === "pink" ? "#ff9ec2" : tint === "pistachio" ? "#8ce8a8" : PALETTE.butterMid;
  let cShadow = tint === "pink" ? "#c94b7c" : tint === "pistachio" ? "#2e9651" : PALETTE.butterShadow;
  let cDeep = tint === "pink" ? "#821842" : tint === "pistachio" ? "#14592b" : PALETTE.butterDeep;

  // 1. Cast shadow under the rosette
  resetBrush();
  brush.wash(cDeep, 145);
  brush.circle(cx + 3, cy + 4, radius * 0.95, 0.2);

  // 2. Velvety base mass of the rosette
  resetBrush();
  brush.wash(cMid, 240);
  brush.circle(cx, cy, radius * 0.9, 0.18);

  // 3. 8 Swirling Star-Tip Fluted Ridges Spiraling from Center to Rim
  const ribs = 8;
  for (let i = 0; i < ribs; i++) {
    let baseA = i * (360 / ribs);
    let rPts = [];
    let shadowPts = [];
    let hiPts = [];

    for (let t = 0.12; t <= 1.0; t += 0.18) {
      let a = baseA + t * 88; // Spiral twist!
      let r = t * radius;
      let zLift = (1 - t) * 9;
      let px = cx + cos(a) * r;
      let py = cy + sin(a) * r * TILT - zLift;
      rPts.push([px, py]);
      shadowPts.push([px + 1.4, py + 2.0]);
      hiPts.push([px - 0.8, py - 1.2]);
    }

    // Deep crease shadow between star-tip grooves
    resetBrush();
    brush.set("cpencil", cShadow, 1.15);
    brush.spline(shadowPts, 0.5);

    // Creamy ridge body
    brush.set("pastel", cLight, 1.55);
    brush.spline(rPts, 0.5);

    // Crisp specular ridge crest
    brush.set("pastel", cHi, 1.15);
    brush.spline(hiPts, 0.5);

    // Razor-sharp 2H pencil cutting the star-tip edge!
    brush.set("2H", cDeep, 0.55);
    brush.spline(shadowPts, 0.5);
    brush.set("2H", "#ffffff", 0.75);
    brush.spline(hiPts, 0.5);
  }

  // 4. Central Star-Tip Peak Swirl
  resetBrush();
  brush.set("pastel", cHi, 1.5);
  brush.circle(cx - 1, cy - 6, 4.2, 0.1);
  brush.set("2H", cDeep, 0.55);
  brush.arc(cx, cy - 5, 4.8, 15, 195);
}

// ============================================================================
// CRYSTALLIZED SUGARED VIOLETS (VIOLA ODORATA WITH FROSTED SUGAR CRYSTALS)
// ============================================================================
function drawSugaredViolet(cx, cy, radius, rot = 0) {
  // 5 Anatomically distinct overlapping heart-shaped petals:
  // 2 upper banner petals, 2 lateral wing petals, 1 broad lower lip petal
  const petalAngles = [-115, -65, -162, -18, 90];
  const petalScales = [0.95, 0.95, 0.92, 0.92, 1.12];

  // Cast shadow under the flower
  resetBrush();
  brush.wash("#22053d", 145);
  brush.circle(cx + 2.5, cy + 3.2, radius * 0.85, 0.25);

  for (let p = 0; p < 5; p++) {
    let a = petalAngles[p] + rot;
    let sc = petalScales[p];
    let pRad = radius * sc;

    // Build heart-lobed petal polygon
    let pts = [[cx, cy]];
    let span = p === 4 ? 46 : 36;
    for (let da = -span; da <= span; da += 12) {
      let norm = da / span; // -1..1
      // Subtle indentation at the tip of the lower petal
      let lobe = 1.0 - 0.15 * exp(-pow(norm * 3, 2)) + 0.12 * cos(norm * 90);
      let r = pRad * lobe;
      let pa = a + da;
      let px = cx + cos(pa) * r;
      let py = cy + sin(pa) * r * (TILT + 0.08);
      pts.push([px, py]);
    }

    // 1. Rich velvety purple-violet petal fill
    let baseCol = p < 2 ? PALETTE.violetDeep : p < 4 ? PALETTE.violetMid : PALETTE.violetLight;
    resetBrush();
    brush.wash(baseCol, 242);
    drawPoly(pts, 0.25, true);

    // 2. Soft pastel shading toward petal lobe
    let lobeMid = [
      cx + cos(a) * pRad * 0.62,
      cy + sin(a) * pRad * 0.62 * TILT
    ];
    resetBrush();
    brush.set("velvet_chalk", p === 4 ? "#d48aff" : PALETTE.violetLight, 1.35);
    brush.circle(lobeMid[0], lobeMid[1], pRad * 0.35, 0.2);

    // 3. Deep velvety throat & botanical veins in 2H pencil
    resetBrush();
    brush.set("2H", PALETTE.violetDark, 0.55);
    for (let v = -1; v <= 1; v++) {
      let va = a + v * 14;
      brush.line(
        cx + cos(va) * 2,
        cy + sin(va) * 2 * TILT,
        cx + cos(va) * pRad * 0.68,
        cy + sin(va) * pRad * 0.68 * TILT
      );
    }

    // 4. Frosted Crystalline Sugar Coating along Petal Rims & Surface!
    for (let i = 1; i < pts.length; i++) {
      let pt = pts[i];
      resetBrush();
      // Alternating pure white & icy lilac sugar crystal facets
      brush.set("2H", i % 2 === 0 ? "#ffffff" : PALETTE.violetHi, 0.85);
      brush.line(pt[0], pt[1], pt[0] + random(-1.8, 1.8), pt[1] + random(-1.8, 1.8));
      if (i % 2 === 1) {
        brush.set("rotring", "#ffffff", 0.75);
        brush.line(pt[0] - 0.5, pt[1] - 0.5, pt[0] + 0.8, pt[1] + 0.5);
      }
    }

    // Interior sparkling sugar granules on the velvet petal
    for (let g = 0; g < 5; g++) {
      let gr = random(0.25, 0.85) * pRad;
      let ga = a + random(-span * 0.7, span * 0.7);
      let gx = cx + cos(ga) * gr;
      let gy = cy + sin(ga) * gr * TILT;
      resetBrush();
      brush.set("2H", "#ffffff", 0.7);
      brush.line(gx, gy, gx + 1.1, gy + 0.8);
    }
  }

  // 5. Glowing Golden-Orange Center Eye of the Violet
  resetBrush();
  brush.set("pastel", "#82e86b", 0.9);
  brush.circle(cx, cy + 1, 2.6, 0.1);
  brush.set("pastel", PALETTE.violetEye, 1.25);
  brush.circle(cx, cy, 2.2, 0.1);
  brush.set("2H", PALETTE.violetEyeHi, 0.95);
  brush.line(cx - 0.8, cy - 0.8, cx + 0.8, cy - 0.4);
}

function drawSugarVioletCluster(vc) {
  const { bx, by, z, count, scale, leaves } = vc;
  let baseP = proj(bx, by, 0, 0, z);

  // Candied angelica diamond leaves beneath the violets
  for (let l = 0; l < leaves; l++) {
    let la = l === 0 ? -145 + random(-15, 15) : 35 + random(-15, 15);
    drawCandiedAngelicaLeaf(baseP[0] + cos(la) * 8, baseP[1] + sin(la) * 6, la, 17 * scale);
  }

  // Clustered sugared violets
  const offsets = [
    [0, 0, 10],
    [-13 * scale, 5 * scale, -28],
    [12 * scale, 6 * scale, 42]
  ];
  for (let i = 0; i < count; i++) {
    let off = offsets[i];
    drawSugaredViolet(
      baseP[0] + off[0],
      baseP[1] + off[1],
      14.5 * scale * (1 - i * 0.06),
      off[2]
    );
  }
}

function drawCandiedAngelicaLeaf(x, y, angleDeg, len) {
  let wid = len * 0.42;
  let tip = [x + cos(angleDeg) * len, y + sin(angleDeg) * len * TILT];
  let side1 = [
    x + cos(angleDeg) * len * 0.5 + cos(angleDeg + 90) * wid,
    y + sin(angleDeg) * len * 0.5 * TILT + sin(angleDeg + 90) * wid * TILT
  ];
  let side2 = [
    x + cos(angleDeg) * len * 0.5 + cos(angleDeg - 90) * wid,
    y + sin(angleDeg) * len * 0.5 * TILT + sin(angleDeg - 90) * wid * TILT
  ];

  resetBrush();
  brush.wash(PALETTE.angelicaMid, 225);
  drawPoly([[x, y], side1, tip, side2], 0.15, true);

  resetBrush();
  brush.set("cpencil", PALETTE.angelicaLight, 0.9);
  brush.line(x, y, tip[0], tip[1]);
  brush.set("2H", PALETTE.angelicaDark, 0.55);
  brush.line(side2[0], side2[1], tip[0], tip[1]);

  // Sugar crystal rim on the candied angelica
  brush.set("2H", "#ffffff", 0.75);
  brush.line(x, y, side1[0], side1[1]);
  brush.line(side1[0], side1[1], tip[0], tip[1]);
}

function drawGoldLeafFlake(x, y, sz) {
  let pts = [
    [x - sz * 0.6, y - sz * 0.2],
    [x + sz * 0.2, y - sz * 0.7],
    [x + sz * 0.8, y + sz * 0.1],
    [x - sz * 0.1, y + sz * 0.6]
  ];
  resetBrush();
  brush.wash(PALETTE.goldLeafMid, 245);
  drawPoly(pts, 0.1, true);

  resetBrush();
  brush.set("2H", PALETTE.goldLeafDark, 0.55);
  brush.line(pts[2][0], pts[2][1], pts[3][0], pts[3][1]);
  brush.set("2H", PALETTE.goldLeafHi, 0.95);
  brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  brush.set("rotring", "#ffffff", 0.8);
  brush.line(x - 1, y - 1, x + 1.5, y - 0.5);
}

function drawSilverDragee(x, y, rad) {
  resetBrush();
  brush.set("2H", "#1c2533", 0.8);
  brush.circle(x + 1.0, y + 1.2, rad, 0.05);

  brush.set("marker", "#6e8299", 1.1);
  brush.circle(x, y, rad * 0.85, 0.05);

  brush.set("rotring", "#ffffff", 0.95);
  brush.line(x - rad * 0.35, y - rad * 0.35, x - rad * 0.1, y - rad * 0.2);
}

// ============================================================================
// STANDALONE PIPED BUTTERCREAM ROCOCO SCROLLS
// ============================================================================
function drawStandaloneButtercreamScroll(sc) {
  const { bx, by, angle, len, flip, tint } = sc;

  let cLight = tint === "pink" ? "#ffe0ed" : tint === "pistachio" ? "#e0ffea" : PALETTE.butterLight;
  let cMid = tint === "pink" ? "#ff94be" : tint === "pistachio" ? "#82e3a0" : PALETTE.butterMid;
  let cShadow = tint === "pink" ? "#bd3a6e" : tint === "pistachio" ? "#268547" : PALETTE.butterShadow;
  let cDeep = tint === "pink" ? "#7a113b" : tint === "pistachio" ? "#0f4d23" : PALETTE.butterDeep;

  let spinePts = [];
  let steps = 14;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps; // 0..1
    // Graceful S/C scroll curve
    let curAng = angle + flip * sin(t * 270 - 45) * 68;
    let dist = t * len;
    let sx = bx + cos(curAng) * dist * 0.85;
    let sy = by + sin(curAng) * dist * 0.85 * TILT - sin(t * 180) * 6;
    spinePts.push([sx, sy]);
  }

  // 1. Cast shadow on doily
  resetBrush();
  brush.set("cpencil", "#544863", 1.5);
  brush.spline(spinePts.map((p) => [p[0] + 3.0, p[1] + 4.0]), 0.5);

  // 2. Thick buttercream body
  brush.set("pastel", cMid, 2.2);
  brush.spline(spinePts.map((p) => [p[0] + 0.8, p[1] + 1.2]), 0.5);

  brush.set("pastel", cLight, 1.9);
  brush.spline(spinePts, 0.5);

  // 3. Fluted star-tip ridges & crisp 2H pencil cuts
  brush.set("2H", cDeep, 0.65);
  brush.spline(spinePts.map((p) => [p[0] + 1.8, p[1] + 2.4]), 0.5);

  brush.set("2H", cShadow, 0.55);
  brush.spline(spinePts.map((p) => [p[0] - 0.5, p[1] + 0.8]), 0.5);

  brush.set("pastel", "#ffffff", 1.25);
  brush.spline(spinePts.map((p) => [p[0] - 1.0, p[1] - 1.4]), 0.5);

  brush.set("2H", "#ffffff", 0.85);
  brush.spline(spinePts.map((p) => [p[0] - 1.2, p[1] - 1.6]), 0.5);

  // Terminal star-tip rosette head at start of scroll
  drawPipedButtercreamRosette(spinePts[0][0], spinePts[0][1], 11.5, tint);
}

// ============================================================================
// HERO CUT/SLICED PETIT FOUR IN THE C-SCROLL HOLLOW (INTERNAL CAKE ANATOMY)
// ============================================================================
function drawCutPetitFour(item) {
  const { bx, by, rx, ry, h, glaze } = item;

  // This triangular/diagonal half-petit four faces the viewer with its cleanly sliced interior:
  // Back-left corner, Back-right corner, and Front-left corner
  let pFL_bot = proj(bx, by, -rx * 0.95, ry * 0.35, 2);
  let pBR_bot = proj(bx, by, rx * 0.92, -ry * 0.15, 2);
  let pBL_bot = proj(bx, by, -rx * 0.25, -ry * 0.95, 2);

  let pFL_top = proj(bx, by, -rx * 0.92, ry * 0.32, h);
  let pBR_top = proj(bx, by, rx * 0.88, -ry * 0.14, h);
  let pBL_top = proj(bx, by, -rx * 0.24, -ry * 0.92, h);

  // 1. Exterior Poured Shell-Pink Fondant Top Face
  let topPts = [pFL_top, pBL_top, pBR_top];
  resetBrush();
  brush.wash(glaze.mid, 248);
  drawPoly(topPts, 0.12, true);

  resetBrush();
  brush.mass("pastel", glaze.light, {
    precision: 0.82,
    strength: 0.7,
    gradient: 0.4,
    outline: false
  });
  drawPoly(topPts, 0.12, true);

  // Specular highlight along back-left fondant edge
  resetBrush();
  brush.set("fondant_glaze", "#ffffff", 2.0);
  brush.spline([pFL_top, pBL_top, pBR_top], 0.35);
  brush.set("2H", "#ffffff", 0.9);
  brush.line(pFL_top[0], pFL_top[1], pBL_top[0], pBL_top[1]);

  // 2. Sliced Cross-Section Face (From pFL to pBR, height 2..h)
  // Reveals 7 distinct patisserie layers!
  const layers = [
    { z0: 0.0, z1: 0.05, col: "#2b1408", hi: "#4a2511", type: "chablon" },       // Dark chocolate base chablon
    { z0: 0.05, z1: 0.28, col: PALETTE.spongeMid, hi: PALETTE.spongeLight, type: "sponge" }, // Almond joconde 1
    { z0: 0.28, z1: 0.39, col: "#3ca854", hi: "#9ef2b0", type: "pistachio" },    // Pistachio mousseline
    { z0: 0.39, z1: 0.61, col: PALETTE.spongeMid, hi: PALETTE.spongeLight, type: "sponge" }, // Almond joconde 2
    { z0: 0.61, z1: 0.72, col: "#c91243", hi: "#ff6b93", type: "raspberry" },    // Ruby raspberry jam
    { z0: 0.72, z1: 0.93, col: PALETTE.spongeMid, hi: PALETTE.spongeLight, type: "sponge" }, // Almond joconde 3
    { z0: 0.93, z1: 1.0, col: glaze.vivid, hi: glaze.hi, type: "fondant" }       // Top poured fondant coat
  ];

  for (let lay of layers) {
    let lBL = [lerp(pFL_bot[0], pFL_top[0], lay.z0), lerp(pFL_bot[1], pFL_top[1], lay.z0)];
    let lBR = [lerp(pBR_bot[0], pBR_top[0], lay.z0), lerp(pBR_bot[1], pBR_top[1], lay.z0)];
    let lTR = [lerp(pBR_bot[0], pBR_top[0], lay.z1), lerp(pBR_bot[1], pBR_top[1], lay.z1)];
    let lTL = [lerp(pFL_bot[0], pFL_top[0], lay.z1), lerp(pFL_bot[1], pFL_top[1], lay.z1)];

    resetBrush();
    brush.wash(lay.col, 248);
    drawPoly([lBL, lBR, lTR, lTL], 0.04, true);

    if (lay.type === "sponge") {
      // Hyperrealistic porous crumb texture of golden almond joconde sponge
      for (let u = 0.04; u <= 0.96; u += 0.05) {
        for (let v = 0.15; v <= 0.85; v += 0.35) {
          let sx = lerp(lerp(lBL[0], lBR[0], u), lerp(lTL[0], lTR[0], u), v) + random(-1.5, 1.5);
          let sy = lerp(lerp(lBL[1], lBR[1], u), lerp(lTL[1], lTR[1], u), v) + random(-1.2, 1.2);
          resetBrush();
          // Tiny dark air pores paired with golden crumb highlights
          brush.set("2H", random() > 0.45 ? PALETTE.spongeDeep : PALETTE.spongeDark, 0.65);
          brush.line(sx, sy, sx + 1.2, sy + 0.6);
          brush.set("cpencil", PALETTE.spongeLight, 0.75);
          brush.line(sx - 0.8, sy - 0.6, sx + 0.4, sy - 0.2);
        }
      }
    } else if (lay.type === "raspberry") {
      // Glistening wet ruby raspberry jam with specular seed highlights
      resetBrush();
      brush.set("fondant_glaze", "#8a0629", 1.2);
      brush.line(lBL[0], lBL[1], lBR[0], lBR[1]);
      for (let u = 0.1; u < 0.9; u += 0.12) {
        let jx = lerp(lTL[0], lTR[0], u);
        let jy = lerp(lTL[1], lTR[1], u) + 1.5;
        brush.set("rotring", "#ffffff", 0.8);
        brush.line(jx, jy, jx + 2.0, jy + 0.3);
      }
    } else if (lay.type === "pistachio") {
      resetBrush();
      brush.set("pastel", lay.hi, 1.1);
      brush.line(lTL[0], lTL[1] + 1, lTR[0], lTR[1] + 1);
      brush.set("2H", "#195c29", 0.55);
      brush.line(lBL[0], lBL[1], lBR[0], lBR[1]);
    } else if (lay.type === "fondant") {
      resetBrush();
      brush.set("pastel", "#ffffff", 1.1);
      brush.line(lTL[0], lTL[1], lTR[0], lTR[1]);
    }
  }

  // Knife-cut vertical edge on left & right of the slice
  resetBrush();
  brush.set("2H", glaze.deep, 0.7);
  brush.line(pFL_bot[0], pFL_bot[1], pFL_top[0], pFL_top[1]);
  brush.line(pBR_bot[0], pBR_bot[1], pBR_top[0], pBR_top[1]);

  // Half-rosette & sugared violet on the crown of the cut petit four
  let crownC = [
    (pFL_top[0] + pBL_top[0] + pBR_top[0]) / 3,
    (pFL_top[1] + pBL_top[1] + pBR_top[1]) / 3
  ];
  drawCandiedAngelicaLeaf(crownC[0] - 10, crownC[1] - 4, -150, 14);
  drawPipedButtercreamRosette(crownC[0], crownC[1] - 1, 16, "ivory");
  drawSugaredViolet(crownC[0] + 6, crownC[1] - 5, 12.5, 20);
}

// ============================================================================
// STAGE 7: SCATTERED CRUMBS, SUGAR CRYSTALS & FALLEN PETALS AS ROCOCO ORNAMENT
// ============================================================================
function drawOrnamentalCrumbsAndSugar(isForeground) {
  // Ornamental C-scroll arcs of golden sponge crumbs, sugar crystals, and fondant droplets
  const crumbZones = [
    // Around the cut petit four in the hollow of the C-scroll
    { cx: 690, cy: 612, rx: 65, ry: 38, count: 38 },
    // Upper-right ornamental tail
    { cx: 848, cy: 405, rx: 55, ry: 42, count: 26 },
    // Center-right open lace doily field
    { cx: 765, cy: 525, rx: 75, ry: 55, count: 32 },
    // Lower-center doily field inside the C
    { cx: 615, cy: 685, rx: 70, ry: 45, count: 28 },
    // Bottom-right ornamental curl tip
    { cx: 895, cy: 645, rx: 50, ry: 45, count: 24 },
    // Spilled onto the gleaming silver rim on the right & bottom-left
    { cx: 995, cy: 585, rx: 45, ry: 60, count: 18 },
    { cx: 305, cy: 735, rx: 45, ry: 45, count: 18 }
  ];

  for (let z of crumbZones) {
    let n = isForeground ? floor(z.count * 0.55) : ceil(z.count * 0.45);
    for (let i = 0; i < n; i++) {
      let a = random(0, 360);
      let r = pow(random(), 0.65);
      let x = z.cx + cos(a) * z.rx * r;
      let y = z.cy + sin(a) * z.ry * r;
      let sz = random(1.4, 5.2);

      // 1. Tiny crisp cast shadow under each crumb
      resetBrush();
      brush.set("2H", "#3c324a", 0.75);
      brush.circle(x + 1.4, y + 1.8, sz * 0.9, 0.25);

      // 2. Golden sponge crumb body
      let cCol = random() > 0.35 ? PALETTE.spongeMid : PALETTE.spongeDark;
      brush.set("cpencil", cCol, 1.15);
      brush.circle(x, y, sz * 0.8, 0.35);

      // 3. Bright toasted-sugar highlight on upper-left of crumb
      brush.set("2H", PALETTE.spongeLight, 0.85);
      brush.line(x - sz * 0.4, y - sz * 0.4, x + sz * 0.2, y - sz * 0.2);
    }
  }

  if (isForeground) {
    // Fallen single sugared violet petals scattered across the doily hollow
    const fallenPetals = [
      { x: 732, y: 598, rot: 25, sz: 9.5 },
      { x: 642, y: 632, rot: -40, sz: 8.5 },
      { x: 785, y: 492, rot: 75, sz: 9.0 },
      { x: 868, y: 585, rot: -15, sz: 8.0 },
      { x: 585, y: 515, rot: 110, sz: 8.5 }
    ];

    for (let fp of fallenPetals) {
      resetBrush();
      brush.wash("#442e5c", 130);
      brush.circle(fp.x + 2.5, fp.y + 3.0, fp.sz * 0.85, 0.2);

      let pts = [];
      for (let a = 0; a < 360; a += 45) {
        let rad = fp.sz * (0.75 + 0.25 * cos(a - fp.rot));
        pts.push([fp.x + cos(a) * rad, fp.y + sin(a) * rad * TILT]);
      }
      resetBrush();
      brush.wash(PALETTE.violetMid, 235);
      drawPoly(pts, 0.3, true);

      resetBrush();
      brush.set("cpencil", PALETTE.violetLight, 0.9);
      brush.circle(fp.x - 1, fp.y - 1, fp.sz * 0.45, 0.2);

      // Sparkling sugar rim on fallen petal
      brush.set("2H", "#ffffff", 0.75);
      brush.arc(fp.x, fp.y, fp.sz * 0.85, fp.rot - 70, fp.rot + 90);
    }

    // Stray silver dragees & pastel fondant droplets on the lace doily
    const drageeSpots = [
      [718, 622], [658, 608], [748, 545], [825, 462],
      [618, 668], [865, 632], [545, 585], [775, 652]
    ];
    for (let d of drageeSpots) {
      drawSilverDragee(d[0], d[1], random(2.4, 3.6));
    }

    // Tiny ruby raspberry jam & pistachio crumbs right in front of the sliced petit four
    const jamDrops = [
      { x: 672, y: 604, r: 3.5, col: "#d91448" },
      { x: 686, y: 610, r: 2.4, col: "#d91448" },
      { x: 702, y: 596, r: 3.0, col: "#38c265" }
    ];
    for (let jd of jamDrops) {
      resetBrush();
      brush.wash(jd.col, 235);
      brush.circle(jd.x, jd.y, jd.r, 0.15);
      brush.set("rotring", "#ffffff", 0.75);
      brush.line(jd.x - 1, jd.y - 1, jd.x + 0.5, jd.y - 0.5);
    }

    // Superfine sparkling caster sugar dust across the C-scroll
    resetBrush();
    for (let s = 0; s < 95; s++) {
      let a = random(-65, 245);
      let rad = random(180, 370);
      let sx = TRAY_X - 30 + cos(a) * rad;
      let sy = TRAY_Y + sin(a) * rad * TILT;
