// =============================================================================
// GEOMETRY & DISTANCE FIELD HELPERS
// =============================================================================

function buildShoeHullAndDistField() {
  // Complete outer silhouette including high-top tongue, collar, heel, sole,
  // cast shadow, and the broken frayed lace trailing onto the floor
  shoeHull = [
    [168, 750], [182, 710], [212, 682], [262, 658], [325, 642],
    [372, 635], [418, 578], [468, 512], [518, 442], [568, 372],
    [608, 305], [635, 252], [678, 244], [728, 256], [748, 288],
    [785, 275], [825, 295], [805, 325], [865, 342], [922, 348],
    [964, 346], [978, 415], [994, 495], [1006, 585], [1016, 675],
    [1022, 745], [1024, 808], [1038, 845], [1015, 872], [935, 892],
    [810, 906], [675, 916], [535, 926], [420, 932], [335, 928],
    [308, 912], [240, 895], [186, 862], [165, 815]
  ];

  for (let gx = 0; gx < GRID_RES; gx++) {
    distGrid[gx] = new Float32Array(GRID_RES);
    let px = (gx + 0.5) * CELL_SIZE;
    for (let gy = 0; gy < GRID_RES; gy++) {
      let py = (gy + 0.5) * CELL_SIZE;
      let d = minDistToPoly(px, py, shoeHull);
      let inside = pointInPoly(px, py, shoeHull);
      distGrid[gx][gy] = inside ? -d : d;
    }
  }
}

function getShoeDist(x, y) {
  let gx = Math.floor(x / CELL_SIZE);
  let gy = Math.floor(y / CELL_SIZE);
  if (gx < 0 || gx >= GRID_RES || gy < 0 || gy >= GRID_RES) return 999;
  return distGrid[gx][gy];
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function minDistToPoly(px, py, poly) {
  let minD2 = Infinity;
  for (let i = 0, n = poly.length; i < n; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % n];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len2 = dx * dx + dy * dy;
    let t = len2 === 0 ? 0 : ((px - p1[0]) * dx + (py - p1[1]) * dy) / len2;
    t = Math.max(0, Math.min(1, t));
    let cx = p1[0] + t * dx;
    let cy = p1[1] + t * dy;
    let d2 = (px - cx) * (px - cx) + (py - cy) * (py - cy);
    if (d2 < minD2) minD2 = d2;
  }
  return Math.sqrt(minD2);
}

