function drawNotebookPaper() {
  brush.noStroke();

  // Soft pastel watercolor stains & age patina across notebook page
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.18);

  brush.fill(PAL.paperWarm, 26);
  brush.circle(180, 180, 260, 0.35);
  brush.circle(1050, 1020, 290, 0.4);
  brush.circle(580, 660, 420, 0.3);

  brush.fill(PAL.paperCool, 24);
  brush.circle(620, 680, 380, 0.3);
  brush.circle(960, 240, 220, 0.35);

  brush.fill(PAL.paperRose, 22);
  brush.circle(150, 620, 230, 0.35);
  brush.circle(880, 460, 260, 0.3);

  brush.fill(PAL.paperMint, 20);
  brush.circle(320, 1040, 210, 0.4);

  brush.noFill();

  // Subtle paper tooth fibers
  brush.set("2H", "#dfd6c7", 0.35);
  for (let i = 0; i < 220; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let a = random(180);
    let len = random(12, 42);
    brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  // Horizontal blue ruled notebook lines (every 34px starting at y = 112)
  for (let y = 112; y <= 1166; y += 34) {
    // Soft pastel blue base rule
    brush.set("rotring", PAL.ruleBlue, 0.65);
    let pts = [];
    for (let x = 8; x <= 1192; x += 60) {
      pts.push([x, y + random(-0.35, 0.35), random(0.7, 1.0)]);
    }
    brush.spline(pts, 0.2);

    // Faint secondary print bleed
    brush.set("bic_whisper", PAL.ruleBlueFaint, 0.5);
    brush.line(10, y + 0.6, 1190, y + 0.6);
  }

  // Vertical double coral-pink margin lines on left (x = 136 and x = 142)
  const marginXs = [136, 142];
  for (let mx of marginXs) {
    brush.set("rotring", PAL.marginPink, 0.72);
    let mPts = [];
    for (let y = 8; y <= 1192; y += 65) {
      mPts.push([mx + random(-0.35, 0.35), y, random(0.75, 1.05)]);
    }
    brush.spline(mPts, 0.2);
  }

  // Three punched binder holes on the left margin
  const holeYs = [206, 600, 994];
  for (let hy of holeYs) {
    let hx = 58;
    // Recessed dark backing
    brush.noStroke();
    brush.wash(PAL.holeDark, 215);
    brush.circle(hx, hy, 22, 0.08);
    brush.noWash();

    // Torn paper thickness rim
    brush.set("bic_pastel", "#c9bfb0", 0.9);
    brush.arc(hx + 1.5, hy + 1.5, 22.5, -40, 140);
    brush.set("bic_med", PAL.inkDeep, 0.75);
    brush.circle(hx, hy, 22, 0.12);

    // Reinforcing ring ghost & stress creases around binder hole
    brush.set("bic_whisper", PAL.inkPastel, 0.55);
    brush.circle(hx, hy, 36, 0.18);
  }
}

