// LAYER 2: OBSESSIVE OUTSIDER MARGINS (LOOPS, TALLIES, PSEUDO-HANDWRITING)
// =============================================================================

function drawObsessiveMargins() {
  const HALO_MIN = 20; // Strict untouched margin around sneaker ("never touches it")

  // A. Compulsive Halo-Hugging Loop Chains (crowding right against the 20px barrier)
  drawHaloCrowdingLoops(21.5, 4.2, "bic_med", PAL.inkMid, 0.95);
  drawHaloCrowdingLoops(28.0, 5.0, "bic_pastel", PAL.inkPastel, 0.8);
  drawHaloCrowdingLoops(35.5, 5.6, "bic_whisper", PAL.inkLavender, 0.7);

  // B. Top Header Margin (y = 20..106): Regimented Tally Blocks & Feverish Script
  drawTallyRegion(152, 22, 540, 82, 16, HALO_MIN);
  drawPseudoScriptBlock(560, 24, 1175, 102, 11, HALO_MIN);

  // C. Left Margin Strip (x = 18..130): Compulsive Tally Columns & Spiral Coils
  for (let y = 116; y <= 1140; y += 34) {
    // Avoid binder holes at (58, 206), (58, 600), (58, 994)
    if (Math.abs(y - 206) < 42 || Math.abs(y - 600) < 42 || Math.abs(y - 994) < 42) {
      // Cram tiny micro-numbers to the right of the binder hole
      drawCrampedWord(94, y + 12, 36, 5.5, "bic_heavy", PAL.inkGouge, 0.9);
      drawCrampedWord(94, y + 25, 36, 5.0, "bic_med", PAL.inkMid, 0.8);
      continue;
    }
    let rowMode = Math.floor(noise(y * 0.05) * 3);
    if (rowMode === 0) {
      drawFiveTally(22, y + 6, 20, 22, HALO_MIN);
      drawFiveTally(52, y + 6, 20, 22, HALO_MIN);
      drawFiveTally(82, y + 6, 20, 22, HALO_MIN);
      drawFiveTally(110, y + 6, 18, 22, HALO_MIN);
    } else if (rowMode === 1) {
      drawLoopChainSegment(20, y + 11, 128, 6.5, HALO_MIN, 0);
      drawLoopChainSegment(20, y + 25, 128, 6.0, HALO_MIN, 1);
    } else {
      drawCrampedWord(20, y + 12, 108, 6.5, "bic_med", PAL.inkMid, 0.85);
      drawCrampedWord(20, y + 26, 108, 6.0, "bic_pastel", PAL.inkPastel, 0.75);
    }
  }

  // D. Main Ruled Notebook Rows (y = 112..1166, x = 148..1182)
  // Every 34px ruled line holds 2 or 3 sub-lines of cramped pseudo-handwriting,
  // repeating cycloid loops, or tally blocks that stop right at the sneaker halo!
  let rowIndex = 0;
  for (let y = 112; y <= 1166; y += 34) {
    rowIndex++;
    let styleSeed = noise(rowIndex * 0.37, 1.5);

    if (styleSeed < 0.44) {
      // Double-stacked cramped pseudo-handwriting on this ruled line
      drawRuledScriptScanline(148, 1180, y + 12, 7.2, HALO_MIN, rowIndex * 13);
      drawRuledScriptScanline(148, 1180, y + 27, 7.5, HALO_MIN, rowIndex * 29 + 7);
    } else if (styleSeed < 0.74) {
      // Compulsive continuous repeating loops + micro-script baseline
      drawLoopChainSegment(148, y + 13, 1180, 8.2, HALO_MIN, rowIndex);
      drawRuledScriptScanline(148, 1180, y + 28, 6.8, HALO_MIN, rowIndex * 19);
    } else {
      // Obsessive tally mark bundles mixed with gouged notations
      drawRuledTallyScanline(148, 1180, y + 6, 23, HALO_MIN, rowIndex);
    }
  }

  // E. Extra crammed micro-writing in the bottom footer margin (y = 1170..1192)
  drawRuledScriptScanline(24, 1180, 1182, 6.5, HALO_MIN, 991);
}

function drawHaloCrowdingLoops(targetDist, amp, brushName, col, weight) {
  // Walk around the shoe hull normals to place tight cycloid loops right along the halo boundary
  let perimeterPts = [];
  const N = shoeHull.length;
  for (let i = 0; i < N; i++) {
    let p1 = shoeHull[i];
    let p2 = shoeHull[(i + 1) % N];
    let segLen = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = Math.max(2, Math.floor(segLen / 5));
    let dx = (p2[0] - p1[0]) / segLen;
    let dy = (p2[1] - p1[1]) / segLen;
    // Outward normal (hull is clockwise in screen coords)
    let nx = dy;
    let ny = -dx;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let bx = lerp(p1[0], p2[0], t) + nx * targetDist;
      let by = lerp(p1[1], p2[1], t) + ny * targetDist;
      if (getShoeDist(bx, by) >= 18.5 && bx > 18 && bx < 1182 && by > 18 && by < 1182) {
        perimeterPts.push([bx, by, nx, ny, dx, dy]);
      }
    }
  }

  // Group into spline chunks of 18 loops so pressure fluctuates feverishly
  let idx = 0;
  while (idx < perimeterPts.length - 4) {
    let chunkLen = Math.min(22, perimeterPts.length - idx);
    let pts = [];
    let pNoise = noise(idx * 0.08, targetDist);
    let curCol = pNoise > 0.68 ? PAL.inkGouge : (pNoise < 0.34 ? PAL.inkPastel : col);
    let curBrush = pNoise > 0.72 ? "bic_heavy" : (pNoise < 0.3 ? "bic_whisper" : brushName);
    brush.set(curBrush, curCol, weight * map(pNoise, 0, 1, 0.65, 1.35));

    for (let k = 0; k < chunkLen; k++) {
      let pt = perimeterPts[idx + k];
      let phase = k * 145;
      let ox = pt[2] * (sin(phase) * amp * 0.55 + amp * 0.45) + pt[4] * cos(phase) * amp * 0.5;
      let oy = pt[3] * (sin(phase) * amp * 0.55 + amp * 0.45) + pt[5] * cos(phase) * amp * 0.5;
      pts.push([pt[0] + ox, pt[1] + oy, random(0.4, 1.3)]);
    }
    if (pts.length >= 3) brush.spline(pts, 0.65);
    idx += chunkLen - 1;
  }
}

function drawLoopChainSegment(xStart, yBase, xEnd, loopH, haloMin, seedOff) {
  let x = xStart;
  while (x < xEnd - 10) {
    if (getShoeDist(x, yBase) < haloMin) {
      x += 5;
      continue;
    }
    // Start a continuous chain of 10-16 connected cycloid loops
    let pts = [];
    let nLoops = Math.floor(random(8, 16));
    let pressureWave = noise(x * 0.015, yBase * 0.02 + seedOff);
    let bName = pressureWave > 0.68 ? "bic_heavy" : (pressureWave < 0.35 ? "bic_whisper" : "bic_med");
    let bCol = pressureWave > 0.72 ? PAL.inkGouge : (pressureWave < 0.32 ? PAL.inkWhisper : (pressureWave < 0.5 ? PAL.inkPastel : PAL.inkMid));
    let wMult = map(pressureWave, 0, 1, 0.55, 1.3);

    for (let i = 0; i < nLoops; i++) {
      let lx = x + i * 4.8;
      if (lx > xEnd || getShoeDist(lx, yBase) < haloMin || getShoeDist(lx, yBase - loopH) < haloMin) {
        break;
      }
      // 3 control points per loop: bottom-right, top-arch, bottom-left crossover
      pts.push([lx, yBase + random(-0.8, 0.8), 0.7]);
      pts.push([lx + 3.2, yBase - loopH * random(0.8, 1.15), 1.15]);
      pts.push([lx + 1.4, yBase - loopH * 0.3, 0.6]);
      x = lx + 4.8;
    }

    if (pts.length >= 4) {
      brush.set(bName, bCol, wMult);
      brush.spline(pts, 0.65);
      // Occasional manic double-strike on dark gouged loops
      if (pressureWave > 0.76) {
        brush.set("bic_gouge", PAL.inkGouge, 0.85);
        brush.spline(pts.slice(0, Math.min(pts.length, 9)), 0.6);
      }
    }
    x += random(3, 8);
  }
}

function drawRuledScriptScanline(xStart, xEnd, yBase, charH, haloMin, seedOff) {
  let x = xStart;
  while (x < xEnd - 14) {
    let d = getShoeDist(x, yBase);
    if (d < haloMin) {
      x += 5;
      continue;
    }

    // Measure available span before hitting shoe halo or right edge
    let maxW = random(22, 68);
    let actualW = 0;
    while (actualW < maxW && (x + actualW) < xEnd) {
      if (getShoeDist(x + actualW, yBase) < haloMin || getShoeDist(x + actualW, yBase - charH) < haloMin) {
        break;
      }
      actualW += 3.5;
    }

    if (actualW >= 10) {
      let pVal = noise((x + seedOff) * 0.012, yBase * 0.018);
      // Vary pressure from ghostly to gouged
      let bName = "bic_med";
      let bCol = PAL.inkMid;
      let wMult = 0.85;
      if (pVal < 0.26) {
        bName = "bic_whisper"; bCol = PAL.inkWhisper; wMult = 0.65;
      } else if (pVal < 0.46) {
        bName = "bic_pastel"; bCol = PAL.inkPastel; wMult = 0.78;
      } else if (pVal < 0.62) {
        bName = "bic_pastel"; bCol = PAL.inkLavender; wMult = 0.85;
      } else if (pVal > 0.78) {
        bName = "bic_gouge"; bCol = PAL.inkGouge; wMult = 1.15;
      } else if (pVal > 0.66) {
        bName = "bic_heavy"; bCol = PAL.inkDeep; wMult = 1.0;
      }

      drawCrampedWord(x, yBase, actualW, charH, bName, bCol, wMult);

      // If right next to the sneaker halo, add a tiny compulsive bracket or stop-tick
      if (getShoeDist(x + actualW + 5, yBase) < haloMin + 3) {
        brush.set("bic_heavy", PAL.inkGouge, 0.95);
        brush.line(x + actualW + 1, yBase - charH * 1.1, x + actualW + 1, yBase + 2);
      }
      x += actualW + random(4, 10);
    } else {
      x += 6;
    }
  }
}

function drawCrampedWord(x, y, w, h, brushName, col, weight) {
  let nPeaks = Math.max(3, Math.floor(w / 3.6));
  let pts = [];
  let slant = random(1.2, 2.8);

  for (let i = 0; i < nPeaks; i++) {
    let cx = x + (i / nPeaks) * w;
    // Ascenders and descenders for authentic handwritten silhouette
    let isAsc = random() < 0.18;
    let isDesc = !isAsc && random() < 0.12;
    let topY = y - h * (isAsc ? random(1.45, 1.9) : random(0.65, 1.1));
    let botY = y + (isDesc ? h * random(0.55, 0.95) : random(-0.6, 1.2));

    pts.push([cx + slant, topY, random(0.45, 1.25)]);
    pts.push([cx + 1.8, botY, random(0.55, 1.35)]);
  }

  brush.set(brushName, col, weight);
  brush.spline(pts, 0.55);

  // Add t-crossbars and i-dots
  if (w > 18 && random() < 0.65) {
    let tx = x + random(0.2, 0.7) * w;
    brush.line(tx - 4, y - h * 1.15, tx + 6, y - h * 1.25);
  }
  if (random() < 0.5) {
    let dx = x + random(0.15, 0.85) * w;
    brush.line(dx, y - h * 1.35, dx + 1.2, y - h * 1.45);
  }
}

function drawRuledTallyScanline(xStart, xEnd, yTop, h, haloMin, rowIdx) {
  let x = xStart;
  while (x < xEnd - 24) {
    if (getShoeDist(x, yTop + h * 0.5) < haloMin || getShoeDist(x + 22, yTop + h * 0.5) < haloMin) {
      x += 6;
      continue;
    }
    if (random() < 0.78) {
      drawFiveTally(x, yTop, 21, h, haloMin);
      x += random(26, 33);
    } else {
      // Interleave a short cramped annotation or boxed number between tally sets
      drawCrampedWord(x, yTop + h * 0.75, 28, 7.5, "bic_heavy", PAL.inkDeep, 0.95);
      x += 34;
    }
  }
}

function drawTallyRegion(x1, y1, x2, y2, rowH, haloMin) {
  for (let y = y1; y < y2 - rowH; y += rowH + 5) {
    let x = x1;
    while (x < x2 - 22) {
      drawFiveTally(x, y, 18, rowH, haloMin);
      x += random(23, 28);
    }
  }
}

function drawPseudoScriptBlock(x1, y1, x2, y2, lineStep, haloMin) {
  let r = 0;
  for (let y = y1 + 8; y < y2; y += lineStep) {
    r++;
    drawRuledScriptScanline(x1, x2, y, 6.2, haloMin, r * 43);
  }
}

function drawFiveTally(x, y, w, h, haloMin) {
  if (getShoeDist(x, y) < haloMin || getShoeDist(x + w, y + h) < haloMin) return;

  let p = noise(x * 0.025, y * 0.025);
  let bName = p > 0.65 ? "bic_gouge" : (p < 0.32 ? "bic_pastel" : "bic_med");
  let col = p > 0.68 ? PAL.inkGouge : (p < 0.32 ? PAL.inkPastel : (p < 0.5 ? PAL.inkMid : PAL.inkDeep));
  let wt = map(p, 0, 1, 0.65, 1.3);

  brush.set(bName, col, wt);
  let step = w / 4.2;
  for (let i = 0; i < 4; i++) {
    let vx = x + i * step + random(-0.7, 0.7);
    let slant = random(-2.2, 1.5);
    brush.line(vx, y + random(-1.2, 1.2), vx + slant, y + h + random(-1.2, 1.2));
  }
  // 5th diagonal slash across the 4 vertical strokes
  brush.set(p > 0.5 ? "bic_heavy" : bName, p > 0.5 ? PAL.inkGouge : col, wt * 1.15);
  brush.line(x - 2.5, y + h * random(0.68, 0.85), x + w + 2.5, y + h * random(0.18, 0.35));
}

// =============================================================================
// TONAL HATCHING & SCRIBBLE MASS UTILITIES FOR SNEAKER REALISM
// =============================================================================

function multiHatchPoly(pts, specs) {
  let poly = new brush.Polygon(pts);
  for (let s of specs) {
    brush.hatchStyle(s.brush || "bic_med", s.color || PAL.inkMid, s.weight || 0.85);
    brush.hatch(s.dist || 4, s.angle || 30, {
      rand: s.rand !== undefined ? s.rand : 0.06,
      continuous: s.continuous !== undefined ? s.continuous : true,
      gradient: s.gradient || 0
    });
    poly.hatch(s.dist || 4, s.angle || 30, {
      rand: s.rand !== undefined ? s.rand : 0.06,
      continuous: s.continuous !== undefined ? s.continuous : true,
      gradient: s.gradient || 0
    });
    brush.noHatch();
  }
}

// Feverish ballpoint scribble shading along a spine curve
function scribbleAlongCurve(spinePts, widthStart, widthEnd, density, brushName, col, weight, loopAngle = 35) {
  brush.set(brushName, col, weight);
  let totalSteps = Math.max(8, Math.floor(density));
  let scribblePts = [];

  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    let pt = evalPolyline(spinePts, t);
    let tang = evalTangent(spinePts, t);
    let nx = -tang[1];
    let ny = tang[0];
    let w = lerp(widthStart, widthEnd, t) * (0.65 + 0.5 * sin(t * 180));

    let side = (i % 2 === 0) ? 1 : -1;
    let ox = nx * w * 0.5 * side + tang[0] * cos(i * loopAngle) * w * 0.22;
    let oy = ny * w * 0.5 * side + tang[1] * sin(i * loopAngle) * w * 0.22;
    scribblePts.push([
      pt[0] + ox + random(-1.2, 1.2),
      pt[1] + oy + random(-1.2, 1.2),
      random(0.45, 1.35)
    ]);

    // Commit in 24-point splines so WebGL buffers stay fast and crisp
    if (scribblePts.length >= 24) {
      brush.spline(scribblePts, 0.62);
      scribblePts = [scribblePts[scribblePts.length - 1]];
    }
  }
  if (scribblePts.length >= 3) {
    brush.spline(scribblePts, 0.62);
  }
}

// Form-following cross-contour hatch band between two boundary polylines
function contourHatchBetween(railA, railB, count, brushName, col, weight, curvature = 0.15) {
  brush.set(brushName, col, weight);
  for (let i = 0; i <= count; i++) {
    let t = i / count;
    let pA = evalPolyline(railA, t);
    let pB = evalPolyline(railB, t);
    let midX = (pA[0] + pB[0]) * 0.5;
    let midY = (pA[1] + pB[1]) * 0.5;
    let dx = pB[0] - pA[0];
    let dy = pB[1] - pA[1];
    let nx = -dy * curvature;
    let ny = dx * curvature;
    brush.spline([
      [pA[0] + random(-0.8, 0.8), pA[1] + random(-0.8, 0.8), random(0.3, 0.8)],
      [midX + nx + random(-0.8, 0.8), midY + ny + random(-0.8, 0.8), random(0.9, 1.35)],
      [pB[0] + random(-0.8, 0.8), pB[1] + random(-0.8, 0.8), random(0.3, 0.8)]
    ], 0.45);
  }
}

function evalPolyline(pts, t) {
  if (t <= 0) return pts[0];
  if (t >= 1) return pts[pts.length - 1];
  let idx = t * (pts.length - 1);
  let i = Math.floor(idx);
  let f = idx - i;
  let p1 = pts[i];
  let p2 = pts[Math.min(pts.length - 1, i + 1)];
  return [lerp(p1[0], p2[0], f), lerp(p1[1], p2[1], f)];
}

function evalTangent(pts, t) {
  let eps = 0.02;
  let p1 = evalPolyline(pts, Math.max(0, t - eps));
  let p2 = evalPolyline(pts, Math.min(1, t + eps));
  let dx = p2[0] - p1[0];
  let dy = p2[1] - p1[1];
  let len = Math.sqrt(dx * dx + dy * dy) || 1;
  return [dx / len, dy / len];
}

