    [[262, 704], [244, 712], [232, 708]],
    [[276, 728], [254, 742], [238, 748]],
    [[290, 726], [312, 718], [328, 722]],
    [[286, 755], [315, 762], [336, 758]],
    [[282, 782], [258, 792], [242, 790]]
  ];
  for (let bc of branchCracks) {
    brush.set("bic_gouge", PAL.inkAbyss, 1.05);
    brush.spline(bc.map(p => [p[0], p[1], 1.1]), 0.3);
    brush.set("paper_scratch", PAL.paperHighlight, 0.85);
    brush.spline(bc.map(p => [p[0] + 1, p[1] + 1, 0.8]), 0.3);
  }

  // 2. VULCANIZED RUBBER FOXING BAND (wrapping from toe to heel)
  const foxingTopRail = [
    [178, 755], [220, 788], [295, 812], [395, 822], [500, 822],
    [615, 815], [735, 802], [855, 784], [952, 764], [1012, 742]
  ];
  const foxingBotRail = [
    [180, 805], [218, 846], [300, 875], [410, 888], [530, 886],
    [665, 870], [790, 855], [912, 834], [982, 814], [1010, 795]
  ];
  const foxingPoly = [...foxingTopRail, ...foxingBotRail.slice().reverse()];

  multiHatchPoly(foxingPoly, [
    { brush: "bic_whisper", color: PAL.inkWhisper, weight: 0.85, dist: 3.6, angle: 82, rand: 0.05 },
    { brush: "bic_pastel", color: PAL.inkPastel, weight: 0.85, dist: 4.2, angle: -10, rand: 0.05 },
    { brush: "bic_med", color: PAL.inkMid, weight: 0.8, dist: 5.2, angle: 38, rand: 0.06, gradient: 0.5 }
  ]);

  // Cylindrical vertical contour shading across the rubber foxing wall
  contourHatchBetween(foxingTopRail, foxingBotRail, 95, "bic_pastel", PAL.inkMid, 0.72, 0.08);

  // Lower foxing bevel shadow (where the sole curves into the ground)
  scribbleAlongCurve(foxingBotRail, 18, 22, 140, "bic_heavy", PAL.inkDeep, 0.95, 32);
  scribbleAlongCurve(foxingBotRail, 8, 10, 110, "bic_gouge", PAL.inkGouge, 1.0, 20);

  // 3. TEXTURED DIAMOND WAFFLE TOE BUMPER (front of foxing: x = 178..385)
  const bumperTop = [[178, 755], [218, 782], [278, 804], [335, 814], [385, 818]];
  const bumperBot = [[180, 805], [218, 846], [282, 870], [338, 882], [382, 886]];

  // Peeling/separated top lip of the rubber toe bumper around x = 230..310
  brush.set("bic_gouge", PAL.inkAbyss, 1.2);
  brush.spline([[215, 780, 0.9], [255, 796, 1.4], [305, 810, 1.3], [350, 816, 0.8]], 0.4);
  brush.set("paper_scratch", PAL.paperHighlight, 1.1);
  brush.spline([[215, 782, 0.9], [255, 798, 1.2], [305, 812, 1.1], [350, 818, 0.8]], 0.4);

  // Waffle diamond cross-ridges on the toe bumper
  const nBumperCols = 26;
  for (let i = 0; i <= nBumperCols; i++) {
    let t1 = i / nBumperCols;
    let t2 = Math.min(1, (i + 2.2) / nBumperCols);
    let t3 = Math.max(0, (i - 2.2) / nBumperCols);

    let pTop = evalPolyline(bumperTop, t1);
    let pBotR = evalPolyline(bumperBot, t2);
    let pBotL = evalPolyline(bumperBot, t3);

    brush.set("bic_heavy", PAL.inkDeep, 0.9);
    brush.line(pTop[0], pTop[1], pBotR[0], pBotR[1]);
    brush.set("bic_med", PAL.inkMid, 0.85);
    brush.line(pTop[0], pTop[1], pBotL[0], pBotL[1]);

    // Highlight ridge alongside each diamond groove
    brush.set("paper_scratch", PAL.paperHighlight, 0.75);
    brush.line(pTop[0] + 1.2, pTop[1], pBotR[0] + 1.2, pBotR[1]);
  }

  // 4. TWO CLASSIC FOXING RACING STRIPES (warped, scuffed & cracked along the sole)
  // Upper foxing stripe (runs along top border of foxing from x = 380 to 1012)
  const stripe1Pts = [];
  const stripe2Pts = [];
  for (let i = 0; i <= 36; i++) {
    let t = i / 36;
    let pT = evalPolyline(foxingTopRail, t);
    let pB = evalPolyline(foxingBotRail, t);
    if (pT[0] >= 375) {
      stripe1Pts.push([lerp(pT[0], pB[0], 0.14), lerp(pT[1], pB[1], 0.14)]);
    }
    if (pT[0] >= 380) {
      stripe2Pts.push([lerp(pT[0], pB[0], 0.52), lerp(pT[1], pB[1], 0.52)]);
    }
  }

  // Draw thick ballpoint racing stripes with scuffed gaps
  for (let sp of [stripe1Pts, stripe2Pts]) {
    for (let offset of [-1.6, 0, 1.6]) {
      brush.set("bic_gouge", PAL.inkGouge, 1.05);
      let sPts = sp.map(p => [p[0], p[1] + offset, random(0.6, 1.4)]);
      brush.spline(sPts, 0.35);
    }
  }

  // 5. DRIED MUD CRUSTS & POLYGONAL MUD CRACKS (along foxing, arch & lower canvas)
  drawMudCracksAndCrusts();
}

function drawMudCracksAndCrusts() {
  // Mud crust patches caked onto the rubber foxing and splashing up onto the lower canvas
  const mudZones = [
    { cx: 435, cy: 848, rx: 58, ry: 28, count: 16 },
    { cx: 565, cy: 846, rx: 68, ry: 32, count: 20 },
    { cx: 695, cy: 832, rx: 62, ry: 30, count: 18 },
    { cx: 835, cy: 812, rx: 64, ry: 28, count: 18 },
    { cx: 955, cy: 785, rx: 45, ry: 26, count: 14 },
    // Mud splatters higher on the canvas & toe bumper
    { cx: 320, cy: 845, rx: 48, ry: 24, count: 14 },
    { cx: 515, cy: 792, rx: 42, ry: 20, count: 12 },
    { cx: 760, cy: 772, rx: 46, ry: 18, count: 12 }
  ];

  for (let mz of mudZones) {
    // 1. Scribbled dried-mud tonal crust
    let mudSpine = [
      [mz.cx - mz.rx * 0.8, mz.cy + random(-4, 4)],
      [mz.cx, mz.cy + random(-5, 5)],
      [mz.cx + mz.rx * 0.8, mz.cy + random(-4, 4)]
    ];
    scribbleAlongCurve(mudSpine, mz.ry * 1.1, mz.ry * 0.9, 42, "bic_med", PAL.inkMid, 0.85, 45);
    scribbleAlongCurve(mudSpine, mz.ry * 0.7, mz.ry * 0.6, 28, "bic_heavy", PAL.inkDeep, 0.8, 30);

    // 2. Polygonal / branching mud-crack fissures cutting through the crust
    for (let c = 0; c < mz.count; c++) {
      let sx = mz.cx + random(-mz.rx * 0.85, mz.rx * 0.85);
      let sy = mz.cy + random(-mz.ry * 0.75, mz.ry * 0.75);
      let crackPts = [[sx, sy, 1.0]];
      let ang = random(360);
      let segs = Math.floor(random(3, 6));
      for (let s = 0; s < segs; s++) {
        ang += random(-55, 55);
        let step = random(6, 15);
        sx += cos(ang) * step;
        sy += sin(ang) * step * 0.65;
        crackPts.push([sx, sy, random(0.8, 1.4)]);
      }

      // Gouged dark mud fissure
      brush.set("bic_gouge", PAL.inkAbyss, 1.05);
      brush.spline(crackPts, 0.25);

      // Raised flaking mud-edge highlight right next to the fissure
      brush.set("paper_scratch", PAL.paperHighlight, 0.9);
      brush.spline(crackPts.map(p => [p[0] + 1.1, p[1] - 1.1, 0.8]), 0.25);
    }

    // 3. Tiny spattered mud dots & dried crumbs around the crust perimeter
    brush.set("bic_heavy", PAL.inkDeep, 0.95);
    for (let d = 0; d < 14; d++) {
      let dx = mz.cx + random(-mz.rx * 1.15, mz.rx * 1.15);
      let dy = mz.cy + random(-mz.ry * 1.15, mz.ry * 1.15);
      brush.line(dx, dy, dx + random(1.5, 3.5), dy + random(-1.5, 1.5));
    }
  }
}

// =============================================================================
// LAYER 6: ANKLE STAR PATCH, METAL VENT GROMMETS & DOUBLE STITCHING
