function drawPatchGrommetsAndStitching() {
  // 1. CIRCULAR ANKLE STAR PATCH (centered at 838, 558, warped slightly by canvas crease)
  const px = 838, py = 558, rx = 50, ry = 54;

  // Patch base circle (slightly lighter canvas/rubber disk with worn edges)
  let patchPts = [];
  for (let a = 0; a < 360; a += 15) {
    let warp = sin(a * 2) * 2.2;
    patchPts.push([px + cos(a) * (rx + warp), py + sin(a) * (ry + warp)]);
  }
  multiHatchPoly(patchPts, [
    { brush: "bic_whisper", color: PAL.inkWhisper, weight: 0.7, dist: 3.8, angle: 20, rand: 0.04 },
    { brush: "bic_pastel", color: PAL.inkPastel, weight: 0.65, dist: 5.5, angle: -70, rand: 0.05, gradient: 0.5 }
  ]);

  // Outer & inner circular rings of the patch
  brush.set("bic_heavy", PAL.inkDeep, 0.95);
  brush.circle(px, py, rx, 0.12);
  brush.set("bic_med", PAL.inkMid, 0.85);
  brush.circle(px, py, rx * 0.82, 0.1);

  // Perimeter stitch dashes around the ankle patch
  brush.set("bic_gouge", PAL.inkGouge, 0.9);
  for (let a = 0; a < 360; a += 9) {
    let a1 = a, a2 = a + 5;
    let rStitch = rx * 0.93;
    brush.line(
      px + cos(a1) * rStitch, py + sin(a1) * (ry * 0.93),
      px + cos(a2) * rStitch, py + sin(a2) * (ry * 0.93)
    );
  }

  // Classic 5-pointed star in the center of the ankle patch
  let starPts = [];
  for (let i = 0; i < 10; i++) {
    let a = -90 + i * 36 - 6; // tilted slightly with shoe posture
    let r = (i % 2 === 0) ? 28 : 11.5;
    starPts.push([px + cos(a) * r, py + sin(a) * (r * 1.06)]);
  }
  multiHatchPoly(starPts, [
    { brush: "bic_med", color: PAL.inkMid, weight: 0.95, dist: 2.0, angle: -25, rand: 0.04 },
    { brush: "bic_heavy", color: PAL.inkDeep, weight: 1.0, dist: 2.2, angle: 45, rand: 0.04 },
    { brush: "bic_gouge", color: PAL.inkGouge, weight: 0.95, dist: 2.8, angle: 85, rand: 0.05 }
  ]);
  brush.set("bic_gouge", PAL.inkGouge, 0.95);
  for (let i = 0; i < 10; i++) {
    let p1 = starPts[i], p2 = starPts[(i + 1) % 10];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Scuffed micro-lettering arcs inside the patch ring
  brush.set("bic_med", PAL.inkDeep, 0.75);
  for (let a = -150; a <= -30; a += 8) {
    let r1 = 31, r2 = 36;
    brush.line(px + cos(a) * r1, py + sin(a) * r1, px + cos(a + 3) * r2, py + sin(a + 3) * r2);
  }
  for (let a = 35; a <= 145; a += 9) {
    let r1 = 31, r2 = 36;
    brush.line(px + cos(a) * r1, py + sin(a) * r1, px + cos(a + 3) * r2, py + sin(a + 3) * r2);
  }

  // Crease shadow cutting across the lower half of the patch
  scribbleAlongCurve([[785, 572], [838, 568], [892, 558]], 10, 8, 35, "bic_heavy", PAL.inkDeep, 0.85, 25);

  // 2. TWO METAL VENTILATION GROMMETS ABOVE THE ARCH
  const grommets = [[582, 758], [646, 748]];
  for (let g of grommets) {
    drawMetalEyeletOrGrommet(g[0], g[1], 11.5, 5.2, true);
    // Tarnish/water streak below grommet
    scribbleAlongCurve([[g[0], g[1] + 11], [g[0] - 2, g[1] + 32]], 6, 3, 14, "bic_pastel", PAL.inkMid, 0.75, 20);
  }

  // 3. DOUBLE-STITCHED STRUCTURAL SEAMS ACROSS THE SNEAKER
  // Toe cap curved canvas seam
  const toeSeam1 = [[438, 820], [430, 758], [412, 700]];
  const toeSeam2 = [[446, 820], [438, 756], [420, 696]];
  drawStitchRow(toeSeam1, 22);
  drawStitchRow(toeSeam2, 22);

  // Curved arch reinforcement stitching (classic Chuck half-moon stitch above vent grommets)
  const archStitch1 = [[522, 818], [545, 725], [610, 695], [678, 718], [705, 804]];
  const archStitch2 = [[530, 818], [552, 732], [610, 703], [670, 725], [697, 805]];
  drawStitchRow(archStitch1, 38);
  drawStitchRow(archStitch2, 36);

  // Eyestay double stitch rows
  const eyestayStitch1 = [[436, 722], [472, 686], [538, 610], [612, 518], [685, 426], [748, 340]];
  const eyestayStitch2 = [[443, 726], [479, 690], [545, 614], [619, 522], [692, 430], [755, 344]];
  drawStitchRow(eyestayStitch1, 56);
  drawStitchRow(eyestayStitch2, 56);

  // Back heel strip double stitch rows
  const heelStitch1 = [[940, 360], [956, 478], [974, 608], [986, 748]];
  const heelStitch2 = [[947, 360], [963, 478], [981, 608], [993, 746]];
  drawStitchRow(heelStitch1, 46);
  drawStitchRow(heelStitch2, 46);

  // Top ankle collar binding seam + frayed collar threads
  const collarRim = [[725, 328], [795, 355], [880, 372], [958, 360]];
  drawStitchRow(collarRim, 34);
  drawStitchRow(collarRim.map(p => [p[0], p[1] + 6]), 34);

  // Frayed canvas threads erupting along the worn ankle collar, tongue top, and heel seam
  drawFrayedEdgeBurst(collarRim, 48, 8, 22, -75);
  drawFrayedEdgeBurst([[635, 255], [685, 246], [735, 262]], 42, 7, 19, -90);
  drawFrayedEdgeBurst(heelStitch1, 32, 6, 16, 15);
}

function drawStitchRow(railPts, numStitches) {
  // Subtle recessed groove line where thread pulls into canvas
  brush.set("bic_pastel", PAL.inkMid, 0.75);
  brush.spline(railPts.map(p => [p[0], p[1], 0.8]), 0.35);

  for (let i = 0; i < numStitches; i++) {
    let t1 = (i + 0.15) / numStitches;
    let t2 = (i + 0.78) / numStitches;
    let p1 = evalPolyline(railPts, t1);
    let p2 = evalPolyline(railPts, t2);

    // Dark needle puncture hole at each end of the stitch
    brush.set("bic_gouge", PAL.inkAbyss, 0.95);
    brush.line(p1[0], p1[1], p1[0] + 1, p1[1] + 1);

    // Individual cotton stitch thread (highlight top + shadow bottom)
    brush.set("bic_heavy", PAL.inkGouge, 0.9);
    brush.line(p1[0], p1[1] + 0.8, p2[0], p2[1] + 0.8);
    brush.set("paper_scratch", PAL.paperHighlight, 0.85);
    brush.line(p1[0], p1[1] - 0.5, p2[0], p2[1] - 0.5);
  }
}

function drawFrayedEdgeBurst(railPts, count, minLen, maxLen, baseAngle) {
  for (let i = 0; i < count; i++) {
    let t = random(0, 1);
    let p = evalPolyline(railPts, t);
    let ang = baseAngle + random(-48, 48);
    let len = random(minLen, maxLen);
    let midX = p[0] + cos(ang) * len * 0.5 + random(-3, 3);
    let midY = p[1] + sin(ang) * len * 0.5 + random(-3, 3);
    let endX = p[0] + cos(ang) * len + random(-5, 5);
    let endY = p[1] + sin(ang) * len + random(-5, 5);

    brush.set(random() < 0.4 ? "bic_med" : "bic_pastel", random() < 0.5 ? PAL.inkDeep : PAL.inkMid, random(0.55, 0.95));
    brush.spline([[p[0], p[1], 1.1], [midX, midY, 0.8], [endX, endY, 0.25]], 0.55);
  }
}

function drawMetalEyeletOrGrommet(cx, cy, outerR, innerR, isDarkHole = true) {
  // Cast shadow under the metallic washer ring
  brush.set("bic_gouge", PAL.inkAbyss, 1.05);
  brush.arc(cx + 1.5, cy + 2.0, outerR, 10, 195);

  // Metallic washer body hatched in ballpoint
  let ringPts = [];
  for (let a = 0; a < 360; a += 30) {
    ringPts.push([cx + cos(a) * outerR, cy + sin(a) * outerR]);
  }
  multiHatchPoly(ringPts, [
    { brush: "bic_pastel", color: PAL.inkPastel, weight: 0.8, dist: 2.2, angle: -35, rand: 0.04 },
    { brush: "bic_med", color: PAL.inkDeep, weight: 0.85, dist: 3.0, angle: 55, rand: 0.05 }
  ]);

  // Outer & inner rim outlines
  brush.set("bic_heavy", PAL.inkGouge, 0.95);
  brush.circle(cx, cy, outerR, 0.08);
  brush.circle(cx, cy, innerR, 0.08);

  // Specular metallic highlight arc on upper-left of washer
  brush.set("paper_scratch", PAL.paperHighlight, 1.3);
  brush.arc(cx - 0.8, cy - 0.8, (outerR + innerR) * 0.5, 195, 330);

  if (isDarkHole) {
    // Deep gouged shadow inside hole
    let holePts = [];
    for (let a = 0; a < 360; a += 40) {
      holePts.push([cx + cos(a) * innerR, cy + sin(a) * innerR]);
    }
    multiHatchPoly(holePts, [
      { brush: "bic_gouge", color: PAL.inkAbyss, weight: 1.2, dist: 1.4, angle: 20, rand: 0.02 },
      { brush: "bic_gouge", color: PAL.inkAbyss, weight: 1.2, dist: 1.4, angle: 110, rand: 0.02 }
    ]);
  }
}

