function drawEyeletsAndFrayedLaces() {
  // 7 pairs of eyelets running up the throat
  const latEyelets = [
    [428, 690], [468, 642], [514, 588], [562, 530],
    [612, 470], [664, 408], [716, 346]
  ];
  const medEyelets = [
    [365, 650], [402, 602], [446, 548], [492, 490],
    [540, 430], [590, 368], [638, 308]
  ];

  // Draw the metal eyelets first
  for (let e of latEyelets) {
    drawMetalEyeletOrGrommet(e[0], e[1], 10.5, 4.8, true);
  }
  for (let e of medEyelets) {
    drawMetalEyeletOrGrommet(e[0], e[1], 9.0, 4.2, true);
  }

  // Criss-crossing flat woven cotton laces between medial and lateral eyelets
  // Bottom bar (Med 0 -> Lat 0)
  drawWovenLaceBand(medEyelets[0], latEyelets[0], 12, -8, false);

  // Crossovers climbing up the throat
  for (let i = 0; i < 6; i++) {
    // Under-crossing: Lat[i] -> Med[i+1]
    drawWovenLaceBand(latEyelets[i], medEyelets[i + 1], 12.5, -10, i === 2);
    // Over-crossing: Med[i] -> Lat[i+1]
    drawWovenLaceBand(medEyelets[i], latEyelets[i + 1], 13.0, 12, i === 3);
  }

  // *** LONG BROKEN / UNTIED LACE TRAILING DOWN ONTO THE FLOOR ***
  // Emerges from lateral eyelet 5 (612, 470), drapes down over the side of the shoe
  // and pools on the notebook paper at (345, 912) with a shattered aglet and frayed burst!
  const trailingLaceSpine = [
    [612, 470], [568, 545], [532, 640], [495, 745],
    [455, 835], [408, 896], [352, 912]
  ];
  drawTrailingLaceSpline(trailingLaceSpine, 11.5);

  // Shattered plastic aglet & exploded frayed cotton fibers at the tip (352, 912)
  drawFrayedLaceTip([352, 912], 195, 75, 36);

  // *** MESSY KNOTTED BOW & FRAYED LOOPS AT TOP ANKLE (around 675, 325) ***
  // Center knot bundle
  scribbleAlongCurve([[662, 322], [685, 330], [702, 338]], 22, 18, 45, "bic_heavy", PAL.inkDeep, 1.0, 40);
  scribbleAlongCurve([[668, 325], [690, 334]], 14, 12, 30, "bic_gouge", PAL.inkGouge, 1.05, 25);

  // Upper-right bow loop (drooping over the collar)
  const bowLoop1 = [[685, 328], [745, 295], [805, 292], [818, 315], [765, 332], [692, 334]];
  drawTrailingLaceSpline(bowLoop1, 10.5);

  // Upper-left bow loop
  const bowLoop2 = [[675, 325], [615, 285], [565, 282], [558, 305], [612, 322], [672, 330]];
  drawTrailingLaceSpline(bowLoop2, 10.0);

  // Short frayed loose lace end sticking out from the top knot toward (785, 415)
  const topLooseEnd = [[692, 335], [738, 368], [775, 412]];
  drawTrailingLaceSpline(topLooseEnd, 10.5);
  drawFrayedLaceTip([775, 412], 48, 65, 32);
}

function drawWovenLaceBand(p1, p2, bandW, archSag, isFrayedMid) {
  let midX = (p1[0] + p2[0]) * 0.5;
  let midY = (p1[1] + p2[1]) * 0.5 + archSag;
  let dx = p2[0] - p1[0];
  let dy = p2[1] - p1[1];
  let len = Math.sqrt(dx * dx + dy * dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;
  let hw = bandW * 0.5;

  // 1. Cast shadow directly beneath the lace onto the tongue/eyestay
  brush.set("bic_gouge", PAL.inkAbyss, 1.15);
  brush.spline([
    [p1[0] + nx * (hw + 2), p1[1] + ny * (hw + 2) + 3, 0.9],
    [midX + nx * (hw + 3), midY + ny * (hw + 3) + 4, 1.35],
    [p2[0] + nx * (hw + 2), p2[1] + ny * (hw + 2) + 3, 0.9]
  ], 0.45);
  brush.set("bic_heavy", PAL.inkDeep, 0.95);
  brush.spline([
    [p1[0] + nx * (hw + 5), p1[1] + ny * (hw + 5) + 5, 0.7],
    [midX + nx * (hw + 6), midY + ny * (hw + 6) + 6, 1.1],
    [p2[0] + nx * (hw + 5), p2[1] + ny * (hw + 5) + 5, 0.7]
  ], 0.45);

  // 2. Opaque paper-cream base wash so the top lace covers underlying lines cleanly
  let lacePoly = [
    [p1[0] - nx * hw, p1[1] - ny * hw],
    [midX - nx * hw, midY - ny * hw],
    [p2[0] - nx * hw, p2[1] - ny * hw],
    [p2[0] + nx * hw, p2[1] + ny * hw],
    [midX + nx * hw, midY + ny * hw],
    [p1[0] + nx * hw, p1[1] + ny * hw]
  ];
  brush.noStroke();
  brush.wash(PAL.paperBase, 235);
  brush.beginShape(0.3);
  for (let pt of lacePoly) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noWash();

  // 3. Woven cotton texture inside the lace band
  multiHatchPoly(lacePoly, [
    { brush: "bic_whisper", color: PAL.inkPastel, weight: 0.8, dist: 2.6, angle: atan2(dy, dx) + 25, rand: 0.04 },
    { brush: "bic_pastel", color: PAL.inkMid, weight: 0.75, dist: 3.2, angle: atan2(dy, dx) - 25, rand: 0.04 }
  ]);

  // Lengthwise cotton weave ribs
  for (let r = -0.75; r <= 0.75; r += 0.375) {
    let isShadowEdge = r > 0.3;
    brush.set(isShadowEdge ? "bic_heavy" : "bic_pastel", isShadowEdge ? PAL.inkDeep : PAL.inkMid, isShadowEdge ? 0.9 : 0.7);
    brush.spline([
      [p1[0] + nx * hw * r, p1[1] + ny * hw * r, 0.9],
      [midX + nx * hw * r, midY + ny * hw * r, 1.1],
      [p2[0] + nx * hw * r, p2[1] + ny * hw * r, 0.9]
    ], 0.45);
  }

  // Outer borders of the lace band
  brush.set("bic_gouge", PAL.inkGouge, 0.95);
  brush.spline([[p1[0] - nx * hw, p1[1] - ny * hw, 1.0], [midX - nx * hw, midY - ny * hw, 1.1], [p2[0] - nx * hw, p2[1] - ny * hw, 1.0]], 0.45);
  brush.spline([[p1[0] + nx * hw, p1[1] + ny * hw, 1.1], [midX + nx * hw, midY + ny * hw, 1.3], [p2[0] + nx * hw, p2[1] + ny * hw, 1.1]], 0.45);

  // If this span is chewed/abraded, burst fine frayed cotton hairs from its edges
  if (isFrayedMid) {
    for (let k = 0; k < 28; k++) {
      let t = random(0.2, 0.8);
      let bx = lerp(p1[0], p2[0], t);
      let by = lerp(p1[1], p2[1], t) + archSag * sin(t * 180);
      let a = atan2(ny, nx) + (random() < 0.5 ? 0 : 180) + random(-45, 45);
      let flen = random(7, 19);
      brush.set("bic_med", PAL.inkDeep, random(0.6, 0.95));
      brush.spline([
        [bx, by, 1.0],
        [bx + cos(a) * flen * 0.5, by + sin(a) * flen * 0.5, 0.7],
        [bx + cos(a) * flen, by + sin(a) * flen, 0.2]
      ], 0.5);
    }
  }
}

function drawTrailingLaceSpline(spine, width) {
  let hw = width * 0.5;
  let leftRail = [];
  let rightRail = [];
  const steps = 28;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = evalPolyline(spine, t);
    let tang = evalTangent(spine, t);
    let nx = -tang[1];
    let ny = tang[0];
    // Natural twist pinch along the loose lace
    let twist = hw * (0.65 + 0.35 * Math.abs(cos(t * 260)));
    leftRail.push([p[0] - nx * twist, p[1] - ny * twist]);
    rightRail.push([p[0] + nx * twist, p[1] + ny * twist]);
  }

  // Cast shadow next to the trailing lace
  brush.set("bic_gouge", PAL.inkAbyss, 1.1);
  brush.spline(rightRail.map(p => [p[0] + 3, p[1] + 4, 1.1]), 0.45);
  brush.set("bic_heavy", PAL.inkDeep, 0.9);
  brush.spline(rightRail.map(p => [p[0] + 6, p[1] + 6, 0.8]), 0.45);

  // Opaque paper wash inside lace
  let polyPts = [...leftRail, ...rightRail.slice().reverse()];
  brush.noStroke();
  brush.wash(PAL.paperBase, 235);
  brush.beginShape(0.25);
  for (let pt of polyPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noWash();

  // Cross-weave hatching along the trailing lace
  contourHatchBetween(leftRail, rightRail, 42, "bic_pastel", PAL.inkMid, 0.75, 0.15);

  // Longitudinal ribs & borders
  brush.set("bic_med", PAL.inkMid, 0.85);
  brush.spline(spine.map(p => [p[0], p[1], 0.95]), 0.45);
  brush.set("bic_gouge", PAL.inkGouge, 1.0);
  brush.spline(leftRail.map(p => [p[0], p[1], 1.0]), 0.45);
  brush.spline(rightRail.map(p => [p[0], p[1], 1.15]), 0.45);

  // Loose fuzz hairs along the trailing lace
  drawFrayedEdgeBurst(leftRail, 24, 5, 13, -120);
  drawFrayedEdgeBurst(rightRail, 24, 5, 13, 60);
}

function drawFrayedLaceTip(tipPt, baseDir, numThreads, maxLen) {
  // Cracked/split aglet collar right before the frayed explosion
  let bx = tipPt[0] - cos(baseDir) * 14;
  let by = tipPt[1] - sin(baseDir) * 14;
  brush.set("bic_gouge", PAL.inkAbyss, 1.15);
  brush.line(bx, by - 5, tipPt[0], tipPt[1] - 4);
  brush.line(bx, by + 5, tipPt[0], tipPt[1] + 4);

  // Fan of individual unraveled cotton threads
  for (let i = 0; i < numThreads; i++) {
    let spread = map(i, 0, numThreads - 1, -68, 68) + random(-8, 8);
    let ang = baseDir + spread;
    let len = random(maxLen * 0.35, maxLen);
    let curl = random(-35, 35);

    let p1 = [tipPt[0] + random(-2, 2), tipPt[1] + random(-2, 2), 1.2];
    let p2 = [
      tipPt[0] + cos(ang) * len * 0.5,
      tipPt[1] + sin(ang) * len * 0.5,
      0.85
    ];
    let p3 = [
      p2[0] + cos(ang + curl) * len * 0.5,
      p2[1] + sin(ang + curl) * len * 0.5,
      0.25
    ];

    let isDark = i % 3 === 0;
    brush.set(isDark ? "bic_heavy" : "bic_pastel", isDark ? PAL.inkGouge : PAL.inkMid, random(0.55, 1.05));
    brush.spline([p1, p2, p3], 0.6);
  }
}

