// ============================================================================
// 3D BOOK PAGE SURFACE & LENS GEOMETRY HELPERS
// ============================================================================

// Left page parameterized by u in [0..1] (left edge to gutter) and v in [0..1] (top to bottom)
function leftPagePt(u, v) {
  const xTop = lerp(-75, 524, u);
  const xBot = lerp(-15, 622, u);
  const yTop = lerp(612, 558, u);
  const yBot = lerp(1170, 1088, u);

  let x = lerp(xTop, xBot, v);
  let y = lerp(yTop, yBot, v);

  // 3D page arch: rises smoothly from left edge, crests at u ~ 0.68, plunges into gutter at u = 1
  const archProfile = Math.sin(Math.pow(u, 0.78) * 180) * Math.pow(u, 0.28);
  const archHeight = lerp(46, 82, v);
  y -= archProfile * archHeight;
  x += archProfile * lerp(-6, -12, v);

  return { x, y };
}

// Right page parameterized by u in [0..1] (gutter to right edge) and v in [0..1] (top to bottom)
function rightPagePt(u, v) {
  const xTop = lerp(524, 1125, u);
  const xBot = lerp(622, 1248, u);
  const yTop = lerp(558, 492, u);
  const yBot = lerp(1088, 982, u);

  let x = lerp(xTop, xBot, v);
  let y = lerp(yTop, yBot, v);

  // 3D page arch: climbs steeply out of gutter (u = 0), peaks around u = 0.34, relaxes toward u = 1
  const archProfile = Math.sin(Math.pow(1 - u, 0.75) * 180) * Math.pow(1 - u, 0.25);
  const archHeight = lerp(52, 92, v);
  y -= archProfile * archHeight;
  x += archProfile * lerp(8, 15, v);

  return { x, y };
}

// Parametric P3 / Pantos rounded-keyhole lens shape
function getLensPoint(lens, angleDeg, radialScaleX = 1.0, radialScaleY = 1.0) {
  const c = cos(angleDeg);
  const s = sin(angleDeg);

  // Classic P3 optical lens shaping: slightly flatter brow, fuller nasal/temporal upper corners, tapered lower cheek
  let rMod = 1.0;
  if (s < 0) {
    // Upper brow contour
    rMod = 1.0 - 0.06 * Math.pow(Math.abs(s), 1.6) + 0.05 * Math.pow(c * s, 2) * 4;
  } else {
    // Lower rim contour (gentle P3 taper)
    rMod = 1.0 - 0.08 * Math.pow(s, 2.2) - 0.04 * Math.pow(c, 2) * s;
  }

  const lx = c * lens.rx * radialScaleX * rMod;
  const ly = s * lens.ry * radialScaleY * rMod;

  const ct = cos(lens.tilt);
  const st = sin(lens.tilt);

  return {
    x: lens.cx + lx * ct - ly * st,
    y: lens.cy + lx * st + ly * ct
  };
}

// Outer tortoiseshell rim point around a lens
function getOuterRimPoint(lens, angleDeg, isLeft) {
  const c = cos(angleDeg);
  const s = sin(angleDeg);

  // Acetate frame thickness varies around the perimeter (thicker at brow, keyhole bridge, and temple lug)
  const browBoost = s < 0 ? 0.16 * Math.pow(Math.abs(s), 0.9) : 0.115;
  const lugSide = isLeft ? -c : c; // +1 towards outer temple lug, -1 towards nasal bridge
  const lugBoost = lugSide > 0.55 && s < 0.25 && s > -0.65
    ? 0.22 * Math.pow((lugSide - 0.55) / 0.45, 1.3)
    : 0;
  const bridgeBoost = lugSide < -0.55 && s < 0.05 && s > -0.75
    ? 0.12 * Math.pow((-lugSide - 0.55) / 0.45, 1.2)
    : 0;

  const scaleX = 1.155 + lugBoost + bridgeBoost;
  const scaleY = 1.165 + browBoost;

  const pt = getLensPoint(lens, angleDeg, scaleX, scaleY);
  // Shift outer rim slightly upward in y for brow profile
  pt.y -= s < 0 ? 3.5 * Math.abs(s) : -1.5 * s;
  return pt;
}

// Check if a canvas point (x, y) lies inside a lens, and return normalized optical coordinates
function getLensOpticalInfo(x, y, lens) {
  const dx = x - lens.cx;
  const dy = y - lens.cy;
  const ct = cos(-lens.tilt);
  const st = sin(-lens.tilt);
  const lx = dx * ct - dy * st;
  const ly = dx * st + dy * ct;

  const angleDeg = atan2(ly / lens.ry, lx / lens.rx);
  const boundary = getLensPoint(lens, angleDeg, 1.0, 1.0);
  const bdx = boundary.x - lens.cx;
  const bdy = boundary.y - lens.cy;
  const maxRSq = bdx * bdx + bdy * bdy;
  const curRSq = dx * dx + dy * dy;
  const normR = Math.sqrt(curRSq / Math.max(1, maxRSq));

  return {
    inside: normR < 0.985,
    normR,
    lx,
    ly
  };
}

// Draw a smooth closed shape from an array of {x, y} points
function drawClosedCurve(pts, curvature = 0.45) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
}

