function drawHardbackBookBase() {
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.28, 0.18);

  // Warm tabletop surface visible at bottom-right corner beneath the book
  brush.fill("#d5cfc3", 150);
  drawClosedCurve([
    { x: 580, y: 1120 },
    { x: 1260, y: 970 },
    { x: 1260, y: 1250 },
    { x: 540, y: 1250 }
  ], 0.1);

