  brush.fill("#8c8478", 135);
  drawClosedCurve([
    { x: 615, y: 1155 },
    { x: 1260, y: 1035 },
    { x: 1260, y: 1110 },
    { x: 615, y: 1215 }
  ], 0.2);

  // Left Page creamy fibrous paper base polygon
