function drawPageShadingAndFibers() {
  // 1. Continuous 3D contour graphite shading down the gutter valley
  for (let i = 0; i < 110; i++) {
    const v = i / 109;
    // Focus sharpness weight
    const yApprox = lerp(558, 1088, v);
    const dof = constrain(Math.abs(yApprox - 785) / 260, 0, 1);

    // Left page slope into gutter (u: 0.62 -> 1.0)
    const uStartL = random(0.60, 0.88);
    const ptsL = [];
    for (let s = 0; s <= 6; s++) {
      const u = lerp(uStartL, 1.0, s / 6);
      ptsL.push(leftPagePt(u, v + random(-0.003, 0.003)));
    }
    brush.set(dof < 0.45 ? "2H" : "HB", "#9e9689", lerp(0.32, 0.6, dof));
    brush.spline(ptsL.map(p => [p.x, p.y]), 0.4);

    // Right page steep rise out of gutter (u: 0.0 -> 0.18)
    const uEndR = random(0.05, 0.19);
    const ptsR = [];
    for (let s = 0; s <= 5; s++) {
      const u = lerp(0.0, uEndR, s / 5);
      ptsR.push(rightPagePt(u, v + random(-0.003, 0.003)));
    }
    brush.set(dof < 0.45 ? "2H" : "HB", "#aba396", lerp(0.3, 0.55, dof));
    brush.spline(ptsR.map(p => [p.x, p.y]), 0.4);
  }

  // Crisp centre gutter crease line
  const gutterPts = [];
  for (let i = 0; i <= 24; i++) {
    const p = leftPagePt(1.0, i / 24);
    gutterPts.push([p.x, p.y]);
  }
  brush.set("2B", "#6e665c", 0.55);
  brush.spline(gutterPts, 0.3);

  // 2. Fibrous cotton-rag paper texture in the sharp focal plane (y ~ 630..960)
  // Hundreds of delicate interwoven cellulose fibers, warm buff flecks, and subtle laid-paper lines
  for (let i = 0; i < 420; i++) {
    const onRight = random() < 0.54;
    const u = random(0.04, 0.96);
    // Concentrate fiber crispness in the focal zone around v = 0.22..0.78
    const v = constrain(randomGaussian(0.46, 0.22), 0.03, 0.97);
    const p1 = onRight ? rightPagePt(u, v) : leftPagePt(u, v);

    const distFromFocus = Math.abs(p1.y - 780);
    if (distFromFocus > 260 && random() < 0.65) continue;

    const len = random(6, 22);
    const ang = random(-18, 18) + (onRight ? -8 : 6);
    const p2 = {
      x: p1.x + cos(ang) * len,
      y: p1.y + sin(ang) * len
    };

    const fiberColors = ["#d8d1c3", "#cfc7b8", "#e5dfd2", "#c4bcad"];
    brush.set("paper_fiber", random(fiberColors), random(0.5, 1.0));
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Subtle laid-paper chain lines running vertically down the pages
  for (let c = 1; c <= 9; c++) {
    const u = c / 10;
    const chainL = [];
    const chainR = [];
    for (let s = 0; s <= 14; s++) {
      const v = s / 14;
      const pl = leftPagePt(u, v);
      const pr = rightPagePt(u, v);
      chainL.push([pl.x, pl.y]);
      chainR.push([pr.x, pr.y]);
    }
    brush.set("paper_fiber", "#ded8ca", 0.45);
    brush.spline(chainL, 0.3);
    brush.spline(chainR, 0.3);
  }
}

function drawPageBlockEdgesAndBinding() {
  const blockThickness = 56;

  // 1. Bottom page block thickness (sheaf of compressed pages beneath Left & Right pages)
