// ============================================================================
// 4. CAST SHADOWS & OPTICAL LENS CAUSTICS ON THE BOOK PAGES
// ============================================================================

function drawGlassesCastShadowsAndCaustics() {
  // Morning window light comes from behind/upper-left, projecting shadows forward (+y) and slightly right (+x)
  const shDx = 16;
  const shDy = 36;

  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.25, 0.15);

  // 1. Soft refracted lens shadow + bright optical caustic ring inside each lens projection
  const lenses = [
    { lens: LEFT_LENS, isLeft: true },
    { lens: RIGHT_LENS, isLeft: false }
  ];

  for (const item of lenses) {
    const L = item.lens;

    // Outer shadow of the frame rim on the page
    const outerSh = [];
    for (let a = 0; a < 360; a += 12) {
      const p = getOuterRimPoint(L, a, item.isLeft);
      // Lower rim (a ~ 60..120) touches the paper directly, so shadow offset is smaller there!
      const contactFactor = map(sin(a), -1, 1, 1.35, 0.22);
      outerSh.push({
        x: p.x + shDx * contactFactor,
        y: p.y + shDy * contactFactor
      });
    }
    brush.fill("#cfc8b9", 115);
    drawClosedCurve(outerSh, 0.4);

    // Bright golden-buttercream caustic convergence oval cast by the convex reading lens onto the paper!
    const causticPts = [];
    for (let a = 0; a < 360; a += 15) {
      const p = getLensPoint(L, a, 0.78, 0.74);
      const contactFactor = map(sin(a), -1, 1, 1.1, 0.25);
      causticPts.push({
        x: p.x + shDx * contactFactor * 0.85,
        y: p.y + shDy * contactFactor * 0.85
      });
    }
    brush.fill("#fffbeb", 165);
    drawClosedCurve(causticPts, 0.45);

    // Warm honey-tinted caustic rim halo (light refracted through the amber frame rim)
    const causticRim = [];
    for (let a = 15; a <= 165; a += 12) {
      const p = getLensPoint(L, a, 0.92, 0.90);
      const contactFactor = map(sin(a), -1, 1, 1.15, 0.22);
      causticRim.push([
        p.x + shDx * contactFactor * 0.9,
        p.y + shDy * contactFactor * 0.9
      ]);
    }
    brush.set("cpencil", "#f5d08a", 1.1);
    brush.spline(causticRim, 0.4);
  }

  // 2. Shadow of the receding temple arms across the pages
  brush.noStroke();
  brush.fill("#d4cdbf", 105);
  // Left temple shadow
  drawClosedCurve([
    { x: 245, y: 810 },
    { x: 385, y: 608 },
    { x: 540, y: 582 },
    { x: 548, y: 598 },
    { x: 398, y: 625 },
    { x: 262, y: 822 }
  ], 0.25);

  // Right temple shadow
  drawClosedCurve([
    { x: 902, y: 712 },
    { x: 640, y: 590 },
    { x: 435, y: 602 },
    { x: 440, y: 616 },
    { x: 645, y: 608 },
    { x: 910, y: 726 }
  ], 0.25);

  // 3. Crisp graphite ambient-occlusion contact shadows right where lower rims rest on the paper
  for (const item of lenses) {
    const L = item.lens;
    for (let pass = 0; pass < 6; pass++) {
      const contactPts = [];
      for (let a = 35 + pass * 4; a <= 145 - pass * 4; a += 8) {
        const p = getOuterRimPoint(L, a, item.isLeft);
        const lift = Math.pow((a - 90) / 55, 2);
        contactPts.push([
          p.x + 2 + pass * 1.1,
          p.y + 1.5 + pass * 2.2 + lift * 6
        ]);
      }
      const col = pass < 2 ? "#4a433b" : (pass < 4 ? "#7d7468" : "#afa799");
      brush.set(pass < 2 ? "2B" : "HB", col, map(pass, 0, 5, 0.75, 0.35));
      brush.spline(contactPts, 0.4);
    }
  }
}

// ============================================================================
// 5. PRINTED BOOK TYPOGRAPHY (SHALLOW DOF + OPTICAL LENS MAGNIFICATION)
// ============================================================================

function drawBookTypographyAndRefraction() {
  // Helper that maps a raw page point (x, y) through the optical magnification of the reading lenses
  function applyLensRefraction(pt) {
    for (const L of [LEFT_LENS, RIGHT_LENS]) {
      const info = getLensOpticalInfo(pt.x, pt.y, L);
      if (info.inside) {
        // Convex reading lens (+2.00 diopter) magnifies text outward from optical center with slight pincushion curve
        const mag = 1.0 + 0.135 * (1.0 - 0.25 * info.normR * info.normR);
        return {
          x: L.cx + (pt.x - L.cx) * mag,
          y: L.cy + (pt.y - L.cy) * mag - 3.5,
          inLens: true,
          normR: info.normR
        };
      }
    }
    return { x: pt.x, y: pt.y, inLens: false, normR: 1.0 };
  }

  // Render a single line of typeset book text on either Left or Right page
  function renderTypesetLine(isRight, v, uStart, uEnd, isHeader = false) {
    const pMid = isRight ? rightPagePt(0.5, v) : leftPagePt(0.5, v);
    const dof = constrain(Math.abs(pMid.y - 785) / 235, 0, 1);

    // Deterministic word lengths along the line
    let u = uStart;
    while (u < uEnd - 0.02) {
      const wordLen = isHeader ? random(0.05, 0.09) : random(0.025, 0.085);
      const uNext = Math.min(uEnd, u + wordLen);

      const p1Raw = isRight ? rightPagePt(u, v) : leftPagePt(u, v);
      const p2Raw = isRight ? rightPagePt(uNext, v) : leftPagePt(uNext, v);

      const p1 = applyLensRefraction(p1Raw);
      const p2 = applyLensRefraction(p2Raw);

      // Inside the reading lenses, focus is hyper-sharp and contrast is slightly elevated
      const localDof = p1.inLens || p2.inLens ? dof * 0.25 : dof;

      if (localDof < 0.38) {
        // Razor-sharp focal zone: render crisp x-height baseline + tiny serif ascenders/stems
        const inkCol = (p1.inLens || p2.inLens) ? "#332e29" : "#4a443d";
        brush.set("macro_ink", inkCol, p1.inLens ? 0.42 : 0.34);
        brush.line(p1.x, p1.y, p2.x, p2.y);

        // Micro-glyph vertical stems & ascenders for hyperreal typeset texture
        const dist = distPts(p1, p2);
        const steps = Math.max(2, Math.floor(dist / (p1.inLens ? 4.2 : 5.0)));
        for (let k = 0; k <= steps; k++) {
          const t = k / steps;
          const gx = lerp(p1.x, p2.x, t);
          const gy = lerp(p1.y, p2.y, t);
          const hasAscender = random() < 0.28;
          const hasDescender = !hasAscender && random() < 0.16;
          const topOff = hasAscender ? (p1.inLens ? 5.2 : 4.2) : (p1.inLens ? 3.1 : 2.5);
          const botOff = hasDescender ? (p1.inLens ? 2.6 : 2.0) : 0.3;
          brush.set("macro_ink", inkCol, p1.inLens ? 0.38 : 0.30);
          brush.line(gx, gy - topOff, gx, gy + botOff);
        }
      } else if (localDof < 0.72) {
        // Transitional depth of field: softened graphite word bars with occasional ascender hints
        brush.set("2H", "#6e675e", map(localDof, 0.38, 0.72, 0.42, 0.65));
        brush.line(p1.x, p1.y, p2.x, p2.y);
        brush.line(p1.x, p1.y - 1.8, p2.x, p2.y - 1.8);
      } else {
        // Far out-of-focus top/bottom of page: soft blurred graphite whisper
        brush.set("HB", "#968e82", map(localDof, 0.72, 1.0, 0.55, 0.85));
        brush.line(p1.x, p1.y - 0.8, p2.x, p2.y - 0.8);
      }

      // Space between words
      u = uNext + (isHeader ? 0.025 : random(0.012, 0.024));
    }
  }

  // Left Page layout: running header + 29 lines of prose + page number
  renderTypesetLine(false, 0.085, 0.34, 0.68, true);
  for (let row = 0; row < 29; row++) {
    const v = 0.135 + row * 0.0255;
    // Paragraph indents & line endings
    const isNewPara = row === 0 || row === 8 || row === 17 || row === 24;
    const isParaEnd = row === 7 || row === 16 || row === 23;
    const uStart = isNewPara ? 0.19 : 0.14;
    const uEnd = isParaEnd ? random(0.45, 0.76) : 0.89;
    renderTypesetLine(false, v, uStart, uEnd, false);
  }
  renderTypesetLine(false, 0.915, 0.48, 0.53, true);

  // Right Page layout: chapter header + 29 lines of prose + page number
  renderTypesetLine(true, 0.085, 0.36, 0.66, true);
  for (let row = 0; row < 29; row++) {
    const v = 0.135 + row * 0.0255;
    const isNewPara = row === 0 || row === 11 || row === 20;
    const isParaEnd = row === 10 || row === 19 || row === 28;
    const uStart = isNewPara ? 0.16 : 0.11;
    const uEnd = isParaEnd ? random(0.42, 0.74) : 0.85;
    renderTypesetLine(true, v, uStart, uEnd, false);
  }
  renderTypesetLine(true, 0.915, 0.47, 0.52, true);
}

function distPts(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}

