  drawClosedCurve(rightTemplePoly, 0.35);
  drawClosedCurve(leftTemplePoly, 0.35);

  // Golden honey internal glow where window sunlight backlights the translucent acetate
  brush.fill("#fbbf24", 160);
  drawClosedCurve(rightTemplePoly, 0.35);
  drawClosedCurve(leftTemplePoly, 0.35);

  // Mottled tortoiseshell patches along the temple arms
  const rightMottles = [0.08, 0.22, 0.38, 0.56, 0.74, 0.88];
  for (const t of rightMottles) {
    const mx = lerp(894, 435, t);
    const my = lerp(692, 572, t) - Math.sin(t * 180) * 26;
    const dof = constrain(Math.abs(my - 785) / 230, 0, 1);
    brush.set("tortoise_glaze", t % 0.16 < 0.08 ? "#291507" : "#6b2c08", lerp(1.1, 0.75, dof));
    brush.line(mx - 12, my + 4, mx + 14, my - 5);
  }

  const leftMottles = [0.06, 0.16, 0.28, 0.42, 0.58, 0.75, 0.90];
  for (const t of leftMottles) {
    const mx = lerp(238, 545, t);
    const my = lerp(790, 568, t) - Math.sin(t * 180) * 32;
    const dof = constrain(Math.abs(my - 785) / 230, 0, 1);
    brush.set("tortoise_glaze", t < 0.45 ? "#1f0f04" : "#5c2406", lerp(1.25, 0.8, dof));
    brush.line(mx - 8, my + 8, mx + 10, my - 8);
  }

  // Faint metallic core-wire visible inside the translucent amber temple arms!
  brush.set("2H", "#fef08a", 0.55);
  brush.spline(leftTempleTop.map((p, i) => [
    (p.x + leftTempleBot[leftTempleBot.length - 1 - i].x) * 0.5,
    (p.y + leftTempleBot[leftTempleBot.length - 1 - i].y) * 0.5
  ]), 0.4);
  brush.spline(rightTempleTop.map((p, i) => [
    (p.x + rightTempleBot[rightTempleBot.length - 1 - i].x) * 0.5,
    (p.y + rightTempleBot[rightTempleBot.length - 1 - i].y) * 0.5
  ]), 0.4);

  // Crisp contour edges near the hinges, softening as the arms recede into the window bokeh
  brush.set("macro_ink", "#261305", 0.55);
  brush.spline(leftTempleTop.slice(0, 3).map(p => [p.x, p.y]), 0.35);
  brush.spline(leftTempleBot.slice(2, 5).map(p => [p.x, p.y]), 0.35);
  brush.spline(rightTempleTop.slice(0, 3).map(p => [p.x, p.y]), 0.35);
  brush.spline(rightTempleBot.slice(2, 5).map(p => [p.x, p.y]), 0.35);

  // Specular rim light catching the top edge of the temple arms from the window
  brush.set("specular_gloss", "#fffbeb", 0.55);
  brush.spline(leftTempleTop.map(p => [p.x, p.y + 1.5]), 0.35);
  brush.spline(rightTempleTop.map(p => [p.x, p.y + 1.5]), 0.35);
}

// ============================================================================
// 7. OPTICAL GLASS LENSES (ANTI-REFLECTIVE TINT & GROUND GLASS BEVEL)
// ============================================================================

function drawLensGlassAndRefractions() {
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.18, 0.12);

  for (const L of [LEFT_LENS, RIGHT_LENS]) {
    const lensPts = [];
    for (let a = 0; a < 360; a += 10) {
      lensPts.push(getLensPoint(L, a, 1.0, 1.0));
    }

    // Whisper-subtle sky-blue / sage optical coating tint across the glass lens
    brush.fill("#e3f0f5", 32);
    drawClosedCurve(lensPts, 0.45);

    // Ground glass inner bevel ring (where the thick optical lens edge sits inside the tortoiseshell groove)
    const innerBevelPts = [];
    for (let a = 0; a < 360; a += 8) {
      const p = getLensPoint(L, a, 0.968, 0.962);
      innerBevelPts.push([p.x, p.y]);
    }
    innerBevelPts.push(innerBevelPts[0]);

    // Refracted sky-blue & white light trapped in the ground glass bevel edge
    brush.set("cpencil", "#cde4f2", 0.95);
    brush.spline(innerBevelPts, 0.45);

    // Brightest internal bevel highlight along the lower & nasal rim
    const lowerBevel = [];
    for (let a = 15; a <= 170; a += 8) {
      const p = getLensPoint(L, a, 0.975, 0.972);
      lowerBevel.push([p.x, p.y]);
    }
    brush.set("specular_gloss", "#f5fbff", 0.65);
    brush.spline(lowerBevel, 0.4);
  }
}

// ============================================================================
// 8. TORTOISESHELL FRAME FRONT (LAYERED ACETATE, MOTTLING & 3D BEVELS)
// ============================================================================

function drawTortoiseshellFrameFront() {
  // Build the front frame in C-shaped overlapping segments around each lens plus the keyhole bridge
  // so `beginShape` creates solid, watertight watercolor and dry-media bands without holes.

  const frameSegments = [];

  // Generate 16 overlapping arc segments around Left Rim and Right Rim
  for (const item of [{ lens: LEFT_LENS, isLeft: true }, { lens: RIGHT_LENS, isLeft: false }]) {
    const numSegs = 16;
    const step = 360 / numSegs;
    for (let s = 0; s < numSegs; s++) {
      const a1 = s * step - 2;
      const a2 = (s + 1) * step + 2;
      const segPts = [];
      for (let a = a1; a <= a2; a += 5) {
        segPts.push(getOuterRimPoint(item.lens, a, item.isLeft));
      }
      for (let a = a2; a >= a1; a -= 5) {
        segPts.push(getLensPoint(item.lens, a, 1.0, 1.0));
      }
      frameSegments.push({ pts: segPts, midAngle: (a1 + a2) * 0.5, lens: item.lens, isLeft: item.isLeft });
    }
  }

  // Keyhole Bridge polygon connecting Left Rim (-38..-8 deg) to Right Rim (-172..-142 deg)
  const bridgePts = [
    getOuterRimPoint(LEFT_LENS, -42, true),
    { x: 545, y: 728 },
    { x: 576, y: 722 },
    { x: 608, y: 719 },
    getOuterRimPoint(RIGHT_LENS, -138, false),
    getOuterRimPoint(RIGHT_LENS, -168, false),
    { x: 606, y: 746 },
    { x: 578, y: 742 },
    { x: 552, y: 754 },
    getOuterRimPoint(LEFT_LENS, -12, true)
  ];

  // 1. 3D Lower/Inner Dark Espresso Thickness of the Frame (extruded 6.5px downward)
  brush.noStroke();
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.25, 0.2);
  brush.fill("#1c0d04", 235);

  for (const seg of frameSegments) {
    const extrudePts = seg.pts.map(p => ({ x: p.x + 1.5, y: p.y + 6.5 }));
    drawClosedCurve(extrudePts, 0.25);
  }
  drawClosedCurve(bridgePts.map(p => ({ x: p.x + 1.5, y: p.y + 6.5 })), 0.3);

  // 2. Base Rich Translucent Amber & Golden Honey Watercolour Wash
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.4, 0.35);
  brush.fill("#d97706", 225);
  for (const seg of frameSegments) {
    drawClosedCurve(seg.pts, 0.25);
  }
  drawClosedCurve(bridgePts, 0.3);

  // Bright golden-honey backlit glow on upper brow & keyhole bridge segments
  brush.fill("#fbbf24", 180);
  for (const seg of frameSegments) {
    if (sin(seg.midAngle) < 0.2) {
      drawClosedCurve(seg.pts, 0.25);
    }
  }
  drawClosedCurve(bridgePts, 0.3);

  // 3. Organic Tortoiseshell Mottling (Layered Burnt Sienna, Mahogany & Deep Espresso Patches)
  // Using precise dry-media & marker glazing strokes strictly inside the frame rim geometry
  for (const item of [{ lens: LEFT_LENS, isLeft: true }, { lens: RIGHT_LENS, isLeft: false }]) {
    const L = item.lens;

    // 26 organic dark & medium tortoiseshell pigment clusters around each rim
    for (let m = 0; m < 28; m++) {
      const baseAngle = m * (360 / 28) + random(-4, 4);
      // Leave radiant golden-amber gaps between the dark tortoise patches!
      const patchIntensity = noise(m * 0.65, item.isLeft ? 10 : 50);
      if (patchIntensity < 0.34) continue;

      const isDeepEspresso = patchIntensity > 0.56;
      const span = random(7, 16);

      // Fill patch polygon with warm mahogany or deep espresso
      const patchPts = [];
      for (let a = baseAngle - span * 0.5; a <= baseAngle + span * 0.5; a += 3) {
        const pIn = getLensPoint(L, a, 1.01, 1.01);
        const pOut = getOuterRimPoint(L, a, item.isLeft);
        const tIn = random(0.05, 0.25);
        patchPts.push({
          x: lerp(pIn.x, pOut.x, tIn),
          y: lerp(pIn.y, pOut.y, tIn)
        });
      }
      for (let a = baseAngle + span * 0.5; a >= baseAngle - span * 0.5; a -= 3) {
        const pIn = getLensPoint(L, a, 1.01, 1.01);
        const pOut = getOuterRimPoint(L, a, item.isLeft);
        const tOut = random(0.78, 0.98);
        patchPts.push({
          x: lerp(pIn.x, pOut.x, tOut),
          y: lerp(pIn.y, pOut.y, tOut)
        });
      }

      brush.noStroke();
      brush.fill(isDeepEspresso ? "#1f0e04" : "#6b2706", isDeepEspresso ? 215 : 185);
      drawClosedCurve(patchPts, 0.35);

      // Feathered colored-pencil & marker grain radiating across the tortoise patch
      for (let s = 0; s < 7; s++) {
        const a1 = baseAngle + random(-span * 0.55, span * 0.55);
        const a2 = a1 + random(-5, 5);
        const pIn = getLensPoint(L, a1, 1.02, 1.02);
        const pOut = getOuterRimPoint(L, a2, item.isLeft);
        const col = s < 3 ? "#170a02" : (s < 5 ? "#78350f" : "#f59e0b");
        brush.set("cpencil", col, random(0.65, 1.15));
        brush.line(
          lerp(pIn.x, pOut.x, 0.1),
          lerp(pIn.y, pOut.y, 0.1),
          lerp(pIn.x, pOut.x, 0.92),
          lerp(pIn.y, pOut.y, 0.92)
        );
      }
    }

    // Glowing honey/buttercream veins where light transmits through the amber acetate
    for (let g = 0; g < 18; g++) {
      const a = g * 20 + random(-6, 6);
      const pIn = getLensPoint(L, a, 1.03, 1.03);
      const pOut = getOuterRimPoint(L, a + 4, item.isLeft);
      brush.set("cpencil", "#fde68a", random(0.7, 1.1));
      brush.line(
        lerp(pIn.x, pOut.x, 0.22),
        lerp(pIn.y, pOut.y, 0.22),
        lerp(pIn.x, pOut.x, 0.82),
        lerp(pIn.y, pOut.y, 0.82)
      );
    }

    // 4. Razor-sharp Inner & Outer Frame Contours + 3D Lower Bevel Shadow
    const outerContour = [];
    const outerLowerBevel = [];
    const innerContour = [];
    for (let a = 0; a <= 360; a += 6) {
      const po = getOuterRimPoint(L, a, item.isLeft);
      const pi = getLensPoint(L, a, 1.0, 1.0);
      outerContour.push([po.x, po.y]);
      outerLowerBevel.push([po.x + 1.5, po.y + 6.0]);
      innerContour.push([pi.x, pi.y]);
    }

    brush.set("macro_ink", "#140902", 0.72);
    brush.spline(outerContour, 0.45);
    brush.spline(innerContour, 0.45);

    brush.set("2B", "#0f0601", 0.85);
    brush.spline(outerLowerBevel, 0.45);
  }

  // Bridge mottling & crisp keyhole arch definition
  brush.set("tortoise_glaze", "#241004", 1.15);
  brush.line(542, 735, 568, 728);
  brush.line(592, 724, 616, 734);
  brush.set("cpencil", "#fde047", 0.95);
  brush.line(566, 726, 590, 724);

  brush.set("macro_ink", "#140902", 0.72);
  brush.spline(bridgePts.slice(0, 5).map(p => [p.x, p.y]), 0.35);
  brush.spline(bridgePts.slice(5, 10).map(p => [p.x, p.y]), 0.35);

  // 5. Continuous Glossy Specular Highlight Ribbon along the Polished Acetate Brow & Bridge
  for (const item of [{ lens: LEFT_LENS, isLeft: true }, { lens: RIGHT_LENS, isLeft: false }]) {
    const L = item.lens;
    // Upper brow specular ribbon
    const browGlint = [];
    for (let a = -158; a <= -22; a += 6) {
      const pIn = getLensPoint(L, a, 1.0, 1.0);
      const pOut = getOuterRimPoint(L, a, item.isLeft);
      browGlint.push([
        lerp(pIn.x, pOut.x, 0.62),
        lerp(pIn.y, pOut.y, 0.62)
      ]);
    }
    brush.set("specular_gloss", "#fffef5", 0.95);
    brush.spline(browGlint, 0.4);

    // Lower rim secondary specular reflection
    const cheekGlint = [];
    for (let a = 32; a <= 142; a += 6) {
      const pIn = getLensPoint(L, a, 1.0, 1.0);
      const pOut = getOuterRimPoint(L, a, item.isLeft);
      cheekGlint.push([
        lerp(pIn.x, pOut.x, 0.45),
        lerp(pIn.y, pOut.y, 0.45)
      ]);
    }
    brush.set("specular_gloss", "#fef9c3", 0.65);
    brush.spline(cheekGlint, 0.4);
  }

  // Bridge top highlight
  brush.set("specular_gloss", "#ffffff", 0.9);
  brush.spline([
    [535, 734],
    [562, 726],
    [590, 723],
    [618, 727]
  ], 0.4);
}

// ============================================================================
// 9. MACRO HARDWARE: SLOTTED HINGE SCREW, 5-BARREL HINGES & SILVER RIVETS
// ============================================================================

function drawMacroHingesAndRivets() {
  // 1. FOREGROUND LEFT HINGE & SLOTTED HINGE SCREW (at x ~ 236, y ~ 796)
  // Where the left frame end-piece (lug) meets the angled miter of the left temple arm,
  // exposing the precision machined metallic 5-barrel hinge and the top of the slotted hinge screw!
  const hx = 236;
  const hy = 795;

  // Dark miter gap between front frame lug and temple arm
  brush.set("macro_ink", "#0f0702", 0.85);
  brush.line(hx - 14, hy + 11, hx + 14, hy - 5);
  brush.line(hx - 12, hy + 16, hx + 16, hy + 0);

  // Metallic 5-barrel hinge housing (machined nickel-silver & warm brass reflection)
  brush.noStroke();
  brush.fillBleed(0.01, "in");
  brush.fillTexture(0.15, 0.1);
  brush.fill("#8c9298", 240);
  drawClosedCurve([
    { x: hx - 9, y: hy - 10 },
    { x: hx + 11, y: hy - 12 },
    { x: hx + 13, y: hy + 12 },
    { x: hx - 7, y: hy + 14 }
  ], 0.2);

  // Individual interleaved hinge barrel lines & metallic cylinder shading
  for (let b = -2; b <= 2; b++) {
    const by = hy + b * 4.2;
    brush.set("macro_ink", "#2b3036", 0.48);
    brush.line(hx - 8, by + 1, hx + 12, by - 1);
    brush.set("specular_gloss", "#f8fafc", 0.42);
    brush.line(hx - 5, by - 0.8, hx + 8, by - 2.2);
  }

  // Counterbore recess around the hinge screw head
  brush.noStroke();
  brush.fill("#3b4046", 245);
  brush.circle(hx + 1, hy - 3, 11.5, 0.02);

  // Machined cylindrical head of the hinge screw (seen in 3D foreshortened perspective)
  brush.fill("#cbd2d9", 250);
  brush.circle(hx + 1, hy - 3.5, 9.2, 0.02);

  // Conical metallic sheen across the screw head
  brush.set("cpencil", "#646d75", 0.65);
  brush.arc(hx + 1, hy - 3.5, 7.2, 20, 195);
  brush.set("specular_gloss", "#ffffff", 0.72);
  brush.arc(hx + 1, hy - 3.5, 7.5, 200, 350);

  // Crisp perimeter of the hinge screw head
  brush.set("macro_ink", "#1e2226", 0.55);
  brush.circle(hx + 1, hy - 3.5, 9.2, 0.02);

  // THE SCREWDRIVER SLOT across the hinge screw head (deep dark groove + razor-sharp bevel glint!)
  brush.set("macro_ink", "#0b0d0f", 0.95);
  brush.line(hx - 6.8, hy - 0.5, hx + 8.8, hy - 6.5);
  brush.set("macro_ink", "#22262b", 0.65);
  brush.line(hx - 6.5, hy + 0.6, hx + 9.0, hy - 5.4);

  // Bright metallic burrs / bevel highlights catching the sunlight along the lower lip of the screw slot
  brush.set("specular_gloss", "#ffffff", 0.78);
  brush.line(hx - 6.2, hy + 1.2, hx + 8.5, hy - 4.8);

  // 2. RIGHT HINGE HARDWARE (at x ~ 893, y ~ 694)
  const rhx = 893;
  const rhy = 694;
  brush.set("macro_ink", "#120802", 0.75);
  brush.line(rhx - 12, rhy - 4, rhx + 12, rhy + 8);

  brush.noStroke();
  brush.fill("#8c9298", 235);
  brush.circle(rhx - 2, rhy - 1, 7.5, 0.03);
  brush.set("macro_ink", "#1e2226", 0.48);
  brush.circle(rhx - 2, rhy - 1, 7.5, 0.02);
  // Slot on right hinge screw
  brush.set("macro_ink", "#0f1214", 0.75);
  brush.line(rhx - 7.5, rhy - 3, rhx + 3.5, rhy + 1);
  brush.set("specular_gloss", "#ffffff", 0.65);
  brush.line(rhx - 7.2, rhy - 1.8, rhx + 3.2, rhy + 2.2);

  // 3. DUAL SILVER RIVET PINS on the front lugs & nasal bridge (classic heritage eyewear detail)
  function drawPinRivet(x, y, rx, ry) {
    const pts = [];
    for (let a = 0; a < 360; a += 30) {
      pts.push({ x: x + cos(a) * rx, y: y + sin(a) * ry });
    }
    brush.noStroke();
    brush.fill("#d8dee3", 245);
    drawClosedCurve(pts, 0.4);
    brush.set("macro_ink", "#2b180a", 0.42);
    brush.circle(x, y, (rx + ry) * 0.5, 0.04);
    brush.set("specular_gloss", "#ffffff", 0.65);
    brush.line(x - rx * 0.5, y - ry * 0.3, x + rx * 0.5, y - ry * 0.3);
  }

  // Left lug dual rivets
  drawPinRivet(251, 804, 4.8, 2.8);
  drawPinRivet(265, 801, 4.5, 2.7);

  // Left nasal rivet
  drawPinRivet(518, 750, 4.2, 2.6);

  // Right nasal rivet
  drawPinRivet(630, 732, 4.2, 2.6);

  // Right lug dual rivets
  drawPinRivet(872, 697, 4.4, 2.6);
  drawPinRivet(885, 694, 4.6, 2.7);
}

// ============================================================================
// 10. LENS SPECULAR REFLECTIONS (CURVED WINDOW PANES & BOKEH GLINTS)
// ============================================================================

function drawLensSpecularReflections() {
  // Across the convex surface of both lenses, render the curved reflection of the sunlit window
  // (sky-blue, buttercream, sage bokeh & crisp white sash highlights) using precision hatching & washes.

  for (const item of [{ lens: LEFT_LENS, isLeft: true }, { lens: RIGHT_LENS, isLeft: false }]) {
    const L = item.lens;

    // Helper to map normalized lens coords (u, v in [-1..1]) to canvas coords with spherical lens curvature
    function lensSurfPt(u, v) {
      const ct = cos(L.tilt);
      const st = sin(L.tilt);
      // Spherical bulge distortion near edges
      const rSq = u * u + v * v;
      const bend = 1.0 - 0.12 * rSq;
      const lx = u * L.rx * bend;
      const ly = v * L.ry * bend;
      return {
        x: L.cx + lx * ct - ly * st,
        y: L.cy + lx * st + ly * ct
      };
    }

    // Pane 1 (Upper-left curved window reflection in lens)
    const pane1 = [
      lensSurfPt(-0.68, -0.58),
      lensSurfPt(-0.12, -0.72),
      lensSurfPt(-0.22, -0.18),
      lensSurfPt(-0.76, -0.06)
    ];

    // Pane 2 (Upper-right curved window reflection in lens)
    const pane2 = [
      lensSurfPt(-0.02, -0.74),
      lensSurfPt(0.52, -0.60),
      lensSurfPt(0.42, -0.12),
      lensSurfPt(-0.12, -0.20)
    ];

    // Pane 3 (Lower-left soft reflection)
    const pane3 = [
      lensSurfPt(-0.74, 0.04),
      lensSurfPt(-0.25, -0.08),
      lensSurfPt(-0.32, 0.36),
      lensSurfPt(-0.68, 0.44)
    ];

    brush.noStroke();
    brush.fillBleed(0.08, "out");
    brush.fillTexture(0.2, 0.15);

    // Translucent sky-blue & buttercream window pane reflections
    brush.fill("#dff0fa", 78);
    drawClosedCurve(pane1, 0.35);
    brush.fill("#fef9dc", 85);
    drawClosedCurve(pane2, 0.35);
    brush.fill("#e3f0e0", 62);
    drawClosedCurve(pane3, 0.35);

    // Reflected mini bokeh discs inside the lens reflection!
    const pBokeh1 = lensSurfPt(-0.38, -0.45);
    const pBokeh2 = lensSurfPt(0.18, -0.42);
    const pBokeh3 = lensSurfPt(-0.48, 0.18);
    brush.fill("#ffffff", 110);
    brush.circle(pBokeh1.x, pBokeh1.y, 22, 0.05);
    brush.circle(pBokeh2.x, pBokeh2.y, 26, 0.05);
    brush.fill("#fcf4c7", 95);
    brush.circle(pBokeh3.x, pBokeh3.y, 18, 0.05);

    // Precision colored-pencil & specular gloss hatching along the curved reflection panes
    for (let s = 0; s <= 12; s++) {
      const t = s / 12;
      const a1 = lensSurfPt(lerp(-0.66, -0.14, t), lerp(-0.56, -0.70, t));
      const a2 = lensSurfPt(lerp(-0.74, -0.22, t), lerp(-0.08, -0.20, t));
      brush.set(s % 3 === 0 ? "specular_gloss" : "cpencil", s % 2 === 0 ? "#ffffff" : "#d8eef8", 0.52);
      brush.line(a1.x, a1.y, a2.x, a2.y);

      const b1 = lensSurfPt(lerp(0.0, 0.50, t), lerp(-0.72, -0.58, t));
      const b2 = lensSurfPt(lerp(-0.10, 0.40, t), lerp(-0.22, -0.14, t));
      brush.set(s % 3 === 0 ? "specular_gloss" : "cpencil", s % 2 === 0 ? "#ffffff" : "#fef7d0", 0.52);
      brush.line(b1.x, b1.y, b2.x, b2.y);
    }

    // Razor-sharp curved white highlight arc along the leading edge of the lens reflection
    const leadArc = [];
    for (let s = 0; s <= 10; s++) {
      const t = s / 10;
      const p = lensSurfPt(lerp(-0.74, -0.66, t), lerp(0.32, -0.56, t));
      leadArc.push([p.x, p.y]);
    }
    brush.set("specular_gloss", "#ffffff", 0.95);
    brush.spline(leadArc, 0.45);

    // Secondary crisp highlight along the top reflection edge
    const topArc = [];
    for (let s = 0; s <= 10; s++) {
      const t = s / 10;
      const p = lensSurfPt(lerp(-0.66, 0.48, t), lerp(-0.56, -0.58, t) - Math.sin(t * 180) * 0.14);
      topArc.push([p.x, p.y]);
    }
    brush.set("specular_gloss", "#ffffff", 0.78);
    brush.spline(topArc, 0.45);
  }
}

