// Hyperrealistic Sawn Tree Stump with Agate Banding
// Rendered with p5.js v2 + p5.brush in WEBGL

const SEED = 4279;

// Stump geometry anchors
const PITH_X = 546;
const PITH_Y = 574;
const CENTER_X = 606;
const CENTER_Y = 602;
const BASE_RADIUS = 432;

// Scar / fortification agate creases (inward V-pinches)
const SCARS = [
  { angle: 38, depth: 0.058, width: 15, startU: 0.14, twist: 8 },
  { angle: 112, depth: 0.042, width: 13, startU: 0.28, twist: -6 },
  { angle: 168, depth: 0.082, width: 20, startU: 0.06, twist: 14 },
  { angle: 224, depth: 0.052, width: 16, startU: 0.22, twist: -10 },
  { angle: 288, depth: 0.068, width: 18, startU: 0.10, twist: 11 },
  { angle: 336, depth: 0.038, width: 12, startU: 0.35, twist: -5 }
];

// Radial cracks (heart checks and seasoning splits)
const CRACKS = [
  { angle: 38, startU: 0.0, endU: 0.94, maxW: 11.5, seed: 11 },
  { angle: 168, startU: 0.0, endU: 0.99, maxW: 14.0, seed: 23 },
  { angle: 288, startU: 0.0, endU: 0.86, maxW: 9.5, seed: 37 },
  { angle: 108, startU: 0.04, endU: 0.62, maxW: 5.5, seed: 51 },
  { angle: 232, startU: 0.02, endU: 0.74, maxW: 6.8, seed: 67 },
  { angle: 342, startU: 0.18, endU: 0.78, maxW: 4.5, seed: 83 },
  { angle: 74, startU: 0.45, endU: 0.96, maxW: 4.2, seed: 97 },
  { angle: 198, startU: 0.38, endU: 0.92, maxW: 3.8, seed: 109 }
];

let ringSchedule = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
