  // 3. Translucent watercolor glazes (concentric agate & wood bands)
  drawAgateWatercolorGlazes();

  // 4. Medullary rays & fine radial wood grain
  drawMedullaryRays();

  // 5. Growth rings & fortification agate banding in fine pencil
  drawGrowthRingsAndAgateBanding();

