  drawSawMarks();

  // 7. Radial heart cracks & seasoning splits
  drawRadialCracks();

  // 8. Creeping moss & crustose lichen at the upper-left / left edge
  drawMossAndLichen();

  // 9. Glistening resin / sap beads with optical caustics
  drawSapBeads();

  noLoop();
}

// ============================================================================
// GEOMETRY & RING SCHEDULE
// ============================================================================

function getStumpPoint(u, thetaDeg) {
  let uClamped = max(0.0001, u);
  let shiftU = pow(constrain(uClamped, 0, 1.2), 0.82);

  // Slight organic drift of the growth center over the tree's life
  let driftX = 16 * sin(uClamped * 260 + 20) * (1 - shiftU * 0.72) * uClamped;
  let driftY = -12 * cos(uClamped * 220 - 15) * (1 - shiftU * 0.72) * uClamped;

  let cx = lerp(PITH_X, CENTER_X, shiftU) + driftX;
  let cy = lerp(PITH_Y, CENTER_Y, shiftU) + driftY;

  let rBase = uClamped * BASE_RADIUS;

  // Low-frequency root buttress lobes
  let lobeEnv = pow(constrain(uClamped, 0, 1.25), 1.3);
  let lobes =
    0.048 * cos(2 * thetaDeg - 24) +
    0.042 * sin(3 * thetaDeg + 45) +
    0.031 * cos(5 * thetaDeg - 70) +
    0.019 * sin(7 * thetaDeg + 120) +
    0.012 * cos(11 * thetaDeg - 30);

  // Sharp inward fortification-agate / cambial scar pinches
  let scarPinch = 0;
  for (let i = 0; i < SCARS.length; i++) {
    let s = SCARS[i];
    if (uClamped > s.startU) {
      let curAngle = s.angle + s.twist * (uClamped - s.startU);
      let dAng = ((thetaDeg - curAngle + 540) % 360) - 180;
      let normAng = abs(dAng) / s.width;
      if (normAng < 2.5) {
        let uEnv = pow(constrain((uClamped - s.startU) / (1.0 - s.startU), 0, 1.2), 0.75);
        // Sharp V-bottomed Gaussian pinch characteristic of agate fortifications
        let profile = exp(-pow(normAng, 1.55) * 1.8);
        scarPinch += s.depth * profile * uEnv;
      }
    }
  }

  // Seamless circular Perlin noise for drought wavering
  let rad = thetaDeg;
  let nx = cos(rad) * 2.1 + 15.0;
  let ny = sin(rad) * 2.1 + 15.0;
  let nz = uClamped * 2.4;
  let nMed = (noise(nx, ny, nz) - 0.5) * 2.0;

  let nx2 = cos(rad) * 5.8 + 42.0;
  let ny2 = sin(rad) * 5.8 + 42.0;
  let nFine = (noise(nx2, ny2, uClamped * 4.2) - 0.5) * 2.0;

  // Eccentric compression (rings tighter on north-west, wider on south-east)
  let eccentric = 0.045 * cos(thetaDeg - 35) * sin(uClamped * 180);

  let rMod =
    1.0 +
    lobeEnv * lobes +
    eccentric -
    scarPinch +
    (0.062 * nMed + 0.021 * nFine) * pow(constrain(uClamped, 0.02, 1.2), 0.72);

  let r = rBase * rMod;
  return {
    x: cx + r * cos(thetaDeg),
    y: cy + r * sin(thetaDeg),
    r: r,
    cx: cx,
    cy: cy
  };
}

function buildRingSchedule() {
  ringSchedule = [];
  let u = 0.014;
  let idx = 0;

  while (u < 0.994) {
    // Drought waves create tight clusters vs wide wet-decade growth
    let climateWave =
      0.5 +
      0.32 * sin(u * 1350 - 40) +
      0.22 * cos(u * 2900 + 80) +
      (noise(u * 14, 7.3) - 0.5) * 0.45;
    climateWave = constrain(climateWave, 0.08, 1.0);

    let du = map(climateWave, 0.08, 1.0, 0.0036, 0.0115);
    if (u < 0.08) du *= 0.85;
    if (u > 0.88) du *= 0.72; // Older outer rings compress near bark

    let nextU = min(0.996, u + du);
    let midU = (u + nextU) * 0.5;

    // Assign geological agate / wood band palette family
    let paletteType = "honey";
    let bandSignal = sin(midU * 1120) + 0.6 * cos(midU * 2350 + 50);

    if (midU < 0.16) {
      paletteType = idx % 3 === 0 ? "rust" : "caramel";
    } else if (midU > 0.84) {
      paletteType = idx % 2 === 0 ? "cream" : "smoky";
    } else {
      if (climateWave < 0.32) {
        paletteType = "rust_drought";
      } else if (bandSignal > 0.68) {
        paletteType = "cream";
      } else if (bandSignal < -0.55) {
        paletteType = "smoky";
      } else if (bandSignal > 0.05) {
        paletteType = "honey";
      } else {
        paletteType = "caramel";
      }
    }

    ringSchedule.push({
      index: idx,
      uInner: u,
      uOuter: nextU,
      uMid: midU,
      du: nextU - u,
      drought: 1.0 - climateWave,
      type: paletteType
    });

    u = nextU;
    idx++;
  }
}

// ============================================================================
// 1. DUSKY TWILIGHT GROUND & ATMOSPHERE
// ============================================================================

function drawTwilightGround() {
  background("#1b1d25");

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Large atmospheric twilight watercolor washes
  const bgWashes = [
    { x: 600, y: 600, rx: 640, ry: 640, col: "#232530", op: 95, bleed: 0.45 },
    { x: 340, y: 310, rx: 480, ry: 420, col: "#2a2836", op: 75, bleed: 0.5 },
    { x: 860, y: 880, rx: 520, ry: 460, col: "#14161e", op: 110, bleed: 0.48 },
    { x: 260, y: 840, rx: 420, ry: 390, col: "#262228", op: 80, bleed: 0.45 },
    { x: 920, y: 310, rx: 410, ry: 380, col: "#1f242e", op: 75, bleed: 0.45 }
  ];

  for (let w of bgWashes) {
    brush.fill(w.col, w.op);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.65, 0.35);
    drawOrganicBlob(w.x, w.y, w.rx, w.ry, 28, 0.14);
  }

  // Deep cast shadow under the stump (offset down-right for twilight top-left light)
  const shadowLayers = [
    { dx: 26, dy: 32, uScale: 1.18, col: "#0f1016", op: 115, bleed: 0.42 },
    { dx: 14, dy: 18, uScale: 1.14, col: "#121117", op: 140, bleed: 0.28 },
    { dx: 5, dy: 7, uScale: 1.10, col: "#0c0b0f", op: 165, bleed: 0.15 }
  ];

  for (let sh of shadowLayers) {
    brush.fill(sh.col, sh.op);
    brush.fillBleed(sh.bleed, "out");
    brush.fillTexture(0.55, 0.4);
    brush.beginShape(0.25);
    for (let a = 0; a < 360; a += 8) {
      let pt = getStumpPoint(sh.uScale, a);
      brush.vertex(pt.x + sh.dx, pt.y + sh.dy);
    }
    brush.endShape(true);
  }

  // Subtle twilight graphite cross-hatching in the negative space around the stump
  brush.set("2B", "#14161f", 0.7);
  for (let i = 0; i < 160; i++) {
    let ang = random(360);
    let distR = random(515, 690);
    let cx = CENTER_X + cos(ang) * distR;
    let cy = CENTER_Y + sin(ang) * distR;
    let len = random(35, 95);
    let strokeAng = ang + 90 + random(-25, 25);
    brush.line(
      cx - cos(strokeAng) * len * 0.5,
      cy - sin(strokeAng) * len * 0.5,
      cx + cos(strokeAng) * len * 0.5,
      cy + sin(strokeAng) * len * 0.5
    );
  }

  // Fine twilight dust / forest floor detritus specks around the stump
  brush.set("spray", "#393c4a", 0.9);
  for (let i = 0; i < 45; i++) {
    let ang = random(360);
    let r = random(500, 620);
    let x = CENTER_X + cos(ang) * r;
    let y = CENTER_Y + sin(ang) * r;
    brush.line(x, y, x + random(-18, 18), y + random(-18, 18));
  }
}

function drawOrganicBlob(cx, cy, rx, ry, steps, irregularity) {
  brush.beginShape(0.3);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let n = noise(cos(a) * 1.5 + cx * 0.01, sin(a) * 1.5 + cy * 0.01);
    let radMod = 1.0 + (n - 0.5) * 2.0 * irregularity;
    brush.vertex(cx + cos(a) * rx * radMod, cy + sin(a) * ry * radMod);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. ROUGH BARK COLLAR (THE AGATE'S CRUST)
// ============================================================================

function drawBarkCollar() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base dark silhouette of the entire stump + bark crust so no background leaks through
  brush.wash("#231b18", 245);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 4) {
    let pt = getStumpPoint(1.10, a);
    let jag = 1.0 + (noise(cos(a) * 8 + 5, sin(a) * 8 + 5) - 0.5) * 0.07;
    brush.vertex(
      pt.cx + (pt.x - pt.cx) * jag,
      pt.cy + (pt.y - pt.cy) * jag
    );
  }
  brush.endShape(true);
  brush.noWash();

  // Build 56 tectonic bark plates around the circumference
  const numPlates = 56;
  const plateColors = [
    "#2b2322", "#382c29", "#463631", "#543d32",
    "#36343a", "#48454d", "#29201e", "#5e3c2c"
  ];

  let plates = [];
  let curAngle = 0;
  for (let i = 0; i < numPlates; i++) {
    let span = 360 / numPlates + random(-1.4, 1.4);
    let a1 = curAngle;
    let a2 = curAngle + span * 0.88; // Leave narrow fissure gap between plates
    curAngle += span;

    let uIn = random(0.975, 0.995);
    let uOut = random(1.07, 1.145);
    // Bark is slightly thicker near buttress lobes
    uOut += 0.025 * sin(3 * a1 + 45);

    plates.push({
      a1: a1,
      a2: a2,
      uIn: uIn,
      uOut: uOut,
      col: random(plateColors),
      isLit: cos(a1 - 225) > 0 // Top-left twilight illumination
    });
  }

  // Watercolor fill for each bark plate
  for (let p of plates) {
    brush.fill(p.col, random(155, 210));
    brush.fillBleed(0.16, "in");
    brush.fillTexture(0.75, 0.55);

    brush.beginShape(0.15);
    // Inner arc along cambium
    for (let a = p.a1; a <= p.a2; a += 1.5) {
      let pt = getStumpPoint(p.uIn, a);
      brush.vertex(pt.x, pt.y);
    }
    // Outer craggy bark edge
    for (let a = p.a2; a >= p.a1; a -= 1.5) {
      let jagU = p.uOut + (noise(a * 0.35, p.uOut * 10) - 0.5) * 0.045;
      let pt = getStumpPoint(jagU, a);
      brush.vertex(pt.x, pt.y);
    }
    brush.endShape(true);
  }

  // Detailed cork strata (periderm rings) & rugged fissures in pencil and ink
  for (let p of plates) {
    // Concentric layered bark striation lines inside each plate
    let strataCount = floor(random(5, 9));
    for (let s = 0; s < strataCount; s++) {
      let t = (s + 0.5) / strataCount;
      let uStrata = lerp(p.uIn, p.uOut, t);

      let col =
        t < 0.28
          ? "#7a4229" // Inner cinnamon phloem/bast
          : p.isLit && s % 2 === 0
          ? "#75737d" // Twilight grey-lavender highlight on outer bark scales
          : "#1d1716";

      brush.set(t < 0.3 ? "cpencil" : "2B", col, random(0.55, 0.95));
      let pts = [];
      for (let a = p.a1; a <= p.a2; a += 1.5) {
        let pt = getStumpPoint(
          uStrata + (noise(a * 0.5, s * 3.1) - 0.5) * 0.012,
          a
        );
        pts.push([pt.x, pt.y, random(0.6, 1.2)]);
      }
      if (pts.length >= 2) brush.spline(pts, 0.25);
    }

    // Deep radial fissure shadow on the side of each bark plate
    brush.set("rotring", "#120d0c", 1.05);
    let pIn = getStumpPoint(p.uIn, p.a2);
    let pMid = getStumpPoint((p.uIn + p.uOut) * 0.5, p.a2 + random(-0.6, 0.6));
    let pOut = getStumpPoint(p.uOut, p.a2 + random(-1.0, 1.0));
    brush.spline(
      [
        [pIn.x, pIn.y, 0.9],
        [pMid.x, pMid.y, 1.3],
        [pOut.x, pOut.y, 0.6]
      ],
      0.2
    );

    // Highlight ridge on lit side of plate
    if (p.isLit || random() < 0.45) {
      brush.set("cpencil", "#949099", 0.55);
      let hIn = getStumpPoint(p.uIn + 0.01, p.a1);
      let hOut = getStumpPoint(p.uOut - 0.01, p.a1);
      brush.line(hIn.x, hIn.y, hOut.x, hOut.y);
    }
  }

  // Crisp inner cambium collar line (the agate matrix boundary)
  for (let a = 0; a < 360; a += 60) {
    brush.set("rotring", "#2b160e", 0.9);
    let pts = [];
    for (let th = a; th <= a + 62; th += 2) {
      let pt = getStumpPoint(0.992, th);
      pts.push([pt.x, pt.y, random(0.7, 1.2)]);
    }
    brush.spline(pts, 0.3);
  }
}

// ============================================================================
// 3. TRANSLUCENT WATERCOLOR GLAZES (AGATE & WOOD BANDS)
// ============================================================================

function drawAgateWatercolorGlazes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base warm cream-parchment wash for the sawn wood surface so watercolor glazes glow
  brush.wash("#e8d6be", 230);
  brush.beginShape(0.2);
  for (let a = 0; a < 360; a += 4) {
    let pt = getStumpPoint(0.99, a);
    brush.vertex(pt.x, pt.y);
  }
  brush.endShape(true);
  brush.noWash();

  // Soft broad radial staining (e.g. twilight smoky mineral stain & warm amber heart glow)
  const broadDisks = [
    { u: 0.96, col: "#d9c3a8", op: 70, bleed: 0.22 },
    { u: 0.80, col: "#cfa068", op: 65, bleed: 0.25 },
    { u: 0.56, col: "#bd7a42", op: 60, bleed: 0.25 },
    { u: 0.32, col: "#9e4f28", op: 70, bleed: 0.25 },
    { u: 0.14, col: "#6e2e18", op: 95, bleed: 0.20 }
  ];

  for (let d of broadDisks) {
    brush.fill(d.col, d.op);
    brush.fillBleed(d.bleed, "in");
    brush.fillTexture(0.6, 0.35);
    brush.beginShape(0.25);
    for (let a = 0; a < 360; a += 6) {
      let pt = getStumpPoint(d.u, a);
      brush.vertex(pt.x, pt.y);
    }
    brush.endShape(true);
  }

  // Concentric Agate Annular Glaze Bands
  // Drawn as non-self-intersecting annular sector bands (3 sectors per ring)
  // so translucent cream, smoky grey-brown, honey, caramel, and rust bands stay distinct and luminous
  const glazeBands = [
    { u1: 0.92, u2: 0.985, col: "#635b5c", op: 95, bleed: 0.14 },  // Outer smoky agate rim
    { u1: 0.86, u2: 0.925, col: "#f2e5d0", op: 110, bleed: 0.10 }, // Luminous chalcedony cream
    { u1: 0.80, u2: 0.865, col: "#7a7073", op: 90, bleed: 0.14 },  // Smoky twilight grey-brown
    { u1: 0.74, u2: 0.805, col: "#d6954d", op: 95, bleed: 0.15 },  // Warm honey
    { u1: 0.69, u2: 0.745, col: "#8f4322", op: 105, bleed: 0.12 }, // Rust drought band
    { u1: 0.63, u2: 0.695, col: "#efe1ca", op: 105, bleed: 0.10 }, // Pale cream agate band
    { u1: 0.57, u2: 0.635, col: "#b86b35", op: 95, bleed: 0.15 },  // Rich caramel
    { u1: 0.51, u2: 0.575, col: "#5e5456", op: 95, bleed: 0.14 },  // Smoky quartz band
    { u1: 0.45, u2: 0.515, col: "#de9f54", op: 95, bleed: 0.14 },  // Golden honey
    { u1: 0.40, u2: 0.455, col: "#7d351b", op: 115, bleed: 0.12 }, // Deep rust ring
    { u1: 0.34, u2: 0.405, col: "#e8d5b9", op: 95, bleed: 0.12 },  // Cream band
    { u1: 0.28, u2: 0.345, col: "#ad5e2e", op: 100, bleed: 0.14 }, // Caramel
    { u1: 0.22, u2: 0.285, col: "#665957", op: 95, bleed: 0.14 },  // Smoky grey-brown
    { u1: 0.16, u2: 0.225, col: "#c9823e", op: 100, bleed: 0.14 }, // Amber honey
    { u1: 0.09, u2: 0.165, col: "#85381c", op: 115, bleed: 0.14 }, // Heartwood rust
    { u1: 0.03, u2: 0.095, col: "#4f2213", op: 130, bleed: 0.16 }  // Deep pith mahogany
  ];

  for (let b of glazeBands) {
    let offset = random(0, 120);
    for (let s = 0; s < 3; s++) {
      let aStart = offset + s * 120;
      let aEnd = aStart + 124; // Slight overlap for wet-on-wet watercolor transitions

      brush.fill(b.col, b.op + random(-12, 12));
      brush.fillBleed(b.bleed, "in");
      brush.fillTexture(0.65, 0.45);

      brush.beginShape(0.2);
      for (let a = aStart; a <= aEnd; a += 4) {
        let pt = getStumpPoint(b.u2, a);
        brush.vertex(pt.x, pt.y);
      }
      for (let a = aEnd; a >= aStart; a -= 4) {
        let pt = getStumpPoint(b.u1, a);
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(true);
    }
  }

  // Pith core dark spot
  brush.fill("#2e130b", 180);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.7, 0.5);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 15) {
    let pt = getStumpPoint(0.032, a);
    brush.vertex(pt.x, pt.y);
  }
  brush.endShape(true);

  // Subtle damp mineral/water stain near the creeping moss edge (140° to 235°)
  brush.fill("#3d4235", 65);
  brush.fillBleed(0.35, "in");
  brush.fillTexture(0.75, 0.4);
  brush.beginShape(0.25);
  for (let a = 135; a <= 240; a += 5) {
    let pt = getStumpPoint(0.99, a);
    brush.vertex(pt.x, pt.y);
  }
  for (let a = 240; a >= 135; a -= 5) {
    let uIn = 0.72 + 0.12 * sin((a - 135) * 1.7);
    let pt = getStumpPoint(uIn, a);
    brush.vertex(pt.x, pt.y);
  }
  brush.endShape(true);
}

// ============================================================================
// 4. MEDULLARY RAYS (FINE RADIAL FILAMENTS)
// ============================================================================

function drawMedullaryRays() {
  const numRays = 340;
  for (let i = 0; i < numRays; i++) {
    let baseAngle = (i / numRays) * 360 + random(-0.6, 0.6);
    let uStart = random() < 0.35 ? random(0.02, 0.15) : random(0.15, 0.65);
    let uEnd = min(0.985, uStart + random(0.18, 0.55));

    // Alternate between luminous cream-silk rays and subtle smoky/caramel rays
    let rayCol;
    let rPick = random();
    if (rPick < 0.42) rayCol = "#f5e8d3";
    else if (rPick < 0.72) rayCol = "#cfa067";
    else rayCol = "#695549";

    brush.set("agate_hairline", rayCol, random(0.45, 0.85));

    let pts = [];
    let steps = 7;
    let wavePhase = random(360);
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let u = lerp(uStart, uEnd, t);
      // Slight gentle curve as the ray crosses growth zones
      let angOffset = 1.2 * sin(u * 320 + wavePhase);
      let pt = getStumpPoint(u, baseAngle + angOffset);
      let pressure = sin(t * 180) * 0.9 + 0.25;
      pts.push([pt.x, pt.y, pressure]);
    }
    brush.spline(pts, 0.3);
  }
}

// ============================================================================
// 5. GROWTH RINGS & FORTIFICATION AGATE BANDING
// ============================================================================

function drawGrowthRingsAndAgateBanding() {
  for (let i = 0; i < ringSchedule.length; i++) {
    let ring = ringSchedule[i];

    // Determine latewood line color and weight based on palette family
    let lateCol, earlyCol, weightBase;
    switch (ring.type) {
      case "cream":
        lateCol = "#8c6d53";
        earlyCol = "#fff9ef";
        weightBase = 0.75;
        break;
      case "smoky":
        lateCol = "#453e3f";
        earlyCol = "#cfc7c6";
        weightBase = 0.85;
        break;
      case "honey":
        lateCol = "#9c5525";
        earlyCol = "#f2d6a7";
        weightBase = 0.80;
        break;
      case "caramel":
        lateCol = "#783719";
        earlyCol = "#e3be8f";
        weightBase = 0.90;
        break;
      case "rust":
      case "rust_drought":
      default:
        lateCol = "#4f1d0e";
        earlyCol = "#cfa376";
        weightBase = 1.05;
        break;
    }

    // 5A. Earlywood luminous agate highlight line (gives the translucent chalcedony depth)
    if (ring.type === "cream" || ring.type === "smoky" || i % 2 === 0) {
      let uEarly = ring.uInner + ring.du * 0.28;
      drawConcentricRing(
        uEarly,
        "agate_hairline",
        earlyCol,
        ring.type === "cream" ? 1.15 : 0.75,
        i * 19
      );
    }

    // 5B. Mid-ring subtle transition tone (agate micro-banding)
    if (ring.du > 0.0065) {
      let uMid = ring.uInner + ring.du * 0.62;
      let midCol =
        ring.type === "smoky"
          ? "#696163"
          : ring.type === "cream"
          ? "#d6c2a8"
          : "#b56c36";
      drawConcentricRing(uMid, "2H", midCol, 0.55, i * 31);
    }

    // 5C. Crisp latewood boundary ring (records the winter/drought arrest line)
    let brushName = ring.drought > 0.62 ? "rotring" : i % 3 === 0 ? "HB" : "2H";
    drawConcentricRing(
      ring.uOuter,
      brushName,
      lateCol,
      weightBase * map(ring.drought, 0, 1, 0.75, 1.35),
      i * 47
    );

    // 5D. Xylem vessel pores along major growth ring boundaries
    if (i % 4 === 1 && ring.uInner > 0.12 && ring.uInner < 0.94) {
      let poreCol = ring.uInner < 0.45 ? "#4a2212" : "#785843";
      brush.set("wood_pore", poreCol, 0.55);
      let aStart = random(0, 60);
      for (let a = aStart; a < 360; a += random(18, 36)) {
        let pt1 = getStumpPoint(ring.uInner + 0.0015, a);
        let pt2 = getStumpPoint(ring.uInner + 0.0015, a + random(5, 12));
        brush.line(pt1.x, pt1.y, pt2.x, pt2.y);
      }
    }
  }

  // Central pith cellular detail
  brush.set("rotring", "#1f0b05", 0.85);
  for (let r = 0.004; r <= 0.014; r += 0.004) {
    drawConcentricRing(r, "rotring", "#240d07", 0.75, r * 1000);
  }
}

function drawConcentricRing(u, brushName, col, weight, seedOffset) {
  // Draw in 3 overlapping 120° arcs with organic pressure modulation
  for (let s = 0; s < 3; s++) {
    let aStart = s * 120;
    let aEnd = aStart + 123;

    brush.set(brushName, col, weight);
    let pts = [];
    let step = u < 0.25 ? 6 : 3;

    for (let a = aStart; a <= aEnd; a += step) {
      let pt = getStumpPoint(u, a);
      let nP = noise(cos(a) * 2 + seedOffset, sin(a) * 2 + seedOffset);
      let pressure = map(nP, 0, 1, 0.45, 1.35);
      pts.push([pt.x, pt.y, pressure]);
    }
    brush.spline(pts, 0.35);
  }
}

// ============================================================================
// 6. SAW MARKS (FINE PENCIL KERF STRIATIONS)
// ============================================================================

function drawSawMarks() {
  // Parallel saw blade striations at ~23° across the stump face
  const sawAngle = 23;
  const cosA = cos(sawAngle);
  const sinA = sin(sawAngle);
  const perpX = -sinA;
  const perpY = cosA;

  // Sweep across the stump diameter from -430 to +430 perpendicular offset
  for (let offset = -425; offset <= 425; offset += random(3.2, 7.5)) {
    let baseX = CENTER_X + perpX * offset;
    let baseY = CENTER_Y + perpY * offset;

    // Approximate chord length inside the stump
    let normOff = abs(offset) / 435;
    if (normOff >= 0.98) continue;
    let halfChord = sqrt(1 - normOff * normOff) * 425;

    // Slight arc curvature of a large circular or band saw blade
    let bladeCurve = random(-14, 14) * (1 - normOff * 0.5);

    // Draw intermittent pencil kerf marks along this track
    let numSegments = floor(random(2, 5));
    for (let seg = 0; seg < numSegments; seg++) {
      let t1 = random(-0.88, 0.45);
      let t2 = min(0.90, t1 + random(0.18, 0.55));

      // Alternate between fine pale wood-dust scuff and subtle graphite groove
      let isLightScuff = random() < 0.48;
      let col = isLightScuff ? "#f5e7d0" : "#4a3b34";
      let bName = isLightScuff ? "agate_hairline" : "2H";
      let w = isLightScuff ? random(0.4, 0.75) : random(0.35, 0.65);

      brush.set(bName, col, w);

      let pts = [];
      for (let k = 0; k <= 4; k++) {
        let t = lerp(t1, t2, k / 4);
        let d = t * halfChord;
        let curveDeflect = bladeCurve * (1 - t * t);
        let px = baseX + cosA * d + perpX * curveDeflect;
        let py = baseY + sinA * d + perpY * curveDeflect;

        // Verify point is inside the sawn wood face
        if (dist(px, py, CENTER_X, CENTER_Y) < 428) {
          pts.push([px, py, sin((k / 4) * 180) * 0.9 + 0.2]);
        }
      }
      if (pts.length >= 2) {
        brush.spline(pts, 0.25);
      }
    }
  }
}

// ============================================================================
// 7. RADIAL CRACKS (HEART CHECKS & SEASONING SPLITS)
// ============================================================================

function drawRadialCracks() {
  for (let c of CRACKS) {
    let steps = 28;
    let spine = [];
    let leftLip = [];
    let rightLip = [];

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let u = lerp(c.startU, c.endU, t);

      // Jagged deflection when crossing dense latewood rings
      let jagAngle =
        c.angle +
        (noise(u * 16, c.seed) - 0.5) * 7.5 +
        1.4 * sin(u * 900 + c.seed * 10);

      let pt = getStumpPoint(u, jagAngle);

      // Crack width profile: wide near pith/mid-heart, tapering to 0 at tip
      let wProfile;
      if (c.startU === 0) {
        wProfile = pow(1.0 - t, 1.35) * (0.65 + 0.35 * sin(t * 180));
      } else {
        wProfile = sin(t * 180) * (1.0 - t * 0.35);
      }
      let halfW = c.maxW * 0.5 * wProfile * (0.75 + 0.5 * noise(u * 25, c.seed + 5));
      if (i === steps) halfW = 0;

      // Perpendicular unit vector
      let perpA = jagAngle + 90;
      let nx = cos(perpA);
      let ny = sin(perpA);

      spine.push({ x: pt.x, y: pt.y, u: u, ang: jagAngle, halfW: halfW });
      leftLip.push([pt.x + nx * halfW, pt.y + ny * halfW]);
      rightLip.push([pt.x - nx * halfW, pt.y - ny * halfW]);
    }

    // 7A. Subtle dark wood-stress shadow halo around the fissure
    brush.noStroke();
    brush.fill("#2b160e", 75);
    brush.fillBleed(0.18, "out");
    brush.fillTexture(0.5, 0.3);
    brush.beginShape(0.15);
    for (let i = 0; i <= steps; i++) {
      brush.vertex(leftLip[i][0], leftLip[i][1]);
    }
    for (let i = steps; i >= 0; i--) {
      brush.vertex(rightLip[i][0], rightLip[i][1]);
    }
    brush.endShape(true);

    // 7B. Deep abyssal shadow inside the split cavity
    brush.wash("#110b0a", 245);
    brush.beginShape(0.08);
    for (let i = 0; i <= steps; i++) {
      brush.vertex(leftLip[i][0], leftLip[i][1]);
    }
    for (let i = steps; i >= 0; i--) {
      brush.vertex(rightLip[i][0], rightLip[i][1]);
    }
    brush.endShape(true);
    brush.noWash();

    // 7C. Lit splintered wood bevel along the lip facing top-left light
    brush.set("agate_hairline", "#f7e8d0", 1.15);
    let litPts = [];
    for (let i = 0; i <= steps; i++) {
      litPts.push([
        leftLip[i][0] + 0.8,
        leftLip[i][1] + 0.8,
        1.1 * (1 - i / steps) + 0.2
      ]);
    }
    brush.spline(litPts, 0.15);

    // 7D. Crisp dark graphite / ink edge along both lips
    brush.set("rotring", "#0d0807", 0.95);
    let darkPts1 = leftLip.map((p, idx) => [p[0], p[1], 1.2 * (1 - idx / steps) + 0.3]);
    let darkPts2 = rightLip.map((p, idx) => [p[0], p[1], 1.0 * (1 - idx / steps) + 0.3]);
    brush.spline(darkPts1, 0.15);
    brush.spline(darkPts2, 0.15);

    // 7E. Fine secondary lightning micro-checks branching off the main crack
    for (let i = 3; i < steps - 3; i += floor(random(4, 7))) {
      if (random() < 0.65) {
        let sp = spine[i];
        let side = random() < 0.5 ? 1 : -1;
        let branchAng = sp.ang + side * random(18, 38);
        let bLen = random(14, 36);

        brush.set("rotring", "#1c100c", 0.65);
        let bPts = [
          [sp.x, sp.y, 1.0],
          [
            sp.x + cos(branchAng) * bLen * 0.5 + random(-3, 3),
            sp.y + sin(branchAng) * bLen * 0.5 + random(-3, 3),
            0.7
          ],
          [
            sp.x + cos(branchAng) * bLen,
            sp.y + sin(branchAng) * bLen,
            0.2
          ]
        ];
        brush.spline(bPts, 0.2);
      }
    }
  }
}

// ============================================================================
// 8. CREEPING MOSS & LICHEN AT ONE EDGE
// ============================================================================

function drawMossAndLichen() {
  // Primary moss colony creeping over the upper-left / left bark edge (138° to 232°)
  // plus a smaller secondary tuft around 108°..128°
  let mossClusters = [];

  for (let a = 136; a <= 234; a += random(3.2, 5.5)) {
    // Envelope: deepest intrusion onto the sawn wood around 172° (along the big scar/crack!)
    let env = sin(map(a, 136, 234, 0, 180));
    let maxInwardU = 1.0 - env * 0.24 - (a > 160 && a < 182 ? 0.11 : 0);

    let numMounds = floor(map(env, 0, 1, 2, 5));
    for (let m = 0; m < numMounds; m++) {
      let u = lerp(1.11, maxInwardU, m / numMounds) + random(-0.025, 0.025);
      let pt = getStumpPoint(u, a + random(-2, 2));
      let rad = map(m, 0, numMounds, 26, 11) * (0.75 + 0.5 * noise(a * 0.2, m));
      mossClusters.push({ x: pt.x, y: pt.y, r: rad, u: u, a: a });
    }
  }

  // Secondary smaller moss colony at 106°..126°
  for (let a = 106; a <= 126; a += 4.5) {
    let env = sin(map(a, 106, 126, 0, 180));
    for (let m = 0; m < 2; m++) {
      let u = lerp(1.10, 0.92, (m / 2) * env);
      let pt = getStumpPoint(u, a);
      mossClusters.push({ x: pt.x, y: pt.y, r: random(10, 19), u: u, a: a });
    }
  }

  // 8A. Deep damp peat-shadow watercolor base under the moss cushions
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  for (let mc of mossClusters) {
    brush.fill("#152116", 130);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.75, 0.5);
    drawOrganicBlob(mc.x + 3, mc.y + 4, mc.r * 1.15, mc.r * 1.15, 12, 0.25);
  }

  // 8B. Mid-tone velvety olive and forest-green watercolor cushions
  const mossWashes = ["#243822", "#314d2c", "#426336", "#537840"];
  for (let mc of mossClusters) {
    let col = random(mossWashes);
    brush.fill(col, 155);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.8, 0.55);
    drawOrganicBlob(mc.x, mc.y, mc.r, mc.r * 0.92, 12, 0.28);
  }

  // 8C. Dry-pigment mass & custom tuft texture for plush bryophyte density
  for (let i = 0; i < mossClusters.length; i += 2) {
    let mc = mossClusters[i];
    brush.noStroke();
    brush.mass("cpencil", i % 4 === 0 ? "#698f4d" : "#38542e", {
      precision: 0.35,
      strength: 0.65,
      gradient: 0.3,
      outline: false
    });
    brush.circle(mc.x - 1, mc.y - 1, mc.r * 0.65, 0.35);
    brush.noMass();
  }

  // 8D. Hundreds of individual star-moss (Polytrichum) micro-rosettes & creeping rhizoids
  const shootColors = [
    "#1c2e1a", "#2e4727", "#486b3a", "#658c4d",
    "#86ad63", "#a7c97b", "#cbe09d"
  ];

  for (let mc of mossClusters) {
    let numRosettes = floor(map(mc.r, 10, 28, 5, 14));
    for (let r = 0; r < numRosettes; r++) {
      let ang = random(360);
      let d = random(0, mc.r * 0.95);
      let rx = mc.x + cos(ang) * d;
      let ry = mc.y + sin(ang) * d;

      // Choose color: brighter yellow-green on top-left lit side of each cushion
      let isTopLeft = cos(ang - 225) > -0.1;
      let cIdx = isTopLeft
        ? floor(random(3, shootColors.length))
        : floor(random(0, 4));
      let col = shootColors[cIdx];

      brush.set("cpencil", col, random(0.45, 0.8));
      let needles = floor(random(4, 7));
      let baseRot = random(360);
      for (let n = 0; n < needles; n++) {
        let nAng = baseRot + (n / needles) * 360 + random(-15, 15);
        let nLen = random(3.5, 8.5);
        brush.line(rx, ry, rx + cos(nAng) * nLen, ry + sin(nAng) * nLen);
      }

      // Tiny luminous spore capsule / tip dot
      if (isTopLeft && random() < 0.45) {
        brush.set("rotring", "#d9eba8", 0.65);
        brush.line(rx, ry, rx + 1.2, ry + 1.2);
      }
    }
  }

  // 8E. Delicate creeping moss protonema tendrils reaching onto the sawn wood rings
  for (let a = 140; a <= 230; a += random(2.5, 4.5)) {
    let env = sin(map(a, 140, 230, 0, 180));
    let uStart = 1.0 - env * 0.20 - (a > 162 && a < 180 ? 0.09 : 0);
    let uEnd = uStart - random(0.03, 0.085);

    brush.set("cpencil", random(["#4d6e3b", "#719653", "#2b4024"]), 0.55);
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      let t = s / 5;
      let u = lerp(uStart, uEnd, t);
      let th = a + sin(t * 240 + a) * 2.2;
      let pt = getStumpPoint(u, th);
      pts.push([pt.x, pt.y, 1.1 * (1 - t) + 0.2]);
    }
    brush.spline(pts, 0.35);
  }

  // 8F. Pale grey-green crustose lichen patches on adjacent bark plates
  const lichenAngles = [92, 98, 130, 242, 248, 255, 310];
  for (let la of lichenAngles) {
    let pt = getStumpPoint(random(1.02, 1.09), la);
    brush.noStroke();
    brush.fill("#85968b", 135);
    brush.fillBleed(0.15, "out");
    drawOrganicBlob(pt.x, pt.y, random(7, 14), random(6, 12), 10, 0.3);

    brush.set("agate_hairline", "#c5d4c9", 0.7);
    brush.circle(pt.x, pt.y, random(4, 9), 0.35);
  }
}

// ============================================================================
// 9. GLISTENING SAP BEADS (TRANSLUCENT RESIN DROPLETS)
// ============================================================================

function drawSapBeads() {
  // Place sap beads along resin canals, near cracks, and near the cambium ring
  const sapBeads = [
    // Clustered near the main 38° crack and honey/heartwood rings
    { u: 0.42, a: 41, r: 9.5 },
    { u: 0.445, a: 43.2, r: 5.2 },
    { u: 0.68, a: 35, r: 7.8 },
    // Along the 168° scar/crack
    { u: 0.31, a: 164, r: 11.0 },
    { u: 0.335, a: 161.5, r: 6.0 },
    { u: 0.54, a: 171, r: 8.4 },
    { u: 0.56, a: 173, r: 4.5 },
    // Along the 288° crack
    { u: 0.48, a: 285, r: 10.2 },
    { u: 0.505, a: 282.5, r: 5.8 },
    { u: 0.22, a: 292, r: 7.2 },
    // Outer sapwood / cambium resin duct beads
    { u: 0.85, a: 12, r: 6.5 },
    { u: 0.855, a: 14.5, r: 4.0 },
    { u: 0.88, a: 78, r: 8.2 },
    { u: 0.82, a: 118, r: 7.0 },
    { u: 0.79, a: 215, r: 6.2 },
    { u: 0.91, a: 258, r: 8.8 },
    { u: 0.915, a: 261, r: 4.8 },
    { u: 0.84, a: 318, r: 7.5 },
    { u: 0.76, a: 348, r: 5.5 },
    // Inner heartwood resin pearls
    { u: 0.15, a: 88, r: 6.8 },
    { u: 0.19, a: 205, r: 5.4 }
  ];

  for (let b of sapBeads) {
    let pt = getStumpPoint(b.u, b.a);
    drawSingleSapBead(pt.x, pt.y, b.r);
  }
}

function drawSingleSapBead(x, y, r) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // 1. Cast shadow on the wood to the bottom-right (light comes from top-left)
  brush.fill("#261007", 150);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.4, 0.3);
  drawOrganicBlob(x + r * 0.38, y + r * 0.42, r * 0.95, r * 0.88, 14, 0.08);

  // 2. Rich amber-rust base body of the resin droplet
  brush.wash("#8c3712", 215);
  drawOrganicBlob(x, y, r, r * 0.94, 16, 0.06);
  brush.noWash();

  // 3. Deeper mahogany-amber crescent on the upper-left interior (refraction shadow)
  brush.fill("#4f1907", 170);
  brush.fillBleed(0.12, "in");
  drawOrganicBlob(x - r * 0.18, y - r * 0.18, r * 0.78, r * 0.72, 14, 0.06);

  // 4. Luminous golden-honey internal caustic glow on the lower-right
  brush.wash("#f09b2e", 220);
  drawOrganicBlob(x + r * 0.18, y + r * 0.18, r * 0.65, r * 0.60, 14, 0.05);

  brush.wash("#ffd46b", 235);
  drawOrganicBlob(x + r * 0.24, y + r * 0.24, r * 0.42, r * 0.36, 12, 0.04);
  brush.noWash();

  // 5. Crisp dark meniscus contour around the bead
  brush.set("rotring", "#361105", 0.75);
  brush.circle(x, y, r * 0.96, 0.06);

  // 6. Brilliant specular highlight arc & pinpoint reflection on the upper-left dome
  brush.noStroke();
  brush.wash("#fffdf7", 250);
  drawOrganicBlob(x - r * 0.32, y - r * 0.32, r * 0.26, r * 0.18, 10, 0.04);
  brush.noWash();

  brush.set("rotring", "#ffffff", 0.95);
  brush.arc(x - r * 0.05, y - r * 0.05, r * 0.64, 195, 255);

  // Secondary tiny rim reflection on bottom-right edge
  brush.set("agate_hairline", "#ffefc2", 0.85);
  brush.arc(x, y, r * 0.82, 20, 65);
}

// Hyperrealist Overhead Study: Folded Wool Sweaters in a Diamond-in-a-Square Quilt
// Alcohol-marker grounds with dense colored-pencil cable knits, pilled fibres & stray wool threads

const SEED = 42891;

// North light direction in canvas space (even cool overhead light from top / slightly top-left)
const LIGHT_X = -0.22;
const LIGHT_Y = -0.975;

