async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom chisel alcohol marker for broad, disciplined underpainting passes
  brush.add("alcohol_chisel", {
    type: "marker",
    weight: 16,
    scatter: 0.05,
    opacity: 36,
    spacing: 0.28,
    pressure: [0.94, 1.0, 0.94],
    rotate: "natural",
    markerTip: false,
    noise: 0.14
  });

  // Narrower alcohol marker for recessed purl channels & fold valleys
  brush.add("alcohol_detail", {
    type: "marker",
    weight: 6.5,
    scatter: 0.08,
    opacity: 48,
    spacing: 0.3,
    pressure: [0.85, 1.0, 0.85],
    rotate: "natural",
    markerTip: false,
    noise: 0.2
  });

  // Crisp colored-pencil brush for individual knit plies, V-loops & cable twists
  brush.add("wool_pencil", {
    type: "default",
    weight: 1.25,
    scatter: 0.28,
    sharpness: 0.64,
    grain: 14,
    opacity: 170,
    spacing: 0.42,
    pressure: [0.65, 1.15, 0.65],
    rotate: "natural",
    noise: 0.42
  });

  // Chalky soft-pastel colored pencil for north-light wool sheen, neps & fuzzy halo
  brush.add("pastel_pencil", {
    type: "default",
    weight: 1.4,
    scatter: 0.44,
    sharpness: 0.42,
    grain: 18,
    opacity: 155,
    spacing: 0.44,
    pressure: [0.55, 1.1, 0.55],
    rotate: "natural",
    noise: 0.52
  });

  buildQuiltGeometry();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e8e2da");
  brush.noField();

  // 1. Lay down flat alcohol-marker washes & directional chisel passes for all garments
  renderAlcoholMarkerGrounds();

  // 2. Rebuild every cable knit, purl trench, moss stitch & ribbed cuff in colored pencil
  for (let g of garments) {
    renderGarmentKnitwear(g);
  }

  // 3. Render internal folded garment tucks (waistband hem & folded sleeve creases)
  for (let g of garments) {
    if (g.internalFold) {
      renderInternalFoldCrease(g);
    }
  }

  // 4. Render crisp, plump 3D seams where the folded sweaters meet edge to edge
  for (let s of seams) {
    renderGarmentSeam(s);
  }

  // 5. Render tactile surface realism: 3D pilled wool fibres (neps) & wispy stray threads
  for (let g of garments) {
    renderPillsAndStrayThreads(g);
  }

  noLoop();
}

