function buildQuiltGeometry() {
  const M = 108; // Outer border width
  const L = 1200 - M; // 1092
  const C = 600; // Center 600

  // Key vertices
  const pTL = [M, M];
  const pTM = [C, M];
  const pTR = [L, M];
  const pRM = [L, C];
  const pBR = [L, L];
  const pBM = [C, L];
  const pBL = [M, L];
  const pLM = [M, C];

  // 1. Central Diamond (Cranberry Aran Sweater on the diagonal bias)
  garments.push(
    createGarment("center_diamond", [pTM, pRM, pBM, pLM], "cranberry", -Math.PI / 4, "aran_medallion", {
      vCut: -212,
      foldSide: -1
    })
