    createGarment("corner_tr", [[L, 0], [1200, 0], [1200, M], pTR], "cranberry", Math.PI / 2, "cuff_rib", null)
  );
  garments.push(
    createGarment("corner_br", [pBR, [1200, L], [1200, 1200], [L, 1200]], "aubergine", 0, "cuff_rib", null)
