  // Register all interior seams between adjacent folded sweaters
  // 4 diagonal diamond seams
  seams.push({ a: pTM, b: pLM, pal1: PALETTES.teal, pal2: PALETTES.cranberry, id: 1 });
  seams.push({ a: pTM, b: pRM, pal1: PALETTES.cranberry, pal2: PALETTES.aubergine, id: 2 });
  seams.push({ a: pRM, b: pBM, pal1: PALETTES.cranberry, pal2: PALETTES.green, id: 3 });
  seams.push({ a: pLM, b: pBM, pal1: PALETTES.black, pal2: PALETTES.cranberry, id: 4 });

  // 8 square-to-border seams
  seams.push({ a: pTL, b: pTM, pal1: PALETTES.green, pal2: PALETTES.teal, id: 5 });
  seams.push({ a: pTM, b: pTR, pal1: PALETTES.green, pal2: PALETTES.aubergine, id: 6 });
