function createGarment(id, poly, paletteKey, theta, patternType, internalFold) {
  let cx = 0;
  let cy = 0;
  for (let p of poly) {
    cx += p[0];
    cy += p[1];
  }
  cx /= poly.length;
  cy /= poly.length;

  const cosT = Math.cos(theta);
  const sinT = Math.sin(theta);

  // Compute local bounding box (u, v)
  let uMin = Infinity, uMax = -Infinity;
  let vMin = Infinity, vMax = -Infinity;
  for (let p of poly) {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let u = dx * cosT + dy * sinT;
    let v = -dx * sinT + dy * cosT;
    if (u < uMin) uMin = u;
    if (u > uMax) uMax = u;
    if (v < vMin) vMin = v;
    if (v > vMax) vMax = v;
  }

  // Precompute inward edge normals for fast Cyrus-Beck clipping
  let edges = [];
  for (let i = 0; i < poly.length; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % poly.length];
    let ex = p2[0] - p1[0];
    let ey = p2[1] - p1[1];
    let len = Math.hypot(ex, ey);
    // Inward normal for clockwise/counterclockwise check against centroid
    let nx = -ey / len;
    let ny = ex / len;
    if (nx * (cx - p1[0]) + ny * (cy - p1[1]) < 0) {
      nx = -nx;
      ny = -ny;
    }
    edges.push({ p1, p2, nx, ny, len });
  }

  let strips = buildStripLayout(patternType, uMin, uMax);

  return {
    id,
    poly,
    edges,
    pal: PALETTES[paletteKey],
    cx,
    cy,
    theta,
    cosT,
    sinT,
    uMin,
    uMax,
    vMin,
    vMax,
    patternType,
    strips,
    internalFold
  };
}

function toWorld(g, u, v) {
  return [
    g.cx + u * g.cosT - v * g.sinT,
    g.cy + u * g.sinT + v * g.cosT
  ];
}

// Compute how strongly a local normal (nu, nv) faces the overhead North Light (-0.22, -0.975)
function getNorthLightDot(g, nu, nv) {
  let wx = nu * g.cosT - nv * g.sinT;
  let wy = nu * g.sinT + nv * g.cosT;
  return LIGHT_X * wx + LIGHT_Y * wy;
}

// Exact Cyrus-Beck segment clipper against convex garment polygon with optional inset
function clipSegmentToGarment(g, x1, y1, x2, y2, inset = 1.2) {
  let t0 = 0.0;
  let t1 = 1.0;
  let dx = x2 - x1;
  let dy = y2 - y1;

  for (let i = 0; i < g.edges.length; i++) {
    let e = g.edges[i];
    // Signed distance of (x1, y1) inside inset edge
    let num = (x1 - e.p1[0]) * e.nx + (y1 - e.p1[1]) * e.ny - inset;
    let den = dx * e.nx + dy * e.ny;

    if (Math.abs(den) < 1e-6) {
      if (num < 0) return null;
    } else {
      let t = -num / den;
      if (den > 0) {
        // Entering
        if (t > t0) t0 = t;
      } else {
        // Leaving
        if (t < t1) t1 = t;
      }
      if (t0 > t1) return null;
    }
  }

  let cx1 = x1 + t0 * dx;
  let cy1 = y1 + t0 * dy;
  let cx2 = x1 + t1 * dx;
  let cy2 = y1 + t1 * dy;
  if (Math.hypot(cx2 - cx1, cy2 - cy1) < 1.2) return null;
  return [cx1, cy1, cx2, cy2];
}

function pointInGarment(g, x, y, inset = 1.5) {
  for (let i = 0; i < g.edges.length; i++) {
    let e = g.edges[i];
    let dist = (x - e.p1[0]) * e.nx + (y - e.p1[1]) * e.ny;
    if (dist < inset) return false;
  }
  return true;
}

// ============================================================================
// LAYER 1: FLAT ALCOHOL-MARKER GROUNDS
// ============================================================================

function renderAlcoholMarkerGrounds() {
  // Batch washes by palette color for optimal p5.brush caching
  const keys = Object.keys(PALETTES);
  brush.noStroke();

  for (let k of keys) {
    let pal = PALETTES[k];
    for (let g of garments) {
      if (g.pal.name !== k) continue;

      // Solid alcohol-marker base wash
      brush.wash(pal.markerBase, 242);
      brush.fill(pal.markerBase, 145);
      brush.fillBleed(0.015, "in");
      brush.fillTexture(0.22, 0.12);
      brush.beginShape(0);
      for (let pt of g.poly) {
        brush.vertex(pt[0], pt[1]);
      }
      brush.endShape(true);
    }
  }
  brush.noFill();
  brush.noWash();

  // Directional alcohol-marker chisel passes along the knit direction of each sweater
  for (let g of garments) {
    brush.set("alcohol_chisel", g.pal.markerBase, 1.0);
    let stepU = 19;
    for (let u = g.uMin + 6; u <= g.uMax - 6; u += stepU) {
      let [x1, y1] = toWorld(g, u, g.vMin - 10);
      let [x2, y2] = toWorld(g, u, g.vMax + 10);
      let seg = clipSegmentToGarment(g, x1, y1, x2, y2, 4.0);
      if (seg) {
        brush.line(seg[0], seg[1], seg[2], seg[3]);
      }
    }

    // Deeper alcohol-marker passes in the recessed purl trenches
    brush.set("alcohol_detail", g.pal.markerDark, 0.95);
    for (let s of g.strips) {
      if (s.type === "purl" || s.type === "honeycomb") {
        let uMid = (s.u0 + s.u1) * 0.5;
        let [x1, y1] = toWorld(g, uMid, g.vMin - 10);
        let [x2, y2] = toWorld(g, uMid, g.vMax + 10);
        let seg = clipSegmentToGarment(g, x1, y1, x2, y2, 3.0);
        if (seg) {
          brush.line(seg[0], seg[1], seg[2], seg[3]);
        }
      }
    }
  }
}

// ============================================================================
// KNIT & CABLE STRIP ARCHITECTURE
// ============================================================================

function buildStripLayout(patternType, uMin, uMax) {
  let strips = [];

  if (patternType === "cuff_rib") {
    // 2x2 folded ribbed cuff blocks
    let u = uMin - 8;
    let idx = 0;
    while (u < uMax + 8) {
      let w = idx % 2 === 0 ? 15 : 11;
      strips.push({
        u0: u,
        u1: u + w,
        type: idx % 2 === 0 ? "rib2" : "purl",
        dir: 1,
        period: 60,
        phase: 0
      });
      u += w;
      idx++;
    }
    return strips;
  }

  // Define symmetric or repeating unit sequences of Aran knit strips
  let sequence = [];
  if (patternType === "aran_medallion") {
    // Central Honeycomb Diamond flanked by purls, 6-wale ropes, twisted ribs & 3-strand braids
    sequence = [
      { w: 14, type: "purl", dir: 1, period: 68 },
      { w: 48, type: "rope", dir: -1, period: 70 },
      { w: 13, type: "purl", dir: 1, period: 68 },
      { w: 14, type: "rib1", dir: 1, period: 68 },
      { w: 13, type: "purl", dir: 1, period: 68 },
      { w: 58, type: "braid", dir: 1, period: 84 },
      { w: 14, type: "purl", dir: 1, period: 68 },
      { w: 48, type: "rope", dir: 1, period: 72 },
      { w: 15, type: "purl", dir: 1, period: 68 },
      { w: 74, type: "honeycomb", dir: 1, period: 104 },
      { w: 15, type: "purl", dir: 1, period: 68 },
      { w: 48, type: "rope", dir: -1, period: 72 },
      { w: 14, type: "purl", dir: 1, period: 68 },
      { w: 58, type: "braid", dir: -1, period: 84 },
      { w: 13, type: "purl", dir: 1, period: 68 },
      { w: 14, type: "rib1", dir: 1, period: 68 },
      { w: 13, type: "purl", dir: 1, period: 68 },
      { w: 48, type: "rope", dir: 1, period: 70 },
      { w: 14, type: "purl", dir: 1, period: 68 }
    ];
  } else if (patternType === "fisherman_cable") {
    sequence = [
      { w: 44, type: "rope", dir: 1, period: 66 },
      { w: 13, type: "purl", dir: 1, period: 66 },
      { w: 28, type: "rib3", dir: 1, period: 66 },
      { w: 13, type: "purl", dir: 1, period: 66 },
      { w: 38, type: "rope", dir: 1, period: 64 },
      { w: 4, type: "purl", dir: 1, period: 64 },
      { w: 38, type: "rope", dir: -1, period: 64 }, // Staghorn mirror pair
      { w: 13, type: "purl", dir: 1, period: 66 },
      { w: 28, type: "rib3", dir: 1, period: 66 },
      { w: 13, type: "purl", dir: 1, period: 66 }
    ];
  } else if (patternType === "staghorn_moss") {
    sequence = [
      { w: 32, type: "moss", dir: 1, period: 64 },
      { w: 13, type: "purl", dir: 1, period: 64 },
      { w: 46, type: "rope", dir: -1, period: 68 },
      { w: 13, type: "purl", dir: 1, period: 64 },
      { w: 14, type: "rib1", dir: 1, period: 64 },
      { w: 13, type: "purl", dir: 1, period: 64 },
      { w: 54, type: "braid", dir: 1, period: 80 },
      { w: 13, type: "purl", dir: 1, period: 64 },
      { w: 14, type: "rib1", dir: 1, period: 64 },
      { w: 13, type: "purl", dir: 1, period: 64 },
      { w: 46, type: "rope", dir: 1, period: 68 },
      { w: 13, type: "purl", dir: 1, period: 64 }
    ];
  } else {
    // border_cable
    sequence = [
      { w: 12, type: "purl", dir: 1, period: 64 },
      { w: 16, type: "rib2", dir: 1, period: 64 },
      { w: 12, type: "purl", dir: 1, period: 64 },
      { w: 44, type: "rope", dir: 1, period: 66 },
      { w: 12, type: "purl", dir: 1, period: 64 },
      { w: 16, type: "rib2", dir: 1, period: 64 },
      { w: 12, type: "purl", dir: 1, period: 64 }
    ];
  }

  let seqWidth = 0;
  for (let item of sequence) seqWidth += item.w;

  // Tile sequence across [uMin - 20, uMax + 20] centered at u = 0
  let startU = -seqWidth * 0.5;
  while (startU > uMin - 20) startU -= seqWidth;

  let curU = startU;
  let phaseIdx = 0;
  while (curU < uMax + 20) {
    for (let item of sequence) {
      let u0 = curU;
      let u1 = curU + item.w;
      if (u1 >= uMin - 15 && u0 <= uMax + 15) {
        strips.push({
          u0,
          u1,
          type: item.type,
          dir: item.dir,
          period: item.period,
          phase: (phaseIdx * 17) % item.period
        });
      }
      curU = u1;
      phaseIdx++;
    }
  }

  return strips;
}

// ============================================================================
// LAYER 2 & 3: COLORED-PENCIL KNITWEAR RECONSTRUCTION
// ============================================================================

function renderGarmentKnitwear(g) {
  // Collect strokes in 6 tonal tiers so dark crevices lie beneath midtones & north-light pastel crowns
  const buckets = {
    shadowDeep: [], // [x1, y1, x2, y2, weight]
    midDark: [],
    midMain: [],
    midLight: [],
    pastelGlow: [],
    splinesShadow: [], // [ptsArray, curvature, weight]
    splinesMain: [],
    splinesLight: [],
    splinesPastel: []
  };

  function addSeg(tier, u1, v1, u2, v2, w = 1.0) {
    let [x1, y1] = toWorld(g, u1, v1);
    let [x2, y2] = toWorld(g, u2, v2);
    let c = clipSegmentToGarment(g, x1, y1, x2, y2, 1.5);
    if (c) {
      buckets[tier].push([c[0], c[1], c[2], c[3], w]);
    }
  }

  function addSpline(tier, uvPts, curv = 0.5, w = 1.0) {
    let worldPts = [];
    for (let p of uvPts) {
      let [wx, wy] = toWorld(g, p[0], p[1]);
      if (pointInGarment(g, wx, wy, 1.8)) {
        worldPts.push([wx, wy, p[2] || 1.0]);
      } else {
        if (worldPts.length >= 3) {
          buckets[tier].push([worldPts, curv, w]);
        }
        worldPts = [];
      }
    }
    if (worldPts.length >= 3) {
      buckets[tier].push([worldPts, curv, w]);
    }
  }

  // Helper to check if (u, v) falls inside the garment's folded ribbed cuff/waistband zone
  function isInFoldedRibZone(v) {
    if (!g.internalFold) return false;
    if (g.internalFold.foldSide < 0) return v < g.internalFold.vCut;
    return v > g.internalFold.vCut;
  }

  // Helper to render a single sculpted knit V-loop stitch at (uCenter, vCenter)
  // tangentSlope = du/dv of the yarn strand, elevation z in [-1, 1]
  function emitKnitStitch(uC, vC, wWale, hRow, tangentSlope = 0, z = 0) {
    // Quick check if stitch center is inside polygon
    let [wx, wy] = toWorld(g, uC, vC);
    if (!pointInGarment(g, wx, wy, 1.0)) return;

    let halfW = wWale * 0.44;
    let halfH = hRow * 0.48;
    let shiftU = tangentSlope * halfH * 0.65;

    // Left leg of V-stitch: slopes down-inward; normal points up-left
    let luTop = uC - halfW + shiftU;
    let lvTop = vC - halfH;
    let luBot = uC - halfW * 0.08 - shiftU * 0.3;
    let lvBot = vC + halfH;

    // Right leg of V-stitch: slopes down-inward; normal points up-right
    let ruTop = uC + halfW + shiftU;
    let rvTop = vC - halfH;
    let ruBot = uC + halfW * 0.08 - shiftU * 0.3;
    let rvBot = vC + halfH;

    // Local 3D surface normals for left leg, right leg, and upper loop crown
    let dotLeft = getNorthLightDot(g, -0.78, -0.45 + z * 0.35);
    let dotRight = getNorthLightDot(g, 0.78, -0.45 + z * 0.35);
    let dotCrown = getNorthLightDot(g, tangentSlope * 0.4, -0.88) + z * 0.28;

    // 1. Deep root shadow at the base of the V-stitch where loop tucks into previous course
    addSeg("shadowDeep", luBot - 1.1, lvBot - 0.5, ruBot + 1.1, lvBot + 0.6, 0.95);

    // 2. Left leg colored-pencil plies
    if (dotLeft > 0.18) {
      addSeg("midMain", luTop - 0.7, lvTop, luBot - 0.5, lvBot, 0.95);
      addSeg("midLight", luTop + 0.3, lvTop, luBot + 0.3, lvBot, 1.0);
      if (dotLeft > 0.48 || z > 0.35) {
        addSeg("pastelGlow", luTop + 0.6, lvTop + 0.4, (luTop + luBot) * 0.5 + 0.4, (lvTop + lvBot) * 0.5, 0.85);
      }
    } else {
      addSeg("shadowDeep", luTop - 0.8, lvTop, luBot - 0.6, lvBot, 0.9);
      addSeg("midDark", luTop, lvTop, luBot, lvBot, 0.95);
      addSeg("midMain", luTop + 0.6, lvTop, luBot + 0.4, lvBot, 0.85);
    }

    // 3. Right leg colored-pencil plies
    if (dotRight > 0.18) {
      addSeg("midMain", ruTop + 0.7, rvTop, ruBot + 0.5, rvBot, 0.95);
      addSeg("midLight", ruTop - 0.3, rvTop, ruBot - 0.3, rvBot, 1.0);
      if (dotRight > 0.48 || z > 0.35) {
        addSeg("pastelGlow", ruTop - 0.6, rvTop + 0.4, (ruTop + ruBot) * 0.5 - 0.4, (rvTop + rvBot) * 0.5, 0.85);
      }
    } else {
      addSeg("shadowDeep", ruTop + 0.8, rvTop, ruBot + 0.6, rvBot, 0.9);
      addSeg("midDark", ruTop, rvTop, ruBot, rvBot, 0.95);
      addSeg("midMain", ruTop - 0.6, rvTop, ruBot - 0.4, rvBot, 0.85);
    }

    // 4. North-light pastel highlight on the upper crown of raised cable/rib stitches
    if (dotCrown > 0.25 && z >= -0.05) {
      let crownTier = (dotCrown > 0.52 || z > 0.4) ? "pastelGlow" : "midLight";
      addSeg(crownTier, luTop + 0.4, lvTop - 0.4, ruTop - 0.4, rvTop - 0.4, 0.9);
    }
  }

  // Helper to render a single horizontal purl bump at (uC, vC)
  function emitPurlBump(uC, vC, wBump, hBump, isRaisedMoss = false) {
    let [wx, wy] = toWorld(g, uC, vC);
    if (!pointInGarment(g, wx, wy, 1.0)) return;

    let hw = wBump * 0.42;
    let hh = hBump * 0.36;
    let dotNorth = getNorthLightDot(g, 0, -1.0);
    let flip = dotNorth >= 0 ? 1 : -1;

    // Deep crevice shadow on the south-facing side of the purl bead
    addSeg("shadowDeep", uC - hw, vC + flip * hh, uC + hw, vC + flip * hh * 1.1, 0.95);
    // Core purl belly
    addSeg(isRaisedMoss ? "midMain" : "midDark", uC - hw * 1.05, vC, uC + hw * 1.05, vC, 1.05);
    // North-facing rim highlight
    let hiTier = isRaisedMoss ? ( Math.abs(dotNorth) > 0.4 ? "pastelGlow" : "midLight" ) : "midMain";
    addSeg(hiTier, uC - hw * 0.8, vC - flip * hh * 0.85, uC + hw * 0.8, vC - flip * hh * 0.85, 0.88);
  }

  // Determine active v-range for main knit pattern vs folded ribbed band
  let vMainStart = g.vMin - 12;
  let vMainEnd = g.vMax + 12;
  let vRibStart = null;
  let vRibEnd = null;

  if (g.internalFold) {
    if (g.internalFold.foldSide < 0) {
      vRibStart = g.vMin - 12;
      vRibEnd = g.internalFold.vCut;
      vMainStart = g.internalFold.vCut;
    } else {
      vMainEnd = g.internalFold.vCut;
      vRibStart = g.internalFold.vCut;
      vRibEnd = g.vMax + 12;
    }
  }

  // Render Folded Ribbed Cuff/Waistband Zone if present on this garment
  if (vRibStart !== null && vRibEnd !== null) {
    let u = g.uMin - 8;
    let rIdx = 0;
    while (u < g.uMax + 8) {
      let isKnit = rIdx % 2 === 0;
      let wStrip = isKnit ? 16 : 11;
      let u0 = u;
      let u1 = u + wStrip;

      // Vertical shadow grooves flanking each 2x2 rib
      let groovePtsL = [];
      for (let v = vRibStart; v <= vRibEnd; v += 16) {
        groovePtsL.push([u0, v, 0.9]);
      }
      addSpline("splinesShadow", groovePtsL, 0.3, 0.95);

      if (isKnit) {
        for (let v = vRibStart + 4; v <= vRibEnd - 2; v += 8.8) {
          emitKnitStitch(u0 + wStrip * 0.28, v, wStrip * 0.48, 8.8, 0, 0.25);
          emitKnitStitch(u0 + wStrip * 0.72, v, wStrip * 0.48, 8.8, 0, 0.25);
        }
      } else {
        for (let v = vRibStart + 4; v <= vRibEnd - 2; v += 8.8) {
          emitPurlBump((u0 + u1) * 0.5, v, wStrip * 0.85, 8.2, false);
        }
      }
      u += wStrip;
      rIdx++;
    }
  }

  // Render Main Knit Strips across [vMainStart, vMainEnd]
  const hCourse = 9.2;

  for (let s of g.strips) {
    let u0 = s.u0;
    let u1 = s.u1;
    let wStrip = u1 - u0;
    let uMid = (u0 + u1) * 0.5;

    // 1. PURL TRENCH
    if (s.type === "purl") {
      let nCols = Math.max(1, Math.round(wStrip / 11));
      let colW = wStrip / nCols;
      for (let c = 0; c < nCols; c++) {
        let uCol = u0 + (c + 0.5) * colW;
        for (let v = vMainStart + 4; v <= vMainEnd; v += hCourse) {
          emitPurlBump(uCol, v + (c % 2) * 4.2, colW * 0.9, hCourse * 0.9, false);
        }
      }
    }

    // 2. SINGLE TWISTED RIB DIVIDER
    else if (s.type === "rib1") {
      let ptsL = [], ptsR = [], ptsHi = [];
      for (let v = vMainStart; v <= vMainEnd; v += 15) {
        ptsL.push([u0 + 0.8, v, 0.95]);
        ptsR.push([u1 - 0.8, v, 0.95]);
        ptsHi.push([uMid - 1.2, v, 0.85]);
      }
      addSpline("splinesShadow", ptsL, 0.3, 1.0);
      addSpline("splinesShadow", ptsR, 0.3, 1.0);
      addSpline("splinesLight", ptsHi, 0.3, 0.85);

      for (let v = vMainStart + 4; v <= vMainEnd; v += hCourse) {
        emitKnitStitch(uMid, v, wStrip * 0.85, hCourse, 0.08, 0.35);
      }
    }

    // 3. 2-WALE OR 3-WALE FISHERMAN'S RIB
    else if (s.type === "rib2" || s.type === "rib3") {
      let nW = s.type === "rib3" ? 3 : 2;
      let wWale = wStrip / nW;
      for (let k = 0; k <= nW; k++) {
        let groovePts = [];
        for (let v = vMainStart; v <= vMainEnd; v += 16) {
          groovePts.push([u0 + k * wWale, v, 0.9]);
        }
        addSpline("splinesShadow", groovePts, 0.3, k === 0 || k === nW ? 1.05 : 0.8);
      }
      for (let k = 0; k < nW; k++) {
        let uW = u0 + (k + 0.5) * wWale;
        for (let v = vMainStart + 4; v <= vMainEnd; v += hCourse) {
          emitKnitStitch(uW, v, wWale * 0.92, hCourse, 0, 0.3);
        }
      }
    }

    // 4. MOSS / SEED STITCH PANEL
    else if (s.type === "moss") {
      let nCols = 3;
      let colW = wStrip / nCols;
      for (let v = vMainStart + 4, row = 0; v <= vMainEnd; v += hCourse * 0.92, row++) {
        for (let c = 0; c < nCols; c++) {
          let uCol = u0 + (c + 0.5) * colW;
          if ((row + c) % 2 === 0) {
            emitPurlBump(uCol, v, colW * 0.92, hCourse * 0.88, true);
          } else {
            emitKnitStitch(uCol, v, colW * 0.88, hCourse * 0.88, 0, 0.12);
          }
        }
      }
    }

    // 5. HEAVY 2-STRAND ARAN ROPE CABLE (with true over/under crossing & undercut bridge shadow)
    else if (s.type === "rope") {
      let P = s.period;
      let dir = s.dir;
      let strandW = wStrip * 0.47;
      let offset = wStrip * 0.245;

      // Outer trench shadow boundaries of the cable
      let edgeL = [], edgeR = [];
      for (let v = vMainStart; v <= vMainEnd; v += 16) {
        let cyc = (((v + s.phase) % P) + P) % P / P;
        let pinch = cyc > 0.45 ? Math.sin(((cyc - 0.45) / 0.55) * Math.PI) * 2.4 : 0;
        edgeL.push([u0 + pinch, v, 1.0]);
        edgeR.push([u1 - pinch, v, 1.0]);
      }
      addSpline("splinesShadow", edgeL, 0.5, 1.15);
      addSpline("splinesShadow", edgeR, 0.5, 1.15);

      // Step through each cable repeat cycle
      let firstCycle = Math.floor((vMainStart - s.phase) / P) * P + s.phase;
      for (let vBase = firstCycle; vBase <= vMainEnd + P; vBase += P) {
        let overSplineL = [], overSplineM = [], overSplineR = [], overBridgeShadow = [];

        let nSteps = 8;
        let dv = P / nSteps;
        for (let i = 0; i <= nSteps; i++) {
          let t = i / nSteps;
          let v = vBase + t * P;
          if (v < vMainStart - hCourse || v > vMainEnd + hCourse) continue;

          // Smooth crossing progression s in [0, 1] during second half of repeat
          let sCross = t < 0.38 ? 0 : (t - 0.38) / 0.62;
          let cosS = Math.cos(sCross * Math.PI);
          let sinS = Math.sin(sCross * Math.PI);

          // Over-strand moves from -dir*offset to +dir*offset
          let uOver = uMid - dir * offset * cosS;
          let slopeOver = (t < 0.38) ? 0 : (dir * offset * Math.PI * sinS) / (0.62 * P);
          let zOver = (t < 0.38) ? 0.25 : 0.25 + 0.75 * sinS;

          // Under-strand moves from +dir*offset to -dir*offset
          let uUnder = uMid + dir * offset * cosS;
          let slopeUnder = -slopeOver;
          let zUnder = (t < 0.38) ? 0.2 : 0.2 - 0.85 * sinS;

          // A. Render Under-Strand stitches when not occluded by the Over-Strand bridge
          if (i < nSteps && (sCross < 0.27 || sCross > 0.73)) {
            let wSub = strandW * 0.48;
            emitKnitStitch(uUnder - wSub * 0.5, v + dv * 0.4, wSub, dv * 0.95, slopeUnder, zUnder);
            emitKnitStitch(uUnder + wSub * 0.5, v + dv * 0.4, wSub, dv * 0.95, slopeUnder, zUnder);

            // Deep tuck shadow where under-strand dives beneath the over-strand
            if (sCross >= 0.16 && sCross <= 0.84) {
              addSeg("shadowDeep", uUnder - strandW * 0.45, v, uUnder + strandW * 0.45, v + dv * 0.35, 1.15);
            }
          }

          // B. Collect continuous ply splines & bridge shadow for the Over-Strand
          overSplineL.push([uOver - strandW * 0.46, v, 0.95]);
          overSplineM.push([uOver, v, 0.9]);
          overSplineR.push([uOver + strandW * 0.46, v, 0.95]);
          if (sCross > 0.08 && sCross < 0.92) {
            overBridgeShadow.push([uOver + dir * strandW * 0.52, v + 2.2, 1.1]);
          }

          // C. Render Over-Strand 2-wale stitches on top
          if (i < nSteps) {
            let wSub = strandW * 0.48;
            emitKnitStitch(uOver - wSub * 0.5, v + dv * 0.4, wSub, dv * 0.96, slopeOver, zOver);
            emitKnitStitch(uOver + wSub * 0.5, v + dv * 0.4, wSub, dv * 0.96, slopeOver, zOver);
          }
        }

        // Emit continuous sculpting splines for the crossing rope
        addSpline("splinesShadow", overBridgeShadow, 0.5, 1.25);
        addSpline("splinesShadow", overSplineL, 0.5, 0.95);
        addSpline("splinesShadow", overSplineR, 0.5, 0.95);
        let dotArch = getNorthLightDot(g, dir * 0.5, -0.85);
        addSpline(dotArch > 0.15 ? "splinesPastel" : "splinesLight", overSplineM, 0.5, 0.95);
      }
    }

    // 6. 3-STRAND BRAIDED PLAIT CABLE
    else if (s.type === "braid") {
      let P = s.period;
      let amp = wStrip * 0.29;
      let strandW = wStrip * 0.34;
      let dv = 8.8;

      for (let v = vMainStart; v <= vMainEnd; v += dv) {
        let phaseBase = ((v + s.phase) / P) * Math.PI * 2;
        // Compute the 3 braiding strands and sort by z height (cos of phase)
        let strands = [];
        for (let b = 0; b < 3; b++) {
          let ang = phaseBase + (b * Math.PI * 2) / 3;
          let uPos = uMid + amp * Math.sin(ang);
          let zHeight = Math.cos(ang);
          let slope = (amp * (Math.PI * 2 / P)) * Math.cos(ang);
          strands.push({ uPos, zHeight, slope });
        }
        strands.sort((a, b) => a.zHeight - b.zHeight);

        // Render from lowest (tucked) strand to highest (over-arching) strand
        for (let st of strands) {
          if (st.zHeight < -0.25) {
            // Partially occluded under-strand
            addSeg("shadowDeep", st.uPos - strandW * 0.4, v, st.uPos + strandW * 0.4, v + dv * 0.4, 1.05);
          } else {
            if (st.zHeight > 0.2) {
              // Cast shadow underneath the crossing over-strand
              addSeg("shadowDeep", st.uPos - strandW * 0.52, v + 2.0, st.uPos + strandW * 0.52, v + dv * 0.6, 1.1);
            }
            emitKnitStitch(st.uPos - strandW * 0.24, v, strandW * 0.48, dv, st.slope, st.zHeight * 0.65);
            emitKnitStitch(st.uPos + strandW * 0.24, v, strandW * 0.48, dv, st.slope, st.zHeight * 0.65);
          }
        }
      }
    }

    // 7. ARAN HONEYCOMB / DIAMOND TRELLIS WITH MOSS-STITCH CORE
    else if (s.type === "honeycomb") {
      let P = s.period;
      let amp = wStrip * 0.41;
      let ribW = 14.5;
      let dv = 8.8;

      let rib1Pts = [], rib2Pts = [];

      for (let v = vMainStart; v <= vMainEnd; v += dv) {
        let ang = ((v + s.phase) / P) * Math.PI * 2;
        let cosA = Math.cos(ang);
        let sinA = Math.sin(ang);

        let uR1 = uMid - amp * cosA;
        let uR2 = uMid + amp * cosA;
        let slope1 = (amp * (Math.PI * 2 / P)) * sinA;
        let slope2 = -slope1;

        rib1Pts.push([uR1, v, 0.95]);
        rib2Pts.push([uR2, v, 0.95]);

        let uLeftRib = Math.min(uR1, uR2);
        let uRightRib = Math.max(uR1, uR2);

        // Fill interior of diamond with raised Moss/Seed stitch and exterior with recessed purl
        let nCells = 6;
        let cellW = wStrip / nCells;
        let rowIdx = Math.round(v / dv);
        for (let c = 0; c < nCells; c++) {
          let uCell = u0 + (c + 0.5) * cellW;
          if (uCell > uLeftRib + ribW * 0.55 && uCell < uRightRib - ribW * 0.55) {
            // Inside the diamond medallion: tactile moss stitch
            if ((rowIdx + c) % 2 === 0) {
              emitPurlBump(uCell, v, cellW * 0.88, dv * 0.85, true);
            } else {
              emitKnitStitch(uCell, v, cellW * 0.85, dv * 0.85, 0, 0.15);
            }
          } else if (uCell < uLeftRib - ribW * 0.55 || uCell > uRightRib + ribW * 0.55) {
            // Outside the diamond: dark recessed purl trench
            emitPurlBump(uCell, v, cellW * 0.85, dv * 0.85, false);
          }
        }

        // Draw the two travelling ribs (alternating which rib crosses on top at the apexes)
        let r1OnTop = sinA >= 0;
        let firstU = r1OnTop ? uR2 : uR1;
        let firstSlope = r1OnTop ? slope2 : slope1;
        let secondU = r1OnTop ? uR1 : uR2;
        let secondSlope = r1OnTop ? slope1 : slope2;

        // Under-rib at crossing
        if (Math.abs(uR1 - uR2) > ribW * 0.65) {
          emitKnitStitch(firstU - 3.2, v, ribW * 0.48, dv, firstSlope, 0.25);
          emitKnitStitch(firstU + 3.2, v, ribW * 0.48, dv, firstSlope, 0.25);
        } else {
          addSeg("shadowDeep", firstU - ribW * 0.5, v, firstU + ribW * 0.5, v + dv * 0.4, 1.15);
        }

        // Over-rib with crevice shadow
        addSeg("shadowDeep", secondU - ribW * 0.55, v + 1.8, secondU + ribW * 0.55, v + 1.8, 1.1);
        emitKnitStitch(secondU - 3.2, v, ribW * 0.48, dv, secondSlope, 0.6);
        emitKnitStitch(secondU + 3.2, v, ribW * 0.48, dv, secondSlope, 0.6);
      }

      addSpline("splinesShadow", rib1Pts, 0.5, 1.0);
      addSpline("splinesShadow", rib2Pts, 0.5, 1.0);
    }
  }

  // ==========================================================================
  // FLUSH BUCKETED STROKES IN PAINTER'S ORDER (DARK CREVICES -> PASTEL BLOOM)
  // ==========================================================================

  // 1. Deepest structural shadow splines & stitch root crevices
  brush.set("2B", g.pal.shadowDeep, 1.0);
  for (let sp of buckets.splinesShadow) {
    brush.strokeWeight(sp[2]);
    brush.spline(sp[0], sp[1]);
  }
  brush.set("cpencil", g.pal.shadowDeep, 0.95);
  for (let seg of buckets.shadowDeep) {
    brush.strokeWeight(seg[4]);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // 2. Shaded yarn plies & purl undersides
  brush.set("wool_pencil", g.pal.midDark, 0.95);
  for (let seg of buckets.midDark) {
    brush.strokeWeight(seg[4]);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // 3. Core colored-pencil wool body strokes
  brush.set("wool_pencil", g.pal.midMain, 1.0);
  for (let sp of buckets.splinesMain) {
    brush.strokeWeight(sp[2]);
    brush.spline(sp[0], sp[1]);
  }
  for (let seg of buckets.midMain) {
    brush.strokeWeight(seg[4]);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // 4. Illuminated upper yarn plies & north-facing cable slopes
  brush.set("wool_pencil", g.pal.midLight, 0.95);
  for (let sp of buckets.splinesLight) {
    brush.strokeWeight(sp[2]);
    brush.spline(sp[0], sp[1]);
  }
  for (let seg of buckets.midLight) {
    brush.strokeWeight(seg[4]);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }

  // 5. Soft-pastel north-light colored-pencil bloom on cable crowns & stitch ridges
  brush.set("pastel_pencil", g.pal.pastelGlow, 0.9);
  for (let sp of buckets.splinesPastel) {
    brush.strokeWeight(sp[2]);
    brush.spline(sp[0], sp[1]);
  }
  for (let seg of buckets.pastelGlow) {
    brush.strokeWeight(seg[4]);
    brush.line(seg[0], seg[1], seg[2], seg[3]);
  }
}

// ============================================================================
// LAYER 4: INTERNAL GARMENT FOLDS & CRISP EDGE-TO-EDGE QUILT SEAMS
// ============================================================================

function renderInternalFoldCrease(g) {
  let vFold = g.internalFold.vCut;
  let side = g.internalFold.foldSide; // -1 or +1
  let [x1, y1] = toWorld(g, g.uMin - 10, vFold);
  let [x2, y2] = toWorld(g, g.uMax + 10, vFold);
  let seg = clipSegmentToGarment(g, x1, y1, x2, y2, 2.5);
  if (!seg) return;

  let len = Math.hypot(seg[2] - seg[0], seg[3] - seg[1]);
  let tx = (seg[2] - seg[0]) / len;
  let ty = (seg[3] - seg[1]) / len;
  // Normal pointing into the overlapping ribbed cuff lip
  let nx = -ty * side;
  let ny = tx * side;
  let northDot = LIGHT_X * (-nx) + LIGHT_Y * (-ny);

  // Soft alcohol-marker crease shadow along the internal tuck
  brush.set("alcohol_detail", g.pal.markerDark, 0.85);
  brush.line(seg[0] - nx * 2.5, seg[1] - ny * 2.5, seg[2] - nx * 2.5, seg[3] - ny * 2.5);

  // Short wrapped colored-pencil strokes rolling over the folded ribbed hem
  let nTicks = Math.floor(len / 5.5);
  brush.set("wool_pencil", northDot > 0 ? g.pal.pastelGlow : g.pal.midLight, 0.85);
  for (let i = 1; i < nTicks; i++) {
    let s = i / nTicks;
    let px = seg[0] + s * (seg[2] - seg[0]);
    let py = seg[1] + s * (seg[3] - seg[1]);
    brush.line(px + nx * 1.2, py + ny * 1.2, px + nx * 7.5, py + ny * 7.5);
  }

  // Crisp colored-pencil tuck crevice
  brush.set("2B", g.pal.shadowDeep, 1.1);
  let pts = [];
  for (let i = 0; i <= 16; i++) {
    let s = i / 16;
    let w = (noise(s * 6, g.cx * 0.01) - 0.5) * 2.2 * Math.sin(s * Math.PI);
    pts.push([
      seg[0] + s * (seg[2] - seg[0]) + nx * w,
      seg[1] + s * (seg[3] - seg[1]) + ny * w,
      1.0
    ]);
  }
  brush.spline(pts, 0.4);
}

function renderGarmentSeam(seam) {
  let x1 = seam.a[0], y1 = seam.a[1];
  let x2 = seam.b[0], y2 = seam.b[1];
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = Math.hypot(dx, dy);
  let tx = dx / len;
  let ty = dy / len;
  // Normal N pointing from Side 1 into Side 2
  let nx = -ty;
  let ny = tx;

  // Coherent cloth wave along the seam (pinned to 0 at corners for severe quilt geometry)
  function seamWave(s) {
    let env = Math.sin(s * Math.PI);
    return (noise(s * 7.5, seam.id * 13.7) - 0.5) * 3.2 * env;
  }

  // 1. Deep alcohol-marker trough shading on both sides of the seam
  brush.set("alcohol_detail", seam.pal1.markerDark, 0.8);
  brush.line(x1 - nx * 3.5, y1 - ny * 3.5, x2 - nx * 3.5, y2 - ny * 3.5);
  brush.set("alcohol_detail", seam.pal2.markerDark, 0.8);
  brush.line(x1 + nx * 3.5, y1 + ny * 3.5, x2 + nx * 3.5, y2 + ny * 3.5);

  // 2. Plump rolled cloth edges on Side 1 (-N) and Side 2 (+N)
  // Side 1 rolls toward +N as it tucks into the seam; Side 2 rolls toward -N
  let dotSide1 = LIGHT_X * nx + LIGHT_Y * ny;
  let dotSide2 = LIGHT_X * (-nx) + LIGHT_Y * (-ny);

  let step = 4.2;
  let nSteps = Math.floor(len / step);

  // Side 1 rolled edge strokes
  brush.set("wool_pencil", seam.pal1.midDark, 0.9);
  for (let i = 1; i < nSteps; i++) {
    let s = i / nSteps;
    let w = seamWave(s);
    let bx = x1 + s * dx + nx * w;
    let by = y1 + s * dy + ny * w;
    brush.line(bx - nx * 0.8, by - ny * 0.8, bx - nx * 5.2, by - ny * 5.2);
  }
  if (dotSide1 > -0.15) {
    let col1 = dotSide1 > 0.25 ? seam.pal1.pastelGlow : seam.pal1.midLight;
    brush.set("pastel_pencil", col1, 0.82);
    for (let i = 1; i < nSteps; i += 2) {
      let s = i / nSteps;
      let w = seamWave(s);
      let bx = x1 + s * dx + nx * w;
      let by = y1 + s * dy + ny * w;
      brush.line(bx - nx * 3.2, by - ny * 3.2, bx - nx * 8.5, by - ny * 8.5);
    }
  }

  // Side 2 rolled edge strokes
  brush.set("wool_pencil", seam.pal2.midDark, 0.9);
  for (let i = 1; i < nSteps; i++) {
    let s = i / nSteps;
    let w = seamWave(s);
    let bx = x1 + s * dx + nx * w;
    let by = y1 + s * dy + ny * w;
    brush.line(bx + nx * 0.8, by + ny * 0.8, bx + nx * 5.2, by + ny * 5.2);
  }
  if (dotSide2 > -0.15) {
    let col2 = dotSide2 > 0.25 ? seam.pal2.pastelGlow : seam.pal2.midLight;
    brush.set("pastel_pencil", col2, 0.82);
    for (let i = 1; i < nSteps; i += 2) {
      let s = i / nSteps;
      let w = seamWave(s);
      let bx = x1 + s * dx + nx * w;
      let by = y1 + s * dy + ny * w;
      brush.line(bx + nx * 3.2, by + ny * 3.2, bx + nx * 8.5, by + ny * 8.5);
    }
  }

  // 3. Crisp, dark recessed meeting crevice where the two folded garments press together
  let seamPts1 = [];
  let seamPts2 = [];
  let nSpline = Math.max(10, Math.floor(len / 24));
  for (let i = 0; i <= nSpline; i++) {
    let s = i / nSpline;
    let w = seamWave(s);
    let px = x1 + s * dx + nx * w;
    let py = y1 + s * dy + ny * w;
    seamPts1.push([px - nx * 0.7, py - ny * 0.7, 1.05]);
    seamPts2.push([px + nx * 0.7, py + ny * 0.7, 1.05]);
  }

  brush.set("2B", seam.pal1.shadowDeep, 1.25);
  brush.spline(seamPts1, 0.45);
  brush.set("2B", seam.pal2.shadowDeep, 1.25);
  brush.spline(seamPts2, 0.45);

  // Fine dark core crevice line
  brush.set("cpencil", "#050507", 1.15);
  brush.spline(seamPts1, 0.45);
}

// ============================================================================
// LAYER 5: PILLED WOOL FIBRES (NEPS) & WISPY STRAY THREADS
// ============================================================================

function renderPillsAndStrayThreads(g) {
  // Estimate garment area to scale pill & stray fiber count proportionally
  let area = (g.uMax - g.uMin) * (g.vMax - g.vMin);
  let nPills = Math.floor(constrain(area / 1150, 18, 220));
  let nThreads = Math.floor(constrain(area / 850, 24, 290));

  let pillShadows = [];
  let pillBodies = [];
  let pillPastels = [];
  let strayMid = [];
  let strayPastel = [];
  let strayFleck = [];

  // 1. Generate 3D wool pills (matted fiber bobbles with south shadow + north pastel crown)
  let attempts = 0;
  let count = 0;
  while (count < nPills && attempts < nPills * 4) {
    attempts++;
    let u = random(g.uMin + 4, g.uMax - 4);
    let v = random(g.vMin + 4, g.vMax - 4);
    let [wx, wy] = toWorld(g, u, v);
    if (!pointInGarment(g, wx, wy, 3.0)) continue;

    let r = random(1.2, 2.8);
    // Pill underside shadow (south side, away from north light)
    pillShadows.push([
      wx - r * 0.7 - LIGHT_X * 1.4,
      wy + 0.5 - LIGHT_Y * 1.3,
      wx + r * 0.7 - LIGHT_X * 1.4,
      wy + 0.7 - LIGHT_Y * 1.3,
      random(0.85, 1.15)
    ]);

    // Tangled pill core (2 tight criss-cross colored-pencil micro-strokes)
    let ang = random(Math.PI);
    let dx = Math.cos(ang) * r;
    let dy = Math.sin(ang) * r;
    pillBodies.push([wx - dx, wy - dy, wx + dx, wy + dy, random(0.9, 1.2)]);
    pillBodies.push([wx - dy * 0.8, wy + dx * 0.8, wx + dy * 0.8, wy - dx * 0.8, random(0.85, 1.1)]);

    // Chalky pastel north-light crown on top of the wool pill
    pillPastels.push([
      wx - r * 0.55 + LIGHT_X * 0.8,
      wy + LIGHT_Y * 0.8,
      wx + r * 0.55 + LIGHT_X * 0.8,
      wy + LIGHT_Y * 0.8 - 0.3,
      random(0.85, 1.15)
    ]);
    count++;
  }

  // 2. Generate wispy, curled stray wool threads & fuzzy halo fibres
  attempts = 0;
  count = 0;
  while (count < nThreads && attempts < nThreads * 4) {
    attempts++;
    // Bias some stray hairs toward the folded seams for hyperrealist edge softness
    let nearSeam = random() < 0.32;
    let u = random(g.uMin + 2, g.uMax - 2);
    let v = random(g.vMin + 2, g.vMax - 2);
    let [wx, wy] = toWorld(g, u, v);
    if (!pointInGarment(g, wx, wy, nearSeam ? 0.5 : 3.5)) continue;

    let len = random(6, 20);
    let baseAng = g.theta + random(-1.2, 1.2);
    let curl = random(-0.9, 0.9);

    let pts = [];
    let cx = wx;
    let cy = wy;
    let nSegs = 3;
    for (let k = 0; k <= nSegs; k++) {
      pts.push([cx, cy, k === 1 ? 1.0 : 0.45]);
      let a = baseAng + k * curl * 0.55;
      cx += Math.cos(a) * (len / nSegs);
      cy += Math.sin(a) * (len / nSegs);
    }

    let roll = random();
    if (roll < 0.38) {
      strayPastel.push(pts);
    } else if (roll < 0.72) {
      strayFleck.push(pts);
    } else {
      strayMid.push(pts);
    }
    count++;
  }

  // Flush pill shadows
  brush.set("cpencil", g.pal.shadowDeep, 0.9);
  for (let s of pillShadows) {
    brush.strokeWeight(s[4]);
    brush.line(s[0], s[1], s[2], s[3]);
  }

  // Flush pill bodies
  brush.set("wool_pencil", g.pal.midLight, 0.95);
  for (let s of pillBodies) {
    brush.strokeWeight(s[4]);
    brush.line(s[0], s[1], s[2], s[3]);
  }

  // Flush pill pastel crowns
  brush.set("pastel_pencil", g.pal.pastelFleck, 0.95);
  for (let s of pillPastels) {
    brush.strokeWeight(s[4]);
    brush.line(s[0], s[1], s[2], s[3]);
  }

  // Flush delicate stray wool threads
  brush.set("cpencil", g.pal.midLight, 0.32);
  for (let pts of strayMid) {
    brush.spline(pts, 0.65);
  }

  brush.set("cpencil", g.pal.pastelGlow, 0.28);
  for (let pts of strayPastel) {
    brush.spline(pts, 0.65);
  }

  brush.set("cpencil", g.pal.pastelFleck, 0.24);
  for (let pts of strayFleck) {
    brush.spline(pts, 0.7);
  }
}

