// =============================================================================
// 3D-TO-FISHEYE CONVEX MIRROR PROJECTION ENGINE
// =============================================================================
// Maps a 3D world point (X, Y, Z) to 2D canvas coordinates on the convex dome.
// X: horizontal (-left, +right)
// Y: vertical (-up/sky, +down/street, 0 = horizon)
// Z: depth in front of hubcap (>0 in front, <0 peripheral wrap-around)
function worldToDome(X, Y, Z, rad = R_DOME) {
  // Slight upward normal tilt of hubcap (~6.5 deg) so horizon arcs gracefully below center
  const tilt = 0.115;
  const cosA = Math.cos(tilt);
  const sinA = Math.sin(tilt);
  const yr = Y * cosA + Z * sinA;
  const zr = -Y * sinA + Z * cosA;

  const len = Math.sqrt(X * X + yr * yr + zr * zr) || 1e-6;
  const dx = X / len;
  const dy = yr / len;
  const dz = zr / len;

  // Reflection half-vector N = normalize(D + V_cam), V_cam = (0, 0, 1)
  const k = Math.sqrt(2 * Math.max(0.06, 1 + dz));
  const nx = dx / k;
  const ny = dy / k;

  // Equisolid/stereographic radial curve across the high-crown dome
  const rNorm = Math.sqrt(nx * nx + ny * ny);
  const rMapped = Math.min(0.998, Math.pow(rNorm * 1.27, 0.94));
  const scale = rNorm > 1e-6 ? (rMapped / rNorm) : 0;

  return [CX + nx * scale * rad, CY + ny * scale * rad];
}

// Subdivide a 3D line segment and project onto dome
function projectSegment3D(p1, p2, steps = 16, rad = R_DOME) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = p1[0] + (p2[0] - p1[0]) * t;
    const y = p1[1] + (p2[1] - p1[1]) * t;
    const z = p1[2] + (p2[2] - p1[2]) * t;
    pts.push(worldToDome(x, y, z, rad));
  }
  return pts;
}

// Convert a 3D polygon [(x,y,z), ...] into a fisheye-warped 2D vertex array
function projectPoly3D(verts3D, stepsPerEdge = 10, rad = R_DOME) {
  const pts = [];
  const n = verts3D.length;
  for (let i = 0; i < n; i++) {
    const p1 = verts3D[i];
    const p2 = verts3D[(i + 1) % n];
    for (let s = 0; s < stepsPerEdge; s++) {
      const t = s / stepsPerEdge;
      pts.push(worldToDome(
        p1[0] + (p2[0] - p1[0]) * t,
        p1[1] + (p2[1] - p1[1]) * t,
        p1[2] + (p2[2] - p1[2]) * t,
        rad
      ));
    }
  }
  return pts;
}

// Helper to create an annular sector polygon in polar coordinates (degrees)
function annularSectorPts(rIn, rOut, aStart, aEnd, steps = 24, radialWave = 0, waveFreq = 0) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = aStart + (aEnd - aStart) * (i / steps);
    const rad = a * Math.PI / 180;
    const dr = radialWave ? Math.sin(rad * waveFreq) * radialWave : 0;
    pts.push([CX + (rOut + dr) * Math.cos(rad), CY + (rOut + dr) * Math.sin(rad)]);
  }
  for (let i = steps; i >= 0; i--) {
    const a = aStart + (aEnd - aStart) * (i / steps);
    const rad = a * Math.PI / 180;
    const dr = radialWave ? Math.sin(rad * waveFreq) * radialWave : 0;
    pts.push([CX + (rIn + dr) * Math.cos(rad), CY + (rIn + dr) * Math.sin(rad)]);
  }
  return pts;
}

// Helper for circular arc point list (degrees)
function arcPts(r, aStart, aEnd, steps = 32, rJitter = 0) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = aStart + (aEnd - aStart) * (i / steps);
    const rad = a * Math.PI / 180;
    const rr = r + (rJitter ? Math.sin(i * 1.7) * rJitter : 0);
    pts.push([CX + rr * Math.cos(rad), CY + rr * Math.sin(rad)]);
  }
  return pts;
}

// Draw a solid wash polygon quickly
function washPoly(pts, col, opacity = 255) {
  if (pts.length < 3) return;
  const p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

// Draw a hatched & washed polygon
function washAndHatchPoly(pts, washCol, washOp, hatchBrush, hatchCol, hatchW, dist, ang, opts = { rand: 0.04 }) {
  if (pts.length < 3) return;
  const p = new brush.Polygon(pts);
  if (washCol && washOp > 0) p.wash(washCol, washOp);
  brush.hatchStyle(hatchBrush, hatchCol, hatchW);
  p.hatch(dist, ang, opts);
  brush.noHatch();
}

// Stroke a polyline with brush.spline or brush.line
function strokeCurve(pts, brushName, col, weight = 1, curvature = 0.45) {
  if (!pts || pts.length < 2) return;
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curvature);
  }
}

