// =============================================================================
// MAIN RENDER PIPELINE
// =============================================================================
function draw() {
  translate(-width / 2, -height / 2);
  background("#eef2f6");

  // Ensure a brush is always active
  brush.set("micro_ink", PAL.inkBlack, 1);

  // 1. TIRE SIDEWALL & PAINTED STEEL WHEEL RECESS (R = 544 to 860)
  drawTireAndWheelWell();

  // 2. OUTER HUBCAP RINGS: ROLLED LIP, 36 STAMPED FLUTES & TOROIDAL STEP (R = 372 to 544)
  drawOuterHubcapRings();

  // 3. MAIN CONVEX DOME: SKY-TO-ASPHALT BASE & SOFT SPRAY GRADIENTS (R = 0 to 372)
  drawDomeBaseAndSprayGradients();

  // 4. PERIPHERAL CAR FENDER REFLECTIONS: CURVING TURQUOISE & CADMIUM BANDS
  drawPeripheralFenderBands();

  // 5. SUBURBAN STREET PANORAMA IN FISHEYE REFLECTION
  drawDistantTreesAndHorizon();
  drawLeftColonialHouse();
  drawRightSuburbanHouse();
  drawParkedVintageCarAndDetails();
  drawLawnsSidewalkAndCurb();
  drawAsphaltStreetAndBands();
  drawUtilityPolesAndWires();

  // 6. TINY DISTORTED FIGURE OF THE VIEWER (CENTER / LOWER-CENTER)
  drawDistortedViewerFigure();

  // 7. SOLAR SPECULAR STARBURST, DOME GLAZES & CRISP INK SPECULAR BREAKS
  drawDomeSpecularsAndBreaks();

  // 8. ROAD GRIME, BRAKE DUST & MICRO-PITTING ON THE RIM
  drawRimGrimeAndPits();

  noLoop();
}

// =============================================================================
// 1. TIRE SIDEWALL & PAINTED STEEL WHEEL RECESS
// =============================================================================
function drawTireAndWheelWell() {
  // Deep rubber tire base filling canvas corners outside R = 578
  washPoly(annularSectorPts(575, 880, 0, 360, 72), "#14181f", 255);

  // Subtle curved tire sidewall molding rings and warm road-dust sheen
  washPoly(annularSectorPts(595, 650, 195, 345, 48), "#222934", 190);
  washPoly(annularSectorPts(595, 665, 20, 160, 48), "#25211e", 180);

  // Spray grain across the rubber tire
  for (let r = 600; r <= 830; r += 26) {
    strokeCurve(arcPts(r, 0, 360, 40), "airbrush_wide", r < 680 ? "#2a323d" : "#101318", 1.1, 0.5);
  }

  // Molded radial sidewall ribs on tire
  for (let a = 0; a < 360; a += 5) {
    const rad = a * Math.PI / 180;
    const r1 = 588, r2 = 642;
    const col = (a > 200 && a < 340) ? "#36414f" : "#0c0e12";
    brush.set("micro_ink", col, 0.85);
    brush.line(
      CX + r1 * Math.cos(rad), CY + r1 * Math.sin(rad),
      CX + r2 * Math.cos(rad), CY + r2 * Math.sin(rad)
    );
  }

  // Vintage Turquoise-painted steel wheel rim peeking between tire and hubcap (R = 544 to 582)
  washPoly(annularSectorPts(R_RIM_OUT - 2, R_WHEEL_OUT, 0, 360, 72), "#08131a", 255);
  washPoly(annularSectorPts(558, 578, 195, 340, 48), PAL.turqDeep, 210);
  washPoly(annularSectorPts(563, 574, 215, 315, 36), PAL.turqBright, 175);
  washPoly(annularSectorPts(556, 576, 25, 155, 48), "#2c2520", 210);

  // Deep cast shadow directly under the hubcap lip
  washPoly(annularSectorPts(R_RIM_OUT - 1, R_RIM_OUT + 15, 0, 360, 72), PAL.inkBlack, 250);
  strokeCurve(arcPts(R_WHEEL_OUT, 0, 360, 64), "crisp_ink", PAL.inkBlack, 1.4, 0.5);
}

// =============================================================================
// 2. OUTER HUBCAP RINGS: ROLLED LIP, 36 STAMPED FLUTES & TOROIDAL STEP
// =============================================================================
function drawOuterHubcapRings() {
  // --- ZONE A: OUTER ROLLED CHROME LIP (R = 496 to 544) ---
  washPoly(annularSectorPts(R_FLUTE_OUT, R_RIM_OUT, 0, 360, 72), "#d8e3ec", 255);

  // Upper sky reflection on rolled lip
  washPoly(annularSectorPts(500, 536, 190, 350, 56), PAL.skyMid, 210);
  washPoly(annularSectorPts(506, 526, 205, 335, 48), PAL.skyDeep, 220);
  washPoly(annularSectorPts(497, 509, 200, 340, 48), PAL.pureWhite, 245);

  // Curving Turquoise & Cadmium bands bent around the rolled lip flanks
  washPoly(annularSectorPts(502, 534, 150, 210, 32), PAL.turqBright, 225);
  washPoly(annularSectorPts(512, 538, 135, 185, 28), PAL.cadBright, 220);
  washPoly(annularSectorPts(502, 534, 330, 390, 32), PAL.turqBright, 225);
  washPoly(annularSectorPts(512, 538, 350, 408, 28), PAL.cadOrange, 220);

  // Lower asphalt & grime reflection on rolled lip
  washPoly(annularSectorPts(500, 540, 18, 162, 48), PAL.asphaltMid, 230);
  washPoly(annularSectorPts(514, 538, 30, 150, 44), PAL.asphaltDark, 235);
  washPoly(annularSectorPts(498, 512, 35, 145, 40), "#b8c2cc", 210);

  // Crisp black ink specular break core running around the rolled lip
  washPoly(annularSectorPts(522, 535, 182, 358, 56), PAL.inkBlack, 250);
  washPoly(annularSectorPts(506, 517, 10, 170, 56), PAL.inkBlack, 245);

  // Soft spray transitions on the outer lip
  strokeCurve(arcPts(516, 195, 345, 36), "fine_spray", PAL.skyPale, 1.0, 0.5);
  strokeCurve(arcPts(526, 25, 155, 36), "fine_spray", PAL.asphaltLite, 1.0, 0.5);

  // --- ZONE B: RECESSED STAMPED FLUTED CHANNEL (R = 414 to 496) ---
  // Base metallic ring
  washPoly(annularSectorPts(R_FLUTE_IN, R_FLUTE_OUT, 0, 360, 72), "#9eb0c0", 255);

  // Continuous background reflections before stamping flutes
  washPoly(annularSectorPts(418, 492, 192, 348, 56), PAL.skyMid, 195);
  washPoly(annularSectorPts(442, 486, 205, 335, 48), PAL.skyZenith, 210);
  washPoly(annularSectorPts(418, 492, 18, 162, 56), PAL.asphaltDark, 220);
  washPoly(annularSectorPts(435, 478, 30, 150, 48), PAL.asphaltLite, 195);

  // Bent Turquoise & Cadmium ribbons sweeping through the fluted channel
  washPoly(annularSectorPts(424, 468, 145, 205, 30), PAL.turqElectric, 220);
  washPoly(annularSectorPts(452, 488, 130, 190, 30), PAL.cadYellow, 225);
  washPoly(annularSectorPts(424, 468, 335, 395, 30), PAL.turqBright, 220);
  washPoly(annularSectorPts(452, 488, 348, 412, 30), PAL.cadBright, 225);

  // 36 Stamped Radial Chrome Flutes (every 10 degrees)
  const numFlutes = 36;
  const stepAng = 360 / numFlutes;
  for (let i = 0; i < numFlutes; i++) {
    const a0 = i * stepAng + 1.1;
    const a1 = (i + 1) * stepAng - 1.1;
    const aMid = (a0 + a1) * 0.5;
    const normA = ((aMid % 360) + 360) % 360;

    const rFIn = 422;
    const rFOut = 488;

    // Determine regional palette for this flute's concave-convex pillow
    let darkCol = PAL.inkBlack;
    let midCol = PAL.skyMid;
    let accentCol = PAL.skyPale;
    let liteCol = PAL.pureWhite;

    if (normA >= 200 && normA <= 340) {
      // Upper sky flutes
      midCol = (normA > 230 && normA < 310) ? PAL.skyDeep : PAL.skyMid;
      accentCol = (normA > 225 && normA < 260) ? PAL.cadPale : PAL.turqPale;
    } else if ((normA > 145 && normA < 200) || normA > 340 || normA < 25) {
      // Side horizon flutes: intense Turquoise & Cadmium bands!
      midCol = PAL.turqBright;
      accentCol = (i % 2 === 0) ? PAL.cadBright : PAL.cadYellow;
      liteCol = PAL.warmWhite;
    } else {
      // Lower street flutes: asphalt grey + warm cadmium/turquoise bounce
      midCol = PAL.asphaltMid;
      accentCol = (normA > 65 && normA < 115) ? PAL.cadOrange : PAL.turqDeep;
      liteCol = "#dbe4ec";
    }

    // Left/Leading shadow crescent of flute
    const pDark = annularSectorPts(rFIn, rFOut, a0, a0 + 2.8, 6);
    washPoly(pDark, darkCol, 240);

    // Core reflection pillow of flute
    const pMid = annularSectorPts(rFIn + 3, rFOut - 3, a0 + 2.5, a1 - 2.2, 6);
    washPoly(pMid, midCol, 225);

    // Transverse specular band inside flute (simulating radial concavity)
    const rBand1 = (normA > 180 && normA < 360) ? 452 : 434;
    const pAcc = annularSectorPts(rBand1, rBand1 + 18, a0 + 1.8, a1 - 1.8, 6);
    washPoly(pAcc, accentCol, 235);

    // Crisp black horizon break cutting across each flute
    const rBreak = 446 + Math.sin(normA * Math.PI / 180) * 14;
    const pBreak = annularSectorPts(rBreak - 4, rBreak + 5, a0 + 0.8, a1 - 0.8, 5);
    washPoly(pBreak, PAL.inkBlack, 248);

    // Trailing bright specular highlight crescent of flute
    const pLite = annularSectorPts(rFIn + 4, rFOut - 4, a1 - 2.3, a1, 6);
    washPoly(pLite, liteCol, 245);

    // Crisp ink contour around the stamped flute pillow
    const fluteBorder = [
      ...arcPts(rFOut, a0 + 0.5, a1 - 0.5, 6),
      ...arcPts(rFIn, a1 - 0.5, a0 + 0.5, 6)
    ];
    fluteBorder.push(fluteBorder[0]);
    strokeCurve(fluteBorder, "micro_ink", PAL.inkBlack, 0.9, 0.25);
  }

  // Deep stamped channel seams at R = 414 and R = 496
  strokeCurve(arcPts(R_FLUTE_OUT, 0, 360, 72), "crisp_ink", PAL.inkBlack, 1.5, 0.5);
  strokeCurve(arcPts(R_FLUTE_OUT - 3, 195, 345, 48), "specular_white", PAL.pureWhite, 1.2, 0.5);
  strokeCurve(arcPts(R_FLUTE_IN, 0, 360, 72), "crisp_ink", PAL.inkBlack, 1.6, 0.5);

  // --- ZONE C: TOROIDAL STEP-DOWN RIDGE (R = 372 to 414) ---
  // High-contrast double-reflection ring around the main dome
  washPoly(annularSectorPts(R_STEP_IN, R_STEP_OUT, 0, 360, 72), PAL.pureWhite, 255);

  // Compressed sky blue & zenith band on upper step
  washPoly(annularSectorPts(384, 412, 188, 352, 60), PAL.skyDeep, 235);
  washPoly(annularSectorPts(375, 390, 198, 342, 56), PAL.skyPale, 230);

  // Vivid curving Cadmium & Turquoise bands stretching around the toroidal step!
  washPoly(annularSectorPts(380, 404, 138, 215, 36), PAL.turqBright, 240);
  washPoly(annularSectorPts(392, 412, 125, 198, 36), PAL.cadBright, 240);
  washPoly(annularSectorPts(374, 386, 148, 205, 32), PAL.cadYellow, 245);

  washPoly(annularSectorPts(380, 404, 325, 402, 36), PAL.turqBright, 240);
  washPoly(annularSectorPts(392, 412, 342, 415, 36), PAL.cadOrange, 240);
  washPoly(annularSectorPts(374, 386, 335, 392, 32), PAL.cadYellow, 245);

  // Lower step asphalt & secondary turquoise/cadmium bounce
  washPoly(annularSectorPts(382, 410, 18, 162, 56), PAL.asphaltMid, 235);
  washPoly(annularSectorPts(394, 412, 32, 148, 48), PAL.asphaltDark, 240);
  washPoly(annularSectorPts(375, 386, 40, 140, 44), PAL.turqPale, 190);

  // Razor-sharp black ink specular break ribbon twisting around the toroidal ridge
  washPoly(annularSectorPts(398, 411, 178, 362, 64), PAL.inkBlack, 252);
  washPoly(annularSectorPts(373, 382, 5, 175, 64), PAL.inkBlack, 250);

  // Blinding white highlight wire on the crown of the step (R = 386..393)
  strokeCurve(arcPts(390, 192, 348, 56), "specular_white", PAL.pureWhite, 1.8, 0.5);
  strokeCurve(arcPts(391, 25, 155, 48), "specular_white", PAL.pureWhite, 1.1, 0.5);
}

// =============================================================================
// 3. MAIN CONVEX DOME: SKY-TO-ASPHALT BASE & SOFT SPRAY GRADIENTS
// =============================================================================
function drawDomeBaseAndSprayGradients() {
  // Base circular wash of the dome
  washPoly(annularSectorPts(0, R_DOME, 0, 360, 72), PAL.skyHorizon, 255);

  // --- LAYERED SKY BANDS (Y < 0 in 3D world) ---
  const skyBands = [
    { y1: -8.0, y2: -2.4, col: PAL.skyZenith, op: 245 },
    { y1: -2.5, y2: -1.35, col: PAL.skyDeep,   op: 235 },
    { y1: -1.4, y2: -0.68, col: PAL.skyMid,    op: 225 },
    { y1: -0.72, y2: -0.25, col: PAL.skyPale,  op: 220 },
    { y1: -0.28, y2: 0.06,  col: PAL.skyHorizon, op: 230 }
  ];

  for (const b of skyBands) {
    const poly3D = [
      [-9.0, b.y1, 1.4], [9.0, b.y1, 1.4],
      [9.0, b.y2, 1.4],  [-9.0, b.y2, 1.4]
    ];
    washPoly(projectPoly3D(poly3D, 20), b.col, b.op);
  }

  // --- LAYERED ASPHALT & GROUND BANDS (Y > 0 in 3D world) ---
  const groundBands = [
    { y1: 0.02, y2: 0.36, col: PAL.lawnMid,     op: 225 },
    { y1: 0.34, y2: 0.62, col: PAL.asphaltLite, op: 235 },
    { y1: 0.58, y2: 1.15, col: PAL.asphaltMid,  op: 240 },
    { y1: 1.10, y2: 2.40, col: PAL.asphaltDark, op: 245 },
    { y1: 2.30, y2: 7.50, col: PAL.charcoal,    op: 250 }
  ];

  for (const b of groundBands) {
    const poly3D = [
      [-9.0, b.y1, 1.4], [9.0, b.y1, 1.4],
      [9.0, b.y2, 1.4],  [-9.0, b.y2, 1.4]
    ];
    washPoly(projectPoly3D(poly3D, 20), b.col, b.op);
  }

  // --- SOFT SPRAY GRADIENTS (Sky Blue -> Horizon -> Asphalt Grey) ---
  // Sweeping fisheye spray curves across the upper sky
  for (let y = -3.8; y <= -0.05; y += 0.14) {
    let col = PAL.skyMid;
    if (y < -2.1) col = PAL.skyZenith;
    else if (y < -1.1) col = PAL.skyDeep;
    else if (y < -0.45) col = PAL.skyPale;
    else col = PAL.pureWhite;

    const pts = projectSegment3D([-7.5, y, 1.5], [7.5, y, 1.5], 24);
    strokeCurve(pts, "airbrush_wide", col, 1.1, 0.5);
    if (Math.abs(y * 10) % 2 < 1) {
      strokeCurve(pts, "fine_spray", col, 0.9, 0.5);
    }
  }

  // Sweeping fisheye spray curves across the lower asphalt street
  for (let y = 0.38; y <= 3.2; y += 0.14) {
    let col = PAL.asphaltMid;
    if (y < 0.65) col = PAL.asphaltLite;
    else if (y < 1.35) col = PAL.asphaltMid;
    else if (y < 2.2) col = PAL.asphaltDark;
    else col = PAL.deepChrome;

    const pts = projectSegment3D([-7.5, y, 1.4], [7.5, y, 1.4], 24);
    strokeCurve(pts, "airbrush_wide", col, 1.15, 0.5);
    strokeCurve(pts, "fine_spray", col, 0.85, 0.5);
  }

  // --- FISHEYE CUMULUS CLOUDS IN THE BENDING SKY ---
  const clouds = [
    { x1: -5.2, x2: -1.8, yTop: -1.55, yBot: -0.75, z: 2.6 },
    { x1: -1.4, x2: 2.1,  yTop: -1.85, yBot: -0.95, z: 2.8 },
    { x1: 2.2,  x2: 5.8,  yTop: -1.40, yBot: -0.68, z: 2.5 },
    { x1: -3.5, x2: 3.5,  yTop: -0.65, yBot: -0.22, z: 3.2 }
  ];

  for (const c of clouds) {
    // Cloud billow polygon in 3D
    const cPts3D = [];
    const steps = 16;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = c.x1 + (c.x2 - c.x1) * t;
      const puff = Math.abs(Math.sin(t * Math.PI * 3.5)) * 0.32 + Math.sin(t * Math.PI) * 0.25;
      cPts3D.push([x, c.yBot - puff - (c.yBot - c.yTop) * 0.5, c.z]);
    }
    for (let i = steps; i >= 0; i--) {
      const t = i / steps;
      const x = c.x1 + (c.x2 - c.x1) * t;
      cPts3D.push([x, c.yBot, c.z]);
    }
    const cPts2D = projectPoly3D(cPts3D, 2);
    washPoly(cPts2D, PAL.warmWhite, 215);

    // Cloud silver-blue shadow base
    const basePts = projectSegment3D([c.x1 + 0.2, c.yBot - 0.06, c.z], [c.x2 - 0.2, c.yBot - 0.06, c.z], 16);
    strokeCurve(basePts, "airbrush_soft", "#9ab5c9", 1.1, 0.5);
    strokeCurve(cPts2D.slice(0, steps + 1), "fine_spray", PAL.pureWhite, 1.0, 0.5);
  }
}

