// =============================================================================
// 5A. DISTANT TREES & HORIZON FOLIAGE
// =============================================================================
function drawDistantTreesAndHorizon() {
  // Billowing suburban shade trees along the horizon (Z = 2.6..3.4)
  const treeClusters = [
    { x1: -6.8, x2: -3.4, yTop: -0.95, yBot: 0.04, z: 2.5, col: PAL.lawnDark, hi: PAL.lawnLite },
    { x1: -0.85, x2: 0.75, yTop: -0.88, yBot: 0.04, z: 3.1, col: "#2e4244",   hi: PAL.turqPale },
    { x1: 3.5,  x2: 7.0,  yTop: -0.92, yBot: 0.04, z: 2.5, col: PAL.lawnDark, hi: PAL.cadPale }
  ];

  for (const tc of treeClusters) {
    const pts3D = [];
    const steps = 18;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = tc.x1 + (tc.x2 - tc.x1) * t;
      const crown = Math.abs(Math.sin(t * Math.PI * 5)) * 0.28 + Math.sin(t * Math.PI) * 0.35;
      pts3D.push([x, tc.yBot - (tc.yBot - tc.yTop) * 0.45 - crown, tc.z]);
    }
    pts3D.push([tc.x2, tc.yBot, tc.z]);
    pts3D.push([tc.x1, tc.yBot, tc.z]);

    const poly2D = projectPoly3D(pts3D, 2);
    washAndHatchPoly(poly2D, tc.col, 230, "2B", PAL.inkBlack, 0.7, 5, 35, { rand: 0.08 });

    // Sunlit foliage crown highlights & crisp ink shadow crevices
    strokeCurve(poly2D.slice(0, steps + 1), "fine_spray", tc.hi, 0.9, 0.4);
    strokeCurve(poly2D.slice(0, steps + 1), "micro_ink", PAL.inkBlack, 0.85, 0.4);
  }
}

// =============================================================================
// 5B. LEFT CLAPBOARD HOUSE ("THE CLASSIC COLONIAL")
// =============================================================================
function drawLeftColonialHouse() {
  const zFront = 2.05;
  const zBack = 2.85;
  const zRidge = 2.45;
  const xLeft = -3.55;
  const xMid = -0.85;
  const yGround = 0.04;
  const yEave = -1.25;
  const yPeak = -1.92;

  // 1. Sunlit Front Clapboard Wall (X in [xLeft, xMid], Z = zFront)
  const frontWall = projectPoly3D([
    [xLeft, yEave, zFront], [xMid, yEave, zFront],
    [xMid, yGround, zFront], [xLeft, yGround, zFront]
  ], 12);
  washPoly(frontWall, PAL.warmWhite, 250);

  // 2. Shaded Side Gable Wall (X = xMid, Z in [zFront, zBack])
  const sideWall = projectPoly3D([
    [xMid, yEave, zFront], [xMid, yPeak, zRidge],
    [xMid, yEave, zBack],  [xMid, yGround, zBack],
    [xMid, yGround, zFront]
  ], 10);
  washAndHatchPoly(sideWall, "#8fa6b8", 240, "2H", "#394858", 0.6, 5, 85, { rand: 0.03 });

  // 3. Pitched Shingle Roof
  const roofSlope = projectPoly3D([
    [xLeft - 0.1, yEave - 0.02, zFront - 0.06],
    [xMid + 0.06, yEave - 0.02, zFront - 0.06],
    [xMid + 0.04, yPeak, zRidge],
    [xLeft - 0.08, yPeak, zRidge]
  ], 12);
  washAndHatchPoly(roofSlope, PAL.charcoal, 245, "HB", PAL.inkBlack, 0.75, 4, 20, { rand: 0.04 });

  // Brick Chimney rising from ridge
  const chimney = projectPoly3D([
    [-2.35, yPeak - 0.32, zRidge], [-2.05, yPeak - 0.32, zRidge],
    [-2.05, yPeak + 0.1, zRidge],  [-2.35, yPeak + 0.1, zRidge]
  ], 4);
  washPoly(chimney, PAL.cadDeep, 240);
  strokeCurve(chimney, "micro_ink", PAL.inkBlack, 0.9, 0.2);

  // 4. Horizontal Clapboard Siding Lines (18 boards bent in fisheye perspective!)
  const numBoards = 18;
  for (let i = 1; i < numBoards; i++) {
    const y = yEave + (yGround - yEave) * (i / numBoards);
    // Front sunlit clapboard shadow line
    const lineFront = projectSegment3D([xLeft, y, zFront], [xMid, y, zFront], 14);
    strokeCurve(lineFront, "micro_ink", "#52606e", 0.7, 0.45);
    // Side shaded clapboard line
    const lineSide = projectSegment3D([xMid, y, zFront], [xMid, y, zBack], 8);
    strokeCurve(lineSide, "micro_ink", "#2c3744", 0.65, 0.45);
  }
  // Gable triangle clapboards
  for (let y = yPeak + 0.1; y < yEave; y += 0.08) {
    const t = (y - yPeak) / (yEave - yPeak);
    const z1 = zRidge - (zRidge - zFront) * t;
    const z2 = zRidge + (zBack - zRidge) * t;
    strokeCurve(projectSegment3D([xMid, y, z1], [xMid, y, z2], 6), "micro_ink", "#2c3744", 0.6, 0.4);
  }

  // 5. Upper Story Sash Windows with Vivid Turquoise Shutters
  const winXs = [-3.05, -2.20, -1.35];
  for (const wx of winXs) {
    const wy1 = -1.04, wy2 = -0.68;
    const ww = 0.24, sw = 0.11;

    // Left & Right Turquoise Shutters
    const shutL = projectPoly3D([
      [wx - ww / 2 - sw, wy1, zFront], [wx - ww / 2, wy1, zFront],
      [wx - ww / 2, wy2, zFront],      [wx - ww / 2 - sw, wy2, zFront]
    ], 4);
    const shutR = projectPoly3D([
      [wx + ww / 2, wy1, zFront], [wx + ww / 2 + sw, wy1, zFront],
      [wx + ww / 2 + sw, wy2, zFront], [wx + ww / 2, wy2, zFront]
    ], 4);
    washPoly(shutL, PAL.turqBright, 245);
    washPoly(shutR, PAL.turqRich, 245);

    // Window Glass (dark specular sky reflection)
    const glass = projectPoly3D([
      [wx - ww / 2, wy1, zFront], [wx + ww / 2, wy1, zFront],
      [wx + ww / 2, wy2, zFront], [wx - ww / 2, wy2, zFront]
    ], 4);
    washPoly(glass, PAL.deepChrome, 250);

    // Crisp white window sash & frame
    strokeCurve(glass, "specular_white", PAL.pureWhite, 0.9, 0.2);
    strokeCurve(projectSegment3D([wx - ww / 2, (wy1 + wy2) / 2, zFront], [wx + ww / 2, (wy1 + wy2) / 2, zFront], 4), "specular_white", PAL.pureWhite, 0.8, 0.2);
    strokeCurve(shutL, "micro_ink", PAL.inkBlack, 0.75, 0.2);
    strokeCurve(shutR, "micro_ink", PAL.inkBlack, 0.75, 0.2);
  }

  // 6. Covered Front Porch, White Columns & Cadmium Front Door
  const yPorchRoof = -0.54;
  const zPorch = 1.88;
  // Dark shadow under porch roof
  const porchRecess = projectPoly3D([
    [-2.85, yPorchRoof, zFront], [-1.05, yPorchRoof, zFront],
    [-1.05, yGround, zFront],    [-2.85, yGround, zFront]
  ], 10);
  washPoly(porchRecess, "#1c2633", 230);

  // Cadmium Orange Front Door
  const door = projectPoly3D([
    [-2.12, -0.46, zFront], [-1.82, -0.46, zFront],
    [-1.82, yGround, zFront], [-2.12, yGround, zFront]
  ], 4);
  washPoly(door, PAL.cadOrange, 245);
  strokeCurve(door, "micro_ink", PAL.inkBlack, 0.85, 0.2);

  // Lower windows flanking door
  for (const lwx of [-2.55, -1.38]) {
    const lGlass = projectPoly3D([
      [lwx - 0.16, -0.44, zFront], [lwx + 0.16, -0.44, zFront],
      [lwx + 0.16, -0.12, zFront], [lwx - 0.16, -0.12, zFront]
    ], 4);
    washPoly(lGlass, PAL.inkBlack, 245);
    strokeCurve(lGlass, "specular_white", PAL.pureWhite, 0.85, 0.2);
  }

  // Porch Roof Overhang
  const porchRoof = projectPoly3D([
    [-2.92, yPorchRoof - 0.08, zFront], [-1.00, yPorchRoof - 0.08, zFront],
    [-1.00, yPorchRoof, zPorch],        [-2.92, yPorchRoof, zPorch]
  ], 10);
  washPoly(porchRoof, PAL.asphaltDark, 245);

  // 4 Crisp White Turned Porch Columns
  for (const cxPos of [-2.85, -2.28, -1.65, -1.06]) {
