// 5C. RIGHT CLAPBOARD HOUSE ("MID-CENTURY RANCH WITH CADMIUM AWNING & FENCE")
// =============================================================================
function drawRightSuburbanHouse() {
  const zFront = 2.15;
  const zGarage = 2.35;
  const xStart = 0.68;
  const xWing = 2.55;
  const xEnd = 4.15;
  const yGround = 0.04;
  const yEave = -1.12;
  const yPeak = -1.76;

  // 1. Main Front-Gable Clapboard Wing (Robin's-egg Turquoise-Grey Siding)
  const mainWing = projectPoly3D([
    [xStart, yEave, zFront],
    [(xStart + xWing) * 0.5, yPeak, zFront],
    [xWing, yEave, zFront],
    [xWing, yGround, zFront],
    [xStart, yGround, zFront]
  ], 10);
  washPoly(mainWing, "#b8d8e0", 245);

  // Shaded Side Return Wall on Left of Right House
  const leftSideWall = projectPoly3D([
    [xStart, yEave, zFront], [xStart, yEave, 2.85],
    [xStart, yGround, 2.85], [xStart, yGround, zFront]
  ], 8);
  washPoly(leftSideWall, PAL.turqDeep, 225);

  // 2. Attached Garage Wing (X in [xWing, xEnd])
  const garageWall = projectPoly3D([
    [xWing, yEave + 0.18, zGarage], [xEnd, yEave + 0.18, zGarage],
    [xEnd, yGround, zGarage],       [xWing, yGround, zGarage]
  ], 10);
  washPoly(garageWall, PAL.warmWhite, 245);

  // Garage Roof Slope
  const garageRoof = projectPoly3D([
    [xWing - 0.05, yEave + 0.18, zGarage - 0.05],
    [xEnd + 0.08, yEave + 0.18, zGarage - 0.05],
    [xEnd, yPeak + 0.32, zGarage + 0.4],
    [xWing, yPeak + 0.32, zGarage + 0.4]
  ], 10);
  washAndHatchPoly(garageRoof, PAL.charcoal, 245, "HB", PAL.inkBlack, 0.7, 4, -22, { rand: 0.04 });

  // 3. Horizontal Clapboard Siding Lines on Right House
  for (let y = yPeak + 0.12; y < yGround; y += 0.085) {
    let x1 = xStart;
    let x2 = xWing;
    if (y < yEave) {
      const t = (y - yPeak) / (yEave - yPeak);
      const halfW = ((xWing - xStart) * 0.5) * t;
      const xCenter = (xStart + xWing) * 0.5;
      x1 = xCenter - halfW;
      x2 = xCenter + halfW;
    }
    strokeCurve(projectSegment3D([x1, y, zFront], [x2, y, zFront], 10), "micro_ink", "#3c5a66", 0.68, 0.45);
  }

  // 4. Picture Window with Bright Cadmium & White Striped Awning
  const pwX1 = 1.12, pwX2 = 2.12, pwY1 = -0.78, pwY2 = -0.24;
  const picWin = projectPoly3D([
    [pwX1, pwY1, zFront], [pwX2, pwY1, zFront],
    [pwX2, pwY2, zFront], [pwX1, pwY2, zFront]
  ], 6);
  washPoly(picWin, PAL.deepChrome, 250);
  // Sky & turquoise reflection slash inside picture window glass
  const glassGlint = projectPoly3D([
    [pwX1 + 0.08, pwY1 + 0.05, zFront], [pwX1 + 0.45, pwY1 + 0.05, zFront],
    [pwX1 + 0.25, pwY2 - 0.05, zFront], [pwX1 + 0.05, pwY2 - 0.05, zFront]
  ], 4);
  washPoly(glassGlint, PAL.turqPale, 210);
  strokeCurve(picWin, "specular_white", PAL.pureWhite, 1.1, 0.2);

  // Cadmium Orange & White Striped Canopy Awning over Picture Window
  const awning = projectPoly3D([
    [pwX1 - 0.04, pwY1 - 0.16, zFront], [pwX2 + 0.04, pwY1 - 0.16, zFront],
    [pwX2 + 0.06, pwY1 + 0.04, zFront - 0.18], [pwX1 - 0.06, pwY1 + 0.04, zFront - 0.18]
  ], 6);
  washPoly(awning, PAL.cadOrange, 250);
  for (let sx = pwX1 + 0.12; sx < pwX2; sx += 0.22) {
    strokeCurve(
      projectSegment3D([sx, pwY1 - 0.16, zFront], [sx, pwY1 + 0.04, zFront - 0.18], 4),
      "specular_white", PAL.pureWhite, 1.3, 0.2
    );
  }
  // Sharp black cast shadow under awning
  const awningShadow = projectPoly3D([
    [pwX1 - 0.02, pwY1, zFront], [pwX2 + 0.02, pwY1, zFront],
    [pwX2 + 0.02, pwY1 + 0.12, zFront], [pwX1 - 0.02, pwY1 + 0.12, zFront]
  ], 4);
  washPoly(awningShadow, PAL.inkBlack, 245);

  // Upper Gable Window
  const gWin = projectPoly3D([
    [1.46, -1.42, zFront], [1.78, -1.42, zFront],
    [1.78, -1.08, zFront], [1.46, -1.08, zFront]
  ], 4);
  washPoly(gWin, PAL.inkBlack, 245);
  strokeCurve(gWin, "specular_white", PAL.pureWhite, 0.9, 0.2);

  // 5. Paneled White Garage Door
  const gDoor = projectPoly3D([
    [2.75, -0.72, zGarage], [3.88, -0.72, zGarage],
    [3.88, yGround, zGarage], [2.75, yGround, zGarage]
  ], 8);
  washPoly(gDoor, "#e3eaef", 245);
  strokeCurve(gDoor, "crisp_ink", PAL.inkBlack, 1.0, 0.3);
  for (let gy = -0.56; gy < 0; gy += 0.18) {
    strokeCurve(projectSegment3D([2.75, gy, zGarage], [3.88, gy, zGarage], 6), "micro_ink", PAL.asphaltDark, 0.75, 0.4);
  }

  // Crisp Gable Roofline & Trim
  const gableLeft = projectSegment3D([xStart - 0.08, yEave + 0.03, zFront - 0.08], [(xStart + xWing) * 0.5, yPeak - 0.04, zFront - 0.08], 10);
  const gableRight = projectSegment3D([(xStart + xWing) * 0.5, yPeak - 0.04, zFront - 0.08], [xWing + 0.08, yEave + 0.03, zFront - 0.08], 10);
  strokeCurve(gableLeft, "crisp_ink", PAL.inkBlack, 1.6, 0.45);
  strokeCurve(gableRight, "crisp_ink", PAL.inkBlack, 1.6, 0.45);
  strokeCurve(gableLeft, "specular_white", PAL.pureWhite, 1.2, 0.45);
  strokeCurve(gableRight, "specular_white", PAL.pureWhite, 1.2, 0.45);

  // 6. White Picket Fence along the front lawn (Z = 1.78)
