// =============================================================================
// 5G. WOODEN UTILITY POLES & OVERHEAD POWER LINES
// =============================================================================
function drawUtilityPolesAndWires() {
  // Left Utility Pole (X = -3.15, Z = 1.34) & Right Utility Pole (X = 2.85, Z = 1.34)
  for (const px of [-3.15, 2.85]) {
    const poleLine = projectSegment3D([px, -2.55, 1.34], [px, 0.36, 1.34], 20);
    const poleHi = projectSegment3D([px - 0.03, -2.55, 1.34], [px - 0.03, 0.36, 1.34], 20);
    strokeCurve(poleLine, "crisp_ink", PAL.inkBlack, 1.55, 0.45);
    strokeCurve(poleHi, "specular_white", PAL.cadPale, 0.85, 0.45);

    // Cross-arms near top of pole
    for (const cyArm of [-2.35, -2.12]) {
      const arm = projectSegment3D([px - 0.35, cyArm, 1.34], [px + 0.35, cyArm, 1.34], 6);
      strokeCurve(arm, "crisp_ink", PAL.inkBlack, 1.2, 0.3);
    }
  }

  // 3 Sweeping Overhead Power Lines bending across the sky in fisheye arcs
  const wireHeights = [-2.36, -2.22, -2.08];
  for (const wy of wireHeights) {
    const wirePts = [];
    const steps = 32;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = -7.8 + 15.6 * t;
      // Catenary sag between poles
      const sag = Math.sin(t * Math.PI * 3) * 0.12;
      wirePts.push(worldToDome(x, wy + sag, 1.34));
    }
    strokeCurve(wirePts, "micro_ink", PAL.inkBlack, 0.8, 0.5);
  }
}

