function drawDomeSpecularsAndBreaks() {
  // 1. Blinding Afternoon Sun Starburst on Upper-Left Dome (X = -1.15, Y = -1.52, Z = 1.9)
  const [sunX, sunY] = worldToDome(-1.15, -1.52, 1.9);

  // Warm Cadmium-Gold & Turquoise-Ice Solar Halo
  for (let r = 82; r >= 12; r -= 10) {
    const col = r > 55 ? PAL.cadYellow : (r > 32 ? PAL.cadPale : PAL.pureWhite);
    const op = map(r, 82, 12, 35, 250);
    const sunRing = [];
    for (let a = 0; a < 360; a += 15) {
      const rad = a * Math.PI / 180;
      sunRing.push([sunX + r * Math.cos(rad), sunY + r * Math.sin(rad)]);
    }
    washPoly(sunRing, col, op);
  }

  // Soft airbrush bloom around solar hotspot
  brush.set("airbrush_wide", PAL.pureWhite, 1.8);
  brush.circle(sunX, sunY, 38, 0.1);
  brush.set("airbrush_soft", PAL.cadYellow, 1.3);
  brush.circle(sunX, sunY, 64, 0.15);

  // Razor-sharp Chrome Diffraction Rays
  for (let i = 0; i < 16; i++) {
    const ang = i * 22.5 + 8;
    const rad = ang * Math.PI / 180;
    const len = (i % 4 === 0) ? 125 : ((i % 2 === 0) ? 72 : 38);
    brush.set("specular_white", PAL.pureWhite, (i % 4 === 0) ? 1.5 : 0.9);
    brush.line(
      sunX + 4 * Math.cos(rad), sunY + 4 * Math.sin(rad),
      sunX + len * Math.cos(rad), sunY + len * Math.sin(rad)
    );
  }

  // 2. Crisp Black Ink Specular Breaks along the Horizon & Dome Perimeter
  // Main horizon break line sweeping from left edge to right edge
  const horizonL = projectSegment3D([-8.5, 0.03, 1.8], [-0.25, 0.03, 1.8], 20);
  const horizonR = projectSegment3D([0.22, 0.03, 1.8], [8.5, 0.03, 1.8], 20);
  strokeCurve(horizonL, "crisp_ink", PAL.inkBlack, 1.4, 0.45);
  strokeCurve(horizonR, "crisp_ink", PAL.inkBlack, 1.4, 0.45);

  // Outer dome crease (R = 372): Deep black ink groove + blinding white rim catchlight
  strokeCurve(arcPts(R_DOME, 0, 360, 72), "crisp_ink", PAL.inkBlack, 1.9, 0.5);
  strokeCurve(arcPts(R_DOME - 3.5, 195, 345, 56), "specular_white", PAL.pureWhite, 1.7, 0.5);
  strokeCurve(arcPts(R_DOME - 3.5, 20, 160, 48), "specular_white", PAL.turqPale, 1.1, 0.5);

  // Subtle machined double beauty-ring scored near the outer edge of the Baby Moon dome (R = 348)
  strokeCurve(arcPts(348, 155, 385, 64), "micro_ink", PAL.inkBlack, 1.0, 0.5);
  strokeCurve(arcPts(350, 190, 350, 56), "specular_white", PAL.pureWhite, 1.15, 0.5);
}

