// 8. ROAD GRIME, BRAKE DUST & MICRO-PITTING ON THE RIM
// =============================================================================
function drawRimGrimeAndPits() {
  // 1. Dusty Road Grime & Brake-Dust Spatter along the lower rim (angles 15 to 165 deg)
  for (let pass = 0; pass < 4; pass++) {
    const rGrime = 486 + pass * 15;
    const a1 = 18 + pass * 4;
    const a2 = 162 - pass * 4;
    const col = (pass % 2 === 0) ? PAL.grimeDark : PAL.grimeMid;
    strokeCurve(arcPts(rGrime, a1, a2, 36, 2.5), "grime_spatter", col, 1.25, 0.5);
  }

  // Fine dusty umber spray along the bottom flutes and step crease
  strokeCurve(arcPts(416, 30, 150, 32), "grime_spatter", PAL.grimeDark, 1.1, 0.5);
  strokeCurve(arcPts(494, 15, 165, 36), "airbrush_soft", PAL.grimeDust, 0.95, 0.5);
  strokeCurve(arcPts(536, 10, 170, 40), "grime_spatter", PAL.grimeRust, 1.15, 0.5);

  // 2. Forensic Chrome Pitting & Tiny Oxidation Specks (240 micro-pits along the rim)
  for (let i = 0; i < 240; i++) {
    // Heavily weighted toward the bottom & lower flanks of the hubcap rim
    let ang = random(0, 360);
    if (random() < 0.72) {
      ang = random(12, 168);
    }
    const rad = ang * Math.PI / 180;

    // Concentrated on outer rolled lip, fluted channel ridges, and step crease
    let rPit = random(475, 540);
    if (random() < 0.35) rPit = random(410, 475);
    else if (random() < 0.12) rPit = random(352, 410);

    const px = CX + rPit * Math.cos(rad);
    const py = CY + rPit * Math.sin(rad);
    const pitSize = random(1.1, 3.2);

    // Tiny rust/grime halo on larger pits
    if (pitSize > 2.2) {
      brush.set("micro_ink", PAL.grimeRust, 0.9);
      brush.circle(px, py, pitSize * 1.35, 0.25);
    }

    // Crisp black ink pit crater
    brush.set("crisp_ink", PAL.inkBlack, random(0.65, 1.25));
    brush.line(px - pitSize * 0.5, py, px + pitSize * 0.5, py + 0.4);

    // Microscopic pure-white specular catchlight on bottom/sunlit lip of the pit!
    brush.set("specular_white", PAL.pureWhite, random(0.55, 0.95));
    brush.line(px - pitSize * 0.35, py + 1.1, px + pitSize * 0.45, py + 1.3);
  }

  // 3. Hairline Chrome Polishing & Curb Scratches catching the afternoon sun
  for (let i = 0; i < 42; i++) {
    const aStart = random(0, 360);
    const aSpan = random(4, 16);
    const rSc = random(360, 535);
    const isBright = (aStart > 185 && aStart < 350) || random() < 0.4;
    strokeCurve(
      arcPts(rSc, aStart, aStart + aSpan, 6),
      isBright ? "specular_white" : "micro_ink",
      isBright ? PAL.pureWhite : PAL.inkBlack,
      random(0.35, 0.65),
      0.4
    );
  }
}

// Hyperrealistic Shipping Container Door — Rust, Flaking Teal & Padlock
// p5.js 2.x + p5.brush (WEBGL)

const SEED = 4829;

// Palette — High-contrast industrial marine teal & oxidized iron
const PAL = {
  // Deepest shadows & cast iron cores
  voidBlack: "#080707",
  ironBlack: "#14100e",
  umberDark: "#24110b",
  tealAbyss: "#07181d",
  tealShadow: "#0d2830",

  // Marine teal paint states (deep, mid, sun-bleached, flaking edge highlight)
  tealDeep: "#143d47",
  tealMid: "#1e5763",
  tealBright: "#2d7582",
  tealFaded: "#4c959e",
  tealBleach: "#7ebdc2",
  tealChipHi: "#bce3e6",

  // Rust spectrum (oxide red, burnt orange, raw sienna, sulfur/ochre crust)
  oxideDark: "#3d120a",
  oxideRed: "#6e1d11",
  oxideBright: "#992b15",
  burntOrange: "#c84614",
  orangeGlow: "#e66019",
  rawSienna: "#b86823",
  siennaLight: "#d98a36",
  ochreCrust: "#e8a948",

  // Salt, stencil & bare steel highlights
  stencilCream: "#dfd8c8",
  stencilShadow: "#8c8678",
  saltWhite: "#f2eee6",
  steelMid: "#6c7a80",
  steelBright: "#b5c4c9",
  steelSpec: "#eef5f7"
};

// Corrugation geometry helper
// Returns normalized height [0 = recessed valley, 1 = raised crest] and surface normal X (-1 to +1)
function getCorrugation(x) {
  // Left structural frame post from x = 0..84
  if (x < 84) {
    return { z: 0.92, nx: 0, zone: "frame" };
  }
  // Periodic trapezoidal waves across the door
  const period = 190;
  const phase = ((x - 84) % period + period) % period;
  // 0..28: left bevel (rising 0 -> 1, facing left toward raking light: nx = -1)
  // 28..98: raised crest flat (z = 1, nx = 0)
  // 98..126: right bevel (falling 1 -> 0, facing right away from light: nx = +1)
  // 126..190: recessed valley flat (z = 0, nx = 0)
  if (phase < 28) {
    const t = phase / 28;
    return { z: t, nx: -1.0, zone: "leftBevel", t };
  } else if (phase < 98) {
    const t = (phase - 28) / 70;
    return { z: 1.0, nx: 0.0, zone: "crest", t };
  } else if (phase < 126) {
    const t = (phase - 98) / 28;
    return { z: 1.0 - t, nx: 1.0, zone: "rightBevel", t };
  } else {
    const t = (phase - 126) / 64;
    return { z: 0.0, nx: 0.0, zone: "valley", t };
  }
}

// Compute 3D elevation in pixels at coordinate x
function surfaceZ(x, y) {
  let base = getCorrugation(x).z * 26;
  // Top header rail and bottom sill protrude slightly
  if (y < 105) base = 28;
  if (y > 1115) base = 28;
  return base;
}

// Project a point at elevation H onto the corrugated door along raking light vector
function projectShadowPoint(x, y, objZ) {
  // Light comes from upper-left: dx = +0.85, dy = +0.62 per unit height difference
  let dz = Math.max(0, objZ - surfaceZ(x, y));
  // One-step refinement because target x has its own corrugation height
  let sx = x + dz * 0.85;
  let sy = y + dz * 0.62;
  dz = Math.max(0, objZ - surfaceZ(sx, sy));
  return [x + dz * 0.85, y + dz * 0.62];
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom hyperrealism brushes for rust crust, paint chips, and splatter
  brush.add("rust_scumble", {
    type: "custom",
    weight: 4.5,
    scatter: 1.6,
    opacity: 42,
    spacing: 0.45,
    pressure: [0.4, 1.3, 0.3],
    noise: 0.9,
    tip: (_m) => {
      _m.rotate(25);
      _m.rect(-2.2, -0.9, 4.4, 1.8);
      _m.circle(1.6, 1.1, 1.4);
      _m.circle(-1.4, -1.2, 1.0);
    },
    rotate: "random",
    markerTip: false
  });

  brush.add("blister_pit", {
    type: "custom",
    weight: 3.0,
    scatter: 2.2,
    opacity: 85,
    spacing: 0.8,
    pressure: [0.6, 1.2, 0.5],
    noise: 1.0,
    tip: (_m) => {
      _m.circle(0, 0, 1.8);
      _m.rect(-1.8, 0.6, 1.2, 1.2);
    },
    rotate: "random",
    markerTip: false
  });

  brush.add("flake_edge", {
    type: "custom",
    weight: 1.8,
    scatter: 0.18,
    opacity: 165,
    spacing: 0.25,
    pressure: [0.8, 1.2, 0.7],
    noise: 0.75,
    tip: (_m) => {
      _m.rotate(15);
      _m.rect(-1.4, -0.4, 2.8, 0.8);
    },
    rotate: "natural",
    markerTip: false
  });

  brush.add("heavy_splatter", {
    type: "spray",
    weight: 14,
    scatter: 4.2,
    opacity: 65,
    spacing: 0.6,
    pressure: [0.5, 1.2, 0.4],
    noise: 1.0
  });

  // Custom vector field for weeping vertical gravity drips with slight corrugated deflection
  brush.addField("rust_gravity", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const fx = (col / field.length) * 1200;
        const fy = (row / field[0].length) * 1200;
        const corr = getCorrugation(fx);
        const bevelPull = corr.nx * 5.5;
        const jitter = (noise(col * 0.18, row * 0.18, t) - 0.5) * 14;
        field[col][row] = 90 + bevelPull + jitter;
      }
    }
    return field;
  });

  // Custom vector field for gritty metal brushing & salt-wind abrasion
  brush.addField("salt_wind", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        const n = noise(col * 0.12, row * 0.12);
        field[col][row] = 12 + (n - 0.5) * 28;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.tealAbyss);

  // 1. RENDER CORRUGATED STEEL DOOR PANELS (3D Raking Light & Rhythmic Shadow)
  drawCorrugatedPanels();

  // 2. STRUCTURAL TOP HEADER, LEFT FRAME POST & LOWER SILL
  drawStructuralFrame();

  // 3. WEATHERED STENCILLED CARGO NUMBERS & ISO MARKINGS
  drawCargoStencils();

  // 4. MAJOR RUST FIELDS, BLISTER ISLANDS & PEELING TEAL EDGES
  drawMajorRustIslands();

  // 5. HORIZONTAL GASKET SEAMS, RIVETS & WEEPING RUST DRIPS
  drawBoltsAndRustDrips();

  // 6. CAST SHADOWS OF LOCKING BARS, HANDLE & PADLOCK ACROSS CORRUGATIONS
  drawMechanismCastShadows();

  // 7. VERTICAL LOCKING BARS (CAM RODS) & MOUNTING BRACKETS
  drawLockingBarsAndBrackets();

  // 8. CENTRAL LOCKING HANDLE, LATCH HASP & RUST-EATEN PADLOCK
  drawHandleAndPadlock();

  // 9. FINAL HYPERREALISTIC MICRO-DETAIL: BLISTER NODULES, SALT CRUST & SCRATCHES
  drawFinalSurfaceGrime();

  noLoop();
}

// =============================================================================
// 1. CORRUGATED STEEL PANELS
// =============================================================================
function drawCorrugatedPanels() {
  // Left frame post base
  brush.noStroke();
  brush.wash(PAL.tealDeep, 235);
  brush.rect(0, 0, 84, 1200, "corner");
  brush.noWash();

  const period = 190;
  for (let baseX = 84; baseX < 1200; baseX += period) {
    const x0 = baseX;
    const x1 = Math.min(1200, baseX + 28);   // Left bevel (lit)
    const x2 = Math.min(1200, baseX + 98);   // Crest flat (mid-bright)
    const x3 = Math.min(1200, baseX + 126);  // Right bevel (deep core shadow)
    const x4 = Math.min(1200, baseX + 190);  // Valley flat (recessed shadow + bounce)

    // --- A. Opaque Base Washes ---
    brush.noStroke();
    if (x1 > x0) {
      brush.wash(PAL.tealBright, 240);
      brush.rect(x0, 95, x1 - x0, 1030, "corner");
    }
    if (x2 > x1) {
      brush.wash(PAL.tealMid, 240);
      brush.rect(x1, 95, x2 - x1, 1030, "corner");
    }
    if (x3 > x2) {
      brush.wash(PAL.tealAbyss, 250);
      brush.rect(x2, 95, x3 - x2, 1030, "corner");
    }
    if (x4 > x3) {
      brush.wash(PAL.tealShadow, 245);
      brush.rect(x3, 95, x4 - x3, 1030, "corner");
    }
    brush.noWash();

    // --- B. Dry-Media Scumbled Shading & Gradients across Facets ---
    // Left bevel raking highlight
    if (x1 > x0 + 4) {
      brush.noStroke();
      brush.mass("charcoal", PAL.tealFaded, { precision: 0.65, strength: 0.65, gradient: 0.4, outline: false });
      brush.rect(x0 + 1, 100, x1 - x0 - 2, 1020, "corner");
      brush.noMass();

      // Sun-bleached chalky streaks along the bevel ridge
      brush.hatchStyle("cpencil", PAL.tealBleach, 0.9);
      brush.hatch(7, 89, { rand: 0.12, gradient: 0.5 });
      brush.rect(x0 + 12, 105, Math.max(4, x1 - x0 - 12), 1010, "corner");
      brush.noHatch();
    }

    // Crest flat mottled marine teal texture
    if (x2 > x1 + 6) {
      const crestW = x2 - x1;
      brush.noStroke();
      brush.fill(PAL.tealBright, 65);
      brush.fillBleed(0.25, "out");
      brush.fillTexture(0.75, 0.4);
      brush.rect(x1 + 2, 110, crestW * 0.65, 990, "corner");
      brush.noFill();

      // Vertical industrial rolled-steel grain on crest
      brush.hatchStyle("2B", PAL.tealDeep, 0.75);
      brush.hatch(5.5, 90, { rand: 0.08, gradient: 0.35 });
      brush.rect(x1 + 3, 105, crestW - 6, 1010, "corner");
      brush.noHatch();

      // Crisp specular ridge lines on left & right knuckles of the crest
      for (let s = 0; s < 18; s++) {
        const sy1 = random(105, 1060);
        const sy2 = Math.min(1110, sy1 + random(35, 160));
        brush.set("cpencil", random() < 0.6 ? PAL.tealChipHi : PAL.tealBleach, random(0.7, 1.4));
        brush.line(x1 + random(-1.5, 1.5), sy1, x1 + random(-1.5, 1.5), sy2);
      }
      for (let s = 0; s < 15; s++) {
        const sy1 = random(105, 1060);
        const sy2 = Math.min(1110, sy1 + random(30, 140));
        brush.set("charcoal", PAL.voidBlack, random(0.8, 1.5));
        brush.line(x2 + random(-1.5, 1.5), sy1, x2 + random(-1.5, 1.5), sy2);
      }
    }

    // Right bevel deep core shadow + warm rust bounce light
    if (x3 > x2 + 4) {
      const bevW = x3 - x2;
      brush.noStroke();
      brush.mass("charcoal", PAL.voidBlack, { precision: 0.7, strength: 0.85, gradient: 0.3, outline: false });
      brush.rect(x2, 100, bevW * 0.75, 1020, "corner");
      brush.noMass();

      // Subtle warm reflected oxide bounce on the right side of the shadow bevel
      brush.hatchStyle("cpencil", PAL.oxideDark, 0.85);
      brush.hatch(6, 90, { rand: 0.15, gradient: 0.5 });
      brush.rect(x2 + bevW * 0.5, 140, bevW * 0.5, 960, "corner");
      brush.noHatch();
    }

    // Valley recessed shadow with trapped grime and vertical streaks
    if (x4 > x3 + 6) {
      const valW = x4 - x3;
      // Deep corner crease shadow where right bevel meets valley floor
      brush.noStroke();
      brush.mass("charcoal", PAL.voidBlack, { precision: 0.6, strength: 0.8, gradient: 0.6, outline: false });
      brush.rect(x3, 100, Math.min(22, valW), 1020, "corner");
      brush.noMass();

      // Ambient teal sky reflection in center-right of valley
      brush.hatchStyle("2B", PAL.tealMid, 0.75);
      brush.hatch(6.5, 90, { rand: 0.1, gradient: 0.4 });
      brush.rect(x3 + valW * 0.32, 110, valW * 0.58, 1000, "corner");
      brush.noHatch();

      // Valley crease line at x3 and x4
      for (let s = 0; s < 14; s++) {
        const sy1 = random(105, 1050);
        const sy2 = Math.min(1110, sy1 + random(40, 180));
        brush.set("2B", PAL.voidBlack, random(0.9, 1.5));
        brush.line(x3 + random(-1, 2), sy1, x3 + random(-1, 2), sy2);
      }
    }
  }
}

// =============================================================================
// 2. STRUCTURAL TOP HEADER, LEFT FRAME POST & LOWER SILL
// =============================================================================
function drawStructuralFrame() {
  // Top heavy box header (y = 0..104)
  brush.noStroke();
  brush.wash(PAL.tealDeep, 245);
  brush.rect(0, 0, 1200, 102, "corner");
  brush.noWash();

  // Under-lip cast shadow of top header undulating across the corrugations!
  brush.noStroke();
  brush.fill(PAL.voidBlack, 195);
  brush.fillBleed(0.08, "out");
  brush.beginShape(0.05);
  brush.vertex(0, 100);
  brush.vertex(1200, 100);
  for (let x = 1200; x >= 0; x -= 12) {
    const c = getCorrugation(x);
    const drop = 116 + (1.0 - c.z) * 26;
    brush.vertex(x, drop);
  }
  brush.endShape(true);
  brush.noFill();

  // Bottom heavy threshold sill (y = 1112..1200)
  brush.noStroke();
  brush.wash(PAL.umberDark, 245);
  brush.rect(0, 1112, 1200, 88, "corner");
