}

// =============================================================================
// 3. WEATHERED STENCILLED CARGO NUMBERS & ISO MARKINGS
// =============================================================================
function drawCargoStencils() {
  // Helper to draw a distorted, half-peeled stencil block that conforms to corrugation depth
  function stencilRect(x, y, w, h, peelChance = 0.35) {
    const steps = Math.max(2, Math.ceil(w / 6));
    const sw = w / steps;
    for (let i = 0; i < steps; i++) {
      const sx = x + i * sw;
      const c = getCorrugation(sx + sw * 0.5);
      // Perspective shift on corrugation depth
      const yShift = (1.0 - c.z) * 11;
      const n = noise(sx * 0.04, y * 0.04);
      if (n < peelChance) continue; // Eaten away by flaking paint / rust

      // Shade stencil according to facet normal
      let col = PAL.stencilCream;
      if (c.nx > 0.3) col = PAL.tealShadow;
      else if (c.z < 0.2) col = PAL.stencilShadow;
      else if (c.nx < -0.3) col = PAL.saltWhite;

      const topCut = n < peelChance + 0.15 ? random(0, h * 0.35) : 0;
      const botCut = noise(sx * 0.06 + 99, y * 0.06) < peelChance + 0.15 ? random(0, h * 0.35) : 0;
      const rh = h - topCut - botCut;
      if (rh <= 2) continue;

      const ry = y + yShift + topCut;
      brush.noStroke();
      brush.wash(col, random(185, 235));
      brush.rect(sx, ry, sw + 0.8, rh, "corner");
      brush.noWash();

      // Tiny shadow and lifted white flake edge where stencil is peeling
      if (topCut > 1 || botCut > 1 || random() < 0.35) {
        brush.set("rotring", PAL.voidBlack, 0.65);
        brush.line(sx, ry + rh, sx + sw, ry + rh + 1);
        brush.set("cpencil", PAL.saltWhite, 0.75);
        brush.line(sx, ry, sx + sw, ry);
      }
    }
  }

  // 7-segment industrial stencil glyph drawer
  // segs: [top, topLeft, topRight, mid, botLeft, botRight, bot]
  const DIGITS = {
    "0": [1, 1, 1, 0, 1, 1, 1],
    "1": [0, 0, 1, 0, 0, 1, 0],
    "2": [1, 0, 1, 1, 1, 0, 1],
    "3": [1, 0, 1, 1, 0, 1, 1],
    "4": [0, 1, 1, 1, 0, 1, 0],
    "5": [1, 1, 0, 1, 0, 1, 1],
    "6": [1, 1, 0, 1, 1, 1, 1],
    "7": [1, 0, 1, 0, 0, 1, 0],
    "8": [1, 1, 1, 1, 1, 1, 1],
    "9": [1, 1, 1, 1, 0, 1, 1],
    "G": [1, 1, 0, 1, 1, 1, 1],
    "K": [0, 1, 1, 1, 1, 1, 0],
    "U": [0, 1, 1, 0, 1, 1, 1],
    "S": [1, 1, 0, 1, 0, 1, 1],
    "C": [1, 1, 0, 0, 1, 0, 1]
  };

  function drawStencilChar(ch, x, y, w, h, thick, peel) {
    const s = DIGITS[ch];
    if (!s) return;
    const gap = 3; // Stencil bridge gaps!
    const halfH = h / 2;
    if (s[0]) stencilRect(x + thick, y, w - thick * 2, thick, peel); // top
    if (s[1]) stencilRect(x, y + gap, thick, halfH - gap * 2, peel); // topLeft
    if (s[2]) stencilRect(x + w - thick, y + gap, thick, halfH - gap * 2, peel); // topRight
    if (s[3]) stencilRect(x + thick, y + halfH - thick / 2, w - thick * 2, thick, peel); // mid
    if (s[4]) stencilRect(x, y + halfH + gap, thick, halfH - gap * 2, peel); // botLeft
    if (s[5]) stencilRect(x + w - thick, y + halfH + gap, thick, halfH - gap * 2, peel); // botRight
    if (s[6]) stencilRect(x + thick, y + h - thick, w - thick * 2, thick, peel); // bot
  }

  // Upper-right container serial number: "482910 [7]"
  const serial = ["4", "8", "2", "9", "1", "0"];
  for (let i = 0; i < serial.length; i++) {
    drawStencilChar(serial[i], 812 + i * 44, 175, 32, 68, 8, 0.36);
  }
  // Check-digit box around "7"
  const bx = 1094, by = 168, bw = 54, bh = 82;
  stencilRect(bx, by, bw, 6, 0.3);
  stencilRect(bx, by + bh - 6, bw, 6, 0.3);
  stencilRect(bx, by + 8, 6, bh - 16, 0.3);
  stencilRect(bx + bw - 6, by + 8, 6, bh - 16, 0.3);
  drawStencilChar("7", bx + 12, by + 9, 30, 64, 8, 0.32);

  // Secondary ISO size/type code below: "2 2 G 1"
  const iso = ["2", "2", "G", "1"];
  for (let i = 0; i < iso.length; i++) {
    drawStencilChar(iso[i], 815 + i * 44, 280, 30, 56, 7, 0.42);
  }

  // Left panel owner prefix fragment: "C S U"
  const owner = ["C", "S", "U"];
  for (let i = 0; i < owner.length; i++) {
    drawStencilChar(owner[i], 125 + i * 50, 175, 34, 68, 8, 0.4);
  }

  // Lower-right weight specification table lines & fragments
  for (let row = 0; row < 4; row++) {
    const ry = 460 + row * 38;
    stencilRect(830, ry, 85, 8, 0.45);
    drawStencilChar(String((row * 3 + 2) % 10), 940, ry - 8, 18, 28, 4.5, 0.45);
    drawStencilChar(String((row * 7 + 4) % 10), 964, ry - 8, 18, 28, 4.5, 0.45);
    drawStencilChar("0", 988, ry - 8, 18, 28, 4.5, 0.45);
    drawStencilChar("0", 1012, ry - 8, 18, 28, 4.5, 0.45);
    drawStencilChar("K", 1046, ry - 8, 18, 28, 4.5, 0.48);
    drawStencilChar("G", 1070, ry - 8, 18, 28, 4.5, 0.48);
  }
}

// =============================================================================
// 4. MAJOR RUST FIELDS, BLISTER ISLANDS & PEELING TEAL PAINT EDGES
// =============================================================================
function drawRustPatch(cx, cy, rx, ry, intensity = 1.0) {
  const pts = 24;
  const outerPoly = [];
  const midPoly = [];
  const corePoly = [];

  const seedOff = random(1000);
  for (let i = 0; i < pts; i++) {
    const ang = (i / pts) * 360;
    const nx = Math.cos((ang * Math.PI) / 180);
    const ny = Math.sin((ang * Math.PI) / 180);
    const n1 = noise(nx * 1.4 + seedOff, ny * 1.4 + seedOff);
    const n2 = noise(nx * 2.8 + seedOff + 50, ny * 2.8 + seedOff + 50);

    // Rust stretches vertically along corrugations
    const rMult = 0.45 + n1 * 0.75 + (n2 - 0.5) * 0.35;
    const ox = constrain(cx + nx * rx * rMult, 4, 1196);
    const oy = constrain(cy + ny * ry * rMult, 4, 1196);
    outerPoly.push([ox, oy]);

    const mx = constrain(cx + nx * rx * rMult * 0.74, 4, 1196);
    const my = constrain(cy + ny * ry * rMult * 0.74, 4, 1196);
    midPoly.push([mx, my]);

    const ix = constrain(cx + nx * rx * rMult * 0.42, 4, 1196);
    const iy = constrain(cy + ny * ry * rMult * 0.42, 4, 1196);
    corePoly.push([ix, iy]);
  }

  // 1. Raw Sienna / Burnt Orange Watercolor Stain Halo (bleeding into surround)
  brush.noStroke();
  brush.fill(random() < 0.5 ? PAL.rawSienna : PAL.burntOrange, 95 * intensity);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.85, 0.65);
  brush.beginShape(0.25);
  for (const p of outerPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // 2. Crusty Iron Oxide Red & Burnt Orange Mass inside the peeled paint boundary
  brush.noStroke();
  brush.mass("rust_scumble", PAL.oxideRed, {
    precision: 0.35,
    strength: 0.85 * intensity,
    gradient: 0.25,
    outline: false
  });
  brush.beginShape(0.15);
  for (const p of outerPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noMass();

  // 3. Hot Burnt Orange / Ochre Oxidized Crust in the mid-zone
  brush.noStroke();
  brush.mass("charcoal", random() < 0.6 ? PAL.burntOrange : PAL.siennaLight, {
    precision: 0.3,
    strength: 0.7,
    gradient: 0.35,
    outline: false
  });
  brush.beginShape(0.2);
  for (const p of midPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noMass();

  // 4. Deep Pitted Ferric Black / Umber Core Scale
  brush.noStroke();
  brush.mass("blister_pit", PAL.umberDark, {
    precision: 0.25,
    strength: 0.9,
    gradient: 0.2,
    outline: false
  });
  brush.beginShape(0.2);
  for (const p of corePoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noMass();

  // 5. HYPERREALISTIC FLAKING TEAL PAINT BORDER!
  // Raking light from upper-left means:
  // - Where paint curls up on the bottom/right of a rust hole, the curled teal lip catches bright tealChipHi (#bce3e6)
  // - Where paint overhangs on the top/left of a rust hole, it casts a crisp razor shadow (#080707) onto the rust!
  for (let i = 0; i < pts; i++) {
    const p1 = outerPoly[i];
    const p2 = outerPoly[(i + 1) % pts];
    const dx = p2[0] - p1[0];
    const dy = p2[1] - p1[1];

    // Shadow under overhanging paint flake
    brush.set("rotring", PAL.voidBlack, random(1.1, 2.2));
    brush.line(p1[0] + 1.5, p1[1] + 2.0, p2[0] + 1.5, p2[1] + 2.0);

    // Bright curled paint edge catching raking light
    const isLitEdge = dx - dy > -5 || random() < 0.45;
    const edgeCol = isLitEdge ? PAL.tealChipHi : PAL.tealBleach;
    brush.set("flake_edge", edgeCol, random(0.9, 1.8));
    brush.line(p1[0] - 1.2, p1[1] - 1.2, p2[0] - 1.2, p2[1] - 1.2);
  }

  // 6. Blister nodules and bright orange ferric dust inside the patch
  const noduleCount = Math.floor((rx * ry) / 420);
  for (let n = 0; n < noduleCount; n++) {
    const a = random(360);
    const r = random(0.1, 0.88);
    const bx = cx + Math.cos((a * Math.PI) / 180) * rx * r;
    const by = cy + Math.sin((a * Math.PI) / 180) * ry * r;
    const br = random(2.5, 8.5);
    // Dark crescent shadow on bottom-right of blister
    brush.set("charcoal", PAL.voidBlack, random(0.9, 1.5));
    brush.arc(bx + 1, by + 1, br, 15, 165);
    // Bright orange/ochre crust highlight on top-left of blister
    brush.set("rust_scumble", random() < 0.5 ? PAL.orangeGlow : PAL.ochreCrust, random(0.7, 1.3));
    brush.arc(bx - 1, by - 1, br, 195, 345);
  }
}

