// =============================================================================
// 5. BOLTS, RIVETS & WEEPING RUST STAIN DRIPS
// =============================================================================
function drawHexBolt(x, y, radius = 9, drawDrip = true, dripLen = 220) {
  if (drawDrip) {
    // 1. Soft watercolor raw sienna / burnt orange weeping stain trail
    const w = radius * random(1.2, 2.1);
    brush.noStroke();
    brush.fill(random() < 0.5 ? PAL.rawSienna : PAL.burntOrange, random(75, 115));
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.7, 0.5);
    brush.beginShape(0.2);
    brush.vertex(x - w, y);
    brush.vertex(x + w, y);
    brush.vertex(x + w * 0.55 + random(-4, 4), y + dripLen * 0.65);
    brush.vertex(x + random(-3, 3), y + dripLen);
    brush.vertex(x - w * 0.55 + random(-4, 4), y + dripLen * 0.65);
    brush.endShape(true);
    brush.noFill();

    // 2. Gravity vector-field flowLines for concentrated oxide streaks
    brush.field("rust_gravity");
    const streaks = Math.floor(random(4, 8));
    for (let s = 0; s < streaks; s++) {
      const sx = x + random(-radius * 0.9, radius * 0.9);
      const sy = y + random(-2, 6);
      const len = dripLen * random(0.45, 1.25);
      const col = s === 0 ? PAL.umberDark : s % 2 === 0 ? PAL.oxideRed : PAL.orangeGlow;
      const brName = s === 0 ? "2B" : "cpencil";
      brush.set(brName, col, random(0.65, 1.35));
      brush.flowLine(sx, sy, len, 90);
    }
    brush.noField();
  }

  // 3. Cast shadow of the hex bolt head (upper-left raking light -> shadow to bottom-right)
  brush.noStroke();
  brush.wash(PAL.voidBlack, 225);
  brush.circle(x + radius * 0.45, y + radius * 0.45, radius * 1.05, 0.15);
  brush.noWash();

  // 4. Washer & hex bolt body in crusted dark oxide + orange rust
  brush.noStroke();
  brush.wash(PAL.oxideDark, 245);
  brush.circle(x, y, radius * 1.15, 0.1);
  brush.wash(PAL.oxideRed, 240);
  brush.beginShape(0.02);
  for (let i = 0; i < 6; i++) {
    const a = (i * 60 + 15) * (Math.PI / 180);
    brush.vertex(x + Math.cos(a) * radius, y + Math.sin(a) * radius);
  }
  brush.endShape(true);
  brush.noWash();

  // 5. Crisp bevel highlights on upper-left hex flats & dark shadow on lower-right flats
  for (let i = 0; i < 6; i++) {
    const a1 = (i * 60 + 15) * (Math.PI / 180);
    const a2 = ((i + 1) * 60 + 15) * (Math.PI / 180);
    const x1 = x + Math.cos(a1) * radius;
    const y1 = y + Math.sin(a1) * radius;
    const x2 = x + Math.cos(a2) * radius;
    const y2 = y + Math.sin(a2) * radius;

    if (i === 3 || i === 4) {
      // Upper-left lit facets
      brush.set("rotring", random() < 0.5 ? PAL.ochreCrust : PAL.steelBright, 1.1);
      brush.line(x1, y1, x2, y2);
    } else if (i === 0 || i === 1) {
      // Lower-right shadow facets
      brush.set("rotring", PAL.voidBlack, 1.2);
      brush.line(x1, y1, x2, y2);
    } else {
      brush.set("cpencil", PAL.burntOrange, 0.9);
      brush.line(x1, y1, x2, y2);
    }
  }
}

