// =============================================================================
// 6. STEPPING 3D CAST SHADOWS OF LOCKING MECHANISM ACROSS CORRUGATIONS
// =============================================================================
function drawMechanismCastShadows() {
  // Helper: cast shadow of a vertical bar at (barX, width, elevationZ) from y1..y2
  // Because the door behind the bar is corrugated, the shadow's X coordinate steps left & right!
  function drawBarShadow(barX, barW, objZ, y1, y2) {
    brush.noStroke();
    brush.fill(PAL.voidBlack, 210);
    brush.fillBleed(0.06, "out");
    brush.beginShape(0.05);
    const step = 12;
    for (let y = y1; y <= y2; y += step) {
      const [sx, sy] = projectShadowPoint(barX - barW * 0.3, y, objZ);
      brush.vertex(sx, sy);
    }
    for (let y = y2; y >= y1; y -= step) {
      const [sx, sy] = projectShadowPoint(barX + barW * 0.5, y, objZ);
      brush.vertex(sx, sy);
    }
    brush.endShape(true);
    brush.noFill();
  }

  // Left locking rod (x = 328, radius = 17, elevation = 52)
  drawBarShadow(328, 34, 52, 0, 1200);

  // Right main locking rod (x = 755, radius = 19, elevation = 56)
  drawBarShadow(755, 38, 56, 0, 1200);

  // Cast shadow of brackets on both bars
  const bracketCenters = [
    [328, 225], [328, 525], [328, 995],
    [755, 225], [755, 495], [755, 1005]
  ];
  for (const [bx, by] of bracketCenters) {
    brush.noStroke();
    brush.fill(PAL.voidBlack, 215);
    brush.fillBleed(0.05, "out");
    brush.beginShape(0.08);
    const pts = [
      [bx - 56, by - 28], [bx + 56, by - 28],
      [bx + 56, by + 28], [bx - 56, by + 28]
    ];
    for (const [px, py] of pts) {
      const [sx, sy] = projectShadowPoint(px, py, 64);
      brush.vertex(sx, sy);
    }
    brush.endShape(true);
    brush.noFill();
  }

  // Cast shadow of the horizontal handle arm & hub (x = 515..775, y = 672..712, elevation = 68)
  brush.noStroke();
  brush.fill(PAL.voidBlack, 225);
  brush.fillBleed(0.06, "out");
  brush.beginShape(0.1);
  const handlePts = [
    [515, 678], [620, 672], [775, 665],
    [775, 712], [620, 715], [515, 718]
  ];
  for (const [px, py] of handlePts) {
    const [sx, sy] = projectShadowPoint(px, py, 68);
    brush.vertex(sx, sy);
  }
  brush.endShape(true);
  brush.noFill();

  // Cast shadow of the hanging padlock (x = 565..652, y = 700..858, elevation = 64)
  brush.noStroke();
  brush.fill(PAL.voidBlack, 235);
  brush.fillBleed(0.07, "out");
  brush.beginShape(0.08);
