function drawLockingBar(cx, radius) {
  const xL = cx - radius;
  const w = radius * 2;

  // 1. Base cylindrical steel & dark oxide core
  brush.noStroke();
  brush.wash(PAL.umberDark, 250);
  brush.rect(xL, 0, w, 1200, "corner");
  brush.noWash();

  // 2. Cylindrical 3D shading bands across the rod width:
  //    Left 25%: remnants of flaking teal paint & cold bare steel highlight
  //    Middle 40%: blistered burnt orange / raw sienna / oxide red crust
  //    Right 25%: deep ferric core shadow (#080707)
  //    Far right 10%: warm reflected oxide rim light (#992b15)
  brush.noStroke();
  brush.wash(PAL.voidBlack, 235);
  brush.rect(cx + radius * 0.15, 0, radius * 0.65, 1200, "corner");
  brush.wash(PAL.oxideRed, 210);
  brush.rect(cx - radius * 0.55, 0, radius * 0.75, 1200, "corner");
  brush.noWash();

  // 3. Textured rust scumbles & flaking teal islands along the vertical rod
  for (let y = 10; y < 1190; y += random(22, 48)) {
    const segH = random(20, 55);
    const state = random();

    if (state < 0.28) {
      // Surviving patch of chipped marine teal paint on the rod
      brush.noStroke();
      brush.wash(PAL.tealMid, 230);
      brush.rect(xL + 1, y, radius * 1.15, segH, "corner");
      brush.wash(PAL.tealChipHi, 210);
      brush.rect(xL + 2, y, radius * 0.35, segH, "corner");
      brush.noWash();

      // Peeling border around teal patch
      brush.set("rotring", PAL.voidBlack, 1.0);
      brush.line(xL + 1, y + segH, cx + 2, y + segH + 1);
      brush.set("flake_edge", PAL.tealChipHi, 1.1);
      brush.line(xL + 1, y, cx + 2, y);
    } else {
      // Heavy crusted rust scale on the rod
      const rCol = random([PAL.burntOrange, PAL.orangeGlow, PAL.rawSienna, PAL.oxideBright]);
      brush.set("rust_scumble", rCol, random(0.9, 1.6));
      brush.line(cx - radius * 0.4, y, cx - radius * 0.2, y + segH);

      brush.set("blister_pit", PAL.umberDark, random(0.8, 1.4));
      brush.line(cx + radius * 0.1, y + 4, cx + radius * 0.2, y + segH - 4);

      if (random() < 0.5) {
        brush.set("rust_scumble", PAL.ochreCrust, random(0.6, 1.1));
        brush.line(xL + 4, y + 3, xL + 5, y + segH * 0.7);
      }
    }

    // Bare steel / specular vertical glint along the left cylindrical highlight ridge
    if (random() < 0.65) {
      brush.set("cpencil", random() < 0.5 ? PAL.steelBright : PAL.steelSpec, random(0.8, 1.4));
      brush.line(xL + 3.5, y, xL + 3.5, y + segH * 0.85);
    }

    // Warm reflected rim light on the far right edge of cylinder
    brush.set("cpencil", PAL.burntOrange, 0.85);
    brush.line(cx + radius - 2, y, cx + radius - 2, y + segH);
  }

  // Crisp silhouette edges of the rod
  brush.set("rotring", PAL.voidBlack, 1.1);
  brush.line(xL, 0, xL, 1200);
  brush.line(cx + radius, 0, cx + radius, 1200);
}

