// Hyperrealist p5.brush Artwork:
// "Isolated in a Follow-Spot: Scuffed Vintage Microphone on Black Stage Boards"

const SPOT_X = 685;
const SPOT_Y = 760;
const SPOT_RX = 375;
const SPOT_RY = 360;

const HOT_X = 640;
const HOT_Y = 700;

// Helper: normalized distance from spotlight center (0 = center, 1 = hard rim)
function spotRadius(x, y) {
  const dx = (x - SPOT_X) / SPOT_RX;
  const dy = (y - SPOT_Y) / SPOT_RY;
  return Math.sqrt(dx * dx + dy * dy);
}

// Helper: check if point is inside the spotlight ellipse (with optional margin)
function inSpot(x, y, margin = 1.0) {
  return spotRadius(x, y) <= margin;
}

// Helper: clip a line segment to the spotlight ellipse using parametric sampling
function clipLineToSpot(x1, y1, x2, y2, margin = 0.995) {
  const steps = 40;
  let tStart = null;
  let tEnd = null;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = lerp(x1, x2, t);
    const y = lerp(y1, y2, t);
    if (inSpot(x, y, margin)) {
      if (tStart === null) tStart = t;
      tEnd = t;
    }
  }
  if (tStart === null || tEnd === null || tStart === tEnd) return null;
  return [
    lerp(x1, x2, tStart),
    lerp(y1, y2, tStart),
    lerp(x1, x2, tEnd),
    lerp(y1, y2, tEnd)
  ];
}

// Helper: safe brush stroke setter
function setBrush(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

// Helper: draw a closed polygon with wash or fill
function drawShapePoly(pts, curvature = 0.1) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Helper: generate points of an ellipse (with optional rotation in degrees)
function getEllipsePts(cx, cy, rx, ry, numPts = 64, rotDeg = 0, jitter = 0) {
  const pts = [];
  const rad = (rotDeg * Math.PI) / 180;
  const cosA = Math.cos(rad);
  const sinA = Math.sin(rad);
  for (let i = 0; i < numPts; i++) {
    const a = (i / numPts) * Math.PI * 2;
    const jx = jitter ? random(-jitter, jitter) : 0;
    const jy = jitter ? random(-jitter, jitter) : 0;
    const lx = (rx + jx) * Math.cos(a);
    const ly = (ry + jy) * Math.sin(a);
    pts.push([
      cx + lx * cosA - ly * sinA,
      cy + lx * sinA + ly * cosA
    ]);
  }
  return pts;
}

// Helper: color interpolation between hex strings
function blendHex(c1, c2, t) {
  return lerpColor(color(c1), color(c2), constrain(t, 0, 1));
}

// Optical color temperature at (x, y) inside the follow-spot:
// Cold pastel white/ice-blue near center, pale pastel amber near the rim
function getLightTint(x, y, baseLightHex = "#dce8f4", rimAmberHex = "#f2cba0", darkEdgeHex = "#6e533b") {
  const r = spotRadius(x, y);
  if (r < 0.78) {
    const dHot = dist(x, y, HOT_X, HOT_Y) / 320;
    return blendHex("#eef6fc", baseLightHex, constrain(dHot, 0, 1));
  } else if (r < 0.94) {
    const t = map(r, 0.78, 0.94, 0, 1);
    return blendHex(baseLightHex, rimAmberHex, t);
  } else {
    const t = map(r, 0.94, 1.0, 0, 1);
    return blendHex(rimAmberHex, darkEdgeHex, t);
  }
}

