  brush.add("velvet_dark", {
    type: "default",
    weight: 16,
    scatter: 0.45,
    sharpness: 0.15,
    grain: 0.75,
    opacity: 160,
    spacing: 0.25,
    pressure: [0.6, 1.2, 0.6],
    rotate: "random",
    noise: 0.8
  });

  brush.add("pastel_shader", {
    type: "default",
    weight: 9,
    scatter: 0.3,
    sharpness: 0.2,
    grain: 0.6,
    opacity: 55,
    spacing: 0.22,
    pressure: [0.4, 1.1, 0.4],
    rotate: "natural",
    noise: 0.5
  });

  brush.add("fine_grain", {
    type: "default",
    weight: 1.1,
    scatter: 0.08,
    sharpness: 0.82,
    grain: 0.45,
    opacity: 145,
    spacing: 0.15,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.35
  });

  brush.add("beam_haze", {
    type: "spray",
    weight: 28,
    scatter: 2.8,
    opacity: 18,
    spacing: 0.6,
    pressure: [0.5, 1.0, 0.5],
    rotate: "random",
    noise: 1.0
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deepest velvety charcoal black ground
  background("#09090d");

  // 2. Spotlight pool base & optical amber rim foundation
  drawSpotlightFoundation();

  // 3. Stage boards: perspective seams, wood grain, nail heads, caster tracks & heel scuffs
  drawStageBoards();

  // 4. Pastel gaffer tape ("spike marks" & cable restraint) on the stage boards
  drawGafferTape();

  // 5. Cast shadows of the base, stand, microphone cage, and coiled cable
  drawFloorShadows();

  // 6. Coiled XLR microphone cable on the stage boards and rising to the mic
  drawCoiledCable();

  // 7. Heavy scuffed cast-iron base and telescoping chrome stand with clutch
  drawStandAndBase();

  // 8. Scuffed vintage ribbed microphone (Shure 55 Unidyne style)
  drawVintageMicrophone();

  // 9. Atmospheric follow-spot haze (soft spray) and illuminated dust motes in the beam
  drawBeamHazeAndDust();

  // 10. Crisp follow-spot aperture rim and dense velvety charcoal black outer surround
  drawVelvetCharcoalSurround();

  noLoop();
}

// ============================================================================
// 2. FOLLOW-SPOT POOL FOUNDATION (COLD WHITE CENTER, PALE AMBER AT RIM)
// ============================================================================
function drawSpotlightFoundation() {
  brush.noField();
  brush.noStroke();

  // Concentric optical layers from rim inward
  const layers = [
    { scale: 1.005, dx: 0, dy: 0, col: "#231a14", op: 255 },
    { scale: 0.992, dx: 0, dy: 0, col: "#4a3524", op: 240 },
    { scale: 0.978, dx: 0, dy: 0, col: "#7a573a", op: 220 },
    { scale: 0.962, dx: 0, dy: 0, col: "#a87c56", op: 190 },
    { scale: 0.942, dx: -2, dy: -2, col: "#caa077", op: 170 },
    { scale: 0.918, dx: -4, dy: -4, col: "#be9c7e", op: 150 },
    { scale: 0.885, dx: -6, dy: -6, col: "#8d8688", op: 165 },
    { scale: 0.840, dx: -10, dy: -10, col: "#5a6272", op: 200 },
    { scale: 0.770, dx: -15, dy: -16, col: "#465060", op: 230 },
    { scale: 0.670, dx: -22, dy: -24, col: "#525e70", op: 210 },
    { scale: 0.550, dx: -28, dy: -32, col: "#617084", op: 190 },
    { scale: 0.420, dx: -34, dy: -40, col: "#728399", op: 175 },
    { scale: 0.280, dx: -40, dy: -46, col: "#8598b0", op: 160 },
    { scale: 0.160, dx: -44, dy: -52, col: "#97acc4", op: 140 }
  ];

  for (let l of layers) {
    brush.wash(l.col, l.op);
    const pts = getEllipsePts(
      SPOT_X + l.dx,
      SPOT_Y + l.dy,
      SPOT_RX * l.scale,
      SPOT_RY * l.scale,
      72
    );
    drawShapePoly(pts, 0.08);
  }
  brush.noWash();

  // Soft watercolor texture wash for subtle stage floor unevenness
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.25);
  brush.fill("#363e4d", 75);
  drawShapePoly(getEllipsePts(SPOT_X, SPOT_Y, SPOT_RX * 0.86, SPOT_RY * 0.86, 56), 0.1);

  brush.fill("#a8bdd4", 55);
  drawShapePoly(getEllipsePts(HOT_X, HOT_Y, SPOT_RX * 0.44, SPOT_RY * 0.42, 48), 0.1);
  brush.noFill();

  // Warm pale amber optical halation ring at the rim using soft pastel shader strokes
  const rimSteps = 140;
  for (let i = 0; i < rimSteps; i++) {
    const a1 = (i / rimSteps) * 360;
    const a2 = ((i + 1.4) / rimSteps) * 360;
    const rNorm = random(0.89, 0.985);
    const x1 = SPOT_X + SPOT_RX * rNorm * cos(a1);
    const y1 = SPOT_Y + SPOT_RY * rNorm * sin(a1);
    const x2 = SPOT_X + SPOT_RX * rNorm * cos(a2);
    const y2 = SPOT_Y + SPOT_RY * rNorm * sin(a2);

    const rimCol = rNorm > 0.95 ? "#e5b887" : (rNorm > 0.92 ? "#f2d4ae" : "#dcc8b8");
    setBrush("pastel_shader", rimCol, random(0.7, 1.4));
    brush.line(x1, y1, x2, y2);
  }
}

// ============================================================================
// 3. BLACK STAGE BOARDS (SEAMS, GRAIN, NAILS, SCUFFS)
// ============================================================================
function drawStageBoards() {
  // Boards run at a slight theatrical perspective tilt (-7.5 degrees)
  const tilt = -7.5;
  const tanT = Math.tan((tilt * Math.PI) / 180);

  // Generate plank seam Y intercepts (slightly narrower higher up for perspective)
  const seamYs = [];
  let curY = 390;
  let dy = 48;
  while (curY < 1180) {
    seamYs.push(curY);
    curY += dy;
    dy += 3.6; // perspective widening toward foreground
  }

  // 3A. Base tonal variation per plank & wood grain fibers
  for (let p = 0; p < seamYs.length - 1; p++) {
    const yTop0 = seamYs[p];
    const yBot0 = seamYs[p + 1];
    const plankH = yBot0 - yTop0;

    // Butt-joint X coordinate for this plank (staggered across stage)
    const buttX = 330 + ((p * 257 + 110) % 690);

    // Draw wood grain lines along each plank
    const numGrains = Math.floor(plankH * 1.45);
    for (let g = 0; g < numGrains; g++) {
      const frac = (g + random(0.1, 0.9)) / numGrains;
      const yBase = lerp(yTop0, yBot0, frac);

      // Break grain into segments across X
      const segs = 7;
      for (let s = 0; s < segs; s++) {
        const x1 = map(s, 0, segs, 300, 1070) + random(-8, 8);
        const x2 = map(s + 1, 0, segs, 300, 1070) + random(-8, 8);
        const xm = (x1 + x2) * 0.5;

        // Slight cathedral wave near butt-joint or plank center
        const wave1 = sin((x1 - buttX) * 0.8 + p * 40) * 2.2;
        const wave2 = sin((x2 - buttX) * 0.8 + p * 40) * 2.2;
        const y1 = yBase + (x1 - SPOT_X) * tanT + wave1;
        const y2 = yBase + (x2 - SPOT_X) * tanT + wave2;

        const clipped = clipLineToSpot(x1, y1, x2, y2, 0.985);
        if (!clipped) continue;

        const ym = (clipped[1] + clipped[3]) * 0.5;
        const r = spotRadius(xm, ym);
        const dHot = dist(xm, ym, HOT_X, HOT_Y);

        // Alternate dark timber grain and lit cold-pastel/amber wood grain ridges
        if (random() < 0.58) {
          // Dark painted timber pore line
          const darkCol = r > 0.88
            ? blendHex("#242834", "#2e2219", map(r, 0.88, 1, 0, 1))
            : blendHex("#1c202a", "#2e3646", constrain(1 - dHot / 350, 0, 1));
          setBrush("2H", darkCol, random(0.45, 0.85));
          brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
        } else {
          // Illuminated wood grain ridge catching the follow-spot
          const litCol = getLightTint(xm, ym, "#9eb2c8", "#e5be94", "#6e5138");
          const dimmed = blendHex("#3a4354", litCol, constrain(1.05 - dHot / 390, 0.25, 0.95));
          setBrush("cpencil", dimmed, random(0.35, 0.75));
          brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
        }
      }
    }

    // Draw plank butt-joint (vertical-ish seam where two boards meet)
    const bxTop = buttX;
    const byTop = yTop0 + (bxTop - SPOT_X) * tanT;
    const bxBot = buttX - plankH * tanT;
    const byBot = yBot0 + (bxBot - SPOT_X) * tanT;
    if (inSpot((bxTop + bxBot) * 0.5, (byTop + byBot) * 0.5, 0.93)) {
      setBrush("rotring", "#101218", 1.1);
      brush.line(bxTop, byTop, bxBot, byBot);
      const edgeHighlight = getLightTint(bxTop, byTop, "#c4d6e8", "#ecc59a", "#785a40");
      setBrush("2H", edgeHighlight, 0.65);
      brush.line(bxTop + 1.8, byTop, bxBot + 1.8, byBot);

      // Twin countersunk nail heads on either side of the butt-joint
      for (let side of [-9, 9]) {
        for (let nf of [0.26, 0.74]) {
          const nx = lerp(bxTop, bxBot, nf) + side;
          const ny = lerp(byTop, byBot, nf) + side * tanT;
          if (inSpot(nx, ny, 0.92)) {
            setBrush("rotring", "#14161e", 0.9);
            brush.circle(nx, ny, 2.2, 0.2);
            setBrush("2H", getLightTint(nx, ny, "#dceaf6", "#f2cfa4", "#8a684a"), 0.55);
            brush.arc(nx, ny, 2.2, -30, 140);
          }
        }
      }
    }
  }

  // 3B. Main horizontal-ish stage plank seams & illuminated upper-lip bevels
  for (let p = 0; p < seamYs.length; p++) {
    const y0 = seamYs[p];
    const segs = 14;
    for (let s = 0; s < segs; s++) {
      const x1 = map(s, 0, segs, 290, 1080);
      const x2 = map(s + 1, 0, segs, 290, 1080);
      const y1 = y0 + (x1 - SPOT_X) * tanT + random(-0.4, 0.4);
      const y2 = y0 + (x2 - SPOT_X) * tanT + random(-0.4, 0.4);

      const clipped = clipLineToSpot(x1, y1, x2, y2, 0.99);
      if (!clipped) continue;

      const xm = (clipped[0] + clipped[2]) * 0.5;
      const ym = (clipped[1] + clipped[3]) * 0.5;
      const r = spotRadius(xm, ym);

      // Deep dark shadow gap between stage boards
      setBrush("rotring", "#0d0e14", map(p, 0, seamYs.length, 1.0, 1.65));
      brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);

      setBrush("2B", "#181b24", 0.9);
      brush.line(clipped[0], clipped[1] - 1.2, clipped[2], clipped[3] - 1.2);

      // Crisp specular/pastel highlight on the lower board's upper bevel lip catching the overhead spot
      const lipCol = getLightTint(xm, ym, "#d6e6f4", "#f0caa0", "#7c5c40");
      const lipWeight = map(r, 0, 1, 0.95, 0.45);
      setBrush("fine_grain", lipCol, lipWeight);
      brush.line(clipped[0], clipped[1] + 1.8, clipped[2], clipped[3] + 1.8);
    }
  }

  // 3C. Stage wear: scuff marks, heel drags, chalky stage dust, and faint caster tracks
  // Faint twin road-case caster tracks crossing the boards
  for (let trackOffset of [-18, 18]) {
    const tx1 = 350, ty1 = 650 + trackOffset;
    const tx2 = 980, ty2 = 860 + trackOffset;
    const clipped = clipLineToSpot(tx1, ty1, tx2, ty2, 0.95);
    if (clipped) {
      setBrush("pastel_shader", "#7b8da3", 0.55);
      brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
    }
  }

  // Scuff marks (pale pastel shoe-sole/chalk scuffs and dark rubber heel drags)
  const pastelScuffCols = ["#d6e4f0", "#e2d8ec", "#d2e6e0", "#f0dec8", "#b8cada"];
  for (let i = 0; i < 95; i++) {
    const angle = random(360);
    const distR = Math.pow(random(), 0.65) * 0.91;
    const sx = SPOT_X + cos(angle) * SPOT_RX * distR;
    const sy = SPOT_Y + sin(angle) * SPOT_RY * distR;

    const len = random(14, 58);
    const dir = random(-35, 35) + (random() < 0.4 ? 90 : 0);
    const ex = sx + cos(dir) * len;
    const ey = sy + sin(dir) * len * 0.65;

    if (!inSpot(ex, ey, 0.93)) continue;

    if (random() < 0.68) {
      // Pale scuffed paint / shoe mark tinted by spotlight position
      const basePastel = random(pastelScuffCols);
      const col = getLightTint(sx, sy, basePastel, "#f0cca2", "#8a6b4e");
      setBrush(random() < 0.5 ? "cpencil" : "HB", col, random(0.45, 1.1));
      const mx = (sx + ex) * 0.5 + random(-6, 6);
      const my = (sy + ey) * 0.5 + random(-4, 4);
      brush.spline([[sx, sy, 0.3], [mx, my, 1.0], [ex, ey, 0.2]], 0.5);
    } else {
      // Dark rubber heel scuff
      setBrush("2B", "#171a22", random(0.6, 1.25));
      brush.line(sx, sy, ex, ey);
    }
  }

  // Subtle dusty chalk/rosin patches on the boards around the mic position
  for (let i = 0; i < 18; i++) {
    const px = HOT_X + random(-160, 180);
    const py = HOT_Y + random(-90, 190);
    if (inSpot(px, py, 0.85)) {
      const dustCol = getLightTint(px, py, "#cad8e8", "#ebd0b0", "#7c6248");
      setBrush("pastel_shader", dustCol, random(0.5, 1.1));
      brush.line(px - random(10, 28), py, px + random(10, 28), py + random(-4, 4));
    }
  }
}

// ============================================================================
// 4. GAFFER TAPE ("SPIKE MARKS" & CABLE TAPE)
// ============================================================================
function drawStripOfGafferTape(cx, cy, len, wid, angleDeg, baseCol, hiCol, shadowCol, peelCorner = true) {
  const rad = (angleDeg * Math.PI) / 180;
  const ux = Math.cos(rad);
  const uy = Math.sin(rad);
  const vx = -Math.sin(rad);
  const vy = Math.cos(rad);

  const hw = len * 0.5;
  const hh = wid * 0.5;

  const corners = [
    [cx - ux * hw - vx * hh, cy - uy * hw - vy * hh],
    [cx + ux * hw - vx * hh, cy + uy * hw - vy * hh],
    [cx + ux * hw + vx * hh, cy + uy * hw + vy * hh],
    [cx - ux * hw + vx * hh, cy - uy * hw + vy * hh]
  ];

  // Drop shadow along bottom-right edge of the tape
  setBrush("rotring", "#12151e", 1.1);
  brush.line(corners[1][0] + 1.5, corners[1][1] + 2, corners[2][0] + 1.5, corners[2][1] + 2);
  brush.line(corners[2][0] + 1.5, corners[2][1] + 2, corners[3][0] + 1.5, corners[3][1] + 2);

  // Solid wash for matte gaffer tape body
  brush.noStroke();
  brush.wash(baseCol, 235);
  drawShapePoly(corners, 0.03);
  brush.noWash();

  // Cloth weave cross-hatching on the gaffer tape
  brush.hatchStyle("2H", hiCol, 0.45);
  brush.hatch(3.2, angleDeg, { rand: 0.04 });
  drawShapePoly(corners, 0.02);
  brush.noHatch();

  brush.hatchStyle("2H", shadowCol, 0.4);
  brush.hatch(3.8, angleDeg + 90, { rand: 0.04 });
  drawShapePoly(corners, 0.02);
  brush.noHatch();

  // Scuffs & dirt smudged onto the tape from stage boots
  for (let i = 0; i < 8; i++) {
    const t = random(-0.42, 0.42);
    const s = random(-0.35, 0.35);
    const sx = cx + ux * len * t + vx * wid * s;
    const sy = cy + uy * len * t + vy * wid * s;
    setBrush("HB", shadowCol, random(0.4, 0.8));
    brush.line(sx - 4, sy - 1, sx + 4, sy + 1);
  }

  // Torn cloth edges with tiny frayed white threads at the ends
  setBrush("fine_grain", hiCol, 0.65);
  brush.line(corners[0][0], corners[0][1], corners[1][0], corners[1][1]);
  brush.line(corners[3][0], corners[3][1], corners[0][0], corners[0][1]);

  // Frayed cotton threads at torn tape ends
  for (let side of [-1, 1]) {
    for (let f = -0.4; f <= 0.4; f += 0.2) {
      const ex = cx + ux * hw * side + vx * wid * f;
      const ey = cy + uy * hw * side + vy * wid * f;
      setBrush("2H", "#eef4fa", 0.4);
      brush.line(ex, ey, ex + ux * side * random(2, 5), ey + uy * side * random(2, 5));
    }
  }

  // Optional curled/peeling corner casting a tiny dark triangular shadow
  if (peelCorner) {
    const px = corners[1][0];
    const py = corners[1][1];
    setBrush("rotring", "#10131a", 1.2);
    brush.line(px - ux * 8, py - uy * 8, px + vx * 7, py + vy * 7);
    setBrush("fine_grain", "#f2f7fc", 0.85);
    brush.line(px - ux * 8, py - uy * 8 - 1.5, px + vx * 6 - 2, py + vy * 6 - 2);
  }
}

function drawGafferTape() {
  // 1. Stage Manager's "X" Spike Mark near the front-left of the mic stand base
  // Soft pastel mint-celadon gaffer tape
  drawStripOfGafferTape(618, 922, 68, 15, 24, "#b8d6c6", "#dcf0e5", "#7a9989", true);
  drawStripOfGafferTape(620, 922, 64, 15, -52, "#c2ded0", "#e4f5ec", "#82a190", true);

  // 2. Small pastel cream label strip with faded marker handwriting near the spike mark
  drawStripOfGafferTape(795, 855, 54, 14, -14, "#e8dec8", "#f7f0e2", "#a89c86", false);
  // Tiny scrawled "VOX 1" marker strokes on the cream tape
  setBrush("rotring", "#2b2d38", 0.55);
  brush.line(778, 856, 782, 860);
  brush.line(782, 860, 785, 854);
  brush.circle(791, 856, 2.5, 0.2);
  brush.line(797, 853, 803, 858);
  brush.line(803, 853, 797, 858);

  // 3. Soft pastel dusty-rose gaffer tape strip at bottom-Right/Left holding floor mark
  drawStripOfGafferTape(512, 745, 58, 14, -8, "#deb8c0", "#f2d8de", "#9c7880", true);
}

// ============================================================================
// 5. FLOOR CAST SHADOWS (STAND, MICROPHONE CAGE, COILED CABLE)
// ============================================================================
function drawFloorShadows() {
  brush.noStroke();

  // 5A. Cast shadow of the heavy round base (offset down-right toward (725, 928))
  const baseShadowPts = getEllipsePts(724, 927, 98, 53, 56, -4);
  brush.wash("#0c0e14", 215);
  drawShapePoly(baseShadowPts, 0.08);
  brush.noWash();

  // 5B. Long dramatic shadow of the stand shaft, clutch, and vintage mic head
  // Stretching from the base at (705, 915) to the lower-right rim at (978, 1012)
  const sx1 = 705, sy1 = 915;
  const sx2 = 965, sy2 = 1006;

  // Soft outer penumbra of the shaft shadow
  for (let w = 18; w >= 6; w -= 4) {
    setBrush("pastel_shader", "#12151e", map(w, 6, 18, 1.1, 0.55));
    brush.line(sx1, sy1, sx2, sy2);
  }
  // Crisp dark umbra core of the shaft shadow
  setBrush("rotring", "#0b0d12", 4.2);
  brush.line(sx1, sy1, sx2, sy2);
  setBrush("charcoal", "#0d0f16", 1.8);
  brush.line(sx1, sy1, sx2, sy2);

  // Clutch shadow bulge along the shaft shadow around (825, 957)
  brush.noStroke();
  brush.wash("#0b0d12", 210);
  drawShapePoly(getEllipsePts(825, 957, 18, 9, 28, 19), 0.1);

  // Iconic ribbed vintage microphone head shadow near the warm amber rim at (968, 1007)!
  const micShadPts = getEllipsePts(968, 1007, 42, 24, 44, 19);
  const clippedMicShad = micShadPts.filter(p => inSpot(p[0], p[1], 0.992));
  if (clippedMicShad.length > 6) {
    brush.wash("#111016", 205);
    drawShapePoly(clippedMicShad, 0.08);
    brush.noWash();

    // Faint warm amber slits of light filtering through the mic cage ribs in the shadow!
    for (let r = -22; r <= 22; r += 8) {
      const rx = 968 + r * 0.85;
      const ry = 1007 + r * 0.32;
      if (inSpot(rx, ry, 0.96)) {
        setBrush("fine_grain", "#d8b088", 0.65);
        brush.line(rx - 5, ry - 9, rx + 5, ry + 9);
      }
    }
  }
  brush.noWash();
}

// ============================================================================
// 6. COILED XLR MICROPHONE CABLE
// ============================================================================
// Helper to draw a realistic 3D rubber cable path with floor shadow, dark core,
// pastel ice-blue top highlight, and warm amber secondary bounce
function drawCableSegment(pts, thickness = 11, isOnFloor = true) {
  // 1. Cast shadow on stage floor
  if (isOnFloor) {
    const shadPts1 = pts.map(p => [p[0] + 8, p[1] + 11, p[2] || 1]);
    const shadPts2 = pts.map(p => [p[0] + 5, p[1] + 7, p[2] || 1]);
    setBrush("charcoal", "#12151e", thickness * 0.22);
    brush.spline(shadPts1, 0.5);
    setBrush("rotring", "#0b0d13", thickness * 0.28);
    brush.spline(shadPts2, 0.5);
  } else {
    // Subtle shadow on the stand shaft if hanging
    const shadPts = pts.map(p => [p[0] + 5, p[1] + 5, p[2] || 1]);
    setBrush("2B", "#141720", thickness * 0.16);
    brush.spline(shadPts, 0.5);
  }

  // 2. Main black rubber cable body (layered for smooth cylindrical profile)
  setBrush("rotring", "#101218", thickness * 0.36);
  brush.spline(pts, 0.5);

  const midPts = pts.map(p => [p[0] - 0.8, p[1] - 1.0, p[2] || 1]);
  setBrush("rotring", "#1d222d", thickness * 0.26);
  brush.spline(midPts, 0.5);

  // 3. Secondary warm amber bounce on the underside/rim-facing edge of the rubber cord
  const warmPts = pts.map(p => [p[0] + 1.8, p[1] + 1.8, p[2] || 0.8]);
  setBrush("fine_grain", "#6e5c50", thickness * 0.08);
  brush.spline(warmPts, 0.5);

  // 4. Primary cold pastel blue-white specular sheen along top-left ridge of the cable
  for (let i = 0; i < pts.length - 1; i++) {
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const xm = (p1[0] + p2[0]) * 0.5;
    const ym = (p1[1] + p2[1]) * 0.5;
    const specCol = getLightTint(xm, ym, "#b8cfe4", "#ebd4b9", "#8c7056");
    setBrush("fine_grain", specCol, thickness * 0.11);
    brush.line(p1[0] - 1.8, p1[1] - 2.0, p2[0] - 1.8, p2[1] - 2.0);

    // Brightest micro-glint on curves
    if (i % 2 === 0) {
      const glintCol = getLightTint(xm, ym, "#e6f2fc", "#f7e5ce", "#a8886a");
      setBrush("2H", glintCol, 0.55);
      brush.line(
        lerp(p1[0], p2[0], 0.25) - 2.0,
        lerp(p1[1], p2[1], 0.25) - 2.2,
        lerp(p1[0], p2[0], 0.75) - 2.0,
        lerp(p1[1], p2[1], 0.75) - 2.2
      );
    }
  }
}

