// ============================================================================
// 7. HEAVY CAST-IRON BASE & TELESCOPING CHROME STAND
// ============================================================================
function drawStandAndBase() {
  const bx = 700;
  const by = 915;
  const brx = 95;
  const bry = 51;

  // 7A. Heavy Cast-Iron Round Base
  // Bottom vertical skirt rim of the cast-iron disc
  brush.noStroke();
  brush.wash("#141720", 250);
  drawShapePoly(getEllipsePts(bx, by + 7, brx, bry, 64, -4), 0.06);

  // Domed upper surface of the cast-iron base
  brush.wash("#1e222e", 245);
  drawShapePoly(getEllipsePts(bx, by, brx, bry, 64, -4), 0.06);
  brush.noWash();

  // Radial pastel highlights & dark crinkle-coat iron texture on the dome
  // Left/upper-left side catches cold pastel blue-grey light from the hotspot
  for (let r = 0.2; r <= 0.96; r += 0.05) {
    const pts = [];
    for (let a = 145; a <= 315; a += 12) {
      const px = bx + cos(a) * brx * r;
      const py = by + sin(a) * bry * r - (1 - r) * 7;
      pts.push([px, py]);
    }
    const col = blendHex("#6c7e94", "#282e3c", map(Math.abs(r - 0.55), 0, 0.45, 0, 1));
    setBrush("pastel_shader", col, 0.75);
    brush.spline(pts, 0.4);
  }

  // Right/lower-right side of the base dome in deep shadow with warm amber rim reflection
  for (let r = 0.25; r <= 0.95; r += 0.06) {
    const pts = [];
    for (let a = -45; a <= 145; a += 12) {
      const px = bx + cos(a) * brx * r;
      const py = by + sin(a) * bry * r - (1 - r) * 7;
      pts.push([px, py]);
    }
    const col = r > 0.78 ? "#4a403c" : "#151822";
    setBrush("pastel_shader", col, 0.75);
    brush.spline(pts, 0.4);
  }

  // Cast-iron crinkle grain stipple & bare-metal boot scuffs around the base rim
  for (let i = 0; i < 120; i++) {
    const a = random(360);
    const rr = Math.sqrt(random()) * 0.95;
    const px = bx + cos(a) * brx * rr;
    const py = by + sin(a) * bry * rr - (1 - rr) * 6;
    const speckCol = (a > 150 && a < 310) ? "#92a6bc" : "#101218";
    setBrush("2H", speckCol, random(0.4, 0.8));
    brush.line(px, py, px + random(-2.5, 2.5), py + random(-1.5, 1.5));
  }

  // Chipped paint / scuffed bare steel marks along the outer bevel of the base
  for (let a = 120; a < 350; a += random(6, 16)) {
    const a2 = a + random(4, 11);
    const x1 = bx + cos(a) * brx * 0.98;
    const y1 = by + sin(a) * bry * 0.98;
    const x2 = bx + cos(a2) * brx * 0.98;
    const y2 = by + sin(a2) * bry * 0.98;
    const chipCol = a < 280 ? "#dceaf8" : "#ebd0b2";
    setBrush("fine_grain", chipCol, random(0.65, 1.2));
    brush.line(x1, y1, x2, y2);
  }

  // Outer dark rim contour under the base skirt
  setBrush("rotring", "#090b10", 1.5);
  brush.arc(bx, by + 6, brx * 0.98, 0, 180);

  // 7B. Machined Chrome Base Collar at center of dome (700, 906)
  const cx = 700, cy = 906;
  brush.noStroke();
  brush.wash("#222834", 255);
  drawShapePoly(getEllipsePts(cx, cy, 22, 12, 32, -4), 0.08);
  brush.wash("#cddff0", 230);
  drawShapePoly(getEllipsePts(cx - 5, cy - 2, 11, 6, 24, -4), 0.08);
  brush.noWash();
  setBrush("fine_grain", "#f4faff", 0.95);
  brush.arc(cx, cy - 2, 20, 170, 340);
  setBrush("rotring", "#10131c", 1.1);
  brush.arc(cx, cy + 2, 22, 0, 180);

  // 7C. Lower Chrome Shaft: from (700, 904) to Clutch at (670, 725)
  drawChromeCylinder(700, 904, 670, 725, 15.5);

  // 7D. Upper Cable Loop wrapping in front of the shaft near the clutch
  // and rising cleanly to the XLR plug at the bottom of the mic
  const riseUpper = [
    [682, 735, 1.0],
    [694, 682, 1.0],
    [672, 628, 1.0],
    [642, 594, 1.0],
    [645, 566, 1.0]
  ];
  drawCableSegment(riseUpper, 10.2, false);

  // 7E. Upper Slender Chrome Rod: from Clutch (670, 700) to Mic Yoke (642, 548)
  drawChromeCylinder(670, 700, 642, 548, 10.5);

  // 7F. Knurled Chrome & Black Twist-Action Clutch at (670, 725) -> (666, 698)
  drawChromeClutch(670, 726, 666, 698, 21);
}

// Helper: Hyperrealistic longitudinal chrome cylinder with cold pastel sky-white
// reflection, dark stage core, warm amber bounce stripe, and micro-scuffs
function drawChromeCylinder(x1, y1, x2, y2, diam) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy);
  const nx = -dy / len; // normal pointing right-up
  const ny = dx / len;
  const r = diam * 0.5;

  // Longitudinal reflection bands across cylinder diameter (-1 = left edge, +1 = right edge)
  const bands = [
    { off: -0.95, col: "#323c4d", w: 0.9 },
    { off: -0.78, col: "#b4cde4", w: 1.1 },
    { off: -0.55, col: "#f4faff", w: 1.4 }, // blinding cold white highlight
    { off: -0.32, col: "#cbe0f4", w: 1.1 },
    { off: -0.08, col: "#546278", w: 1.1 },
    { off: 0.18,  col: "#161a24", w: 1.5 }, // dark core reflection of the dark theatre
    { off: 0.45,  col: "#2c3240", w: 1.2 },
    { off: 0.72,  col: "#dfbe9b", w: 1.0 }, // warm pale amber bounce reflection
    { off: 0.94,  col: "#1b1e28", w: 0.9 }
  ];

  for (let b of bands) {
    const ox = nx * r * b.off;
    const oy = ny * r * b.off;
    setBrush("fine_grain", b.col, b.w);
    brush.line(x1 + ox, y1 + oy, x2 + ox, y2 + oy);
  }

  // Extra razor-sharp specular gleam along the -0.55 ridge
  const gx = nx * r * -0.55;
  const gy = ny * r * -0.55;
  setBrush("2H", "#ffffff", 0.75);
  brush.line(x1 + gx, y1 + gy, x2 + gx, y2 + gy);

  // Horizontal ring scuffs & wear marks on the chrome tube
  const numScuffs = Math.floor(len / 9);
  for (let i = 1; i < numScuffs; i++) {
    const t = (i + random(-0.3, 0.3)) / numScuffs;
    const sx = lerp(x1, x2, t);
    const sy = lerp(y1, y2, t);
    const scCol = random() < 0.6 ? "#e8f4fc" : "#222734";
    setBrush("2H", scCol, 0.45);
    brush.line(sx - nx * r * 0.7, sy - ny * r * 0.7, sx + nx * r * 0.5, sy + ny * r * 0.5);
  }
}

function drawChromeClutch(x1, y1, x2, y2, diam) {
  // Base chrome cylinder for the clutch
  drawChromeCylinder(x1, y1, x2, y2, diam);

  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy);
  const nx = -dy / len;
  const ny = dx / len;
  const r = diam * 0.5;

  // Knurled vertical ridges along the middle grip band of the clutch
  const mx1 = lerp(x1, x2, 0.22);
  const my1 = lerp(y1, y2, 0.22);
  const mx2 = lerp(x1, x2, 0.78);
  const my2 = lerp(y1, y2, 0.78);

  for (let f = -0.88; f <= 0.88; f += 0.22) {
    const ox = nx * r * f;
    const oy = ny * r * f;
    const knurlCol = f < -0.1 ? "#d8eaf8" : (f < 0.4 ? "#141720" : "#cfa882");
    setBrush("rotring", knurlCol, 0.65);
    brush.line(mx1 + ox, my1 + oy, mx2 + ox, my2 + oy);
  }

  // Top and bottom bevel rings of the clutch
  for (let t of [0.0, 0.22, 0.78, 1.0]) {
    const rx = lerp(x1, x2, t);
    const ry = lerp(y1, y2, t);
    setBrush("rotring", "#12151e", 0.85);
    brush.line(rx - nx * r, ry - ny * r, rx + nx * r, ry + ny * r);
    setBrush("fine_grain", "#f2f8ff", 0.65);
    brush.line(rx - nx * r * 0.85, ry - ny * r * 0.85 - 1, rx, ry - 1);
  }
}

// ============================================================================
// 8. SCUFFED VINTAGE MICROPHONE (SHURE 55 UNIDYNE / "ELVIS" BIRDCAGE)
// ============================================================================
function drawVintageMicrophone() {
  // 8A. Chrome XLR Plug Shell & Swivel Yoke Neck (from (642, 548) to (633, 520))
  // Angled XLR connector shell protruding down-right to (645, 566) where cable enters
  drawChromeCylinder(645, 566, 638, 538, 11.5);

  // Swivel yoke assembly & knurled thumb-screw on the left side at (626, 537)
  drawChromeCylinder(642, 548, 634, 522, 13);

  // Knurled thumbwheel on the side of the swivel mount
  setBrush("rotring", "#171b24", 1.2);
  brush.circle(625, 536, 7.5, 0.15);
  setBrush("fine_grain", "#e8f4fc", 0.9);
  brush.arc(625, 536, 7.2, 130, 310);
  setBrush("fine_grain", "#b2cae0", 0.6);
  brush.line(621, 533, 629, 539);
  brush.line(621, 536, 629, 536);

  // 8B. Main Vintage Ribbed Microphone Head
  // Center at (628, 474), tilted -9 degrees toward the upper-left follow-spot
  push();
  translate(628, 474);
  rotate(-9);

  const micW = 36; // half-width at widest point (total width 72px)
  const micH = 48; // half-height (total height 96px)

  // Helper for barrel width at normalized y in [-1, 1]
  function ribHalfWidth(yn) {
    // Classic tapered art-deco barrel shape: widest at yn = -0.15
    const profile = Math.sqrt(Math.max(0, 1 - Math.pow(yn * 0.92, 2)));
    const taper = yn > 0 ? 1 - yn * 0.22 : 1 - Math.abs(yn) * 0.08;
    return micW * profile * taper;
  }

  // 1. Outer silhouette pts of the microphone head
  const headPts = [];
  const steps = 48;
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    const yn = Math.sin(a);
    const hw = ribHalfWidth(yn);
    const x = Math.cos(a) * hw;
    const y = yn * micH;
    headPts.push([x, y]);
  }

  // 2. Dark recessed interior & pleated vintage pastel rose/amber silk windscreen
  brush.noStroke();
  brush.wash("#16141d", 250);
  drawShapePoly(headPts, 0.08);
  brush.noWash();

  // Vertical pleats of the inner vintage cloth windscreen (soft pastel dusty-rose,
  // warm peach-amber, and cool lavender-slate in shadow)
  for (let xf = -0.82; xf <= 0.82; xf += 0.11) {
    const x = xf * (micW - 5);
    const yMax = micH * Math.sqrt(Math.max(0, 1 - xf * xf)) * 0.88;
    if (yMax < 6) continue;

    let clothCol;
    if (xf < -0.15) {
      // Illuminated side of inner silk mesh: dusty pastel rose & warm coral-cream
      clothCol = blendHex("#dfb8be", "#b88692", map(xf, -0.82, -0.15, 0, 1));
    } else if (xf < 0.35) {
      // Mid-shadow pleated silk
      clothCol = "#5c4856";
    } else {
      // Right side catching warm amber bounce
      clothCol = "#785a58";
    }

    setBrush("cpencil", clothCol, 1.15);
    brush.line(x, -yMax, x, yMax);

    // Dark vertical shadow groove between cloth pleats
    setBrush("2H", "#1a1622", 0.65);
    brush.line(x + 2.2, -yMax, x + 2.2, yMax);
  }

  // Subtle horizontal mesh weave inside the silk screen
  for (let yf = -0.8; yf <= 0.8; yf += 0.14) {
    const y = yf * micH;
    const hw = ribHalfWidth(yf) - 5;
    setBrush("2H", "#2e2430", 0.45);
    brush.line(-hw, y, hw, y);
  }

  // 3. Outer Chrome Side Frame Rails (wrapping around left and right perimeter)
  const leftRail = [];
  const rightRail = [];
  for (let yn = -0.95; yn <= 0.95; yn += 0.12) {
    const hw = ribHalfWidth(yn);
    leftRail.push([-hw, yn * micH]);
    rightRail.push([hw, yn * micH]);
  }
  // Left side rail (blinding cold pastel blue-white highlight)
  setBrush("rotring", "#191e28", 2.2);
  brush.spline(leftRail, 0.4);
  setBrush("fine_grain", "#cce2f6", 1.5);
  brush.spline(leftRail.map(p => [p[0] + 1.5, p[1]]), 0.4);
  setBrush("2H", "#ffffff", 0.8);
  brush.spline(leftRail.map(p => [p[0] + 2.2, p[1]]), 0.4);

  // Right side rail (dark metallic shadow + warm pale amber rim reflection)
  setBrush("rotring", "#12151e", 2.2);
  brush.spline(rightRail, 0.4);
  setBrush("fine_grain", "#e2be98", 1.2);
  brush.spline(rightRail.map(p => [p[0] - 1.5, p[1]]), 0.4);

  // 4. Seven Iconic Curved Horizontal Chrome Ribs wrapping across the front of the cage
  const ribYNorms = [-0.82, -0.58, -0.33, -0.07, 0.19, 0.45, 0.71];
  for (let idx = 0; idx < ribYNorms.length; idx++) {
    const yn = ribYNorms[idx];
    const hw = ribHalfWidth(yn);
    const yBase = yn * micH;
    // Perspective arch of each rib (curving upward slightly across the barrel front)
    const archH = -7.5 * (1 - yn * 0.25);

    const ribPts = [];
    const shadowPts = [];
    const topGlintPts = [];
    const botAmberPts = [];

    for (let s = 0; s <= 12; s++) {
      const xf = map(s, 0, 12, -1, 1);
      const x = xf * hw;
      const curveY = yBase + archH * (1 - xf * xf);
      ribPts.push([x, curveY]);
      shadowPts.push([x, curveY + 3.2]);
      topGlintPts.push([x, curveY - 1.5]);
      botAmberPts.push([x, curveY + 1.6]);
    }

    // Drop shadow cast by rib onto the inner silk cloth
    setBrush("rotring", "#0c0a12", 1.9);
    brush.spline(shadowPts, 0.45);

    // Dark metallic core of the chrome rib
    setBrush("rotring", "#202634", 2.1);
    brush.spline(ribPts, 0.45);

    // Warm pale amber underside reflection from the lit stage floorboards
    setBrush("fine_grain", "#dfb992", 0.85);
    brush.spline(botAmberPts, 0.45);

    // Cold pastel sky-blue & pure white upper bevel highlight on the rib
    // Left two-thirds of the rib are brightly lit by the spotlight
    setBrush("fine_grain", "#c6def4", 1.25);
    brush.spline(topGlintPts.slice(0, 9), 0.45);

    setBrush("2H", "#ffffff", 0.85);
    brush.spline(topGlintPts.slice(1, 7), 0.45);

    // Right third of the rib transitions into cool slate and amber rim glint
    setBrush("fine_grain", "#68788e", 0.95);
    brush.spline(topGlintPts.slice(7, 13), 0.45);

    // Scuff marks & tiny dark tarnish pits on the vintage chrome ribs
    const scX = random(-hw * 0.6, hw * 0.4);
    const scY = yBase + archH * (1 - Math.pow(scX / hw, 2));
    setBrush("2H", "#14161e", 0.6);
    brush.line(scX - 2, scY - 1, scX + 2, scY + 1.5);
  }

  // Crown cap at top of microphone cage (yn = -0.96 .. -0.82)
  setBrush("fine_grain", "#eef7ff", 1.6);
  brush.arc(0, -micH * 0.72, micW * 0.65, 200, 340);
  setBrush("2H", "#ffffff", 0.9);
  brush.arc(-3, -micH * 0.74, micW * 0.55, 210, 315);

  // Lower chin bowl of the microphone cage (yn = 0.72 .. 1.0)
  setBrush("rotring", "#1a202c", 2.0);
  brush.arc(0, micH * 0.62, micW * 0.68, 20, 160);
  setBrush("fine_grain", "#e8c49e", 1.1);
  brush.arc(0, micH * 0.64, micW * 0.65, 35, 145);

  // 5. Central Vertical Chrome Spine & ON/OFF Switch Plate
  // Runs vertically from crown (-micH + 3) to bottom (+micH - 2)
  setBrush("rotring", "#161a24", 3.2);
  brush.line(0, -micH + 3, 0, micH - 2);

  setBrush("fine_grain", "#d4e8f8", 1.8);
  brush.line(-1.8, -micH + 4, -1.8, micH - 3);

  setBrush("2H", "#ffffff", 0.9);
  brush.line(-2.2, -micH + 6, -2.2, 6);

  setBrush("fine_grain", "#e2be98", 1.0);
  brush.line(2.0, -micH + 6, 2.0, micH - 4);

  // Rectangular ON/OFF switch plate on lower half of central spine (y = 8 to 38)
  const swPts = [
    [-7.5, 8],
    [7.5, 8],
    [6.8, 38],
    [-6.8, 38]
  ];
  brush.noStroke();
  brush.wash("#1e2330", 250);
  drawShapePoly(swPts, 0.04);

  // Inner dark maroon/black vintage badge plate
  const badgePts = [
    [-4.8, 12],
    [4.8, 12],
    [4.4, 34],
    [-4.4, 34]
  ];
  brush.wash("#26151c", 250);
  drawShapePoly(badgePts, 0.03);
  brush.noWash();

  // Chrome frame bevel around the switch plate
  setBrush("fine_grain", "#f0f8ff", 0.9);
  brush.line(-7.5, 8, 7.5, 8);
  brush.line(-7.5, 8, -6.8, 38);
  setBrush("fine_grain", "#dfb890", 0.75);
  brush.line(7.5, 8, 6.8, 38);
  brush.line(-6.8, 38, 6.8, 38);

  // Tiny vintage pastel coral-red "ON" indicator dot and metallic toggle switch
  setBrush("rotring", "#eb8a84", 1.15);
  brush.line(-2, 16, 2, 16);

  // Protruding metallic switch button at (0, 24)
  setBrush("rotring", "#0c0e14", 1.6);
  brush.line(-3.2, 26, 3.2, 26); // switch shadow
  setBrush("fine_grain", "#f4faff", 1.35);
  brush.line(-3.0, 23.5, 2.5, 23.5);

  // Specular star-glints on the upper-left rib knuckles of the vintage mic
  const glintCoords = [
    [-19, -29],
    [-23, -16],
    [-24, -2],
    [-2, -36]
  ];
  for (let g of glintCoords) {
    setBrush("2H", "#ffffff", 0.85);
    brush.line(g[0] - 4.5, g[1], g[0] + 4.5, g[1]);
    brush.line(g[0], g[1] - 4.5, g[0], g[1] + 4.5);
  }

  pop();
}

// ============================================================================
// 9. ATMOSPHERIC HAZE (SOFT SPRAY) & DUST MOTES IN THE BEAM
// ============================================================================
function drawBeamHazeAndDust() {
  // 9A. Faint diagonal follow-spot haze rendered by soft spray inside the circle
  // Beam angle flows from upper-left of the circle (~500, 440) down-right across the mic and floor
  const hazePasses = 38;
  for (let i = 0; i < hazePasses; i++) {
    const t = i / hazePasses;
    const hx1 = lerp(440, 560, t) + random(-25, 25);
    const hy1 = lerp(490, 420, t) + random(-20, 20);
    const hx2 = lerp(690, 960, t) + random(-35, 35);
    const hy2 = lerp(980, 860, t) + random(-30, 30);

    const clipped = clipLineToSpot(hx1, hy1, hx2, hy2, 0.90);
    if (!clipped) continue;

    const xm = (clipped[0] + clipped[2]) * 0.5;
    const ym = (clipped[1] + clipped[3]) * 0.5;
    const hazeCol = getLightTint(xm, ym, "#dcecf8", "#f2d2ad", "#9e7b58");

    setBrush("beam_haze", hazeCol, random(0.65, 1.35));
    brush.line(clipped[0], clipped[1], clipped[2], clipped[3]);
  }

  // Additional fine built-in "spray" pass around the microphone head and upper beam
  for (let i = 0; i < 24; i++) {
    const sx = 630 + random(-140, 150);
    const sy = 560 + random(-120, 180);
    const ex = sx + random(40, 110);
    const ey = sy + random(50, 120);
    if (inSpot(sx, sy, 0.88) && inSpot(ex, ey, 0.88)) {
      const spCol = getLightTint(sx, sy, "#e6f2fc", "#f5d8b5", "#a88460");
      setBrush("spray", spCol, random(0.45, 0.9));
      brush.line(sx, sy, ex, ey);
    }
  }

  // 9B. Floating dust motes caught in the follow-spot beam
  // Soft out-of-focus bokeh dust circles
  brush.noStroke();
  for (let i = 0; i < 32; i++) {
    const a = random(360);
    const rr = Math.pow(random(), 0.7) * 0.88;
    const dx = SPOT_X + cos(a) * SPOT_RX * rr;
    const dy = SPOT_Y + sin(a) * SPOT_RY * rr;
    const rMote = random(2.2, 5.2);
    const moteCol = getLightTint(dx, dy, "#e8f4fc", "#f5d5b0", "#b8926a");
    brush.wash(moteCol, random(28, 68));
    drawShapePoly(getEllipsePts(dx, dy, rMote, rMote, 14), 0.1);
  }
  brush.noWash();

  // Crisp sparkling micro-dust specs suspended in the beam (especially dense around the mic & hotspot)
  for (let i = 0; i < 210; i++) {
    const a = random(360);
    const rr = Math.pow(random(), 0.62) * 0.94;
    const dx = SPOT_X + cos(a) * SPOT_RX * rr;
    const dy = SPOT_Y + sin(a) * SPOT_RY * rr;

    const dCol = getLightTint(dx, dy, "#f2f9ff", "#fae0be", "#c49b72");
    const w = random(0.45, 1.15);
    setBrush(random() < 0.6 ? "2H" : "fine_grain", dCol, w);
    brush.line(dx, dy, dx + random(-1.4, 1.4), dy + random(-1.4, 1.4));
  }
}

// ============================================================================
// 10. HARD-EDGED RIM & DENSE VELVETY CHARCOAL BLACK SURROUND
// ============================================================================
function drawVelvetCharcoalSurround() {
  // 10A. Precision optical pale-amber rim accent right inside the follow-spot edge
  const rimPtsCount = 120;
  for (let i = 0; i < rimPtsCount; i++) {
    const a1 = (i / rimPtsCount) * 360;
    const a2 = ((i + 1.2) / rimPtsCount) * 360;

    // Inner pale amber glow (r = 0.968)
    setBrush("fine_grain", "#ecc496", 0.95);
    brush.line(
      SPOT_X + SPOT_RX * 0.968 * cos(a1),
      SPOT_Y + SPOT_RY * 0.968 * sin(a1),
      SPOT_X + SPOT_RX * 0.968 * cos(a2),
      SPOT_Y + SPOT_RY * 0.968 * sin(a2)
    );

    // Outer warm burnt-amber iris falloff (r = 0.988)
    setBrush("pastel_shader", "#785336", 0.85);
    brush.line(
      SPOT_X + SPOT_RX * 0.988 * cos(a1),
      SPOT_Y + SPOT_RY * 0.988 * sin(a1),
      SPOT_X + SPOT_RX * 0.988 * cos(a2),
      SPOT_Y + SPOT_RY * 0.988 * sin(a2)
    );
  }

  // 10B. Hard-edged outer mask in 4 overlapping quadrants so EVERYTHING outside
  // the spotlight circle is pure, dense charcoal black with zero stray spray bleed
  brush.noStroke();
  const outerR = 1.002;
  const ringSteps = 96;
  const outerCorners = [
    [-40, -40],
    [1240, -40],
    [1240, 1240],
    [-40, 1240]
  ];

  // Build 4 quadrant mask polygons between the spotlight ellipse and the canvas boundary
  for (let q = 0; q < 4; q++) {
    const aStart = q * 90;
    const aEnd = (q + 1) * 90;
    const poly = [];

    for (let s = 0; s <= ringSteps / 4; s++) {
      const a = map(s, 0, ringSteps / 4, aStart, aEnd);
      poly.push([
        SPOT_X + SPOT_RX * outerR * cos(a),
        SPOT_Y + SPOT_RY * outerR * sin(a)
      ]);
    }

    // Add corresponding outer canvas boundary points
    if (q === 0) {
      poly.push([SPOT_X, 1240], [1240, 1240], [1240, SPOT_Y]);
    } else if (q === 1) {
      poly.push([-40, SPOT_Y], [-40, 1240], [SPOT_X, 1240]);
    } else if (q === 2) {
      poly.push([SPOT_X, -40], [-40, -40], [-40, SPOT_Y]);
    } else {
      poly.push([1240, SPOT_Y], [1240, -40], [SPOT_X, -40]);
    }

    brush.wash("#09090d", 255);
    drawShapePoly(poly, 0);
  }
  brush.noWash();

  // 10C. Crisp charcoal-black iris rim line at r = 1.003
  for (let i = 0; i < rimPtsCount; i++) {
    const a1 = (i / rimPtsCount) * 360;
    const a2 = ((i + 1.3) / rimPtsCount) * 360;
    setBrush("charcoal", "#09090d", 2.2);
    brush.line(
      SPOT_X + SPOT_RX * 1.006 * cos(a1),
      SPOT_Y + SPOT_RY * 1.006 * sin(a1),
      SPOT_X + SPOT_RX * 1.006 * cos(a2),
      SPOT_Y + SPOT_RY * 1.006 * sin(a2)
    );
  }

  // 10D. Rich, tactile velvety charcoal strokes across the vast dark surround
  // so the darkness feels like dense, hand-rubbed velvety charcoal rather than flat digital black
  const velvetCols = ["#07070b", "#0b0b10", "#0f0e15", "#121118", "#08080c"];
  for (let i = 0; i < 420; i++) {
    const x = random(20, 1180);
    const y = random(20, 1180);
    const r = spotRadius(x, y);
    if (r < 1.09) continue;

    const len = random(45, 140);
    const ang = atan2(y - SPOT_Y, x - SPOT_X) + 90 + random(-25, 25);
    const x2 = x + cos(ang) * len;
    const y2 = y + sin(ang) * len;
    if (spotRadius(x2, y2) < 1.09) continue;

    const vCol = random(velvetCols);
    setBrush(random() < 0.65 ? "velvet_dark" : "charcoal", vCol, random(0.8, 1.8));
    brush.line(x, y, x2, y2);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.noClip();

  // =========================================================================
  // 1. ARCHIVAL PALE GRAPH PAPER GROUND & COOL WINDOW LIGHT WASH
  // =========================================================================
  background("#f3ede1");

  // Subtle large atmospheric lighting washes across the drafting sheet:
  // Cool sky-window daylight entering from upper-left, warm ambient shadow lower-right
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.15);

  brush.fill("#e2ecf0", 48);
  brush.rect(-40, -40, 760, 720, "corner");

  brush.fill("#e7eff2", 36);
  brush.rect(20, 20, 520, 500, "corner");

  brush.fill("#e5dac6", 46);
  brush.rect(420, 440, 820, 800, "corner");

  brush.fill("#dccdb4", 38);
  brush.rect(640, 660, 600, 580, "corner");
  brush.noFill();

  // Fine archival paper grain across the background
  brush.set("2H", "#dfd6c5", 0.35);
  for (let i = 0; i < 220; i++) {
    let gx = random(30, 1170);
    let gy = random(30, 1170);
    let len = random(18, 55);
    let ang = random(-8, 8);
    brush.line(gx, gy, gx + cos(ang) * len, gy + sin(ang) * len);
  }

  // =========================================================================
  // 2. PRECISION GRAPH PAPER GRID & MARGIN CALIBRATIONS
  // =========================================================================
  const margin = 60;
  const gLeft = margin;
  const gTop = margin;
  const gRight = width - margin;
  const gBottom = height - margin;
  const stepMinor = 18; // 90px medium (5 divs), 180px major (10 divs)

  // Minor grid lines (every 18px)
  brush.set("2H", "#dcd5c7", 0.28);
  for (let x = gLeft; x <= gRight; x += stepMinor) {
    if (Math.round((x - gLeft) / stepMinor) % 5 !== 0) {
      brush.line(x, gTop, x, gBottom);
    }
  }
  for (let y = gTop; y <= gBottom; y += stepMinor) {
    if (Math.round((y - gTop) / stepMinor) % 5 !== 0) {
      brush.line(gLeft, y, gRight, y);
    }
  }

  // Medium grid lines (every 90px)
  brush.set("2H", "#c6beb0", 0.36);
  for (let x = gLeft; x <= gRight; x += stepMinor * 5) {
    if (Math.round((x - gLeft) / stepMinor) % 10 !== 0) {
      brush.line(x, gTop, x, gBottom);
    }
  }
  for (let y = gTop; y <= gBottom; y += stepMinor * 5) {
    if (Math.round((y - gTop) / stepMinor) % 10 !== 0) {
      brush.line(gLeft, y, gRight, y);
    }
  }

  // Major grid lines (every 180px)
  brush.set("rotring", "#b2a999", 0.32);
  for (let x = gLeft; x <= gRight; x += stepMinor * 10) {
    brush.line(x, gTop - 8, x, gBottom + 8);
  }
  for (let y = gTop; y <= gBottom; y += stepMinor * 10) {
    brush.line(gLeft - 8, y, gRight + 8, y);
  }

  // Outer technical border frame & calibration ticks
  brush.set("rotring", "#8c8273", 0.42);
  brush.noFill();
  brush.rect(gLeft, gTop, gRight - gLeft, gBottom - gTop, "corner");

  // Fine millimeter ticks along top and left borders
  brush.set("rotring", "#9a8f7f", 0.28);
  for (let x = gLeft; x <= gRight; x += stepMinor) {
    let isMaj = Math.round((x - gLeft) / stepMinor) % 5 === 0;
    brush.line(x, gTop, x, gTop - (isMaj ? 6 : 3));
    brush.line(x, gBottom, x, gBottom + (isMaj ? 6 : 3));
  }
  for (let y = gTop; y <= gBottom; y += stepMinor) {
    let isMaj = Math.round((y - gTop) / stepMinor) % 5 === 0;
    brush.line(gLeft, y, gLeft - (isMaj ? 6 : 3), y);
    brush.line(gRight, y, gRight + (isMaj ? 6 : 3), y);
  }

  // =========================================================================
  // 3. ORIGAMI TSURU (CRANE) GEOMETRY & 3D RELIEF MESH CONSTRUCTION
  // =========================================================================
  const cx = 578;
  const cy = 622;
  const S = 392; // Half-side length of the square sheet (~784x784 px)
  const rotDeg = -11.5; // Analytical tilt on the graph paper

  const k = 2 - Math.sqrt(2); // ~0.585786 (22.5 deg Bird Base diamond constant)
  const h = k * 0.5;          // ~0.292893 (diagonal intersection)
  const q = 0.788;            // 11.25 deg narrowing midline constant

  const V = {};

  function tableCoords(u, v) {
    let rx = (u * cos(rotDeg) - v * sin(rotDeg)) * S;
    let ry = (u * sin(rotDeg) + v * cos(rotDeg)) * S;
    return { tx: cx + rx, ty: cy + ry };
  }

  function addV(id, u, v, z, pullU = 0, pullV = 0) {
    // Residual crease contraction pulls vertices slightly toward center
    let shrink = 1.0 - 0.00055 * z;
    let eu = u * shrink + pullU;
    let ev = v * shrink + pullV;
    let tc = tableCoords(eu, ev);
    let fl = tableCoords(u, v);
    // 3D oblique relief shift (camera slightly below-right looking down, light from top-left)
    let x = tc.tx - 0.24 * z;
    let y = tc.ty - 0.40 * z;
    // Shadow cast onto the flat graph paper (z = 0) toward bottom-right
    let sx = tc.tx + 0.78 * z;
    let sy = tc.ty + 0.64 * z;
    V[id] = {
      id, u, v, z,
      tx: tc.tx, ty: tc.ty,
      fx: fl.tx, fy: fl.ty,
      x, y, sx, sy
    };
    return V[id];
  }

  function addV3D(id, u, v, z) {
    let tc = tableCoords(u, v);
    let x = tc.tx - 0.24 * z;
    let y = tc.ty - 0.40 * z;
    let sx = tc.tx + 0.78 * z;
    let sy = tc.ty + 0.64 * z;
    V[id] = { id, u, v, z, tx: tc.tx, ty: tc.ty, fx: tc.tx, fy: tc.ty, x, y, sx, sy };
    return V[id];
  }

  // --- A. CENTRAL BACK DIAMOND & INFLATED BOX PLATEAU ---
  addV("O", 0, 0, 38);

  // Inner box-memory ring around the central peak
  addV("I_T",  0, -0.20, 31);
  addV("I_TR", 0.14, -0.14, 26);
  addV("I_R",  0.20, 0, 31);
  addV("I_BR", 0.14, 0.14, 35);
  addV("I_B",  0, 0.20, 30);
  addV("I_BL", -0.14, 0.14, 25);
  addV("I_L",  -0.20, 0, 30);
  addV("I_TL", -0.14, -0.14, 34);

  // Bird Base Central Diamond vertices
  addV("D_T",  0, -k, 15);
  addV("M_TR", h, -h, 11);
  addV("D_R",  k, 0, 16);
  addV("M_BR", h, h, 28);
  addV("D_B",  0, k, 14);
  addV("M_BL", -h, h, 10);
  addV("D_L",  -k, 0, 13);
  addV("M_TL", -h, -h, 24);

  // Midpoints on neck/tail diamond edges where 11.25-deg narrowing creases terminate
  addV("K_TR_T", h * 0.5, -(k + h) * 0.5, 19);
  addV("K_TR_R", (k + h) * 0.5, -h * 0.5, 20);
  addV("K_BL_L", -(k + h) * 0.5, h * 0.5, 17);
  addV("K_BL_B", -h * 0.5, (k + h) * 0.5, 18);

  // Midline narrowing vertices & outer edge midpoints
  addV("N_T", 0, -q, 9);
  addV("E_T", 0, -1, 5, 0, 0.025);

  addV("N_R", q, 0, 11);
  addV("E_R", 1, 0, 6, -0.028, 0);

  addV("N_B", 0, q, 9);
  addV("E_B", 0, 1, 5, 0, -0.028);

  addV("N_L", -q, 0, 8);
  addV("E_L", -1, 0, 4, 0.022, 0);

  // --- B. TOP-LEFT QUADRANT: LEFT WING (Unfolded with ghost camber folds) ---
  const tW1 = 0.37;
  const tW2 = 0.70;
  addV("ET_TL1", -tW1, -1, 11, 0.01, 0.022);
  addV("ET_TL2", -tW2, -1, 8, 0.015, 0.020);
  addV("P_TL_T1", -tW1, -k + (-1 + k) * tW1, 9);
  addV("P_TL_T2", -tW2, -k + (-1 + k) * tW2, 6);
  addV("W_TL1", -(h + (1 - h) * tW1), -(h + (1 - h) * tW1), 21);
  addV("W_TL2", -(h + (1 - h) * tW2), -(h + (1 - h) * tW2), 14);
  addV("P_TL_L1", -k + (-1 + k) * tW1, -tW1, 8);
  addV("P_TL_L2", -k + (-1 + k) * tW2, -tW2, 5);
  addV("EL_TL1", -1, -tW1, 10, 0.022, 0.01);
  addV("EL_TL2", -1, -tW2, 7, 0.020, 0.015);
  addV("C_TL", -1, -1, 7, 0.022, 0.022);

  // --- C. BOTTOM-RIGHT QUADRANT: RIGHT WING (Unfolded with higher spring arch) ---
  addV("ER_BR1", 1, tW1, 15, -0.028, -0.01);
  addV("ER_BR2", 1, tW2, 16, -0.032, -0.015);
  addV("P_BR_R1", k + (1 - k) * tW1, tW1, 12);
  addV("P_BR_R2", k + (1 - k) * tW2, tW2, 10);
  addV("W_BR1", h + (1 - h) * tW1, h + (1 - h) * tW1, 29);
  addV("W_BR2", h + (1 - h) * tW2, h + (1 - h) * tW2, 23);
  addV("P_BR_B1", tW1, k + (1 - k) * tW1, 11);
  addV("P_BR_B2", tW2, k + (1 - k) * tW2, 9);
  addV("EB_BR1", tW1, 1, 14, -0.01, -0.028);
  addV("EB_BR2", tW2, 1, 15, -0.015, -0.032);
  addV("C_BR", 1, 1, 13, -0.035, -0.035);

  // --- D. BOTTOM-LEFT QUADRANT: THE TAIL (Unfolded 80%, curled narrowing flap) ---
  // 9 rays converging from base [E_L, N_L, D_L, K_BL_L, M_BL, K_BL_B, D_B, N_B, E_B] to C_BL(-1, 1)
  const blBase = ["E_L", "N_L", "D_L", "K_BL_L", "M_BL", "K_BL_B", "D_B", "N_B", "E_B"];
  // Zigzag inside-reverse fold parameters across the 9 accordion rays
  const blT1 = [0.34, 0.41, 0.33, 0.42, 0.34, 0.42, 0.33, 0.41, 0.34];
  const blT2 = [0.67, 0.74, 0.66, 0.75, 0.67, 0.75, 0.66, 0.74, 0.67];
  const blZ1 = [5, 18, 7, 22, 8, 24, 10, 29, 24];
  const blZ2 = [4, 15, 6, 19, 7, 22, 9, 33, 39];
  // Notice rays 7 and 8 curl upward and inward strongly where the tail flap refuses to flatten!
  const blPull1 = [
    [0.02, 0], [0.015, 0], [0.01, 0], [0.01, -0.01], [0, 0],
    [-0.01, -0.01], [-0.01, -0.015], [-0.055, -0.075], [-0.115, -0.135]
  ];
  const blPull2 = [
    [0.02, 0], [0.015, 0], [0.01, 0], [0.01, -0.01], [0, 0],
    [-0.01, -0.01], [-0.015, -0.02], [-0.075, -0.095], [-0.155, -0.180]
  ];

  for (let i = 0; i < 9; i++) {
    let b = V[blBase[i]];
    let u1 = b.u + (-1 - b.u) * blT1[i];
    let v1 = b.v + (1 - b.v) * blT1[i];
    addV("BL_1_" + i, u1, v1, blZ1[i], blPull1[i][0], blPull1[i][1]);

    let u2 = b.u + (-1 - b.u) * blT2[i];
    let v2 = b.v + (1 - b.v) * blT2[i];
    addV("BL_2_" + i, u2, v2, blZ2[i], blPull2[i][0], blPull2[i][1]);
  }
  addV("C_BL", -1, 1, 14, 0.035, -0.045);

  // --- E. TOP-RIGHT QUADRANT: NECK & HEAD (Half-unfolded base + 3D folded Neck & Beak!) ---
  const trBase = ["E_T", "N_T", "D_T", "K_TR_T", "M_TR", "K_TR_R", "D_R", "N_R", "E_R"];
  const trT1 = [0.35, 0.42, 0.34, 0.44, 0.35, 0.44, 0.34, 0.42, 0.35];
  const trZ1 = [12, 23, 14, 27, 16, 28, 15, 24, 13];
  const trPull1 = [
    [-0.02, 0.03], [-0.015, 0.02], [-0.01, 0.01], [-0.01, 0.01], [0, 0],
    [-0.01, 0.01], [-0.01, 0.01], [-0.02, 0.015], [-0.03, 0.02]
  ];
  for (let i = 0; i < 9; i++) {
    let b = V[trBase[i]];
    let u1 = b.u + (1 - b.u) * trT1[i];
    let v1 = b.v + (-1 - b.v) * trT1[i];
    addV("TR_1_" + i, u1, v1, trZ1[i], trPull1[i][0], trPull1[i][1]);
  }

  // Outer side flaps of TR folding inward & upward into the neck base
  addV3D("TR_FLAP_T", 0.48, -0.83, 34);
  addV3D("TR_FLAP_R", 0.83, -0.48, 32);

  // 3D Folded Neck shaft vertices (rising from the reverse fold chevron up to the head crimp)
  addV3D("NK_L_MID", 0.59, -0.76, 45);
  addV3D("NK_C_MID", 0.65, -0.68, 36);
  addV3D("NK_R_MID", 0.76, -0.59, 43);

  // Head Crimp Crown (where the neck reverse-folds into the head/beak)
  addV3D("HD_CROWN_L", 0.66, -0.89, 58);
  addV3D("HD_CROWN_C", 0.75, -0.84, 52);
  addV3D("HD_CROWN_R", 0.82, -0.75, 55);

  // Lower jaw / throat crease of the head crimp
  addV3D("HD_JAW_L", 0.56, -0.79, 46);
  addV3D("HD_JAW_R", 0.67, -0.73, 44);

  // Pointed Beak Tip & inner reverse-fold ridge
  addV3D("BEAK_RIDGE", 0.53, -0.86, 51);
  addV3D("BEAK_TIP",   0.39, -0.81, 43);

  // Reference ghost-projection vertices on the flat graph paper for the unfolded TR corner
  const flatTR = {
    C_TR: tableCoords(1, -1),
    E_T:  tableCoords(0, -1),
    N_T:  tableCoords(0, -q),
    D_T:  tableCoords(0, -k),
    M_TR: tableCoords(h, -h),
    D_R:  tableCoords(k, 0),
    N_R:  tableCoords(q, 0),
    E_R:  tableCoords(1, 0),
    K_T:  tableCoords(h * 0.5, -(k + h) * 0.5),
    K_R:  tableCoords((k + h) * 0.5, -h * 0.5)
  };

  // =========================================================================
  // 4. FACET LIST & EDGE CLASSIFICATION (M, V, M2, V2, G, B)
  // =========================================================================
  const facets = [];
  const edgesMap = new Map();

  function addFacet(v0, v1, v2, group = "main", isUnderside = false) {
    let A = V[v0], B = V[v1], C = V[v2];
    let zAvg = (A.z + B.z + C.z) / 3;
    // Order boost ensures 3D folded neck & head layers render strictly above base facets
    let sortKey = zAvg + (group === "neck" ? 50 : group === "head" ? 95 : group === "tailCurl" ? 25 : 0);
    facets.push({ v0, v1, v2, A, B, C, zAvg, sortKey, group, isUnderside });
  }

  function setEdge(vA, vB, type, layer = 0) {
    let key = vA < vB ? vA + "|" + vB : vB + "|" + vA;
    edgesMap.set(key, { vA, vB, A: V[vA], B: V[vB], type, layer });
  }

  // --- 4A. Central Back Diamond Facets ---
  const ringI = ["I_T", "I_TR", "I_R", "I_BR", "I_B", "I_BL", "I_L", "I_TL"];
  for (let i = 0; i < 8; i++) {
    let nxt = (i + 1) % 8;
    addFacet("O", ringI[i], ringI[nxt], "center");
    setEdge("O", ringI[i], i % 2 === 1 ? (i === 1 || i === 5 ? "V" : "M") : "M2");
    setEdge(ringI[i], ringI[nxt], "G"); // Soft box-inflation memory ring
  }

  // Outer Central Diamond facets (watertight with K_TR and K_BL vertices)
  // Top-Left octant of center
  addFacet("I_T", "D_T", "M_TL", "center");
  addFacet("I_T", "M_TL", "I_TL", "center");
  addFacet("I_TL", "M_TL", "D_L", "center");
  addFacet("I_TL", "D_L", "I_L", "center");

  // Bottom-Right octant of center
  addFacet("I_R", "D_R", "M_BR", "center");
