  // =========================================================================
  // 5. ANALYTICAL PROJECTION LINES ON GRAPH PAPER (UNDER TOP-RIGHT CORNER)
  // =========================================================================
  function drawDashedLine(x1, y1, x2, y2, dashLen, gapLen, dotInGap = false) {
    let dx = x2 - x1, dy = y2 - y1;
    let dist = Math.hypot(dx, dy);
    if (dist < 1) return;
    let ux = dx / dist, uy = dy / dist;
    let pos = 0;
    while (pos < dist) {
      let endPos = Math.min(pos + dashLen, dist);
      brush.line(x1 + ux * pos, y1 + uy * pos, x1 + ux * endPos, y1 + uy * endPos);
      if (dotInGap && pos + dashLen + gapLen * 0.5 < dist) {
        let mPos = pos + dashLen + gapLen * 0.42;
        let mEnd = Math.min(mPos + 1.8, dist);
        brush.line(x1 + ux * mPos, y1 + uy * mPos, x1 + ux * mEnd, y1 + uy * mEnd);
      }
      pos += dashLen + gapLen;
    }
  }

  // Faint construction lines on the graph paper where the unfolded TR corner originates
  brush.set("rotring", "#8d7c68", 0.30);
  drawDashedLine(flatTR.E_T.tx, flatTR.E_T.ty, flatTR.C_TR.tx, flatTR.C_TR.ty, 7, 5, false);
  drawDashedLine(flatTR.E_R.tx, flatTR.E_R.ty, flatTR.C_TR.tx, flatTR.C_TR.ty, 7, 5, false);
  drawDashedLine(flatTR.M_TR.tx, flatTR.M_TR.ty, flatTR.C_TR.tx, flatTR.C_TR.ty, 10, 6, true);

  brush.set("rotring", "#a46a49", 0.26);
