  drawDashedLine(flatTR.D_R.tx, flatTR.D_R.ty, flatTR.C_TR.tx, flatTR.C_TR.ty, 5, 5, false);
  drawDashedLine(flatTR.N_T.tx, flatTR.N_T.ty, flatTR.C_TR.tx, flatTR.C_TR.ty, 3, 5, false);
