  brush.set("rotring", "#9b5e3e", 0.28);
  let arcPts = [];
  for (let t = 0; t <= 1.001; t += 0.1) {
    let ax = lerp(ctrx, beakV.x, t) - Math.sin(t * Math.PI) * 38;
    let ay = lerp(ctry, beakV.y, t) - Math.sin(t * Math.PI) * 52;
