  // =========================================================================
  // 6. CAST SHADOW OF THE LIFTED WASHI ONTO THE GRAPH PAPER
  // =========================================================================
  // Sort facets by sortKey (back-to-front painter's order)
  facets.sort((a, b) => a.sortKey - b.sortKey);

  // Helper to clip parallel hatch lines inside a triangle
  function hatchTriangle(p0, p1, p2, angleDeg, spacing, jitter = 0) {
    let rad = angleDeg * Math.PI / 180;
    let nx = -Math.sin(rad), ny = Math.cos(rad);
    let tx = Math.cos(rad), ty = Math.sin(rad);

    let d0 = p0.x * nx + p0.y * ny;
    let d1 = p1.x * nx + p1.y * ny;
    let d2 = p2.x * nx + p2.y * ny;
    let dMin = Math.min(d0, d1, d2);
    let dMax = Math.max(d0, d1, d2);

    let tri = [p0, p1, p2];
    let lines = [];
    for (let d = dMin + spacing * 0.45; d < dMax; d += spacing) {
      let hits = [];
      for (let e = 0; e < 3; e++) {
        let a = tri[e], b = tri[(e + 1) % 3];
        let da = a.x * nx + a.y * ny;
        let db = b.x * nx + b.y * ny;
        if ((da <= d && db > d) || (db <= d && da > d)) {
          let t = (d - da) / (db - da);
          hits.push({
            x: a.x + (b.x - a.x) * t,
            y: a.y + (b.y - a.y) * t
          });
        }
      }
      if (hits.length === 2) {
        let len = Math.hypot(hits[1].x - hits[0].x, hits[1].y - hits[0].y);
        if (len > 2.2) {
          let j = jitter ? (random(-jitter, jitter)) : 0;
          lines.push([
            hits[0].x + tx * j, hits[0].y + ty * j,
            hits[1].x - tx * j, hits[1].y - ty * j
          ]);
        }
      }
    }
    return lines;
  }

  // Render cast shadows on the graph paper
  // Layer 1: Soft outer penumbra
  brush.noStroke();
  for (let f of facets) {
    let p0 = { x: f.A.sx + 5, y: f.A.sy + 5 };
    let p1 = { x: f.B.sx + 5, y: f.B.sy + 5 };
    let p2 = { x: f.C.sx + 5, y: f.C.sy + 5 };
    brush.wash("#cfc2ae", 52);
    brush.beginShape(0);
    brush.vertex(p0.x, p0.y);
    brush.vertex(p1.x, p1.y);
    brush.vertex(p2.x, p2.y);
    brush.endShape(true);
  }
  // Layer 2: Core cast shadow umbra
  for (let f of facets) {
    let p0 = { x: f.A.sx, y: f.A.sy };
    let p1 = { x: f.B.sx, y: f.B.sy };
    let p2 = { x: f.C.sx, y: f.C.sy };
    brush.wash("#b9aa95", 82);
    brush.beginShape(0);
    brush.vertex(p0.x, p0.y);
    brush.vertex(p1.x, p1.y);
    brush.vertex(p2.x, p2.y);
    brush.endShape(true);
  }
  brush.noWash();

  // Soft graphite hatching inside the cast shadow so it blends organically with the graph paper
  brush.set("2B", "#8f816d", 0.34);
  for (let f of facets) {
    if (f.zAvg > 10) {
      let sLines = hatchTriangle(
        { x: f.A.sx, y: f.A.sy },
        { x: f.B.sx, y: f.B.sy },
        { x: f.C.sx, y: f.C.sy },
        38, 6.5, 0.8
      );
      for (let ln of sLines) {
        brush.line(ln[0], ln[1], ln[2], ln[3]);
      }
    }
  }

  // =========================================================================
  // 7. 3D SURFACE NORMAL LIGHTING & DIRECTIONAL PENCIL SHADING PER FACET
  // =========================================================================
  // Cool window light vector from top-left: L_win = normalize(-0.66, -0.58, 0.48)
  const L_win = { x: -0.66, y: -0.58, z: 0.48 };
  // Warm bounce light vector from bottom-right: L_bnc = normalize(0.55, 0.55, 0.63)
  const L_bnc = { x: 0.55, y: 0.55, z: 0.63 };

  function computeFacetLighting(f) {
    let x0 = f.A.tx, y0 = f.A.ty, z0 = f.A.z * 2.35;
    let x1 = f.B.tx, y1 = f.B.ty, z1 = f.B.z * 2.35;
    let x2 = f.C.tx, y2 = f.C.ty, z2 = f.C.z * 2.35;

    let det = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    let dz_dx = 0, dz_dy = 0;
    if (Math.abs(det) > 1e-4) {
      dz_dx = ((z1 - z0) * (y2 - y0) - (z2 - z0) * (y1 - y0)) / det;
      dz_dy = ((x1 - x0) * (z2 - z0) - (x2 - x0) * (z1 - z0)) / det;
    }
    // Upward normal N = normalize(-dz/dx, -dz/dy, 1) — completely winding-invariant!
    let nx = -dz_dx, ny = -dz_dy, nz = 1.0;
    let nLen = Math.hypot(nx, ny, nz);
    nx /= nLen; ny /= nLen; nz /= nLen;

    let dotWin = nx * L_win.x + ny * L_win.y + nz * L_win.z;
    let dotBnc = nx * L_bnc.x + ny * L_bnc.y + nz * L_bnc.z;

    // Normalize light intensity tLit in [0, 1]
    // Flat surface (nx=0, ny=0, nz=1) has dotWin = 0.48
    let tLit = constrain((dotWin - 0.10) / 0.72, 0, 1);
    let slopeAngle = atan2(ny, nx);

    // Color interpolation across Warm Kraft Washi + Cool Window Light sheen:
    // Shadow: warm toasted umber-kraft (152, 112, 66)
    // Midtone: warm golden kraft washi (206, 171, 121)
    // Cool-lit highlight: luminous pale cool-champagne buff (236, 226, 206) with subtle cool sky tint
    let r, g, b;
    if (f.isUnderside) {
      // Underside of washi is slightly paler, oat-fibrous raw kozo
      if (tLit < 0.5) {
        let u = tLit * 2;
        r = lerp(178, 216, u);
        g = lerp(146, 189, u);
        b = lerp(104, 148, u);
      } else {
        let u = (tLit - 0.5) * 2;
        r = lerp(216, 241, u);
        g = lerp(189, 232, u);
        b = lerp(148, 214, u);
      }
    } else {
      if (tLit < 0.5) {
        let u = tLit * 2;
        r = lerp(150, 205, u);
        g = lerp(110, 169, u);
        b = lerp(65, 118, u);
      } else {
        let u = (tLit - 0.5) * 2;
        r = lerp(205, 236, u);
        g = lerp(169, 224, u);
        b = lerp(118, 204, u);
      }
    }
    // Warm bounce light boost in deep shadow facets facing bottom-right
    if (tLit < 0.35 && dotBnc > 0.55) {
      r += 10 * (dotBnc - 0.55);
      g += 5 * (dotBnc - 0.55);
    }

    let hexColor = color(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255));
    return { nx, ny, nz, dotWin, tLit, slopeAngle, hexColor };
  }

  // Precompute lighting for all facets
  for (let f of facets) {
    f.light = computeFacetLighting(f);
  }

  // Helper to draw a single facet with base wash + directional pencil shading + crevice gradients
  function renderFacetSlice(f) {
    let p0 = { x: f.A.x, y: f.A.y };
    let p1 = { x: f.B.x, y: f.B.y };
    let p2 = { x: f.C.x, y: f.C.y };
    let lt = f.light;

    // 1. Crisp base wash for exact 3D facet value
    brush.noStroke();
    brush.wash(lt.hexColor, 244);
    brush.beginShape(0);
    brush.vertex(p0.x, p0.y);
    brush.vertex(p1.x, p1.y);
    brush.vertex(p2.x, p2.y);
    brush.endShape(true);
    brush.noWash();

    // 2. Primary directional pencil shading aligned with the facet's 3D tilt slope
    let hAngle = lt.slopeAngle + 90;
    let spacing = map(lt.tLit, 0, 1, 3.2, 7.5);
    let pLines = hatchTriangle(p0, p1, p2, hAngle, spacing, 0.6);

    if (lt.tLit < 0.42) {
      // Shadowed facet: rich warm umber + cool graphite pencil shading
      brush.set("2B", "#694b2a", map(lt.tLit, 0, 0.42, 0.46, 0.28));
      for (let ln of pLines) brush.line(ln[0], ln[1], ln[2], ln[3]);

      // Secondary cross-hatch in deep shadow facets
      let cLines = hatchTriangle(p0, p1, p2, hAngle + 34, spacing * 1.45, 0.6);
      brush.set("HB", "#4e3a25", map(lt.tLit, 0, 0.42, 0.36, 0.20));
      for (let ln of cLines) brush.line(ln[0], ln[1], ln[2], ln[3]);
    } else if (lt.tLit < 0.72) {
      // Mid-tone facet: soft HB/2H graphite-sepia grain
      brush.set("HB", "#8f6d44", 0.30);
      for (let ln of pLines) brush.line(ln[0], ln[1], ln[2], ln[3]);

      let cLines = hatchTriangle(p0, p1, p2, hAngle - 28, spacing * 1.7, 0.5);
      brush.set("2H", "#7c6549", 0.24);
      for (let ln of cLines) brush.line(ln[0], ln[1], ln[2], ln[3]);
    } else {
      // Facet tilted strongly toward the cool window light:
      // Delicate cool blue-silver & warm chalk colored-pencil sheen!
      brush.set("cpencil", "#e4ecee", map(lt.tLit, 0.72, 1, 0.32, 0.52));
      for (let ln of pLines) brush.line(ln[0], ln[1], ln[2], ln[3]);

      let sheenLines = hatchTriangle(p0, p1, p2, -35, spacing * 1.3, 0.5);
      brush.set("cpencil", "#f6f0e4", map(lt.tLit, 0.72, 1, 0.28, 0.45));
      for (let ln of sheenLines) brush.line(ln[0], ln[1], ln[2], ln[3]);
    }

    // 3. Crevice ambient occlusion near Valley edges & stretch highlight near Mountain edges
    let vs = [f.v0, f.v1, f.v2];
    let pts = [p0, p1, p2];
    let cxTri = (p0.x + p1.x + p2.x) / 3;
    let cyTri = (p0.y + p1.y + p2.y) / 3;

    for (let e = 0; e < 3; e++) {
      let va = vs[e], vb = vs[(e + 1) % 3];
      let key = va < vb ? va + "|" + vb : vb + "|" + va;
      let ed = edgesMap.get(key);
      if (!ed) continue;

      let pa = pts[e], pb = pts[(e + 1) % 3];
      if (ed.type === "V" || ed.type === "V2") {
        // Soft pencil shadow gradient hugging the valley trough inside this facet
        brush.set("2B", "#63492e", ed.type === "V" ? 0.34 : 0.24);
        for (let s = 1; s <= 3; s++) {
          let fPull = s * 0.055;
          let ax = lerp(pa.x, cxTri, fPull);
          let ay = lerp(pa.y, cyTri, fPull);
          let bx = lerp(pb.x, cxTri, fPull);
          let by = lerp(pb.y, cyTri, fPull);
          brush.line(ax, ay, bx, by);
        }
      } else if (ed.type === "M" || ed.type === "M2") {
        // Luminous cool-ivory highlight along the stretched mountain ridge fiber
        brush.set("cpencil", "#f4ecdc", ed.type === "M" ? 0.38 : 0.26);
        let fPull = 0.04;
        let ax = lerp(pa.x, cxTri, fPull);
        let ay = lerp(pa.y, cyTri, fPull);
        let bx = lerp(pb.x, cxTri, fPull);
        let by = lerp(pb.y, cyTri, fPull);
        brush.line(ax, ay, bx, by);
      }
    }
  }

  // Separate base facets from elevated 3D overlapping flaps (tailCurl, neck, head)
  const baseFacets = facets.filter(f => f.group !== "neck" && f.group !== "head" && f.group !== "tailCurl");
  const tailCurlFacets = facets.filter(f => f.group === "tailCurl");
  const neckHeadFacets = facets.filter(f => f.group === "neck" || f.group === "head");

  // Render all unfolded base facets first
  for (let f of baseFacets) {
    renderFacetSlice(f);
  }

  // Subtle organic watercolor mottling over the kraft washi base facets (few large grouped washes)
  brush.noStroke();
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.55, 0.22);
  brush.fill("#b88e58", 26);
  brush.circle(cx - 45, cy + 35, 220, 0.25);
  brush.fill("#e8dec8", 28);
  brush.circle(cx - 120, cy - 130, 190, 0.25);
  brush.noFill();

  // Cast shadow of the curled Tail flap onto the adjacent Tail facets
  brush.noStroke();
  for (let f of tailCurlFacets) {
    brush.wash("#7d5b37", 68);
    brush.beginShape(0);
    brush.vertex(f.A.x + 10, f.A.y + 8);
    brush.vertex(f.B.x + 10, f.B.y + 8);
    brush.vertex(f.C.x + 10, f.C.y + 8);
    brush.endShape(true);
  }
  brush.noWash();

  // Render the curled Tail flap facets
  for (let f of tailCurlFacets) {
    renderFacetSlice(f);
  }

  // =========================================================================
  // 8. VISIBLE KRAFT WASHI FIBRES & FAINT GHOST FOLDS ON UNFOLDED SHEET
  // =========================================================================
  // Helper: barycentric point inside triangle
  function randomPointInTri(A, B, C) {
    let r1 = Math.sqrt(random());
    let r2 = random();
    let a = 1 - r1;
    let b = r1 * (1 - r2);
    let c = r1 * r2;
    return {
      x: a * A.x + b * B.x + c * C.x,
      y: a * A.y + b * B.y + c * C.y
    };
  }

  // Draw Mulberry / Kozo Washi Fibres embedded across all base + tailCurl facets
  const fiberColorsLight = ["#f5ebd6", "#eadbc0", "#e2cfa8"];
  const fiberColorsDark  = ["#9c7243", "#7e562d", "#664320", "#b38854"];

  for (let f of [...baseFacets, ...tailCurlFacets]) {
    let area = 0.5 * Math.abs(
      (f.B.x - f.A.x) * (f.C.y - f.A.y) - (f.C.x - f.A.x) * (f.B.y - f.A.y)
    );
    let numFibers = Math.max(2, Math.floor(area / 420));
    for (let i = 0; i < numFibers; i++) {
      let pt = randomPointInTri(f.A, f.B, f.C);
      let cxF = (f.A.x + f.B.x + f.C.x) / 3;
      let cyF = (f.A.y + f.B.y + f.C.y) / 3;
      // Keep fiber safely inside facet interior
      let sx = lerp(pt.x, cxF, 0.25);
      let sy = lerp(pt.y, cyF, 0.25);
      let len = random(6, 19);
      let ang = random(360);
      let curveAng = ang + random(-35, 35);

      let mx = sx + cos(ang) * (len * 0.5);
      let my = sy + sin(ang) * (len * 0.5);
      let ex = mx + cos(curveAng) * (len * 0.5);
      let ey = my + sin(curveAng) * (len * 0.5);

      if (random() < 0.48) {
        brush.set("cpencil", random(fiberColorsLight), random(0.24, 0.42));
      } else {
        brush.set("2H", random(fiberColorsDark), random(0.22, 0.38));
      }
      brush.spline([[sx, sy, 0.4], [mx, my, 0.9], [ex, ey, 0.3]], 0.5);
    }
  }

  // Render FAINT GHOST FOLDS (where the paper refuses to flatten — no hard pen ink!)
  function drawGhostFoldCurve(pts, strength = 1.0) {
    // Soft multi-pass graphite trough memory
    for (let pass = -2; pass <= 2; pass++) {
      let off = pass * 1.4;
      let shifted = pts.map(p => [p[0] + off * 0.7, p[1] + off * 0.7, p[2] || 0.6]);
      let w = (1.1 - Math.abs(pass) * 0.25) * 0.32 * strength;
      brush.set("2B", pass <= 0 ? "#7a5b37" : "#8d6d46", w);
      brush.spline(shifted, 0.45);
    }
    // Delicate stretched-fiber highlight along the upper-left lip of the ghost fold
    let hiPts = pts.map(p => [p[0] - 2.2, p[1] - 2.2, p[2] || 0.7]);
    brush.set("cpencil", "#f4ead6", 0.40 * strength);
    brush.spline(hiPts, 0.45);
  }

  // Ghost folds across Left Wing, Right Wing, Central Box Plateau, and Tail
  drawGhostFoldCurve([
    [V["ET_TL1"].x, V["ET_TL1"].y, 0.4],
    [V["P_TL_T1"].x, V["P_TL_T1"].y, 0.8],
    [V["W_TL1"].x, V["W_TL1"].y, 0.9],
    [V["P_TL_L1"].x, V["P_TL_L1"].y, 0.8],
    [V["EL_TL1"].x, V["EL_TL1"].y, 0.4]
  ], 1.0);

  drawGhostFoldCurve([
    [V["ET_TL2"].x, V["ET_TL2"].y, 0.3],
    [V["P_TL_T2"].x, V["P_TL_T2"].y, 0.7],
    [V["W_TL2"].x, V["W_TL2"].y, 0.9],
    [V["P_TL_L2"].x, V["P_TL_L2"].y, 0.7],
    [V["EL_TL2"].x, V["EL_TL2"].y, 0.3]
  ], 0.85);

  drawGhostFoldCurve([
    [V["ER_BR1"].x, V["ER_BR1"].y, 0.4],
    [V["P_BR_R1"].x, V["P_BR_R1"].y, 0.8],
    [V["W_BR1"].x, V["W_BR1"].y, 0.9],
    [V["P_BR_B1"].x, V["P_BR_B1"].y, 0.8],
    [V["EB_BR1"].x, V["EB_BR1"].y, 0.4]
  ], 1.05);

  drawGhostFoldCurve([
    [V["ER_BR2"].x, V["ER_BR2"].y, 0.3],
    [V["P_BR_R2"].x, V["P_BR_R2"].y, 0.7],
    [V["W_BR2"].x, V["W_BR2"].y, 0.9],
    [V["P_BR_B2"].x, V["P_BR_B2"].y, 0.7],
    [V["EB_BR2"].x, V["EB_BR2"].y, 0.3]
  ], 0.9);

  // Additional wandering stress-buckle ghost creases where the paper resisted flattening
  drawGhostFoldCurve([
    [lerp(V["D_T"].x, V["P_TL_T1"].x, 0.5), lerp(V["D_T"].y, V["P_TL_T1"].y, 0.5), 0.3],
    [lerp(V["M_TL"].x, V["W_TL1"].x, 0.45) - 6, lerp(V["M_TL"].y, V["W_TL1"].y, 0.45) + 4, 0.8],
    [lerp(V["D_L"].x, V["P_TL_L1"].x, 0.5), lerp(V["D_L"].y, V["P_TL_L1"].y, 0.5), 0.3]
  ], 0.75);

  drawGhostFoldCurve([
    [lerp(V["D_R"].x, V["P_BR_R1"].x, 0.5), lerp(V["D_R"].y, V["P_BR_R1"].y, 0.5), 0.3],
    [lerp(V["M_BR"].x, V["W_BR1"].x, 0.55) + 5, lerp(V["M_BR"].y, V["W_BR1"].y, 0.55) - 4, 0.8],
    [lerp(V["D_B"].x, V["P_BR_B1"].x, 0.5), lerp(V["D_B"].y, V["P_BR_B1"].y, 0.5), 0.3]
  ], 0.75);

  // Central box inflation memory ring
  drawGhostFoldCurve([
    [V["I_T"].x, V["I_T"].y, 0.6],
    [V["I_TR"].x, V["I_TR"].y, 0.8],
    [V["I_R"].x, V["I_R"].y, 0.6],
    [V["I_BR"].x, V["I_BR"].y, 0.8],
    [V["I_B"].x, V["I_B"].y, 0.6],
    [V["I_BL"].x, V["I_BL"].y, 0.8],
    [V["I_L"].x, V["I_L"].y, 0.6],
    [V["I_TL"].x, V["I_TL"].y, 0.8],
    [V["I_T"].x, V["I_T"].y, 0.6]
  ], 0.85);

  // =========================================================================
  // 9. TECHNICAL PEN CREASE WEB ON BASE LAYER (LAYER 0)
  // =========================================================================
  function renderCreaseEdge(ed) {
    let x1 = ed.A.x, y1 = ed.A.y;
    let x2 = ed.B.x, y2 = ed.B.y;
    let dx = x2 - x1, dy = y2 - y1;
    let len = Math.hypot(dx, dy);
    if (len < 1.5) return;
    let nx = -dy / len, ny = dx / len;
    // Ensure normal points generally toward top-left window (-1, -1)
    if (nx * (-1) + ny * (-1) < 0) {
      nx = -nx; ny = -ny;
    }

    if (ed.type === "M") {
      // PRIMARY MOUNTAIN CREASE:
      // 1. Soft shadow on the leeward side of the ridge
      brush.set("HB", "#735433", 0.30);
      brush.line(x1 - nx * 1.8, y1 - ny * 1.8, x2 - nx * 1.8, y2 - ny * 1.8);
      // 2. Bright stretched-fiber highlight on the window-facing side of the ridge
      brush.set("cpencil", "#f9f2e4", 0.48);
      brush.line(x1 + nx * 1.3, y1 + ny * 1.3, x2 + nx * 1.3, y2 + ny * 1.3);
      // 3. Crisp technical pen mountain line right along the ridge crest
      brush.set("rotring", "#332215", 0.56);
      brush.line(x1, y1, x2, y2);
    } else if (ed.type === "M2") {
      // SECONDARY MOUNTAIN CREASE (11.25 deg narrowing / reverse fold)
      brush.set("cpencil", "#f4ecdc", 0.36);
      brush.line(x1 + nx * 1.0, y1 + ny * 1.0, x2 + nx * 1.0, y2 + ny * 1.0);
      brush.set("rotring", "#4a3321", 0.40);
      brush.line(x1, y1, x2, y2);
    } else if (ed.type === "V") {
      // PRIMARY VALLEY CREASE:
      // 1. Soft graphite recess shadow in the valley trough
      brush.set("2B", "#62472b", 0.38);
      brush.line(x1 - nx * 1.1, y1 - ny * 1.1, x2 - nx * 1.1, y2 - ny * 1.1);
      brush.line(x1 + nx * 1.1, y1 + ny * 1.1, x2 + nx * 1.1, y2 + ny * 1.1);
      // 2. Crisp technical pen dashed-dotted or broken valley line
      brush.set("rotring", "#3e2e22", 0.46);
      drawDashedLine(x1, y1, x2, y2, 9.5, 5.5, true);
    } else if (ed.type === "V2") {
      // SECONDARY VALLEY CREASE:
      brush.set("HB", "#705336", 0.30);
      brush.line(x1, y1, x2, y2);
      brush.set("rotring", "#544030", 0.36);
      drawDashedLine(x1, y1, x2, y2, 5.5, 4.2, false);
    } else if (ed.type === "B") {
      // OUTER DECKLED WASHI BOUNDARY EDGE:
      let facesWindow = (nx * L_win.x + ny * L_win.y) > 0;
      // Paper thickness rim
      brush.set("2B", "#593e23", 0.50);
      brush.line(x1 + 1.0, y1 + 1.2, x2 + 1.0, y2 + 1.2);
      // Crisp warm kraft border
      brush.set("rotring", "#452f1b", 0.44);
      brush.line(x1, y1, x2, y2);
      if (facesWindow) {
        // Bright catch-light on the paper edge thickness facing the cool window
        brush.set("cpencil", "#fbf5e9", 0.52);
        brush.line(x1 - 0.7, y1 - 0.7, x2 - 0.7, y2 - 0.7);
      }
      // Delicate handmade mulberry fiber whiskers along the deckled edge
      brush.set("2H", "#d8c3a0", 0.25);
      let steps = Math.floor(len / 14);
      for (let s = 1; s < steps; s++) {
        let t = s / steps;
        let bx = lerp(x1, x2, t);
        let by = lerp(y1, y2, t);
        let a = random(360);
        brush.line(bx, by, bx + cos(a) * 2.6, by + sin(a) * 2.6);
      }
    }
  }

  for (let ed of edgesMap.values()) {
    if (ed.layer === 0) {
      renderCreaseEdge(ed);
    }
  }

  // =========================================================================
  // 10. 3D FOLDED NECK & POINTED CRANE HEAD OVERLAY (LAYERS 1 & 2)
  // =========================================================================
  // First: Cast shadow of the lifted 3D Neck and Beak onto the underlying unfolded facets!
  brush.noStroke();
  for (let f of neckHeadFacets) {
    let shOffX = (f.zAvg - 18) * 0.58;
    let shOffY = (f.zAvg - 18) * 0.48;
    brush.wash("#6e5030", 56);
    brush.beginShape(0);
    brush.vertex(f.A.x + shOffX, f.A.y + shOffY);
    brush.vertex(f.B.x + shOffX, f.B.y + shOffY);
    brush.vertex(f.C.x + shOffX, f.C.y + shOffY);
    brush.endShape(true);
  }
  brush.noWash();

  // Soften the neck/beak shadow on the paper with fine 2B hatching
  brush.set("2B", "#523a21", 0.32);
  for (let f of neckHeadFacets) {
    let shOffX = (f.zAvg - 18) * 0.52;
    let shOffY = (f.zAvg - 18) * 0.44;
    let sLines = hatchTriangle(
      { x: f.A.x + shOffX, y: f.A.y + shOffY },
      { x: f.B.x + shOffX, y: f.B.y + shOffY },
      { x: f.C.x + shOffX, y: f.C.y + shOffY },
      42, 4.5, 0.5
    );
    for (let ln of sLines) brush.line(ln[0], ln[1], ln[2], ln[3]);
  }

  // Render the 3D Neck & Head facets in painter's order
  for (let f of neckHeadFacets) {
    renderFacetSlice(f);
    // Add mulberry fibers on the 3D neck & head facets too
    for (let i = 0; i < 4; i++) {
      let pt = randomPointInTri(f.A, f.B, f.C);
      let cxF = (f.A.x + f.B.x + f.C.x) / 3;
      let cyF = (f.A.y + f.B.y + f.C.y) / 3;
      let sx = lerp(pt.x, cxF, 0.3);
      let sy = lerp(pt.y, cyF, 0.3);
      let ang = random(360);
      brush.set("cpencil", "#f2e6cf", 0.30);
      brush.line(sx, sy, sx + cos(ang) * 7, sy + sin(ang) * 7);
    }
  }

  // Render Technical Pen Crease Edges on the 3D Neck (layer 1) & Head (layer 2)
  for (let ed of edgesMap.values()) {
    if (ed.layer === 1) renderCreaseEdge(ed);
  }
  for (let ed of edgesMap.values()) {
    if (ed.layer === 2) renderCreaseEdge(ed);
  }

  // =========================================================================
  // 11. PRECISION ANALYTICAL VERTEX MARKERS & DIAGRAMMATIC DETAILS
  // =========================================================================
  // Tiny pin-prick / compass registration dots & vertex ticks at primary Bird-Base nodes
  const keyNodes = ["O", "D_T", "D_R", "D_B", "D_L", "M_TR", "M_BR", "M_BL", "M_TL"];
  for (let id of keyNodes) {
    let v = V[id];
    brush.set("rotring", "#2b1c10", 0.45);
    brush.circle(v.x, v.y, 2.2, 0.05);
    brush.set("cpencil", "#fbf4e6", 0.42);
    brush.line(v.x - 2.5, v.y - 2.5, v.x - 0.8, v.y - 0.8);
  }

  // Subtle analytical callout ticks along the Bottom-Left Tail & Left Wing margin
  let vCBL = V["C_BL"];
  let vCTL = V["C_TL"];
  let vCBR = V["C_BR"];
  brush.set("rotring", "#8c5638", 0.30);
  drawDashedLine(vCTL.x, vCTL.y, vCTL.fx - 26, vCTL.fy - 26, 4, 4, false);
  drawDashedLine(vCBR.x, vCBR.y, vCBR.fx + 26, vCBR.fy + 26, 4, 4, false);

  // Analytical scale & crease legend bar in bottom-left margin of the graph paper
  const legX = gLeft + 28;
  const legY = gBottom - 36;
  brush.set("rotring", "#5c5246", 0.36);
  brush.line(legX, legY, legX + 180, legY);
  for (let s = 0; s <= 180; s += 36) {
    brush.line(legX + s, legY - 4, legX + s, legY + 4);
  }
  // Mountain & Valley legend key samples on the right margin
  const keyX = gRight - 220;
  const keyY = gBottom - 36;
  // Mountain sample line
  brush.set("rotring", "#332215", 0.54);
  brush.line(keyX, keyY - 8, keyX + 75, keyY - 8);
  // Valley sample line (dash-dot)
  brush.set("rotring", "#3e2e22", 0.44);
  drawDashedLine(keyX, keyY + 6, keyX + 75, keyY + 6, 9, 5, true);
  // Small angular protractor diagram icon next to the legend
  brush.set("rotring", "#7a6a58", 0.30);
  brush.line(keyX + 110, keyY + 8, keyX + 165, keyY + 8);
  brush.line(keyX + 110, keyY + 8, keyX + 110 + cos(-22.5) * 55, keyY + 8 + sin(-22.5) * 55);
  brush.line(keyX + 110, keyY + 8, keyX + 110 + cos(-45) * 55, keyY + 8 + sin(-45) * 55);
  brush.arc(keyX + 110, keyY + 8, 38, -45, 0);

  noLoop();
}

// Hyperrealist Coloured Pencil Rendering:
// Extreme close crop of a city pigeon's iridescent neck, shoulder, orange eye & pale cere

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(83412);

  // Custom coloured-pencil brushes tailored for 1200x1200 hyperrealist barb & burnish work
  brush.add("cp_soft", {
    type: "default",
    weight: 0.75,
    scatter: 0.38,
    sharpness: 0.32,
    grain: 0.78,
    opacity: 75,
    spacing: 0.18,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.45
  });

  brush.add("cp_barb", {
    type: "default",
    weight: 0.24,
    scatter: 0.06,
    sharpness: 0.80,
    grain: 0.62,
    opacity: 155,
    spacing: 0.10,
    pressure: [0.35, 1.0, 0.12],
    noise: 0.28
  });

  brush.add("cp_burnish", {
    type: "default",
    weight: 0.36,
