// ---------------------------------------------------------------------------
// ANATOMICAL BOUNDARY HELPERS
// ---------------------------------------------------------------------------

// Left feathered silhouette (forehead -> face behind cere -> throat -> crop -> breast)
function getLeftPlumageX(y) {
  if (y < 95) {
    let t = constrain(y / 95, 0, 1);
    return lerp(336, 280, pow(t, 0.85));
  } else if (y < 185) {
    let t = (y - 95) / 90;
    return lerp(280, 244, t) + sin(t * 180) * 6;
  } else if (y < 295) {
    // Gentle concave hollow under the chin/throat
    let t = (y - 185) / 110;
    return lerp(244, 272, sin(t * 90)) + (t > 0.7 ? (t - 0.7) * -20 : 0);
  } else {
    // Proud, convex curve of the pigeon's inflated neck and crop/breast
    let t = (y - 295) / 945;
    let swell = sin(pow(constrain(t, 0, 1), 0.72) * 158) * 102;
    return 268 - swell + t * 28;
  }
}

// Right silhouette (crown -> nape -> mantle -> rounded wing shoulder)
function getRightPlumageX(y) {
  if (y < 210) {
    let t = y / 210;
    return lerp(612, 742, pow(t, 0.92));
  } else if (y < 430) {
    let t = (y - 210) / 220;
    return lerp(742, 888, pow(t, 1.05));
  } else {
    let t = (y - 430) / 810;
    return lerp(888, 1310, pow(t, 0.88));
  }
}

// Internal shoulder/scapular furrow dividing the plush neck/breast from the wing coverts
function getShoulderFurrowX(y) {
  if (y < 480) return 9999;
  let t = constrain((y - 480) / 740, 0, 1);
  return 720 - sin(t * 155) * 92 + t * 48;
}

// Color interpolation helper in RGB space
function mixHex(hex1, hex2, amt) {
  amt = constrain(amt, 0, 1);
  let c1 = color(hex1);
  let c2 = color(hex2);
  return lerpColor(c1, c2, amt);
}

// ---------------------------------------------------------------------------
// MAIN RENDER
// ---------------------------------------------------------------------------

function draw() {
  translate(-width / 2, -height / 2);
  background("#c2c6c5");

  // 1. Soft concrete grey background (underwash + subtle coloured pencil paper grain)
  drawConcreteBackground();

  // 2. Sculptural underpainting of the pigeon's head, neck, breast, and shoulder
  drawAnatomicalUnderpainting();

  // 3. Beak & Lower Mandible (drawn before face feathers & cere overlap its base)
  drawBeak();

  // 4. Imbricated Plumage (rendered strictly bottom-to-top so upper feathers overlap lower bases)
  drawAllPlumage();

  // 5. Pale Cere (swollen powdery operculum sitting at the upper-left edge)
  drawPaleCere();

  // 6. Beady Fiery Orange Eye & Orbital Ring (focal accent near the upper edge)
  drawOrangeEye();

  // 7. Final luminous mother-of-pearl burnishing & stray silhouette barb details
  drawFinalBurnishPass();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. SOFT CONCRETE GREY BACKGROUND
// ---------------------------------------------------------------------------

function drawConcreteBackground() {
  brush.noStroke();

  // Soft tonal modulation of architectural concrete
  brush.wash("#c6cac9", 255);
  brush.rect(0, 0, 1200, 1200);

  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.25);

  // Subtle cool concrete shadow in lower-left and upper-right
  brush.fill("#aeb3b3", 95);
  brush.circle(80, 1080, 520, 0.2);
  brush.circle(1080, 160, 460, 0.2);

  // Soft luminous skylight glow behind the upper throat and beak
  brush.fill("#d5d8d7", 110);
  brush.circle(160, 340, 380, 0.25);
  brush.noFill();

  // Delicate diagonal coloured-pencil grain on the visible concrete negative space
  let bgTones = ["#b8bcBC", "#cfd3d2", "#a7acac", "#dcdfdf"];
  for (let b = 0; b < bgTones.length; b++) {
    brush.set("cp_soft", bgTones[b], 1.1);
    let count = b < 2 ? 260 : 140;
    for (let i = 0; i < count; i++) {
      let y = random(-20, 1220);
      let maxX = y < 480 ? getLeftPlumageX(y) + 35 : getLeftPlumageX(y) + 25;
      // Also allow top-right negative space above the shoulder/nape
      let onRight = random() < 0.28 && y < 650;
      let x = onRight
        ? random(getRightPlumageX(y) - 20, 1220)
        : random(-20, maxX);

      let ang = -52 + noise(x * 0.004, y * 0.004) * 24 + random(-6, 6);
      let len = random(35, 95);
      let dx = cos(ang) * len * 0.5;
      let dy = sin(ang) * len * 0.5;
      brush.line(x - dx, y - dy, x + dx, y + dy);
    }
  }
}

// ---------------------------------------------------------------------------
// 2. ANATOMICAL UNDERPAINTING (3D Volume Base)
// ---------------------------------------------------------------------------

function drawAnatomicalUnderpainting() {
  brush.noStroke();

  // Base dark silhouette wash so no background paper peeks between dense feather barbs
  brush.wash("#2a2830", 245);
  brush.beginShape(0.2);
  for (let y = -10; y <= 1220; y += 45) {
    brush.vertex(getLeftPlumageX(y) + 4, y);
  }
  for (let y = 1220; y >= -10; y -= 45) {
    brush.vertex(min(1215, getRightPlumageX(y) - 4), y);
  }
  brush.endShape(true);
  brush.noWash();

  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.5, 0.2);

  // Wing shoulder slate mass (lower right)
  brush.fill("#5f6873", 170);
  brush.circle(960, 880, 390, 0.15);

  // Lower breast smoky plum-slate mass
  brush.fill("#483e52", 165);
  brush.circle(430, 920, 340, 0.15);

  // Mid-neck amethyst & rose-pearl underglow
  brush.fill("#6e5678", 160);
  brush.circle(460, 620, 290, 0.18);

  // Upper-mid neck seafoam-emerald iridescent underglow
  brush.fill("#4f786d", 165);
  brush.circle(530, 410, 250, 0.18);

  // Crown & cheek velvety dove-slate underpainting
  brush.fill("#585e68", 175);
  brush.circle(470, 140, 230, 0.15);

  brush.noFill();
}

// ---------------------------------------------------------------------------
// 3. BEAK (Upper & Lower Mandible at Upper-Left Edge)
// ---------------------------------------------------------------------------

function drawBeak() {
  brush.noStroke();
  brush.wash("#28272c", 250);
  brush.beginShape(0.15);
  brush.vertex(74, 168);   // Beak tip
  brush.vertex(128, 134);  // Upper dorsal curve
  brush.vertex(196, 118);  // Under cere
  brush.vertex(260, 164);  // Gape corner
  brush.vertex(248, 186);  // Chin junction
  brush.vertex(152, 180);  // Lower mandible ventral curve
  brush.vertex(78, 173);   // Lower tip
  brush.endShape(true);
  brush.noWash();

  // Coloured pencil shading along the horn beak
  for (let i = 0; i < 240; i++) {
    let t = random(0, 1);
    let x1 = lerp(76, 245, t);
    let yTop = lerp(167, 122, pow(t, 0.78));
    let yBot = lerp(172, 184, pow(t, 0.85));
    let f = random(0, 1);
    let y = lerp(yTop, yBot, f);

    // Dorsal ridge highlight vs dark gape & lower mandible
    let col;
    if (f < 0.26) {
      col = mixHex("#b8bec4", "#747a82", t * 0.6 + random(-0.1, 0.1));
    } else if (f > 0.52 && f < 0.66) {
      col = color("#161519"); // Dark gape cleft
    } else {
      col = mixHex("#222126", "#4b4a52", sin(f * 180) * 0.7);
    }

    brush.set("cp_micro", col, random(0.85, 1.35));
    let ang = -14 + t * 8 + random(-3, 3);
    let len = random(10, 24);
    brush.line(x1, y, x1 + cos(ang) * len, y + sin(ang) * len);
  }

  // Polished specular glint along upper culmen of beak
  brush.set("cp_burnish", "#dde2e6", 0.9);
  for (let i = 0; i < 38; i++) {
    let t = random(0.06, 0.58);
    let x = lerp(80, 190, t);
    let y = lerp(164, 124, pow(t, 0.78)) + random(-1.5, 2.0);
    brush.line(x, y, x + 12, y - 3.5);
  }
}

// ---------------------------------------------------------------------------
// 4. IMBRICATED PLUMAGE SYSTEM (Individual Feathers & Barbs)
// ---------------------------------------------------------------------------

function drawAllPlumage() {
  let feathers = [];

  // Generate rows from bottom (y = 1245) to top (y = -15)
  // Drawing bottom-to-top ensures upper feathers naturally overlap the bases of lower feathers
  let y = 1245;
  let rowIdx = 0;

  while (y >= -18) {
    // Feather scale decreases organically from shoulder/breast up to the head
    let rowStep;
    if (y > 820) rowStep = 34;
    else if (y > 460) rowStep = 24;
    else if (y > 230) rowStep = 17;
    else rowStep = 11.5;

    let leftX = getLeftPlumageX(y);
    let rightX = min(1245, getRightPlumageX(y));
    let furrowX = getShoulderFurrowX(y);

    // Horizontal spacing along the row
    let xCursor = leftX + (rowIdx % 2 === 0 ? 4 : rowStep * 0.55);

    while (xCursor <= rightX) {
      // Determine anatomical zone
      let isWing = y > 490 && xCursor > furrowX;
      let isHead = y < 235;
      let isNeck = !isWing && !isHead && y < 820;

      // Skip inside eye & cere zones (feathers wrap around them)
      let dEye = dist(xCursor, y, 438, 116);
      let inCere = xCursor < 292 && y > 72 && y < 170;

      if (dEye > 39 && !inCere) {
        // Local horizontal spacing and feather dimensions by zone
        let colStep, fLen, fWid;
        if (isWing) {
          colStep = map(y, 500, 1240, 42, 66);
          fLen = map(y, 500, 1240, 68, 115) * random(0.92, 1.08);
          fWid = map(y, 500, 1240, 48, 82) * random(0.92, 1.08);
        } else if (isHead) {
          colStep = map(y, 0, 235, 13, 21);
          fLen = map(y, 0, 235, 20, 36) * random(0.9, 1.1);
          fWid = map(y, 0, 235, 14, 25) * random(0.9, 1.1);
        } else if (isNeck) {
          colStep = map(y, 235, 820, 22, 38);
          fLen = map(y, 235, 820, 42, 76) * random(0.92, 1.08);
          fWid = map(y, 235, 820, 30, 52) * random(0.92, 1.08);
        } else {
          // Lower breast
          colStep = map(y, 820, 1240, 38, 52);
          fLen = map(y, 820, 1240, 74, 98) * random(0.92, 1.08);
          fWid = map(y, 820, 1240, 52, 72) * random(0.92, 1.08);
        }

        let fx = xCursor + random(-colStep * 0.14, colStep * 0.14);
        let fy = y + random(-rowStep * 0.14, rowStep * 0.14);

        // Compute natural feather flow angle (degrees, where 90 = straight down)
        let dir = computeFeatherAngle(fx, fy, leftX, rightX, furrowX, isWing, isHead);

        feathers.push({
          x: fx,
          y: fy,
          len: fLen,
          wid: fWid,
          dir: dir,
          isWing: isWing,
          isHead: isHead,
          isNeck: isNeck,
          leftNorm: constrain((fx - leftX) / max(1, rightX - leftX), 0, 1),
          furrowDist: fx - furrowX
        });

        xCursor += colStep * 0.86;
      } else {
        xCursor += 14;
      }
    }

    y -= rowStep;
    rowIdx++;
  }

  // Sort strictly so lower feathers and wing-side feathers beneath the breast furrow render first
  feathers.sort((a, b) => {
    let scoreA = a.y + (a.isWing ? 45 : 0);
    let scoreB = b.y + (b.isWing ? 45 : 0);
    return scoreB - scoreA;
  });

  // Render every feather with individual barbs and burnished tips
  for (let i = 0; i < feathers.length; i++) {
    drawSingleFeather(feathers[i]);
  }
}

function computeFeatherAngle(x, y, leftX, rightX, furrowX, isWing, isHead) {
  if (isHead) {
    // Radial flow over the crown, around the orbital ring, and down the cheek
    if (y < 95 && x < 460) {
      // Forehead sweeping up and back over the skull
      return map(x, 280, 460, -28, 12) + map(y, 0, 95, -8, 15);
    }
    let angFromEye = atan2(y - 112, x - 415);
    if (x < 430 && y >= 95) {
      // Lore & cheek sweeping back-down under the eye
      return map(y, 95, 235, 22, 68) + map(x, 250, 430, 18, -10);
    }
    return constrain(map(x, 420, 740, 18, 56) + map(y, 0, 235, -12, 32), -25, 78);
  }

  if (isWing) {
    // Wing coverts sweep diagonally down-right across the shoulder dome
    return map(x, furrowX, 1220, 62, 38) + map(y, 500, 1220, -6, 8);
  }

  // Neck & Breast cylinder flow:
  // Feathers near the left profile wrap outward/downward; center points down; right flows toward mantle
  let u = constrain((x - leftX) / max(1, min(furrowX, rightX) - leftX), 0, 1);
  let baseAng = lerp(104, 54, pow(u, 0.85));

  // Subtle organic wave along the iridescent neck tracts
  let ripple = sin(y * 0.045 + x * 0.025) * 5.5;
  return baseAng + ripple;
}

// ---------------------------------------------------------------------------
// SINGLE FEATHER RENDERER (Individual Barbs + Mother-of-Pearl Burnishing)
// ---------------------------------------------------------------------------

function drawSingleFeather(f) {
  let { x, y, len, wid, dir, isWing, isHead, isNeck, leftNorm, furrowDist } = f;

  // Evaluate 3D illumination & iridescence physics for this feather
  // Cylinder normal across the neck/breast (peaks around leftNorm = 0.28 facing upper-left key light)
  let cylLight = exp(-pow((leftNorm - 0.27) / 0.34, 2));
  // Diagonal neck muscle fluting creates pearly ribbons of green, rose, and amethyst
  let fluteWave = 0.5 + 0.5 * sin(y * 0.052 - x * 0.038 + noise(x * 0.008, y * 0.008) * 140);
  let microVar = random(-0.08, 0.08);

  // Determine the 4 tonal bands of this feather:
  // [0] Deep root shadow, [1] Mid-proximal vane, [2] Distal iridescent/lit vane, [3] Burnished tip highlight
  let colRoot, colMid, colDistal, colBurnish;

  if (isWing) {
    // Silvery-slate wing coverts with dark velvet wing-bar accent in lower right
    let wingLight = exp(-pow((x - 860) / 340, 2)) * exp(-pow((y - 680) / 420, 2));
    let inWingBar = (x + y * 0.55 > 1390 && x + y * 0.55 < 1515) || (x + y * 0.52 > 1610 && x + y * 0.52 < 1710);
    // Cast shadow just inside the shoulder furrow
    let furrowShadow = furrowDist > 0 && furrowDist < 65 ? map(furrowDist, 0, 65, 0.45, 0) : 0;

    if (inWingBar) {
      colRoot = color("#181a1f");
      colMid = mixHex("#23272e", "#353b45", wingLight);
      colDistal = mixHex("#2e333d", "#4c5461", wingLight);
      colBurnish = mixHex("#687280", "#8c96a6", wingLight);
    } else {
      colRoot = mixHex("#2b3038", "#1e2228", furrowShadow);
      colMid = mixHex("#5d6673", "#7d8896", constrain(wingLight - furrowShadow + microVar, 0, 1));
      colDistal = mixHex("#7c8796", "#a4b0bf", constrain(wingLight - furrowShadow * 0.7 + microVar, 0, 1));
      colBurnish = mixHex("#b4c0cf", "#dde5ed", constrain(wingLight + 0.15 - furrowShadow * 0.5, 0, 1));
    }
  } else if (isHead) {
    // Velvety dove-slate head & cheek feathers with subtle pearly sheen near nape
    let headLight = constrain(cylLight * 0.85 + map(y, 235, 0, 0, 0.25) + microVar, 0, 1);
    colRoot = color("#1e1f24");
    colMid = mixHex("#3e424b", "#59606b", headLight);
    colDistal = mixHex("#5a616e", "#838c99", headLight);
    colBurnish = mixHex("#8f98a6", "#c4cdd6", headLight);
  } else {
    // NECK & BREAST: Mother-of-pearl iridescence (seafoam green, rose, amethyst, silvery slate)
    // Iridescence strength peaks in y = 240..790
    let iridEnv = 1.0;
    if (y < 290) iridEnv = constrain((y - 210) / 80, 0, 1);
    else if (y > 680) iridEnv = constrain(1 - (y - 680) / 320, 0, 1);

    // Vertical & angular hue shift:
    // Upper/mid neck & direct light -> Seafoam green & mother-of-pearl
    // Oblique angles & mid-lower neck -> Rose opal & soft Amethyst
    // Lower breast -> Silvery slate with dusty plum undertones
    let greenBias = constrain(map(y, 660, 270, 0.0, 1.0) * 0.65 + cylLight * 0.45 + (fluteWave - 0.5) * 0.45, 0, 1);
    let roseBias = constrain(1.0 - abs(greenBias - 0.48) * 2.1 + sin(y * 0.03 + x * 0.02) * 0.25, 0, 1);

    // Base iridescent palette
    let cAmethystMid = "#6f5980";
    let cRoseMid = "#9c7389";
    let cSeafoamMid = "#568578";
    let cSlateMid = "#565f6b";

    let cAmethystDist = "#9d86b0";
    let cRoseDist = "#c99eb2";
    let cSeafoamDist = "#86b8a8";
    let cSlateDist = "#7a8491";

    let cAmethystBurn = "#dfd4eb";
    let cRoseBurn = "#f2dae5";
    let cSeafoamBurn = "#d8f2e9";
    let cSlateBurn = "#bcc6d1";

    // Blend Mid Vane
    let iridMid = mixHex(cAmethystMid, cSeafoamMid, greenBias);
    iridMid = lerpColor(iridMid, color(cRoseMid), roseBias * 0.58);
    colMid = lerpColor(color(cSlateMid), iridMid, iridEnv);

    // Blend Distal Vane
    let iridDist = mixHex(cAmethystDist, cSeafoamDist, constrain(greenBias + 0.12, 0, 1));
    iridDist = lerpColor(iridDist, color(cRoseDist), roseBias * 0.62);
    colDistal = lerpColor(color(cSlateDist), iridDist, iridEnv);

    // Blend Burnished Tip (Pearly glow)
    let iridBurn = mixHex(cAmethystBurn, cSeafoamBurn, constrain(greenBias + 0.18, 0, 1));
    iridBurn = lerpColor(iridBurn, color(cRoseBurn), roseBias * 0.55);
    colBurnish = lerpColor(color(cSlateBurn), iridBurn, iridEnv);

    // Darken gently on the turned shadow side of the neck/breast
    let shadowFade = constrain(map(cylLight, 0.0, 0.35, 0.62, 1.0), 0.62, 1.0);
    colRoot = color("#1d1924");
    colMid = lerpColor(color("#282330"), colMid, shadowFade);
    colDistal = lerpColor(color("#3b3545"), colDistal, shadowFade);
    colBurnish = lerpColor(color("#6e6878"), colBurnish, shadowFade * 0.9 + 0.1);
  }

  let cosD = cos(dir);
  let sinD = sin(dir);
  let cosP = -sinD;
  let sinP = cosD;

  // Helper to convert local feather coords (along axis u, across width v) to canvas (X, Y)
  // Includes subtle natural longitudinal curve of the feather vane
  let bend = (leftNorm - 0.45) * wid * 0.14;
  function toWorld(u, v) {
    let curveOffset = u * u * bend;
    let wx = x + u * len * cosD + (v * wid * 0.5 + curveOffset) * cosP;
    let wy = y + u * len * sinD + (v * wid * 0.5 + curveOffset) * sinP;
    return [wx, wy];
  }

  // Number of individual barb pairs scaled to feather size
  let barbPairs = isHead ? 9 : isWing ? 17 : 14;
  let hasNotchedTip = isNeck && y > 260 && y < 740;

  // PASS A: Deep velvety root barbs & subtle cast shadow under the distal rim
  brush.set("cp_barb", colRoot, isHead ? 0.85 : 1.05);
  // Cast shadow arc right under the feather tip onto the feather below
  for (let s = -0.65; s <= 0.65; s += 0.32) {
    let p1 = toWorld(1.02 - s * s * 0.18, s);
    let p2 = toWorld(0.96 - s * s * 0.16, s + 0.24);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Basal barbs (u from 0.05 to 0.42)
  for (let i = 0; i < barbPairs; i++) {
    let t = i / (barbPairs - 1);
    if (t < 0.52) {
      let u0 = t * 0.55;
      let u1 = u0 + 0.24;
      let v1 = sin(pow(u1, 0.7) * 165) * 0.85;
      let pR = toWorld(u0, 0);
      let pL = toWorld(u1, -v1);
      let pRt = toWorld(u1, v1);
      brush.line(pR[0], pR[1], pL[0], pL[1]);
      brush.line(pR[0], pR[1], pRt[0], pRt[1]);
    }
  }

  // PASS B: Mid-vane transitional barbs (amethyst / rose / slate)
  brush.set("cp_barb", colMid, isHead ? 0.9 : 1.1);
  for (let i = 0; i < barbPairs; i++) {
    let t = i / (barbPairs - 1);
    if (t >= 0.18 && t <= 0.85) {
      let u0 = t * 0.68;
      let uMid = u0 + (1 - u0) * 0.58;
      let vMid = sin(pow(uMid, 0.65) * 160) * 0.96;

      for (let side = -1; side <= 1; side += 2) {
        let p0 = toWorld(u0 + 0.06, side * 0.08);
        let p1 = toWorld(uMid, side * vMid);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // PASS C: Distal iridescent barbs (each barb extending to the outer feather margin)
  brush.set("cp_barb", colDistal, isHead ? 0.95 : 1.15);
  for (let i = 0; i < barbPairs; i++) {
    let t = i / (barbPairs - 1);
    if (t >= 0.32) {
      let u0 = t * 0.66;
      let uTip = 0.46 + t * 0.54;
      // Neck hackle feathers have a characteristic slight central notch/parting at the tip
      if (hasNotchedTip && t > 0.88) {
        uTip -= 0.04;
      }
      // Feather vane width envelope (broad and rounded at the tip)
      let vTip = sin(pow(constrain(t, 0, 0.98), 0.58) * 156) * 1.02;
      if (t > 0.82) vTip = map(t, 0.82, 1.0, 0.86, 0.16);

      for (let side = -1; side <= 1; side += 2) {
        let jitterU = random(-0.025, 0.035);
        let jitterV = random(-0.03, 0.03);
        let pStart = toWorld(u0 + 0.14, side * vTip * 0.36);
        let pEnd = toWorld(uTip + jitterU, side * (vTip + jitterV));
        brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
      }
    }
  }

  // PASS D: Densely burnished mother-of-pearl highlights along the distal ridge & rachis
  let burnishIntensity = isHead ? 0.75 : isWing ? 0.85 : constrain(cylLight * 0.95 + fluteWave * 0.45, 0.3, 1.25);
  brush.set("cp_burnish", colBurnish, burnishIntensity);

  let burnCount = isHead ? 5 : isWing ? 11 : 10;
  for (let i = 0; i < burnCount; i++) {
    let t = map(i, 0, burnCount - 1, 0.48, 0.98);
    let uStart = 0.54 + (t - 0.48) * 0.55;
    let uEnd = 0.72 + (t - 0.48) * 0.56;
    let vSpan = map(t, 0.48, 0.98, 0.92, 0.14);

    for (let side = -1; side <= 1; side += 2) {
      // Slightly favor the upper-left lit side of each feather
      if (side === 1 && random() < 0.25 && cylLight < 0.4) continue;
      let p1 = toWorld(uStart, side * vSpan * 0.62);
      let p2 = toWorld(uEnd + random(-0.02, 0.03), side * vSpan);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Central rachis (feather shaft) glint in fine pencil
  let pRachis0 = toWorld(0.18, 0);
  let pRachis1 = toWorld(0.84, 0);
  brush.set("cp_micro", colBurnish, isHead ? 0.6 : 0.85);
  brush.line(pRachis0[0], pRachis0[1], pRachis1[0], pRachis1[1]);
}

// ---------------------------------------------------------------------------
// 5. PALE CERE (Fleshy Powdery-White Operculum at the Base of the Beak)
// ---------------------------------------------------------------------------

function drawPaleCere() {
  // Base sculpted form of the swollen bilobed cere (x: 176..292, y: 76..164)
  brush.noStroke();
  brush.wash("#dbd7d0", 248);
  brush.beginShape(0.35);
  brush.vertex(182, 122);  // Front dorsal overhang on beak
  brush.vertex(214, 86);   // Upper lobe crest
  brush.vertex(258, 78);   // Top-back cushion
  brush.vertex(288, 96);   // Forehead junction top
  brush.vertex(284, 138);  // Forehead junction mid
  brush.vertex(264, 162);  // Base near gape
  brush.vertex(212, 158);  // Lower nostril rim
  brush.vertex(178, 142);  // Front tip over culmen
  brush.endShape(true);
  brush.noWash();

  // Granular, powdery chalk-white and dove-grey coloured pencil texture
  for (let i = 0; i < 420; i++) {
    let a = random(0, 360);
    let r = pow(random(0, 1), 0.65);
    let cx = 236 + cos(a) * r * 52;
    let cy = 121 + sin(a) * r * 40;

    // Illumination from top-left makes upper dome chalky pearl-white, lower edge warm stone-grey
    let lightAmt = constrain(map(cy, 158, 82, 0.1, 0.95) + map(cx, 286, 188, -0.1, 0.2), 0, 1);
    let col;
    if (lightAmt > 0.68) {
      col = mixHex("#eceae4", "#faf9f6", (lightAmt - 0.68) * 3.1);
    } else if (lightAmt > 0.35) {
      col = mixHex("#c4bfb7", "#eceae4", (lightAmt - 0.35) * 3.0);
    } else {
      col = mixHex("#87827b", "#c4bfb7", lightAmt * 2.8);
    }

    brush.set(lightAmt > 0.62 ? "cp_burnish" : "cp_micro", col, random(0.75, 1.25));
    // Short curving pebble-grain strokes following the rounded contour of the cere
    let strokeAng = a + 75 + random(-18, 18);
    let len = random(4, 10);
    brush.line(cx, cy, cx + cos(strokeAng) * len, cy + sin(strokeAng) * len);
  }

  // Oblique slit nostril at lower-front of cere & fine crease against forehead feathers
  brush.set("cp_micro", "#3a3638", 1.15);
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    // Nostril slit
    let nx = lerp(186, 226, t);
    let ny = lerp(138, 151, pow(t, 0.85)) + random(-1, 1);
    brush.line(nx, ny, nx + 5, ny + 1.5);

    // Posterior fold where tiny forehead feathers tuck behind the cere
    let fx = 285 - sin(t * 170) * 14 + random(-1.5, 1.5);
    let fy = lerp(82, 160, t);
    brush.line(fx, fy, fx + 4, fy + 4);
  }

  // Powdery white highlight along the upper operculum ridge
  brush.set("cp_burnish", "#fbfaf7", 1.1);
  for (let i = 0; i < 45; i++) {
    let t = random(0.1, 0.85);
    let hx = lerp(196, 272, t) + random(-4, 4);
    let hy = lerp(104, 88, sin(t * 150)) + random(-4, 5);
    brush.line(hx, hy, hx + 6, hy - 1.5);
  }
}

// ---------------------------------------------------------------------------
// 6. BEADY FIERY ORANGE EYE & PALE ORBITAL RING (Upper Edge Focal Accent)
// ---------------------------------------------------------------------------

function drawOrangeEye() {
  let ex = 438;
  let ey = 116;

  // A. Tiny dark velvet peri-orbital feathers framing the bare eye-ring
  for (let a = 0; a < 360; a += 4.5) {
    let rx = 50 + random(-2, 3);
    let ry = 45 + random(-2, 3);
    let px = ex + cos(a) * rx;
    let py = ey + sin(a) * ry;
    let outAng = a + (cos(a) < 0 ? 18 : -12);
    let isLit = sin(a) < 0;
    brush.set("cp_micro", isLit ? "#7c8491" : "#282a30", 1.0);
    brush.line(px, py, px + cos(outAng) * 11, py + sin(outAng) * 11);
  }

  // B. Bare fleshy pale orbital skin ring (eye-cere, rx = 47, ry = 43)
  brush.noStroke();
  brush.wash("#c8c3ba", 250);
  brush.circle(ex, ey, 45, 0.08);
  brush.noWash();

  // Concentric and radial micro-creases on the pale orbital ring
  for (let i = 0; i < 360; i++) {
    let a = random(0, 360);
    let rad = random(33.5, 47.5);
    let px = ex + cos(a) * rad * 1.06;
    let py = ey + sin(a) * rad * 0.96;

    // Upper-left of ring catches bright light; lower edge has subtle shadow crease
    let ringLight = constrain(0.55 - sin(a - 35) * 0.42 + random(-0.1, 0.1), 0.1, 1.0);
    let ringCol = ringLight > 0.6
      ? mixHex("#dcd7ce", "#f5f2ec", (ringLight - 0.6) * 2.5)
      : mixHex("#7d7872", "#dcd7ce", ringLight * 1.6);

    brush.set("cp_micro", ringCol, random(0.75, 1.15));
    // Alternate radial skin Papillae and concentric ring creases
    let strokeAng = random() < 0.6 ? a + random(-8, 8) : a + 90 + random(-10, 10);
    let len = random(3.5, 7.0);
    brush.line(px, py, px + cos(strokeAng) * len, py + sin(strokeAng) * len);
  }

  // Crisp dark charcoal eyelid rim & outer limbal ring
  brush.noStroke();
  brush.wash("#191416", 255);
  brush.circle(ex, ey, 34.5, 0.03);
  brush.noWash();

  // C. THE BEADY FIERY ORANGE IRIS (Radius = 32.5)
  // Base warm vermilion-orange wash
  brush.noStroke();
  brush.wash("#d9440d", 255);
  brush.circle(ex, ey, 31.5, 0.02);
  brush.noWash();

  // Radial iris stromal filaments:
  // Outer ruby-crimson -> mid blazing cadmium orange -> inner glowing amber-gold ruff
  let irisFibers = 340;
  for (let i = 0; i < irisFibers; i++) {
    let a = (i / irisFibers) * 360 + random(-1.2, 1.2);
    // Corneal caustic brightening on the lower-right side opposite the upper-left catchlight
    let caustic = exp(-pow(((a - 42 + 540) % 360 - 180) / 55, 2));
    // Upper eyelid shadow across the top of the iris (a around 240..310)
    let lidShadow = exp(-pow(((a - 275 + 540) % 360 - 180) / 48, 2));

    // 1. Outer ruby-vermilion rim (r = 24..32)
    let cOuter = mixHex("#6e1405", "#cf2f08", constrain(0.45 + caustic * 0.55 - lidShadow * 0.4, 0, 1));
    brush.set("cp_micro", cOuter, 0.95);
    brush.line(
      ex + cos(a) * 23.5,
      ey + sin(a) * 23.5,
      ex + cos(a + random(-3, 3)) * 32.0,
      ey + sin(a + random(-3, 3)) * 32.0
    );

    // 2. Mid fiery orange stroma (r = 17..26)
    let cMid = mixHex("#d6410a", "#ff7714", constrain(0.5 + caustic * 0.5 - lidShadow * 0.35 + random(-0.1, 0.1), 0, 1));
    brush.set("cp_burnish", cMid, 0.85);
    brush.line(
      ex + cos(a) * 17.0,
      ey + sin(a) * 17.0,
      ex + cos(a + random(-2, 2)) * 25.5,
      ey + sin(a + random(-2, 2)) * 25.5
    );

    // 3. Inner golden-amber pupillary ring (r = 14.5..19.5)
    if (i % 2 === 0) {
      let cInner = mixHex("#f27d16", "#ffc938", constrain(0.55 + caustic * 0.45 - lidShadow * 0.25, 0, 1));
      brush.set("cp_burnish", cInner, 0.8);
      brush.line(
        ex + cos(a) * 14.5,
        ey + sin(a) * 14.5,
        ex + cos(a) * 19.5,
        ey + sin(a) * 19.5
      );
    }
  }

  // Delicate dark circular vascular pigment rings inside the pigeon's orange iris
  brush.set("cp_micro", "#7a1806", 0.75);
  for (let a = 0; a < 360; a += 8) {
    let r = 27.5 + sin(a * 5) * 1.5;
    brush.line(
      ex + cos(a) * r,
      ey + sin(a) * r,
      ex + cos(a + 7) * r,
      ey + sin(a + 7) * r
    );
  }

  // Dark inner eyelid rim line for crispness
  brush.set("cp_micro", "#120e10", 1.3);
  for (let a = 0; a < 360; a += 5) {
    let r1 = 32.8;
    brush.line(
      ex + cos(a) * r1 * 1.03,
      ey + sin(a) * r1 * 0.98,
      ex + cos(a + 6) * r1 * 1.03,
      ey + sin(a + 6) * r1 * 0.98
    );
  }

  // D. JET-BLACK VELVET PUPIL (Center slightly forward at ex - 2, ey)
  let px = ex - 1.8;
  let py = ey;
  brush.noStroke();
  brush.wash("#09080c", 255);
  brush.circle(px, py, 14.8, 0.01);
  brush.noWash();

  // Dense pitch-black coloured pencil burnish inside the pupil
  brush.set("cp_burnish", "#0a090d", 1.2);
  for (let i = 0; i < 85; i++) {
    let a = random(0, 360);
    let r = random(0, 14.2);
    brush.line(px + cos(a) * r, py + sin(a) * r, px - cos(a) * r * 0.6, py - sin(a) * r * 0.6);
  }

  // E. GLOSSY CORNEAL SPECULAR CATCHLIGHT (Upper-Left Sky Reflection)
  // Soft icy-blue pre-glaze around catchlight
  brush.set("cp_burnish", "#dceef5", 0.95);
  for (let a = 198; a <= 258; a += 2.0) {
    for (let r = 11.5; r <= 27.5; r += 1.6) {
      let gx = ex + cos(a) * r;
      let gy = ey + sin(a) * r;
      brush.line(gx, gy, gx + cos(a + 90) * 3.5, gy + sin(a + 90) * 3.5);
    }
  }

  // Crisp pure white window catchlight bridging the pupil edge and upper-left iris
  brush.set("cp_burnish", "#ffffff", 1.35);
  for (let a = 204; a <= 252; a += 1.4) {
    for (let r = 13.0; r <= 25.5; r += 1.2) {
      // Subtle window-frame split in the reflection for hyperrealism
      if (abs(a - 228) < 2.2) continue;
      let gx = ex + cos(a) * r;
      let gy = ey + sin(a) * r;
      brush.line(gx, gy, gx + cos(a + 90) * 3.0, gy + sin(a + 90) * 3.0);
    }
  }

  // Secondary warm golden-white caustic glint along the lower-right iris rim
  brush.set("cp_burnish", "#ffebb3", 0.9);
  for (let a = 22; a <= 68; a += 3) {
    let r = 22.5 + sin(a * 4) * 1.2;
    brush.line(
      ex + cos(a) * r,
      ey + sin(a) * r,
      ex + cos(a + 5) * (r + 1.5),
      ey + sin(a + 5) * (r + 1.5)
    );
  }
}

// ---------------------------------------------------------------------------
// 7. FINAL LUMINOUS BURNISHING & SILHOUETTE BARB DETAILS
// ---------------------------------------------------------------------------

function drawFinalBurnishPass() {
  // A. Ultra-delicate stray feather barbules projecting along the left breast/throat contour
  // against the soft concrete grey background
  for (let y = 188; y <= 1200; y += 2.2) {
    let lx = getLeftPlumageX(y);
    let isNeckZone = y > 260 && y < 780;

    // Color matches the local pearly edge of the pigeon's silhouette
    let colEdge;
    if (y < 260) {
      colEdge = mixHex("#6e7580", "#aeb6c0", random(0.3, 0.9));
    } else if (isNeckZone) {
      let w = 0.5 + 0.5 * sin(y * 0.045);
      colEdge = mixHex("#d6ebe4", "#ebd4e0", w);
    } else {
      colEdge = mixHex("#8a8296", "#c4cbd4", random(0.2, 0.85));
    }

    brush.set("cp_micro", colEdge, random(0.65, 1.05));
    let ang = map(y, 188, 1200, 145, 112) + random(-8, 8);
    let len = random(6, 15);
    let startX = lx + random(-2, 4);
    brush.line(startX, y, startX + cos(ang) * len, y + sin(ang) * len);
  }

  // B. Concentrated mother-of-pearl burnish glazes across the high-light crests of the neck
  // Layers pure pearly seafoam, rose-opal, and moonstone white where light grazes the feathers
  let highlightZones = [
    { cx: 430, cy: 365, rx: 135, ry: 95, col: "#e4f7f0" }, // Upper neck seafoam-pearl crest
    { cx: 365, cy: 485, rx: 145, ry: 110, col: "#f5e3ec" }, // Mid-front neck rose-pearl crest
    { cx: 485, cy: 550, rx: 150, ry: 105, col: "#dff5ed" }, // Mid-dorsal seafoam-mint wave
    { cx: 350, cy: 640, rx: 140, ry: 110, col: "#e6dcf2" }, // Lower neck amethyst-pearl glow
    { cx: 880, cy: 670, rx: 180, ry: 140, col: "#e2e8f0" }  // Shoulder covert silvery-pearl sheen
  ];

  for (let z = 0; z < highlightZones.length; z++) {
    let hz = highlightZones[z];
    brush.set("cp_burnish", hz.col, 0.85);
    for (let i = 0; i < 160; i++) {
      let a = random(0, 360);
      let r = pow(random(0, 1), 0.75);
      let bx = hz.cx + cos(a) * r * hz.rx;
      let by = hz.cy + sin(a) * r * hz.ry;

      // Follow local barb angle
      let barbAng = z === 4 ? 48 + random(-12, 12) : 82 + (bx - 420) * -0.08 + random(-14, 14);
      let bLen = random(8, 18);
      brush.line(bx, by, bx + cos(barbAng) * bLen, by + sin(barbAng) * bLen);
    }
  }
}
